-- 国試の解説を、選択肢ごとに分けた形で入れ直す。何度流しても結果は同じ。
--
-- 先に scripts/sql/migrate_quiz_0009_choice_explanations.sql を流すこと
-- （choice_explanations 列がまだ無いとここで落ちる）。
--
-- 中身は同梱データ（backend/quiz/management/commands/data/kokushi_*.json）から
-- 取り込みと同じ変換（import_questions.build_explanation）を通して生成した。
-- scripts/build_choice_explanation_sql.py で作り直せる。
--
-- kokushi_explanations.sql の後継。あちらは explanation 列だけを更新し、
-- 文面も 9/4 時点のもの（否定形を読み違えた3問を含む）。こちらを流せば
-- 直った文面に揃う。
--
-- 連問116問は本番にまだ入っていないので当たらない（0行更新）。
-- import_questions 経由で解説ごと入る。

BEGIN;

UPDATE quiz_question AS q
SET explanation = v.explanation,
    choice_explanations = v.choice_explanations::jsonb
FROM (VALUES
    ('114-A-1', '正答は D「アナフィラキシー — アドレナリン静注」。

アナフィラキシーに対するアドレナリンは大腿前外側への筋注が標準で、静注ではない。筋注は血中濃度の立ち上がりが速く安全域も広い。静注は不整脈や心筋虚血を招くため、心停止例や筋注に反応しない難治性ショックに限り、希釈して監視下で行う例外的な投与法である。

出典：厚生労働省ホームページ 第114回医師国家試験 A001',
     '{"A": "蕁麻疹の第一選択は非鎮静性H1受容体拮抗薬の内服で、標準治療として正しい。", "B": "食物アレルギーの基本は原因食物の必要最小限の除去であり、正しい組合せである。", "C": "アトピー性皮膚炎の炎症を抑える中心は副腎皮質ステロイド外用薬で、正しい。", "E": "気管支喘息の急性増悪では短時間作用性β2刺激薬の吸入が第一選択で、正しい。"}'),
    ('114-A-2', '正答は D「胃食道逆流症 — 後鼻漏」。

後鼻漏は副鼻腔炎など上気道由来の咳（上気道咳症候群）の特徴であって、胃食道逆流症の特徴ではない。逆流による慢性咳嗽は胸やけや呑酸を伴い、食後や臥位・前屈で増悪するのが特徴である。

出典：厚生労働省ホームページ 第114回医師国家試験 A002',
     '{"A": "COPDによる咳嗽の背景には喫煙歴があり、正しい組合せである。", "B": "咳喘息は季節性や日内変動（夜間から早朝の増悪）を示し、正しい。", "C": "アトピー咳嗽は咽喉頭の瘙痒感（イガイガ感）を伴い、抗ヒスタミン薬が有効である。", "E": "副鼻腔気管支症候群は慢性副鼻腔炎に気道病変を合併し、膿性痰を伴う。正しい。"}'),
    ('114-A-4', '正答は B「汗腺の数が増加している。」。

原発性局所多汗症では汗腺の数も組織像も正常で、増加していない。交感神経を介した発汗刺激が過剰になっているだけであり、これが治療の標的になる。

出典：厚生労働省ホームページ 第114回医師国家試験 A004',
     '{"A": "掌蹠の発汗は精神的緊張で亢進する精神性発汗が主体で、正しい。", "C": "常に湿潤するため角層が浸軟し、白癬や点状角質融解症などを起こしやすい。正しい。", "D": "水道水イオントフォレーシスは掌蹠多汗症の標準的な治療法の一つである。", "E": "Minor法はヨードとデンプンの反応で発汗部位を可視化する検査で、正しい。"}'),
    ('114-A-5', '正答は B「味覚異常 — 亜鉛」。

亜鉛は味蕾の細胞の代謝回転に必要で、欠乏すると味覚異常をきたす。ほかに皮膚炎、脱毛、創傷治癒の遅延、小児では成長障害を伴う。

出典：厚生労働省ホームページ 第114回医師国家試験 A005',
     '{"A": "匙状爪（スプーンネイル）は鉄欠乏の徴候である。銅欠乏では貧血・好中球減少・脊髄症をきたす。", "C": "出血傾向をきたすのはビタミンK欠乏。ビタミンA欠乏では夜盲や眼球乾燥症を生じる。", "D": "ペラグラはナイアシン（ビタミンB3）欠乏で、皮膚炎・下痢・認知症を三徴とする。", "E": "骨軟化症はビタミンD欠乏による。ビタミンC欠乏で起こるのは壊血病である。"}'),
    ('114-A-6', '正答は C「カルシウム製剤」。

甲状腺全摘に伴って副甲状腺が摘出されたり血流障害を受けたりすると、術後に低カルシウム血症が生じる。テタニーは神経筋の興奮性亢進による症候で、直ちにグルコン酸カルシウムを静注して補正する。

出典：厚生労働省ホームページ 第114回医師国家試験 A006',
     '{"A": "甲状腺を全摘した後であり、抗甲状腺薬の適応はない。", "B": "テタニーはてんかん発作ではなく低カルシウム血症による神経筋興奮性の亢進であり、抗けいれん薬では改善しない。", "D": "ビスホスホネートは血清カルシウムをさらに低下させるため、低カルシウム血症では避ける。", "E": "活性型ビタミンD製剤は術後低カルシウム血症の維持療法として併用するが、作用発現が遅く急性期のテタニーには間に合わない。"}'),
    ('114-A-8', '正答は B「聴力は正常である。」。

選択（性）緘黙は、家庭など特定の場面では話せるのに学校など別の場面では話せなくなる不安症で、聴力・言語能力・知能はいずれも正常である。話せないのは能力の問題ではなく不安によるという理解が対応の前提になる。

出典：厚生労働省ホームページ 第114回医師国家試験 A008',
     '{"A": "発症の多くは5歳前後で、就学を機に気づかれることが多い。思春期に多いわけではない。", "C": "言語理解は保たれている。言語発達の障害が原因なら、話せる場面があることを説明できない。", "D": "器質的な脳疾患ではないため、脳波検査は診断に寄与しない。", "E": "発声機能そのものに問題はないので発声練習は的外れで、行動療法や環境調整、不安への介入が中心となる。"}'),
    ('114-A-9', '正答は E「収縮性心膜炎」。

収縮性心膜炎は心膜の線維化・石灰化により拡張が妨げられる疾患で、結核や心臓手術、放射線照射などが原因となる。閉塞性睡眠時無呼吸症候群との因果関係は知られていない。

出典：厚生労働省ホームページ 第114回医師国家試験 A009',
     '{"A": "夜間の間欠的低酸素と胸腔内圧の変動が心負荷となり、心不全のリスクを高める。", "B": "重症例では夜間から早朝の突然死のリスクが上昇することが知られている。", "C": "交感神経活動の亢進により高血圧、とくに治療抵抗性高血圧と強く関連する。", "D": "左房への負荷と自律神経の変動から心房細動のリスクが上昇する。"}'),
    ('114-A-10', '正答は B「三叉神経痛」。

典型的な三叉神経痛は、上小脳動脈などの血管が橋から出る三叉神経の根部（root entry zone）を圧迫して生じる。片側顔面痙攣が顔面神経で起こるのと同じ機序で、微小血管減圧術が根治的治療になる。

出典：厚生労働省ホームページ 第114回医師国家試験 A010',
     '{"A": "片頭痛の発症には三叉神経血管系の活性化が関わるが、血管が神経を圧迫して起こるわけではない。", "C": "本態性振戦は小脳-視床-皮質回路の機能的な異常によるもので、血管圧迫は関与しない。", "D": "Parkinson病は黒質のドパミン神経の変性による。", "E": "側頭葉てんかんの多くは海馬硬化などの内側側頭葉病変による。"}'),
    ('114-A-11', '正答は D「メトトレキサート」。

メトトレキサートは葉酸代謝を阻害し、神経管閉鎖障害や頭蓋顔面の形成異常など催奇形性をもつため妊娠中は禁忌である。挙児希望があれば妊娠前に中止し、少なくとも1月経周期をおいてから妊娠を計画する。

出典：厚生労働省ホームページ 第114回医師国家試験 A011',
     '{"A": "タクロリムスは胎盤移行が限られ、妊娠中も継続可能な免疫抑制薬として扱われる。", "B": "NSAIDは妊娠後期には胎児動脈管の早期閉鎖のため避けるが、妊娠前にあらかじめ中止する薬ではない。", "C": "TNF阻害薬は妊娠中期までの胎盤移行が少なく、必要に応じて継続できる。", "E": "サラゾスルファピリジンは妊娠中も比較的安全に使用でき、葉酸を併用する。"}'),
    ('114-A-12', '正答は A「年齢6歳以上」。

小児急性中耳炎が難治化・反復する最大の危険因子は2歳未満の低年齢である。乳幼児では耳管が短く太く水平に近いため、鼻咽腔からの感染が及びやすく換気も悪い。6歳以上ではむしろ治りやすくなる。

出典：厚生労働省ホームページ 第114回医師国家試験 A012',
     '{"B": "免疫能の低下は起炎菌の排除を妨げ、難治化の要因となる。", "C": "鼻副鼻腔炎の合併は耳管を介した感染源となり、難治化に関連する。", "D": "集団保育所への通所は耐性菌への曝露と反復感染の機会を増やす。", "E": "耳漏から薬剤耐性菌が検出されれば、通常の抗菌薬が効かず難治化する。"}'),
    ('114-A-21', '正答は E「第VIII因子活性の測定」。

高齢者に誘因なく広範な皮下出血が出現し、PTが正常でAPTTのみが延長し、血小板数も正常であることから、後天性血友病A（第VIII因子インヒビターの出現）を第一に考える。第VIII因子活性の測定とクロスミキシング試験、インヒビター定量で確定する。

出典：厚生労働省ホームページ 第114回医師国家試験 A021',
     '{"A": "貧血はあるが白血球分画も血小板数も正常で、造血器腫瘍を積極的に疑う所見に乏しい。APTT単独延長も説明できない。", "B": "血管炎による紫斑は触知可能で下腿優位のことが多い。本例は凝固検査の異常が明らかで、皮膚生検では診断に至らない。", "C": "Coombs試験は自己免疫性溶血性貧血の検査だが、網赤血球増加や間接ビリルビン上昇の所見はなく、出血傾向も説明できない。", "D": "抗血小板抗体は免疫性血小板減少症を疑うときの検査で、血小板32万と正常な本例には当たらない。"}'),
    ('114-A-22', '正答は E「プロゲステロン負荷試験」。

プロゲステロン負荷試験は無月経の患者でエストロゲン分泌と子宮内膜の反応性をみて第1度・第2度無月経を鑑別する検査である。本例は稀発月経ながら月経があり、不妊の原因検索には寄与しない。

出典：厚生労働省ホームページ 第114回医師国家試験 A022',
     '{"A": "子宮鏡は子宮内腔の癒着・ポリープ・粘膜下筋腫など着床を妨げる病変の評価に有用である。", "B": "経腟超音波は卵胞発育や多囊胞性卵巣の所見、子宮筋腫などの評価に必須である。", "C": "基礎体温の二相性から排卵の有無と黄体機能を推定でき、月経周期が不整な本例では特に有用である。", "D": "子宮卵管造影は卵管の疎通性を評価する検査で、不妊症の基本検査に含まれる。"}'),
    ('114-A-23', '正答は D「聴力の左右差」。

立ち上がった時に限って起こり意識消失を伴わない前失神発作で、起立性低血圧を強く示唆する。原因として心拍出量の制限（大動脈弁狭窄など）、貧血、自律神経障害、脱水を確認する。聴力の左右差は蝸牛症状を伴う末梢前庭疾患を疑うときの所見で、体位変換に限って生じる本例では優先度が最も低い。

出典：厚生労働省ホームページ 第114回医師国家試験 A023',
     '{"A": "大動脈弁狭窄など器質的心疾患による失神を除外するために心雑音の聴取は重要である。", "B": "臥位と立位での血圧測定は起立性低血圧を直接証明する検査で、最優先である。", "C": "頸部血管雑音は頸動脈狭窄を示唆し、脳灌流低下の要因となる。", "E": "眼瞼結膜の蒼白は貧血を示唆し、貧血は起立耐性を低下させる。"}'),
    ('114-A-24', '正答は E「黄色ブドウ球菌」。

熱傷創を有する患者に、発熱・低血圧・びまん性紅斑・消化器症状が急速に出現しており、黄色ブドウ球菌のTSST-1などの毒素によるトキシックショック症候群を考える。熱傷創は発赤や膿など明らかな感染徴候に乏しくても菌が定着していることがある。

出典：厚生労働省ホームページ 第114回医師国家試験 A024',
     '{"A": "大腸菌は腸管由来の敗血症を起こしうるが、熱傷創とびまん性紅斑という組合せは説明しにくい。", "B": "緑膿菌は熱傷創感染の代表的な起炎菌だが、緑色の滲出液やエクチマ壊疽が典型で、毒素性ショック様の紅斑は非典型である。", "C": "カンジダは広域抗菌薬の長期投与や中心静脈カテーテル留置例に多く、受傷1週でこの急激な経過をとることは考えにくい。", "D": "肺炎球菌感染は呼吸器症状が主体で、呼吸音に異常のない本例の経過に合わない。"}'),
    ('114-A-25', '正答は E「仕事に関する本人の考えを聞く。」。

症状は平日と職場に限られ、休日は熟睡でき趣味も以前どおり楽しめている。気分反応性が保たれており、うつ病エピソードの基準を満たさず、異動というストレス因に対する適応反応症（適応障害）が考えられる。初診ではまず職場で何が起きていて本人がどう受け止めているかを聴くのが適切である。

出典：厚生労働省ホームページ 第114回医師国家試験 A025',
     '{"A": "欠勤はなく職業機能は保たれている。評価の前に休職を勧めるのは早計である。", "B": "励ましは本人を追い詰めるおそれがあり、支持的精神療法の原則に反する。", "C": "適応反応症では抗うつ薬は第一選択とならず、まず環境調整と支持的介入を行う。", "D": "投影法の心理検査は初診時に必須ではなく、まず病歴の聴取が優先される。"}'),
    ('114-A-29', '正答は B「蛋白摂取量は45g/日とする。」。

顕性腎症からさらに進行した糖尿病性腎臓病で、蛋白制限が中心となる。0.6〜0.8 g/kg標準体重/日が目安で、標準体重約64 kgでは38〜51 g/日にあたり、45 g/日は妥当である。

出典：厚生労働省ホームページ 第114回医師国家試験 A029',
     '{"A": "血圧182/102 mmHgで腎症も進行しており、食塩は6 g/日未満に制限する。", "C": "蛋白を制限する分エネルギーは十分に確保しないと異化が亢進する。標準体重約64 kgの軽労作では1,600〜1,900 kcal/日が目安で、1,400 kcalでは不足する。", "D": "蛋白制限下でエネルギーを確保するには糖質を減らせない。糖質は総エネルギーの50〜60%とする。", "E": "脂質異常症も合併しており、コレステロールは200〜300 mg/日未満に抑える。1,000 mg/日は過剰である。"}'),
    ('114-A-32', '正答は D「乳汁漏出」。

乳汁漏出は高プロラクチン血症による症状で、ドパミン受容体を遮断する抗精神病薬やメトクロプラミドなどで起こる。NSAIDの副作用ではない。

出典：厚生労働省ホームページ 第114回医師国家試験 A032',
     '{"A": "腎でのプロスタグランジン産生が抑えられ、ナトリウムと水の貯留から浮腫を生じる。", "B": "COX-1阻害により血小板のトロンボキサンA2産生が抑えられ、出血傾向から鼻出血を生じうる。", "C": "ナトリウム貯留と腎血管拡張の抑制により血圧が上昇する。", "E": "上腹部痛はNSAID起因性の胃十二指腸潰瘍を示唆し、倍量を連日服用している本例で最も警戒すべき症状である。"}'),
    ('114-A-40', '正答は B「便のGram染色」。

東南アジアからの帰国後2日で発症した発熱を伴う下痢で、細菌性の旅行者下痢症を考える。便のGram染色は迅速で、Campylobacterのらせん状桿菌など起炎菌の推定に役立ち、培養と併せて診断を確定する。

出典：厚生労働省ホームページ 第114回医師国家試験 A040',
     '{"A": "腹膜刺激徴候はなく、造影CTは起炎菌の同定には寄与しない。", "C": "腹部超音波は腸管壁の肥厚を捉えることはあっても、原因微生物を確定できない。", "D": "抗酸菌染色は腸結核を疑うときの検査だが、腸結核は亜急性から慢性の経過をとり、2日の急性経過に合わない。", "E": "Clostridioides difficile感染症は先行する抗菌薬使用歴や入院歴を背景に起こるが、本例にはいずれもない。"}'),
    ('114-A-44', '正答は E「機能性ディスペプシア」。

早期飽満感と食後の心窩部痛が6か月続き、上部消化管内視鏡でも腹部超音波でも器質的疾患が除外されている。食後愁訴症候群と心窩部痛症候群の要素をもつ機能性ディスペプシアと考える。

出典：厚生労働省ホームページ 第114回医師国家試験 A044',
     '{"A": "慢性膵炎ではアミラーゼの変動や脂肪便、背部に放散する疼痛がみられるが、本例は膵酵素も正常である。", "B": "逆流性食道炎は胸やけが主症状で、内視鏡で粘膜傷害を認めることが多いが、本例の内視鏡は正常である。", "C": "過敏性腸症候群は排便に関連する腹痛と便通異常が診断に必要だが、本例に便通異常はない。", "D": "食道アカラシアはつかえ感と食物の逆流が主症状で、内視鏡でも食道の拡張や食物残渣を認めることが多い。"}'),
    ('114-A-51', '正答は B「酸素投与」。

閉鎖された倉庫内でガソリンエンジンを使用し、同じ場所にいた同僚も頭痛や悪心を訴えていることから一酸化炭素中毒を考える。カルボキシヘモグロビンはパルスオキシメータで酸素化ヘモグロビンと区別できないためSpO2は見かけ上正常となる。直ちに高濃度酸素を投与してCOの半減期を短縮する。

出典：厚生労働省ホームページ 第114回医師国家試験 A051',
     '{"A": "経口摂取による中毒ではなく、胃管挿入の適応はない。", "C": "低血糖を疑う病歴はない。血糖測定は行うにしても、まず行うべき処置ではない。", "D": "アナフィラキシーを示唆する皮疹・気道症状・曝露歴がない。", "E": "喘鳴など気道閉塞の所見はなく、β刺激薬の適応はない。"}'),
    ('114-A-58', '正答は D「Machado-Joseph病」。

父、父方祖父、叔父に同症状があり常染色体顕性遺伝の形式をとる。小脳性運動失調に錐体路徴候を伴い、眼瞼後退による「びっくり眼」を認めることから脊髄小脳失調症3型（Machado-Joseph病）を考える。CAGリピートの伸長による疾患である。

出典：厚生労働省ホームページ 第114回医師国家試験 A058',
     '{"A": "Parkinson病は静止時振戦・筋強剛・寡動が主体で、小脳性運動失調は伴わない。", "B": "多系統萎縮症は孤発性で、起立性低血圧や排尿障害など自律神経症状が目立つ。本例は明らかな家族歴があり自律神経障害もない。", "C": "Huntington病も常染色体顕性だが、舞踏運動と精神症状・認知機能低下が主体である。本例は不随意運動がなく認知機能も正常である。", "E": "ミトコンドリア脳筋症は母系遺伝を示す。父方に症状が連なる本例の家系図と合わない。"}'),
    ('114-A-61', '正答は E「非アルコール性脂肪性肝疾患」。

肥満（BMI約31）、耐糖能異常、高トリグリセリド血症、低HDLコレステロール血症とメタボリック症候群の要素が揃い、飲酒歴がなくウイルス性肝炎も自己抗体も陰性である。ALT優位の軽度トランスアミナーゼ上昇は非アルコール性脂肪性肝疾患に典型的である。

出典：厚生労働省ホームページ 第114回医師国家試験 A061',
     '{"A": "Wilson病は若年発症で、セルロプラスミン低値、Kayser-Fleischer輪、神経・精神症状を伴う。58歳発症で神経診察も正常な本例は非典型である。", "B": "Gilbert症候群は間接ビリルビン優位の軽度上昇のみでトランスアミナーゼは正常。本例は直接ビリルビン優位でAST・ALTも上昇している。", "C": "自己免疫性肝炎は中年女性に多いが、抗核抗体が陰性でIgG上昇の所見もない。", "D": "原発性胆汁性胆管炎は抗ミトコンドリア抗体が陽性となり胆道系酵素優位の上昇を示すが、本例は抗体陰性でALPも基準内である。"}'),
    ('114-A-64', '正答は B「クラミジア感染症は治癒した。」。

治療により症状が消失し、性器クラミジアDNA検査も陰性化しており、感染症としては治癒したと説明してよい。ただし治癒は再感染しないことを意味せず、パートナーの同時治療とコンドームの使用を併せて説明する必要がある。

出典：厚生労働省ホームページ 第114回医師国家試験 A064',
     '{"A": "クラミジア感染症の治癒後に避妊を要する医学的根拠はない。", "C": "骨盤内炎症性疾患による卵管の器質的障害は治癒しても元に戻らず、異所性妊娠のリスクは残る。低下したとは言えない。", "D": "クラミジアによる不妊は卵管性であって子宮性ではなく、また必ず不妊になるわけでもない。", "E": "クラミジアに対する感染防御免疫は成立せず、再感染しうる。"}'),
    ('114-B-1', '正答は B「「2型糖尿病の発症予防には肥満にならないことが重要です」」。

2型糖尿病の最大の修正可能な危険因子は肥満で、体重管理が発症予防の中心になる。市民向けの健康教育として妥当な内容である。

出典：厚生労働省ホームページ 第114回医師国家試験 B001',
     '{"A": "受動喫煙が肺癌のリスクを高めることは確立しており、誤った情報を伝えることになる。", "C": "飽和脂肪酸はLDLコレステロールを上昇させる。下げるのは不飽和脂肪酸である。", "D": "高血圧症患者に推奨される食塩摂取量は6g/日未満で、10gでは過剰である。", "E": "食物繊維との関連が示されているのは主に大腸癌である。食道癌の確立した危険因子は飲酒・喫煙・熱い飲食物である。"}'),
    ('114-B-2', '正答は D「急性喉頭蓋炎」。

急性喉頭蓋炎は声門上の腫脹で急速に気道が閉塞し、窒息死しうる。腫脹のため経口挿管が困難あるいは不可能なことがあり、輪状甲状靱帯切開を含む外科的気道確保を準備する。

出典：厚生労働省ホームページ 第114回医師国家試験 B002',
     '{"A": "肺水腫では気道自体は開通しており、酸素投与・非侵襲的陽圧換気・利尿薬で対応する。", "B": "緊張性気胸は胸腔穿刺による脱気が第一で、気道の問題ではない。", "C": "過換気症候群では気道閉塞はなく、まず安心させて呼吸を整える。", "E": "声帯ポリープは嗄声が主症状で、急性の気道閉塞をきたすことは稀である。"}'),
    ('114-B-3', '正答は C「265」。

血漿浸透圧の推定式は 2×Na + 血糖/18 + 尿素窒素/2.8。2×125 + 90/18 + 28/2.8 = 250 + 5 + 10 = 265 mOsm/kgH2O となる。低ナトリウム血症が浸透圧を規定していることが読み取れる。

出典：厚生労働省ホームページ 第114回医師国家試験 B003',
     '{"A": "計算値より20低く、Naの寄与を過小に見積もっている。", "B": "計算値より10低い。", "D": "Naが正常域(140程度)であれば得られる値で、本例の125に合わない。", "E": "正常血漿浸透圧の値であり、低ナトリウム血症を反映していない。"}'),
    ('114-B-4', '正答は B「肺癌」。

Lambert-Eaton筋無力症候群は、小細胞肺癌に伴う傍腫瘍性神経症候群として最も多く発症する。P/Q型電位依存性カルシウムチャネルに対する自己抗体により神経筋接合部からのアセチルコリン放出が減少する。

出典：厚生労働省ホームページ 第114回医師国家試験 B004',
     '{"A": "膵癌に伴う傍腫瘍症候群としてはTrousseau症候群(遊走性血栓性静脈炎)が知られる。", "C": "胸腺腫と合併するのは重症筋無力症であり、Lambert-Eaton症候群ではない。", "D": "直腸癌との合併は知られていない。", "E": "悪性リンパ腫でも傍腫瘍性神経症候群は起こりうるが、Lambert-Eaton症候群の合併頻度は高くない。"}'),
    ('114-B-5', '正答は D「児童相談所に通告する。」。

児童虐待の防止等に関する法律により、虐待を受けたと思われる児童を発見した者には通告義務がある。確証は不要で、疑いの段階で児童相談所または市町村に通告する。守秘義務違反にはあたらない。

出典：厚生労働省ホームページ 第114回医師国家試験 B005',
     '{"A": "学校への連絡は通告に代わるものではない。まず通告する。", "B": "通告先は児童相談所または市町村である。生命の危険が差し迫っていれば警察にも連絡するが、原則ではない。", "C": "虐待の事実の立証は医師の役割ではなく、児童相談所や司法の判断に委ねる。", "E": "親への確認は証拠の隠滅や児のさらなる危険を招くおそれがあり、通告前に行うべきでない。"}'),
    ('114-B-6', '正答は B「「鼻腔RSウイルス迅速検査を行います」」。

生後8か月で発熱・咳嗽・鼻汁に続いて喘鳴と陥没呼吸をきたし、SpO2が低下している。乳児の急性細気管支炎で、原因としてRSウイルスが最も多い。鼻腔からの迅速検査で診断でき、入院時の隔離方針にも直結する。

出典：厚生労働省ホームページ 第114回医師国家試験 B006',
     '{"A": "A群溶連菌性咽頭炎は3歳未満には稀で、喘鳴を主体とする本例の病像と合わない。", "C": "尿中肺炎球菌抗原は小児では鼻咽腔の保菌で偽陽性となりやすく、有用性が低い。", "D": "アデノウイルス感染では眼球結膜の充血や滲出性扁桃炎を伴うことが多いが、本例では認めない。", "E": "マイコプラズマ感染は学童期以降に多く、乳児の細気管支炎の原因としては考えにくい。"}'),
    ('114-B-7', '正答は C「右小脳半球」。

小脳は同側性に四肢の協調運動を支配する。右上肢の運動失調は右小脳半球の病変で生じる。

出典：厚生労働省ホームページ 第114回医師国家試験 B007',
     '{"A": "放線冠は皮質脊髄路の通り道で、障害されると対側(左)の運動麻痺をきたす。", "B": "中脳被蓋では上小脳脚がすでに交叉しており、病変により対側の失調を生じる。", "D": "左延髄外側の障害(Wallenberg症候群)では同側すなわち左の小脳性失調をきたす。", "E": "脊髄後索の障害は同側の深部感覚障害による感覚性失調で、左病変なら左に出る。"}'),
    ('114-B-8', '正答は A「医師法に定められている。」。

説明と同意について定めているのは医療法である(第1条の4第2項で、医療従事者は適切な説明を行い理解を得るよう努めなければならないとされる)。医師法ではない。

出典：厚生労働省ホームページ 第114回医師国家試験 B008',
     '{"B": "患者が自らの価値観に基づいて治療を選べるようにすることが目的で、正しい。", "C": "提案する治療だけでなく代替となる選択肢や何もしない場合の見通しも示す必要がある。", "D": "一度同意しても患者はいつでも撤回でき、それによって不利益を受けない。", "E": "判断に足る情報が医療従事者側から十分に提供されていることが前提となる。"}'),
    ('114-B-9', '正答は E「大胸筋前面での可動性低下」。

腫瘤が大胸筋の前面で動かなくなっているのは、癌が乳腺を越えて胸壁側へ浸潤・固定していることを意味し、乳癌を強く示唆する。

出典：厚生労働省ホームページ 第114回医師国家試験 B009',
     '{"A": "疼痛を伴う乳房腫瘤は乳腺症や乳腺炎など良性のことが多く、乳癌はむしろ無痛性が典型である。", "B": "乳頭部の熱感は急性乳腺炎で目立つ。炎症性乳癌もあるが頻度は低い。", "C": "境界明瞭で表面平滑な可動性腫瘤は線維腺腫など良性を示唆する。乳癌は表面不整で硬い。", "D": "乳汁様・白色の分泌物は生理的あるいは高プロラクチン血症による。乳癌を示唆するのは血性分泌である。"}'),
    ('114-B-10', '正答は E「基線細変動消失」。

基線細変動の消失は、胎児の自律神経系が低酸素やアシドーシスで抑制されていることを示し、胎児機能不全のなかで最も重篤な所見である。

出典：厚生労働省ホームページ 第114回医師国家試験 B010',
     '{"A": "一過性頻脈は胎児が健常であることを示す所見で、懸念すべきものではない。", "B": "早発一過性徐脈は児頭圧迫による生理的な反応で、予後に影響しない。", "C": "変動一過性徐脈は臍帯圧迫によるもので、軽度・散発性なら経過観察でよい。", "D": "基線細変動の増加は急性の低酸素や臍帯圧迫で生じうるが、消失に比べれば重篤度は低く、最も懸念される所見ではない。"}'),
    ('114-B-14', '正答は E「5」。

受療行動とは、患者がいつ・どこで・なぜ医療を受けようとしたかという行動そのものを指す。「評判が良く家から近いので来た」という発言は、この医療機関を選んだ理由であり受療行動の情報である。

出典：厚生労働省ホームページ 第114回医師国家試験 B014',
     '{"A": "「左の膝が痛い」は主訴である。", "B": "「階段で膝が痛くなる」は症状の増悪因子で、現病歴にあたる。", "C": "「昨年末くらいから」は発症時期と経過で、現病歴にあたる。", "D": "「歩けなくなったら周りに迷惑をかけるのでは」は患者の解釈モデル・懸念であって、受療行動そのものではない。"}'),
    ('114-B-16', '正答は D「運動習慣」。

運動習慣は慢性腎臓病の危険因子ではなく、肥満や高血圧の是正を通じてむしろ発症を抑える方向に働く。

出典：厚生労働省ホームページ 第114回医師国家試験 B016',
     '{"A": "加齢に伴い糸球体濾過量は生理的に低下し、CKDの主要な危険因子である。", "B": "喫煙は腎の細動脈硬化と蛋白尿を促進する。", "C": "糖尿病は糖尿病性腎臓病を通じて透析導入原因の第1位である。", "E": "高血圧は腎硬化症の原因であり、透析導入原因の上位を占める。"}'),
    ('114-B-17', '正答は E「臍帯静脈の血液は胎児側に向かって流れる。」。

臍帯静脈は胎盤で酸素化された血液を胎児へ運ぶ。臍帯のなかで静脈は1本、動脈が2本である。

出典：厚生労働省ホームページ 第114回医師国家試験 B017',
     '{"A": "羊水はpH7.0〜7.5の弱アルカリ性で、破水の診断にBTB試験紙の変色を利用するのはこのためである。", "B": "臍帯動脈は通常2本ある。1本しかない単一臍帯動脈では他の奇形の合併に注意する。", "C": "臍帯の表面を覆うのは羊膜である。", "D": "Wharton膠質は臍帯血管を保護する間質のゼリー状組織で、羊膜そのものではない。"}'),
    ('114-B-18', '正答は B「「症状の出現は突然であった」」。

脳血管障害の本質は血流の突然の途絶であり、症状が突然出現したという病歴が最も脳梗塞を示唆する。

出典：厚生労働省ホームページ 第114回医師国家試験 B018',
     '{"A": "同様の症状の反復は片頭痛やてんかん、あるいは一過性脳虚血発作でもみられ、脳梗塞に特異的ではない。", "C": "症状が変動しないことは脳梗塞と矛盾しないが、発症様式ほど診断的価値は高くない。", "D": "頭痛を伴わないことは脳出血やくも膜下出血を相対的に否定するにとどまる。", "E": "発熱がないことは感染症の除外にはなるが、脳梗塞を積極的に示唆しない。"}'),
    ('114-B-19', '正答は A「黄疸」。

溶血で放出されたヘモグロビンが処理されて間接ビリルビンが増加し、黄疸をきたす。ハプトグロビン低下、LD上昇、網赤血球増加を伴う。

出典：厚生労働省ホームページ 第114回医師国家試験 B019',
     '{"B": "貧血では組織への酸素供給を保つため代償性に頻脈となる。", "C": "匙状爪(スプーンネイル)は鉄欠乏性貧血の徴候である。", "D": "眼球突出はBasedow病の所見で、溶血とは関係しない。", "E": "貧血で聴取されるのは血流量増加による収縮期駆出性雑音である。"}'),
    ('114-B-21', '正答は B「「自分の考えていることが周りの人に伝わってしまいます」」。

自分の考えが他人に伝わってしまうという体験は考想伝播で、自我障害の一つである。Schneiderの一級症状に含まれ、統合失調症を強く示唆する。

出典：厚生労働省ホームページ 第114回医師国家試験 B021',
     '{"A": "希死念慮はうつ病をはじめ多くの精神疾患でみられ、統合失調症に特異的ではない。", "C": "現実感が失われる訴えは離人感・現実感消失症で、健常者でも疲労時に生じうる。", "D": "不合理と分かっていながらやめられない手洗いは強迫症の強迫行為である。", "E": "検査で異常がないのに重篤な病気だと確信するのは心気症(病気不安症)の訴えである。"}'),
    ('114-B-22', '正答は A「エックス線写真を撮影して確認する。」。

胃管が気管に誤挿入されていないことを確実に示せるのはエックス線写真による確認である。誤挿入に気づかず栄養剤を注入すると致命的になる。

出典：厚生労働省ホームページ 第114回医師国家試験 B022',
     '{"B": "口腔内でたわんでいないことは、先端が胃にあることの保証にならない。", "C": "気管に入っていても気道分泌物が引けることがあり、確実ではない。", "D": "挿入長は目安にすぎず、先端の位置を保証しない。", "E": "気泡音の聴取は気管や食道への誤挿入でも聴こえることがあり、確認法として推奨されない。"}'),
    ('114-B-23', '正答は A「動眼神経麻痺」。

瞳孔括約筋を支配する副交感神経線維は動眼神経の表層を走る。動眼神経麻痺では散瞳に加えて眼瞼下垂と外眼筋麻痺を伴う。

出典：厚生労働省ホームページ 第114回医師国家試験 B023',
     '{"B": "有機リン中毒はコリンエステラーゼ阻害によりムスカリン作用が過剰となり、著明な縮瞳をきたす。", "C": "Horner症候群は交感神経の障害で、縮瞳・眼瞼下垂・患側顔面の発汗低下を示す。", "D": "オピオイドは特徴的な縮瞳(pinpoint pupil)をきたす。", "E": "Wallenberg症候群では同側のHorner症候群を伴い、縮瞳となる。"}'),
    ('114-B-25', '正答は A「嗅覚障害」。

嗅覚は姿勢の制御に関与しないため、転倒の危険因子とはならない。転倒予防では下肢筋力・視覚・体性感覚・前庭機能というバランスを支える要素を評価する。

出典：厚生労働省ホームページ 第114回医師国家試験 B025',
     '{"B": "下肢筋力の低下は立ち直り反応を弱め、転倒の主要な危険因子である。", "C": "視覚は姿勢制御の重要な入力で、白内障などによる視力低下は転倒を増やす。", "D": "深部知覚の低下は足底からの位置情報を失わせ、暗所での転倒を招く。", "E": "前庭機能障害はめまい・平衡障害を通じて直接転倒につながる。"}'),
    ('114-B-26', '正答は A「仰臥位にする。」。

創部を見たことを契機に顔面蒼白と冷汗を伴う気分不快が生じており、血管迷走神経反射(神経調節性失神の前駆症状)である。直ちに仰臥位とし、必要なら下肢を挙上して脳血流を確保する。

出典：厚生労働省ホームページ 第114回医師国家試験 B026',
     '{"B": "意識があり脈も保たれており、AEDの適応はない。", "C": "皮疹や気道症状、曝露歴がなくアナフィラキシーではない。", "D": "過換気の所見はなく、深呼吸の指導はかえって症状を悪化させうる。", "E": "すでに止血は確認されており、再圧迫は不要である。"}'),
    ('114-B-31', '正答は D「深部静脈血栓症」。

ネフローゼ症候群では、アンチトロンビンなどの凝固制御因子が尿中に失われる一方で肝臓での凝固因子産生が亢進し、血液濃縮も加わって血栓症を起こしやすい。本例もフィブリノゲンとDダイマーが上昇し、Hb18.1g/dLと血液濃縮を示している。

出典：厚生労働省ホームページ 第114回医師国家試験 B031',
     '{"A": "左室肥大は慢性的な圧負荷の結果生じるもので、血圧92/56mmHgの本例で警戒すべき合併症ではない。", "B": "食道静脈瘤は門脈圧亢進症による。低アルブミン血症は共通するが、本例に肝疾患を示す所見はない。", "C": "視神経乳頭浮腫は頭蓋内圧亢進の所見で、ネフローゼ症候群の合併症ではない。", "E": "ネフローゼ症候群では甲状腺ホルモン結合蛋白が尿中に失われるため、機能はむしろ低下傾向を示す。"}'),
    ('114-B-33', '正答は B「ビリルビン尿」。

急性下肢動脈閉塞に対する再灌流では、虚血で壊死した筋から細胞内成分が全身へ流入する。高カリウム血症、乳酸アシドーシス、CK上昇、ミオグロビン尿による赤褐色尿、そしてコンパートメント症候群による浮腫が問題となる。ビリルビン尿は肝胆道疾患による所見で、この病態では生じない。

出典：厚生労働省ホームページ 第114回医師国家試験 B033',
     '{"A": "再灌流後の浮腫やコンパートメント症候群は典型的な合併症である。", "C": "壊死筋から細胞内カリウムが放出され、致死的不整脈の原因となる。", "D": "虚血組織に貯留した乳酸が再灌流により全身循環へ流入する。", "E": "横紋筋融解によりクレアチンキナーゼが著明に上昇する。"}'),
    ('114-B-34', '正答は E「脳動脈瘤破裂」。

突然の激しい頭痛に片側の動眼神経麻痺(眼瞼下垂・散瞳・対光反射消失)を伴っており、内頸動脈-後交通動脈分岐部の脳動脈瘤破裂によるくも膜下出血を第一に考える。動脈瘤が直上を走る動眼神経を圧迫することで生じる。

出典：厚生労働省ホームページ 第114回医師国家試験 B034',
     '{"A": "髄膜炎は発熱を伴い数時間から数日かけて進行することが多く、突発する激しい頭痛と片側動眼神経麻痺の組合せは説明できない。", "B": "脳梗塞では突然の激しい頭痛は典型的でなく、片麻痺を伴わない点も合わない。", "C": "片頭痛は反復する拍動性頭痛で、瞳孔不同と対光反射消失を伴うことはない。", "D": "緊張型頭痛は締めつけられるような持続性の頭痛で、突発せず神経学的異常も伴わない。"}'),
    ('114-B-35', '正答は E「死亡確認し、死亡診断書を作成する。」。

在宅で看取る方針が本人・家族で共有され、診療を継続してきた患者が、その傷病の経過として死亡している。死後に診察して死因が診療中の傷病であると判断できるため、死亡確認のうえ死亡診断書を作成する。身体所見に不審な点がなく、異状死としての警察への届出も要さない。

出典：厚生労働省ホームページ 第114回医師国家試験 B035',
     '{"A": "蘇生を望まない在宅看取りであり、救急要請は本人と家族の意向に反する。", "B": "医師法第21条の届出は異状を認めた場合の規定である。診療中の傷病による死亡で不審な点もなく、該当しない。", "C": "心肺蘇生は本人・家族が選択しなかった医療であり、行ってはならない。", "D": "病院へ搬送しても得られるものはなく、看取りの場を本人の望んだ自宅から移すことになる。"}'),
    ('114-B-37', '正答は D「脊髄後索」。

胃全摘後10年で内因子が失われ、ビタミンB12欠乏による亜急性連合性脊髄変性症をきたしている。閉眼で増強する体幹動揺(Romberg徴候陽性)は深部感覚の障害を示し、後索が主座である。側索も侵されるため膝蓋腱反射は亢進し、末梢神経障害を合併してアキレス腱反射は低下するという一見矛盾した所見をとる。

出典：厚生労働省ホームページ 第114回医師国家試験 B037',
     '{"A": "後頭葉の障害では視野障害が主体で、深部感覚障害やしびれは説明できない。", "B": "大脳基底核の障害では寡動・筋強剛・不随意運動が前面に出る。", "C": "小脳性の失調では開眼でも動揺があり閉眼で著明に増強することはなく、眼振を伴うことが多い。本例は眼球運動が正常で眼振もない。", "E": "神経筋接合部の障害は易疲労性の筋力低下が主体で、感覚障害や腱反射の変化は伴わない。"}'),
    ('114-B-39', '正答は B「直ちに救急搬送するように指示する。」。

意識変容(JCS II-10)、呼吸数30/分、収縮期血圧78mmHgとqSOFAの3項目すべてを満たし、敗血症性ショックの状態にある。誤嚥性肺炎が疑われ、輸液と抗菌薬、循環管理を要するため直ちに救急搬送する。

出典：厚生労働省ホームページ 第114回医師国家試験 B039',
     '{"A": "解熱しても循環不全は改善せず、NSAIDは腎血流をさらに減らすため有害である。", "C": "数時間の遅れが予後を左右する病態であり、外来終了を待つ余裕はない。", "D": "経口摂取で補える脱水の程度ではなく、静脈路の確保が必要である。", "E": "翌日まで待てば死亡しうる。"}'),
    ('114-B-40', '正答は B「片肺挿管」。

成人男性の気管チューブの適正な深さは門歯で21〜23cm程度で、28cmは深すぎる。右主気管支に入って左肺が換気されず、左の呼吸音消失・左胸郭挙上不良・低酸素血症をきたしている。チューブを引き抜いて左右の呼吸音を再確認する。

出典：厚生労働省ホームページ 第114回医師国家試験 B040',
     '{"A": "気胸であれば患側の打診で鼓音となるが、本例は打診で左右差がない。", "C": "食道挿管ではカプノグラフに持続する波形は出ない。本例は波形が出ており否定される。", "D": "気管支けいれんは両側性で、呼気の延長と喘鳴を伴う。片側の呼吸音消失は説明できない。", "E": "チューブ閉塞では換気自体が困難となり、片側だけ換気されるという所見にはならない。"}'),
    ('114-B-43', '正答は B「血糖測定」。

意識障害の患者では、原因が何であれ最初に血糖を測る。低血糖は数分で判断でき、ブドウ糖投与で速やかに戻せる一方、見逃して時間が経つと不可逆的な脳障害を残す。本例は2型糖尿病で投薬を受けており、低血糖の可能性を真っ先に否定する必要がある。

出典：厚生労働省ホームページ 第114回医師国家試験 B043',
     '{"A": "脳波はてんかん重積などの評価に有用だが、その場で治療方針を変える情報は得られず、緊急度が低い。", "C": "腰椎穿刺は髄膜炎を疑えば必要になるが、ショック状態で先に行う検査ではない。", "D": "胸部単純CTは意識障害の原因検索としての優先度が低い。", "E": "腹部超音波検査も同様で、この時点で意識障害の原因に迫れる検査ではない。"}'),
    ('114-B-44', '正答は D「生理食塩液」。

高温のビニールハウス内で倒れており、体温39.0°C、意識障害を伴う熱中症（III度）である。Na 166mEq/L、Ht 60%、総蛋白9.0g/dL、アルブミン5.2g/dLはいずれも血液が濃縮されていることを示し、血圧84/46mmHgと循環血液量減少性ショックに陥っている。まず生理食塩液で血管内容量を回復させ、並行して体表冷却を行う。

出典：厚生労働省ホームページ 第114回医師国家試験 B044',
     '{"A": "CRP 0.2mg/dLと炎症反応に乏しく、感染症を示す所見がない。", "B": "昇圧薬は輸液で血管内容量を戻しても血圧が保てないときに考えるもので、脱水が明らかな段階で先に使う薬ではない。", "C": "熱中症の高体温は視床下部の設定温度が上がったものではないため、解熱薬は効かない。冷却が必要である。", "E": "副腎不全を示す所見はなく（Naは高値、Kは4.8mEq/Lと正常）、ステロイドの適応がない。"}'),
    ('114-B-45', '正答は A「標準予防策」。

排尿痛に続く悪寒戦慄と発熱、左肋骨脊柱角の叩打痛、膿尿があり急性腎盂腎炎である。人から人へ空気・飛沫・接触で伝播する病態ではないので、追加の予防策は要らず、すべての患者に対して常に行う標準予防策で足りる。

出典：厚生労働省ホームページ 第114回医師国家試験 B045',
     '{"B": "空気感染予防策は結核・麻疹・水痘のように微小な飛沫核で伝播する感染症に用いる。", "C": "接触感染予防策は多剤耐性菌やクロストリジオイデス・ディフィシルなどで追加する。", "D": "飛沫感染予防策はインフルエンザや流行性耳下腺炎などで追加する。", "E": "使用済みのディスポーザブル物品は通常の感染性廃棄物として処理すればよく、個別に焼却を指示するものではない。"}'),
    ('114-B-46', '正答は B「血液」。

悪寒戦慄を伴う発熱は菌血症を強く示唆する。腎盂腎炎では起因菌が血流に入っていることが少なくないため、尿培養と同時に血液培養を2セット採取してから抗菌薬を開始する。起因菌と感受性が分かれば、狭域の薬へ切り替えられる。

出典：厚生労働省ホームページ 第114回医師国家試験 B046',
     '{"A": "咽頭に異常を認めず、咽頭粘液を培養する根拠がない。", "C": "意識は清明で髄膜刺激症状もなく、脳脊髄液の採取は適応がない。", "D": "鼻腔ぬぐい液はMRSAの保菌調査に用いるもので、この発熱の起因菌検索にはならない。", "E": "下痢や腹痛がなく、便培養の適応がない。"}'),
    ('114-B-47', '正答は D「甲状腺」。

大量の飲食後に生じた近位筋優位の弛緩性麻痺で、K 2.4mEq/Lの低カリウム血症を伴う。3か月前からの動悸、頻脈、発汗、微熱もあり、甲状腺中毒性周期性四肢麻痺と考える。甲状腺ホルモン過剰がNa-K ATPaseを亢進させ、糖質の負荷でカリウムが細胞内へ移動して麻痺が起こる。

出典：厚生労働省ホームページ 第114回医師国家試験 B047',
     '{"A": "胸腺は重症筋無力症で問題になるが、それでは低カリウム血症も腱反射の低下も説明できない。", "B": "膵臓のインスリノーマなら低血糖をきたすが、血糖は85mg/dLと保たれている。", "C": "原発性アルドステロン症でも低カリウム性の麻痺は起こるが、高血圧を伴うのが普通で、本例は96/44mmHgと低い。", "E": "副甲状腺の異常はカルシウム代謝の問題であり、低カリウム血症による麻痺は説明できない。"}'),
    ('114-B-48', '正答は C「考えられる病態」。

SOAPのAはAssessment、すなわち集めた情報から医師が何を考えたかを書く欄である。本例なら「低カリウム血症による周期性四肢麻痺、甲状腺機能亢進症を疑う」といった病態の評価がここに入る。

出典：厚生労働省ホームページ 第114回医師国家試験 B048',
     '{"A": "起立困難は患者本人の訴えなのでS（Subjective）に書く。", "B": "意識レベルは診察して得た所見なのでO（Objective）に書く。", "D": "行うべき検査の計画はP（Plan）に書く。", "E": "徒手筋力テストの結果も診察所見なのでOに書く。"}'),
    ('114-C-1', '正答は C「構想区域は都道府県単位である。」。

地域医療構想の構想区域は、原則として二次医療圏を単位とする。都道府県単位ではない。

出典：厚生労働省ホームページ 第114回医師国家試験 C001',
     '{"A": "団塊の世代が75歳以上となる2025年の医療需要を推計するのが出発点である。", "B": "医療計画の一部として都道府県が策定する。", "D": "高度急性期・急性期・回復期・慢性期の機能別に必要病床数を推計する。", "E": "地域医療構想調整会議には医療関係者のほか医療保険者も参加する。"}'),
    ('114-C-2', '正答は E「保険療養費は被災労働者の自己負担はない。」。

労働者災害補償保険の療養補償給付は現物給付(療養の給付)として全額が支給され、被災労働者の自己負担はない。健康保険と異なり一部負担金が生じない点が重要である。

出典：厚生労働省ホームページ 第114回医師国家試験 C002',
     '{"A": "平成期の改正で通勤災害も給付対象に含まれている。", "B": "保険者は国(政府)であり、市町村ではない。", "C": "業務上外の認定は労働基準監督署長が行う。", "D": "労災保険料は全額を事業主が負担し、労働者の負担はない。"}'),
    ('114-C-3', '正答は C「死戦期呼吸を認めたら蘇生行為を開始する。」。

死戦期呼吸(あえぎ呼吸)は心停止直後にみられる異常呼吸で、正常な呼吸ではない。これを認めたら心停止と判断して直ちに胸骨圧迫を開始する。

出典：厚生労働省ホームページ 第114回医師国家試験 C003',
     '{"A": "胸骨圧迫の深さは胸の厚さの約1/3で、乳児では約4cmが目安である。", "B": "胸骨圧迫の速さは年齢によらず100〜120回/分である。", "D": "医療者2人で行う小児・乳児の蘇生では胸骨圧迫と人工呼吸の比は15:2とする。30:2は1人法または成人の場合である。", "E": "乳児では上腕動脈で脈を確認する。大腿動脈は小児で用いる。"}'),
    ('114-C-4', '正答は E「現在の気持ちについて話題にする。」。

「死にたい」という訴えの背後には、痛み、孤独、役割の喪失、家族への負担感など具体的な苦痛が隠れている。まず訴えを否定せずに受け止め、いま何を感じているかを尋ねることが出発点になる。

出典：厚生労働省ホームページ 第114回医師国家試験 C004',
     '{"A": "励ましは「その苦しみは受け止めてもらえない」というメッセージになり、患者を孤立させる。", "B": "訴えの背景を確かめずに退院を進めるのは、問題からの回避である。", "C": "療養場所の調整は必要になりうるが、気持ちを聴く前に持ち出す話ではない。", "D": "死の話題を避けることは、患者が最も話したいことを封じることになる。"}'),
    ('114-C-5', '正答は C「国民健康・栄養調査」。

国民健康・栄養調査は、栄養摂取状況・身体状況・生活習慣を毎年把握する調査で、健康日本21をはじめとする一次予防(健康増進・発症予防)施策の基礎資料となる。

出典：厚生労働省ホームページ 第114回医師国家試験 C005',
     '{"A": "患者調査は医療機関を受診した患者の傷病状況を調べるもので、二次予防以降の資料である。", "B": "人口動態調査は出生・死亡・婚姻などを扱い、健康増進施策の直接の基礎資料ではない。", "D": "医師・歯科医師・薬剤師調査は医療従事者の分布を把握する調査である。", "E": "全国在宅障害児・者等実態調査は障害福祉施策のための調査である。"}'),
    ('114-C-7', '正答は E「医療ソーシャルワーカー」。

医療ソーシャルワーカーは保健医療機関で相談援助を担う職種の呼称であって、資格の名称ではない。相当する国家資格は社会福祉士である。

出典：厚生労働省ホームページ 第114回医師国家試験 C007',
     '{"A": "介護福祉士は社会福祉士及び介護福祉士法に基づく国家資格である。", "B": "言語聴覚士は言語聴覚士法に基づく国家資格である。", "C": "理学療法士は理学療法士及び作業療法士法に基づく国家資格である。", "D": "臨床工学技士は臨床工学技士法に基づく国家資格である。"}'),
    ('114-C-8', '正答は D「浮腫性硬化症 — 糖尿病」。

浮腫性硬化症(scleredema)は項部から背部にかけて皮膚が板状に硬くなる疾患で、コントロール不良の2型糖尿病に合併する型が知られる。

出典：厚生労働省ホームページ 第114回医師国家試験 C008',
     '{"A": "Sweet病(急性熱性好中球性皮膚症)は骨髄異形成症候群や白血病などの血液疾患に伴うことがある。", "B": "環状肉芽腫は糖尿病との関連が指摘される疾患で、甲状腺機能亢進症ではない。", "C": "壊疽性膿皮症は潰瘍性大腸炎などの炎症性腸疾患や関節リウマチに伴う。", "E": "脛骨前粘液水腫はBasedow病に特徴的で、潰瘍性大腸炎ではない。"}'),
    ('114-C-9', '正答は C「市役所入口の自動ドア」。

ユニバーサルデザインは、障害の有無や年齢にかかわらず初めから誰もが使える設計を指す。自動ドアは車椅子利用者にも荷物を持った人にも子どもにも等しく有用で、特定の人向けの設備ではない点が該当する。

出典：厚生労働省ホームページ 第114回医師国家試験 C009',
     '{"A": "授乳室は授乳する人のための専用設備で、対象を限定している。", "B": "歩道橋は階段があり、車椅子利用者や高齢者をむしろ排除する。", "D": "オストメイト対応トイレは人工肛門・人工膀胱保有者のための設備である。", "E": "点字ブロックは視覚障害者のための設備で、バリアフリーの発想にあたる。"}'),
    ('114-C-10', '正答は D「自己複製能」。

造血幹細胞の本質的な性質は、自分と同じ細胞を作り出す自己複製能と、すべての血球系統へ分化できる多分化能である。この2つがあるため生涯にわたり血球を供給し続けられる。

出典：厚生労働省ホームページ 第114回医師国家試験 C010',
     '{"A": "止血に働くのは血小板である。", "B": "貪食を担うのは好中球やマクロファージなど分化した細胞である。", "C": "酸素運搬は成熟赤血球のヘモグロビンが担う。", "E": "血栓の溶解はプラスミンによる線溶系の働きである。"}'),
    ('114-C-12', '正答は A「食中毒患者を診断したとき保健所長に届け出る。」。

食品衛生法により、食中毒患者を診断した医師は直ちに最寄りの保健所長に届け出なければならない。集団発生の探知と拡大防止の起点になる。

出典：厚生労働省ホームページ 第114回医師国家試験 C012',
     '{"B": "サルモネラ食中毒は発熱・腹痛・下痢を典型とし、発熱はむしろ特徴的である。", "C": "黄色ブドウ球菌の産生するエンテロトキシンは耐熱性で、加熱しても失活しない。予防は菌を増やさないこと(手指衛生と低温保存)である。", "D": "カンピロバクターの潜伏期は2〜5日で、細菌性食中毒のなかではやや長いがそれでも週単位ではない。", "E": "近年の食中毒患者数はノロウイルスとカンピロバクターが上位を占め、腸炎ビブリオは減少している。"}'),
    ('114-C-13', '正答は A「「一定時刻に起床し日光を浴びましょう」」。

睡眠衛生の基本は、起床時刻を一定にして朝の光を浴び、体内時計を毎日リセットすることである。入眠時刻は結果としてついてくる。

出典：厚生労働省ホームページ 第114回医師国家試験 C013',
     '{"B": "眠くないうちから床に就くと、床のなかで眠れない時間が延びて入眠困難がかえって悪化する。", "C": "アルコールは入眠を早めるが睡眠を浅くし中途覚醒を増やす。耐性がついて量が増える危険もある。", "D": "臥床時間を延ばすと睡眠効率が下がり、不眠が固定しやすい。", "E": "眠れないまま床にとどまると「床＝眠れない場所」という条件づけができる。いったん床を離れ、眠気が来てから戻る(刺激制御法)。"}'),
    ('114-C-15', '正答は E「らせん状視野 — 心因性視力障害」。

らせん状視野は、視野計測を繰り返すうちに測定値がらせん状に狭くなっていくもので、解剖学的な視路の障害では説明できない。管状視野とともに心因性視力障害・視野異常に特徴的な所見である。

出典：厚生労働省ホームページ 第114回医師国家試験 C015',
     '{"A": "視神経炎で典型的なのは中心暗点である。管状視野は網膜色素変性症の末期や緑内障末期、心因性でみられる。", "B": "同名半盲は視交叉より後方の視路の障害による。黄斑疾患では中心暗点となる。", "C": "盲中心暗点は視神経炎や中毒性視神経症でみられる。緑内障ではBjerrum暗点や鼻側階段が特徴的である。", "D": "Bjerrum暗点は緑内障の典型的な視野欠損である。"}'),
    ('114-C-17', '正答は D「ロコモティブシンドローム」。

運動器の障害により移動機能が低下した状態をロコモティブシンドローム(運動器症候群)と呼ぶ。日本整形外科学会が提唱した概念で、要介護に至る前段階として予防的介入の対象になる。

出典：厚生労働省ホームページ 第114回医師国家試験 C017',
     '{"A": "クラッシュシンドロームは長時間の圧挫後、解放により生じる横紋筋融解と高カリウム血症・急性腎障害である。", "B": "ダンピングシンドロームは胃切除後に食物が急速に小腸へ流入して起こる症候群である。", "C": "メタボリックシンドロームは内臓脂肪蓄積を基盤とする代謝異常の集積で、運動器の概念ではない。", "E": "コンパートメントシンドロームは筋区画内圧の上昇による循環障害で、急性の外科的緊急症である。"}'),
    ('114-C-18', '正答は D「腹部ダイナミックCT」。

腹部ダイナミックCTは単純相に加えて動脈相・門脈相・平衡相と複数回撮影するため、1回の検査当たりの被ばく線量が最も大きくなる。

出典：厚生労働省ホームページ 第114回医師国家試験 C018',
     '{"A": "FDG-PETの被ばくは投与放射能に依存し、PET単独では数mSv程度でダイナミックCTには及ばない。", "B": "頭部単純CTは撮影範囲が限られ、2mSv前後である。", "C": "上部消化管造影は透視時間によるが、数mSv程度である。", "E": "胸部単純エックス線写真は0.1mSv未満で、選択肢のなかで最も少ない。"}'),
    ('114-C-22', '正答は E「興味のあるものに指さしをしない。」。

興味のあるものを指さして相手と共有する行動(共同注意)は生後10〜12か月ごろに現れる。2歳0か月で指さしがないのは明らかな発達の遅れで、自閉スペクトラム症を含めた評価が必要になる。

出典：厚生労働省ホームページ 第114回医師国家試験 C022',
     '{"A": "三輪車をこげるようになるのは3歳ごろで、2歳でできなくても遅れではない。", "B": "片足立ちは3〜4歳の課題である。", "C": "自分の姓名を言えるようになるのは3歳ごろである。", "D": "はさみで紙を切れるようになるのは3歳ごろである。"}'),
    ('114-C-24', '正答は C「100」。

グルコース5.0%は100mLあたり5gなので、500mL中には25gが含まれる。糖質は1gあたり約4kcalなので、25g×4=100kcalとなる。維持輸液だけでは必要エネルギーをまったく賄えないことが分かる。

出典：厚生労働省ホームページ 第114回医師国家試験 C024',
     '{"A": "約6gのグルコースに相当し、濃度と液量の掛け算が合わない。", "B": "グルコース量を半分に見積もった値である。", "D": "グルコース50g分にあたり、5%500mLの2倍である。", "E": "1gあたり9kcalの脂質として計算したような値で、糖質のエネルギー換算と合わない。"}'),
    ('114-C-35', '正答は B「徒手整復」。

手を引っ張られた直後から肘を動かさなくなり、橈骨頭周囲に圧痛があって腫脹・熱感・発赤がなく、エックス線写真でも骨折がない。輪状靱帯から橈骨頭が亜脱臼する肘内障で、徒手整復(回外法または回内屈曲法)で速やかに改善する。

出典：厚生労働省ホームページ 第114回医師国家試験 C035',
     '{"A": "整復すれば直ちに使えるようになる病態で、鎮痛薬で経過をみる意味はない。", "C": "固定しても亜脱臼は戻らない。整復が先である。", "D": "感染や外傷性の関節内病変ではなく、観血的処置の適応はない。", "E": "整復前の可動域訓練は疼痛を与えるだけで意味がない。"}'),
    ('114-C-37', '正答は E「副腎皮質ステロイド全身投与」。

犬吠様(オットセイの鳴き声様)咳嗽、吸気性喘鳴、陥没呼吸はクループ症候群(急性喉頭気管気管支炎)の典型像である。アドレナリン吸入は効果が一過性なので、声門下の浮腫を抑えるデキサメタゾンなど副腎皮質ステロイドの全身投与を併せて行う。

出典：厚生労働省ホームページ 第114回医師国家試験 C037',
     '{"A": "SpO2 96%で意識も保たれており、直ちに挿管する段階ではない。挿管はさらに気道浮腫を招く危険もある。", "B": "β2刺激薬は下気道の平滑筋に働くもので、声門下の浮腫による上気道狭窄には無効である。", "C": "急性の気道狭窄に呼吸リハビリテーションの適応はない。", "D": "クループの大半はパラインフルエンザウイルスなどウイルス性で、抗菌薬は無効である。"}'),
    ('114-C-38', '正答は C「炭水化物主体の食事にする。」。

炭水化物は呼吸商が1.0と高く、代謝により産生される二酸化炭素が多い。換気予備能の乏しいCOPD患者では炭水化物主体の食事はCO2産生を増やして換気の負担となるため、脂質の比率を高めた食事が勧められる。

出典：厚生労働省ホームページ 第114回医師国家試験 C038',
     '{"A": "肺性心や浮腫を避けるため、塩分の過剰摂取は控える。適切である。", "B": "腹部膨満が横隔膜を押し上げて呼吸を妨げるため、1回量を減らして分割食にする。適切である。", "D": "呼吸仕事量の増大でエネルギー消費が亢進しており、十分なエネルギー摂取が必要である。適切である。", "E": "骨格筋量の維持のため分岐鎖アミノ酸を含む蛋白質の確保が勧められる。適切である。"}'),
    ('114-C-39', '正答は D「サルコペニア」。

長期透析と加齢を背景に、歩行速度の低下、体重減少、下肢筋力低下(MMT 4)が揃っており、サルコペニアと考える。透析患者では蛋白異化の亢進と活動量低下が重なり、高頻度にみられる。

出典：厚生労働省ホームページ 第114回医師国家試験 C039',
     '{"A": "Hb11.0g/dLは透析患者の管理目標範囲に近く、この程度の貧血で横断歩道を渡りきれないほどの歩行障害は説明できない。", "B": "高尿酸血症は関節炎の原因になるが、本例に関節症状の記載はない。", "C": "高リン血症は血管石灰化や二次性副甲状腺機能亢進症に関わるが、直接歩行機能を落とすものではない。", "E": "閉塞性動脈硬化症なら間欠性跛行と足背動脈の触知不良を伴うが、本例は左右差なく触知できる。"}'),
    ('114-C-41', '正答は B「術前3時間までの飲水」。

術後回復力強化(ERAS)の考え方では、術前の長時間絶飲食は脱水とインスリン抵抗性を招くため避け、清澄水は麻酔導入の2〜3時間前まで摂取を許可する。

出典：厚生労働省ホームページ 第114回医師国家試験 C041',
     '{"A": "48時間もの絶食は脱水と異化亢進を招き、合併症を増やす。", "C": "術中の過剰輸液は腸管浮腫を生じて縫合不全や腸管麻痺のリスクを高める。目標指向型の適正輸液を行う。", "D": "術後は早期離床が原則で、臥床の継続は肺炎・静脈血栓症・筋力低下を招く。", "E": "結腸切除後も早期に経口摂取を開始するのが標準で、1週間の絶食は回復を遅らせる。"}'),
    ('114-C-43', '正答は B「オピオイド投与」。

寛解に至らない急性白血病の患者で、NSAIDでは抑えられない腰背部痛と腹痛が増悪し歩行も不能になっている。まず苦痛を取ることが優先で、WHO方式に沿って強オピオイドへ切り替える。血小板が低下しつつある状況でNSAIDを続けることも避けたい。

出典：厚生労働省ホームページ 第114回医師国家試験 C043',
     '{"A": "アルブミン製剤は膠質浸透圧を保つためのもので、疼痛には無効である。", "C": "皮下出血などの出血徴候はなく、この血小板数で予防的輸血の適応にはならない。", "D": "全身放射線照射は造血幹細胞移植の前処置であり、この場面の疼痛緩和にはならない。", "E": "すでに複数の薬物療法で寛解に至っておらず、また抗癌治療に即座の除痛効果は期待できない。"}'),
    ('114-C-47', '正答は D「生活習慣に関する詳細な聴取」。

腹囲104cm、血糖・脂質・肝機能の異常、喫煙、毎日の飲酒と危険因子が重なっており、どれか一つに介入すればよい状態ではない。まず食事内容、飲酒量、身体活動、喫煙の実態と本人の考えを詳しく聴き取り、優先順位をつけて介入を組み立てる。

出典：厚生労働省ホームページ 第114回医師国家試験 C047',
     '{"A": "血圧138/76mmHgは高値血圧の域で、この段階で降圧薬を開始する適応はない。", "B": "禁煙の意思や準備性を確認しないまま薬物療法を始めても続かない。", "C": "空腹時血糖130mg/dL、HbA1c6.8%ですでに糖尿病型を疑う値であり、負荷試験を行う段階を越えている。", "E": "現在の活動量や整形外科的な問題を把握せずに一律の運動強度を勧めるのは、続かないうえ危険でもある。"}'),
    ('114-C-49', '正答は D「肺血栓塞栓症」。

妊娠・産褥期は凝固能が亢進しており、帝王切開・肥満・術後臥床が加わって静脈血栓塞栓症の高リスクとなる。臥床していた患者が初回歩行を始めた直後に突然の呼吸困難・胸痛・低酸素血症をきたすのは肺血栓塞栓症の典型的な発症様式で、下肢深部静脈の血栓が遊離したことによる。

出典：厚生労働省ホームページ 第114回医師国家試験 C049',
     '{"A": "羊水塞栓症は分娩中から直後に発症し、播種性血管内凝固と大量出血を伴う。産後1日目の初回歩行時という経過に合わない。", "B": "29歳で急性心筋梗塞は極めて稀で、心電図異常の記載もない。", "C": "周産期心筋症は心不全として数日から数週かけて進行するもので、突然発症の胸痛と低酸素血症は説明できない。", "E": "急性大動脈解離では引き裂かれるような激痛や血圧の左右差を伴う。呼吸音正常で酸素化のみが低下する本例とは病像が異なる。"}'),
    ('114-C-50', '正答は D「地域包括支援センター」。

地域包括支援センターは、高齢者の総合相談窓口として介護予防・権利擁護・ケアマネジメントを担う。介護保険の利用に至る前の生活上の困りごとを相談する先として適切である。

出典：厚生労働省ホームページ 第114回医師国家試験 C050',
     '{"A": "診療所は医療の窓口であり、生活支援の調整を担う機関ではない。", "B": "保健所は感染症対策や難病支援など公衆衛生を担い、個別の生活支援の窓口ではない。", "C": "特別養護老人ホームは原則要介護3以上を対象とする入所施設で、在宅生活の相談先ではない。", "E": "訪問看護ステーションは医療的ケアを提供する事業所で、サービス全体を調整する総合相談窓口ではない。"}'),
    ('114-C-53', '正答は E「5」。

要介護度は市町村の介護認定審査会が一次判定と主治医意見書をもとに決定するもので、主治医が意見書に記載する事項ではない。主治医は医学的な状態像を書く。

出典：厚生労働省ホームページ 第114回医師国家試験 C053',
     '{"A": "麻痺の有無と程度は身体状況として記載が求められる。", "B": "食事の摂取方法は日常生活動作の状況として記載する。", "C": "移動能力や屋外歩行の可否は記載事項である。", "D": "認知機能や意思決定能力は記載事項である。"}'),
    ('114-C-56', '正答は E「感染予防にサージカルマスク着用が有用である。」。

麻疹は空気感染するため、サージカルマスクでは感染を防げない。医療従事者にはN95マスクの着用が必要で、患者は陰圧個室で管理する。

出典：厚生労働省ホームページ 第114回医師国家試験 C056',
     '{"A": "麻疹は5類感染症の全数把握対象で、診断した医師は直ちに保健所へ届け出る。正しい。", "B": "血液・咽頭ぬぐい液・尿からのウイルス遺伝子検査で確定診断する。正しい。", "C": "空気感染対策として陰圧個室での管理は正しい。", "D": "感染力が強く、受診前の行動から接触者を把握して感染拡大を防ぐ必要がある。正しい。"}'),
    ('114-D-1', '正答は D「頸部の聴診」。

繰り返す片側性の一過性視力障害(一過性黒内障)は、同側の内頸動脈の粥腫から飛んだ微小塞栓が網膜中心動脈を一時的に閉塞して起こる。頸部を聴診して血管雑音を確認し、頸動脈エコーへつなげる。脳梗塞の前触れであり見逃せない。

出典：厚生労働省ホームページ 第114回医師国家試験 D001',
     '{"A": "眼圧上昇による急性緑内障発作は視力低下が持続し、眼痛・充血・頭痛を伴う。反復して自然軽快する経過に合わない。", "B": "視野検査は発作間欠期には正常で、診断の決め手にならない。", "C": "対光反射も発作間欠期には正常である。", "E": "眼球運動障害は視力障害の機序に関与しない。"}'),
    ('114-D-2', '正答は A「脂腺癌」。

マイボーム腺(脂腺)由来の脂腺癌は霰粒腫と外観が酷似し、高齢者で再発を繰り返す霰粒腫では必ず鑑別する。診断が遅れやすい悪性腫瘍で、疑えば生検を行う。

出典：厚生労働省ホームページ 第114回医師国家試験 D002',
     '{"B": "乳頭腫は有茎性で表面が乳頭状に隆起し、霰粒腫の皮下腫瘤とは外観が異なる。", "C": "麦粒腫は急性の炎症で発赤・疼痛・熱感を伴い、無痛性の霰粒腫と経過が異なる。", "D": "基底細胞癌は眼瞼縁に潰瘍や結節を作り睫毛脱落を伴うことが多く、瞼板内の腫瘤とは像が違う。", "E": "ぶどう膜腫瘍は眼球内の腫瘍で、眼瞼腫瘤と紛れることはない。"}'),
    ('114-D-5', '正答は E「直腸子宮窩」。

直腸子宮窩(Douglas窩)は仰臥位で腹腔内の最も低い位置にあたり、術後の滲出液や血液が重力で貯留する。S状結腸切除のように骨盤内を操作した術後に膿瘍を形成しやすい。

出典：厚生労働省ホームページ 第114回医師国家試験 D005',
     '{"A": "右横隔膜下は上腹部の手術後に膿瘍を作りやすい部位である。", "B": "左横隔膜下は脾摘後などで問題となる。", "C": "右傍結腸溝は液体の通り道になるが、最終的には骨盤底に落ちる。", "D": "左傍結腸溝も同様に貯留の最終地点にはなりにくい。"}'),
    ('114-D-6', '正答は D「緑膿菌感染症 — セファゾリン」。

セファゾリンは第1世代セフェムで、緑膿菌には抗菌活性がない。緑膿菌にはセフタジジムやピペラシリン・タゾバクタム、カルバペネム、アミノグリコシドなど抗緑膿菌活性をもつ薬剤を用いる。

出典：厚生労働省ホームページ 第114回医師国家試験 D006',
     '{"A": "オウム病(Chlamydia psittaci)にはテトラサイクリン系が第一選択で、正しい。", "B": "放線菌症にはペニシリン系の大量長期投与を行う。正しい。", "C": "ノカルジア症にはST合剤が第一選択である。正しい。", "E": "レジオネラ症にはキノロン系やマクロライド系が有効である。正しい。"}'),
    ('114-D-7', '正答は C「離脱症状にベンゾジアゼピン系薬を投与する。」。

アルコール離脱では中枢神経の過剰興奮が生じ、けいれんや振戦せん妄に至りうる。ベンゾジアゼピン系薬はアルコールと交叉耐性があり、これを予防・軽減する目的で用いる。

出典：厚生労働省ホームページ 第114回医師国家試験 D007',
     '{"A": "外来での断酒治療が基本で、入院は重症の離脱や重い身体合併症、家庭環境の問題がある場合に選択する。", "B": "匿名参加を原則とするのはAA(Alcoholics Anonymous)である。断酒会は実名で家族とともに参加するのが特徴である。", "D": "Wernicke脳症の予防に必要なのはビタミンB1(チアミン)であり、ビタミンDではない。", "E": "本人に知らせずに薬を投与することは同意原則に反し、飲酒時の強い反応で危険でもある。"}'),
    ('114-D-8', '正答は C「子宮頸管ポリープ」。

子宮頸管ポリープは不正性器出血の原因となるが、妊娠の継続を妨げる病態ではなく流産との関連は知られていない。

出典：厚生労働省ホームページ 第114回医師国家試験 D008',
     '{"A": "年齢が上がるほど卵子の染色体異常が増え、流産率は上昇する。", "B": "甲状腺機能低下症は流産・早産のリスクを高め、妊娠前からの補充が必要となる。", "D": "抗リン脂質抗体症候群は胎盤の微小血栓により反復流産をきたす代表的な病態である。", "E": "均衡型転座の保因者では不均衡型の配偶子が生じ、流産を繰り返す。"}'),
    ('114-D-9', '正答は A「咽頭」。

ヘルパンギーナはコクサッキーA群ウイルスによる夏かぜで、軟口蓋から口蓋弓にかけての咽頭後方に小水疱とアフタが多発する。高熱を伴い、疼痛のため摂食不良となる。

出典：厚生労働省ホームページ 第114回医師国家試験 D009',
     '{"B": "手掌の水疱は手足口病の所見である。", "C": "足底の水疱も手足口病でみられる。", "D": "体幹の発疹は水痘や麻疹などで、ヘルパンギーナの好発部位ではない。", "E": "外陰部は手足口病で時に侵されるが、ヘルパンギーナの好発部位ではない。"}'),
    ('114-D-10', '正答は B「大動脈二尖弁」。

大動脈二尖弁は左心系の弁の形態異常で、右左短絡を生じないためチアノーゼをきたさない。狭窄や閉鎖不全、上行大動脈拡大が問題となる。

出典：厚生労働省ホームページ 第114回医師国家試験 D010',
     '{"A": "Fallot四徴症は右室流出路狭窄と心室中隔欠損により右左短絡を生じ、チアノーゼをきたす。", "C": "完全大血管転位症は体循環と肺循環が並列となり、生後早期から強いチアノーゼを示す。", "D": "総肺静脈還流異常症では肺静脈血が右房に還り、心房間交通を通じて右左短絡となる。", "E": "Eisenmenger症候群では肺高血圧により短絡が右左に逆転してチアノーゼが出現する。"}'),
    ('114-D-11', '正答は E「後頸部リンパ節腫脹」。

伝染性単核球症(EBウイルス感染症)では後頸部のリンパ節が腫大するのが特徴で、前頸部が主体となるA群溶連菌性咽頭炎との鑑別点になる。肝脾腫、異型リンパ球、肝逸脱酵素上昇を伴う。

出典：厚生労働省ホームページ 第114回医師国家試験 D011',
     '{"A": "頭痛は両者に共通してみられ、鑑別に役立たない。", "B": "発熱も両者に共通する。", "C": "咽頭発赤・扁桃の白苔はどちらでもみられ、外観では区別できない。", "D": "咳嗽の有無はウイルス性咽頭炎と溶連菌性咽頭炎の区別に用いるが、伝染性単核球症を特異的に示すものではない。"}'),
    ('114-D-16', '正答は D「右付属器」。

子宮内膜症性囊胞(チョコレート囊胞)を背景に発生した卵巣癌が疑われる。卵巣癌の標準術式は子宮全摘・両側付属器摘出・大網切除であり、肉眼的に正常にみえる対側(右)の付属器も摘出する。潜在的な転移や新たな発生の場となるためである。

出典：厚生労働省ホームページ 第114回医師国家試験 D016',
     '{"A": "腟壁への浸潤を示す所見はなく、切除の対象にならない。", "B": "膀胱への浸潤や癒着は認められていない。", "C": "腫瘤と腸管との癒着はないと明記されており、S状結腸を合併切除する理由がない。", "E": "腹膜播種がなく、腸間膜リンパ節は卵巣癌の所属リンパ節でもない。"}'),
    ('114-D-17', '正答は C「子宮破裂」。

腹腔鏡下子宮筋腫核出術の既往があり、その瘢痕部から子宮が破裂したと考える。外出血が少量にとどまるのに頻脈・低血圧・意識混濁と腹痛をきたしているのは、出血が腹腔内に貯留しているためである。

出典：厚生労働省ホームページ 第114回医師国家試験 D017',
     '{"A": "頸管裂傷では持続する鮮紅色の外出血が目立つ。本例は外出血が少量である。", "B": "弛緩出血でも外出血が多量となり、子宮は柔らかく触れる。", "D": "胎盤は5分でスムーズに娩出されており、癒着胎盤は否定的である。", "E": "子宮内反症では腟内に反転した子宮底を触知し、強い下腹部痛と外出血を伴う。"}'),
    ('114-D-18', '正答は B「卵巣」。

1年前から月経がなくFSHが38mIU/mLと上昇しており、卵巣機能の低下によるエストロゲン欠乏状態にある。発作性の発汗・熱感(hot flush)や肩こりは更年期症状で、原因臓器は卵巣である。

出典：厚生労働省ホームページ 第114回医師国家試験 D018',
     '{"A": "AST・ALTとも正常で肝疾患を示す所見はない。", "C": "FSHが高値であることは下垂体が正常に反応している証拠で、下垂体の障害は否定的である。", "D": "心電図に異常がなく胸部症状もない。冠動脈疾患では説明できない。", "E": "TSHもFT4も基準内で、甲状腺機能は正常である。"}'),
    ('114-D-19', '正答は C「遂行機能障害」。

時刻や食事内容への常同的なこだわり、脱抑制的な易怒性、自分の主張を押し通す社会的行動の変化が前景で、記憶・見当識・日常生活動作は保たれている。行動障害型前頭側頭型認知症であり、前頭葉機能である遂行機能の障害が予想される。

出典：厚生労働省ホームページ 第114回医師国家試験 D019',
     '{"A": "具体的で反復する幻視はLewy小体型認知症の中核症状である。", "B": "復唱の障害は伝導失語でみられる所見で、会話に不自由のない本例には合わない。", "D": "視空間認知の障害はAlzheimer型やLewy小体型で目立つ。", "E": "エピソード記憶の障害はAlzheimer型の中核症状だが、本例は物忘れがないと明記されている。"}'),
    ('114-D-29', '正答は B「頰粘膜」。

発熱がいったん下がって再び上昇する二峰性の経過と、その後の発疹は麻疹に典型的である。カタル期の終わりに頰粘膜(第二大臼歯付近)に現れるKoplik斑は麻疹に特異的で、発疹出現前後の短期間しか見られないため確認を急ぐ。

出典：厚生労働省ホームページ 第114回医師国家試験 D029',
     '{"A": "口唇の変化(いちご舌や口唇の紅潮・亀裂)は川崎病や溶連菌感染症の所見である。", "C": "眼球結膜の充血は麻疹でもみられるが、川崎病やアデノウイルス感染でも生じ特異性が低い。", "D": "後頸部リンパ節腫脹は風疹を示唆する所見である。", "E": "BCG接種部位の発赤は川崎病に特徴的な所見である。"}'),
    ('114-D-31', '正答は E「保存療法として足関節背屈制限装具を用いる。」。

アキレス腱断裂の保存療法では、足関節を底屈位に保って断裂した腱の断端を近づけ、背屈を制限する装具を用いる。治癒に伴って徐々に背屈を許していく。

出典：厚生労働省ホームページ 第114回医師国家試験 D031',
     '{"A": "スポーツ復帰を目指す例や再断裂を避けたい例では手術も選択肢となり、適応がないとは言えない。", "B": "長母趾屈筋や後脛骨筋など他の底屈筋が働くため自動運動は可能で、つま先立ちができないだけである。", "C": "前後方向の不安定性は靱帯損傷でみられるもので、腱の断裂では生じない。", "D": "Thompson試験では下腿三頭筋を把握しても足関節が底屈しないことが断裂の所見である。底屈するのは腱が連続している証拠になる。"}'),
    ('114-D-35', '正答は A「減圧症」。

潜水後に十分な時間をおかず航空機に搭乗すると、機内の気圧低下により体内に溶けていた窒素が気泡化して減圧症をきたす。関節痛(ベンズ)や四肢のしびれ、手指の震えといった神経症状が現れる。

出典：厚生労働省ホームページ 第114回医師国家試験 D035',
     '{"B": "動揺病は悪心・嘔吐・冷汗が主症状で、関節痛や指先の感覚異常は生じない。", "C": "頸肩腕障害は反復作業の蓄積で緩徐に進行するもので、ダイビングと搭乗を契機とする急性発症に合わない。", "D": "塗料店での仕事は在庫管理であって有機溶剤への曝露は限定的であり、症状の発現時期がダイビングと搭乗に一致している。", "E": "VDT作業による障害は眼精疲労や頸肩腕症状が中心で、経過が合わない。"}'),
    ('114-D-36', '正答は B「寒冷凝集素高値」。

寒冷曝露で手指や耳介がチアノーゼとなり、貧血・黄疸・ヘモグロビン尿(尿潜血3+)を伴っている。IgM型の寒冷凝集素が低温で赤血球に結合し、補体を介して血管内溶血を起こす寒冷凝集素症である。

出典：厚生労働省ホームページ 第114回医師国家試験 D036',
     '{"A": "溶血に対する骨髄の代償で網赤血球はむしろ増加する。", "C": "IgG型の自己抗体が関与するのは温式自己免疫性溶血性貧血で、寒冷凝集素はIgMである。", "D": "血管内溶血で遊離したヘモグロビンと結合して消費されるため、ハプトグロビンは低下する。", "E": "GPIアンカー蛋白の欠損は発作性夜間ヘモグロビン尿症の所見で、寒冷曝露との関連はない。"}'),
    ('114-D-40', '正答は D「頸動脈洞マッサージ」。

両側頸動脈に動脈硬化性狭窄があるため、頸動脈洞マッサージは粥腫を遊離させて脳塞栓を起こす危険があり行ってはならない。同様に高齢者や頸動脈雑音を聴取する例では禁忌である。

出典：厚生労働省ホームページ 第114回医師国家試験 D040',
     '{"A": "Valsalva手技は迷走神経刺激により発作性上室頻拍を停止させる方法で、最初に試みるべき安全な手技である。", "B": "ベラパミルは房室結節の伝導を抑えて発作性上室頻拍を停止させる。", "C": "ジソピラミドはIa群抗不整脈薬で、上室頻拍に用いられることがある。", "E": "アデノシン三リン酸は房室結節を一過性に遮断し、発作性上室頻拍の停止に有効である。"}'),
    ('114-D-42', '正答は A「関節液検査」。

発熱を伴う急性の単関節炎で、関節液を採取して細胞数・グラム染色・培養・偏光顕微鏡による結晶の検索を行うことが最優先である。化膿性関節炎と結晶誘発性関節炎は治療がまったく異なり、関節液を見ずに治療を始めてはならない。

出典：厚生労働省ホームページ 第114回医師国家試験 D042',
     '{"B": "造影CTは膿瘍や骨破壊の評価には役立つが、起炎菌や結晶の有無は分からない。", "C": "固定は診断がついた後の補助的手段で、原因の特定にならない。", "D": "培養検体を採る前に広域抗菌薬を投与すると起炎菌の同定が困難になる。", "E": "化膿性関節炎であればステロイドの関節内投与は感染を悪化させる。診断前には行えない。"}'),
    ('114-D-47', '正答は D「Lewy小体型認知症」。

具体的で反復する幻視、REM睡眠行動異常症を示唆する数年来の寝言や夜間の行動、半年前からの動作緩慢というパーキンソニズムが揃っており、Lewy小体型認知症の中核症状を満たす。見当識が保たれ礼節も保たれている点も矛盾しない。

出典：厚生労働省ホームページ 第114回医師国家試験 D047',
     '{"A": "妄想性障害では体系化した妄想が主体で、パーキンソニズムやREM睡眠行動異常症は説明できない。", "B": "血管性認知症では脳血管障害の画像所見と階段状の経過、局所神経徴候を伴う。", "C": "前頭側頭型認知症では脱抑制や常同行動が前景となり、幻視は稀である。", "E": "Alzheimer型認知症は近時記憶の障害が中核で、初期から幻視とパーキンソニズムが揃うことはない。"}'),
    ('114-D-48', '正答は D「Fanconi症候群」。

シスプラチンは近位尿細管に毒性を示す。血糖が正常なのに尿糖が陽性(腎性糖尿)で、尿中β2-マイクログロブリンが著明に増加しているのは近位尿細管での再吸収障害を意味し、Fanconi症候群である。

出典：厚生労働省ホームページ 第114回医師国家試験 D048',
     '{"A": "腎性尿崩症では集合管がADHに反応せず、多尿と低張尿(尿比重の低下)をきたす。尿量1,200mL・比重1.014の本例と合わない。", "B": "Liddle症候群は上皮性ナトリウムチャネルの機能亢進による遺伝性疾患で、高血圧と低カリウム性アルカローシスを示す。", "C": "Bartter症候群はHenleループ上行脚の障害で、低カリウム性アルカローシスをきたすが尿細管性の糖尿は示さない。", "E": "Gitelman症候群は遠位尿細管の障害で、低カリウム血症と低マグネシウム血症が特徴である。"}'),
    ('114-D-55', '正答は B「発達遅滞をきたす。」。

胎児発育不全、眼裂狭小と小下顎の特徴的顔貌、手指の重合(overlapping fingers)、揺り椅子状足底、筋緊張亢進は18トリソミー(Edwards症候群)の所見である。生存例では重度の発達遅滞をきたす。

出典：厚生労働省ホームページ 第114回医師国家試験 D055',
     '{"A": "18トリソミーの生命予後は不良で、多くが生後1年以内に死亡する。", "C": "心室中隔欠損をはじめとする先天性心疾患を90%以上に合併する。", "D": "急性白血病を合併しやすいのは21トリソミー(Down症候群)である。", "E": "甲高い猫の鳴き声のような泣き声は5p欠失症候群(猫鳴き症候群)の特徴である。"}'),
    ('114-D-56', '正答は B「吸入副腎皮質ステロイド薬」。

吸入副腎皮質ステロイド薬は気道の慢性炎症そのものを抑える治療の土台で、症状が消えても継続する。中止すると炎症が再燃して増悪や死亡のリスクが上がる。本例は好酸球10%と気道炎症の残存も示唆され、減薬するとしても最後まで残すべき薬剤である。

出典：厚生労働省ホームページ 第114回医師国家試験 D056',
     '{"A": "テオフィリンは有効血中濃度の幅が狭く、悪心・不整脈・けいれんなどの副作用もあるため、減薬では優先して外す。", "C": "長時間作用性β2刺激薬は単独では使えず、症状が安定すれば吸入ステロイド単剤に戻すことができる。", "D": "長時間作用性抗コリン薬は step-up のための追加薬で、コントロールが得られれば減らせる。", "E": "ロイコトリエン受容体拮抗薬も追加治療の位置づけで、減薬の対象となる。"}'),
    ('114-D-58', '正答は D「心拍数」。

母体のTSH受容体刺激抗体は胎盤を通過して児の甲状腺を刺激する。母体が服用していた抗甲状腺薬は児から速やかに消失するため、生後数日で新生児バセドウ病が顕在化する。頻脈が最も早く現れる徴候で、放置すると心不全に至る。

出典：厚生労働省ホームページ 第114回医師国家試験 D058',
     '{"A": "血圧は新生児甲状腺機能亢進症の早期指標として鋭敏ではない。", "B": "尿量は循環動態を反映するが、甲状腺機能亢進の直接の指標ではない。", "C": "呼吸数は心不全が進めば増えるが、頻脈より遅れて現れる。", "E": "酸素飽和度の低下は心不全の進行を示すもので、早期発見の指標にならない。"}'),
    ('114-D-60', '正答は D「リスペリドン」。

被害関係妄想(テレビが自分のことを流す、サインを送ってくる)と幻聴を疑わせる訴えがあり、感情表出の乏しさなど陰性症状も伴う。器質的疾患は除外されており統合失調症と考え、第二世代抗精神病薬であるリスペリドンを用いる。

出典：厚生労働省ホームページ 第114回医師国家試験 D060',
     '{"A": "イミプラミンは三環系抗うつ薬で、うつ病に用いる。", "B": "炭酸リチウムは双極症の気分安定薬である。", "C": "フェニトインは抗てんかん薬で、脳波に異常のない本例に適応はない。", "E": "カルバマゼピンは抗てんかん薬・気分安定薬で、統合失調症の第一選択にはならない。"}'),
    ('114-E-1', '正答は B「患者本人の意思が確認できる場合は患者の意向を尊重する。」。

人生の最終段階における医療・ケアの決定プロセスに関するガイドラインでは、本人による意思決定を基本とする。本人の意思が確認できるならその意向を尊重し、繰り返し話し合って共有する。

出典：厚生労働省ホームページ 第114回医師国家試験 E001',
     '{"A": "意思が確認できないときも、家族の意向にそのまま従うのではなく、家族らとともに本人の推定意思を探ることが求められる。", "C": "認知症があっても意思決定能力は一律に失われるわけではなく、その時々の状態に応じて個別に評価する。", "D": "意思決定能力の評価は主治医を含む医療・ケアチームが行うもので、精神科医の診察が必須ではない。", "E": "家族間で意見が分かれた場合に優先順位はなく、多職種のチームで話し合い合意形成を図る。"}'),
    ('114-E-2', '正答は D「麻酔薬の注射後、疼痛の有無を確認してから処置を行う。」。

局所麻酔薬を注射した後は、切開する前に疼痛の有無を確認して効果が得られていることを確かめる。効いていないまま処置を始めると強い苦痛を与える。

出典：厚生労働省ホームページ 第114回医師国家試験 E002',
     '{"A": "18Gは太く刺入時の痛みが強い。局所麻酔には25〜27Gの細い針を用いる。", "B": "消毒は滅菌ドレープの穴より広い範囲に行う。狭いと清潔野の縁が汚染される。", "C": "ポビドンヨードは乾燥する過程で殺菌力を発揮するため、2分程度待ってから処置する。", "E": "血液の逆流が「ない」ことを確認してから注入する。逆流があれば血管内であり、局所麻酔薬中毒の危険がある。"}'),
    ('114-E-3', '正答は D「医療安全支援センターの業務は医療法に規定されている。」。

医療安全支援センターは医療法第6条の13に基づき都道府県・保健所設置市・特別区に設置され、患者からの苦情・相談への対応や情報提供を行う。

出典：厚生労働省ホームページ 第114回医師国家試験 E003',
     '{"A": "定期予防接種の実施主体は市町村である。", "B": "地方衛生研究所は検査・研究を担う対物サービスの機関で、対人サービスは行わない。", "C": "地域包括支援センターの設置主体は市町村である。", "E": "市町村保健センターに医師を必ず置くという規定はない。医師であることが求められるのは保健所長である。"}'),
    ('114-E-4', '正答は D「「心配し過ぎるあなたの性格に問題があるように思います」」。

「心配し過ぎる性格に問題がある」という言葉は、患者の訴えを性格のせいにして責めるもので、信頼関係を損ない受診の継続も妨げる。不安の背景を探る機会も失われる。

出典：厚生労働省ホームページ 第114回医師国家試験 E004',
     '{"A": "感情の表出を促す開かれた問いで、適切である。", "B": "患者が何を恐れているのかという解釈モデルを尋ねるもので、適切である。", "C": "患者の感情を言葉にして返す共感的応答で、適切である。", "E": "努力を認めて支える支持的な言葉で、適切である。"}'),
    ('114-E-5', '正答は E「瞳孔径の左右差」。

瞳孔径の左右差(瞳孔不同)は、鉤ヘルニアにより動眼神経が圧迫されていることを示す。脳ヘルニアが切迫している徴候で、直ちに画像評価と頭蓋内圧管理を要する。

出典：厚生労働省ホームページ 第114回医師国家試験 E005',
     '{"A": "眼脂は結膜炎などの所見で、緊急性はない。", "B": "翼状片は結膜の増殖性変化で、慢性の所見である。", "C": "眼球結膜下出血は自然に吸収され、それ自体は緊急性がない。", "D": "眼瞼結膜の充血は結膜炎などを示すもので、意識障害の原因評価では優先度が低い。"}'),
    ('114-E-6', '正答は B「PM2.5はタバコの煙に含まれている。」。

タバコの煙には粒径2.5μm以下の微小粒子状物質(PM2.5)が大量に含まれ、屋内の受動喫煙環境ではしばしば大気汚染の基準値をはるかに超える濃度になる。

出典：厚生労働省ホームページ 第114回医師国家試験 E006',
     '{"A": "依存性の本体はニコチンである。タールは発癌物質を含む成分である。", "C": "煙は空間を越えて拡散し、換気や分煙では受動喫煙を防ぎきれない。屋内の全面禁煙が必要である。", "D": "発癌の主因はタールに含まれる多環芳香族炭化水素やニトロソアミンなどである。", "E": "禁煙により肺癌のリスクは着実に低下するが、長期の禁煙後も非喫煙者と同じ水準までは下がらない。"}'),
    ('114-E-8', '正答は C「輸血製剤の放射線照射が予防に有効である。」。

輸血後移植片対宿主病は、輸血製剤中の生きたドナーリンパ球が受血者の組織を攻撃して起こる。放射線照射でリンパ球を不活化することが確実な予防法で、我が国ではほぼすべての輸血用血液が照射されている。

出典：厚生労働省ホームページ 第114回医師国家試験 E008',
     '{"A": "発症は輸血の1〜2週後で、6時間以内ではない。6時間以内に起こるのは輸血関連急性肺障害などである。", "B": "リンパ球が生存している新鮮血のほうが起こりやすい。保存により生着能は低下する。", "D": "初回輸血でも発症しうる。輸血回数との関連はない。", "E": "HLAハプロタイプが一方向に適合する血縁者からの供血で起こりやすい。このため血縁者からの輸血は避ける。"}'),
    ('114-E-9', '正答は E「黄色泡沫状腟分泌」。

黄色泡沫状の腟分泌物はトリコモナス腟炎に特徴的な所見で、感染症によるものである。月経周期に伴うホルモン変動とは関係しない。

出典：厚生労働省ホームページ 第114回医師国家試験 E009',
     '{"A": "黄体期にはプロゲステロンの作用で水分が貯留し、体重がわずかに増える。", "B": "排卵期にエストロゲンが一過性に低下することで中間期出血が起こる。", "C": "乳房の緊満感は黄体期のプロゲステロンによるもので、月経開始とともに軽快する。", "D": "排卵期にはエストロゲンの作用で頸管粘液が増量し、透明で牽糸性が高くなる。"}'),
    ('114-E-10', '正答は C「過多月経」。

筋層内筋腫が大きくなると子宮内腔の面積が増え、月経時の子宮収縮も妨げられるため出血量が増える。過多月経とそれによる鉄欠乏性貧血が代表的な症状である。

出典：厚生労働省ホームページ 第114回医師国家試験 E010',
     '{"A": "片頭痛は血管・三叉神経系の病態で、子宮筋腫とは関係しない。", "B": "排卵の有無は視床下部-下垂体-卵巣系が規定するもので、筋腫は関与しない。", "D": "希発月経は排卵障害によるもので、筋腫では生じない。", "E": "月経前症候群は黄体期のホルモン変動に伴う症候群であり、筋腫の有無とは独立である。"}'),
    ('114-E-11', '正答は E「反跳痛〈rebound tenderness〉は手掌全体で押さえて確認する。」。

反跳痛は、指先で局所をゆっくり圧迫してから急に手を離し、離した瞬間の痛みをみる。手掌全体で押さえると圧痛の局在が分からず、患者に与える苦痛も大きい。

出典：厚生労働省ホームページ 第114回医師国家試験 E011',
     '{"A": "言葉で訴えない患者もいるため、表情の変化を観察することは重要である。正しい。", "B": "痛みのない部位から始めることで、患者の緊張を減らし比較の基準も得られる。正しい。", "C": "打診で痛みがある時点で腹膜刺激が疑われ、触診はより慎重にすべきである。正しい。", "D": "腹膜刺激が明らかな部位を繰り返し触診しても情報は増えず、苦痛を与えるだけである。正しい。"}'),
    ('114-E-12', '正答は C「細菌検査の検体を採取後に抗菌薬を投与する。」。

抗菌薬を投与すると細菌が検出されにくくなるため、血液培養などの検体は投与前に採取する。起炎菌と感受性が分かれば、狭域薬への変更(de-escalation)が可能になる。

出典：厚生労働省ホームページ 第114回医師国家試験 E012',
     '{"A": "感染症ごとに必要な投与期間があり、解熱だけを基準に中止すると再燃する。", "B": "発熱の原因はウイルス感染や非感染性のことも多く、発熱そのものは抗菌薬の適応にならない。", "D": "感受性が判明したら狭域薬へ変更するのが原則で、広域薬の漫然とした継続は耐性菌を生む。", "E": "解熱薬は発熱を抑えてしまい、抗菌薬が効いているかどうかの判定をかえって難しくする。"}'),
    ('114-E-14', '正答は C「データを自分の仮説に合うように改ざんする。」。

データを仮説に合うように書き換えることは改ざんであり、捏造・盗用と並ぶ研究不正の中核である。研究そのものの信頼を失わせ、患者に害を及ぼしうる。

出典：厚生労働省ホームページ 第114回医師国家試験 E014',
     '{"A": "利益相反の公表は求められる行為で、倫理に反しない。", "B": "個人が特定されないようにすることは守秘義務上必要な配慮である。", "D": "自験例をまとめて発表することは通常の学術活動である。", "E": "企業から助成を受けた研究でも、利益相反を開示したうえで発表することは問題ない。"}'),
    ('114-E-15', '正答は A「職種独自の略語を使用する。」。

職種の内輪でしか通じない略語は、他職種に意味が伝わらないだけでなく誤解を生み、患者の安全を損なう。チーム内では共通の言葉を使う。

出典：厚生労働省ホームページ 第114回医師国家試験 E015',
     '{"B": "家族の希望を聴くことは、患者中心のケアを組み立てるうえで欠かせない。", "C": "他職種の意見を尊重する姿勢はチーム医療の前提である。", "D": "各職種の専門性が確立していることは、役割分担を可能にする条件である。", "E": "他職種の役割と機能を理解していれば、適切な依頼と連携ができる。"}'),
    ('114-E-16', '正答は A「貧血の影響を受ける。」。

HbA1cは赤血球の寿命に依存するため、貧血の影響を受ける。溶血や出血で赤血球寿命が短縮すると低値になり、未治療の鉄欠乏性貧血では高値に傾く。数値の解釈には血算を併せて見る必要がある。

出典：厚生労働省ホームページ 第114回医師国家試験 E016',
     '{"B": "HbA1cはグルコースがヘモグロビンのβ鎖N末端に結合したもので、他の糖は反映しない。", "C": "反映するのは過去1〜2か月の平均血糖である。1〜2週間を反映するのはグリコアルブミンである。", "D": "酵素を介さない非酵素的な糖化反応によって生じる。", "E": "我が国のメタボリックシンドロームの診断基準は腹囲に加えて血圧・血糖(空腹時)・脂質で、HbA1cは含まれない。"}'),
    ('114-E-17', '正答は D「症例数の設定のためには治療効果の推定が必要である。」。

必要な症例数は、検出したい治療効果の大きさ、有意水準、検出力から算出する。したがって設計段階で治療効果を推定しておく必要がある。

出典：厚生労働省ホームページ 第114回医師国家試験 E017',
     '{"A": "外科手技やリハビリテーションなど盲検化が困難な介入もあり、二重盲検は必須ではない。", "B": "有効性が確立した標準治療がない領域ではプラセボ対照は倫理的に許容される。禁止されてはいない。", "C": "ランダム割付の目的は既知・未知の交絡因子を群間で均等にすることであり、症例数を減らすためではない。", "E": "ITT解析は実際に受けた治療ではなく、割り付けられたとおりに解析する方法である。実際の治療に基づくのはper protocol解析やas treated解析である。"}'),
    ('114-E-18', '正答は B「大村智 — マラリアに対する新たな治療法の発見」。

大村智の受賞理由は、線虫による寄生虫感染症(オンコセルカ症・リンパ系フィラリア症)に対する新規治療法の発見で、イベルメクチンの基となるエバーメクチンの発見による。マラリアに対する治療法(アルテミシニン)の発見で同時受賞したのは屠呦呦である。

出典：厚生労働省ホームページ 第114回医師国家試験 E018',
     '{"A": "大隅良典はオートファジーの仕組みの解明で2016年に受賞した。正しい。", "C": "利根川進は抗体の多様性が生まれる遺伝的原理の発見で1987年に受賞した。正しい。", "D": "本庶佑は免疫チェックポイント分子PD-1の発見と癌治療への応用で2018年に受賞した。正しい。", "E": "山中伸弥は成熟細胞の初期化による多能性獲得(iPS細胞)で2012年に受賞した。正しい。"}'),
    ('114-E-19', '正答は A「脂肪腫」。

脂肪腫は皮下に存在する腫瘍で、その上の表皮は正常である。したがって触診では表面が平滑で、柔らかく可動性のある腫瘤として触れる。

出典：厚生労働省ホームページ 第114回医師国家試験 E019',
     '{"B": "Bowen病は表皮内癌で、角化を伴う紅色局面として鱗屑を付け表面はざらつく。", "C": "尋常性疣贅は表面が粗糙で乳頭状に隆起し、点状の黒色(血栓化した毛細血管)を伴う。", "D": "脂漏性角化症は表面が疣状・顆粒状で、脂ぎった感触を示す。", "E": "ケラトアカントーマは中央に角栓を有する火山状の結節で、表面は平滑ではない。"}'),
    ('114-E-20', '正答は E「25%アルブミン液」。

25%アルブミン液は血漿より浸透圧が高い高張液で、投与すると膠質浸透圧により組織間から血管内へ水を引き込む。循環血漿量を増やす目的で用いる。

出典：厚生労働省ホームページ 第114回医師国家試験 E020',
     '{"A": "生理食塩液は0.9%塩化ナトリウム液で、血漿とほぼ等張である。", "B": "5%ブドウ糖液は投与時点では等張だが、糖が代謝されて自由水が残るため細胞内へも分布する。等張液に分類される。", "C": "酢酸リンゲル液は電解質組成を血漿に近づけた等張の細胞外液補充液である。", "D": "乳酸リンゲル液も同様に等張の細胞外液補充液である。"}'),
    ('114-E-21', '正答は A「GH」。

成長ホルモンは血糖の上昇によって分泌が抑制されるため、食後に低下する。逆に空腹・睡眠・運動・低血糖で分泌が高まる。この性質を利用して、先端巨大症の診断には75g経口ブドウ糖負荷試験でGHが抑制されないことを確認する。

出典：厚生労働省ホームページ 第114回医師国家試験 E021',
     '{"B": "インスリンは食後の血糖上昇に応じて分泌が増える。", "C": "血糖は食後に上昇する。", "D": "トリグリセリドは食事由来のカイロミクロンにより食後に上昇する。", "E": "遊離サイロキシンは食事による短期的な変動を示さない。"}'),
    ('114-E-22', '正答は B「腎不全」。

観察研究のアウトカムには、患者にとって意味のある事象を置く。糖尿病腎症の腎機能予後を問うなら、透析導入を要する腎不全という真のアウトカムが臨床的に最も重要である。

出典：厚生労働省ホームページ 第114回医師国家試験 E022',
     '{"A": "HbA1cは血糖管理の指標であって、腎機能の予後そのものではない。", "C": "蛋白尿は腎不全への進行を予測する代替アウトカムで、真のアウトカムには及ばない。", "D": "下腿浮腫は腎機能以外の要因でも生じ、腎機能予後の指標としては不適切である。", "E": "病理所見は病態の理解には有用だが、患者にとっての帰結を直接表すものではない。"}'),
    ('114-E-23', '正答は B「嚥下機能」。

言語聴覚士は言語・構音・音声・聴覚に加えて摂食嚥下を担当する。脳梗塞後は嚥下障害の頻度が高く、誤嚥性肺炎の予防のため嚥下機能の評価と訓練を行う。

出典：厚生労働省ホームページ 第114回医師国家試験 E023',
     '{"A": "見当識を含む認知機能の評価は医師や公認心理師が担うことが多い。", "C": "手指の巧緻運動や日常生活動作の訓練は作業療法士の領域である。", "D": "四肢筋力の評価と基本動作の訓練は理学療法士の領域である。", "E": "心理状態の評価と支援は公認心理師や精神科医が担う。"}'),
    ('114-E-24', '正答は C「心電図検査」。

失神ではまず心原性失神を除外する。不整脈、QT延長、Brugada症候群、心筋虚血など突然死につながる病態を心電図で拾えるため、血糖測定とともに直ちに施行する。

出典：厚生労働省ホームページ 第114回医師国家試験 E024',
     '{"A": "けいれんを伴わない失神でてんかんの頻度は低く、脳波は初期検査として優先度が低い。", "B": "頸椎の病変は失神の原因とならない。", "D": "頸動脈狭窄は脳梗塞の危険因子だが、それ自体で失神をきたすことは稀である。", "E": "胸部エックス線写真は補助的で、失神の致死的原因を直接拾えない。"}'),
    ('114-E-25', '正答は C「水痘帯状疱疹ウイルス」。

麻疹は空気(飛沫核)感染するため、陰圧個室とN95マスクによる空気予防策を要する。同じ空気予防策が必要なのは水痘帯状疱疹ウイルスと結核菌である。

出典：厚生労働省ホームページ 第114回医師国家試験 E025',
     '{"A": "A群レンサ球菌は飛沫予防策の対象である。", "B": "ムンプスウイルスも飛沫予防策の対象である。", "D": "多剤耐性緑膿菌は接触予防策の対象である。", "E": "メチシリン耐性黄色ブドウ球菌も接触予防策の対象である。"}'),
    ('114-E-26', '正答は B「血液培養」。

アトピー性皮膚炎の搔破で皮膚のバリアが破綻したところから細菌が侵入し、菌血症をきたしている。悪寒戦慄を伴う発熱に加え、血圧86/58mmHg、頻脈、頻呼吸と敗血症の徴候が揃っており、抗菌薬を開始する前に血液培養を2セット採取する。

出典：厚生労働省ホームページ 第114回医師国家試験 E026',
     '{"A": "頻尿も排尿時痛もなく背部叩打痛もないため、尿路感染を第一に疑う根拠がない。", "C": "咳・痰がなく呼吸音も正常で、喀痰を採取できる状況でも肺炎を示唆する状況でもない。", "D": "皮疹はアトピー性皮膚炎による紅斑・鱗屑・搔破痕であり、麻疹の発疹の経過とは異なる。", "E": "上気道症状がなく周囲に同様の症状の人もおらず、インフルエンザを疑う状況ではない。"}'),
    ('114-E-27', '正答は E「バッグバルブマスクによる人工呼吸」。

新生児蘇生では、初期処置(保温・気道確保・皮膚刺激)の後に自発呼吸がないか心拍が100/分未満であれば、直ちにバッグバルブマスクによる人工呼吸を開始する。本例は心拍110/分だが自発呼吸がないため、人工呼吸の適応である。

出典：厚生労働省ホームページ 第114回医師国家試験 E027',
     '{"A": "気管挿管はマスク換気で有効な換気が得られない場合や胸骨圧迫を要する場合に考慮する。", "B": "胸骨圧迫は有効な人工呼吸を30秒行っても心拍が60/分未満のときに開始する。心拍110/分では適応がない。", "C": "生理食塩液の急速投与は循環血液量減少が疑われるときの処置である。", "D": "アドレナリンは十分な換気と胸骨圧迫を行っても心拍が60/分未満のときに用いる。"}'),
    ('114-E-28', '正答は E「常位胎盤早期剝離」。

妊娠高血圧腎症と喫煙という危険因子があり、激しい腹痛、板状硬の子宮、胎盤の著明な肥厚(後血腫)、基線細変動の減少と遅発一過性徐脈という胎児機能不全が揃っている。常位胎盤早期剝離で、外出血が少量でも出血の大半は子宮内に貯留する。母児ともに危険で緊急帝王切開を要する。

出典：厚生労働省ホームページ 第114回医師国家試験 E028',
     '{"A": "切迫早産では規則的な子宮収縮と頸管の熟化がみられるが、子宮が板状に硬くなることはない。", "B": "切迫流産は妊娠22週未満の概念で、妊娠34週の本例には当てはまらない。", "C": "前置胎盤は無痛性の性器出血が特徴で、本例は胎盤が子宮底部にあり位置も合わない。", "D": "絨毛膜羊膜炎では発熱と子宮の圧痛、破水を伴うが、本例は体温36.9°Cで感染徴候がない。"}'),
    ('114-E-31', '正答は C「9点」。

開眼は痛み刺激で開くのでE2、発語はうなり声のみで意味のある言葉がないためV2、運動は左上下肢が痛み刺激を払いのける(localizing)ためM5。合計9点となる。運動反応は左右で良いほうを採用する。

出典：厚生労働省ホームページ 第114回医師国家試験 E031',
     '{"A": "3点は開眼・発語・運動のすべてが最低(E1V1M1)で、深昏睡の状態である。", "B": "6点は運動反応をM2〜M3と誤って評価した場合の値である。", "D": "12点は呼びかけで開眼(E3)し発語も保たれる場合の値で、本例より軽い。", "E": "15点は完全に清明な状態である。"}'),
    ('114-E-32', '正答は E「喫煙量を戻すように指導する。」。

喫煙本数を減らしてイライラが強まっているのはニコチン離脱症状で、依存が形成されている証拠である。喫煙量を戻すよう指導するのは依存を維持させるだけで、支援として誤っている。禁煙治療につなぐべき場面である。

出典：厚生労働省ホームページ 第114回医師国家試験 E032',
     '{"A": "現在の喫煙状況とニコチン依存度の把握は支援の出発点である。", "B": "ニコチン依存が明らかで、禁煙外来での薬物療法を含む治療につなぐのは適切である。", "C": "健康被害を具体的に伝えることは行動変容の動機づけになる。", "D": "禁煙が本人にとってなぜ重要かを伝えることは短時間支援の要素である。"}'),
    ('114-E-33', '正答は E「腰椎穿刺」。

発熱・頭痛・頻回の嘔吐があり、jolt accentuation(頭を左右に振ると頭痛が増強する)が陽性である。項部硬直やKernig徴候がなくても髄膜炎は否定できず、髄液検査で確定させる必要がある。

出典：厚生労働省ホームページ 第114回医師国家試験 E033',
     '{"A": "排尿時痛も背部叩打痛もなく尿所見も正常で、尿路感染を疑う根拠がない。", "B": "下痢や腹痛の記載がなく、腸管感染を疑う状況ではない。", "C": "咽頭痛がなく咽頭炎を示す所見もない。", "D": "咳嗽がなく呼吸音も正常で、喀痰を採取する状況ではない。"}'),
    ('114-E-34', '正答は D「地域包括支援センターに相談するよう説明する。」。

本人が問題を認めず受診も拒んでいる段階で、まず必要なのは家族への支援と地域資源へのつなぎである。地域包括支援センターは高齢者と家族の総合相談窓口として、こうした事例の相談先になる。

出典：厚生労働省ホームページ 第114回医師国家試験 E034',
     '{"A": "差し迫った暴力や生命の危険がある状況の記載はなく、いきなり通報すると家族関係を壊しかねない。", "B": "本人が受診を拒んでいるため、紹介状を用意しても受診にはつながらない。", "C": "診療関係のない相手に医師が直接連絡して説得することは、本人の反発を招き逆効果になりやすい。", "E": "訪問診療は本人の同意なしには導入できない。"}'),
    ('114-E-37', '正答は A「仰臥位で診察する。」。

直腸肛門指診は左側臥位(Sims位)または砕石位で行う。仰臥位では肛門部の視診も指の挿入も行いにくく、患者の負担も大きい。

出典：厚生労働省ホームページ 第114回医師国家試験 E037',
     '{"B": "手袋の着用は感染対策として必須である。正しい。", "C": "痔核・裂肛・瘻孔などは視診で分かることが多く、指診の前に必ず観察する。正しい。", "D": "潤滑剤を用いてゆっくり挿入することで疼痛と粘膜損傷を避ける。正しい。", "E": "直腸内腔と肛門管の触診により腫瘤や狭窄、前立腺の性状を評価する。正しい。"}'),
    ('114-E-39', '正答は B「抗コリン薬」。

残尿240mLと著明な排出障害があり、国際前立腺症状スコアも重症域である。この状態で抗コリン薬を用いると排尿筋の収縮がさらに弱まり尿閉を招く危険が高い。過活動膀胱症状の治療は、まず排出障害を改善してから検討する。

出典：厚生労働省ホームページ 第114回医師国家試験 E039',
     '{"A": "α1遮断薬は前立腺平滑筋の緊張を下げて尿道抵抗を減らす、前立腺肥大症の第一選択薬である。", "C": "抗男性ホルモン薬は前立腺を縮小させる目的で用いられる。", "D": "5α還元酵素阻害薬は推定体積60mLと腫大した前立腺を縮小させ、長期的な進行を抑える。", "E": "タダラフィルは前立腺肥大症に伴う排尿障害に保険適応がある。"}'),
    ('114-E-40', '正答は A「輸液」。

アルコール性肝硬変を背景とした食道静脈瘤破裂による大量吐血で、血圧88/68mmHg、頻脈、冷汗と出血性ショックの状態にある。太い静脈路を確保して急速輸液を開始し、輸血の準備を進めることが最優先である。止血処置はその後である。

出典：厚生労働省ホームページ 第114回医師国家試験 E040',
     '{"B": "胃管は出血の程度を知る助けになるが、循環を立て直すことが先で、静脈瘤破裂では挿入自体が出血を助長しうる。", "C": "腹水の診断的穿刺は緊急性がなく、ショックの是正が優先される。", "D": "意識があり脈も触れており、AEDの適応はない。", "E": "尿量のモニタリングは必要だが、まず行うべき処置ではない。"}'),
    ('114-E-43', '正答は D「動悸時の脈のリズム」。

動悸は受診時には消えており、来院時の心電図は洞調律で手掛かりがない。発作中に本人が触れた脈が不整で112〜124/分だったという情報は、心房細動のような絶対性不整脈か、規則正しい発作性上室頻拍かを分ける決定的な材料になる。

出典：厚生労働省ホームページ 第114回医師国家試験 E043',
     '{"A": "心疾患の家族歴はなく、鑑別に寄与しない。", "B": "喫煙は心血管疾患の危険因子だが、どの不整脈かを絞る情報にはならない。", "C": "高尿酸血症は動悸の原因と直接は結びつかない。", "E": "来院時の心電図は症状が消えた後の記録で、発作中の調律を捉えていない。"}'),
    ('114-E-44', '正答は E「「心臓に悪影響を与えないためにはお酒の種類を変更すればよいです」」。

設問は「誤っている」説明を選ぶもの。心臓への影響を決めるのは摂取したアルコールの総量であって酒の種類ではない。種類を変えれば大丈夫という説明は誤りで、本例のようにビール3L/日を29年続けている場合は総量を減らすことが要る。

出典：厚生労働省ホームページ 第114回医師国家試験 E044',
     '{"A": "多量の飲酒が血圧を上げるのは正しく、本例も152/94mmHgと高い。", "B": "多量の飲酒はアルコール性心筋症を起こしうる。本例も左室拡大と駆出率45%への低下があり、正しい説明である。", "C": "多量の飲酒は心房細動を誘発しやすく（holiday heart syndrome）、正しい説明である。", "D": "アルコール性心筋症は禁酒により心機能の改善が期待でき、正しい説明である。"}'),
    ('114-E-45', '正答は D「「B型肝炎ワクチンの接種状況を教えてください」」。

報告書のうち基準を満たしていないのはB型肝炎だけで、HBs抗体4.8mIU/mLは基準の10mIU/mL未満である。病院実習では針刺しの危険があるため、まずワクチンの接種歴を確認し、未完了なら接種を進める。

出典：厚生労働省ホームページ 第114回医師国家試験 E045',
     '{"A": "IGRAは陰性で結核に感染しておらず、成人へのBCG接種の適応もない。", "B": "麻疹20.4、風疹10.0といずれも基準を満たしており、MRワクチンの再接種は要らない。", "C": "水痘の抗体価6.4は基準の4.0を満たしている。帯状疱疹になりやすいと言う根拠はない。", "E": "流行性耳下腺炎の抗体は陽性で基準を満たしており、診療への参加を制限する理由がない。"}'),
    ('114-E-46', '正答は A「HIV」。

針刺し事故で、内服薬による曝露後予防をできるだけ早く（できれば2時間以内）始める必要があるのはHIVである。抗HIV薬を原則4週間内服する。開始が遅れるほど効果が下がるため、検査結果を待たずに方針を決めることもある。

出典：厚生労働省ホームページ 第114回医師国家試験 E046',
     '{"B": "HBVの曝露後予防はB型肝炎ワクチンと抗HBsヒト免疫グロブリンで、内服薬ではない。", "C": "HCVには有効な曝露後予防がなく、経過を追って感染が成立した時点で治療する。", "D": "梅毒は針刺しでの感染がまれで、緊急の内服予防投与は行わない。", "E": "HTLV-1にも確立した曝露後予防はない。"}'),
    ('114-E-49', '正答は E「「なぜ検査を受けたくないのか、お聞かせください」その後、患者は下部内視鏡検査を受け早期大腸癌が認められた。加療のため4床室に入院した。治療に関する説明のため医師が病室を訪れると、患者はベッドを起こした状態で、そばの椅子に座っている夫と話していた。4床室は満床で、空いている椅子は見当たらない。」。

検査の拒否は、痛みへの不安、費用、家族の負担、以前の不快な経験など、背景がさまざまである。理由を聴かずに説得や中止に進むと、本当の障壁は解けない。まず開かれた質問で理由を尋ねるのが、この時点でふさわしい。

出典：厚生労働省ホームページ 第114回医師国家試験 E049',
     '{"A": "理由も聴かずに中止すれば、早期に治せる大腸癌を見逃すことになる。", "B": "何を不安に思っているか分からないまま安全性だけを断言しても、患者には届かない。", "C": "意思決定の主体は本人である。いきなり家族に判断を委ねる進め方は適切でない。", "D": "理解していないと決めつける言い方は患者を責めることになり、信頼関係を損なう。"}'),
    ('114-E-50', '正答は E「患者を車椅子に乗せ、夫と一緒に車椅子で別室に移動して話す。」。

癌の告知を含む病状説明は、他の患者に聞かれない場所で、本人を中心に、同席してほしい人と一緒に行う。4床室は満床でプライバシーが保てず、患者は車椅子で移動できるので、夫とともに別室へ移って話すのが望ましい。

出典：厚生労働省ホームページ 第114回医師国家試験 E050',
     '{"A": "本人を差し置いて家族にだけ説明するのは、本人の知る権利と意思決定を損なう。", "B": "立ったまま話すと患者を見下ろす姿勢になり、しかも同室の患者に話が聞こえてしまう。", "C": "患者のベッドの上に座るのは、私的な領域に立ち入る行為で適切でない。", "D": "座って目線を合わせる点はよいが、4床室のままではプライバシーが保てない。"}'),
    ('114-F-1', '正答は D「大腸菌が10 コロニー/mL 以下」。

水道水の水質基準では、大腸菌は「検出されないこと」と定められている。何コロニーまで許容という基準ではない。

出典：厚生労働省ホームページ 第114回医師国家試験 F001',
     '{"A": "濁度は2度以下と定められている。正しい。", "B": "味は異常でないことと定められている。正しい。", "C": "pH値は5.8以上8.6以下である。正しい。", "E": "一般細菌は1mLの検水で形成される集落数が100以下と定められている。正しい。"}'),
    ('114-F-2', '正答は B「司法解剖には遺族の承諾は必要ない。」。

司法解剖は犯罪との関連が疑われる場合に、刑事訴訟法に基づき裁判官の発する鑑定処分許可状によって行われる。遺族の承諾は必要としない。

出典：厚生労働省ホームページ 第114回医師国家試験 F002',
     '{"A": "死体検案は医師が行うものである。警察は検視を行う。", "C": "監察医制度のある地域では、行政解剖を遺族の承諾なく行うことができる。", "D": "医師法第20条ただし書きは死亡診断書の交付に関する規定であって、検案の要否を定めたものではない。診療中の傷病と異なる原因が疑われれば検案が必要である。", "E": "異状死体の届出義務を定めているのは医師法第21条であり、医療法ではない。"}'),
    ('114-F-4', '正答は D「経食道心エコー検査」。

経食道心エコーは探触子を食道内に置くため心臓との距離が近く、経胸壁心エコーでは捉えられない小さな疣贅や弁周囲膿瘍、人工弁の病変も描出できる。感染性心内膜炎を疑って経胸壁で所見がない場合も、経食道で確認する。

出典：厚生労働省ホームページ 第114回医師国家試験 F004',
     '{"A": "心臓MRIは心筋の性状評価には優れるが、可動する小さな疣贅の描出には向かない。", "B": "造影CTは塞栓や膿瘍の検索には有用だが、疣贅の検出感度はエコーに劣る。", "C": "経胸壁心エコーは第一に行う検査だが、感度は経食道に及ばない。", "E": "MIBG心筋シンチグラフィは心臓交感神経機能の評価に用いる検査である。"}'),
    ('114-F-6', '正答は A「強迫観念」。

自分でも「そんなことはない」と分かっているのに繰り返し頭に浮かんで離れないという訴えは、不合理性の認識(自我異和性)を伴う強迫観念である。

出典：厚生労働省ホームページ 第114回医師国家試験 F006',
     '{"B": "作為体験は自分の考えや行動が他人に操られているという自我障害で、統合失調症でみられる。", "C": "罪業妄想はうつ病でみられる微小妄想で、訂正不能である点が強迫観念と異なる。", "D": "滅裂思考は話のつながりが失われる思考形式の障害で、本例の訴えは筋が通っている。", "E": "妄想着想は根拠なく突然確信が生じるもので、不合理性の自覚を欠く。"}'),
    ('114-F-8', '正答は A「妊娠の1か月以上前」。

神経管は受精後およそ28日までに閉鎖するため、妊娠に気づいてから飲み始めたのでは間に合わない。妊娠の1か月以上前から葉酸400μg/日の摂取を始める。

出典：厚生労働省ホームページ 第114回医師国家試験 F008',
     '{"B": "妊娠10週ではすでに神経管の閉鎖が完了しており、予防の時期を過ぎている。", "C": "妊娠20週では遅すぎる。", "D": "妊娠30週では遅すぎる。", "E": "妊娠36週では遅すぎる。"}'),
    ('114-F-9', '正答は A「疼痛の緩和」。

転移性骨腫瘍に対する放射線治療の主目的は除痛(緩和)である。多くの症例で数週以内に疼痛が軽減し、鎮痛薬の減量につながる。

出典：厚生労働省ホームページ 第114回医師国家試験 F009',
     '{"B": "すでに全身に播種した病態であり、局所照射で根治は望めない。", "C": "放射線は照射野内に作用する局所治療で、遠隔転移を抑える効果はない。", "D": "照射後に骨の再石灰化が進むまでには数か月を要し、切迫骨折には手術による固定を優先する。", "E": "高カルシウム血症の是正にはビスホスホネートやデノスマブ、輸液を用いる。"}'),
    ('114-F-10', '正答は C「飲酒の害に関する知識の普及活動」。

一次予防は、病気そのものが起こらないようにする働きかけである。飲酒の害についての知識を広める活動はアルコール使用障害の発生を抑えるもので、一次予防にあたる。

出典：厚生労働省ホームページ 第114回医師国家試験 F010',
     '{"A": "就労移行支援は、発症後の社会復帰と再発防止を支える三次予防である。", "B": "病院での治療の促進は、既に発症した人への対応で一次予防ではない。", "D": "抗精神病薬による症状改善は治療そのもので、二次〜三次予防にあたる。", "E": "精神状態の把握は早期発見を目指すもので、二次予防にあたる。"}'),
    ('114-F-12', '正答は B「血清FSH」。

閉経に伴い卵巣からのエストロゲンとインヒビンの分泌が低下すると、負のフィードバックが外れて下垂体からのFSH分泌が増える。高齢女性でFSHが高値になるのはこのためである。

出典：厚生労働省ホームページ 第114回医師国家試験 F012',
     '{"A": "肺活量は加齢に伴い低下する。", "C": "血清アルブミンは加齢とともにやや低下する。", "D": "血清クレアチンキナーゼは筋量の減少に伴い低下する。", "E": "クレアチニンクリアランスは糸球体濾過量の生理的低下により減少する。"}'),
    ('114-F-13', '正答は D「被虐待児の一時保護を行う。」。

児童相談所は児童福祉法に基づき、虐待を受けた児童の一時保護を行う権限をもつ。保護者の同意がなくても所長の判断で実施できる。

出典：厚生労働省ホームページ 第114回医師国家試験 F013',
     '{"A": "設置主体は都道府県と指定都市などであり、国の機関ではない。", "B": "療育の指導は保健所の業務として法に定められている。", "C": "乳幼児健康診査の実施主体は市町村である。", "E": "所長が医師でなければならないという規定はない。"}'),
    ('114-F-14', '正答は B「医師の指示を受けて業務を行う。」。

訪問看護は主治医が交付する訪問看護指示書に基づいて提供される。看護師の判断だけで開始できるものではない。

出典：厚生労働省ホームページ 第114回医師国家試験 F014',
     '{"A": "訪問看護ステーションの開設主体は医療法人に限られず、営利法人や社会福祉法人なども可能である。", "C": "在宅人工呼吸器の管理は訪問看護の重要な業務に含まれる。", "D": "介護保険の訪問看護に原則週1回という回数制限はない。", "E": "介護保険が適用される場合の自己負担は原則1割で、所得により2〜3割となる。"}'),
    ('114-F-17', '正答は E「ピークフロー」。

ピークフロー(最大呼気流量)は気道の可逆的な狭窄を反映し、早朝に低下する日内変動(morning dip)を示す。変動が大きいことは喘息のコントロール不良を意味し、自己管理の指標として用いられる。

出典：厚生労働省ホームページ 第114回医師国家試験 F017',
     '{"A": "残気量は発作時に増加するが、日内変動の指標としては用いない。", "B": "肺活量は気道狭窄の影響を受けにくく、日内変動を示さない。", "C": "肺拡散能は肺胞毛細血管でのガス交換能を反映し、喘息では通常正常で日内変動もない。", "D": "1回換気量は呼吸パターンで変わるが、気道狭窄の日内変動を表す指標ではない。"}'),
    ('114-F-18', '正答は C「就寝時にベッド柵で囲む。」。

高齢者虐待防止法が定める養護者による虐待は、身体的虐待・介護等放棄・心理的虐待・性的虐待・経済的虐待の5類型である。転倒防止のためのベッド柵は安全確保の措置であり、この類型に該当しない。

出典：厚生労働省ホームページ 第114回医師国家試験 F018',
     '{"A": "必要な食事を与えないことは介護等放棄(ネグレクト)にあたる。", "B": "わいせつな行為は性的虐待にあたる。", "D": "排泄物を放置することは介護等放棄にあたる。", "E": "本人の財産を無断で処分することは経済的虐待にあたる。"}'),
    ('114-F-19', '正答は D「虚血性心疾患」。

高所得国では感染症や周産期の死亡が減り、非感染性疾患が死因の上位を占める。虚血性心疾患は高所得国の死因第1位である。

出典：厚生労働省ホームページ 第114回医師国家試験 F019',
     '{"A": "交通事故は低・中所得国で相対的に上位を占める。", "B": "下痢性疾患は衛生環境と関連し、低所得国で上位に入る。", "C": "下気道感染症は低所得国の主要死因である。", "E": "新生児仮死および出生時損傷は周産期医療の整備が不十分な低所得国で上位となる。"}'),
    ('114-F-20', '正答は E「周産期死亡とはすべての死産に早期新生児死亡を加えたものである。」。

周産期死亡は「妊娠22週以後の死産」に早期新生児死亡を加えたものと定義される。すべての死産を含むわけではない。死産の法的定義(妊娠12週以後)とは区切りが異なる点が問われている。

出典：厚生労働省ホームページ 第114回医師国家試験 F020',
     '{"A": "乳児死亡は生後1年未満の死亡で、正しい。", "B": "新生児死亡は生後4週(28日)未満の死亡で、正しい。", "C": "死産は死産の届出に関する規程により妊娠12週以後の死児の出産と定められている。正しい。", "D": "早期新生児死亡は生後1週(7日)未満の死亡で、正しい。"}'),
    ('114-F-21', '正答は D「転倒防止のための住宅改修に利用できる。」。

介護保険の居宅サービスには住宅改修費の支給が含まれ、手すりの設置や段差の解消など転倒防止のための改修に利用できる(支給限度基準額20万円)。

出典：厚生労働省ホームページ 第114回医師国家試験 F021',
     '{"A": "保険者は市町村および特別区である。", "B": "40歳以上65歳未満の第2号被保険者も、特定疾病による要介護状態であれば給付を受けられる。", "C": "介護給付費は国民医療費には含まれない。", "E": "自己負担割合は原則1割だが、一定以上の所得がある場合は2割または3割となる。"}'),
    ('114-F-22', '正答は E「流行性耳下腺炎」。

証明書にはHib、肺炎球菌、B型肝炎、DPT-IPV、BCG、麻疹風疹混合、水痘の記載がある。流行性耳下腺炎(ムンプス)ワクチンだけが記録になく、これは我が国では定期接種に含まれない任意接種であることが背景にある。

出典：厚生労働省ホームページ 第114回医師国家試験 F022',
     '{"A": "水痘はVaricella 1st・2ndとして接種済みである。", "B": "麻疹はMeasles, Rubella 1stとして接種済みである。", "C": "百日咳はDPT-IPVに含まれ、4回接種済みである。", "D": "肺炎球菌はPneumococcalとして4回接種済みである。"}'),
    ('114-F-24', '正答は C「国民医療費の総額は40 兆円を超えている。」。

平成28年度の国民医療費は約42.1兆円で、40兆円を超えている。国民所得に対する比率は約11%である。

出典：厚生労働省ホームページ 第114回医師国家試験 F024',
     '{"A": "予防接種や健康診断、正常分娩、美容整形など保険診療の対象外の費用は国民医療費に含まれない。", "B": "生活保護の医療扶助費は国民医療費に含まれる。", "D": "65歳以上の医療費は全体の約6割を占めるが、そのうち入院分に限れば全体の50%には達しない。", "E": "1日あたりの単価は高度医療を要する若年層の入院のほうが高く、75歳以上の入院が最高というわけではない。"}'),
    ('114-F-37', '正答は A「抗凝固薬の投与」。

75歳・高血圧という脳梗塞の危険因子をもつ心房細動で、CHADS2スコアは2点となる。自覚症状がなくても心原性脳塞栓症の予防が最優先で、抗凝固薬(直接経口抗凝固薬またはワルファリン)を開始する。

出典：厚生労働省ホームページ 第114回医師国家試験 F037',
     '{"B": "t-PAは急性期脳梗塞に対する血栓溶解療法で、脳梗塞を発症していない本例に適応はない。", "C": "徐脈や房室ブロックはなく、ペースメーカーの適応がない。", "D": "無症状で心拍数も許容範囲であり、除細動を急ぐ理由がない。行うとしても抗凝固を先行させる必要がある。", "E": "アブレーションは症状が強く薬物治療で抑えられない例に検討するもので、まず行う対応ではない。"}'),
    ('114-F-38', '正答は E「「夜間の決めた時間に起こして排尿させましょう」」。

夜間に決まった時刻に起こして排尿させる方法は、睡眠を妨げるうえ夜尿の改善につながらないことが分かっており、現在は勧められていない。

出典：厚生労働省ホームページ 第114回医師国家試験 F038',
     '{"A": "就寝前に膀胱を空にしておくことは基本的な生活指導で、適切である。", "B": "冷えは膀胱容量を小さくするため、保温は生活指導として適切である。", "C": "夕方以降の水分を控え、日中に多めに摂らせるのは適切な指導である。", "D": "叱責は子どもの自尊心を傷つけ改善にもつながらないため、叱らないよう伝えるのは適切である。"}'),
    ('114-F-39', '正答は D「臓器障害の全身管理が可能な医療施設に緊急に転院させる。」。

クレゾールはフェノール系の化合物で、皮膚から吸収されて肝障害・腎障害・溶血・メトヘモグロビン血症・中枢神経抑制をきたす。下半身の広範囲に曝露しており、局所の創処置だけでは足りない。全身管理のできる施設へ緊急に搬送する。

出典：厚生労働省ホームページ 第114回医師国家試験 F039',
     '{"A": "経皮吸収による全身毒性が起こりうるため、処置を終えて帰すことはできない。", "B": "翌日まで待つ間に肝腎障害や溶血が進行する危険がある。", "C": "鎮痛だけを行って帰宅させると全身毒性を見逃す。", "E": "問題は感染ではなく化学物質の全身毒性である。"}'),
    ('114-F-40', '正答は C「染色体検査」。

低身長に翼状頸と外反肘を伴っており、Turner症候群(45,X など)を考える。確定には染色体検査(核型分析)を行う。

出典：厚生労働省ホームページ 第114回医師国家試験 F040',
     '{"A": "成長ホルモン分泌の評価は低身長の精査に含まれるが、基礎疾患そのものの診断にはならない。", "B": "Turner症候群は特定の遺伝子変異ではなくX染色体の数的・構造的異常によるため、核型分析が必要である。", "D": "手根骨エックス線は骨年齢の評価に用いるもので、原因診断にはならない。", "E": "エストラジオールは性腺機能低下を示すが、その原因を特定できない。"}'),
    ('114-F-41', '正答は C「任意入院」。

患者自身が症状を苦痛と感じ、入院しての治療を希望している。本人の同意に基づく任意入院が適切である。精神科入院は本人の同意による任意入院が原則である。

出典：厚生労働省ホームページ 第114回医師国家試験 F041',
     '{"A": "応急入院は急速を要し家族等の同意も得られない場合に72時間を限度として行うもので、本人が同意している本例には当たらない。", "B": "自由入院という入院形式は精神保健福祉法に定められていない。", "D": "医療保護入院は本人の同意が得られない場合に家族等の同意で行うもので、本人が希望している状況では選ばない。", "E": "緊急措置入院は自傷他害のおそれが著しく急を要する場合の形式である。"}'),
    ('114-F-42', '正答は E「本日の抗TNF-α 抗体の自己注射をしないよう指導する。」。

抗TNF-α抗体は感染症を増悪させ重症化させるため、発熱など感染徴候があるときは投与を見合わせる。関節症状は落ち着いており、まず本日の自己注射を中止するよう指導する。

出典：厚生労働省ホームページ 第114回医師国家試験 F042',
     '{"A": "鼻汁と発熱のみで細菌感染を示す所見に乏しく、経過をみる段階で抗菌薬を投与する根拠がない。", "B": "ステロイドパルス療法の適応となる病態ではなく、免疫抑制をさらに強めることになる。", "C": "関節の腫脹・圧痛はなく抗リウマチ薬を追加する理由がない。感染時に免疫抑制を強めるのは危険である。", "D": "同様に、感染徴候があるときにメトトレキサートを増量すべきではない。"}'),
    ('114-F-44', '正答は A「起立試験」。

朝起きられない、起立時の気分不良と眼前暗黒感、午前中に症状が強いという訴えは起立性調節障害に典型的である。新起立試験(能動起立試験)で臥位から立位への血圧・心拍の反応をみて診断する。

出典：厚生労働省ホームページ 第114回医師国家試験 F044',
     '{"B": "視野の異常を示す所見はなく、視野検査の適応がない。", "C": "意識消失や痙攣はなく、てんかんを疑う状況ではない。", "D": "回転性めまいや眼振はなく、末梢前庭機能の検査は不要である。", "E": "平衡機能そのものの異常を示す所見はない。"}'),
    ('114-F-46', '正答は C「喉頭軟化症」。

出生直後から吸気性喘鳴があり、成長とともに安静時にも目立つようになっている。RSウイルスは陰性で胸部エックス線も正常であり、喉頭軟化症を考える。乳児の吸気性喘鳴の原因として最も多く、多くは1〜2歳までに自然軽快する。

出典：厚生労働省ホームページ 第114回医師国家試験 F046',
     '{"A": "心音は正常で体重増加も良好であり、心不全を示す所見がない。", "B": "喘息では呼気性の喘鳴となり、2か月児で診断することはない。", "D": "RSウイルス迅速検査が陰性で、出生直後からの喘鳴を急性疾患では説明できない。", "E": "クループは犬吠様咳嗽を伴って急性に発症するもので、経過が異なる。"}'),
    ('114-F-48', '正答は A「睡眠薬の処方」。

産業医は労働者の健康管理と就業上の措置に関する意見を担う立場で、診療行為である処方は行わない。治療が必要であれば主治医や専門医療機関につなぐ。

出典：厚生労働省ホームページ 第114回医師国家試験 F048',
     '{"B": "飲酒は睡眠障害の重要な要因で、評価は産業医の役割に含まれる。", "C": "リラクセーションなどセルフケアの指導は保健指導として適切である。", "D": "作業環境や職場のあり方への助言は産業医の中心的な役割である。", "E": "勤務状態を踏まえた生活指導は就業上の配慮につながる産業医の役割である。"}'),
    ('114-F-52', '正答は E「「座ってうつむいて鼻を強くつまんでください」」。

鼻出血の大半はキーゼルバッハ部位からで、座って前かがみになり、鼻翼を指で強くつまんで10〜15分圧迫すれば止まることが多い。前かがみにするのは、血液が咽頭へ流れ込むのを防ぐためである。

出典：厚生労働省ホームページ 第114回医師国家試験 F052',
     '{"A": "温めると血管が広がって出血が増える。冷やすほうが理にかなう。", "B": "仰向けでは血液が咽頭へ流れ込み、誤嚥や嘔吐の原因になる。", "C": "血圧は120/70mmHgで、この場で降圧薬を追加する適応がない。", "D": "血液を飲み込むと胃を刺激して嘔吐を招き、出血量も分からなくなる。吐き出させる。"}'),
    ('114-F-53', '正答は B「交換輸血」。

総ビリルビン29.5mg/dLと著明な高ビリルビン血症があり、傾眠、吸啜反射とMoro反射の減弱、筋緊張低下と急性ビリルビン脳症の徴候が出ている。光線療法では間に合わず、直ちに交換輸血を行ってビリルビンを除去する。

出典：厚生労働省ホームページ 第114回医師国家試験 F053',
     '{"A": "血漿交換は新生児高ビリルビン血症の標準治療ではない。", "C": "アルブミン投与は遊離ビリルビンを結合させる補助的手段で、これ単独では脳症の進行を止められない。", "D": "すでに神経症状が出ており、光線療法の強化では間に合わない。", "E": "免疫グロブリンは血液型不適合による溶血の抑制に用いる補助療法で、脳症が出現した時点の主治療にはならない。"}'),
    ('114-F-54', '正答は C「環軸椎亜脱臼」。

瞼裂斜上、内眼角贅皮、鼻根部平坦、巨舌、筋緊張低下はDown症候群の所見である。環軸椎の不安定性(亜脱臼)を10〜20%に合併し、頸髄症をきたしうるため、頸椎の評価と運動時の注意が長期管理上の要点になる。

出典：厚生労働省ホームページ 第114回医師国家試験 F054',
     '{"A": "大動脈解離のリスクが高いのはMarfan症候群である。", "B": "潰瘍性大腸炎の合併が特に多いという関連はない。", "D": "神経芽細胞腫との関連はない。Down症候群で増えるのは一過性骨髄異常増殖症と急性巨核芽球性白血病である。", "E": "Down症候群で問題となるのは甲状腺機能低下症であり、副甲状腺機能亢進症ではない。"}'),
    ('115-A-1', '正答は E「血栓性微小血管障害」。

強皮症腎クリーゼでは腎の細小動脈に内膜の増殖と狭窄が生じ、血栓性微小血管障害をきたす。急激な血圧上昇、腎機能の急速な悪化、微小血管障害性溶血性貧血と血小板減少を伴う。ACE阻害薬が治療の中心である。

出典：厚生労働省ホームページ 第115回医師国家試験 A001',
     '{"A": "大動脈瘤は強皮症腎に特徴的な所見ではない。", "B": "仙腸関節炎は脊椎関節炎(強直性脊椎炎など)の所見である。", "C": "サーモンピンク疹は成人Still病に特徴的な皮疹である。", "D": "強皮症腎の蛋白尿は軽度にとどまることが多く、ネフローゼ症候群を呈するのは典型的でない。"}'),
    ('115-A-2', '正答は A「Douglas窩」。

Douglas窩(直腸子宮窩・直腸膀胱窩)は仰臥位で腹腔内の最も低い位置にあたり、骨盤内の手術後に貯留する滲出液や出血を効率よく排出できる。

出典：厚生労働省ホームページ 第115回医師国家試験 A002',
     '{"B": "Morrison窩は右肝下面で、上腹部の手術後に用いる。", "C": "Winslow孔は網囊への入口で、膵や胆道の手術で用いる。", "D": "左横隔膜下は脾摘後などのドレナージ部位である。", "E": "右横隔膜下は肝切除後などのドレナージ部位である。"}'),
    ('115-A-3', '正答は C「平均赤血球ヘモグロビン濃度は正常範囲である。」。

腎性貧血はエリスロポエチンの産生低下による貧血で、赤血球の大きさもヘモグロビン濃度も正常な正球性正色素性貧血を示す。したがって平均赤血球ヘモグロビン濃度(MCHC)は正常範囲にある。

出典：厚生労働省ホームページ 第115回医師国家試験 A003',
     '{"A": "エリスロポエチンが不足しているため骨髄の反応は乏しく、網赤血球は増加しない。", "B": "溶血ではないので間接ビリルビンは上昇しない。", "D": "貧血が明らかになるのはおおむねG3b期(eGFR 45未満)以降で、G2期から低下するわけではない。", "E": "エリスロポエチンは貧血の程度に見合った上昇を示さないだけで、測定感度以下になるわけではない。"}'),
    ('115-A-4', '正答は D「PD〈programmed cell death〉-1」。

切除不能の悪性黒色腫には免疫チェックポイント阻害薬が用いられ、ニボルマブやペムブロリズマブはT細胞上のPD-1を標的とする。PD-1とそのリガンドの結合を遮ることで、腫瘍が免疫から逃れる仕組みを解除する。

出典：厚生労働省ホームページ 第115回医師国家試験 A004',
     '{"A": "IL-17を標的とする抗体薬は乾癬などに用いる。", "B": "EGFR抗体は大腸癌や頭頸部癌に用いる。", "C": "IL-6受容体抗体(トシリズマブ)は関節リウマチなどに用いる。", "E": "VEGF抗体(ベバシズマブ)は大腸癌や肺癌に用いる血管新生阻害薬である。"}'),
    ('115-A-5', '正答は A「髄様癌」。

甲状腺髄様癌は傍濾胞細胞(C細胞)由来の腫瘍で、カルシトニンを産生する。CEAも上昇し、多発性内分泌腫瘍症2型の部分症として発症することがあるためRET遺伝子の検索も行う。

出典：厚生労働省ホームページ 第115回医師国家試験 A005',
     '{"B": "乳頭癌は濾胞上皮由来で、サイログロブリンが指標となる。", "C": "濾胞癌も濾胞上皮由来である。", "D": "亜急性甲状腺炎は炎症性疾患で、破壊性の甲状腺中毒症を示す。", "E": "腺腫様甲状腺腫は過形成性の病変でホルモン産生の異常を伴わない。"}'),
    ('115-A-7', '正答は C「内鼠径ヘルニア」。

Hesselbach三角(下腹壁動静脈の内側、腹直筋外側縁、鼠径靱帯に囲まれた領域)から後腹壁を押し出すように脱出するのが内鼠径ヘルニア(直接鼠径ヘルニア)である。高齢男性の腹壁脆弱化に伴って生じる。

出典：厚生労働省ホームページ 第115回医師国家試験 A007',
     '{"A": "大腿ヘルニアは鼠径靱帯の下、大腿輪から脱出する。女性に多く嵌頓しやすい。", "B": "外鼠径ヘルニアは下腹壁動静脈の外側にある内鼠径輪から鼠径管に入る。", "D": "閉鎖孔ヘルニアは骨盤の閉鎖孔から脱出し、やせた高齢女性に多い。", "E": "Bochdalek孔ヘルニアは横隔膜後外側の欠損による先天性横隔膜ヘルニアである。"}'),
    ('115-A-8', '正答は E「α-フェトプロテイン〈AFP〉値」。

α-フェトプロテインは肝細胞癌の腫瘍マーカーであり、肝臓がどれだけ働けるか(肝予備能)とは無関係である。切除可能な肝容積の判断には使えない。

出典：厚生労働省ホームページ 第115回医師国家試験 A008',
     '{"A": "血清アルブミンは肝の蛋白合成能を反映し、Child-Pugh分類の項目である。", "B": "ICG15分停滞率は色素の肝取り込み・排泄能を反映し、切除可能量の決定に用いる。", "C": "総ビリルビンは肝の排泄能を反映し、Child-Pugh分類の項目である。", "D": "プロトロンビン時間は凝固因子の合成能を反映し、Child-Pugh分類の項目である。"}'),
    ('115-A-9', '正答は E「血栓性血小板減少性紫斑病」。

血栓性血小板減少性紫斑病では微小血管内に血小板血栓ができ、そこを通過する赤血球が機械的に破砕される。末梢血に破砕赤血球(schistocyte)が出現するのが特徴で、ADAMTS13活性の著減による。

出典：厚生労働省ホームページ 第115回医師国家試験 A009',
     '{"A": "異常ヘモグロビン症では赤血球の変形や不安定化が起こるが、機械的な破砕によるものではない。", "B": "遺伝性球状赤血球症は膜蛋白の異常による球状化と脾での捕捉が本態である。", "C": "自己免疫性溶血性貧血は自己抗体による血管外溶血が主体である。", "D": "発作性寒冷血色素尿症はDonath-Landsteiner抗体による補体介在性の血管内溶血で、破砕赤血球は伴わない。"}'),
    ('115-A-10', '正答は E「大動脈およびその分枝に病変をきたしやすい。」。

高安動脈炎は大動脈とその主要分枝を侵す大型血管炎で、上肢の脈拍減弱・血圧の左右差、血管雑音、めまいなどを呈する。我が国では若年女性に多い。

出典：厚生労働省ホームページ 第115回医師国家試験 A010',
     '{"A": "好発は10〜30歳代の女性で、中年男性ではない。", "B": "喫煙との関連が強いのは閉塞性血栓血管炎(Buerger病)である。", "C": "水晶体偏位はMarfan症候群やホモシスチン尿症の所見である。", "D": "浅側頭動脈の炎症は巨細胞性動脈炎の特徴で、高齢者に発症する。"}'),
    ('115-A-16', '正答は E「抗D人免疫グロブリン投与」。

RhD陰性の母からRhD陽性児が生まれており、分娩時に児の赤血球が母体に入って感作される危険がある。分娩後72時間以内に抗D人免疫グロブリンを投与し、次回妊娠での血液型不適合を防ぐ。

出典：厚生労働省ホームページ 第115回医師国家試験 A016',
     '{"A": "投与しなければ感作が成立し、次回妊娠で胎児溶血性疾患を起こしうる。", "B": "アルブミン投与は感作の予防に無関係である。", "C": "ハプトグロビンは血管内溶血時に用いるもので、この場面の適応ではない。", "D": "副腎皮質ステロイドは感作の予防にならない。"}'),
    ('115-A-17', '正答は E「コルポスコピィ検査」。

細胞診で異常を指摘された場合の次の段階は、コルポスコピィ(腟拡大鏡診)で子宮頸部を観察し、疑わしい部位から狙い組織診を行うことである。肉眼で異常がなくてもこの手順を踏む。

出典：厚生労働省ホームページ 第115回医師国家試験 A017',
     '{"A": "22歳で組織診も行っていない段階での子宮全摘は、妊孕性を失わせる過剰な治療である。", "B": "HPVそのものを排除する抗ウイルス薬は存在しない。", "C": "円錐切除は組織診で高度異形成以上が確認されてから検討する。", "D": "腫瘍マーカーは早期の子宮頸部病変の診断に役立たない。"}'),
    ('115-A-23', '正答は A「睡眠中は消失する。」。

抗精神病薬の長期投与により生じた遅発性ジスキネジアである。口をもぐもぐ動かす、舌を突き出すといった口部・舌の不随意運動が特徴で、他の多くの不随意運動と同様に睡眠中は消失する。

出典：厚生労働省ホームページ 第115回医師国家試験 A023',
     '{"B": "抗Parkinson病薬(抗コリン薬)はむしろ遅発性ジスキネジアを悪化させる。", "C": "メトクロプラミドなど抗精神病薬以外のドパミン受容体遮断薬でも生じるため、特異的とは言えない。", "D": "注意を向けると一時的に抑制できることが多く、増悪するわけではない。", "E": "片側の上下肢を投げ出すような大きな不随意運動はバリズムで、遅発性ジスキネジアの典型ではない。"}'),
    ('115-A-24', '正答は D「睡眠薬による前向健忘」。

睡眠薬を服用して就床した後の行動を本人がまったく覚えていないが、周囲からは普通に振る舞っていたと見える。ベンゾジアゼピン系や非ベンゾジアゼピン系の睡眠薬による前向健忘で、夜間の摂食や外出といった複雑な行動を伴うことがある。

出典：厚生労働省ホームページ 第115回医師国家試験 A024',
     '{"A": "夜間せん妄では意識が混濁し行動もまとまらない。本例は普通に歌い飲食したと友人が述べている。", "B": "一過性全健忘は数時間の記銘障害が一度だけ生じるもので、2か月にわたり反復する経過に合わない。", "C": "全生活史健忘は解離性の健忘で、自分が誰かを含む生活史全体を失う。", "E": "REM睡眠行動障害は夢の内容に伴う暴力的な動きが特徴で、外出やカラオケのような複雑で社会的な行動はとらない。"}'),
    ('115-A-25', '正答は A「経過観察」。

RSウイルスによる細気管支炎だが、SpO2は98%で陥没呼吸もなく、哺乳量も保たれている。軽症であり、水分摂取と呼吸状態の観察を続ける経過観察でよい。悪化の徴候を保護者に伝えることが重要である。

出典：厚生労働省ホームページ 第115回医師国家試験 A025',
     '{"B": "ウイルス感染であり、細菌感染を示す所見もないため抗菌薬の適応がない。", "C": "RSウイルスに対する抗ウイルス薬は一般診療では用いない。", "D": "免疫グロブリンの適応となる病態ではない。", "E": "パリビズマブはハイリスク児の発症予防に用いる薬剤で、発症後の治療薬ではない。"}'),
    ('115-A-31', '正答は B「加齢黄斑変性」。

高齢者で線がゆがんで見える変視症と中心視力の低下があり、両眼性で左右差を伴っている。加齢黄斑変性を第一に考える。滲出型では脈絡膜新生血管が黄斑部に生じ、抗VEGF薬の硝子体内注射が治療となる。

出典：厚生労働省ホームページ 第115回医師国家試験 A031',
     '{"A": "視神経炎は若年に多く、眼球運動時痛と中心暗点、相対的瞳孔求心路障害を伴う。", "C": "特発性黄斑円孔も変視症をきたすが、中高年女性の片眼性に生じることが多い。", "D": "網膜中心静脈閉塞症は突然の視力低下と広範な眼底出血をきたす。", "E": "網膜動脈分枝閉塞症は突然の視野欠損として発症する。"}'),
    ('115-A-34', '正答は B「急性動脈閉塞」。

心房細動があり、突然発症した片側上肢の疼痛・しびれに加え、蒼白と橈骨動脈拍動の微弱を認める。心内血栓が上肢動脈に飛んだ急性動脈閉塞で、疼痛・蒼白・脈拍消失・知覚異常・運動麻痺の5徴を確認する。時間との勝負で、血行再建を急ぐ。

出典：厚生労働省ホームページ 第115回医師国家試験 A034',
     '{"A": "意識障害や片麻痺、構音障害など中枢神経症状がなく、脳梗塞では上肢の蒼白と脈拍微弱を説明できない。", "C": "手根管症候群は正中神経領域のしびれが緩徐に進むもので、突然発症せず皮膚色や脈拍にも影響しない。", "D": "胸郭出口症候群は上肢挙上など特定の姿勢で誘発される慢性の症候群である。", "E": "頸椎椎間板ヘルニアは神経根症状をきたすが、皮膚の蒼白や動脈拍動の消失は生じない。"}'),
    ('115-A-35', '正答は E「自宅での経過観察の指示」。

マムシ咬傷では腫脹が数日かけて中枢側へ進み、横紋筋融解による急性腎障害やDICを合併しうる。症状が軽くみえても入院して経過を観察する必要があり、自宅で様子をみるよう指示するのは誤りである。

出典：厚生労働省ホームページ 第115回医師国家試験 A035',
     '{"A": "蛇の口腔内細菌による創部感染を予防するため抗菌薬を投与する。正しい。", "B": "受傷直後であれば吸引器で局所から毒を吸い出すことが試みられる。正しい。", "C": "横紋筋融解による腎障害を防ぐため十分な輸液を行う。正しい。", "D": "腫脹が進行する例では抗マムシウマ血清の投与を検討する。正しい。"}'),
    ('115-A-36', '正答は C「膀胱瘻を造設する。」。

会陰部打撲後に外尿道口からの出血と尿閉があり、尿道損傷を考える。この状況で尿道カテーテルを挿入すると損傷を完全断裂に広げてしまうため禁忌で、恥骨上から膀胱瘻を造設して尿路を確保する。

出典：厚生労働省ホームページ 第115回医師国家試験 A036',
     '{"A": "クレアチニン0.7mg/dLと腎機能は正常で、透析の適応がない。", "B": "閉塞は下部尿路にあり、腎瘻では尿道損傷の管理にならない。", "D": "尿管の損傷ではないため、尿管ステントの適応がない。", "E": "血圧は保たれており、動脈塞栓術を要する大量出血ではない。"}'),
    ('115-A-38', '正答は C「アドレナリン筋注」。

給食(エビ・小麦)の後の運動中に喘鳴と全身の膨疹が出現しており、食物依存性運動誘発アナフィラキシーである。皮膚と呼吸器の2臓器に症状が及んでおり、直ちにアドレナリン0.01mg/kgを大腿前外側に筋注する。

出典：厚生労働省ホームページ 第115回医師国家試験 A038',
     '{"A": "意識は清明で会話もできており、この時点で気道確保の手技を優先する状況ではない。アドレナリンが先である。", "B": "吸入ステロイドは効果発現が遅く、アナフィラキシーの急性期治療にならない。", "D": "抗ヒスタミン薬は皮膚症状にしか効かず、気道や循環の症状を改善しない。", "E": "重炭酸ナトリウムの適応となる病態ではない。"}'),
    ('115-A-39', '正答は E「Guillain-Barré症候群」。

上気道感染の1週後に外眼筋麻痺、運動失調、腱反射消失の三徴が亜急性に進行しており、Guillain-Barré症候群の亜型であるFisher症候群である。抗GQ1b抗体が高率に陽性となる。

出典：厚生労働省ホームページ 第115回医師国家試験 A039',
     '{"A": "重症筋無力症は症状に日内変動と易疲労性があり、腱反射は保たれる。", "B": "多発性硬化症は中枢の脱髄で、腱反射は亢進し感覚障害を伴うことが多い。", "C": "進行性核上性麻痺は高齢者に緩徐進行し、垂直方向の注視麻痺と易転倒性を示す。10日の経過に合わない。", "D": "筋萎縮性側索硬化症は筋萎縮と線維束性収縮が主体で、外眼筋は末期まで保たれる。"}'),
    ('115-A-41', '正答は E「右心カテーテル検査」。

労作時息切れにII音肺動脈成分の亢進、右室肥大、肺動脈主幹部の拡張があり、肺血栓塞栓や肺実質病変は否定されている。肺動脈性肺高血圧症を疑うが、確定には右心カテーテル検査で平均肺動脈圧と肺血管抵抗、肺動脈楔入圧を実測する必要がある。心エコーの推定値だけでは診断できない。

出典：厚生労働省ホームページ 第115回医師国家試験 A041',
     '{"A": "胸部MRIは右室機能の評価には使えるが、肺動脈圧を実測できない。", "B": "FDG-PETは悪性腫瘍の検索に用いるもので、この病態の診断には寄与しない。", "C": "喀痰細胞診は肺癌を疑うときの検査で、肺野に異常のない本例には当たらない。", "D": "冠動脈造影は虚血性心疾患の評価で、労作時息切れの原因としては否定的である。"}'),
    ('115-A-42', '正答は D「浸透圧性下剤投与」。

兎糞状便で排便回数が少なく、強くいきむ必要があり残便感が続く慢性便秘症である。器質的疾患は内視鏡で除外されており、生活指導に加えて浸透圧性下剤(酸化マグネシウムなど)から始める。

出典：厚生労働省ホームページ 第115回医師国家試験 A042',
     '{"A": "身体活動は腸蠕動を促すため、安静はむしろ便秘を悪化させる。", "B": "感染性の病態ではなく抗菌薬の適応がない。", "C": "浣腸を習慣化すると直腸の排便反射が鈍り、自力での排便が難しくなる。", "E": "食物繊維は便量を増やして排便を促すため、制限するのは逆である。"}'),
    ('115-A-43', '正答は A「血小板輸血」。

寛解導入療法中で血小板1.0万/μLまで低下し、下腿に紫斑という出血症状が出ている。予防的輸血の閾値を下回ったうえ出血徴候もあり、血小板輸血の適応である。

出典：厚生労働省ホームページ 第115回医師国家試験 A043',
     '{"B": "PT-INR 1.0、APTT 29.2秒とほぼ正常で、凝固因子の補充を要する状態ではない。", "C": "Hb8.8g/dLは化学療法中としては許容範囲で、緊急の赤血球輸血の適応にならない。", "D": "エリスロポエチン製剤は化学療法後の貧血に用いる薬剤ではなく、効果発現も遅い。", "E": "トロンボポエチン受容体作動薬は免疫性血小板減少症に用いるもので、化学療法による骨髄抑制の急性期には使わない。"}'),
    ('115-A-44', '正答は B「抗SS-A抗体」。

眼の乾燥と口腔乾燥に多関節痛と白血球減少を伴っており、Sjögren症候群を考える。診断の裏づけとして抗SS-A抗体(抗Ro抗体)を測定する。関節リウマチとの合併もあるため注意する。

出典：厚生労働省ホームページ 第115回医師国家試験 A044',
     '{"A": "PR3-ANCAは多発血管炎性肉芽腫症で陽性となる。", "C": "抗MDA5抗体は皮膚筋炎、とくに急速進行性間質性肺炎を伴う型でみられる。", "D": "抗dsDNA抗体は全身性エリテマトーデスに特異的で、腎炎の活動性を反映する。", "E": "抗アクアポリン4抗体は視神経脊髄炎スペクトラム障害の抗体である。"}'),
    ('115-A-46', '正答は C「気管支喘息の合併が多い。」。

気管支肺胞洗浄液の好酸球37%と肺胞隔壁への好酸球浸潤があり、自然軽快と再燃を繰り返す遊走性の陰影という経過から慢性好酸球性肺炎である。半数程度に気管支喘息を合併する。

出典：厚生労働省ホームページ 第115回医師国家試験 A046',
     '{"A": "中年女性に多い疾患で、高齢者に多いわけではない。", "B": "非喫煙者に多い。喫煙が発症に関わるのは急性好酸球性肺炎のほうである。", "D": "副腎皮質ステロイドが著効するのが特徴で、抵抗性ではない。ただし減量で再燃しやすい。", "E": "末梢血好酸球も増加することが多い。"}'),
    ('115-A-47', '正答は D「機能性ディスペプシア」。

食後のもたれ感と早期飽満感が半年続き、内視鏡・腹部超音波とも異常がなくH. pylori抗体も陰性である。体重減少もなく、機能性ディスペプシアの食後愁訴症候群と考える。

出典：厚生労働省ホームページ 第115回医師国家試験 A047',
     '{"A": "逆流性食道炎は胸やけが主症状で、内視鏡で粘膜傷害を認める。本例は胸やけがなく内視鏡も正常である。", "B": "過敏性腸症候群は排便に関連する腹痛と便通異常が診断に必要である。", "C": "食道裂孔ヘルニアは内視鏡で確認できる形態異常で、本例では指摘されていない。", "E": "非びらん性胃食道逆流症は内視鏡で異常がない逆流症だが、胸やけや呑酸が主症状である。本例に逆流症状はない。"}'),
    ('115-A-48', '正答は C「大動脈縮窄症」。

上肢のSpO2が96%、下肢が88%と下半身のみ酸素化が低い分離性チアノーゼで、皮膚色も下半身が暗い。動脈管を介して肺動脈血が下行大動脈へ流れていることを意味し、大動脈縮窄症など動脈管に依存する左心系閉塞性病変を考える。

出典：厚生労働省ホームページ 第115回医師国家試験 A048',
     '{"A": "Fallot四徴症では右左短絡血が全身に回るため、上下肢に差のない全身性チアノーゼとなる。", "B": "三尖弁閉鎖症も全身性のチアノーゼを示す。", "D": "心室中隔欠損症は左右短絡でチアノーゼをきたさない。", "E": "完全大血管転位症では動脈管を通る血流の向きが逆になり、上肢のほうが低く下肢が高い逆分離性チアノーゼを示すことがある。"}'),
    ('115-A-51', '正答は D「4」。

高齢者の高血圧でもサイアザイド系利尿薬は第一選択薬の一つで、カルシウム拮抗薬・ARB・ACE阻害薬と並ぶ。「第一選択にできません」という4は誤りである。

出典：厚生労働省ホームページ 第115回医師国家試験 A051',
     '{"A": "高齢者でも減塩は降圧に有効だが、極端な制限は食欲低下から低栄養を招くため配慮が要る。正しい。", "B": "加齢に伴う圧受容器反射の低下により、起立時の血圧維持が弱くなる。正しい。", "C": "食後に内臓血流が増えることで血圧が下がる食後低血圧は高齢者で問題になる。正しい。", "E": "ACE阻害薬とARBの併用は腎機能悪化と高カリウム血症を増やし、予後の改善も示されていないため推奨されない。正しい。"}'),
    ('115-A-52', '正答は B「経過観察」。

紙巻たばこの誤飲では、ニコチンの吸収が遅く胃内で嘔吐を誘発することが多いため、乾いた葉を少量食べただけで3時間無症状なら中毒症状が出る可能性は低い。経過観察でよい。

出典：厚生労働省ホームページ 第115回医師国家試験 A052',
     '{"A": "胃洗浄は誤嚥のリスクがあり、無症状の少量誤飲には適応がない。", "C": "下剤で排泄を促す必要はない。", "D": "活性炭はニコチンを吸着するが、無症状で時間が経過した本例には不要である。", "E": "脱水も循環不全もなく、輸液の適応がない。"}'),
    ('115-A-53', '正答は C「明け方の血糖値の測定」。

朝食前の血糖が3日とも最も高く、夜間に発汗を伴って目覚めることがある。夜間低血糖の反跳による朝の高血糖(Somogyi効果)か、単純な暁現象かで対応が正反対になるため、まず明け方(午前3時前後)の血糖を測って区別する。

出典：厚生労働省ホームページ 第115回医師国家試験 A053',
     '{"A": "夕食後の運動は夜間低血糖をさらに助長しうる。", "B": "夕食の糖質を減らすことも夜間低血糖を悪化させる方向に働く。", "D": "インスリン療法中の2型糖尿病にスルホニル尿素薬を追加すれば低血糖の危険が増す。", "E": "夕食前の超速効型インスリンを増やすと夜間低血糖がさらに強まる。原因を確かめる前に増量してはならない。"}'),
    ('115-A-54', '正答は B「チック」。

突発的で非律動的な瞬目や顔しかめ、首振りが数か月にわたり増減し、睡眠中には消失し、短時間なら自分で抑えられる。いずれもチックの特徴である。運動チックと音声チックが1年以上続けばTourette症候群を考える。

出典：厚生労働省ホームページ 第115回医師国家試験 A054',
     '{"A": "振戦は律動的な振動で、抑制できず睡眠中に消失する点は共通だが動作の性質が異なる。", "C": "バリズムは片側の四肢を投げ出すような大振りの不随意運動である。", "D": "舞踏運動は流れるように次々と部位が移る不随意運動で、意図的に抑制できない。", "E": "アテトーゼはゆっくりとねじれるような持続的な運動である。"}'),
    ('115-A-56', '正答は E「精巣」。

25歳男性でhCGとAFPがともに上昇しており、非セミノーマ型の胚細胞腫瘍を考える。この年代の胚細胞腫瘍の原発は精巣が最も多く、腰背部痛は後腹膜リンパ節転移、咳嗽は肺転移で説明できる。触診と陰囊超音波で精巣を確認する。

出典：厚生労働省ホームページ 第115回医師国家試験 A056',
     '{"A": "甲状腺癌はサイログロブリンやカルシトニンが指標で、hCG・AFPは上昇しない。", "B": "肝細胞癌でもAFPは上昇するが、25歳で背景肝疾患がなく、hCG上昇も説明できない。", "C": "膵癌の腫瘍マーカーはCA19-9で、本例は基準内である。", "D": "大腸癌のマーカーはCEAで、本例は基準内である。"}'),
    ('115-A-57', '正答は D「2,500mL」。

心拍数120/分・収縮期血圧80mmHgでショックインデックスは1.5となる。産科危機的出血ではショックインデックス1.0でおよそ1,000〜1,500mL、1.5でおよそ2,500mLの出血に相当するとされる。

出典：厚生労働省ホームページ 第115回医師国家試験 A057',
     '{"A": "500mLはショックインデックス1.0未満に相当し、この循環動態には合わない。", "B": "1,000mLはショックインデックス1.0前後の目安である。", "C": "1,500mLでもショックインデックスは1.0強にとどまる。", "E": "4,000mLではさらに高度のショックとなり、意識レベルも保たれない。"}'),
    ('115-A-61', '正答は D「網膜色素変性」。

顔面の三叉神経第1枝領域のポートワイン母斑と、同側大脳の軟膜血管腫、そして無熱性けいれんからSturge-Weber症候群である。網膜色素変性は含まれず、眼合併症としては緑内障や脈絡膜血管腫がみられる。

出典：厚生労働省ホームページ 第115回医師国家試験 A061',
     '{"A": "血管腫のある大脳半球の障害により、対側の片麻痺を生じる。", "B": "難治性てんかんの反復により精神運動発達の遅れをきたす。", "C": "軟膜血管腫による皮質の慢性虚血でてんかんを発症し、しばしば難治性となる。", "E": "皮質に沿った軌道様(tram-track)の石灰化が特徴的な画像所見である。"}'),
    ('115-A-62', '正答は E「⑤」。

双胎の分娩様式を決めるうえで最も重要なのは先進児の胎位である。先進児が頭位でなければ経腟分娩は選択できず、帝王切開となる。本例は先進児が骨盤位であり、この情報が判断を左右する。

出典：厚生労働省ホームページ 第115回医師国家試験 A062',
     '{"A": "高年初産であることは分娩管理上の注意点だが、それ自体が経腟分娩の可否を決めない。", "B": "不妊治療歴も分娩様式の決定因子ではない。", "C": "卵巣囊胞摘出術の既往は子宮に及ぶ手術ではなく、子宮破裂のリスクにならない。", "D": "推定胎児体重の差は小さく、いずれも経腟分娩が可能な範囲である。"}'),
    ('115-A-63', '正答は A「術後出血」。

骨盤底に留置したドレーンからの排液の性状と量を見ることで、術後出血を早期に発見できる。血性排液の増加は再開腹の判断につながる。

出典：厚生労働省ホームページ 第115回医師国家試験 A063',
     '{"B": "腸管癒着はドレーンの排液では分からない。むしろドレーン自体が癒着の原因になりうる。", "C": "神経因性膀胱は広汎子宮全摘術に伴う骨盤神経損傷で起こるが、排尿機能の評価でしか分からない。", "D": "癌の再発は画像や腫瘍マーカーで追うもので、術直後のドレーンでは検出できない。", "E": "深部静脈血栓症は下肢の腫脹やDダイマー、超音波で評価する。"}'),
    ('115-B-1', '正答は A「飲酒 — 食道癌」。

飲酒は食道扁平上皮癌の確立した危険因子で、喫煙との相乗効果がある。アセトアルデヒド脱水素酵素の活性が低い人ではとくにリスクが高い。

出典：厚生労働省ホームページ 第115回医師国家試験 B001',
     '{"B": "睡眠時無呼吸症候群の危険因子は肥満であり、低体重ではない。", "C": "フレイルは体重減少・筋力低下を特徴とし、体重増加は危険因子でない。", "D": "食物繊維の摂取は糖尿病の発症を抑える方向に働く。", "E": "n-3系多価不飽和脂肪酸は虚血性心疾患のリスクを下げる方向に働く。"}'),
    ('115-B-2', '正答は E「疾患や診療に対する患者の考えを把握する。」。

解釈モデルとは、患者が自分の症状を何によるものと考え、何を心配し、どうしてほしいと思っているかという理解の枠組みである。これを聞くことで説明の焦点が定まり、患者の納得と治療への参加が得られる。

出典：厚生労働省ホームページ 第115回医師国家試験 B002',
     '{"A": "患者誤認の防止は氏名と生年月日など2つ以上の識別子で確認するもので、解釈モデルとは別である。", "B": "訴えの信憑性を疑うための手段ではない。", "C": "精神疾患のスクリーニングを目的とするものではない。", "D": "医療機関への不満を聞き出すことが目的ではない。"}'),
    ('115-B-3', '正答は B「守秘義務」。

医師の守秘義務を定めているのは刑法第134条(秘密漏示罪)であり、医師法ではない。医師法には応召義務、臨床研修、処方箋交付義務、診療録記載・保存義務などが規定されている。

出典：厚生労働省ホームページ 第115回医師国家試験 B003',
     '{"A": "応召義務は医師法第19条第1項に規定されている。", "C": "臨床研修は医師法第16条の2に規定されている。", "D": "処方箋の交付義務は医師法第22条に規定されている。", "E": "診療録の記載と5年間の保存は医師法第24条に規定されている。"}'),
    ('115-B-4', '正答は E「後腹膜線維症」。

後腹膜線維症はIgG4関連疾患や薬剤性などで生じる病態で、関節リウマチの関節外症状には含まれない。

出典：厚生労働省ホームページ 第115回医師国家試験 B004',
     '{"A": "皮下結節(リウマトイド結節)は肘頭など伸側に生じる代表的な関節外症状である。", "B": "リウマトイド血管炎により皮膚潰瘍を生じることがある。", "C": "心外膜炎は関節リウマチの心病変として知られる。", "D": "間質性肺炎は関節リウマチの肺病変として頻度が高く、予後を左右する。"}'),
    ('115-B-5', '正答は A「患者の権利に基づく。」。

セカンドオピニオンは、患者が自分の治療について他の医師の意見も聞いたうえで選択するという自己決定権に基づくものである。主治医は求めに応じて診療情報を提供する。

出典：厚生労働省ホームページ 第115回医師国家試験 B005',
     '{"B": "セカンドオピニオン外来は原則として保険給付の対象外で、自費診療となる。", "C": "悪性腫瘍に限らず、あらゆる疾患・治療方針が対象になる。", "D": "目的は治療方針の理解と納得であって、主治医を替えることではない。", "E": "患者の権利に基づく求めであり、担当医が拒否することはできない。"}'),
    ('115-B-7', '正答は D「家族が同居していることが必要である。」。

在宅医療は独居でも受けられる。訪問診療・訪問看護・訪問介護を組み合わせ、必要に応じて介護保険サービスや看取りの体制を整える。家族の同居を要件とすると、独居高齢者が在宅療養を選べなくなる。

出典：厚生労働省ホームページ 第115回医師国家試験 B007',
     '{"A": "末期の悪性腫瘍は40〜64歳でも第2号被保険者として介護保険の特定疾病に該当し、申請できる。", "B": "療養の場を決めるのは本人であり、同意が前提となる。", "C": "在宅でも輸液や麻薬の持続投与を行うことができる。", "E": "在宅でのリハビリテーションも訪問リハビリや通所リハビリとして提供される。"}'),
    ('115-B-10', '正答は B「食塩」。

ナトリウムは摂取したほぼ全量が尿中に排泄されるため、24時間蓄尿の尿中ナトリウム量から食塩摂取量を推定できる。減塩指導の効果判定に用いられる。

出典：厚生労働省ホームページ 第115回医師国家試験 B010',
     '{"A": "脂質は尿中に排泄されないため蓄尿では評価できない。", "C": "食物繊維は消化されず糞便に排泄されるため、尿では分からない。", "D": "エネルギー摂取量は尿から推定できない。", "E": "脂溶性ビタミンは体内に蓄積され尿中排泄が乏しい。"}'),
    ('115-B-11', '正答は C「問題を具体化せず意見を求める。」。

コンサルテーションでは、何を相談したいのかを具体的な問いの形にして伝えることが要である。問題を具体化せずに漠然と意見を求めると、相手は何に答えればよいか分からず、時間も浪費する。

出典：厚生労働省ホームページ 第115回医師国家試験 B011',
     '{"A": "要点を絞って簡潔に伝えることは適切である。", "B": "継続的に相談できる関係を保つことは診療の質につながる。", "D": "病歴・所見・検査結果を整理してから相談するのは適切である。", "E": "緊急度に応じて連絡の手段とタイミングを選ぶのは適切である。"}'),
    ('115-B-13', '正答は A「嗅覚低下」。

嗅覚の低下は食欲や食事の楽しみに影響しうるが、嚥下の運動そのものには関与しないため嚥下障害の原因にはならない。

出典：厚生労働省ホームページ 第115回医師国家試験 B013',
     '{"B": "歯牙の欠損は咀嚼を妨げ、食塊形成の不良から嚥下を難しくする。", "C": "舌の運動低下は食塊を咽頭へ送り込む口腔期の障害となる。", "D": "唾液分泌の低下は食塊がまとまらず、咽頭への送り込みを妨げる。", "E": "咽頭収縮力の低下は咽頭残留と誤嚥の直接の原因になる。"}'),
    ('115-B-14', '正答は D「はさみ歩行」。

両下肢の痙縮では股関節内転筋の緊張が強まり、歩行時に膝が内側で交差する。この歩容をはさみ歩行(scissors gait)と呼び、痙直型脳性麻痺や痙性対麻痺でみられる。

出典：厚生労働省ホームページ 第115回医師国家試験 B014',
     '{"A": "開脚歩行は小脳性運動失調で、体幹の動揺を補うため足を広げて歩く。", "B": "動揺歩行は近位筋の筋力低下(筋ジストロフィーなど)で骨盤が左右に揺れる歩き方である。", "C": "小刻み歩行はParkinson病でみられ、歩幅が小さく前傾姿勢をとる。", "E": "分回し歩行は片麻痺で麻痺側下肢を外側に回して振り出す歩き方である。"}'),
    ('115-B-15', '正答は E「マイコプラズマ肺炎」。

3週未満の急性咳嗽の大半は感染性で、かぜ症候群や肺炎などが原因となる。マイコプラズマ肺炎はその代表である。

出典：厚生労働省ホームページ 第115回医師国家試験 B015',
     '{"A": "COPDによる咳嗽は8週を超える慢性咳嗽の原因である。", "B": "咳喘息は遷延性から慢性咳嗽の代表的な原因である。", "C": "胃食道逆流症も慢性咳嗽の原因として重要である。", "D": "副鼻腔気管支症候群は慢性咳嗽の原因である。"}'),
    ('115-B-16', '正答は E「本人の意思が確認できない場合、家族等による推定意思が尊重される。」。

本人の意思が確認できない場合は、家族等が本人の価値観や以前の言動から推定する意思を尊重し、それも分からなければ本人にとって何が最善かを医療・ケアチームと家族等で慎重に話し合って決める。

出典：厚生労働省ホームページ 第115回医師国家試験 B016',
     '{"A": "癌に限らず、非癌の慢性疾患や老衰なども対象である。", "B": "意思は状態や状況の変化で変わりうるため、繰り返し話し合うことが求められる。", "C": "積極的安楽死は我が国では認められておらず、選択肢にならない。", "D": "生命維持を希望する患者も当然に対象で、その意思が尊重される。"}'),
    ('115-B-17', '正答は A「小脳梗塞 — 同名半盲」。

同名半盲は視交叉より後方の視路(後頭葉や視放線)の障害で生じる。小脳は視覚路に関与しないため、小脳梗塞で同名半盲は起こらない。小脳梗塞では失調性歩行、眼振、めまい、嘔吐がみられる。

出典：厚生労働省ホームページ 第115回医師国家試験 B017',
     '{"B": "聴神経腫瘍では後迷路性難聴として、聴力低下の程度に不釣り合いな語音明瞭度の低下を示す。", "C": "突発性難聴では耳鳴やめまいを伴うことが多い。", "D": "パニック障害では動悸・発汗・呼吸困難などの自律神経症状が発作性に生じる。", "E": "良性発作性頭位めまい症は寝返りや起き上がりなど頭位変換で誘発される回転性めまいが特徴である。"}'),
    ('115-B-18', '正答は C「行為によって不安は緩和される。」。

強迫行為は、強迫観念による不安を打ち消すために行われる。行為によって不安は一時的に和らぐが、繰り返すほど強迫観念が強化されるという悪循環に陥る。

出典：厚生労働省ホームページ 第115回医師国家試験 B018',
     '{"A": "意識は保たれており、行為中の記憶はある。", "B": "時間帯による一定の日内変動は特徴でない。", "D": "患者自身も行為が不合理だと分かっており(自我異和性)、そこが妄想と異なる点である。", "E": "外から命令が吹き込まれるのは幻聴や作為体験で、統合失調症の症状である。"}'),
    ('115-B-19', '正答は A「僧帽弁狭窄症」。

僧帽弁狭窄症では左房から左室への流入が妨げられるため、左室に入る血液量すなわち前負荷が低下する。左室はむしろ小さく保たれ、うっ血は左房から肺静脈側に生じる。

出典：厚生労働省ホームページ 第115回医師国家試験 B019',
     '{"B": "大動脈弁狭窄症は左室の後負荷が増える病態で、前負荷は低下しない。", "C": "三尖弁閉鎖不全症は右心系の容量負荷で、左室前負荷には直接影響しない。", "D": "僧帽弁閉鎖不全症では逆流した血液が左房を経て左室に戻るため前負荷が増える。", "E": "大動脈弁閉鎖不全症では拡張期に大動脈から左室へ逆流し、前負荷が増える。"}'),
    ('115-B-21', '正答は D「児童相談所」。

児童虐待防止法により、虐待を受けたと思われる児童を発見した者は児童相談所または市町村に通告する義務を負う。生命の危険がない段階でも通告する。

出典：厚生労働省ホームページ 第115回医師国家試験 B021',
     '{"A": "警察への通報は生命に差し迫った危険がある場合で、通常の通告先ではない。", "B": "学校は通告先として法に定められていない。", "C": "保健所は感染症や難病を扱う機関で、虐待通告の窓口ではない。", "E": "市町村保健センターは健康づくりの拠点で、通告先として第一に挙がるものではない。"}'),
    ('115-B-22', '正答は B「胆囊癌」。

胆囊は肝臓に付着しているため、呼吸に伴う横隔膜の動きで肝臓とともに上下する。腫大した胆囊や胆囊癌は、吸気時に触知しやすく呼吸性に移動する。

出典：厚生労働省ホームページ 第115回医師国家試験 B022',
     '{"A": "膵囊胞は後腹膜にあり、呼吸性の移動を示さない。", "C": "腹部大動脈瘤は後腹膜で拍動性に触れるが、呼吸で移動しない。", "D": "腹膜偽粘液腫は腹腔内にゼリー状の粘液が充満する病態で、限局した可動性腫瘤としては触れない。", "E": "Krukenberg腫瘍は骨盤内の卵巣転移で、呼吸性の移動はない。"}'),
    ('115-B-23', '正答は D「喀痰のGram染色を確認してから開始する。」。

喀痰のGram染色は数分で結果が得られ、起炎菌の推定と適切な狭域抗菌薬の選択に直結する。培養結果を待たずに治療を始められるという点で、抗菌薬適正使用の要になる。

出典：厚生労働省ホームページ 第115回医師国家試験 B023',
     '{"A": "体温の高さは起炎菌の種類を示さない。", "B": "白血球数も起炎菌の推定には使えない。", "C": "培養の最終結果は数日かかり、待っていては治療が遅れる。", "E": "CRPは炎症の指標にすぎず、正常化を治療終了の基準にすると不要に長期投与になる。"}'),
    ('115-B-24', '正答は D「蛋白制限」。

蛋白制限はアンモニアの産生を抑えるため、肝性脳症の誘因ではなく治療の一部である。ただし過度の制限は筋肉量を落としてかえって不利になるため、現在は極端な制限は行わない。

出典：厚生労働省ホームページ 第115回医師国家試験 B024',
     '{"A": "感染は異化を亢進させアンモニア産生を増やす。誘因となる。", "B": "脱水は腎前性の腎障害と電解質異常を招き、脳症を誘発する。", "C": "便秘は腸内でのアンモニア産生と吸収を増やす。誘因となる。", "E": "消化管出血では血液が腸内で分解されて大量のアンモニアが生じる。誘因となる。"}'),
    ('115-B-25', '正答は B「FSH」。

54歳女性で発汗発作(hot flush)、疲労感、動悸が反復しており更年期症状である。卵巣機能の低下によりエストロゲンとインヒビンが減り、負のフィードバックが外れてFSHが上昇する。

出典：厚生労働省ホームページ 第115回医師国家試験 B025',
     '{"A": "GHは加齢とともに分泌が低下する。", "C": "オキシトシンは分娩や授乳に関わるホルモンで、この症候とは無関係である。", "D": "プロラクチンの上昇は乳汁漏出や無月経をきたすが、発汗発作の原因ではない。", "E": "プロゲステロンは黄体から分泌されるため、閉経期にはむしろ低下する。"}'),
    ('115-B-26', '正答は D「4」。

ノロウイルスはエンベロープを持たないためアルコールが効きにくい。診察後は石けんと流水による手洗いで物理的に洗い流す必要があり、聴診器をそのままポケットにしまうのは誤りである。使用のたびに次亜塩素酸ナトリウムなどで清拭する。

出典：厚生労働省ホームページ 第115回医師国家試験 B026',
     '{"A": "診察前の手指衛生は必要で、この時点でのアルコール消毒は誤りではない。", "B": "接触予防策としてガウンの着用は正しい。", "C": "手袋の着用も接触予防策として正しい。", "E": "ノロウイルスにはアルコールが効きにくいため、石けんと流水での手洗いは正しい。"}'),
    ('115-B-27', '正答は E「Master二階段負荷試験」。

心房細動があり一過性の意識消失を繰り返している。徐脈性不整脈(徐脈頻脈症候群)による失神が疑われ、運動負荷は失神や重篤な不整脈を誘発する危険がある。日常の活動度も5分の杖歩行が限界で、負荷試験に耐えられない。

出典：厚生労働省ホームページ 第115回医師国家試験 B027',
     '{"A": "貧血や電解質異常、腎機能の評価は失神の鑑別に必要である。", "B": "弁膜症や心機能、心内血栓の評価に有用である。", "C": "発作性の徐脈や頻脈を捉えるためHolter心電図は適切である。", "D": "12誘導心電図は不整脈や伝導障害の評価に必須である。"}'),
    ('115-B-28', '正答は B「胸骨圧迫」。

心電図モニターに心拍数20/分の波形が出ているが、意識も脈もない。心静止でも心室細動でもない無脈性電気活動(PEA)であり、除細動の適応はない。直ちに胸骨圧迫を再開し、可逆的な原因の検索と是正を進める。

出典：厚生労働省ホームページ 第115回医師国家試験 B028',
     '{"A": "気道確保は重要だが、胸骨圧迫の中断を最小にすることが優先される。", "C": "PEAと心静止は電気ショックの適応外である。", "D": "アトロピンは現在の心停止アルゴリズムでは推奨されていない。", "E": "リドカインは難治性の心室細動・無脈性心室頻拍に用いるもので、PEAには適応がない。"}'),
    ('115-B-30', '正答は C「3」。

2歳児の呼吸数48/分は明らかな頻呼吸で、陥没呼吸を伴っており呼吸仕事量の増大を示す。SpO2が保たれていても代償の限界に近づいている可能性があり、緊急性を示す所見として最も重要である。

出典：厚生労働省ホームページ 第115回医師国家試験 B030',
     '{"A": "体温37.8°Cは軽度の発熱で、緊急性を示すものではない。", "B": "2歳の脈拍120/分は正常範囲である。", "D": "SpO2 98%は保たれており、この値自体は緊急性を示さない。", "E": "毛細血管再充満時間1秒は正常で、循環は保たれている。"}'),
    ('115-B-31', '正答は C「抗菌薬の投与」。

白血球54,300で芽球95%、貧血と血小板減少を伴っており急性白血病である。発熱性好中球減少症に近い状態で肺炎を併発しており、生命に直結するのは感染症のコントロールである。血液培養と喀痰培養を採ったうえで、直ちに広域抗菌薬を開始する。

出典：厚生労働省ホームページ 第115回医師国家試験 B031',
     '{"A": "高血圧症は既往としてあるが、この場面で優先される問題ではない。", "B": "血小板3.2万は出血徴候がなければ直ちに介入を要する値ではない。", "D": "起炎菌は未確定で、肺炎球菌と決めつける根拠がない。", "E": "芽球を伴う白血球増多は診断の手がかりだが、対応そのものではない。"}'),
    ('115-B-34', '正答は A「1」。

開放型質問は「はい・いいえ」や特定の語で答えられない、患者が自由に語れる問いである。「症状について詳しく教えてください」がこれにあたる。

出典：厚生労働省ホームページ 第115回医師国家試験 B034',
     '{"B": "「熱や鼻汁はありますか」は有無を問う閉鎖型質問である。", "C": "「周囲に同じような症状の人はいますか」も有無を問う閉鎖型質問である。", "D": "「アレルギーはありますか」も閉鎖型質問である。", "E": "「ご両親にアレルギーはありますか」も閉鎖型質問である。"}'),
    ('115-B-35', '正答は C「腹部超音波検査」。

直接ビリルビン優位の黄疸にトランスアミナーゼ上昇を伴っている。胆道の閉塞(総胆管結石や腫瘍)をまず除外する必要があり、非侵襲的で胆管拡張と胆石の描出に優れる腹部超音波検査を最初に行う。

出典：厚生労働省ホームページ 第115回医師国家試験 B035',
     '{"A": "造影CTは超音波で胆管拡張を確認したうえで、原因検索として次に行う。", "B": "Coombs試験は溶血性貧血の検査だが、貧血がなく間接ビリルビン優位でもない。", "D": "腫瘍マーカーは閉塞の有無を確認した後の検討事項である。", "E": "薬剤性肝障害も鑑別に挙がるが、まず閉塞性黄疸を除外するのが順序である。"}'),
    ('115-B-37', '正答は A「患者を左側臥位として挿入する。」。

経鼻胃管は座位または半座位で挿入するのが基本で、左側臥位にする必要はない。臥位では誤嚥の危険が増し、嚥下の協力も得にくい。

出典：厚生労働省ホームページ 第115回医師国家試験 B037',
     '{"B": "胃内容物を吸引してpHを確認することは、胃内留置の確認法の一つである。", "C": "初回投与は異常が起きたときに対応しやすい日中に行う。", "D": "気泡音の聴診は補助的な確認法として行われる(単独では不十分)。", "E": "エックス線撮影による位置確認が最も確実で、初回留置時には必須である。"}'),
    ('115-B-41', '正答は C「64%」。

検査後の確率は「事前オッズ×尤度比」で求める。検査前確率80%の事前オッズは0.8/0.2＝4。陰性尤度比は(1−感度)/特異度＝0.4/0.9≒0.44なので、事後オッズは4×0.44≒1.78、事後確率は1.78/(1+1.78)≒0.64で64%になる。感度60%の検査が陰性でも、これだけ疑わしい患者では6割以上が心筋梗塞であり、陰性を理由に帰宅させてはいけない。

出典：厚生労働省ホームページ 第115回医師国家試験 B041',
     '{"A": "検査前確率をそのまま答えた値で、陰性という結果をまったく反映していない。", "B": "0.8×0.9のように確率と特異度を直接掛けた形の値で、尤度比を使う手順になっていない。", "D": "0.6×0.9のように感度と特異度を掛けた形の値で、事前オッズを経由していない。", "E": "確率が求まらないときの「半々」に相当する値で、与えられた数値から導けない。"}'),
    ('115-B-42', '正答は B「「今までの説明で分からないことはありますか」」。

説明したことが伝わったかを確かめるには、患者の側に分からない点が残っていないかを開かれた形で尋ねる。「今までの説明で分からないことはありますか」はそのための問いで、理解の確認にあたる。

出典：厚生労働省ホームページ 第115回医師国家試験 B042',
     '{"A": "治療法の希望を聞くのは、患者の意向・価値観の確認であって理解の確認ではない。", "C": "家族へ話すかどうかは、情報を共有する範囲の確認である。", "D": "病気の原因をどう考えているかを聞くのは、患者自身の解釈を知るための問いである。", "E": "この病院で受けるかを尋ねるのは、方針への同意の確認である。"}'),
    ('115-B-43', '正答は B「低くなる。」。

3項目のいずれにも当てはまらない。頭痛は徐々に出現して増悪しておらず、これまでにもっと強い頭痛を経験している。当てはまる項目がないときの尤度比は0.1で、1より小さいため、事後オッズは事前オッズより小さくなり、重篤な原因である確率は低くなる。

出典：厚生労働省ホームページ 第115回医師国家試験 B043',
     '{"A": "尤度比が1より小さいので、確率は上がらない。", "C": "尤度比がちょうど1のときだけ変化しない。0.1なので確率は動く。", "D": "事前オッズに尤度比を掛ければ求まるので、計算できないわけではない。", "E": "事後確率の値は事前オッズによって変わるが、尤度比が1未満である以上「低くなる」という向きは変わらない。"}'),
    ('115-B-44', '正答は C「光過敏を伴う。」。

きらきらした点が見えた後に頭痛と悪心が続いており、前兆（閃輝暗点）を伴う片頭痛である。片頭痛では光や音に過敏になり、暗く静かな場所で休むと楽になる。

出典：厚生労働省ホームページ 第115回医師国家試験 B044',
     '{"A": "片頭痛は女性に多い。本例も母が頭痛持ちで、家族内発症が多いことも特徴である。", "B": "思春期から40歳代に多く、加齢とともにむしろ減っていく。", "D": "軽度から中等度の発作にはNSAIDが有効で、効かないときにトリプタンを用いる。", "E": "体を動かすと拍動性の痛みが強まるのが片頭痛の特徴で、軽減はしない。"}'),
    ('115-C-1', '正答は C「各都道府県内の複数の市町村を含む。」。

二次医療圏は、一般的な入院医療を提供する単位として設定され、複数の市町村をまとめた地域に相当する。地域医療構想の構想区域も原則としてこれに一致する。

出典：厚生労働省ホームページ 第115回医師国家試験 C001',
     '{"A": "中学校区は日常生活圏域の目安で、医療圏の区分ではない。", "B": "市町村単位は一次医療圏に相当する。", "D": "都道府県単位は三次医療圏に相当する。", "E": "複数の都道府県にまたがる医療圏は設定されていない。"}'),
    ('115-C-2', '正答は A「労働者に悪影響がみられないと判断する濃度」。

許容濃度は、労働者が1日8時間・週40時間程度その濃度の環境で働いても、ほとんどの人に健康上の悪影響がみられないと判断される濃度である。日本産業衛生学会が勧告している。

出典：厚生労働省ホームページ 第115回医師国家試験 C002',
     '{"B": "国が望ましいとして定めるのは環境基準である。", "C": "食品添加物について定められるのは一日摂取許容量(ADI)である。", "D": "作業場の管理区分を決めるのに用いるのは管理濃度である。", "E": "毒性が認められない最大量は無毒性量(NOAEL)であり、許容濃度とは概念が異なる。"}'),
    ('115-C-3', '正答は A「発疹が消失するまで」。

学校保健安全法施行規則では、風疹の出席停止期間を「発疹が消失するまで」と定めている。

出典：厚生労働省ホームページ 第115回医師国家試験 C003',
     '{"B": "「解熱した後3日を経過するまで」は麻疹の基準である。", "C": "「発症した後5日を経過し、かつ解熱した後2日を経過するまで」はインフルエンザの基準である。", "D": "「すべての発疹が痂皮化するまで」は水痘の基準である。", "E": "「医師が感染のおそれがないと認めるまで」は結核や髄膜炎菌性髄膜炎など第一種の感染症の扱いである。"}'),
    ('115-C-4', '正答は A「鼻カニューラ — 1L/分」。

鼻カニューラは1〜6L/分の範囲で用いる。1L/分でおよそ24%の吸入酸素濃度が得られ、低流量投与に適する。

出典：厚生労働省ホームページ 第115回医師国家試験 C004',
     '{"B": "7L/分では鼻粘膜の乾燥と疼痛が強く、鼻カニューラの上限(6L/分)を超えている。", "C": "フェイスマスクは5L/分未満だとマスク内に呼気が滞留して二酸化炭素を再呼吸する。", "D": "3L/分も同様に再呼吸を招くため不適切である。", "E": "リザーバー付マスクは6L/分以上、通常10L/分程度で用いる。4L/分ではリザーバーが虚脱する。"}'),
    ('115-C-5', '正答は E「何がつらくてそう思うのか尋ねる。」。

「死にたい」という訴えには、痛み、孤独、家族への負担感など具体的な苦痛が背景にある。まずその内容を尋ね、受け止めることが出発点になる。そのうえで緩和ケアや精神科的支援につなぐ。

出典：厚生労働省ホームページ 第115回医師国家試験 C005',
     '{"A": "背景を確かめずに薬物療法から入るのは適切でない。", "B": "診療の拒否は許されない。", "C": "自殺を思いとどまらせようと責めるのは、患者をさらに追い詰める。", "D": "専門家への紹介は必要になりうるが、まず担当医が話を聴かずに他へ回すのは適切でない。"}'),
    ('115-C-6', '正答は B「指定感染症による入院」。

感染症法に基づく入院勧告・入院措置による入院の医療費は公費で負担される。1類・2類感染症、新型インフルエンザ等感染症、指定感染症が対象で、まん延防止のために国が負担する仕組みである。

出典：厚生労働省ホームページ 第115回医師国家試験 C006',
     '{"A": "結核の一般医療は医療費の95%が公費で、5%は自己負担となる。", "C": "精神障害者の措置入院は公費負担だが、所得に応じた費用徴収がある。", "D": "小児慢性特定疾病の医療費助成には所得に応じた自己負担がある。", "E": "予防接種による健康被害への対応は救済給付制度であり、医療費の公費負担の枠組みとは異なる。"}'),
    ('115-C-7', '正答は E「人工呼吸器の管理は看護師が在宅で行う診療補助行為に含まれる。」。

在宅人工呼吸器の管理は、主治医の指示のもとで看護師が行う診療の補助に含まれる。回路の点検、加温加湿、吸引、アラーム対応などを担う。

出典：厚生労働省ホームページ 第115回医師国家試験 C007',
     '{"A": "医療保険・介護保険いずれでも自己負担が生じる。", "B": "訪問看護は主治医の交付する訪問看護指示書に基づいて行う。", "C": "要介護認定を受けている場合は介護保険が優先される。ただし厚生労働大臣が定める疾病等では医療保険が適用される。", "D": "要介護認定を受けていなくても、医療保険による訪問看護を利用できる。"}'),
    ('115-C-11', '正答は E「人工妊娠中絶」。

人工妊娠中絶は母体保護法第14条により、都道府県の医師会が指定する医師(指定医師)でなければ行えない。

出典：厚生労働省ホームページ 第115回医師国家試験 C011',
     '{"A": "人工授精に母体保護法上の資格要件はない。", "B": "体外受精も母体保護法の対象ではなく、学会の登録施設要件による。", "C": "不妊手術は母体保護法第3条に定めがあるが、条文上は「医師」が行えるとされ、指定医師に限定されていない。", "D": "出生前診断に母体保護法指定医の資格は要求されない。"}'),
    ('115-C-12', '正答は A「アラニンは糖新生に利用される。」。

筋で生じたアラニンは肝へ運ばれてピルビン酸に変換され、糖新生の材料になる(グルコース-アラニン回路)。飢餓時の血糖維持に働く。

出典：厚生労働省ホームページ 第115回医師国家試験 C012',
     '{"B": "胆汁酸はコレステロールから合成される。中性脂肪からではない。", "C": "非代償性肝硬変では分岐鎖アミノ酸が減り芳香族アミノ酸が増えるため、Fischer比は低下する。", "D": "アンモニアは尿素回路(オルニチン回路)で尿素に変換される。TCAサイクルではない。", "E": "グルクロン酸抱合を受けることで水溶性となり、胆汁中に排泄される。"}'),
    ('115-C-15', '正答は E「新型インフルエンザは、診断後直ちに都道府県知事に届け出る。」。

新型インフルエンザ等感染症は、診断した医師が直ちに最寄りの保健所長を経由して都道府県知事へ届け出る。

出典：厚生労働省ホームページ 第115回医師国家試験 C015',
     '{"A": "検疫感染症は1類感染症、新型インフルエンザ等感染症、マラリア・デング熱などが指定されており、結核は含まれない。", "B": "コレラは3類感染症で、医療費の公費負担はない。", "C": "髄膜炎菌ワクチンは任意接種で、定期接種の対象ではない。", "D": "マラリアは4類感染症で、入院勧告の対象ではない。"}'),
    ('115-C-16', '正答は C「生物学的製剤の使用 — HIV感染」。

生物学的製剤は遺伝子組換え技術で製造される抗体などで、ヒト血液を原料としないためHIV感染の原因にはならない。感染症の再活性化(結核・B型肝炎)には注意を要する。

出典：厚生労働省ホームページ 第115回医師国家試験 C016',
     '{"A": "頻回輸血では鉄が体内に蓄積し、続発性ヘモクロマトーシスをきたす。", "B": "腓骨頭部を副木で圧迫すると腓骨神経麻痺(下垂足)を生じる。", "D": "ヒト乾燥硬膜の移植によるCreutzfeldt-Jakob病は実際に発生し、大きな問題となった。", "E": "ステロイドの長期内服は視床下部-下垂体-副腎系を抑制し、二次性副腎機能不全をきたす。"}'),
    ('115-C-17', '正答は E「萎縮性胃炎」。

悪性貧血は自己免疫性の萎縮性胃炎により胃壁細胞と内因子が失われ、ビタミンB12の吸収が障害されて起こる。抗内因子抗体・抗胃壁細胞抗体が陽性となり、胃癌のリスクも高まる。

出典：厚生労働省ホームページ 第115回医師国家試験 C017',
     '{"A": "色素胆石は慢性溶血に伴って生じる。", "B": "脾腫は遺伝性球状赤血球症など血管外溶血で目立つ。", "C": "氷などを無性に食べたくなる異食症は鉄欠乏性貧血の特徴である。", "D": "鉄欠乏に伴う嚥下障害はPlummer-Vinson症候群である。"}'),
    ('115-C-18', '正答は C「尋常性狼瘡」。

尋常性狼瘡は皮膚結核の一型で、顔面などに緩徐に拡大する赤褐色の局面を作る。自覚症状に乏しく瘙痒を伴わない。

出典：厚生労働省ホームページ 第115回医師国家試験 C018',
     '{"A": "疥癬はヒゼンダニによるもので、夜間に増強する激しい瘙痒が特徴である。", "B": "扁平苔癬は紫紅色の多角形丘疹で強い瘙痒を伴う。", "D": "疱疹状皮膚炎は激しい瘙痒を伴う小水疱性の皮疹で、セリアック病と関連する。", "E": "水疱性類天疱瘡は緊満性水疱に先行して強い瘙痒が出ることが多い。"}'),
    ('115-C-19', '正答は C「涙もろくなるのが特徴である。」。

マタニティ・ブルーズは産後3〜10日ごろに現れる一過性の情緒不安定で、涙もろさ、不安、集中困難などを示す。多くは2週以内に自然軽快する。

出典：厚生労働省ホームページ 第115回医師国家試験 C019',
     '{"A": "母乳育児を禁止する理由はない。", "B": "直ちに精神科へつなぐ必要はなく、支持的な関わりと経過観察が基本である。ただし2週を超えて続くなら産後うつ病を疑う。", "D": "大半が自然に軽快する。", "E": "発症のピークは産後数日で、1か月後ではない。"}'),
    ('115-C-21', '正答は D「低体重 — 巨大児出産」。

巨大児出産の危険因子は母体の肥満と糖尿病である。母体の低体重はむしろ低出生体重児のリスクとなる。

出典：厚生労働省ホームページ 第115回医師国家試験 C021',
     '{"A": "喫煙は胎盤の血管障害を通じて常位胎盤早期剝離のリスクを高める。正しい。", "B": "高年妊娠では卵子の染色体異常が増え、流産率が上がる。正しい。", "C": "肥満は妊娠高血圧症候群の危険因子である。正しい。", "E": "子宮筋腫核出術後の瘢痕は子宮破裂の危険因子である。正しい。"}'),
    ('115-C-22', '正答は B「尿道カテーテルは陰茎を頭側に向けて下腹部に固定する。」。

陰茎を頭側に向けて下腹部に固定すると、陰茎陰囊角での尿道の屈曲がなくなる。屈曲したまま留置するとその部位に圧迫壊死が起き、尿道皮膚瘻を生じうる。

出典：厚生労働省ホームページ 第115回医師国家試験 C022',
     '{"A": "尿路感染を防ぐため閉鎖式回路を用いる。", "C": "定期的な交換は感染を減らさない。閉塞や汚染があるときに交換する。", "D": "膀胱洗浄の連日施行は感染予防効果が示されておらず、推奨されない。", "E": "留置中も可能な範囲で離床を促す。安静臥床は合併症を増やす。"}'),
    ('115-C-24', '正答は C「急速な都市化や生活習慣のグローバル化が加速要因となっている。」。

非感染性疾患の増加には、都市化に伴う身体活動の低下、加工食品や砂糖入り飲料の普及、たばこ・アルコールの流通といった生活習慣のグローバル化が背景にある。低・中所得国でとくに急速に進んでいる。

出典：厚生労働省ホームページ 第115回医師国家試験 C024',
     '{"A": "世界の死亡の約7割を非感染性疾患が占め、感染性疾患より多い。", "B": "非感染性疾患による死亡の8割近くは低・中所得国で生じている。", "D": "最大の寄与を持つ単一の危険因子は喫煙や高血圧であり、塩分過剰摂取単独ではない。", "E": "低・中所得国では貧困層のほうが死亡率が高い。"}'),
    ('115-C-35', '正答は A「禁煙」。

一次予防は病気になる前に発症そのものを防ぐ取り組みである。禁煙は肺癌・心血管疾患・COPDなど未発症の疾患の発症予防にあたり、一次予防に該当する。

出典：厚生労働省ホームページ 第115回医師国家試験 C035',
     '{"B": "すでに糖尿病がある患者の血糖管理は、合併症の発症・進展を防ぐ二次〜三次予防にあたる。", "C": "脳梗塞既往のある患者への抗血小板薬は再発予防で、三次予防にあたる。", "D": "HbA1cの定期測定は既存疾患の管理であり、一次予防ではない。", "E": "がん検診は無症状の段階で早期発見する二次予防である。"}'),
    ('115-C-36', '正答は D「赤血球液-LRとの交差適合試験」。

交差適合試験は輸血する血液を決めた時点で、投与の直前に行う検査である。手術は4週後であり、現時点で行っても有効期間を過ぎてしまう。

出典：厚生労働省ホームページ 第115回医師国家試験 C036',
     '{"A": "フェリチン5ng/mLと鉄欠乏があり、術前に鉄剤で貧血を改善しておくのは適切である。", "B": "RhD陰性で適合血の確保が難しく、術前の自己血貯血は有用である。", "C": "不規則抗体の有無を早期に把握しておくことは、適合血の準備に必要である。", "E": "予測出血量800mLに対し、輸血部門と準備量を調整しておくのは適切である。"}'),
    ('115-C-40', '正答は E「腹部に挫創があり、意識レベルがJCSIII-100である。」。

腹部挫創に加えJCS III-100の意識障害があり、緊急度・重症度がともに高い最優先治療群(赤)にあたる。搬送手段が限られる災害現場では、この患者を最初に搬送する。

出典：厚生労働省ホームページ 第115回医師国家試験 C040',
     '{"A": "自力歩行できるのは軽症群(緑)で、ヘリ搬送の優先度は低い。", "B": "呼吸も脈もない頭部挫滅は死亡群(黒)で、限られた資源を投じる対象にならない。", "C": "呼吸状態が安定していれば待機的治療群(黄)である。", "D": "簡単な指示に従えるなら意識は保たれており、待機的治療群にとどまる。"}'),
    ('115-C-43', '正答は A「導尿」。

下腹部に弾性軟の腫瘤を触れ、超音波で膀胱に大量の尿貯留があり尿閉である。前立腺肥大症による溢流性尿失禁と考え、まず導尿して膀胱内圧を下げ、腎後性腎障害を防ぐ。

出典：厚生労働省ホームページ 第115回医師国家試験 C043',
     '{"B": "尿道ブジーは尿道狭窄に対する処置で、まず行うべきものではない。", "C": "利尿薬は尿量を増やして膀胱をさらに拡張させ、病態を悪化させる。", "D": "β3刺激薬は蓄尿症状に用いる薬剤で、尿閉を助長する。", "E": "抗コリン薬は排尿筋の収縮を抑え、尿閉を悪化させるため禁忌に近い。"}'),
    ('115-C-45', '正答は B「「体重を毎朝測定して減量を目指しましょう」」。

毎朝の体重測定は自己モニタリングとして行動変容を促す代表的な方法で、減量の目標設定にも役立つ。肥満を基盤とした耐糖能異常・脂質異常症・高血圧の是正はまず減量から入る。

出典：厚生労働省ホームページ 第115回医師国家試験 C045',
     '{"A": "高血圧があっても有酸素運動は推奨される。運動を控えるのは逆である。", "C": "食後2時間血糖252mg/dLとHbA1c8.2%で糖尿病型と判定でき、空腹時採血は必須ではない。", "D": "アルコール自体がエネルギー源であり肝への負担にもなるため、糖質を含まなければよいわけではない。", "E": "標準体重約65kgに対して1,200kcalは過度な制限で、続かず筋肉量も落とす。"}'),
    ('115-C-46', '正答は C「アドレナリンの筋肉注射」。

食物アレルギーの既往があり、膨疹の多発、口唇の高度浮腫、喘鳴、血圧70/42mmHgとアナフィラキシーショックである。直ちにアドレナリン0.3mgを大腿前外側に筋注するよう指示する。

出典：厚生労働省ホームページ 第115回医師国家試験 C046',
     '{"A": "気道浮腫が進めば挿管も要するが、まずアドレナリンで浮腫と血管透過性亢進を抑えることが先である。", "B": "体温37.5°Cで熱中症の病像ではなく、冷却は的外れである。", "D": "気管支拡張薬は補助的で、循環虚脱には無効である。", "E": "心電図は頻脈以外に異常がなく、除細動の適応がない。"}'),
    ('115-C-48', '正答は B「「死因の究明が病理解剖の主な目的です」」。

病理解剖(剖検)は、死因の解明と診断・治療が適切であったかの検証を目的として、遺族の承諾を得て行われる。得られた知見は医療の質の向上に還元される。

出典：厚生労働省ホームページ 第115回医師国家試験 C048',
     '{"A": "解剖後は遺体を整えて遺族に返す。火葬は遺族が行う。", "C": "摘出した臓器の保存には別途の承諾が必要で、無条件に永久保管はできない。", "D": "通常は数時間で終了し、当日中に遺体を返すことができる。", "E": "死亡診断書は解剖の有無にかかわらず交付される。"}'),
    ('115-C-49', '正答は C「現状の食塩摂取量を維持する。」。

慢性腎臓病の食塩摂取量は3g/日以上6g/日未満が目安である。本例は5.2〜5.8g/日で適正範囲にあり、現状を維持するよう伝えるのが正しい。

出典：厚生労働省ホームページ 第115回医師国家試験 C049',
     '{"A": "飲酒習慣のない患者に飲酒を勧める理由はない。", "B": "適度な運動は腎機能の維持にも心血管リスクの低減にも有益で、減らす必要はない。", "D": "体重66kgに対し蛋白48〜52g/日は0.7〜0.8g/kgで適正である。2倍にすれば腎への負担が増す。", "E": "1,200kcalでは必要量に足りず、蛋白の異化が進んでしまう。"}'),
    ('115-C-53', '正答は E「5」。

興味のあるものを指さして他者と共有する行動は生後10〜12か月ごろに現れる。1歳6か月でこれがないのは明らかな遅れで、自閉スペクトラム症を含めた評価が必要になる。

出典：厚生労働省ホームページ 第115回医師国家試験 C053',
     '{"A": "スキップができるようになるのは5歳ごろである。", "B": "まねをして〇を描けるようになるのは3歳ごろである。", "C": "2語文が出るのは2歳ごろで、1歳6か月で単語のみでも遅れではない。", "D": "自分の名前を言えるようになるのは3歳ごろである。"}'),
    ('115-D-1', '正答は C「卵巣」。

卵巣の機能が失われるとエストロゲンとインヒビンが減り、負のフィードバックが外れて下垂体からのFSHが上昇する。高ゴナドトロピン性の無月経で、障害部位は卵巣である。

出典：厚生労働省ホームページ 第115回医師国家試験 D001',
     '{"A": "視床下部性ではGnRHの分泌低下によりFSH・LHとも低値となる。", "B": "下垂体性でもFSHは低値となる。", "D": "子宮性無月経(Asherman症候群など)ではホルモンは正常である。", "E": "腟の異常(処女膜閉鎖など)は月経血の流出障害で、ホルモンは正常である。"}'),
    ('115-D-2', '正答は C「バンコマイシン」。

バンコマイシンは有効域と中毒域が近く、腎障害と聴器障害のリスクがあるため、トラフ値を測定して投与量を調整する(TDM)。

出典：厚生労働省ホームページ 第115回医師国家試験 D002',
     '{"A": "クリンダマイシンはTDMの対象ではない。", "B": "セファゾリンも治療域が広くTDMを要さない。", "D": "ペニシリンGは安全域が広い。", "E": "レボフロキサシンもTDMの対象ではない。"}'),
    ('115-D-3', '正答は E「網膜中心動脈閉塞症 — 眼球マッサージ」。

網膜中心動脈閉塞症は網膜が数十分で不可逆的に障害されるため、診断と同時に眼球マッサージを行い、塞栓を末梢へ移動させて灌流の再開を図る。前房穿刺や炭酸脱水酵素阻害薬で眼圧を下げることも併用する。

出典：厚生労働省ホームページ 第115回医師国家試験 D003',
     '{"A": "眼窩蜂巣炎は細菌感染で、抗菌薬の全身投与が初期対応となる。炭酸脱水酵素阻害薬は無関係である。", "B": "急性涙囊炎も細菌感染で、抗菌薬投与と切開排膿を行う。アトロピンは適応がない。", "C": "急性ぶどう膜炎では虹彩後癒着を防ぐため散瞳薬とステロイドを用いる。縮瞳薬のピロカルピンは癒着を助長する。", "D": "裂孔原性網膜剝離は手術による復位が必要で、ステロイド点眼では治らない。"}'),
    ('115-D-4', '正答は E「老人性全身性アミロイドーシスでは免疫グロブリンが心臓に沈着する。」。

老人性(野生型トランスサイレチン型)全身性アミロイドーシスで沈着するのはトランスサイレチンである。免疫グロブリン軽鎖が沈着するのはAL型アミロイドーシスで、形質細胞疾患を背景とする。

出典：厚生労働省ホームページ 第115回医師国家試験 D004',
     '{"A": "全身疾患に伴って心筋が障害される二次性(特定)心筋症である。正しい。", "B": "心筋壁は厚くなるのに心電図では低電位を示すという乖離が特徴的である。正しい。", "C": "心筋生検でCongo red染色と偏光顕微鏡による緑色複屈折を確認する。正しい。", "D": "心筋が硬くなり拡張が妨げられる拘束型の血行動態を示す。正しい。"}'),
    ('115-D-5', '正答は A「気胸の既往」。

気胸は胸腔内に空気が漏れる疾患で、閉塞性睡眠時無呼吸症候群との関連は知られていない。

出典：厚生労働省ホームページ 第115回医師国家試験 D005',
     '{"B": "日中の過度の眠気は無呼吸による睡眠の分断を反映する代表的な症状である。", "C": "無呼吸のたびに覚醒反応が起こり、夜間の中途覚醒が増える。", "D": "交感神経の亢進により治療抵抗性高血圧の背景となる。", "E": "夜間から早朝の心筋梗塞・脳卒中・不整脈のリスクが高まる。"}'),
    ('115-D-6', '正答は E「アセトン血性嘔吐症」。

アセトン血性嘔吐症(自家中毒、周期性嘔吐症)は2〜10歳の幼児期に発症し、感染や心理的ストレスを契機に反復する。思春期までにほとんどが自然寛解する。

出典：厚生労働省ホームページ 第115回医師国家試験 D006',
     '{"A": "片頭痛は成人期にも持続し、女性では月経周期と関連して続くことが多い。", "B": "過換気症候群は思春期以降の発症が多い。", "C": "起立性調節障害は思春期に発症する。", "D": "神経性やせ症は思春期以降に発症する。"}'),
    ('115-D-7', '正答は D「肺線維症」。

肺線維症は間質の線維化であり、胸腔内に膿がたまる膿胸の原因にはならない。

出典：厚生労働省ホームページ 第115回医師国家試験 D007',
     '{"A": "肺炎に伴う傍肺炎性胸水が感染して膿胸に移行するのが最も多い経路である。", "B": "胸部外傷による血胸に感染が加わると膿胸になる。", "C": "食道穿孔では消化管内容と細菌が縦隔・胸腔に漏れて膿胸をきたす。", "E": "歯性感染や扁桃周囲膿瘍から下降した降下性壊死性縦隔炎は縦隔・胸腔に波及する。"}'),
    ('115-D-8', '正答は D「βラクタム系抗菌薬が有効である。」。

Legionellaは細胞内寄生菌で、細胞内に到達しないβラクタム系抗菌薬は無効である。キノロン系やマクロライド系を用いる。

出典：厚生労働省ホームページ 第115回医師国家試験 D008',
     '{"A": "冷却塔や循環式浴槽、給湯設備を介した集団感染が知られている。", "B": "意識障害や失見当識など中枢神経症状を伴いやすい。", "C": "低ナトリウム血症は他の肺炎より高頻度で、診断の手がかりになる。", "E": "尿中抗原検査は血清群1に対して感度が高く、迅速診断に有用である。"}'),
    ('115-D-17', '正答は B「塩酸モルヒネ皮下投与」。

食欲は良好で経口摂取に問題がなく、疼痛管理は経口投与から始めるのが原則である。皮下投与は経口摂取ができない場合や急速な調節が必要な場合に選ぶもので、現時点では適切でない。

出典：厚生労働省ホームページ 第115回医師国家試験 D017',
     '{"A": "骨転移痛にはNSAIDが有効で、経口から開始するのは適切である。", "C": "骨転移巣への放射線照射は除痛効果が高く、適切である。", "D": "アセトアミノフェンの経口投与も基本的な鎮痛手段として適切である。", "E": "ビスホスホネートは骨関連事象の抑制と骨痛の軽減に用いられ、適切である。"}'),
    ('115-D-18', '正答は C「中脳」。

左の動眼神経麻痺(眼瞼下垂・散瞳・対光反射消失・外転位)と、対側である右の片麻痺が同時にみられる。中脳の大脳脚を含む病変で動眼神経核・神経束と錐体路が同時に障害されるWeber症候群である。

出典：厚生労働省ホームページ 第115回医師国家試験 D018',
     '{"A": "放線冠の障害では対側の片麻痺のみで、動眼神経麻痺は生じない。", "B": "内包の障害も対側の片麻痺のみである。", "D": "橋の障害では外転神経・顔面神経の麻痺と対側片麻痺(Millard-Gubler症候群)となる。", "E": "延髄の障害では舌下神経麻痺と対側片麻痺(Dejerine症候群)となる。"}'),
    ('115-D-21', '正答は E「「ブドウ果汁入りジュースをやめて、明日の便を観察してください」」。

前日に初めて飲んだブドウ果汁の色素で便が赤紫色に着色したもので、便潜血が陰性であり出血ではない。腹部超音波でも異常がなく機嫌も食欲も良い。原因となった飲料をやめて便の色を確認するよう説明すればよい。

出典：厚生労働省ホームページ 第115回医師国家試験 D021',
     '{"A": "感染性腸炎を示す所見がなく、抗菌薬の適応がない。", "B": "経口摂取は良好で脱水もなく、輸液の必要がない。", "C": "腸重積を疑う所見(間欠的啼泣、嘔吐、腹部腫瘤、超音波のtarget sign)がなく、整復の適応はない。", "D": "眼瞼結膜に貧血がなく、便潜血も陰性で、貧血の検索を急ぐ理由がない。"}'),
    ('115-D-22', '正答は D「広域抗菌薬投与」。

人工関節置換術の翌朝に37.4°C程度の発熱がみられるのは、手術侵襲に伴う炎症反応(吸収熱)として一般的である。創部に異常はなく、感染を示す所見もない段階で広域抗菌薬を投与するのは適切でない。

出典：厚生労働省ホームページ 第115回医師国家試験 D022',
     '{"A": "早期離床は深部静脈血栓症と肺炎の予防になり、適切である。", "B": "発熱への対症的なクーリングは適切である。", "C": "苦痛が強ければ解熱鎮痛薬を用いてよい。", "E": "人工膝関節置換術後は早期からのリハビリテーションが機能予後を左右する。適切である。"}'),
    ('115-D-25', '正答は A「普通型車いす」。

上腕二頭筋と橈側手根伸筋が5、上腕三頭筋が4で、深指屈筋と小指外転筋が0という分布はC7レベルの頸髄損傷にあたる。肘の伸展と手関節の背屈が使えるため、上肢で駆動する普通型車いすでの移動が可能である。

出典：厚生労働省ホームページ 第115回医師国家試験 D025',
     '{"B": "体幹筋と下肢筋の随意運動が不可能で、歩行器を用いた歩行はできない。", "C": "松葉杖歩行も下肢の支持性が必要で不可能である。", "D": "短下肢装具は足関節を制御するもので、対麻痺のある本例には対応できない。", "E": "下顎コントロール電動車いすは上肢がまったく使えない高位頸髄損傷で用いる。本例は上肢が使える。"}'),
    ('115-D-28', '正答は C「慢性的な空虚感を抱えている。」。

見捨てられ不安に基づく激しい対人関係の変動、理想化と脱価値化の反復、自傷行為、感情の不安定さがみられ、境界性パーソナリティ症を考える。慢性的な空虚感は診断基準に含まれる特徴である。

出典：厚生労働省ホームページ 第115回医師国家試験 D028',
     '{"A": "繰り返し嘘をつき他者を欺くのは反社会性パーソナリティ症の特徴である。", "B": "第六感やジンクスへのこだわりは統合失調型パーソナリティ症の特徴である。", "D": "完全主義のため物事を終えられないのは強迫性パーソナリティ症の特徴である。", "E": "常に注目の的でありたいと求めるのは演技性パーソナリティ症の特徴である。"}'),
    ('115-D-29', '正答は C「ビタミンB12投与」。

母が胃全摘後に貧血治療薬を自己中断しており、完全母乳栄養の児にビタミンB12が供給されていない。体重増加不良、定頸の遅れ、Moro反射の消失という神経症状を伴う大球性貧血で、ビタミンB12を投与する。

出典：厚生労働省ホームページ 第115回医師国家試験 D029',
     '{"A": "鉄欠乏では小球性低色素性貧血となり、神経症状は伴わない。", "B": "葉酸欠乏も大球性貧血をきたすが、母は妊娠前から葉酸を含む栄養補助食品を摂取しており、また神経症状は葉酸欠乏では説明しにくい。", "D": "輸血は原因治療にならず、B12の補充で速やかに改善する。", "E": "エリスロポエチン不足による貧血ではない。"}'),
    ('115-D-30', '正答は A「ヘパリン」。

胎児心拍確認後の流産を3回繰り返し、抗リン脂質抗体が陽性でAPTTが延長し、下肢血栓症の既往もある。抗リン脂質抗体症候群による反復流産で、次回妊娠中はヘパリンと低用量アスピリンの併用で胎盤の微小血栓を防ぐ。

出典：厚生労働省ホームページ 第115回医師国家試験 D030',
     '{"B": "ビタミンDに流産予防の根拠はない。", "C": "ビタミンKはむしろ凝固を促す方向に働き、逆効果である。", "D": "エストロゲンは血栓リスクを高め、この病態では避けたい。", "E": "黄体機能不全による流産ではなく、基礎体温は二相性で高温相も14日間保たれている。"}'),
    ('115-D-31', '正答は D「ポリソムノグラフィ」。

日中の耐えがたい眠気、情動により誘発される脱力(情動脱力発作)、入眠時幻覚、睡眠麻痺という四徴が揃っており、ナルコレプシーである。終夜睡眠ポリグラフ検査に続いて反復睡眠潜時検査を行い、入眠潜時の短縮と入眠時レム睡眠期の出現を確認する。

出典：厚生労働省ホームページ 第115回医師国家試験 D031',
     '{"A": "針筋電図は筋・神経原性疾患の評価に用いるもので、本例に適応がない。", "B": "聴性脳幹反応は聴覚路と脳幹機能の評価で、眠気の診断にならない。", "C": "Holter心電図は不整脈による失神との鑑別に使えるが、情動脱力発作や睡眠麻痺は説明できない。", "E": "ドパミントランスポーターSPECTはParkinson症候群やLewy小体型認知症の評価に用いる。"}'),
    ('115-D-32', '正答は A「赤血球輸血」。

汎血球減少があり骨髄は正形成で3系統に異形成を認めることから骨髄異形成症候群である。Hb6.5g/dLで貧血症状(全身倦怠感)と心雑音が出ており、まず赤血球輸血で症状を改善する。

出典：厚生労働省ホームページ 第115回医師国家試験 D032',
     '{"B": "鉄キレート剤は輸血の反復で鉄が蓄積してから用いるもので、現時点では不要である。フェリチンも120ng/mLと正常上限である。", "C": "同種造血幹細胞移植は根治的治療だが、78歳という年齢では適応にならない。", "D": "副腎皮質ステロイドは骨髄異形成症候群の標準治療ではない。", "E": "トロンボポエチン受容体作動薬は免疫性血小板減少症に用いる薬剤である。"}'),
    ('115-D-34', '正答は E「指に付着した便の培養結果」。

便培養は感染性腸炎を疑うときの検査で、慢性便秘と排便時の少量の鮮血という病像には結びつかない。優先度は最も低い。

出典：厚生労働省ホームページ 第115回医師国家試験 D034',
     '{"A": "排便時の鮮血の原因として痔核は最も多く、視診・指診で確認する。", "B": "硬便による裂肛も鮮血の原因として頻度が高い。", "C": "65歳で便通の変化と出血があり、直腸癌の除外は必須である。", "D": "指に血液が付着するかどうかは、出血の有無と位置を知る直接の情報になる。"}'),
    ('115-D-35', '正答は C「たこつぼ心筋症」。

たこつぼ心筋症は心尖部を中心とした一過性の壁運動異常が本態で、左室壁厚の増加はきたさない。この時点の鑑別には含まれない。

出典：厚生労働省ホームページ 第115回医師国家試験 D035',
     '{"A": "Fabry病は左室肥大をきたす代謝性疾患で、鑑別に含まれる。", "B": "肥大型心筋症は左室壁厚20mmを説明できる代表的疾患である。", "D": "心アミロイドーシスも壁厚の増加を示し、心電図の低電位との乖離が手がかりになる。", "E": "血圧152/90mmHgが持続しており、高血圧性心肥大も当然鑑別に入る。"}'),
    ('115-D-36', '正答は A「子宮はない。」。

乳房は発達しているのに腋毛・陰毛がなく、腟が盲端で子宮腟部を認めず、鼠径部に腫瘤(停留精巣)を触れる。アンドロゲン不応症で、核型は46,XYであり、Müller管抑制因子の作用によって子宮は形成されない。

出典：厚生労働省ホームページ 第115回医師国家試験 D036',
     '{"B": "性腺は精巣である。鼠径部の腫瘤がそれにあたる。", "C": "染色体は46,XYで、トリソミーではない。", "D": "排卵がないため基礎体温は一相性である。", "E": "男性ホルモンは分泌されているが受容体が働かないため作用しない。欠損しているのではない。"}'),
    ('115-D-40', '正答は E「JAK2遺伝子変異陽性」。

赤血球増多に加えて白血球・血小板も増え、エリスロポエチンが基準以下に低下している。二次性ではなく真性多血症を考え、90%以上で認められるJAK2 V617F変異を確認する。

出典：厚生労働省ホームページ 第115回医師国家試験 D040',
     '{"A": "PaO2低下による二次性多血症ならエリスロポエチンは上昇するはずで、本例は低値である。", "B": "瀉血を要する多血症では鉄が消費され、血清鉄はむしろ低下しやすい。", "C": "真性多血症の骨髄は3系統とも過形成となる。", "D": "血小板産生が亢進しており、網血小板比率は低下しない。"}'),
    ('115-D-42', '正答は D「妊娠高血圧腎症」。

妊娠20週以降に高血圧が出現し、蛋白尿(尿蛋白/Cr比1.0g/gCr)を伴っている。妊娠前や妊娠20週までに高血圧はなく、妊娠高血圧腎症と診断する。

出典：厚生労働省ホームページ 第115回医師国家試験 D042',
     '{"A": "妊娠高血圧は蛋白尿や臓器障害を伴わない場合の診断名である。本例は蛋白尿がある。", "B": "HELLP症候群は溶血・肝酵素上昇・血小板減少を伴うが、本例はいずれも認めない。", "C": "高血圧合併妊娠は妊娠前または妊娠20週までに高血圧があった場合である。", "E": "加重型妊娠高血圧腎症は、もともと高血圧や腎疾患があった妊婦に蛋白尿や臓器障害が加わった場合をいう。"}'),
    ('115-D-43', '正答は E「肝内胆汁うっ滞」。

術後に中心静脈栄養のみで経過した患者に、胆管拡張や肝腫瘤を伴わない直接ビリルビン優位の黄疸が出現している。長期の絶食と高カロリー輸液による肝内胆汁うっ滞で、経腸栄養の再開が改善につながる。

出典：厚生労働省ホームページ 第115回医師国家試験 D043',
     '{"A": "溶血なら間接ビリルビンが優位となり、貧血の進行や網赤血球増加を伴う。", "B": "急性胆囊炎では発熱と右季肋部痛、Murphy徴候を伴う。本例は無熱で圧痛もない。", "C": "閉塞性黄疸なら胆管の拡張を認めるが、超音波では拡張がない。", "D": "肝内に腫瘤性病変を認めず、転移性肝腫瘍は否定的である。"}'),
    ('115-D-45', '正答は B「アセトアミノフェン」。

異型リンパ球の出現、肝脾腫、肝逸脱酵素の上昇を伴う咽頭炎で伝染性単核球症である。特異的治療はなく、解熱鎮痛にアセトアミノフェンを用いる対症療法が基本となる。脾破裂を避けるため激しい運動は控えさせる。

出典：厚生労働省ホームページ 第115回医師国家試験 D045',
     '{"A": "アシクロビルは単純ヘルペスや水痘帯状疱疹に用いる薬剤で、EBウイルスによる本症の経過を改善しない。", "C": "アンピシリンは伝染性単核球症で高率に薬疹を誘発するため避ける。", "D": "オセルタミビルはインフルエンザの治療薬である。", "E": "ステロイドは気道閉塞や重篤な血球減少など限られた場合にのみ用いる。"}'),
    ('115-D-51', '正答は A「腹膜透析は可能である。」。

腹膜透析は年齢だけを理由に除外されるものではない。手技を実施できる本人または介助者がいれば高齢者でも選択でき、通院回数が少なく残存腎機能を保ちやすいという利点がある。

出典：厚生労働省ホームページ 第115回医師国家試験 D051',
     '{"B": "82歳の妻からの生体腎提供は、ドナーの安全性の面から一般に適応にならない。", "C": "血液透析でも腹膜透析でも就業は可能で、実際に多くの患者が働いている。", "D": "透析施設の手配や装具の携行により旅行も可能である。", "E": "パソコン教室の講師を務めており認知機能の低下を疑う所見はない。療法選択に認知機能評価が必須というわけではない。"}'),
    ('115-D-55', '正答は A「Fabry病」。

小児期からの四肢末端の疼痛、低汗症、下背部・臀部の被角血管腫、蛋白尿があり、母と弟にも同症状、母の兄が透析後に突然死という家族歴からFabry病を考える。X連鎖性のα-ガラクトシダーゼA欠損症で、酵素補充療法がある。

出典：厚生労働省ホームページ 第115回医師国家試験 D055',
     '{"B": "線維筋痛症は広範な慢性疼痛が主体で、低汗症や被角血管腫、蛋白尿は伴わない。", "C": "Alport症候群は血尿と難聴を主徴とし、四肢痛や被角血管腫はない。", "D": "Bartter症候群は低カリウム血症とアルカローシスを示すが、本例の電解質は正常である。", "E": "Sjögren症候群は乾燥症状が主体で、家族性の集積や被角血管腫は伴わない。"}'),
    ('115-D-57', '正答は D「Alzheimer型認知症」。

3か月かけて緩徐に進行する意欲低下と作業能率の低下があり、周囲からは「ぼーっとしている」と見える。うつ病の既往があるため見誤られやすいが、経過と抗不安薬・睡眠薬でも改善しない点からAlzheimer型認知症を考える。高齢者では認知症の初期がうつ状態として現れることが少なくない。

出典：厚生労働省ホームページ 第115回医師国家試験 D057',
     '{"A": "過去2回のうつ病エピソードは薬物療法で6か月ほどで回復しており、今回は薬剤を増量しても悪化している点が異なる。", "B": "慢性硬膜下血腫は頭部外傷の既往と経過中の局所神経徴候を伴うことが多い。", "C": "甲状腺機能低下症も認知機能低下をきたすが、寒がり・便秘・徐脈・浮腫などの身体所見を伴う。", "E": "処方された抗不安薬・睡眠薬の影響は考慮すべきだが、増量前の2か月前から症状が始まっている。"}'),
    ('115-D-59', '正答は A「梅毒」。

無痛性で硬い潰瘍(硬性下疳)と無痛性の鼠径リンパ節腫脹は梅毒第1期の典型像である。痛みがないため受診が遅れやすく、放置しても数週で自然に消退するが感染は進行する。

出典：厚生労働省ホームページ 第115回医師国家試験 D059',
     '{"B": "淋菌感染症は女性では帯下や排尿時痛が主で、潰瘍は作らない。", "C": "性器ヘルペスは強い疼痛を伴う多発性の浅い潰瘍で、初感染では発熱も伴う。", "D": "クラミジア感染症は無症状か軽度の帯下増加が主体で、潰瘍は形成しない。", "E": "尖圭コンジローマは乳頭状に隆起する腫瘤で、潰瘍ではない。"}'),
    ('115-D-61', '正答は B「膜性腎症」。

高度の蛋白尿(2.5g/gCr)がありながら血尿に乏しく、血圧も腎機能も保たれている。中高年に発症するネフローゼ症候群の原因として最も多い膜性腎症を考える。悪性腫瘍の合併にも注意する。

出典：厚生労働省ホームページ 第115回医師国家試験 D061',
     '{"A": "IgA腎症は顕微鏡的血尿が必発で、赤血球円柱を伴うことが多い。本例は潜血陰性である。", "C": "多発性囊胞腎は両腎に多数の囊胞ができ腎腫大をきたす。右腎の2cm大の所見だけでは合致しない。", "D": "微小変化型は小児と若年成人に多く、急激な浮腫を伴う。本例は浮腫がなく緩徐な経過である。", "E": "半月体形成性糸球体腎炎は数週で腎機能が急速に悪化し、血尿と赤血球円柱を伴う。"}'),
    ('115-D-62', '正答は C「食道」。

下咽頭癌と食道癌はいずれも飲酒・喫煙を共通の危険因子とし、同じ扁平上皮に発生する。とくに飲酒で顔が赤くなる体質(アセトアルデヒド脱水素酵素2の活性低下)がありながら飲酒を続けた例では食道扁平上皮癌のリスクが著しく高く、重複癌の頻度が最も高い。

出典：厚生労働省ホームページ 第115回医師国家試験 D062',
     '{"A": "口腔も同じ危険因子を共有するが、食道ほど頻度は高くない。", "B": "喉頭も領域癌化の対象だが、下咽頭癌後の重複癌としては食道が最多である。", "D": "胃癌の主要な危険因子はH. pylori感染で、飲酒・喫煙との関連は相対的に弱い。", "E": "十二指腸癌は稀で、飲酒・喫煙との関連も知られていない。"}'),
    ('115-D-64', '正答は A「1%未満」。

転座を伴わない標準型18トリソミーは減数分裂時の不分離による偶発的な事象で、両親の核型は正常である。再発率は1%未満とされ、主に母体年齢に依存する。

出典：厚生労働省ホームページ 第115回医師国家試験 D064',
     '{"B": "5%程度になるのは均衡型転座保因者の一部の場合である。", "C": "25%は常染色体潜性遺伝疾患の再発率である。", "D": "50%は常染色体顕性遺伝疾患の再発率である。", "E": "ほぼ100%となるのはRobertson転座で同一染色体同士が結合している特殊な場合などである。"}'),
    ('115-E-1', '正答は B「予測される入院費」。

入院診療計画書には、傷病名、症状、治療計画、検査内容と日程、手術内容と日程、推定入院期間、看護計画、リハビリテーションの計画などを記載する。費用の見込みは記載事項に含まれない。

出典：厚生労働省ホームページ 第115回医師国家試験 E001',
     '{"A": "入院時の傷病名は記載が求められる。", "C": "推定される入院期間は記載事項である。", "D": "退院に向けた支援計画も記載が求められる。", "E": "入院中に計画される検査の内容と日程も記載事項である。"}'),
    ('115-E-3', '正答は B「残った注射薬は研修医が1人で破棄する。」。

麻薬注射薬の残液を廃棄する際は、麻薬管理者または麻薬施用者の立会いのもと、複数名で確認して廃棄し記録を残す。研修医が1人で処理してはならない。

出典：厚生労働省ホームページ 第115回医師国家試験 E003',
     '{"A": "麻薬は鍵をかけた堅固な設備内に保管することが麻薬及び向精神薬取締法で定められている。", "C": "事故(紛失・盗難・破損)が生じた場合は速やかに都道府県知事へ届け出る。", "D": "施用・交付にあたっては診療録に品名・数量・年月日などを記載する。", "E": "麻薬の施用・交付には都道府県知事の免許を受けた麻薬施用者であることが必要である。"}'),
    ('115-E-4', '正答は D「明日から食後のジョギングを始めるつもりでいる。」。

準備期は1か月以内に行動を始める意思があり、具体的な準備をしている段階である。「明日から食後のジョギングを始めるつもりでいる」がこれにあたる。

出典：厚生労働省ホームページ 第115回医師国家試験 E004',
     '{"A": "問題を認識しつつ変える意思がないのは前熟考期にあたる。", "B": "すでに1週間実行しているのは実行期(6か月未満)である。", "C": "1年以上継続しているのは維持期である。", "E": "半年後からと考えているのは熟考期にあたる。"}'),
    ('115-E-5', '正答は B「患者は同意をいつでも撤回できる。」。

同意はいつでも撤回でき、撤回によって不利益な扱いを受けることはない。この撤回可能性が保証されて初めて、同意が自由な意思に基づくものになる。

出典：厚生労働省ホームページ 第115回医師国家試験 E005',
     '{"A": "意思決定能力のある成人では本人の同意で足り、家族の同意は要件ではない。", "C": "予後は治療を選ぶうえで欠かせない情報で、説明の対象である。", "D": "目的は患者の自己決定の支援であり、医師の免責のためではない。", "E": "最新であることが最善とは限らず、選択肢を示して患者が選べるようにする。"}'),
    ('115-E-6', '正答は E「側臥位で両膝を両手で抱え首を前屈した体位をとらせる。」。

腰椎穿刺は側臥位で膝を抱えて首を前屈させ、背中を丸めることで椎間腔を広げる。この体位をとらせることが穿刺成功の鍵になる。

出典：厚生労働省ホームページ 第115回医師国家試験 E006',
     '{"A": "脳ヘルニアあるいはその切迫がある場合、腰椎穿刺は脳ヘルニアを誘発するため禁忌である。", "B": "Jacoby線(両側腸骨稜を結ぶ線)は第4腰椎棘突起の高さで、脊髄円錐を避けるためこれより下の椎間で穿刺する。", "C": "髄液は自然滴下で採取する。吸引すると脳ヘルニアや神経根損傷の危険がある。", "D": "細い針のほうが硬膜の穿刺孔が小さく、穿刺後頭痛は起こりにくい。"}'),
    ('115-E-7', '正答は A「公衆衛生」。

医師法第1条は「医師は、医療及び保健指導を掌ることによつて公衆衛生の向上及び増進に寄与し、もつて国民の健康な生活を確保するものとする」と定めている。医師の職責が個々の診療にとどまらず公衆衛生に及ぶことを示した条文である。

出典：厚生労働省ホームページ 第115回医師国家試験 E007',
     '{"B": "社会保障は憲法第25条の文脈で用いられる語である。", "C": "生命科学は法文の用語ではない。", "D": "適正診療という語は条文にない。", "E": "臨床医学も条文の用語ではない。"}'),
    ('115-E-8', '正答は D「治験参加への同意書が未取得の段階で治験用の降圧薬を使用した。」。

治験は被験者の自由意思による文書同意が絶対の前提で、同意が取得できていない段階で治験薬を使うことは許されない。救命に必要なのは標準治療であって治験薬ではない。

出典：厚生労働省ホームページ 第115回医師国家試験 E008',
     '{"A": "家族への連絡を試みることは、本人の意思の推定と情報収集の両面で適切である。", "B": "緊急時に院内で必要性を検討し記録に残すことは適切である。", "C": "通院先へ診療情報を照会することは、救命のために必要な範囲で許される。", "E": "血液型判明前の緊急輸血にはO型RhD陰性の赤血球を用いる。適切である。"}'),
    ('115-E-10', '正答は D「頭位変換時に眼振を示す。」。

良性発作性頭位めまい症は、頭位を変えたときに数十秒続く回転性めまいと眼振が誘発される。Dix-Hallpike法などで頭位変換時の眼振を確認して診断する。

出典：厚生労働省ホームページ 第115回医師国家試験 E010',
     '{"A": "難聴や耳鳴は伴わない。伴う場合はMeniere病などを考える。", "B": "中高年に多く、小児には稀である。", "C": "意識消失は伴わない。伴う場合は失神の鑑別が必要である。", "E": "浮遊耳石は卵形囊の耳石器から剝がれたもので、半規管由来ではない。"}'),
    ('115-E-11', '正答は E「ボトルに検体を注入後、ボトル内の培地と血液を転倒混和する。」。

ボトルに血液を注入した後は転倒混和して培地と血液をよく混ぜる。混和が不十分だと凝固して菌の検出感度が落ちる。

出典：厚生労働省ホームページ 第115回医師国家試験 E011',
     '{"A": "抗菌薬投与前に採取する。投与後では菌が検出されにくくなる。", "B": "汚染菌と真の菌血症を区別するため、2セットは別々の部位から採取する。", "C": "消毒薬が乾燥してから穿刺する。乾く前では殺菌効果が十分でない。", "D": "注射器で採血した場合は嫌気ボトルから先に入れる(空気の混入を避けるため)。"}'),
    ('115-E-12', '正答は A「肩関節」。

肩関節は球関節で、屈曲・伸展・外転・内転に加えて内旋・外旋という回旋運動の可動域を測定する。

出典：厚生労働省ホームページ 第115回医師国家試験 E012',
     '{"B": "肘関節は蝶番関節で屈曲・伸展を測る。前腕の回内・回外は前腕として別に測定する。", "C": "手関節は掌屈・背屈と橈屈・尺屈を測る。", "D": "膝関節は屈曲・伸展を測る。", "E": "足関節は背屈・底屈を測る。"}'),
    ('115-E-13', '正答は A「高血糖」。

高血糖では糸球体で濾過されたブドウ糖が近位尿細管の再吸収能を超えて尿細管腔に残り、浸透圧により水の再吸収を妨げて多尿となる。糖尿病の口渇・多飲・多尿はこの機序による。

出典：厚生労働省ホームページ 第115回医師国家試験 E013',
     '{"B": "心因性多飲は水の過剰摂取による水利尿で、尿浸透圧は低い。", "C": "腎性尿崩症は集合管がADHに反応せず水を再吸収できない水利尿である。", "D": "中枢性尿崩症もADHの分泌不足による水利尿である。", "E": "低カリウム血症は尿濃縮力の低下をきたすが、浸透圧利尿ではない。"}'),
    ('115-E-15', '正答は D「ペスト」。

ペストはペスト菌(Yersinia pestis)による感染症で、ノミを介してネズミから人に伝播する。14世紀のヨーロッパで大流行し、皮膚が黒ずんで死に至ることから黒死病と呼ばれた。感染症法の1類感染症である。

出典：厚生労働省ホームページ 第115回医師国家試験 E015',
     '{"A": "結核も歴史的に大きな被害をもたらしたが黒死病とは呼ばれない。", "B": "コレラは19世紀以降に世界的流行を繰り返した。", "C": "天然痘は世界的に流行したが1980年に根絶宣言が出された。", "E": "発疹チフスはシラミが媒介し、戦争や飢饉に伴って流行した。"}'),
    ('115-E-17', '正答は E「情報バイアスは統計的手法で調整できる。」。

情報バイアスは測定や聞き取りの段階で生じる系統誤差で、いったん歪んだデータを後から統計的に補正することはできない。設計段階で盲検化や標準化した測定手順によって防ぐしかない。

出典：厚生労働省ホームページ 第115回医師国家試験 E017',
     '{"A": "情報バイアスは対象者から情報を得る過程で生じる。正しい。", "B": "選択バイアスは対象者をどう選ぶかによって生じる。正しい。", "C": "交絡因子は限定・マッチング・層別化・多変量解析などで調整できる。正しい。", "D": "交絡因子は曝露と結果の両方に関連し、かつ因果の中間段階にないものをいう。正しい。"}'),
    ('115-E-19', '正答は C「有能な人材への業務の集中」。

有能な人材に業務を集中させると、その人の疲労と負荷が増してかえって誤りが起きやすくなり、不在時に対応できる者がいなくなる。防止策にならない。

出典：厚生労働省ホームページ 第115回医師国家試験 E019',
     '{"A": "研修による知識と技能の維持は基本的な対策である。", "B": "実態に合わなくなったマニュアルは守られないため、定期的な見直しが要る。", "D": "起こりうる危険を先に想像して備える訓練は有効である。", "E": "指さし呼称は確認行為を意識化して見落としを減らす。"}'),
    ('115-E-21', '正答は D「食道裂孔ヘルニア」。

内ヘルニアは腹腔内の裂孔や陥凹に腸管などが入り込むもので、体表からは触れない。食道裂孔ヘルニアは横隔膜の食道裂孔から胃が縦隔側へ入り込む内ヘルニアである。

出典：厚生労働省ホームページ 第115回医師国家試験 E021',
     '{"A": "鼠径ヘルニアは腹壁を通って体表に脱出する外ヘルニアである。", "B": "大腿ヘルニアも鼠径靱帯の下から体表へ脱出する外ヘルニアである。", "C": "閉鎖孔ヘルニアは骨盤の閉鎖孔から大腿内側へ脱出する外ヘルニアである。", "E": "腹壁瘢痕ヘルニアは手術創部の腹壁欠損から脱出する外ヘルニアである。"}'),
    ('115-E-22', '正答は E「エネルギーと栄養素の摂取量の基準を示すものである。」。

日本人の食事摂取基準は、健康の保持増進と生活習慣病の予防のために、エネルギーと各栄養素の摂取量の基準を示したものである。5年ごとに改定される。

出典：厚生労働省ホームページ 第115回医師国家試験 E022',
     '{"A": "集団だけでなく個人の食事改善にも用いる。", "B": "乳児から高齢者(75歳以上を含む)まで全年齢を対象とする。", "C": "妊婦・授乳婦についても付加量が示されている。", "D": "目標とするBMIは年齢区分ごとに定められ、18〜49歳で18.5〜24.9、65歳以上で21.5〜24.9などとなっている。"}'),
    ('115-E-23', '正答は A「腎結石」。

蓄尿症状とは頻尿・尿意切迫感・尿失禁など尿をためる過程の障害である。腎結石は側腹部痛や血尿をきたすが、膀胱の蓄尿機能そのものには影響しない。

出典：厚生労働省ホームページ 第115回医師国家試験 E023',
     '{"B": "脳梗塞では排尿の抑制が外れて過活動膀胱となり、頻尿や切迫性尿失禁を生じる。", "C": "脊髄損傷では排尿筋過活動により蓄尿症状をきたす。", "D": "Parkinson病でも過活動膀胱による夜間頻尿や切迫性尿失禁がみられる。", "E": "間質性膀胱炎は膀胱の伸展に伴う疼痛と頻尿が主症状である。"}'),
    ('115-E-24', '正答は C「急性好酸球性肺炎」。

急性好酸球性肺炎は喫煙開始や再開、本数の急増を契機に発症することが多く、喫煙が発症因子として知られている。禁煙により再発が防げる。

出典：厚生労働省ホームページ 第115回医師国家試験 E024',
     '{"A": "過敏性肺炎は真菌や鳥の蛋白など抗原の反復吸入による。喫煙はむしろ発症を抑える方向に働くとされる。", "B": "レジオネラ肺炎は環境中の水系からの感染で、喫煙は重症化の因子ではあるが発症因子とは位置づけられない。", "D": "非結核性抗酸菌症は中年女性の非喫煙者に多い。", "E": "マイコプラズマ肺炎は飛沫感染で、喫煙との関連は知られていない。"}'),
    ('115-E-26', '正答は D「本人の意思」。

胃瘻造設のような侵襲的な処置の可否は、本人の意思が最も優先される。あらかじめ本人が文書で意思表示していれば、それを尊重して方針を決める。

出典：厚生労働省ホームページ 第115回医師国家試験 E026',
     '{"A": "要介護度は必要な介護量の指標であって、本人の希望に優先しない。", "B": "医師の医学的判断は選択肢と見通しを示すためのもので、本人の意思に代わるものではない。", "C": "家族の希望は本人の意思が確認できない場合に推定意思を探る手がかりとなるが、本人の明示の意思には優先しない。", "E": "受け入れ施設の状況は療養場所の調整に関わる事情にすぎない。"}'),
    ('115-E-27', '正答は D「トリコモナス腟炎」。

黄色泡沫状の帯下と外陰の瘙痒はトリコモナス腟炎に特徴的である。性行為で伝播するためパートナーの同時治療が必要で、メトロニダゾールを用いる。

出典：厚生労働省ホームページ 第115回医師国家試験 E027',
     '{"A": "萎縮性腟炎は閉経後のエストロゲン低下による乾燥と接触出血が主体で、40歳では考えにくい。", "B": "細菌性腟症は灰白色でさらさらした帯下と魚臭が特徴で、瘙痒は乏しい。", "C": "カンジダ腟炎は白色の酒粕様・カッテージチーズ様帯下と強い瘙痒、外陰の発赤を伴う。本例は帯下の性状が異なり発赤もない。", "E": "クラミジア子宮頸管炎は無症状のことが多く、帯下が黄色泡沫状にはならない。"}'),
    ('115-E-28', '正答は A「「リスクマネジャーへの報告が必要です」」。

インスリン10単位の指示に対して100単位を混注し、重症低血糖を起こした重大なインシデントである。事実を組織として共有し原因を分析して再発を防ぐため、リスクマネジャーへ報告する必要がある。個人を責めるのではなく仕組みを直すのが目的である。

出典：厚生労働省ホームページ 第115回医師国家試験 E028',
     '{"B": "指示を出した主治医にも確認体制の責任があり、担当医個人の問題として切り離すことはできない。", "C": "患者・家族への説明は医療安全の基本であり、心配をかけたくないという理由で省いてよいものではない。", "D": "事実と異なる記載は診療録の改ざんであり、絶対に許されない。", "E": "原因が判明しているのに不明と説明するのは虚偽の説明で、信頼を根本から損なう。"}'),
    ('115-E-29', '正答は E「「大したことではないので早く忘れた方がいいです」」。

「大したことではない」「早く忘れたほうがよい」という言葉は被害を矮小化し、自責感を強めて回復を妨げる。被害者の語りを受け止め、安全の確保と必要な検査・支援につなぐ姿勢が求められる。

出典：厚生労働省ホームページ 第115回医師国家試験 E029',
     '{"A": "自責感を和らげる言葉で、適切である。", "B": "受診という行動を肯定的に認める言葉で、適切である。", "C": "診察の希望を確認し本人に選択権を渡す言葉で、適切である。", "D": "話してくれたことをねぎらう言葉で、適切である。"}'),
    ('115-E-30', '正答は E「保護者が同意しなくても当人が同意すれば研究参加は可能である。」。

16歳未満の未成年者を対象とする研究では、代諾者(保護者)からのインフォームド・コンセントが必要である。本人からはインフォームド・アセントを得るが、それだけで参加させることはできない。

出典：厚生労働省ホームページ 第115回医師国家試験 E030',
     '{"A": "年齢と理解力に応じた平易な説明を行うことが求められる。正しい。", "B": "理解力のある未成年者からはアセントを得る。正しい。", "C": "同意書には記名・捺印または自署名が必要である。正しい。", "D": "侵襲の程度の評価を含め、研究計画の妥当性は倫理審査委員会が判断する。正しい。"}'),
    ('115-E-31', '正答は E「ベンゾジアゼピン系薬剤が有効である。」。

手術翌日の夜間に急に始まったつじつまの合わない言動で、術後せん妄である。ベンゾジアゼピン系薬剤はせん妄を悪化させ遷延させるため、原則として用いない。必要なら少量の抗精神病薬を検討する。

出典：厚生労働省ホームページ 第115回医師国家試験 E031',
     '{"A": "幻視を伴うことが多い。正しい。", "B": "夜間に目立つが日中にも起こりうる。正しい。", "C": "手術侵襲・疼痛・脱水・薬剤など身体的要因が原因となる。正しい。", "D": "意識レベルが数時間単位で変動するのがせん妄の特徴で、認知症との鑑別点になる。正しい。"}'),
    ('115-E-32', '正答は A「看護師 — 抗菌薬の処方」。

薬剤の処方は医師・歯科医師の業務であり、看護師は行えない。看護師は与薬、観察、口腔ケア、体位管理などを担う。

出典：厚生労働省ホームページ 第115回医師国家試験 E032',
     '{"B": "管理栄養士が嚥下機能に合わせた食形態を評価・調整するのは適切である。", "C": "言語聴覚士が嚥下機能を評価し訓練を行うのは適切である。", "D": "薬剤師が嚥下しやすい剤型(簡易懸濁・粉砕の可否など)を検討するのは適切である。", "E": "理学療法士が排痰や呼吸機能の維持を目的とした呼吸リハビリテーションを行うのは適切である。"}'),
    ('115-E-35', '正答は B「会陰部の異常感覚」。

会陰部の感覚障害(サドル型知覚障害)は馬尾症候群の所見で、正中に大きく脱出したヘルニアで生じる。本例は第4/5腰椎間の右側ヘルニアで片側のL5神経根症状を呈しており、会陰部の異常感覚は認められない。

出典：厚生労働省ホームページ 第115回医師国家試験 E035',
     '{"A": "疼痛のため患側をかばう疼痛性跛行はみられる。", "C": "L5神経根領域である下腿外側の感覚鈍麻はみられる。", "D": "長母趾伸筋はL5支配で、母趾背屈の筋力低下はL5障害の典型である。", "E": "下肢伸展挙上テスト(SLR)は坐骨神経の伸張により疼痛が誘発され陽性となる。"}'),
    ('115-E-39', '正答は C「下痢」。

モルヒネの代表的な副作用は便秘であり、下痢ではない。便秘はほぼ必発で耐性も生じないため、開始と同時に緩下剤を予防的に併用する。

出典：厚生労働省ホームページ 第115回医師国家試験 E039',
     '{"A": "肝転移があり、進行に伴う黄疸に注意する。", "B": "悪心・嘔吐はモルヒネ開始初期によくみられ、制吐薬の併用を検討する。", "D": "腰椎転移による脊髄圧迫は下肢麻痺と膀胱直腸障害を招く緊急事態で、警戒が要る。", "E": "肺転移の進行に加え、モルヒネによる呼吸抑制にも注意する。"}'),
    ('115-E-45', '正答は B「気管挿管」。

JCS III-100の意識障害に舌根沈下といびき様呼吸があり、リザーバー付マスクで10L/分投与してもSpO2は91%にとどまる。気道が保てておらず、まず気管挿管で気道を確保して換気を確実にする。三環系抗うつ薬の過量服薬でQRS幅の延長もあり、けいれんや不整脈で急変しうるため、気道の確保は先延ばしにできない。

出典：厚生労働省ホームページ 第115回医師国家試験 E045',
     '{"A": "胃洗浄は気道を確保する前に行うと誤嚥を招く。適応も限られ、この場面で最初にするものではない。", "C": "頻脈と散瞳は三環系抗うつ薬の抗コリン作用によるもので、アトロピンはそれをさらに強める。", "D": "三環系抗うつ薬は蛋白結合率が高く組織へ広く分布するため、利尿では除去できない。循環血液量を減らす不利益のほうが大きい。", "E": "副腎皮質ステロイドの適応となる病態がない。"}'),
    ('115-E-46', '正答は B「胸壁触診による皮下握雪感」。

設問は誤嚥性肺炎の所見と「合致しない」ものを選ぶもの。皮下握雪感は皮下気腫の触診所見で、気胸や気道・食道の損傷を示す。誤嚥性肺炎そのものでは生じない。

出典：厚生労働省ホームページ 第115回医師国家試験 E046',
     '{"A": "浸潤影や胸水があれば打診で濁音となり、合致する所見である。", "C": "口腔内に吐物の残渣があれば誤嚥を裏づけるもので、合致する。", "D": "気道内の分泌物により coarse crackles が聴かれ、合致する。", "E": "無気肺や胸水を伴えば呼吸音は減弱し、合致する。"}'),
    ('115-E-49', '正答は D「「糖尿病についてどのようにご理解されていますか」」。

2年前に診断されたまま通院が途切れており、「まだ糖尿病なのですかね」という発言は病気の理解が十分でないことをうかがわせる。責めたり脅したりせず、まず本人が糖尿病をどう捉えているかを聞くところから始める。理解のずれが分かって初めて、必要な説明を届けられる。

出典：厚生労働省ホームページ 第115回医師国家試験 E049',
     '{"A": "合併症を持ち出して脅す言い方は不安をあおるだけで、通院の再開にはつながらない。", "B": "血糖350mg/dLは高いが、この一点だけでインスリンの適応を断定できない。まず病態と生活を把握する。", "C": "「なぜ放っておいたのか」は患者を責める問いで、関係を損なう。", "E": "通院の必要がないと突き放すのは、治療の機会そのものを奪う言葉である。"}'),
    ('115-E-50', '正答は C「「ご家族にも病状を説明したいのですが、良いですか」」。

偏食と大量飲酒があり、生活の立て直しには同居する家族の協力が要る。ただし病状は本人の情報なので、家族に伝える前に本人の同意を得る。「説明したいのですが、良いですか」と尋ねるのはその手順にかなっている。

出典：厚生労働省ホームページ 第115回医師国家試験 E050',
     '{"A": "血糖350mg/dLでアキレス腱反射も消失しており、合併症の評価をせずに運動を勧めるのは危険である。", "B": "薬物治療を始めるかどうかを決めるのは医師の責任であり、薬剤師に委ねるものではない。", "D": "生活指導を看護師が担うのはよいが、医師に聞くなと伝えるのは患者の疑問に答える責任を放棄することになる。", "E": "医師の指示が絶対という伝え方は一方的で、本人が納得して続けられる治療にならない。"}'),
    ('115-F-1', '正答は C「ビタミンC — 出血傾向」。

ビタミンCはコラーゲン合成に必要で、欠乏すると血管の脆弱化により歯肉出血や皮下出血をきたす(壊血病)。

出典：厚生労働省ホームページ 第115回医師国家試験 F001',
     '{"A": "味覚障害をきたすのは亜鉛欠乏である。", "B": "ペラグラはナイアシン(ビタミンB3)欠乏による。", "D": "貧血をきたすのは鉄・ビタミンB12・葉酸の欠乏である。", "E": "夜盲はビタミンA欠乏による。"}'),
    ('115-F-5', '正答は A「過強陣痛」。

遅発一過性徐脈は子宮収縮のピークより遅れて始まり遅れて回復する徐脈で、子宮胎盤循環不全を反映する。過強陣痛では収縮の間に胎盤血流が回復せず、これを生じる。

出典：厚生労働省ホームページ 第115回医師国家試験 F005',
     '{"B": "臍帯圧迫では変動一過性徐脈となる。", "C": "児頭圧迫では迷走神経反射により早発一過性徐脈となる。", "D": "胎児貧血ではサイナソイダルパターンを示す。", "E": "母体発熱では胎児頻脈となる。"}'),
    ('115-F-6', '正答は E「メタンフェタミン」。

覚醒剤(メタンフェタミン)では、反復使用の後に少量の再使用でも以前より強い幻覚・妄想が出現する逆耐性現象が知られている。断薬後も飲酒やストレスで再燃(フラッシュバック)しうる。

出典：厚生労働省ホームページ 第115回医師国家試験 F006',
     '{"A": "LSDは急速に耐性が形成される薬物で、逆耐性は示さない。", "B": "大麻も逆耐性現象を示さない。", "C": "アルコールは耐性が形成される。", "D": "ジアゼパムなどベンゾジアゼピンも耐性が形成される。"}'),
    ('115-F-9', '正答は A「世帯数は増加傾向にある。」。

人口が減少に転じても、単独世帯と核家族世帯の増加によって世帯の小規模化が進み、世帯数そのものは増加傾向にある。

出典：厚生労働省ホームページ 第115回医師国家試験 F009',
     '{"B": "三世代世帯は減少を続けており、単独世帯のほうがはるかに多い。", "C": "核家族世帯が最も多く、単独世帯はそれに次ぐ。", "D": "65歳以上の者のみの世帯は全世帯の3割程度で、過半数には達しない。", "E": "核家族世帯の内訳では「夫婦と未婚の子のみ」と「夫婦のみ」が多く、ひとり親と未婚の子は最も少ない。"}'),
    ('115-F-13', '正答は A「現金が給付される。」。

公的医療保険の給付は療養の給付という現物給付が原則である(傷病手当金や出産育児一時金など一部に現金給付はあるが、医療そのものは現物で給付される)。

出典：厚生労働省ホームページ 第115回医師国家試験 F013',
     '{"B": "財源は保険料が主で、これに公費と患者負担が加わる。正しい。", "C": "被用者保険(健康保険組合・協会けんぽ・共済)の加入者が最も多い。正しい。", "D": "国民皆保険により、国民はいずれかの医療保険に加入する。正しい。", "E": "小学校就学前の自己負担割合は2割である。正しい。"}'),
    ('115-F-14', '正答は C「顆粒円柱」。

顆粒円柱は尿細管上皮の変性物を含む病的円柱で、1視野に1つでも認めれば腎実質の障害を示唆する。

出典：厚生労働省ホームページ 第115回医師国家試験 F014',
     '{"A": "赤血球は1視野に4個以下なら正常範囲である。", "B": "白血球も1視野に4個以下なら正常範囲である。", "D": "硝子円柱は健常者でも運動後や脱水時に出現し、少数なら異常ではない。", "E": "扁平上皮は外尿道口由来の混入で、少数なら意義がない。"}'),
    ('115-F-18', '正答は D「骨格筋からアミノ酸が放出される。」。

絶食が続くと糖新生の基質を確保するため、骨格筋の蛋白が分解されてアラニンなどのアミノ酸が血中に放出される。これが肝でグルコースに変換される。

出典：厚生労働省ホームページ 第115回医師国家試験 F018',
     '{"A": "脂肪酸のβ酸化が亢進し、血中ケトン体はむしろ上昇する。", "B": "肝はグルコースを取り込むのではなく、糖新生とグリコーゲン分解で放出する。", "C": "乳酸は骨格筋から肝へ運ばれ糖新生に使われる(Cori回路)。向きが逆である。", "E": "遊離脂肪酸は血液脳関門を通れない。飢餓時の中枢神経はケトン体を利用する。"}'),
    ('115-F-19', '正答は B「黒色壊死は温存する。」。

黒色壊死(エスカー)は感染源となり創傷治癒を妨げるため、原則としてデブリードマンで除去する。温存するのは血流の乏しい踵部の乾燥壊死など限られた場合である。

出典：厚生労働省ホームページ 第115回医師国家試験 F019',
     '{"A": "異物は感染と創傷治癒遅延の原因になるため除去する。正しい。", "C": "深部臓器や血管・神経・腱の損傷の有無を確認することは必須である。正しい。", "D": "汚染のない新鮮な創は一期的縫合でよい。正しい。", "E": "III度熱傷は真皮全層を越えるため自然上皮化せず、植皮を要する。正しい。"}'),
    ('115-F-20', '正答は D「パラシュート反射」。

パラシュート反射は生後6〜9か月ごろに出現し、以後生涯持続する姿勢反射である。10か月児では認められるのが正常で、欠如は運動発達の異常を示唆する。

出典：厚生労働省ホームページ 第115回医師国家試験 F020',
     '{"A": "吸啜反射は生後4〜6か月ごろに消失する原始反射である。", "B": "Moro反射も生後4〜6か月ごろに消失する。", "C": "手掌把握反射も生後4〜6か月ごろに消失する。", "E": "非対称性緊張性頸反射も生後4〜6か月ごろに消失する。"}'),
    ('115-F-21', '正答は B「受精2〜8週」。

器官形成期にあたる受精後2〜8週は、放射線被曝により形態異常(奇形)が生じうる時期である。しきい値はおよそ100〜200mGyとされる。

出典：厚生労働省ホームページ 第115回医師国家試験 F021',
     '{"A": "受精後8日までは着床前期で、影響が出れば流産、出なければ正常に発育する「全か無か」の時期である。", "C": "受精8〜15週は中枢神経の発達期で、精神発達遅滞のリスクが問題となるが形態異常は少ない。", "D": "受精15〜25週も中枢神経への影響が主で、感受性は低下する。", "E": "受精25週以降は形態異常のリスクはほぼない。"}'),
    ('115-F-22', '正答は C「医療観察法は自殺念慮の強い場合の入院に関する法律である。」。

医療観察法は、心神喪失または心神耗弱の状態で重大な他害行為を行った者に対し、適切な医療と社会復帰を確保するための法律である。自殺念慮に関する入院を定めたものではない。

出典：厚生労働省ホームページ 第115回医師国家試験 F022',
     '{"A": "精神科診療所は増加傾向にある。正しい。", "B": "我が国の人口当たり精神科病床数はOECD諸国のなかで最も多い水準にある。正しい。", "D": "精神科救急医療システムの整備は都道府県・政令指定都市が担う。正しい。", "E": "精神保健福祉センターは精神障害者保健福祉手帳の等級判定などを行う。正しい。"}'),
    ('115-F-23', '正答は A「パッチテスト」。

パッチテストは接触皮膚炎などIV型(遅延型)アレルギーを調べる検査で、IgEが介在する即時型食物アレルギーの検査ではない。

出典：厚生労働省ホームページ 第115回医師国家試験 F023',
     '{"B": "プリックテストは皮膚に抗原を入れて15分後の膨疹を見る即時型の検査である。", "C": "食物経口負荷試験は即時型食物アレルギーの確定診断・耐性獲得の確認に用いる標準的検査である。", "D": "ヒスタミン遊離試験は患者の好塩基球から抗原刺激でヒスタミンが遊離するかを見る即時型の検査である。", "E": "抗原特異的IgE検査は即時型アレルギーの基本検査である。"}'),
    ('115-F-24', '正答は D「生命表から作成した生存率曲線下の面積」。

平均寿命は0歳の平均余命であり、生命表の生存数曲線の下の面積を出生数で割ったものに等しい。実際に死亡した人の年齢の平均ではない。

出典：厚生労働省ホームページ 第115回医師国家試験 F024',
     '{"A": "その年の死亡者の年齢の平均は死亡時年齢の平均であって平均寿命ではない。", "B": "最も死亡率の高い年齢は最高齢層になる。", "C": "最も死亡者が多かった年齢は最頻死亡年齢である。", "E": "生存率が50%になる年齢は寿命中位数と呼ばれ、平均寿命とは別の指標である。"}'),
    ('115-F-25', '正答は D「有機溶剤中毒」。

生物学的モニタリングは、体内に取り込まれた化学物質やその代謝物を血液・尿で測る手法である。有機溶剤ではトルエンの尿中馬尿酸、キシレンの尿中メチル馬尿酸などを測定する。

出典：厚生労働省ホームページ 第115回医師国家試験 F025',
     '{"A": "過重労働は労働時間の把握と面接指導で管理する。", "B": "気分障害はストレスチェックや面接で把握する。", "C": "筋骨格系障害は作業姿勢の評価や自覚症状調査による。", "E": "電離放射線は個人線量計による外部被曝線量の測定(物理的モニタリング)で管理する。"}'),
    ('115-F-26', '正答は D「他の年齢層に比べて高齢者の致死率が高い。」。

インフルエンザは高齢者で肺炎の合併や基礎疾患の増悪により致死率が高くなる。このため高齢者は予防接種の定期接種(B類)の対象とされている。

出典：厚生労働省ホームページ 第115回医師国家試験 F026',
     '{"A": "罹患率は小児で最も高い。", "B": "1シーズンの推計罹患者数は約1,000万人にのぼる。", "C": "流行のピークは12月から3月で、春ではない。", "E": "オセルタミビル耐性株が大半を占めるという事実はない。"}'),
    ('115-F-27', '正答は D「鼻閉の程度」。

最長発声持続時間は、深く息を吸って「あー」と発声を続けられる秒数で、肺活量と声門閉鎖の効率で決まる。鼻閉は共鳴に影響するが、発声を持続できる長さには影響しない。

出典：厚生労働省ホームページ 第115回医師国家試験 F027',
     '{"A": "肺活量の差により男性のほうが長くなる傾向があり、性別は影響する。", "B": "加齢とともに肺活量と声門閉鎖機能が低下するため影響する。", "C": "呼気を供給する呼吸機能は直接の規定因子である。", "E": "声門閉鎖が不十分だと呼気が漏れて持続時間が短くなる。"}'),
    ('115-F-28', '正答は E「ミトコンドリア遺伝子の点変異は母から子に伝達する。」。

ミトコンドリアDNAは卵細胞質を介して伝わるため、点変異は母から男女いずれの子にも伝達される。父からは伝わらない。

出典：厚生労働省ホームページ 第115回医師国家試験 F028',
     '{"A": "伝達は母系だが発症に男女差はなく、女性患者が多いわけではない。", "B": "父は関与せず、両親が保因者という遺伝形式ではない。", "C": "変異ミトコンドリアの割合(ヘテロプラスミー)が卵ごとに異なるため、次子の罹患や重症度を正確に予測できない。", "D": "世代を追って必ず重症化するという法則はない。"}'),
    ('115-F-29', '正答は A「アルコールの摂取 — 尿酸の排泄低下」。

アルコールの代謝で生じた乳酸が尿細管における尿酸の分泌を競合的に阻害し、尿酸の排泄が低下する。加えてビール等のプリン体負荷も加わり、血清尿酸値が上昇する。

出典：厚生労働省ホームページ 第115回医師国家試験 F029',
     '{"B": "糖質摂取割合が高ければ余剰は脂肪として蓄積し、体重は増加する。", "C": "長期絶食後に急に栄養を入れるとリフィーディング症候群を起こす。マラスムスは慢性のエネルギー欠乏による消耗である。", "D": "胆石形成に関わるのは脂質の過剰摂取や肥満、急激な減量である。", "E": "動物性脂肪(飽和脂肪酸)の過剰摂取は血中LDLコレステロールを上昇させる。"}'),
    ('115-F-38', '正答は A「海水 — レジオネラ」。

レジオネラは循環式浴槽や冷却塔、加湿器など淡水系の環境で増殖し、エアロゾルの吸入で肺炎を起こす。海水では増殖せず、また経口感染による消化器症状の集団発生の原因にもならない。

出典：厚生労働省ホームページ 第115回医師国家試験 F038',
     '{"B": "ノロウイルスは二枚貝などの食材や感染者を介した集団食中毒の代表である。", "C": "エルシニアは井戸水や食肉を介した感染が知られている。", "D": "クリプトスポリジウムは塩素に抵抗性で、水道水を介した集団感染例がある。", "E": "病原性大腸菌はプールの水を介した集団感染を起こしうる。"}'),
    ('115-F-39', '正答は C「安静時PaO276Torr、労作後PaO255Torr」。

酸素解離曲線ではSpO2 90%がPaO2およそ60Torrに対応する。安静時SpO2 94%はPaO2 70〜80Torr、労作後SpO2 88%はPaO2 55Torr前後にあたる。労作時に急激に酸素化が落ちるのは、曲線の急峻な部分に入るためである。

出典：厚生労働省ホームページ 第115回医師国家試験 F039',
     '{"A": "PaO2 96TorrではSpO2は97〜98%となり、安静時94%と合わない。", "B": "PaO2 88TorrでもSpO2は96〜97%で、94%より高くなる。", "D": "PaO2 58TorrならSpO2は約90%で、安静時94%より低すぎる。", "E": "PaO2 116Torrは室内気では通常みられない高値である。"}'),
    ('115-F-41', '正答は C「放射線肺炎」。

放射線肺炎は照射終了後1〜6か月、多くは3か月前後に照射野に一致して生じる。乾性咳嗽・発熱・労作時呼吸困難で発症し、重症例では副腎皮質ステロイドを要する。

出典：厚生労働省ホームページ 第115回医師国家試験 F041',
     '{"A": "脱毛は照射野に毛髪がある場合に起こる。胸部照射では生じない。", "B": "血球減少は広範囲の骨髄照射で問題になるもので、限局した肺照射では起こりにくい。", "D": "放射線食道炎は照射期間中から直後にかけての急性反応で、3か月後には軽快している。", "E": "放射線皮膚炎も照射中から直後の急性反応である。"}'),
    ('115-F-43', '正答は D「ビタミンK製剤静注」。

完全母乳栄養の新生児に生後数日で消化管出血が起こり、PT-INRとAPTTがともに延長しPIVKA-IIが著増している。ビタミンK欠乏性出血症で、直ちにビタミンK製剤を静注する。母乳はビタミンKに乏しく、予防投与の徹底が重要である。

出典：厚生労働省ホームページ 第115回医師国家試験 F043',
     '{"A": "外科的疾患を示す所見はなく、凝固異常の是正が先である。", "B": "母乳をやめる必要はない。ビタミンKの補充で対応する。", "C": "Hb13.4g/dLで貧血はなく、輸血の適応がない。", "E": "低蛋白血症を補正しても出血は止まらない。"}'),
    ('115-F-44', '正答は E「地域包括支援センターに虐待の可能性について相談する。」。

新旧混在する皮下出血斑と打撲痕、口腔衛生の不良、脱水と栄養不良、服薬管理の破綻が揃っており、養護者による虐待(身体的虐待と介護等放棄)を疑う。高齢者虐待防止法により、疑いの段階で市町村または地域包括支援センターに相談・通報する。

出典：厚生労働省ホームページ 第115回医師国家試験 F044',
     '{"A": "処方管理だけを整えても虐待の状況は変わらない。", "B": "口腔ケアは必要だが、優先すべきは安全の確保である。", "C": "加害の疑いがある息子を同伴させるのは本人をさらに危険にさらす。", "D": "警察への保護依頼は生命に差し迫った危険がある場合で、まず通報先は市町村・地域包括支援センターである。"}'),
    ('115-F-48', '正答は A「経過観察」。

精巣容積は正常で恥毛も出現し、声変わりも始まっている。二次性徴はすでに進行しており、身長も−1.0SDに沿って伸びている。家族歴(母の初経が遅い)からも体質性の遅れと考えられ、経過観察でよい。

出典：厚生労働省ホームページ 第115回医師国家試験 F048',
     '{"B": "下垂体病変を疑う所見(視野障害、頭痛、他の下垂体機能低下)がない。", "C": "成長曲線がSDに沿っており、成長ホルモン分泌不全を疑う伸び率の低下がない。", "D": "甲状腺機能低下を示唆する症状や成長速度の低下がない。", "E": "骨年齢の評価は成長障害を疑う場合に行うもので、本例では必須でない。"}'),
    ('115-F-51', '正答は D「多発肋骨骨折」。

隣接する複数の肋骨がそれぞれ2か所以上で折れると、その部分が胸郭から分離して動揺胸郭(flail chest)となる。吸気で胸腔内が陰圧になると分離部が内側へ引き込まれ、前胸部が陥凹する奇異呼吸を示す。

出典：厚生労働省ホームページ 第115回医師国家試験 F051',
     '{"A": "血胸では呼吸音が減弱するが、胸壁が奇異性に動くことはない。", "B": "横隔膜損傷では腹部臓器が胸腔へ脱出するが、前胸部の陥凹は生じない。", "C": "横隔神経麻痺は横隔膜の挙上をきたすもので、胸壁の動きには影響しない。", "E": "心タンポナーデはショックと頸静脈怒張、心音減弱を示すが、胸壁の奇異運動は伴わない。"}'),
    ('116-A-4', '正答は D「スルホニル尿素薬」。

スルホニル尿素薬は血糖値と無関係に膵β細胞からのインスリン分泌を促すため、単剤でも低血糖を起こしうる。作用時間が長く、高齢者や腎機能低下例では遷延性低血糖に注意する。

出典：厚生労働省ホームページ 第116回医師国家試験 A004',
     '{"A": "DPP-4阻害薬はインクレチンを介した血糖依存性の作用で、単剤では低血糖を起こしにくい。", "B": "SGLT2阻害薬は尿糖排泄を増やす薬で、単剤での低血糖は少ない。", "C": "ビグアナイド薬は肝の糖新生を抑えるもので、インスリン分泌を促さない。", "E": "αグルコシダーゼ阻害薬は糖の吸収を遅らせるだけで、単剤では低血糖を起こしにくい。"}'),
    ('116-A-5', '正答は C「原疾患は拡張型心筋症が最も多い。」。

我が国の成人心臓移植の原疾患は拡張型心筋症が最も多く、次いで拡張相肥大型心筋症、虚血性心筋症の順である。

出典：厚生労働省ホームページ 第116回医師国家試験 A005',
     '{"A": "10年生存率は約90%で、国際的にみても良好である。", "B": "実施数は年間50〜100例程度にとどまる。", "D": "拒絶反応を防ぐため免疫抑制薬の生涯服用が必要である。", "E": "ドナー不足のため平均待機期間は3年を超えている。"}'),
    ('116-A-6', '正答は E「レニン・アンジオテンシン系抑制薬」。

レニン・アンジオテンシン系抑制薬(ACE阻害薬・ARB・ミネラルコルチコイド受容体拮抗薬)はアルドステロンの作用を弱め、集合管からのカリウム排泄を減らすため高カリウム血症を起こす。腎機能低下例で特に注意する。

出典：厚生労働省ホームページ 第116回医師国家試験 A006',
     '{"A": "β刺激薬はカリウムを細胞内へ移動させ、血清カリウムを下げる。", "B": "インスリンもカリウムを細胞内へ取り込ませ、高カリウム血症の治療に用いる。", "C": "ループ利尿薬は尿中カリウム排泄を増やし低カリウム血症をきたす。", "D": "グリチルリチンは偽アルドステロン症を起こし、低カリウム血症の原因となる。"}'),
    ('116-A-7', '正答は D「萎縮性胃炎」。

萎縮性胃炎では胃酸分泌が低下するため、逆流しても食道粘膜の傷害が起こりにくい。むしろ逆流性食道炎の頻度は下がる。

出典：厚生労働省ホームページ 第116回医師国家試験 A007',
     '{"A": "肥満は腹圧を高めて逆流を促す。誘因である。", "B": "高齢では下部食道括約筋の機能低下と食道裂孔ヘルニアが増える。誘因である。", "C": "亀背(円背)は腹圧を高め、食道裂孔ヘルニアも生じやすくする。誘因である。", "E": "カルシウム拮抗薬は下部食道括約筋を弛緩させる。誘因である。"}'),
    ('116-A-8', '正答は D「心室中隔の非対称性肥大」。

心室中隔の非対称性肥大は肥大型心筋症の所見である。心サルコイドーシスではむしろ心室中隔基部の菲薄化が特徴的で、肥大は示さない。

出典：厚生労働省ホームページ 第116回医師国家試験 A008',
     '{"A": "刺激伝導系に肉芽腫ができやすく、房室ブロックは初発症状として頻度が高い。", "B": "心筋の瘢痕を基質とする持続性心室頻拍がみられる。", "C": "心筋障害の進行により左室駆出率が低下する。", "E": "FDG-PETでの心筋への異常集積は活動性病変の評価に用いられる。"}'),
    ('116-A-9', '正答は D「有機リン剤」。

有機リン剤はコリンエステラーゼを阻害して中毒症状をきたす物質で、骨壊死との関連は知られていない。

出典：厚生労働省ホームページ 第116回医師国家試験 A009',
     '{"A": "多量飲酒は大腿骨頭壊死の代表的な危険因子である。", "B": "減圧症では骨内の血管が窒素気泡で閉塞し、骨壊死を起こす。", "C": "放射線照射は骨の微小循環を障害して放射線骨壊死を生じる。", "E": "副腎皮質ステロイドの全身投与は大腿骨頭壊死の最大の危険因子である。"}'),
    ('116-A-10', '正答は D「手指腫脹を伴う。」。

全身性強皮症では皮膚硬化の前段階として手指が腫れぼったくなる浮腫期(puffy finger)がみられ、Raynaud現象に手指腫脹を伴う。爪郭部の毛細血管異常や抗核抗体陽性も続発性を示唆する所見である。

出典：厚生労働省ホームページ 第116回医師国家試験 A010',
     '{"A": "続発性Raynaud現象も両側性に生じる。片側性なら胸郭出口症候群など局所の血管病変を疑う。", "B": "家族歴があるのは原発性(Raynaud病)の特徴である。", "C": "若年女性の発症は原発性に多い。続発性は比較的高齢での発症が多い。", "E": "血圧の左右差は鎖骨下動脈狭窄や大動脈炎症候群を示唆する所見である。"}'),
    ('116-A-11', '正答は E「物事に対するこだわりが弱い。」。

自閉スペクトラム症の中核症状は、社会的コミュニケーションの障害と、限定された反復的な行動・興味である。こだわりは弱いのではなく強いのが特徴である。

出典：厚生労働省ホームページ 第116回医師国家試験 A011',
     '{"A": "男児に多く、男女比はおよそ4:1とされる。", "B": "音や光、触覚などへの感覚過敏(あるいは鈍麻)を伴うことが多い。", "C": "対人的な相互交流の困難は中核症状である。", "D": "発達早期(就学前)から症状が現れることが診断の要件である。"}'),
    ('116-A-12', '正答は E「肺動脈性肺高血圧症を伴う呼吸不全」。

肺動脈性肺高血圧症は肺循環の圧が上がる病態で、体血圧の急激な上昇による臓器障害という高血圧緊急症の枠組みには当てはまらない。

出典：厚生労働省ホームページ 第116回医師国家試験 A012',
     '{"A": "急性大動脈解離は血圧の厳格な降圧を要する代表的な高血圧緊急症である。", "B": "褐色細胞腫クリーゼはカテコラミンの過剰放出による血圧急上昇で、高血圧緊急症である。", "C": "乳頭浮腫を伴う脳浮腫は高血圧性脳症で、高血圧緊急症である。", "D": "急激な後負荷増大による肺水腫も高血圧緊急症に含まれる。"}'),
    ('116-A-16', '正答は C「糖尿病網膜症の存在」。

糖尿病網膜症と糖尿病性腎症はいずれも高血糖による細小血管障害で、並行して進行する。網膜症が存在することは、蛋白尿の原因が糖尿病性腎症であることを最も強く支持する。腎生検が行えない場合の重要な手がかりになる。

出典：厚生労働省ホームページ 第116回医師国家試験 A016',
     '{"A": "家族歴は糖尿病そのもののなりやすさを示すが、蛋白尿の原因を特定しない。", "B": "抗GAD抗体陰性は1型糖尿病を否定するだけで、腎障害の原因とは無関係である。", "D": "高血糖の存在は糖尿病の診断根拠だが、蛋白尿の原因が糖尿病かどうかを示さない。", "E": "蛋白尿の量は原因を示さない。他の糸球体疾患でも同程度の蛋白尿は出る。"}'),
    ('116-A-18', '正答は A「入眠時に金縛りにあう。」。

日中の耐えがたい眠気と情動脱力発作があり、ナルコレプシーである。入眠時や覚醒時に体が動かせなくなる睡眠麻痺(金縛り)は入眠時幻覚とともに四徴の一つで、高率にみられる。

出典：厚生労働省ホームページ 第116回医師国家試験 A018',
     '{"B": "夜間せん妄はナルコレプシーの特徴ではない。", "C": "ナルコレプシーの睡眠発作は短時間眠るとすっきりするのが特徴で、眠気が残るのは睡眠時無呼吸症候群などである。", "D": "睡眠中のパニック発作はパニック症でみられる。", "E": "脚を動かしたい欲求はむずむず脚症候群(レストレスレッグス症候群)の症状である。"}'),
    ('116-A-25', '正答は C「プリックテストを行う。」。

特定の食物を摂った後に運動したときだけ症状が出る食物依存性運動誘発アナフィラキシーである。まず原因食物を確定させることが対応の出発点で、プリックテストと特異的IgEで評価する。

出典：厚生労働省ホームページ 第116回医師国家試験 A025',
     '{"A": "原因食物を摂らずに運動すれば発症しないため、部活動を一律にやめさせる必要はない。", "B": "原因が確定する前に食物を禁止するのは過剰であり、確定後も運動と組み合わせなければ摂取できることが多い。", "D": "食事一般を禁じるのではなく、原因食物と運動の組合せを避けるよう指導する。", "E": "運動前のステロイド内服に予防効果は確立していない。"}'),
    ('116-A-26', '正答は E「感染症の流行が終息するまで辛抱するよう励ます。」。

抑うつ気分、易疲労、集中力低下が3か月続き、寝酒という不適切な対処も始まっている。状況が改善するまで我慢するよう励ますのは、必要な評価と介入を遅らせるだけで適切でない。

出典：厚生労働省ホームページ 第116回医師国家試験 A026',
     '{"A": "うつ病の可能性があり、専門医への受診勧奨は適切である。", "B": "寝酒は睡眠を浅くし抑うつも悪化させるため、やめるよう指導するのは適切である。", "C": "本人の同意を得たうえで業務量や環境の調整を上司と相談するのは産業医の役割である。", "D": "仕事の内容と進め方を具体的に聴き取ることは、就業上の措置を考えるうえで必要である。"}'),
    ('116-A-29', '正答は A「書痙」。

字を書くときにだけ手指が不随意に強く屈曲し、他の日常動作には支障がない。特定の課題でのみ症状が出る課題特異性の局所ジストニアで、書痙である。

出典：厚生労働省ホームページ 第116回医師国家試験 A029',
     '{"B": "痙性斜頸は頸部の筋が不随意に収縮して頭位が傾く局所ジストニアである。", "C": "本態性振戦は姿勢時・動作時の律動的な振戦で、字が震えることはあっても手指の異常な屈曲肢位はとらない。", "D": "ジスキネジアは抗精神病薬などによる不随意運動で、書字に限局しない。", "E": "アステリキシスは羽ばたき振戦で、肝性脳症などの代謝性脳症でみられる。"}'),
    ('116-A-30', '正答は A「尿潜血3+」。

側腹部から始まり下方へ移動する数分周期の激痛と悪心・嘔吐は、尿管結石による疝痛発作の典型である。結石が尿路粘膜を傷つけるため、尿潜血が強陽性となる。

出典：厚生労働省ホームページ 第116回医師国家試験 A030',
     '{"B": "閉塞は片側なので水腎症も片側にとどまる。", "C": "赤血球円柱は糸球体由来の血尿を示す所見で、尿路結石では出現しない。", "D": "対側の腎が保たれていれば血清クレアチニンは上昇しない。", "E": "ネフローゼ域の蛋白尿は糸球体疾患の所見で、結石では生じない。"}'),
    ('116-A-32', '正答は E「プロスタグランディンE1の投与」。

高濃度酸素を投与してもチアノーゼが改善せず、右室から肺動脈への駆出がなく動脈管経由でのみ肺血流が保たれている。動脈管依存性肺循環の病態で、プロスタグランジンE1を投与して動脈管の開存を維持することが救命につながる。

出典：厚生労働省ホームページ 第116回医師国家試験 A032',
     '{"A": "利尿薬は循環血液量を減らし、動脈管を通る肺血流をさらに減らす。", "B": "ドパミンは血圧を保つ助けにはなるが、肺血流の確保にはならない。", "C": "ジゴキシンは心不全の治療薬で、この病態の本質に働かない。", "D": "酸素は動脈管を収縮させる方向に働くため、動脈管依存性の病態では高濃度酸素の継続は有害となりうる。"}'),
    ('116-A-38', '正答は E「持続硬膜外麻酔による鎮痛を行う。」。

開腹手術後の疼痛管理として持続硬膜外麻酔を用いると、鎮痛が良好で腸管運動の回復も早く、早期離床につながる。術後回復力強化(ERAS)の中核的な要素である。

出典：厚生労働省ホームページ 第116回医師国家試験 A038',
     '{"A": "固形物は誤嚥防止のため手術の6時間前までとする。2時間前まで許容されるのは清澄水である。", "B": "術後は早期離床が原則で、3日間のベッド上安静は血栓症と肺合併症を増やす。", "C": "腸管の手術後も早期に経口摂取を再開するのが標準である。", "D": "術中は加温して低体温を防ぐ。低体温は創感染と出血を増やす。"}'),
    ('116-A-40', '正答は B「Na+154mEq/L、Cl−154mEq/L」。

炎天下の激しい運動の後に筋痛と赤褐色尿が出現し、尿潜血が強陽性なのに沈渣の赤血球が少ないことからミオグロビン尿である。労作性横紋筋融解症で、急性腎障害を防ぐため生理食塩液(Na 154mEq/L、Cl 154mEq/L)を大量に投与して尿量を確保する。

出典：厚生労働省ホームページ 第116回医師国家試験 A040',
     '{"A": "5%ブドウ糖液は代謝されると自由水となり細胞内へ分布するため、細胞外液量を保てない。", "C": "カリウムを含む輸液は、壊死した筋から放出されるカリウムに上乗せして高カリウム血症を悪化させる。", "D": "同様にカリウムを含んでおり、この病態では避ける。", "E": "ナトリウム濃度が低く低張で、細胞外液の補充に適さない。"}'),
    ('116-A-43', '正答は C「ガストリン」。

下垂体腺腫の既往に加えて高カルシウム血症と低リン血症(副甲状腺機能亢進症)があり、繰り返す難治性の十二指腸潰瘍を伴う。多発性内分泌腫瘍症1型に伴うガストリノーマ(Zollinger-Ellison症候群)を疑い、血清ガストリンを測定する。

出典：厚生労働省ホームページ 第116回医師国家試験 A043',
     '{"A": "TSHの異常では難治性潰瘍も高カルシウム血症も説明できない。", "B": "ACTH過剰(Cushing病)は下垂体腺腫の一型だが、消化性潰瘍の反復と高カルシウム血症を説明しない。", "D": "カテコラミン過剰(褐色細胞腫)は発作性高血圧が主症状である。本例は血圧98/62mmHgと低めである。", "E": "テストステロンはこの病像に関与しない。"}'),
    ('116-A-44', '正答は E「プロラクチン」。

無月経に両側の乳汁分泌を伴い、乳房発育不良、子宮の萎縮、基礎体温一相性と低エストロゲン状態を示している。高プロラクチン血症がゴナドトロピンの分泌を抑えている病態で、プロラクチンが高値となる。

出典：厚生労働省ホームページ 第116回医師国家試験 A044',
     '{"A": "GH過剰では先端巨大症の身体所見が現れる。", "B": "卵巣性無月経ならFSHが上昇するが、その場合は乳汁分泌を伴わない。", "C": "原発性甲状腺機能低下症ではTRH増加を介してプロラクチンも上がりうるが、甲状腺腫大がなく本例の主座はプロラクチンである。", "D": "ACTHの異常はCushing病を示唆し、乳汁分泌の説明にならない。"}'),
    ('116-A-46', '正答は B「ブドウ糖負荷試験」。

顔貌の変化、手足の増大、手根管症候群、高血圧、耐糖能異常が揃っており先端巨大症を疑う。確定診断には75g経口ブドウ糖負荷試験を行い、正常なら抑制されるはずのGHが抑制されないことを確認する。

出典：厚生労働省ホームページ 第116回医師国家試験 A046',
     '{"A": "GHRH負荷試験は異所性GHRH産生腫瘍の検索などに用いる特殊な検査である。", "C": "インスリン負荷試験はGH分泌不全や副腎皮質機能低下の評価に用いる。", "D": "グルカゴン負荷試験は膵β細胞機能や褐色細胞腫の評価に用いる。", "E": "デキサメタゾン抑制試験はCushing症候群の診断に用いる。"}'),
    ('116-A-47', '正答は E「被害の状況を本人から再度聴き取って確認する。」。

被害の状況を繰り返し語らせることは、体験を再体験させて心的外傷を深める二次被害になる。事情聴取は警察が行っており、医師は診療に必要な範囲にとどめる。

出典：厚生労働省ホームページ 第116回医師国家試験 A047',
     '{"A": "性感染症の検査と予防内服は必要な医療である。", "B": "最終月経から12日で妊娠しうる時期にあたり、緊急避妊薬の提案は適切である。", "C": "診察は本人の同意を得て行う。適切である。", "D": "証拠保全のための検体採取は、本人の同意のうえで行う必要な対応である。"}'),
    ('116-A-48', '正答は E「「高圧浣腸で整復できなければ開腹手術になります」」。

間欠的な啼泣、嘔吐、血便、右上腹部の腫瘤、超音波のtarget signから腸重積症である。まず高圧浣腸(注腸)による非観血的整復を試み、整復できなければ、あるいは穿孔や腹膜炎があれば開腹手術となる。この見通しを保護者に伝える。

出典：厚生労働省ホームページ 第116回医師国家試験 A048',
     '{"A": "整復できても10%前後に再発があるため、通常は入院して経過を観察する。", "B": "感染症ではなく抗菌薬の適応がない。", "C": "腹腔内遊離ガス像がなく腹膜炎の所見もない。直ちに手術と決まったわけではない。", "D": "すでに超音波で診断が確定しており、グリセリン浣腸で確認する段階ではない。"}'),
    ('116-A-52', '正答は D「生理食塩液での洗眼」。

アルカリは蛋白を融解しながら組織深部へ進行するため、化学眼外傷のなかでも予後が悪い。診断や他の処置に先んじて、生理食塩液などで大量かつ長時間の洗眼を直ちに開始する。

出典：厚生労働省ホームページ 第116回医師国家試験 A052',
     '{"A": "鎮痛は必要だが、洗眼より優先されるものではない。", "B": "酸で中和しようとすると中和熱が発生し、組織障害をさらに広げる。", "C": "感染対策は洗眼の後に考えることで、初期対応ではない。", "E": "高浸透圧利尿薬は眼圧上昇に対する薬剤で、まず行う処置ではない。"}'),
    ('116-A-55', '正答は E「HBワクチン及び抗HBsヒト免疫グロブリンの投与」。

曝露源がHBs抗原陽性で、受傷者はHBs抗体を持たない。曝露直後に抗HBsヒト免疫グロブリンで受動免疫を与え、同時にHBワクチンを開始して能動免疫を獲得させるのが標準的対応である。

出典：厚生労働省ホームページ 第116回医師国家試験 A055',
     '{"A": "感染リスクが高く、無投薬は許されない。", "B": "ワクチン単独では抗体産生までに時間がかかり、初期の感染を防げない。", "C": "核酸アナログ製剤は慢性B型肝炎の治療薬で、曝露後予防には用いない。", "D": "免疫グロブリン単独では効果が一時的で、長期の防御が得られない。"}'),
    ('116-A-57', '正答は A「虐待」。

新旧混在する皮下出血、硬膜下血腫とびまん性脳浮腫、大腿骨と上腕骨の骨折という説明のつかない多発外傷があり、健診も受けていない。身体的虐待による死亡を第一に考え、警察への届出と司法解剖が必要になる。

出典：厚生労働省ホームページ 第116回医師国家試験 A057',
     '{"B": "てんかんでは多発骨折や新旧混在する皮下出血を説明できない。", "C": "2か月児は寝返りもできず、大腿骨・上腕骨骨折を伴う事故は起こりにくい。説明のつかない受傷機転自体が虐待を示唆する。", "D": "熱性けいれんは発熱を伴い、外傷所見とは無関係である。", "E": "細菌性髄膜炎でも骨折や新旧混在の皮下出血は生じない。"}'),
    ('116-A-64', '正答は E「がん治療を継続しながら膝の手術治療」。

余命が2年以上見込まれ、膝の変形と可動域制限で歩行が制限されている。癌の治療を続けながら人工膝関節置換術を行い、残された時間の生活の質を保つのが妥当である。癌があること自体は手術の禁忌ではない。

出典：厚生労働省ホームページ 第116回医師国家試験 A064',
     '{"A": "どちらも放棄する理由がない。", "B": "癌治療を中断する医学的理由がない。", "C": "同様に癌治療の終了は不要である。", "D": "保存治療では高度の変形と可動域制限による歩行障害は改善しない。"}'),
    ('116-B-1', '正答は D「患者に発表に関する同意を取る。」。

症例報告であっても患者の情報を公表する以上、本人(または代諾者)から発表についての同意を得ることが必要である。学会の指針でも同意の取得が前提とされている。

出典：厚生労働省ホームページ 第116回医師国家試験 B001',
     '{"A": "国籍は医学的に必要でない限り記載せず、個人の特定にもつながる。", "B": "日付を正確に書くと受診記録と照合されて個人が特定されうるため、時系列は相対表記にする。", "C": "顔全体が判別できる写真は個人を特定するため、必要な範囲に限りマスクするなどの配慮が要る。", "E": "イニシャルも個人の特定につながるため、記号(症例1など)に置き換える。"}'),
    ('116-B-2', '正答は C「頸静脈の怒張 — 右心不全」。

頸静脈の怒張は右房圧の上昇を意味し、右心不全の重要な身体所見である。半座位で観察し、他の所見と併せて評価する。

出典：厚生労働省ホームページ 第116回医師国家試験 B002',
     '{"A": "喘息で聴かれるのは呼気性の笛声音(wheeze)である。coarse cracklesは肺炎や気管支拡張症でみられる。", "B": "気胸では患側の打診で鼓音となる。濁音は胸水や無気肺である。", "D": "呼吸不全はPaO2 60Torr以下と定義され、SpO2ではおよそ90%以下にあたる。95%は呼吸不全ではない。", "E": "Cheyne-Stokes呼吸は心不全や脳障害でみられる周期性呼吸で、上気道閉塞の所見ではない。"}'),
    ('116-B-4', '正答は C「開始時のCRP値で投与期間を決定する。」。

抗菌薬の投与期間は疾患ごとに標準が定まっており、CRPの値で決めるものではない。CRPは炎症の指標にすぎず、これを基準にすると不要に長期の投与になる。

出典：厚生労働省ホームページ 第116回医師国家試験 B004',
     '{"A": "起炎菌の同定のため培養検体を採ってから投与を開始する。正しい。", "B": "時間依存性か濃度依存性かなど薬物動態・薬力学に応じて用量と間隔を決める。正しい。", "D": "髄膜炎や骨髄炎など、目的臓器への移行性を考慮して薬剤を選ぶ。正しい。", "E": "感受性判明後は狭域薬へ変更する(de-escalation)。正しい。"}'),
    ('116-B-5', '正答は D「鼻指鼻試験」。

鼻指鼻試験は患者が指示に従って動くことが前提の協調運動検査で、意識障害があると実施できない。

出典：厚生労働省ホームページ 第116回医師国家試験 B005',
     '{"A": "腱反射は患者の協力がなくても打腱器で誘発できる。", "B": "項部硬直は他動的に頸部を屈曲させて確認でき、意識障害があっても評価できる。", "C": "対光反射は光刺激への反応で、意識障害の評価そのものに用いる。", "E": "膝立て試験は他動的に立てた下肢がどう倒れるかを見るもので、意識障害でも実施できる。"}'),
    ('116-B-6', '正答は D「医療安全支援センター」。

医療安全支援センターは医療法に基づき都道府県等に設置され、患者・家族からの医療に関する相談に応じ、助言や情報提供を行う。主治医以外に相談したいときの窓口となる。

出典：厚生労働省ホームページ 第116回医師国家試験 B006',
     '{"A": "保健所は感染症対策や難病支援など公衆衛生を担う。", "B": "福祉事務所は生活保護など福祉の窓口である。", "C": "市町村保健センターは健康診査や健康相談の拠点である。", "E": "地域包括支援センターは高齢者の総合相談窓口である。"}'),
    ('116-B-8', '正答は B「尿濃縮力低下」。

加齢に伴い髄質の浸透圧勾配が保ちにくくなり、尿濃縮力が低下する。このため脱水になりやすく、夜間尿も増える。

出典：厚生労働省ホームページ 第116回医師国家試験 B008',
     '{"A": "腎血流量は加齢とともに減少する。", "C": "糸球体濾過量も加齢とともに低下する。", "D": "硬化糸球体の数は加齢とともに増加する。", "E": "機能するネフロンの数は減少する。"}'),
    ('116-B-9', '正答は E「症状が患者の生活に及ぼしている影響を聞く。」。

症状が生活にどう影響しているかを聞くことで、患者の困りごとの中心が分かり、治療目標を共有できる。患者中心の医療面接の基本である。

出典：厚生労働省ホームページ 第116回医師国家試験 B009',
     '{"A": "専門用語は理解を妨げる。平易な言葉に置き換える。", "B": "患者の言葉を繰り返す(反復)ことは、聞いていることを示し語りを促す技法である。", "C": "冒頭は開かれた質問で自由に語ってもらい、その後に閉じられた質問で絞り込む。", "D": "画面を見続けると視線が合わず、聴いてもらえていないという印象を与える。"}'),
    ('116-B-10', '正答は E「結核患者の医療費の公費負担は感染症法に規定されている。」。

結核患者の医療費の公費負担は、感染症法(第37条・第37条の2)に規定されている。入院勧告による入院は全額、通院医療は95%が公費で負担される。

出典：厚生労働省ホームページ 第116回医師国家試験 B010',
     '{"A": "診療録の保存義務期間は完結の日から5年間である。", "B": "国民健康保険組合の被保険者数は300万人程度で、6千万人には遠く及ばない。", "C": "国民医療費は2000年の約30兆円から40兆円台へ増えたが、3倍にはなっていない。", "D": "第1号被保険者(65歳以上)より第2号被保険者(40〜64歳)のほうが多い。"}'),
    ('116-B-11', '正答は C「唾液の流涎」。

唾液を飲み込めずに流涎するのは、咽頭・喉頭の高度な腫脹や疼痛で嚥下できないことを意味する。急性喉頭蓋炎や咽後膿瘍など、短時間で気道閉塞に至る病態を示唆する危険な徴候である。

出典：厚生労働省ホームページ 第116回医師国家試験 B011',
     '{"A": "喀痰は下気道の症状で、咽頭痛の緊急性を示すものではない。", "B": "膿性鼻汁は副鼻腔炎を示唆するが緊急性は低い。", "D": "顎下リンパ節の圧痛は咽頭炎に一般的で、それ自体は緊急性を示さない。", "E": "高熱だけでは気道の危険を判断できない。"}'),
    ('116-B-12', '正答は C「Duchenne型筋ジストロフィー」。

Duchenne型筋ジストロフィーは乳児期には目立たず、3〜5歳ごろに転びやすさや登はん性起立(Gowers徴候)で気づかれる。X連鎖潜性遺伝で、血清CKの著明高値が手がかりになる。

出典：厚生労働省ホームページ 第116回医師国家試験 B012',
     '{"A": "Werdnig-Hoffmann病(脊髄性筋萎縮症I型)は生後6か月までに発症する。", "B": "新生児一過性重症筋無力症は母体からの抗体移行によるもので、生直後に発症し数週で消退する。", "D": "福山型先天性筋ジストロフィーは乳児期から筋緊張低下と発達遅滞を示す。", "E": "先天性筋強直性ジストロフィーは新生児期から重度の筋緊張低下と呼吸障害を示す。"}'),
    ('116-B-13', '正答は D「それぞれの高齢者の習慣や生活ペースに合わせた介護を行う。」。

生活歴や習慣は人によって異なり、それに合わせて介護を組み立てることが個性と尊厳の尊重にあたる。施設や介護者の都合に合わせさせるのではない。

出典：厚生労働省ホームページ 第116回医師国家試験 B013',
     '{"A": "「ちゃん」づけは相手を子ども扱いすることになり、尊厳を損なう。", "B": "体幹をバンドで固定するのは身体拘束で、原則として認められない。", "C": "排泄について大声で指図することは羞恥心を傷つける。", "E": "移動が難しいというだけで施設入所を勧めるのは、本人の希望を無視した対応である。"}'),
    ('116-B-14', '正答は D「フレイル — 高齢者の強い咀嚼力」。

フレイルの危険因子は咀嚼力の低下である。噛む力が弱まると食べられるものが減り、低栄養からサルコペニア・フレイルへ進む。強い咀嚼力は保護的に働く。

出典：厚生労働省ホームページ 第116回医師国家試験 B014',
     '{"A": "飲酒習慣は乳癌の危険因子として確立している。", "B": "速い摂食速度は満腹感が得られる前に食べ過ぎるため、肥満の危険因子である。", "C": "熱い飲食物は食道粘膜を傷つけ、食道癌の危険因子となる。", "E": "若年期の過度な食事制限は最大骨量の獲得を妨げ、将来の骨粗鬆症につながる。"}'),
    ('116-B-15', '正答は D「呼吸数24/分」。

成人の安静時呼吸数は12〜20/分で、24/分は頻呼吸にあたる。呼吸数はもっとも早期に異常を示すバイタルサインで、敗血症や呼吸不全の指標として重要である。

出典：厚生労働省ホームページ 第116回医師国家試験 B015',
     '{"A": "腋窩体温36.2°Cは正常範囲である。", "B": "脈拍96/分は正常範囲(60〜100/分)の上限内である。", "C": "血圧112/70mmHgは正常である。", "E": "SpO2 97%は正常である。"}'),
    ('116-B-16', '正答は E「チューブ先端位置をエックス線写真で確認する。」。

胃管の先端が胃内にあることを最も確実に示せるのはエックス線写真である。気管に誤挿入したまま栄養剤を注入すると致命的になるため、初回留置時には必ず画像で確認する。

出典：厚生労働省ホームページ 第116回医師国家試験 B016',
     '{"A": "リドカインの塗布は必須ではなく、咽頭反射を抑えて誤嚥のリスクを高める面もある。", "B": "頸部を前屈させることで食道側へ入りやすくなる。後屈させると気管に入りやすい。", "C": "成人では鼻孔から45〜55cm程度必要で、35cmでは食道内にとどまる。", "D": "液体を注入して確認するのは危険である。誤挿入なら気道に液体を入れることになる。"}'),
    ('116-B-17', '正答は C「2:15」。

小児(乳児を含む)の蘇生を医療者2名で行う場合、胸骨圧迫と人工呼吸の比は15:2とする。1名で行う場合や成人では30:2である。

出典：厚生労働省ホームページ 第116回医師国家試験 B017',
     '{"A": "1:3という比は用いない。", "B": "人工呼吸1回に対し胸骨圧迫15回という比は用いない。", "D": "30:2は成人、あるいは小児を救助者1名で行う場合の比である。", "E": "3:30という比は用いない。"}'),
    ('116-B-19', '正答は E「乳頭の色素沈着」。

乳頭・乳輪の色素沈着は妊娠やホルモンの影響による生理的変化で、悪性を示唆する所見ではない。

出典：厚生労働省ホームページ 第116回医師国家試験 B019',
     '{"A": "えくぼ徴候(dimpling)はCooper靱帯への浸潤による皮膚の陥凹で、乳癌を示唆する。", "B": "橙皮様皮膚は皮下リンパ管の閉塞による浮腫で、進行乳癌や炎症性乳癌でみられる。", "C": "乳頭のびらんはPaget病を疑わせる所見である。", "D": "血性の乳頭分泌は乳管内病変(乳管内乳頭腫や乳癌)を示唆する。"}'),
    ('116-B-20', '正答は B「1」。

徒手筋力テストで、関節の動きは起こらないが筋の収縮を触知・視認できる状態は1(trace)と評価する。

出典：厚生労働省ホームページ 第116回医師国家試験 B020',
     '{"A": "0は筋収縮がまったく認められない状態である。", "C": "2は重力を除けば全可動域を動かせる状態である。", "D": "3は重力に抗して全可動域を動かせる状態である。", "E": "4は重力に抗し、ある程度の抵抗にも打ち勝てる状態である。"}'),
    ('116-B-21', '正答は B「グルコース」。

髄液のグルコースは血糖のおよそ60%が正常で、絶対値だけでは評価できない。同時に測った血糖と比べて低下しているかどうかを見ることで、細菌性・結核性・真菌性髄膜炎(髄液糖低下)とウイルス性(正常)を鑑別する。

出典：厚生労働省ホームページ 第116回医師国家試験 B021',
     '{"A": "髄液アルブミンは血液脳関門の評価に用いるが、血液との比較が必須の項目ではない。", "C": "好中球数は髄液中の絶対数と分画で評価する。", "D": "髄液蛋白は基準値との比較で評価する。", "E": "白血球数も髄液中の値そのもので評価する。"}'),
    ('116-B-22', '正答は C「遺伝子工学によるヒトインスリン製剤の作製」。

遺伝子組換え技術によるヒトインスリン製剤の作製は1980年代で、選択肢のなかで最も新しい。ランゲルハンス島の発見(1869年)、膵摘出犬の実験(1889年)、インスリンの精製(1921年)、アミノ酸配列と立体構造の解明(1950〜60年代)の順に続く。

出典：厚生労働省ホームページ 第116回医師国家試験 B022',
     '{"A": "ランゲルハンスによる膵島の発見は1869年で最も古い。", "B": "BantingとBestによる動物膵からのインスリン抽出・精製は1921年である。", "D": "Sangerによるアミノ酸配列の決定は1950年代、Hodgkinによる立体構造の解明は1960年代である。", "E": "MeringとMinkowskiによる膵摘出犬の実験は1889年である。"}'),
    ('116-B-23', '正答は E「「今困っていることについてもっと詳しく教えていただけますか」」。

開放型質問は「はい・いいえ」や特定の情報では答えられず、患者が自由に語れる問いである。「今困っていることについてもっと詳しく教えていただけますか」がこれにあたる。

出典：厚生労働省ホームページ 第116回医師国家試験 B023',
     '{"A": "年齢を尋ねる質問は特定の情報を求める閉鎖型である。", "B": "左右差の有無を問うのは閉鎖型である。", "C": "時期を問うのも答えの範囲が限定される閉鎖型である。", "D": "発作性夜間呼吸困難の有無を問うのは閉鎖型である。"}'),
    ('116-B-24', '正答は A「検査入院では記載を省略できる。」。

退院時要約は入院の目的にかかわらず作成するもので、検査入院だからといって省略できない。次の診療にとって必要な記録である。

出典：厚生労働省ホームページ 第116回医師国家試験 B024',
     '{"B": "入院中の経過・検査・治療・転帰をまとめたものである。正しい。", "C": "退院後の診療に用いるため、遅滞なく記載することが求められる。正しい。", "D": "退院後14日以内の記載が診療録管理体制加算の要件となっている。正しい。", "E": "医師事務作業補助者が代行入力し、医師が内容を確認して承認する運用は認められている。正しい。"}'),
    ('116-B-25', '正答は E「橈骨神経」。

飲酒後に肘掛けへ上腕を長時間圧迫した後に手関節と手指MP関節の伸展ができなくなっており、下垂手である。上腕骨の橈骨神経溝で橈骨神経が圧迫された麻痺(いわゆるSaturday night palsy)である。手背の感覚鈍麻も橈骨神経の支配領域に一致する。

出典：厚生労働省ホームページ 第116回医師国家試験 B025',
     '{"A": "腋窩神経の障害では三角筋麻痺による肩関節外転障害と肩外側の感覚障害が生じる。", "B": "筋皮神経の障害では肘屈曲(上腕二頭筋)の障害と前腕外側の感覚障害が生じる。", "C": "尺骨神経の障害では鷲手となり、小指・環指尺側の感覚障害を伴う。", "D": "正中神経の障害では猿手となり、母指球の萎縮と橈側3指半の感覚障害を伴う。"}'),
    ('116-B-26', '正答は D「肺血栓塞栓症」。

骨盤内手術後で臥床していた患者が、離床して動いた直後に突然の呼吸困難と低酸素血症をきたしている。呼吸音は正常で、肺血栓塞栓症を第一に考える。手術・臥床・悪性疾患などの危険因子と発症の契機が手がかりになる。

出典：厚生労働省ホームページ 第116回医師国家試験 B026',
     '{"A": "気道異物では吸気性の喘鳴や咳嗽を伴い、突然の窒息感を訴える。", "B": "気管支喘息では呼気性喘鳴を聴取し、喫煙歴や既往が背景にあることが多い。", "C": "急性左心不全では湿性ラ音を聴取し、起坐呼吸となる。呼吸音は正常でない。", "E": "特発性肺線維症は慢性に進行し、fine cracklesとばち指を伴う。突然発症しない。"}'),
    ('116-B-28', '正答は B「患者の意向」。

改訂長谷川式22点で意思決定能力は保たれており、本人が告知を望み積極的治療を望まないと明確に意思表示している。治療方針は本人の意向を最も重視して決める。

出典：厚生労働省ホームページ 第116回医師国家試験 B028',
     '{"A": "年齢だけで治療方針を決めることはできない。", "C": "家族の意向は考慮するが、本人の明示の意思には優先しない。", "D": "医師の考えは選択肢を示すためのもので、本人の意思を上書きできない。", "E": "認知機能は意思決定能力の判断材料だが、22点で能力は保たれており、これ自体が方針を決める因子ではない。"}'),
    ('116-B-29', '正答は C「かかりつけの整形外科担当医へ情報提供」。

骨形成不全症で年1回整形外科を受診しており、今回の手術と入院の経過をかかりつけの整形外科医へ情報提供することが、退院後の継続的な診療に必要である。

出典：厚生労働省ホームページ 第116回医師国家試験 B029',
     '{"A": "術後経過は良好で良性であり、特別な安静指導を要さない。", "B": "すでにボランティアによる支援体制があり、新たな機能障害も生じていない。", "D": "電動車いすを含む必要な福祉器具はすでに使用しており、新規の手配は不要である。", "E": "入院中に新たな機能障害はなく、在宅リハビリテーションの適応がない。"}'),
    ('116-B-30', '正答は C「離床センサーの使用」。

夜間にトイレへ行こうとして転倒しており、離床センサーを用いて起き上がりを早期に把握し、介助に入れるようにするのが妥当である。行動を制限せずに安全を高める方法である。

出典：厚生労働省ホームページ 第116回医師国家試験 B030',
     '{"A": "ベンゾジアゼピン系薬剤は高齢者の転倒とせん妄の危険因子で、追加はむしろ有害である。減量・中止を検討する。", "B": "身体拘束は原則として認められず、せん妄や廃用を悪化させる。", "D": "転倒は事故であり、家族への報告は速やかに行う。", "E": "排尿のためだけの尿道カテーテル留置は尿路感染とADL低下を招き、適応がない。"}'),
    ('116-B-31', '正答は B「「あなたが承諾した方に病状をお話しします」」。

診療情報を誰に伝えるかは患者本人が決める。本人が承諾した相手にのみ説明するという方針を伝えるのが正しい。

出典：厚生労働省ホームページ 第116回医師国家試験 B031',
     '{"A": "主治医に勤務先へ病状を報告する義務はない。", "C": "病状を家族に伝えないことと、治療法の選択とは無関係である。", "D": "血縁者であっても本人の同意なく病状を伝えることはできない。", "E": "意思決定能力のある成人では本人の同意で足り、血縁者の同意は不要である。"}'),
    ('116-B-33', '正答は C「血糖値の日内変動を測定」。

妊娠中の随時尿糖陽性に加えて空腹時血糖132mg/dLと高値である。この値は妊娠中の明らかな糖尿病(overt diabetes in pregnancy)の基準を満たし、負荷試験は不要で危険でもある。まず血糖の日内変動を測って治療方針を決める。

出典：厚生労働省ホームページ 第116回医師国家試験 B033',
     '{"A": "24時間蓄尿は腎症の評価には使えるが、血糖管理の判断に直接つながらない。", "B": "経口血糖降下薬は妊娠中には原則用いない。", "D": "インスリン療法が必要になる可能性は高いが、まず血糖の推移を把握してから量を決める。", "E": "空腹時血糖が126mg/dL以上あり、負荷試験は高血糖を助長するため行わない。"}'),
    ('116-B-35', '正答は D「家族の面会制限」。

緩和ケアでは家族との時間を保つことが大切で、面会を制限する理由はない。むしろ家族が過ごしやすい環境を整える。

出典：厚生労働省ホームページ 第116回医師国家試験 B035',
     '{"A": "低酸素血症による呼吸困難を和らげるため酸素投与は継続する。適切である。", "B": "室温や湿度、風の当たり方など環境の調整は呼吸困難の緩和に有効である。", "C": "オピオイドは呼吸困難の緩和に有効で、非癌の終末期でも用いられる。", "E": "マッサージは苦痛の緩和と安楽に寄与する。"}'),
    ('116-B-42', '正答は A「搬入後直ちに。」。

止血帯（駆血）は血流を止めるので、長く続けば末梢の筋や神経が不可逆的に傷む。受傷から既に80分が経っており、搬入後は直ちに外して出血の有無を見直し、出血していれば創部の直接圧迫に切り替える。

出典：厚生労働省ホームページ 第116回医師国家試験 B042',
     '{"B": "画像評価を待つ分だけ阻血時間が延びる。止血帯を外してからでも評価できる。", "C": "血液検査の結果を待つ理由がなく、その間も阻血が続く。", "D": "抗菌薬の投与と止血帯の解除は独立した処置で、待つ必要がない。", "E": "手術開始まで置けば阻血時間が最も長くなり、組織壊死の危険が高い。"}'),
    ('116-B-44', '正答は C「大動脈弁狭窄症」。

胸骨右縁第2肋間を最強点とし頸部へ放散する駆出性収縮期雑音は、大動脈弁狭窄症に特徴的である。労作時の胸部圧迫感（狭心症）と息切れ（心不全）が現れており、症状が出た大動脈弁狭窄症は予後が急に悪くなるため、弁置換やTAVIの検討に進む。

出典：厚生労働省ホームページ 第116回医師国家試験 B044',
     '{"A": "肥大型心筋症の収縮期雑音は胸骨左縁が最強点で頸部へは放散しにくく、Valsalva手技で増強する。", "B": "動脈管開存症は収縮期・拡張期を通じた連続性雑音を呈する。", "D": "心房中隔欠損症はII音の固定性分裂を伴い、雑音の最強点は胸骨左縁第2肋間である。", "E": "僧帽弁閉鎖不全症は心尖部を最強点とする全収縮期雑音で、腋窩へ放散する。"}'),
    ('116-B-45', '正答は E「MIBG心筋シンチグラフィの所見」。

設問は治療方針の決定に役立つ情報に「含まれない」ものを選ぶもの。MIBG心筋シンチグラフィは心臓の交感神経機能をみる検査で、Lewy小体病の診断や心不全の予後評価に用いる。大動脈弁狭窄症の治療方針を決める材料にはならない。

出典：厚生労働省ホームページ 第116回医師国家試験 B045',
     '{"A": "症状の有無は介入の時期を決める最も重要な情報である。", "B": "併存疾患は外科的弁置換とTAVIのどちらを選ぶかに直結する。", "C": "心エコーの弁口面積や圧較差で重症度が決まる。", "D": "心臓カテーテル検査で冠動脈病変の有無を確かめ、冠動脈バイパスの同時施行を検討する。"}'),
    ('116-B-46', '正答は C「研究段階の医療の概要」。

設問は「省略できる」説明を選ぶもの。医師が説明すべきなのは、現在の病状と診断名、これから行う検査や処置の内容と危険性である。研究段階の医療は確立した標準治療ではなく、この時点で必ず説明しなければならないものではない。

出典：厚生労働省ホームページ 第116回医師国家試験 B046',
     '{"A": "現在の病状は、患者が自分の状態を理解するための前提であり省略できない。", "B": "診断名を伝えることは、患者が納得して治療を選ぶ出発点になる。", "D": "緊急に行う処置の概要と危険性は、同意を得るために欠かせない。", "E": "これから行う検査の概要と危険性も、同意を得るために必要である。"}'),
    ('116-B-48', '正答は A「気管挿管」。

心拍は再開したがJCS III-300で舌根が沈下しており、バッグバルブマスクによる換気でもSpO2は92%にとどまる。自発呼吸に頼れない状態なので、まず気管挿管で気道を確保し、確実な換気と誤嚥の防止を図る。

出典：厚生労働省ホームページ 第116回医師国家試験 B048',
     '{"B": "アドレナリンの筋注はアナフィラキシーの適応で、自己心拍が再開している本例には当たらない。", "C": "副腎皮質ステロイドの適応となる病態がない。", "D": "グルコン酸カルシウムは高カリウム血症などで用いるが、それを示す所見がない。", "E": "心電図モニターは洞調律で、電気ショックの適応となる心室細動や無脈性心室頻拍ではない。"}'),
    ('116-C-1', '正答は D「男性では膀胱留置カテーテルを下腹部に固定する。」。

男性では陰茎を頭側に向けて下腹部にカテーテルを固定する。陰茎陰囊角で屈曲したまま留置すると、その部位に圧迫壊死が起き尿道皮膚瘻を生じうる。

出典：厚生労働省ホームページ 第116回医師国家試験 C001',
     '{"A": "胃瘻を造設しても嚥下機能が保たれていれば経口摂取を併用でき、控える必要はない。", "B": "中心静脈栄養中も日常生活や体動は制限しない。制限は廃用を招く。", "C": "円座は接触部の圧を高めて褥瘡を悪化させるため、現在は用いない。", "E": "気管切開下でも、切開部の防水など工夫すれば入浴は可能である。"}'),
    ('116-C-2', '正答は D「タンパク質 : 0.8g/kg/日」。

低栄養のある高齢者では、筋肉量の維持のため蛋白質を1.0〜1.2g/kg/日程度確保する。腎障害がない以上、0.8g/kg/日では不足で適切でない。

出典：厚生労働省ホームページ 第116回医師国家試験 C002',
     '{"A": "水分30mL/kg/日は高齢者の目安として妥当である。", "B": "脂肪を総エネルギーの20〜30%とするのは妥当である。", "C": "糖質を総エネルギーの50〜60%とするのは妥当である。", "E": "総エネルギー30kcal/kg/日は低栄養の改善を目指す量として妥当である。"}'),
    ('116-C-3', '正答は C「輸入感染症患者の検疫」。

検疫は検疫所が国の機関として空港・海港で行う業務であり、医療機関の感染制御チームの役割ではない。

出典：厚生労働省ホームページ 第116回医師国家試験 C003',
     '{"A": "職員のワクチン接種や針刺し事故対応など職業感染防止はチームの業務である。", "B": "病棟ラウンドによる手指衛生や隔離の実施状況の確認は中心的な業務である。", "D": "適切な検体提出と培養検査の推進はチームの役割である。", "E": "耐性菌や医療関連感染のサーベイランスはチームの基本業務である。"}'),
    ('116-C-5', '正答は B「肺がん検診では判定に二重読影が行われる。」。

肺がん検診の胸部エックス線写真は、読影の見落としを減らすため2人以上による二重読影が行われる。比較読影も併せて行う。

出典：厚生労働省ホームページ 第116回医師国家試験 C005',
     '{"A": "特定健診・特定保健指導の実施主体は医療保険者である。", "C": "地域包括支援センターの設置主体は市町村である。", "D": "5疾病は癌・脳卒中・心筋梗塞等の心血管疾患・糖尿病・精神疾患で、高血圧は含まれない。", "E": "PSA検診は死亡率減少効果の証拠が不十分で、対策型検診としては推奨されていない。"}'),
    ('116-C-7', '正答は E「特定の区域を超えて世界中で感染が拡大して持続している状態」。

パンデミックは、特定の地域を超えて世界的な規模で感染が拡大し持続している状態を指す。

出典：厚生労働省ホームページ 第116回医師国家試験 C007',
     '{"A": "人への新しい種類の感染が確認された状態は、新興感染症の出現である。", "B": "通常の予測を超えて感染が拡大するのはアウトブレイクである。", "C": "特定の区域や集団内での予測以上の拡大はエピデミックである。", "D": "特定の区域で継続的に発生している状態はエンデミック(常在)である。"}'),
    ('116-C-8', '正答は D「自律神経系の活動が変動しやすい。」。

レム睡眠では交感神経と副交感神経の活動が不安定に変動し、心拍数や血圧、呼吸が乱れやすい。早朝のレム睡眠期に心血管イベントが起こりやすいのはこのためである。

出典：厚生労働省ホームページ 第116回医師国家試験 C008',
     '{"A": "徐波睡眠と呼ばれるのはノンレム睡眠の深い段階である。", "B": "レム睡眠では抗重力筋の緊張が完全に消失する。", "C": "レム睡眠中に覚醒させると高率に夢の報告が得られる。", "E": "レム睡眠は成人で全睡眠時間のおよそ20〜25%である。"}'),
    ('116-C-9', '正答は E「患者世帯の標準報酬月額」。

高額療養費制度の自己負担限度額は、70歳未満では標準報酬月額(所得区分)によって、70歳以上では所得区分と外来・入院の別によって決まる。疾患の種類や医療機関の規模では変わらない。

出典：厚生労働省ホームページ 第116回医師国家試験 C009',
     '{"A": "疾患の種類による区別はない。", "B": "治療の種類でも変わらない。", "C": "罹病期間ではなく、同一月の自己負担額で判定する。", "D": "医療機関の規模は限度額を規定しない。"}'),
    ('116-C-10', '正答は A「終末期になってから導入する。」。

緩和ケアは終末期に限らず、診断された時から治療と並行して提供されるべきものとされている。基本計画でもこの点が繰り返し強調されている。

出典：厚生労働省ホームページ 第116回医師国家試験 C010',
     '{"B": "家族も支援の対象であり、遺族ケアも含まれる。正しい。", "C": "医療用麻薬への誤解を解くための啓発が挙げられている。正しい。", "D": "精神腫瘍医(サイコオンコロジスト)の役割についての記載がある。正しい。", "E": "看護師・薬剤師・心理職など多職種が関わることが前提とされている。正しい。"}'),
    ('116-C-11', '正答は D「4」。

三次予防はすでに発症した疾患の重症化を防ぎ、機能を回復・維持する取り組みである。慢性閉塞性肺疾患の患者に対する呼吸リハビリテーションがこれにあたる。

出典：厚生労働省ホームページ 第116回医師国家試験 C011',
     '{"A": "小学生への禁煙教育は発症前の健康増進で、一次予防である。", "B": "産業医としての禁煙活動も一次予防である。", "C": "喫煙者の健康診断は無症状のうちに疾患を早期発見する二次予防である。", "E": "喫煙妊婦への禁煙指導は、母児の疾患発症を防ぐ一次予防である。"}'),
    ('116-C-12', '正答は B「肝硬変」。

肝硬変による胸水は、低アルブミン血症と門脈圧亢進によって生じる漏出性胸水である。滲出性ではない。

出典：厚生労働省ホームページ 第116回医師国家試験 C012',
     '{"A": "肺梗塞では胸膜の炎症と血管透過性亢進により滲出性胸水を生じる。", "C": "急性膵炎では膵酵素の刺激により左優位の滲出性胸水を生じる。", "D": "結核性胸膜炎は代表的な滲出性胸水で、ADA高値とリンパ球優位が特徴である。", "E": "全身性エリテマトーデスの漿膜炎も滲出性胸水をきたす。"}'),
    ('116-C-13', '正答は E「1,000ppm(0.1%)次亜塩素酸ナトリウム」。

ノロウイルスはエンベロープを持たないためアルコールが効きにくい。0.1%(1,000ppm)次亜塩素酸ナトリウムによる消毒か、85〜90°Cで90秒以上の加熱で不活化する。

出典：厚生労働省ホームページ 第116回医師国家試験 C013',
     '{"A": "逆性石鹸(塩化ベンザルコニウム)はノロウイルスに無効である。", "B": "40°Cの温水では不活化できない。85°C以上の加熱が必要である。", "C": "アルコールはエンベロープを持たないウイルスには効きにくい。", "D": "赤外線照射に消毒効果はない。"}'),
    ('116-C-14', '正答は B「−20度」。

関節可動域は解剖学的肢位を0度として表す。底屈20度の位置までしか戻せず0度に届かないので、背屈の可動域は−20度と記載する。

出典：厚生労働省ホームページ 第116回医師国家試験 C014',
     '{"A": "−40度は底屈40度の位置が限界の場合である。", "C": "0度は中間位まで背屈できる場合である。", "D": "20度は中間位を越えて背屈できる場合で、尖足と矛盾する。", "E": "40度も同様に背屈可能な場合の値である。"}'),
    ('116-C-15', '正答は A「婚姻率」。

婚姻率は人口千人当たりの婚姻件数で、分母は総人口(日本人人口)である。出生率・死亡率も同様に総人口を分母とする。

出典：厚生労働省ホームページ 第116回医師国家試験 C015',
     '{"B": "乳児死亡率の分母は出生数である。", "C": "老年人口指数の分母は生産年齢人口(15〜64歳)である。", "D": "標準化死亡比の分母は基準集団から求めた期待死亡数である。", "E": "合計特殊出生率は年齢別出生率の合計で、各年齢の女性人口を分母とする。"}'),
    ('116-C-16', '正答は D「バルトリン腺炎」。

バルトリン腺炎は大前庭腺の導管が閉塞して感染し、膿瘍を形成すると外陰部の強い疼痛と腫脹をきたす。歩行や坐位も困難になり、切開排膿を要する。

出典：厚生労働省ホームページ 第116回医師国家試験 C016',
     '{"A": "子宮前屈は正常な子宮の位置で、症状の原因にならない。", "B": "子宮腔癒着(Asherman症候群)は無月経や不妊が問題となり、痛みは主症状でない。", "C": "子宮腟部びらんは無症状か帯下・接触出血が主で、疼痛は伴わない。", "E": "子宮頸管ポリープは不正性器出血が主症状で、無痛性である。"}'),
    ('116-C-20', '正答は B「ケトン体」。

糖質の供給が絶たれると脂肪酸のβ酸化が亢進し、肝でケトン体が産生される。飢餓性ケトーシスで、絶食2日目には血中ケトン体が明らかに上昇する。

出典：厚生労働省ホームページ 第116回医師国家試験 C020',
     '{"A": "HbA1cは過去1〜2か月の平均血糖を反映し、2日では変化しない。", "C": "アルブミンは半減期が約21日で、2日では下がらない。", "D": "トリグリセリドは食事由来のカイロミクロンが減るため、むしろ低下する。", "E": "総コレステロールも短期の絶食で上昇しない。"}'),
    ('116-C-21', '正答は D「40歳未満女性の部位別悪性新生物では子宮頸がんが最も罹患率が高い。」。

40歳未満の女性では子宮頸癌の罹患率が最も高い。HPVワクチンと検診による予防が可能な癌であり、若年層への対策が課題となっている。

出典：厚生労働省ホームページ 第116回医師国家試験 C021',
     '{"A": "脳血管疾患の患者数は高血圧管理の普及により減少傾向にある。", "B": "生活習慣病のリスクとなる飲酒習慣は、男性では所得が高い層で割合が高い。", "C": "悪性新生物の年齢調整死亡率は全体として低下しており、60代で増加という事実はない。", "E": "糖尿病の発症には教育歴・所得・雇用形態など社会経済的要因が強く関与することが分かっている。"}'),
    ('116-C-22', '正答は B「IL-6」。

IL-6は肝細胞に働いてCRPをはじめとする急性期蛋白の産生を誘導する中心的なサイトカインである。IL-6受容体を阻害するトシリズマブ投与中はCRPが上がらなくなり、感染の指標として使えなくなる点も重要である。

出典：厚生労働省ホームページ 第116回医師国家試験 C022',
     '{"A": "IL-1は発熱や炎症の惹起に関わるが、CRP産生の主たる誘導因子ではない。", "C": "TGF-βは線維化や免疫抑制に関わる。", "D": "TNF-αも炎症の中心的なサイトカインだが、CRP産生はIL-6を介する。", "E": "インターフェロンγはマクロファージの活性化や細胞性免疫に働く。"}'),
    ('116-C-24', '正答は C「迷走神経」。

内喉頭筋は迷走神経の枝である反回神経(下喉頭神経)が支配する。輪状甲状筋のみ上喉頭神経外枝が支配するが、これも迷走神経の枝である。

出典：厚生労働省ホームページ 第116回医師国家試験 C024',
     '{"A": "顔面神経は表情筋を支配する。", "B": "舌咽神経は茎突咽頭筋と咽頭・舌後1/3の感覚を担う。", "D": "副神経は胸鎖乳突筋と僧帽筋を支配する。", "E": "舌下神経は舌筋を支配する。"}'),
    ('116-C-25', '正答は A「人口動態統計に係る統計」。

人口動態統計は市区町村から都道府県、厚生労働省へと集計される国の統計業務で、地方衛生研究所の業務ではない。

出典：厚生労働省ホームページ 第116回医師国家試験 C025',
     '{"B": "地域の健康課題に関する調査研究は地方衛生研究所の業務である。", "C": "保健所職員など地域保健関係者への研修指導も業務に含まれる。", "D": "衛生微生物や食品・環境の試験検査は中心的な業務である。", "E": "公衆衛生情報の収集・解析・提供も業務に含まれる。"}'),
    ('116-C-26', '正答は B「平均寿命」。

平均寿命は医療の進歩と生活環境の改善により延び続けており、2019年は男性81.41年・女性87.45年で2009年より延伸している。

出典：厚生労働省ホームページ 第116回医師国家試験 C026',
     '{"A": "総人口は2008年をピークに減少に転じている。", "C": "年間出生数は減少を続け、2019年に90万人を割り込んだ。", "D": "生産年齢人口(15〜64歳)も減少を続けている。", "E": "合計特殊出生率は1.3台で推移し、2019年は2009年をやや下回る。"}'),
    ('116-C-37', '正答は D「小腸カプセル内視鏡」。

反復する暗赤色血便と鉄欠乏性貧血があり、上部・下部消化管内視鏡で出血源が特定できない原因不明消化管出血である。小腸が出血源として残るため、非侵襲的に全小腸を観察できるカプセル内視鏡を行う。

出典：厚生労働省ホームページ 第116回医師国家試験 C037',
     '{"A": "小腸造影は血管拡張症など粘膜面のわずかな病変を捉えにくい。", "B": "腹部MRIは腫瘍の検索には使えるが、小さな出血源の同定には向かない。", "C": "血管造影は0.5mL/分以上の活動性出血がなければ描出できず、受診時には出血が止まっている。", "E": "Meckel憩室シンチグラフィは異所性胃粘膜を検出する検査で、小児の下血に用いる。"}'),
    ('116-C-38', '正答は B「気管支鏡検査」。

閉鎖空間での火災で顔面・口腔に煤が付着し毛髪が焼けており、喘鳴も聴取する。気道熱傷が強く疑われ、気管支鏡で声門下から気管・気管支の粘膜傷害を直接評価する。浮腫が進む前の予防的気管挿管の判断にも直結する。

出典：厚生労働省ホームページ 第116回医師国家試験 C038',
     '{"A": "胸部MRIは気道粘膜の評価に向かず、緊急性のある場面で選ぶ検査ではない。", "C": "肺動脈造影は肺血栓塞栓症を疑うときの検査である。", "D": "肺血流シンチグラフィも同様である。", "E": "上部消化管内視鏡は腐食性物質の誤飲で行うもので、吸入による気道熱傷の評価にはならない。"}'),
    ('116-C-41', '正答は C「摂取エネルギー量の制限を指導する。」。

設問は「適切でない」対応を選ぶもの。身長152cm・体重46kg（BMI 19.9）、アルブミン3.4g/dLと低栄養に傾いており、転倒を繰り返す高齢者では筋肉量の維持が転倒予防そのものになる。HbA1c 6.9%は高齢者の目標として良好で、厳格な血糖管理の適応でもない。ここで摂取エネルギー量の制限を指導するのは、フレイルとサルコペニアを進めるだけで不適切である。

出典：厚生労働省ホームページ 第116回医師国家試験 C041',
     '{"A": "転倒を繰り返し、残薬も管理できていない。認知機能の評価は必要で適切である。", "B": "小刻み歩行と筋強剛があり振戦を欠くパーキンソニズムで、薬剤性が疑われる。残薬も多く、内服内容の確認は適切である。", "D": "日中は独居で転倒が多い。在宅支援の導入は適切である。", "E": "高齢者の頭部打撲後は、CTで出血がなくても慢性硬膜下血腫が遅れて現れうる。説明しておくのは適切である。"}'),
    ('116-C-42', '正答は E「5」。

毛細血管再充満時間が2秒を超えるのは末梢循環不全を示す所見である。3秒は明らかな延長で、脱水やショックの進行を意味する。

出典：厚生労働省ホームページ 第116回医師国家試験 C042',
     '{"A": "足底刺激で開眼するのは意識レベルの評価で、循環の指標ではない。", "B": "皮膚色がピンク色であることは循環が保たれている所見である。", "C": "ツルゴールの軽度低下は脱水を示すが、循環不全そのものの指標ではない。", "D": "口唇の乾燥も脱水の所見で、循環不全を直接示さない。"}'),
    ('116-C-44', '正答は A「1」。

正常な新生児は生後24時間以内に胎便を排泄する。48時間かかっているのは胎便排泄遅延で、腹部膨満を伴うことからHirschsprung病や鎖肛、胎便性イレウスなどを疑う。

出典：厚生労働省ホームページ 第116回医師国家試験 C044',
     '{"B": "出生体重3,100gに対し2,950gは4.8%の減少で、生理的体重減少(5〜10%)の範囲内である。", "C": "大泉門2×2cmは正常範囲である。", "D": "日齢3の黄疸は生理的黄疸として矛盾しない。", "E": "新生児で肝を右季肋下に1〜2cm触知するのは正常である。"}'),
    ('116-C-45', '正答は B「12誘導心電図」。

糖尿病と陳旧性心筋梗塞があり、労作と無関係に発汗と悪心が反復している。糖尿病では神経障害のため胸痛を欠く無痛性心筋虚血が起こりうる。急性冠症候群を想定してまず12誘導心電図を記録する。

出典：厚生労働省ホームページ 第116回医師国家試験 C045',
     '{"A": "胸部造影CTは大動脈解離や肺塞栓を疑うときの検査で、まず行うものではない。", "C": "心エコーは壁運動異常の評価に有用だが、心電図より優先されない。", "D": "急性冠症候群が否定されていない段階での運動負荷は危険である。", "E": "心筋シンチグラフィは待機的な虚血評価に用いる検査である。"}'),
    ('116-C-46', '正答は A「初乳がみられる。」。

初乳は産褥2〜3日ごろから分泌が始まり、蛋白質と免疫グロブリンA、ラクトフェリンに富む。産褥3日目の所見として正しい。

出典：厚生労働省ホームページ 第116回医師国家試験 C046',
     '{"B": "産褥3日は赤色悪露の時期である。黄色悪露は産褥2週ごろからみられる。", "C": "内子宮口が閉鎖するのは産褥10〜12日ごろで、3日目にはまだ開いている。", "D": "産褥3日では子宮底は臍下2〜3横指で触れる。触れなくなるのは産褥10〜12日ごろである。", "E": "後陣痛は分娩直後から翌日にかけて最も強く、産褥3日には軽快している。"}'),
    ('116-C-47', '正答は D「ビタミンD」。

魚介類も乳製品も10年以上摂っていない厳格な菜食で、低カルシウム血症と低リン血症をきたしている。手のこわばりは低カルシウム血症によるテタニー症状で、ビタミンDの欠乏を考える。

出典：厚生労働省ホームページ 第116回医師国家試験 C047',
     '{"A": "亜鉛欠乏では味覚障害をきたすが、本例は味覚に異常がない。", "B": "葉酸欠乏では大球性貧血をきたすが、血算は正常である。", "C": "ビタミンB1欠乏では脚気やWernicke脳症をきたし、神経診察に異常が出る。", "E": "ビタミンE欠乏は稀で、失調や深部感覚障害をきたす。"}'),
    ('116-C-49', '正答は D「医療保護入院」。

本人の意思を確認できず、医療保護が必要な状態である。精神保健指定医の診察と家族等(ここでは夫)の同意により医療保護入院とする。

出典：厚生労働省ホームページ 第116回医師国家試験 C049',
     '{"A": "緊急措置入院は自傷他害のおそれが著しく急を要する場合の形式である。", "B": "措置入院も自傷他害のおそれがあり、2名の指定医の診察が必要な形式である。", "C": "応急入院は家族等の同意が得られない場合に72時間を限度として行うもので、同意可能な夫がいる本例には当たらない。", "E": "任意入院は本人の同意によるもので、意思を確認できない本例では選べない。"}'),
    ('116-C-51', '正答は C「「早朝1時間の散歩を始めたのは良いことですね」」。

すでに早朝の散歩を始めており、行動変容ステージの実行期にあたる。この段階では始めた行動を肯定的に評価して強化し、継続を支えることが有効である。

出典：厚生労働省ホームページ 第116回医師国家試験 C051',
     '{"A": "知識の提供は前熟考期から熟考期にかけての働きかけである。", "B": "周囲がやっているという情報は動機づけとして弱く、実行期の支援にならない。", "D": "漠然と努力を促すのは、すでに実行している人への働きかけとして適切でない。", "E": "生活の見直しを勧めるのは熟考期から準備期への働きかけである。"}'),
    ('116-C-52', '正答は E「第1子の遺伝子検査が陰性でも診断は変わらない。」。

Duchenne型筋ジストロフィーの遺伝子検査(欠失・重複の検出)の感度はおよそ95%で、点変異などは検出されないことがある。臨床所見と筋病理で診断されている以上、遺伝子検査が陰性でも診断は変わらない。

出典：厚生労働省ホームページ 第116回医師国家試験 C052',
     '{"A": "およそ1/3は新生突然変異によるため、母親が確定保因者とは言えない。", "B": "新生突然変異による発症は珍しくない。", "C": "X染色体不活化の偏りにより、保因者女性が症状を示すことがある(manifesting carrier)。", "D": "感度は100%ではない。"}'),
    ('116-C-54', '正答は C「出発国への送還」。

検疫法に基づき検疫所長が行えるのは、隔離・停留、消毒、質問・診察・検査、健康監視などである。出発国への送還を命じる権限はない。

出典：厚生労働省ホームページ 第116回医師国家試験 C054',
     '{"A": "一類感染症の患者に対する隔離は検疫法に定められた措置である。", "B": "航空機・船舶や物件の消毒も検疫所長が行える措置である。", "D": "質問により行動歴や接触者を聴取することは検疫法に基づく措置である。", "E": "病原体の検査も検疫所長が行える措置である。"}'),
    ('116-D-2', '正答は A「「自分は電波で操られている」」。

「電波で操られている」という訴えは、自分の意思や行動が外部の力に支配されているという作為体験(させられ体験)で、自我障害にあたる。Schneiderの一級症状に含まれ統合失調症を強く示唆する。

出典：厚生労働省ホームページ 第116回医師国家試験 D002',
     '{"B": "壁のしみが虫に見えるのは錯視で、せん妄やアルコール離脱でみられる。", "C": "発作への予期不安はパニック症の症状である。", "D": "人前での過度の緊張は社交不安症の症状である。", "E": "施錠の確認を繰り返すのは強迫症の強迫行為である。"}'),
    ('116-D-3', '正答は C「Forrester分類」。

Forrester分類は、肺動脈楔入圧18mmHgと心係数2.2L/分/m2を境として心不全を4群に分ける。Swan-Ganzカテーテルによる実測値に基づく分類である。

出典：厚生労働省ホームページ 第116回医師国家試験 D003',
     '{"A": "AHA/ACCのステージ分類は器質的心疾患の有無と症状によるもので、血行動態の実測値を用いない。", "B": "Child分類は肝硬変の重症度分類である。", "D": "Nohria-Stevenson分類はうっ血と低灌流を身体所見から判断する分類で、カテーテルを要さない。", "E": "NYHA分類は自覚症状に基づく機能分類である。"}'),
    ('116-D-4', '正答は D「糖質コルチコイドの増量」。

先天性副腎皮質過形成症では内因性のコルチゾール分泌が不足しており、発熱などのストレス下では需要に見合った増加ができない。副腎クリーゼを防ぐため、糖質コルチコイドを通常の2〜3倍に増量する(シックデイルール)。

出典：厚生労働省ホームページ 第116回医師国家試験 D004',
     '{"A": "水分制限はむしろ脱水と循環虚脱を招く。", "B": "抗菌薬は原因が細菌感染と判断されれば用いるが、初期対応の要点ではない。", "C": "利尿薬は循環血液量を減らし危険である。", "E": "グルコース・インスリン療法は高カリウム血症の治療で、初期対応として選ぶものではない。"}'),
    ('116-D-5', '正答は B「食道アカラシア」。

食道アカラシアは下部食道括約筋の弛緩不全による疾患で、内視鏡下バルーン拡張術や経口内視鏡的筋層切開術(POEM)が治療として行われる。

出典：厚生労働省ホームページ 第116回医師国家試験 D005',
     '{"A": "食道憩室の治療は外科的切除で、内視鏡治療の対象ではない。", "C": "食道カンジダ症は抗真菌薬による薬物療法で治療する。", "D": "食道裂孔ヘルニアの根治には腹腔鏡下噴門形成術など外科手術を行う。", "E": "非びらん性胃食道逆流症はプロトンポンプ阻害薬などの薬物療法が中心である。"}'),
    ('116-D-6', '正答は C「Buerger病」。

Buerger病(閉塞性血栓血管炎)は四肢の中小動脈に炎症性血栓を生じて閉塞をきたす疾患で、動脈壁が膨らむ動脈瘤は形成しない。喫煙との関連が強い。

出典：厚生労働省ホームページ 第116回医師国家試験 D006',
     '{"A": "梅毒性大動脈炎は上行大動脈に瘤を作る古典的な原因である。", "B": "動脈硬化は腹部大動脈瘤の最も多い原因である。", "D": "高安動脈炎は大動脈とその分枝に狭窄だけでなく瘤も作る。", "E": "Marfan症候群ではフィブリリンの異常により大動脈基部拡張・瘤・解離をきたす。"}'),
    ('116-D-7', '正答は D「腹部エコー検査」。

腎後性急性腎障害は尿路の閉塞によるもので、腹部超音波で水腎症や膀胱の尿貯留を確認すれば速やかに診断できる。非侵襲的で最初に行うべき検査である。閉塞が解除できれば腎機能は回復しうる。

出典：厚生労働省ホームページ 第116回医師国家試験 D007',
     '{"A": "腎生検は腎性の鑑別に用いるもので、閉塞の有無は分からない。", "B": "尿蛋白定量は糸球体疾患の評価で、閉塞の判定にならない。", "C": "尿比重は腎前性と腎性の鑑別の参考になるが、腎後性は区別できない。", "E": "血清クレアチニンは腎障害の程度を示すだけで、原因の部位を示さない。"}'),
    ('116-D-8', '正答は E「伝染性膿痂疹」。

伝染性膿痂疹(とびひ)は黄色ブドウ球菌やA群レンサ球菌による急性の細菌感染症で、水疱や痂皮が接触により拡大する。

出典：厚生労働省ホームページ 第116回医師国家試験 D008',
     '{"A": "癜風はMalassezia属による表在性真菌症である。", "B": "掌蹠膿疱症は無菌性の膿疱を繰り返す慢性疾患で、扁桃や歯性の病巣感染が関与する。", "C": "膿疱性乾癬も無菌性膿疱を生じる慢性炎症性疾患である。", "D": "化膿性汗腺炎は毛包の閉塞に始まる慢性反復性の炎症性疾患で、急性の細菌感染症ではない。"}'),
    ('116-D-10', '正答は D「胚染色体異常」。

妊娠12週未満の早期流産の原因として最も多いのは胎児(胚)の染色体異常で、およそ半数以上を占める。偶発的に生じるもので、母体側の行動によるものではない点を説明することが大切である。

出典：厚生労働省ホームページ 第116回医師国家試験 D010',
     '{"A": "子宮奇形は流産の原因となりうるが頻度は低い。", "B": "子宮筋腫も粘膜下筋腫などで流産に関与しうるが、最多ではない。", "C": "頸管無力症は妊娠中期以降の流早産の原因である。", "E": "抗リン脂質抗体症候群は反復流産の重要な原因だが、全体としての頻度は染色体異常に及ばない。"}'),
    ('116-D-17', '正答は B「切符を買うなどの一般的な行動はできる。」。

身元の記憶を失いながら、日常の行動能力や新たな記憶は保たれている。解離性同一性の障害を伴う解離性健忘(解離性遁走)で、切符を買う、会話するといった手続き的・日常的な行動は問題なく行える。

出典：厚生労働省ホームページ 第116回医師国家試験 D017',
     '{"A": "替え玉妄想(Capgras症候群)は器質性疾患や統合失調症でみられる別の症候である。", "C": "記憶がないことに対して深刻に悩まず淡々としている(満ち足りた無関心)のが特徴である。", "D": "解離性障害に抗精神病薬の適応はない。", "E": "Alzheimer型認知症では近時記憶から障害され、保護後の記憶が保たれることはない。"}'),
    ('116-D-18', '正答は A「α遮断薬」。

α遮断薬は末梢血管を拡張させる降圧薬で、抗不整脈作用を持たない。特発性心室頻拍の薬物療法には用いられない。

出典：厚生労働省ホームページ 第116回医師国家試験 D018',
     '{"B": "β遮断薬は交感神経を介した心室頻拍の抑制に用いられる。", "C": "I群抗不整脈薬(Naチャネル遮断薬)は心室頻拍に用いられる。", "D": "ベラパミルはベラパミル感受性特発性心室頻拍に有効である。", "E": "ジルチアゼムも同じ非ジヒドロピリジン系カルシウム拮抗薬として用いられうる。"}'),
    ('116-D-19', '正答は C「中枢性鎮咳薬の投与」。

喫煙歴が長く口すぼめ呼吸を認め、感染を契機に増悪したCOPDである。喀痰の喀出が治療の要であり、中枢性鎮咳薬で咳を止めると痰が貯留して気道閉塞と感染の悪化を招く。

出典：厚生労働省ホームページ 第116回医師国家試験 D019',
     '{"A": "SpO2 87%であり、CO2ナルコーシスに注意しつつ酸素療法を行う。適切である。", "B": "黄色痰と発熱があり、細菌感染を伴う増悪として抗菌薬を投与する。適切である。", "D": "COPD増悪では全身性ステロイドの短期投与が回復を早める。適切である。", "E": "短時間作用型β2刺激薬の吸入は気流閉塞の改善に有効である。適切である。"}'),
    ('116-D-21', '正答は C「出血性脳梗塞を併発後の昏睡状態」。

感染性心内膜炎に出血性脳梗塞を併発して昏睡状態にある場合、体外循環に伴う抗凝固で頭蓋内出血が拡大する危険が高く、早期手術は避けて時期を待つ。他の選択肢はいずれも早期手術の適応である。

出典：厚生労働省ホームページ 第116回医師国家試験 D021',
     '{"A": "弁穿孔による急性弁逆流は手術適応である。", "B": "弁周囲膿瘍は抗菌薬だけでは制御できず、手術適応である。", "D": "可動性の大きな疣贅や塞栓の反復は手術適応である。", "E": "内科的に制御できない心不全は最も明確な手術適応である。"}'),
    ('116-D-22', '正答は A「レム〈REM〉睡眠行動障害」。

夢の内容に一致した大声や粗大な体動が睡眠中に現れており、レム睡眠中に本来生じる筋緊張の消失が失われるレム睡眠行動障害である。α-シヌクレイノパチー(Parkinson病、Lewy小体型認知症、多系統萎縮症)の前駆症状となることが知られている。

出典：厚生労働省ホームページ 第116回医師国家試験 D022',
     '{"B": "睡眠時無呼吸症候群はいびきと無呼吸、日中の眠気が主体で、粗大な体動は伴わない。", "C": "下肢静止不能症候群は入眠前の下肢の不快感と動かしたい衝動が特徴である。", "D": "突発睡眠(ナルコレプシー)は日中の耐えがたい眠気が主症状である。", "E": "夜驚症はノンレム睡眠から生じる小児の睡眠時随伴症で、本人に記憶が残らない。"}'),
    ('116-D-24', '正答は D「鎮痛状況により投与量の調節を行う。」。

癌性疼痛に対するオピオイドは、痛みの強さに応じて有効かつ副作用が許容できる量まで個々に調節する(タイトレーション)。上限を決めた固定量で使うものではない。

出典：厚生労働省ホームページ 第116回医師国家試験 D024',
     '{"A": "フェンタニル貼付薬など経皮吸収型製剤が使用でき、経口摂取が難しい患者にも有用である。", "B": "持続する痛みには定時投与が原則で、疼痛時のみの頓用では痛みの波を抑えられない。", "C": "経口摂取が可能であれば経口薬から開始する。", "E": "レスキューには即効性のある速放性製剤を用いる。長時間作用性では間に合わない。"}'),
    ('116-D-28', '正答は E「「以前にこのようなことはありましたか」」。

過去に同様のことがあったかどうかは、今回の誤飲に対する処置の判断には結びつかない。何を・どれだけ・いつ飲んだか、その後どうしたかが処置を決める情報である。

出典：厚生労働省ホームページ 第116回医師国家試験 D028',
     '{"A": "すでに嘔吐させたかどうかは、追加処置や誤嚥のリスク評価に必要である。", "B": "水を飲ませたかどうかは、たばこの場合ニコチンの吸収を早めるため重要な情報である。", "C": "口腔内の残存物は摂取物の同定と量の推定につながる。", "D": "経過時間は催吐や吸着の適応、症状出現の見通しを決める。"}'),
    ('116-D-34', '正答は B「多系統萎縮症」。

起立性低血圧(収縮期で30mmHgの低下)、便秘と尿失禁という自律神経障害に、小脳性運動失調(測定障害・変換運動障害・体幹動揺)と振戦を欠くパーキンソニズムが加わっている。多系統萎縮症である。

出典：厚生労働省ホームページ 第116回医師国家試験 D034',
     '{"A": "Parkinson病では小脳症状を欠き、初期からこれほど高度の自律神経障害は出にくい。", "C": "Huntington病は舞踏運動と精神症状・認知機能低下が主体である。", "D": "筋萎縮性側索硬化症は上位・下位運動ニューロン徴候が主体で、自律神経障害や小脳症状は目立たない。", "E": "大脳皮質基底核変性症は左右差の強い失行と筋強剛が特徴で、自律神経障害は前景に出ない。"}'),
    ('116-D-35', '正答は A「肺拡散能検査」。

設問は診断に有用な検査として「誤っている」ものを選ぶもの。製パン工房で働き始めてから、職場にいる日中だけ乾性咳嗽が出て週末には消える。小麦粉抗原による職業性喘息（baker''s asthma）を考える病歴である。肺拡散能検査は間質性肺疾患や肺気腫で低下をみる検査で、気道の可逆性や過敏性を評価するものではなく、この診断には寄与しない。

出典：厚生労働省ホームページ 第116回医師国家試験 D035',
     '{"B": "気道過敏性試験は喘息の本態である気道過敏性を証明でき、有用である。", "C": "小麦粉抗原に対する特異的IgE抗体は職業性の感作を裏づけられる。好酸球12%と花粉症の既往もアトピー素因を支持する。", "D": "気道可逆性試験は気管支拡張薬への反応から可逆性の気流制限を示せる。", "E": "ピークフローの日内変動は、職場にいる日と週末で差が出るかを見られ、職業性喘息の診断に有用である。"}'),
    ('116-D-38', '正答は B「左股関節切開・洗浄」。

発熱に続いて左下肢を動かさなくなり、他動運動で強く泣き、著明な炎症反応がある。乳児の化膿性股関節炎で、関節軟骨と大腿骨頭が急速に破壊されるため、緊急に切開・洗浄してドレナージすることが必要である。

出典：厚生労働省ホームページ 第116回医師国家試験 D038',
     '{"A": "NSAIDでは感染は制御できず、診断と治療が遅れる。", "C": "牽引は化膿性関節炎の治療にならない。", "D": "リーメンビューゲル装具は発育性股関節形成不全に用いる。", "E": "感染している関節へのステロイド投与は病態を悪化させる。"}'),
    ('116-D-39', '正答は D「50%」。

両側の側腹部腫瘤、成人期発症の腎障害、くも膜下出血の家族歴、複数の血縁者の透析歴から常染色体顕性多発性囊胞腎である。常染色体顕性遺伝なので、子への伝達確率は50%である。

出典：厚生労働省ホームページ 第116回医師国家試験 D039',
     '{"A": "遺伝性であり0%ではない。", "B": "25%は常染色体潜性遺伝の場合の再発率である。", "C": "33%という値は遺伝形式から導かれない。", "E": "100%となるのは変異がホモ接合の場合などで、この疾患では該当しない。"}'),
    ('116-D-40', '正答は D「経口副腎皮質ステロイド」。

難治性喘息に末梢血好酸球の著明な増加と中枢性気管支拡張、抗菌薬に反応しない肺陰影があり、アレルギー性気管支肺アスペルギルス症を考える。治療の中心は経口副腎皮質ステロイドで、必要に応じて抗真菌薬を併用する。

出典：厚生労働省ホームページ 第116回医師国家試験 D040',
     '{"A": "シクロスポリンはステロイド抵抗例に検討されることはあるが第一選択ではない。", "B": "真菌に対する免疫反応が病態であり、細菌用の抗菌薬は無効である。", "C": "吸入ステロイドだけでは中枢気道の粘液栓と免疫反応を抑えられない。", "E": "アスペルギルスの減感作療法は確立した治療法ではない。"}'),
    ('116-D-47', '正答は C「ボツリヌス症」。

蜂蜜を与えられた乳児に便秘が先行し、哺乳力低下、眼瞼下垂、散瞳と対光反射遅延、頸定の消失、腱反射消失が現れている。乳児ボツリヌス症で、腸管内で発芽した芽胞が産生する毒素が神経筋接合部を遮断する。1歳未満に蜂蜜を与えてはならない。

出典：厚生労働省ホームページ 第116回医師国家試験 D047',
     '{"A": "脳性麻痺は非進行性で、4か月まで発達良好だった児に急性に発症することはない。", "B": "重症筋無力症でも眼瞼下垂は出るが、瞳孔は侵されず対光反射は正常である。", "D": "先天性ミオパチーは出生時から筋緊張低下があり、急性発症ではない。", "E": "Werdnig-Hoffmann病も進行性だが、瞳孔散大や便秘の先行は特徴でない。"}'),
    ('116-D-49', '正答は E「劇症肝炎」。

意識障害にPT-INR延長とFDP上昇を伴い、肝性脳症をきたしている。非ホジキンリンパ腫の治療歴があり、化学療法に伴うHBV再活性化による劇症肝炎が典型的な経過である。治療前のHBs抗原・HBc抗体の確認と、再活性化のモニタリングが欠かせない。

出典：厚生労働省ホームページ 第116回医師国家試験 D049',
     '{"A": "原発性硬化性胆管炎は慢性の胆汁うっ滞で、急性の意識障害と凝固障害を説明しない。", "B": "被包化膵臓壊死は重症膵炎の後期合併症である。", "C": "急性膵炎では上腹部痛と膵酵素上昇が主体で、肝性脳症はきたさない。", "D": "急性肝炎でも肝逸脱酵素は上がるが、昏睡と高度の凝固障害を伴えば劇症肝炎と呼ぶ。"}'),
    ('116-D-50', '正答は C「活性型葉酸」。

メトトレキサートの継続投与により汎血球減少と口腔粘膜のびらん、消化器症状をきたしている。葉酸代謝の阻害が本態なので、活性型葉酸(ホリナート)を投与して救済する(ロイコボリン救援)。同時にメトトレキサートは中止する。

出典：厚生労働省ホームページ 第116回医師国家試験 D050',
     '{"A": "ST合剤も葉酸代謝を阻害するため、メトトレキサート中毒では併用を避ける。", "B": "真菌感染が確認されていない段階で抗真菌薬を主治療にはしない。", "D": "ビタミンB12欠乏による血球減少ではない。", "E": "ステロイドは骨髄抑制と粘膜障害の是正にならない。"}'),
    ('116-D-51', '正答は C「麻薬性鎮痛薬投与」。

排便により軽快する腹痛と便通異常が続き、内視鏡で器質的疾患が否定されている過敏性腸症候群である。麻薬性鎮痛薬は依存を生むうえ便秘を悪化させ、慢性の機能性疾患には用いない。

出典：厚生労働省ホームページ 第116回医師国家試験 D051',
     '{"A": "下痢型では止痢薬(ロペラミドなど)が用いられる。", "B": "食物繊維(水溶性)の摂取は便性の改善に有用である。", "D": "プロバイオティクスは症状の改善に用いられる。", "E": "5-HT3受容体拮抗薬(ラモセトロン)は下痢型過敏性腸症候群の治療薬である。"}'),
    ('116-D-55', '正答は D「エリスロポエチン増加」。

肥満といびき、無呼吸の目撃があり閉塞性睡眠時無呼吸症候群による夜間の低酸素血症が背景にある。低酸素が腎でのエリスロポエチン産生を刺激して二次性赤血球増多をきたすため、エリスロポエチンは増加する。

出典：厚生労働省ホームページ 第116回医師国家試験 D055',
     '{"A": "ヒスタミン増加は真性多血症でみられ、そう痒の原因となる。", "B": "ビタミンB12増加も真性多血症や慢性骨髄性白血病でみられる。", "C": "JAK2遺伝子変異は真性多血症の所見で、二次性ではみられない。", "E": "フィラデルフィア染色体は慢性骨髄性白血病の所見である。"}'),
    ('116-D-58', '正答は A「補液」。

異型リンパ球の出現、後頸部リンパ節腫脹、肝逸脱酵素の上昇から伝染性単核球症である。特異的治療はなく、水分が摂れていないため補液で脱水を補正する対症療法を行う。

出典：厚生労働省ホームページ 第116回医師国家試験 D058',
     '{"B": "扁桃摘出術は急性期に行うものではない。気道閉塞が切迫すればステロイドを用いる。", "C": "ペニシリン系(とくにアンピシリン)は高率に薬疹を誘発するため避ける。", "D": "EBウイルスに有効な抗ウイルス薬はない。", "E": "アレルギー疾患ではなく抗アレルギー薬の適応がない。"}'),
    ('116-D-59', '正答は D「種別ごとの復帰プログラムに基づいて段階的に復帰させる。」。

意識消失と受傷前後の健忘があり脳振盪である。画像に異常がなくても、その日のうちに競技へ戻してはならない。無症状を確認しながら段階的競技復帰プログラムに沿って進める。

出典：厚生労働省ホームページ 第116回医師国家試験 D059',
     '{"A": "当日の復帰はセカンドインパクト症候群の危険があり禁忌である。", "B": "3時間の経過観察では不十分である。", "C": "12時間でも同様に不十分である。", "E": "適切な段階的復帰を経れば同一競技に戻ることができ、一律に禁止する根拠はない。"}'),
    ('116-D-62', '正答は D「尿中アルブミン/クレアチニン比の測定」。

糖尿病性腎症の早期診断には尿中アルブミンの評価が必要である。試験紙法の尿蛋白が陰性でも微量アルブミン尿の段階があり、尿中アルブミン/クレアチニン比が30mg/gCr以上で早期腎症と判定する。

出典：厚生労働省ホームページ 第116回医師国家試験 D062',
     '{"A": "腎臓超音波検査は形態評価で、糖尿病性腎症の病期判定にならない。", "B": "血清クレアチニンは腎機能の指標だが、早期腎症では正常である。", "C": "シスタチンCも糸球体濾過量の指標で、アルブミン尿の有無は分からない。", "E": "β2-マイクログロブリンは尿細管障害の指標で、糖尿病性腎症の診断基準ではない。"}'),
    ('116-D-63', '正答は A「抗菌薬内服」。

通年性の鼻閉・水様性鼻汁・くしゃみに蒼白で浮腫状の鼻粘膜があり、通年性アレルギー性鼻炎である。細菌感染を示す所見はなく、抗菌薬の適応がない。上顎洞粘膜の肥厚もアレルギー性の変化として説明できる。

出典：厚生労働省ホームページ 第116回医師国家試験 D063',
     '{"B": "抗原が同定できれば減感作療法(アレルゲン免疫療法)は根治的治療になりうる。", "C": "鼻内レーザー手術は鼻閉が強い症例の下鼻甲介に対して行われる。", "D": "抗ヒスタミン薬はくしゃみ・鼻汁に有効である。", "E": "鼻噴霧用ステロイドは鼻閉を含む全症状に有効で、治療の中心となる。"}'),
    ('116-E-1', '正答は C「呼吸機能検査」。

呼吸機能検査は閉塞性・拘束性障害の評価に用いるもので、血痰の原因(腫瘍・感染・気管支拡張症・抗凝固薬など)の検索には直接寄与しない。

出典：厚生労働省ホームページ 第116回医師国家試験 E001',
     '{"A": "喀痰細胞診は肺癌の検索に有用である。", "B": "抗凝固薬や抗血小板薬の服用は血痰の原因になるため確認が必要である。", "D": "肺結核は血痰の重要な原因で、抗酸菌検査は必須である。", "E": "胸部エックス線写真は腫瘍・感染・気管支拡張症の評価の第一歩である。"}'),
    ('116-E-2', '正答は E「虐待が疑われるため家族の同意なく児童の情報を児童相談所に通報した。」。

児童虐待防止法は、虐待を受けたと思われる児童を発見した者に通告義務を課しており、この通告は守秘義務違反にあたらないと明記されている。家族の同意は不要である。

出典：厚生労働省ホームページ 第116回医師国家試験 E002',
     '{"A": "家系の調査は遺伝情報という機微な個人情報を扱うため、本人の同意が要る。", "B": "実名を含む診療内容の投稿は守秘義務違反であり、絶対に許されない。", "C": "残余検体であっても遺伝子解析には別途の同意が必要である。", "D": "皮膚所見の公開も個人情報の第三者提供にあたり、同意が要る。"}'),
    ('116-E-3', '正答は B「圧痛を伴う。」。

圧痛を伴うリンパ節腫大は、急速な被膜の伸展を意味し炎症性(反応性)を示唆する。癌の転移では緩徐に増大するため痛みを欠くことが多い。

出典：厚生労働省ホームページ 第116回医師国家試験 E003',
     '{"A": "石のように硬いリンパ節は転移を示唆する。", "C": "周囲組織への浸潤による可動性の低下は悪性を示唆する。", "D": "鎖骨上窩(とくに左のVirchowリンパ節)の腫大は腹部悪性腫瘍の転移を示唆する。", "E": "辺縁が不整であることも悪性を示唆する所見である。"}'),
    ('116-E-4', '正答は D「蜂巣炎(蜂窩織炎)」。

蜂巣炎は皮下組織の細菌感染で、罹患部位に限局した発赤・熱感・腫脹をきたす。片側性の浮腫となる点が全身性の浮腫と異なる。

出典：厚生労働省ホームページ 第116回医師国家試験 E004',
     '{"A": "肝硬変では低アルブミン血症により両側性の浮腫と腹水を生じる。", "B": "急性心不全でも静脈圧の上昇により両側性の浮腫となる。", "C": "ネフローゼ症候群も低アルブミン血症による全身性浮腫である。", "E": "甲状腺機能低下症の粘液水腫も全身性である。"}'),
    ('116-E-6', '正答は B「Murphy徴候 — 急性胆囊炎」。

Murphy徴候は右季肋部を圧迫しながら深呼吸させると、炎症のある胆囊が指に触れて痛みで吸気が止まる所見で、急性胆囊炎に特徴的である。

出典：厚生労働省ホームページ 第116回医師国家試験 E006',
     '{"A": "筋性防御は腹膜炎の所見で、急性膀胱炎では生じない。", "C": "下腹部の腫瘤は尿閉による膀胱の拡張や子宮・卵巣腫瘍でみられる。尿管結石では触れない。", "D": "腹壁静脈の怒張(メデューサの頭)は門脈圧亢進症の所見である。", "E": "停留精巣自体は鼠径リンパ節腫大をきたさない。"}'),
    ('116-E-7', '正答は A「臍静脈」。

胎盤でガス交換を受けた血液は臍静脈を通って胎児へ戻るため、胎児循環のなかで最も酸素分圧が高い。静脈管を経て下大静脈から右房に入り、卵円孔を通って優先的に脳と上半身へ送られる。

出典：厚生労働省ホームページ 第116回医師国家試験 E007',
     '{"B": "胎児の肺は換気されておらず、肺静脈血の酸素分圧は低い。", "C": "動脈管には肺動脈の低酸素血が流れる。", "D": "上大静脈には上半身からの静脈血が戻る。", "E": "内腸骨動脈は臍動脈へつながる低酸素の血液である。"}'),
    ('116-E-8', '正答は A「敗血症 — ノルアドレナリン」。

敗血症性ショックは血管拡張による血液分布異常性ショックで、十分な輸液でも血圧が保てない場合はノルアドレナリンを第一選択の昇圧薬として用いる。

出典：厚生労働省ホームページ 第116回医師国家試験 E008',
     '{"B": "大量出血には輸血と止血が必要で、ヘパリンは出血を助長する。", "C": "徐脈性不整脈にはアトロピンや経皮ペーシングを用いる。", "D": "肺血栓塞栓症には抗凝固療法や血栓溶解療法を行う。", "E": "アナフィラキシーの第一選択はアドレナリンの筋注である。"}'),
    ('116-E-9', '正答は C「亜急性期」。

地域医療構想の病床機能区分は高度急性期・急性期・回復期・慢性期の4つで、亜急性期は含まれない。

出典：厚生労働省ホームページ 第116回医師国家試験 E009',
     '{"A": "高度急性期は集中治療室など特に高い医療資源を投入する機能である。", "B": "急性期は急性期の患者に医療を提供する機能である。", "D": "回復期はリハビリテーションを提供し在宅復帰を支える機能である。", "E": "慢性期は長期にわたる療養を担う機能である。"}'),
    ('116-E-10', '正答は B「妊娠蛋白尿」。

妊娠高血圧症候群の病型は、妊娠高血圧腎症・妊娠高血圧・加重型妊娠高血圧腎症・高血圧合併妊娠の4つである。蛋白尿のみで高血圧を伴わない「妊娠蛋白尿」は現在の分類に含まれない。

出典：厚生労働省ホームページ 第116回医師国家試験 E010',
     '{"A": "妊娠高血圧は妊娠20週以降の高血圧で蛋白尿や臓器障害を伴わないものである。", "C": "高血圧合併妊娠は妊娠前または妊娠20週までに高血圧を認めるものである。", "D": "妊娠高血圧腎症は高血圧に蛋白尿または臓器障害を伴うものである。", "E": "加重型妊娠高血圧腎症は高血圧合併妊娠に蛋白尿や臓器障害が加わったものである。"}'),
    ('116-E-11', '正答は E「弾性ストッキング着用」。

弾性ストッキングは下肢の静脈還流を助けて静脈うっ滞を防ぎ、間欠的空気圧迫法とともに周術期の静脈血栓塞栓症の物理的予防法として用いられる。

出典：厚生労働省ホームページ 第116回医師国家試験 E011',
     '{"A": "絶飲食は脱水と血液濃縮を招き、血栓形成をむしろ促す。", "B": "長期臥床は静脈うっ滞をつくる最大の危険因子で、早期離床が予防になる。", "C": "酸素投与は血栓形成を防がない。", "D": "尿道カテーテルの留置は離床を妨げ、予防に逆行する。"}'),
    ('116-E-13', '正答は E「肋骨脊柱角の叩打痛」。

肋骨脊柱角(CVA)の叩打痛は腎実質の炎症による所見で、発熱・膿尿と併せて腎盂腎炎の診断を支持する。膀胱炎との鑑別点になる。

出典：厚生労働省ホームページ 第116回医師国家試験 E013',
     '{"A": "Grey-Turner徴候は側腹部の皮下出血で、出血性膵炎や後腹膜出血の所見である。", "B": "Rovsing徴候は左下腹部の圧迫で右下腹部に痛みが生じる虫垂炎の所見である。", "C": "Rosenstein徴候も虫垂炎の所見で、左側臥位で圧痛が増強する。", "D": "反跳痛は腹膜刺激徴候で、腎盂腎炎に特異的ではない。"}'),
    ('116-E-15', '正答は C「石綿肺 — fine crackles」。

石綿肺は間質性肺疾患で、吸気終末に聴かれる細かい断続性ラ音(fine crackles)が特徴である。ばち指を伴うことも多い。

出典：厚生労働省ホームページ 第116回医師国家試験 E015',
     '{"A": "COPDでは呼気延長と笛声音(wheeze)を聴取する。stridorは上気道狭窄の所見である。", "B": "胸膜炎では胸膜摩擦音(friction rub)を聴取する。", "D": "肺水腫では粗い断続性ラ音(coarse crackles)を聴取する。Hamman徴候は縦隔気腫の所見である。", "E": "気管支喘息ではwheezeを聴取する。"}'),
    ('116-E-16', '正答は B「受療行動調査」。

受療行動調査は、患者が医療機関を選んだ理由、受けた医療の内容、待ち時間、そして満足度などを調べる調査である。

出典：厚生労働省ホームページ 第116回医師国家試験 E016',
     '{"A": "患者調査は傷病の種類や受療率など医療の需要を把握する調査で、満足度は扱わない。", "C": "病院機能評価は第三者機関による医療の質の評価で、患者への満足度調査そのものではない。", "D": "医療事故調査制度は予期しない死亡事例の原因究明と再発防止のための制度である。", "E": "産科医療補償制度は分娩に関連して発症した重度脳性麻痺への補償制度である。"}'),
    ('116-E-17', '正答は A「脳性麻痺」。

脳性麻痺は周産期などに生じた非進行性の脳病変による運動障害で、上位運動ニューロンの障害により痙性麻痺(筋緊張亢進・腱反射亢進・病的反射)を呈する型が最も多い。

出典：厚生労働省ホームページ 第116回医師国家試験 E017',
     '{"B": "ボツリヌス症は神経筋接合部の遮断による弛緩性麻痺である。", "C": "脊髄性筋萎縮症は前角細胞の変性による下位運動ニューロン障害で、弛緩性麻痺となる。", "D": "Prader-Willi症候群は乳児期の著明な筋緊張低下が特徴である。", "E": "Guillain-Barré症候群は末梢神経の脱髄による弛緩性麻痺である。"}'),
    ('116-E-18', '正答は D「注射針は皮膚に対し直角に刺入する。」。

筋肉注射では、皮下組織を越えて筋層に確実に届かせるため皮膚に対して90度で刺入する。三角筋では肩峰から3横指下を選ぶ。

出典：厚生労働省ホームページ 第116回医師国家試験 E018',
     '{"A": "18Gは太すぎる。ワクチンの筋注には23〜25G程度を用いる。", "B": "接種後に揉むと組織の損傷や吸収の変動を招くため、揉まずに押さえる。", "C": "逆流が「ない」ことを確認する。逆流があれば血管内であり刺し直す。", "E": "アナフィラキシーは接種後30分以内に多く、少なくとも15〜30分の観察が必要である。"}'),
    ('116-E-19', '正答は C「横紋筋融解症」。

横紋筋融解症は筋の広範な壊死による病態で、静脈採血で起こるものではない。

出典：厚生労働省ホームページ 第116回医師国家試験 E019',
     '{"A": "消毒用アルコールなどへのアレルギー反応は起こりうる。", "B": "血管迷走神経反射は採血中の失神として最も頻度の高い合併症である。", "D": "神経損傷は穿刺部位によっては起こりうる重大な合併症である。", "E": "皮下血腫は圧迫不十分などで日常的にみられる合併症である。"}'),
    ('116-E-20', '正答は B「適用となるのは常時50人以上の事業場である。」。

長時間労働者に対する医師の面接指導は、事業場の規模にかかわらずすべての事業場に義務づけられている。常時50人以上という要件があるのは産業医の選任やストレスチェックの実施である。

出典：厚生労働省ホームページ 第116回医師国家試験 E020',
     '{"A": "メンタルヘルス対策として、うつ病や自殺の予防は目的に含まれる。正しい。", "C": "過重労働による脳・心臓疾患の発症予防が制度の主眼である。正しい。", "D": "時間外・休日労働が月80時間を超え疲労の蓄積が認められる労働者は、申出により面接指導を受けられる。正しい。", "E": "事業者には面接指導の実施義務がある。正しい。"}'),
    ('116-E-21', '正答は B「突然、意識を失い倒れこんだ。」。

Adams-Stokes症候群は徐脈性・頻脈性不整脈による脳虚血で、前駆症状なく突然意識を失い、不整脈が改善すれば速やかに意識が戻る。

出典：厚生労働省ホームページ 第116回医師国家試験 E021',
     '{"A": "排尿後の失神は状況失神(神経調節性失神)である。", "C": "意識回復後に麻痺が残るのは脳卒中を示唆する。", "D": "舌咬傷はてんかん発作を示唆する。", "E": "回復後のもうろう状態(発作後もうろう)もてんかんを示唆する。"}'),
    ('116-E-22', '正答は D「末梢神経伝導検査」。

手根管症候群では正中神経が手根管内で絞扼される。末梢神経伝導検査で手関節部の遠位潜時延長と伝導速度低下を示し、絞扼部位を客観的に示せる。

出典：厚生労働省ホームページ 第116回医師国家試験 E022',
     '{"A": "脳波検査は大脳の機能評価で、末梢神経の絞扼は分からない。", "B": "針筋電図は神経原性変化の有無を見るが、絞扼部位の同定には伝導検査が有用である。", "C": "脳脊髄液検査は中枢神経疾患の評価に用いる。", "E": "反復誘発筋電図は重症筋無力症など神経筋接合部疾患の検査である。"}'),
    ('116-E-23', '正答は C「システムレビューを行うと家族歴についての情報が充実する。」。

システムレビューは全身の各系統について症状の有無を系統的に確認する手順で、見落としを防ぐためのものである。家族歴の情報を充実させるものではない。

出典：厚生労働省ホームページ 第116回医師国家試験 E023',
     '{"A": "表情や姿勢、視線などの非言語的情報は病歴の重要な手がかりになる。正しい。", "B": "感情に応答することで信頼関係が築かれ、語りが深まる。正しい。", "D": "解釈モデルを踏まえた説明は納得につながり、満足度を高める。正しい。", "E": "疾患と治療についての理解が深まれば治療の遵守は高まる。正しい。"}'),
    ('116-E-24', '正答は B「前立腺肥大」。

前立腺肥大症は下部尿路の閉塞をきたし、進行すると尿を排出できない尿閉に至る。男性の尿閉の原因として最も多い。

出典：厚生労働省ホームページ 第116回医師国家試験 E024',
     '{"A": "尿道下裂は外尿道口の位置異常で、通常は尿閉をきたさない。", "C": "膀胱尿管逆流は尿が上行する病態で、排出障害ではない。", "D": "間質性膀胱炎は頻尿と膀胱痛が主症状である。", "E": "クラミジア性尿道炎は排尿時痛と分泌物が主症状である。"}'),
    ('116-E-25', '正答は A「アトピー性皮膚炎の合併」。

アナフィラキシーの病歴聴取では、原因(誘因)の特定が最も重要である。アトピー性皮膚炎の合併はアトピー素因を示すが、今回の発症の誘因を教えてくれるものではない。

出典：厚生労働省ホームページ 第116回医師国家試験 E025',
     '{"B": "食物が誘因として最も多く、直近の食事内容は必須の情報である。", "C": "蜂毒は代表的な誘因で、刺傷歴の確認は重要である。", "D": "食物依存性運動誘発アナフィラキシーを見分けるため、食後の運動の有無を聞く。", "E": "薬剤も主要な誘因で、内服薬の確認は欠かせない。"}'),
    ('116-E-27', '正答は B「K 7.0mEq/L」。

脈拍32/分の徐脈と低血圧、眼前暗黒感があり、高カリウム血症による徐脈性不整脈を考える。K 7.0mEq/Lではテント状T波から幅広いQRS、洞停止・房室ブロックへ進み、心停止に至りうる。グルコン酸カルシウム静注を急ぐ。

出典：厚生労働省ホームページ 第116回医師国家試験 E027',
     '{"A": "低ナトリウム血症は意識障害やけいれんをきたすが、徐脈の原因にならない。", "C": "Cl 92mEq/Lの軽度低下は徐脈と関係しない。", "D": "Ca 8.0mg/dLの軽度低下ではQT延長を生じうるが、この徐脈は説明しない。", "E": "P 5.0mg/dLは軽度高値で、この病態と直接関係しない。"}'),
    ('116-E-28', '正答は C「経鼻胃管挿入」。

誤嚥性肺炎に敗血症を合併し、嘔吐と上腹部膨隆がある。胃内容を減圧しないと再び誤嚥して肺炎が悪化するため、経鼻胃管を挿入して排液する。

出典：厚生労働省ホームページ 第116回医師国家試験 E028',
     '{"A": "貧血や出血を示す所見がなく、輸血の適応がない。", "B": "SpO2 94%で自発呼吸も保たれており、直ちに挿管する段階ではない。", "D": "血栓症を示す所見はなく、ヘパリンの適応がない。", "E": "β遮断薬は敗血症性ショックの循環をさらに悪化させる。"}'),
    ('116-E-30', '正答は E「尿道カテーテル挿入」。

けいれん重積では気道・呼吸・循環の確保と抗けいれん薬の投与が最優先である。尿道カテーテルは急性期の救命処置に直接寄与せず、優先度が低い。

出典：厚生労働省ホームページ 第116回医師国家試験 E030',
     '{"A": "チアノーゼを認めており酸素投与は必須である。", "B": "けいれん中は舌根沈下や分泌物で気道が閉塞しやすく、気道確保が要る。", "C": "抗けいれん薬の静脈投与と血糖・電解質の評価のために静脈路が必要である。", "D": "15分以上持続しており、ジアゼパムなど抗けいれん薬の投与が必要である。"}'),
    ('116-E-31', '正答は E「「なぜそのようなお気持ちになったのか、お話し下さいますか」」。

「死なせてほしい」という訴えの背景には、制御できていない痛みや、迷惑をかけているという思い、孤独がある。まずその気持ちの中身を尋ね、痛みの再評価と支援体制の見直しにつなげる。

出典：厚生労働省ホームページ 第116回医師国家試験 E031',
     '{"A": "励ましは訴えを否定することになり、患者を孤立させる。", "B": "積極的安楽死は我が国では認められておらず、実施できない。", "C": "本人は自宅で最期を迎えることを希望しており、まず気持ちを聴かずに転院を提案するのは希望に反する。", "D": "末期肺癌に根治的治療はなく、虚偽の説明にあたる。"}'),
    ('116-E-34', '正答は C「服薬管理を本人に任せる。」。

改訂長谷川式16点と巧緻機能障害があり独居である。服薬を本人だけに任せると飲み忘れや過量服用が起こる。一包化や訪問看護・薬剤師による服薬支援を組み立てる必要がある。

出典：厚生労働省ホームページ 第116回医師国家試験 E034',
     '{"A": "心不全の管理と服薬支援のため訪問看護の導入は適切である。", "B": "要介護認定を受けてサービスにつなぐことは適切である。", "D": "血縁者がなく判断能力の低下があるため、成年後見制度の検討は適切である。", "E": "多職種で情報を共有することは在宅療養を支えるうえで適切である。"}'),
    ('116-E-35', '正答は C「収入が無くなる事への不安」。

全人的苦痛のうち社会的苦痛は、仕事・経済・家庭内の役割など社会生活上の問題から生じる苦痛である。休業により収入が絶たれることへの不安がこれにあたる。

出典：厚生労働省ホームページ 第116回医師国家試験 E035',
     '{"A": "死への恐怖はスピリチュアルペイン(実存的苦痛)にあたる。", "B": "上腹部の痛みは身体的苦痛である。", "D": "診断されることへの恐怖は精神的苦痛である。", "E": "受診が遅れたという後悔も精神的苦痛にあたる。"}'),
    ('116-E-36', '正答は C「起床時の日光浴」。

起床時に日光を浴びると体内時計がリセットされ、約14〜16時間後に自然な眠気が訪れる。睡眠薬に頼る前に行うべき睡眠衛生指導の基本である。

出典：厚生労働省ホームページ 第116回医師国家試験 E036',
     '{"A": "アルコールは入眠を早めるが睡眠を浅くし中途覚醒を増やす。高齢者ではとくに避ける。", "B": "効果不十分だからと増量すると、転倒やせん妄の危険が高まる。", "D": "長い昼寝は夜間の睡眠圧を下げる。昼寝は30分以内にとどめる。", "E": "カフェインの作用は数時間続くため、夕方以降の摂取は避ける。"}'),
    ('116-E-37', '正答は C「アドレナリン筋注」。

甲殻類摂取後に嘔吐、意識レベル低下、血圧78/52mmHg、膨疹、喘鳴が出現しており、アナフィラキシーショックである。直ちにアドレナリン0.01mg/kgを大腿前外側に筋注する。

出典：厚生労働省ホームページ 第116回医師国家試験 E037',
     '{"A": "β刺激薬吸入は気管支攣縮に補助的だが、循環虚脱には無効である。", "B": "アトロピンは徐脈に用いる薬剤で、この病態の適応ではない。", "D": "抗ヒスタミン薬は皮膚症状にしか効かず、効果発現も遅い。", "E": "ステロイドは遅発相の予防に用いるもので、急性期の第一選択にはならない。"}'),
    ('116-E-47', '正答は A「10%」。

4項目のうち当てはまるのは発熱・口蓋扁桃の白苔・咳がないの3つである。リンパ節腫大は後頸部で、項目にある前頸部ではないため数えない。当てはまるのが3つのときの事前確率は35%で、事前オッズは0.35/0.65≒0.54、陰性尤度比0.2を掛けて事後オッズは約0.11、事後確率は0.11/(1+0.11)≒0.10で10%になる。

出典：厚生労働省ホームページ 第116回医師国家試験 E047',
     '{"B": "事前確率35%を陰性の結果でいくらか下げただけの値で、尤度比を掛ける計算になっていない。", "C": "事前確率をほぼそのまま残した値で、陰性という結果が反映されていない。", "D": "後頸部の腫大を前頸部と取り違えて4項目とし、事前確率52%をそのまま答えたときの値に近い。検査結果を使っていない。", "E": "確率が上がる向きの値で、陰性尤度比ではなく陽性尤度比を当てはめたときの形になっている。"}'),
    ('116-E-48', '正答は C「唾液」。

抗EBV VCA IgM抗体が陽性で、異型リンパ球10%、肝脾腫、扁桃の白苔を伴う伝染性単核球症である。EBVは唾液中に排出され、food/飲み物の回し飲みやキスなど唾液を介して伝播する。

出典：厚生労働省ホームページ 第116回医師国家試験 E048',
     '{"A": "サイトメガロウイルスでは尿中排泄が問題になるが、EBVの主な伝播経路ではない。", "B": "汗を介して伝播することは知られていない。", "D": "糞便を介するのは経口感染する腸管ウイルスの経路で、EBVには当てはまらない。", "E": "輸血や臓器移植で伝播することはあるが、日常生活で他者への感染源となるのは唾液である。"}'),
    ('116-F-1', '正答は A「ケアマネジャー」。

介護保険サービスの利用計画(ケアプラン)を作成し、事業所との調整を行うのは介護支援専門員(ケアマネジャー)である。通所リハビリテーションの導入もここを通す。

出典：厚生労働省ホームページ 第116回医師国家試験 F001',
     '{"B": "歯科衛生士は口腔ケアを担う。", "C": "訪問看護師は在宅での医療的ケアを提供する。", "D": "ホームヘルパーは訪問介護のサービスを提供する。", "E": "理学療法士はリハビリテーションを実施する側で、サービスの調整は行わない。"}'),
    ('116-F-2', '正答は C「就労上の留意点を指導する。」。

主治医は病状に基づいて、就労にあたり避けるべき作業や配慮すべき点を具体的に示す。これが産業医や事業者による就業上の措置につながる。

出典：厚生労働省ホームページ 第116回医師国家試験 F002',
     '{"A": "復職の可否と就業上の措置を最終的に判断するのは事業者で、産業医が意見を述べる。", "B": "上司の同席は本人の同意が前提で、必須ではない。", "D": "雇用主への情報提供は本人の同意なしにはできない。", "E": "治療と仕事の両立支援は、仕事を続けながら治療を受けられるようにする取り組みである。"}'),
    ('116-F-3', '正答は C「神経」。

放射線感受性は細胞分裂が盛んで未分化な細胞ほど高い(Bergonié-Tribondeauの法則)。神経細胞は分裂しない高度に分化した細胞で、感受性が最も低い。

出典：厚生労働省ホームページ 第116回医師国家試験 F003',
     '{"A": "甲状腺は小児期を中心に感受性があり、被曝で癌のリスクが高まる。", "B": "骨髄は造血幹細胞が盛んに分裂しており、最も感受性が高い組織の一つである。", "D": "皮膚の基底細胞も分裂が盛んで、脱毛や紅斑を生じる。", "E": "卵巣の卵母細胞も感受性が高い。"}'),
    ('116-F-5', '正答は D「甲状腺機能亢進症」。

甲状腺機能亢進症では脂質代謝が亢進し、トリグリセリドもコレステロールもむしろ低下する。高値の原因にならない。

出典：厚生労働省ホームページ 第116回医師国家試験 F005',
     '{"A": "先端巨大症ではGHのインスリン拮抗作用により脂質異常をきたす。", "B": "内臓脂肪の蓄積は遊離脂肪酸の肝への流入を増やし、VLDL産生を高める。", "C": "アルコールは肝でのVLDL合成を促進する。", "E": "インスリン抵抗性はリポ蛋白リパーゼ活性を下げ、トリグリセリドを上昇させる。"}'),
    ('116-F-7', '正答は E「しゃがみ込みで減弱する収縮期雑音 — 閉塞性肥大型心筋症」。

閉塞性肥大型心筋症の収縮期雑音は、左室容積が増えると流出路の狭窄が軽減して減弱する。しゃがみ込みは静脈還流を増やし前負荷を高めるため雑音は弱まる。逆にValsalva手技や立位で増強する。

出典：厚生労働省ホームページ 第116回医師国家試験 F007',
     '{"A": "連続性雑音は動脈管開存症に特徴的である。大動脈弁狭窄兼閉鎖不全では収縮期と拡張期の雑音がそれぞれ聴かれる(to-and-fro)。", "B": "心膜ノック音は収縮性心膜炎の所見である。心タンポナーデでは心音が減弱する。", "C": "吸気で増強する収縮期雑音(Rivero-Carvallo徴候)は三尖弁閉鎖不全症の所見である。", "D": "前傾姿勢で増強する拡張期雑音は大動脈弁閉鎖不全症の所見である。"}'),
    ('116-F-8', '正答は A「子宮腺筋症」。

子宮腺筋症は子宮内膜組織が筋層内に存在する疾患で、子宮の腫大と収縮不良により過多月経と強い月経痛をきたす。

出典：厚生労働省ホームページ 第116回医師国家試験 F008',
     '{"B": "子宮腔癒着症(Asherman症候群)では内膜が失われ、過少月経や無月経となる。", "C": "Sheehan症候群は下垂体前葉機能低下で、無月経と乳汁分泌不全をきたす。", "D": "多囊胞性卵巣症候群は稀発月経・無月経が特徴である。", "E": "高プロラクチン血症も無月経の原因である。"}'),
    ('116-F-9', '正答は B「尋常性乾癬」。

尋常性乾癬は境界明瞭な紅斑と銀白色の鱗屑を特徴とする皮膚の疾患で、粘膜疹はほとんどみられない。

出典：厚生労働省ホームページ 第116回医師国家試験 F009',
     '{"A": "扁平苔癬は頰粘膜にレース状の白色線条(Wickham線条)を生じる。", "C": "膿疱性乾癬では地図状舌など口腔内の変化を伴うことがある。", "D": "尋常性天疱瘡は口腔粘膜のびらんで発症することが多い。", "E": "多形滲出性紅斑、とくに重症型では口唇・口腔粘膜のびらんを伴う。"}'),
    ('116-F-10', '正答は A「高度医療の提供」。

離島の診療所に求められるのは、限られた資源のなかで初期対応を行い、必要な患者を本土の医療機関へつなぐことである。高度医療をその場で提供することは現実的でなく、優先度が低い。

出典：厚生労働省ホームページ 第116回医師国家試験 F010',
     '{"B": "保健・福祉との連携は地域全体の健康を支えるうえで欠かせない。", "C": "後方支援病院との連携は紹介・搬送の要である。", "D": "遠隔読影は専門医のいない環境で画像診断を可能にする。", "E": "急変時にヘリコプターや船で搬送する体制の整備は必須である。"}'),
    ('116-F-12', '正答は C「使い方が限定的である。」。

ユニバーサルデザインの7原則は、公平な利用、利用における柔軟性、単純で直感的な利用、分かりやすい情報、うっかりミスへの寛容、身体的負担の少なさ、接近と利用のための空間である。使い方が限定的であることは柔軟性の原則に反する。

出典：厚生労働省ホームページ 第116回医師国家試験 F012',
     '{"A": "公平な利用は第1原則である。", "B": "身体的負担が少ないことは第6原則である。", "D": "単純で直感的な利用は第3原則である。", "E": "誤りへの寛容は第5原則である。"}'),
    ('116-F-13', '正答は E「免疫能低下の患者に生じることが多い。」。

院内肺炎は入院48時間以降に発症する肺炎で、基礎疾患や治療により免疫能が低下した患者に起こることが多い。緑膿菌や耐性菌が起炎菌となりやすい。

出典：厚生労働省ホームページ 第116回医師国家試験 F013',
     '{"A": "院内肺炎の主要な検出菌は緑膿菌、黄色ブドウ球菌、腸内細菌科細菌などである。肺炎球菌は市中肺炎の主要菌である。", "B": "人工呼吸器関連肺炎は院内肺炎に含まれる。", "C": "入院48時間以内の発症は市中肺炎として扱う。", "D": "院内肺炎の死亡率は医療・介護関連肺炎より高い。"}'),
    ('116-F-14', '正答は C「左右が分かる。」。

左右の区別がつくのは5〜6歳ごろで、選択肢のなかで最も遅い。

出典：厚生労働省ホームページ 第116回医師国家試験 F014',
     '{"A": "円を模写できるのは3歳ごろである。", "B": "はさみを使えるのは3歳ごろである。", "D": "片足立ちができるのは3〜4歳ごろである。", "E": "ごっこ遊びは2〜3歳ごろから始まる。"}'),
    ('116-F-15', '正答は E「顕微鏡的多発血管炎」。

顕微鏡的多発血管炎はANCA関連血管炎で、好中球の顆粒成分であるミエロペルオキシダーゼに対する自己抗体(MPO-ANCA)が高率に陽性となる。急速進行性糸球体腎炎と肺胞出血が問題になる。

出典：厚生労働省ホームページ 第116回医師国家試験 F015',
     '{"A": "川崎病にANCAは関与せず、診断は臨床基準による。", "B": "高安動脈炎は大型血管炎でANCAは陰性である。", "C": "巨細胞性動脈炎も大型血管炎でANCAは陰性である。", "D": "結節性多発動脈炎は中型血管炎で、ANCAは通常陰性である。"}'),
    ('116-F-16', '正答は D「水平半盲 — 加齢黄斑変性」。

加齢黄斑変性は黄斑部の病変なので中心暗点と変視症をきたす。水平半盲(高位・低位半盲)は網膜中心動脈分枝閉塞や視神経・視路の病変でみられ、加齢黄斑変性の所見ではない。

出典：厚生労働省ホームページ 第116回医師国家試験 F016',
     '{"A": "Bjerrum暗点は緑内障に特徴的な弓状の視野欠損である。", "B": "盲中心暗点は視神経炎や中毒性視神経症でみられる。", "C": "両耳側半盲は視交叉中央部を圧迫する下垂体腺腫の所見である。", "E": "輪状暗点は網膜色素変性の初期にみられる。"}'),
    ('116-F-17', '正答は C「被保護世帯数は高齢者世帯が最も多い。」。

被保護世帯を世帯類型別にみると高齢者世帯が最も多く、全体の半数を超えている。単身高齢者の増加が背景にある。

出典：厚生労働省ホームページ 第116回医師国家試験 F017',
     '{"A": "生活保護基準は厚生労働大臣が定める。", "B": "被保護世帯数は高齢者世帯の増加により高止まりし、近年も減少に転じていない。", "D": "保護開始の理由では傷病や貯金等の減少・喪失が多く、要介護状態が最多ではない。", "E": "生活保護受給者は国民健康保険の適用から除外され、医療扶助により医療を受ける。"}'),
    ('116-F-18', '正答は A「凝集性(食塊のまとまり)が高い」。

食塊がひとまとまりになりやすい(凝集性が高い)食品は、咽頭をまとまって通過するため誤嚥しにくい。とろみを付けるのはこの性質を高めるためである。

出典：厚生労働省ホームページ 第116回医師国家試験 F018',
     '{"B": "均質性が低くばらけやすい食品はまとまらず、誤嚥しやすい。", "C": "付着性が高いと咽頭に残留し、後から誤嚥する原因になる。", "D": "硬度が高いと咀嚼で食塊を作りにくい。", "E": "温度が高いことは誤嚥の予防にならない。むしろ体温に近い温度は嚥下反射を起こしにくい。"}'),
    ('116-F-19', '正答は D「薬剤相互作用は考慮せずに処方する。」。

高齢者では複数の薬による相互作用が有害事象の主要な原因になる。相互作用を考慮せずに処方することは、ポリファーマシー対策として明確に誤りである。

出典：厚生労働省ホームページ 第116回医師国家試験 F019',
     '{"A": "かかりつけ薬局に一本化すると重複や相互作用を薬剤師が把握できる。", "B": "同種同効薬の重複の確認は基本的な対応である。", "C": "お薬手帳の携行は他院での処方を含めた把握につながる。", "E": "病状が安定していれば減薬(処方の見直し)を検討するのは適切である。"}'),
    ('116-F-20', '正答は A「児童福祉施設が規定されている。」。

児童福祉施設について定めているのは児童福祉法である。次世代育成支援対策推進法は、子育て支援のための行動計画の策定を国・地方公共団体・事業主に求める法律である。

出典：厚生労働省ホームページ 第116回医師国家試験 F020',
     '{"B": "国民も子育て支援に協力する責務を負うと規定されている。", "C": "次代の社会を担う子どもが健やかに生まれ育つ環境の整備が目的である。", "D": "国及び地方公共団体の責務が規定されている。", "E": "常時雇用する労働者が100人を超える事業主に一般事業主行動計画の策定が義務づけられている。"}'),
    ('116-F-21', '正答は C「ママ、ブーブーなど意味のあることばをいくつか話しますか。」。

1歳6か月では有意語(ママ、ブーブーなど意味のあることば)がいくつか出ているかを確認する。これが1歳6か月健康診査の言語発達の目安である。

出典：厚生労働省ホームページ 第116回医師国家試験 F021',
     '{"A": "自分の名前が言えるのは3歳ごろの目安である。", "B": "2語文が出るのは2歳ごろの目安である。", "D": "喃語のような発声は生後6か月ごろの目安で、1歳6か月では遅すぎる基準である。", "E": "簡単な指示の理解は1歳前後の目安で、言語表出の評価にはならない。"}'),
    ('116-F-23', '正答は E「臍レベルの温痛覚障害」。

Brown-Séquard症候群では、後索と皮質脊髄路は同側性の障害となり、外側脊髄視床路は交叉後に上行するため対側の温痛覚が障害される。右半分の離断なので、左半身には障害レベルのやや下方から温痛覚障害が現れる。乳頭は第4胸髄、臍は第10胸髄に相当する。

出典：厚生労働省ホームページ 第116回医師国家試験 F023',
     '{"A": "腹壁反射の消失は同側(右)に生じる。", "B": "Babinski徴候は錐体路障害の所見で同側(右)に出る。", "C": "Hoffmann反射も同側の上位運動ニューロン徴候である。", "D": "振動覚は後索を通り同側性なので、障害は右に出る。"}'),
    ('116-F-24', '正答は E「精神保健福祉センター」。

精神保健福祉センターは地域住民の精神保健福祉を担う都道府県の機関で、職場の自殺予防対策の枠組みに直接位置づけられる組織ではない。

出典：厚生労働省ホームページ 第116回医師国家試験 F024',
     '{"A": "産業医はメンタルヘルス対策の中心的な役割を担う。", "B": "衛生管理者は職場の衛生管理を統括し、対策の実務を担う。", "C": "産業保健師は健康相談や保健指導を通じて関わる。", "D": "産業保健総合支援センターは事業場の産業保健活動を支援する機関である。"}'),
    ('116-F-25', '正答は A「IgG」。

糸球体基底膜は分子量と電荷によるふるいとして働き、分子量約15万でマイナス荷電のIgGはほとんど濾過されない。健常者の尿にIgGが出ないのはこのためである。

出典：厚生労働省ホームページ 第116回医師国家試験 F025',
     '{"B": "イヌリンは分子量約5,000で自由に濾過され、糸球体濾過量の測定に用いられる。", "C": "グルコースは自由に濾過されたのち近位尿細管でほぼ全量が再吸収される。", "D": "ナトリウムは自由に濾過される。", "E": "クレアチニンも自由に濾過され、腎機能の指標に用いられる。"}'),
    ('116-F-39', '正答は C「気管内の煤付着」。

気管内の煤の付着は、火災発生時に呼吸をしていた、すなわち生存していたことを示す生活反応である。血中一酸化炭素ヘモグロビン濃度の上昇も同様の意義をもつ。

出典：厚生労働省ホームページ 第116回医師国家試験 F039',
     '{"A": "頭蓋内の燃焼血腫は加熱により硬膜外に血液が滲出したもので、死後の加熱でも生じる。", "B": "皮膚の熱傷は死後の焼損でも生じ、生存の証明にならない。", "D": "熱により屈筋が収縮して生じる闘士型姿勢(拳闘家肢位)も死後変化である。", "E": "死斑は死後に生じる所見である。"}'),
    ('116-F-42', '正答は C「ネフローゼ症候群」。

眼瞼を含む全身の圧痕性浮腫が急速に進み、1か月で8kgの体重増加がある。心不全や肝疾患を示す所見がなく、低アルブミン血症による浮腫すなわちネフローゼ症候群を第一に考える。尿蛋白の定量を急ぐ。

出典：厚生労働省ホームページ 第116回医師国家試験 F042',
     '{"A": "肺高血圧症では頸静脈怒張やII音肺動脈成分の亢進を伴う。", "B": "下肢静脈血栓症は片側性で疼痛を伴い、眼瞼の浮腫は説明できない。", "D": "甲状腺機能低下症の粘液水腫は圧痕を残さない非圧痕性浮腫である。", "E": "Budd-Chiari症候群は肝静脈の閉塞で腹水と肝腫大をきたすが、眼瞼浮腫は生じにくい。"}'),
    ('116-F-43', '正答は B「産瘤は右頭頂骨後部にできる。」。

先進部が小泉門で3時方向、矢状縫合が骨盤横径に一致する第2頭位から、全開大時に小泉門が12時方向で矢状縫合が縦径に一致している。第2回旋(内回旋)が正常に完了した所見である。産瘤は先進部すなわち骨盤入口部で最も低い位置にあたる右頭頂骨の後部にできる。

出典：厚生労働省ホームページ 第116回医師国家試験 F043',
     '{"A": "矢状縫合が縦径に一致し小泉門が恥骨側を向いており、第2回旋は正常に完了している。", "C": "骨重積では先進する側の頭頂骨が上になる。第2頭位では右頭頂骨が左頭頂骨の上に重なる。", "D": "第4回旋(外回旋)では児の顔面は母体の右側を向く。", "E": "体幹娩出では恥骨側にある前在肩甲、すなわち右肩甲が先に娩出される。"}'),
    ('116-F-44', '正答は C「3」。

下顎呼吸は呼吸中枢の機能が失われつつあることを示す死亡直前の徴候で、多くは数時間から24時間以内の死亡を予測させる。家族に立ち会いを希望されている以上、この時点で連絡することが必要である。

出典：厚生労働省ホームページ 第116回医師国家試験 F044',
     '{"A": "呼びかけに答えない意識レベルの低下は数日前から進行しうる。", "B": "嚥下できないことも数日単位で先行する変化である。", "D": "四肢の浮腫は低アルブミン血症などで慢性に生じる。", "E": "1日排便がないことは死期の予測に結びつかない。"}'),
    ('116-F-48', '正答は B「冠動脈造影を施行する。」。

II・III・aVF誘導のST上昇があり、下壁の急性心筋梗塞である。透析患者でも再灌流療法の適応は同じで、直ちに冠動脈造影を行い経皮的冠動脈形成術につなげる。

出典：厚生労働省ホームページ 第116回医師国家試験 F048',
     '{"A": "透析直後で体液過剰はなく、心不全でもないため利尿薬の適応がない。", "C": "透析は本日終了しており、緊急に行う理由がない。", "D": "ST上昇型心筋梗塞であり、経過観察は許されない。", "E": "シャントは血管雑音を聴取でき機能している。胸痛の原因ではない。"}'),
    ('116-F-50', '正答は A「身体依存が認められる。」。

断酒3日目に手指振戦と発汗という離脱症状が出ており、身体依存が形成されていることを示す。離脱期にはベンゾジアゼピンによる管理とビタミンB1の補充を行う。

出典：厚生労働省ホームページ 第116回医師国家試験 F050',
     '{"B": "退職を勧めるのは医師の役割ではなく、就労の継続はむしろ回復を支える。", "C": "アルコール依存症はうつ病を高率に合併する。本例も気分の落ち込みを訴えている。", "D": "治療の中心は断酒の継続を支える心理社会的介入(自助グループ、集団療法)で、薬物療法は補助である。", "E": "否認が強く、自ら治療を求めることは少ない。周囲の働きかけで受診に至ることが多い。"}'),
    ('116-F-51', '正答は B「医療者は袖なしエプロンを装着する。」。

袖なしエプロンでは前腕が露出し、放射性物質による汚染を防げない。長袖のガウンと手袋、キャップ、マスクで全身を覆う必要がある。

出典：厚生労働省ホームページ 第116回医師国家試験 F051',
     '{"A": "医療者自身の被曝線量を把握するため個人線量計は必須である。", "C": "核種によって半減期・放射線の種類・除染方法が異なるため、種類の確認は重要である。", "D": "汚染区域と清潔区域を分けるゾーニングは汚染拡大の防止に必要である。", "E": "除染の効果を確認するためサーベイメータによる測定を行う。"}'),
    ('116-F-54', '正答は B「流行性耳下腺炎」。

新生児聴覚スクリーニングは正常だったが、2歳時のムンプス罹患後に一側の高度感音難聴が生じている。ムンプス難聴は片側性・高度で不可逆的なことが多く、後天性一側性難聴の代表的な原因である。

出典：厚生労働省ホームページ 第116回医師国家試験 F054',
     '{"A": "慢性中耳炎では伝音難聴が主体で、高度感音難聴は説明できない。", "C": "先天性風疹症候群による難聴は出生時から存在し、新生児スクリーニングで検出される。", "D": "新生児仮死の既往はなく、低酸素性虚血性脳症は否定的である。", "E": "Treacher Collins症候群は特徴的な顔貌と外耳道閉鎖を伴い、出生時から明らかである。"}'),
    ('116-F-75', '正答は D「後期流産 — 死産届必要」。

妊娠12週以降22週未満の流産を後期流産という。妊娠14週なので後期流産にあたり、死産の届出に関する規程により妊娠12週以後の死児の出産は死産届が必要である。

出典：厚生労働省ホームページ 第116回医師国家試験 F075',
     '{"A": "妊娠14週は早期流産(12週未満)ではなく、また死産届は必要である。", "B": "診断が誤っている。", "C": "死産届が必要である。", "E": "妊娠22週未満なので早産ではない。", "F": "同様に早産ではない。"}'),
    ('117-A-4', '正答は D「片側性すりガラス陰影」。

急性好酸球性肺炎の陰影は両側びまん性で、すりガラス陰影と小葉間隔壁の肥厚、胸水を伴う。片側性ではない。

出典：厚生労働省ホームページ 第117回医師国家試験 A004',
     '{"A": "両側の胸水貯留は高率に認められる。正しい。", "B": "好酸球の遊走・活性化を担うIL-5が上昇する。正しい。", "C": "急性期には末梢血好酸球が正常のことが多く、これが慢性好酸球性肺炎との違いである。正しい。", "E": "気管支肺胞洗浄液中の好酸球が25%以上に増加することが診断の要である。正しい。"}'),
    ('117-A-5', '正答は D「神経性食思〈欲〉不振症」。

神経性やせ症は思春期から若年成人の女性に圧倒的に多く、男女比はおよそ1:10とされる。

出典：厚生労働省ホームページ 第117回医師国家試験 A005',
     '{"A": "双極I型障害の有病率に明らかな男女差はない。", "B": "アルコール依存症は男性に多い。", "C": "自閉スペクトラム症は男児に多い(およそ4:1)。", "E": "反社会性パーソナリティ障害は男性に多い。"}'),
    ('117-A-7', '正答は A「悪性貧血」。

自己免疫性胃炎(A型胃炎)では胃体部の壁細胞が自己免疫機序で破壊され、内因子の分泌が失われる。回腸末端でのビタミンB12吸収が障害され、悪性貧血(巨赤芽球性貧血)をきたす。

出典：厚生労働省ホームページ 第117回医師国家試験 A007',
     '{"B": "溶血性貧血との関連はない。", "C": "胃MALTリンパ腫はH. pylori感染に関連する。", "D": "鉄欠乏性貧血も初期に生じうるが、A型胃炎に特徴的な合併症は悪性貧血である。", "E": "再生不良性貧血との関連はない。"}'),
    ('117-A-8', '正答は E「マンモグラフィ」。

我が国の対策型乳がん検診は40歳以上の女性を対象に2年に1回のマンモグラフィで行う。死亡率減少効果が示されている方法である。

出典：厚生労働省ホームページ 第117回医師国家試験 A008',
     '{"A": "CTは被曝が多く、対策型検診には用いない。", "B": "MRIは高リスク者の検査で、対策型検診の方法ではない。", "C": "視触診は単独では死亡率減少効果が示されず、現在は推奨されていない。", "D": "超音波検査は有効性の証拠が十分でなく、対策型検診には含まれない。"}'),
    ('117-A-9', '正答は B「静止時振戦」。

静止時振戦はParkinson病でみられる所見である。肝硬変で特徴的なのは羽ばたき振戦(アステリキシス)で、性質が異なる。

出典：厚生労働省ホームページ 第117回医師国家試験 A009',
     '{"A": "手掌紅斑はエストロゲンの代謝障害による。正しい。", "C": "女性化乳房も同じ機序で生じる。正しい。", "D": "くも状血管腫も肝硬変の代表的な皮膚所見である。正しい。", "E": "腹壁静脈怒張(メデューサの頭)は門脈圧亢進による側副血行路である。正しい。"}'),
    ('117-A-11', '正答は B「喘息増悪はウイルス感染後が最も多い。」。

喘息増悪の契機として最も多いのはウイルス性上気道感染(ライノウイルスなど)である。感染対策と増悪時の対応をあらかじめ計画しておくことが重要になる。

出典：厚生労働省ホームページ 第117回医師国家試験 A011',
     '{"A": "吸入ステロイドの普及により喘息死は大きく減少している。", "C": "喫煙は吸入ステロイドの効果を弱める。", "D": "抗IgE抗体は重症の難治例に用いる生物学的製剤で、第一選択ではない。", "E": "急性増悪時には短時間作用性β2刺激薬を用いる。長時間作用性は効果発現が遅い。"}'),
    ('117-A-12', '正答は C「日本住血吸虫症」。

日本住血吸虫症は淡水中のミヤイリガイを中間宿主とし、経皮的にセルカリアが侵入して感染する。性行為による感染ではない。

出典：厚生労働省ホームページ 第117回医師国家試験 A012',
     '{"A": "梅毒は性感染症で、第2期に肝炎を生じることがある。", "B": "B型肝炎ウイルスは血液・体液を介し、性感染症として重要である。", "D": "赤痢アメーバは糞口感染に加え、男性同性間の性行為による感染が問題となっている。", "E": "Fitz-Hugh-Curtis症候群はクラミジアや淋菌の骨盤内感染が肝周囲に波及したものである。"}'),
    ('117-A-13', '正答は C「ビタミンA — 夜盲」。

ビタミンAはロドプシンの構成成分で、欠乏すると暗順応が障害され夜盲をきたす。進行すると眼球乾燥症や角膜軟化症に至る。

出典：厚生労働省ホームページ 第117回医師国家試験 A013',
     '{"A": "葉酸欠乏では大球性(巨赤芽球性)貧血をきたす。小球性ではない。", "B": "ニコチン酸(ナイアシン)欠乏はペラグラで、皮膚炎・下痢・認知症を三徴とする。", "D": "ビタミンB1欠乏(脚気)では腱反射は低下・消失する。", "E": "ビタミンB12欠乏では巨赤芽球性貧血と亜急性連合性脊髄変性症をきたす。皮膚炎ではない。"}'),
    ('117-A-14', '正答は B「下痢」。

胃食道逆流症は胃酸が食道へ逆流する疾患で、胸やけ・呑酸・胸痛・咽頭違和感・慢性咳嗽などの食道外症状をきたす。下痢は下部消化管の症状で、生じにくい。

出典：厚生労働省ホームページ 第117回医師国家試験 A014',
     '{"A": "非心臓性胸痛の原因として頻度が高い。", "C": "呑酸は代表的な症状である。", "D": "咽喉頭の逆流症状として咽頭痛や違和感が出る。", "E": "逆流による迷走神経反射や微少誤嚥で慢性咳嗽をきたす。"}'),
    ('117-A-18', '正答は D「選択緘黙」。

家庭では普通に話せるのに学校など特定の場面で話せなくなり、知的発達に問題がない。選択性緘黙(場面緘黙)で、社交不安を背景とする不安症である。

出典：厚生労働省ホームページ 第117回医師国家試験 A018',
     '{"A": "吃音症は話そうとするときに音の繰り返しや引き伸ばしが生じるもので、場面による差はこれほど明瞭でない。", "B": "Tourette症候群は運動チックと音声チックが持続する疾患である。", "C": "学習障害は読み書き計算など特定の学習能力の障害である。", "E": "素行症は他者の権利を侵害する反復的な行動パターンで、本例に該当しない。"}'),
    ('117-A-19', '正答は C「利尿薬投与」。

反復する回転性めまいに、患側の耳閉感・耳鳴・変動する感音難聴を伴っており、Ménière病である。内リンパ水腫が病態なので、浸透圧利尿薬(イソソルビド)で内リンパ液量を減らす治療を行う。

出典：厚生労働省ホームページ 第117回医師国家試験 A019',
     '{"A": "むしろ水分を十分にとることが内リンパ圧の安定に有用とされる。", "B": "頭位治療(Epley法など)は良性発作性頭位めまい症の治療である。", "D": "抗ウイルス薬は前庭神経炎やRamsay Hunt症候群で検討されるものである。", "E": "ガンマグロブリンの適応となる病態ではない。"}'),
    ('117-A-20', '正答は A「胃全摘術を予定する。」。

設問は「適切でない」対応を選ぶもの。多発肝転移・リンパ節転移・腹膜播種が確認されており、根治手術の適応はない。患者が手術を希望したからといって胃全摘術を予定するのは医学的適応を欠き、侵襲だけを与えることになる。希望の背景を聴き、病状の理解を確かめたうえで標準治療を共有していく。

出典：厚生労働省ホームページ 第117回医師国家試験 A020',
     '{"B": "「家族と相談してきたい」と申し出ており、家族同席での説明は適切である。", "C": "手術を希望する理由を尋ねることは、本人の価値観や不安を知る手がかりになり適切である。", "D": "本人が病状をどう理解しているかの確認は、説明の出発点として適切である。", "E": "セカンドオピニオンの案内は患者の権利であり、適切である。"}'),
    ('117-A-24', '正答は A「終生免疫を獲得する。」。

両眼の充血・眼脂と耳前リンパ節腫脹から流行性角結膜炎(アデノウイルス)である。アデノウイルスには多数の血清型があり、終生免疫は獲得できず何度でも罹患しうる。

出典：厚生労働省ホームページ 第117回医師国家試験 A024',
     '{"B": "感染力が強く、眼科外来や病棟での院内感染の原因となる。正しい。", "C": "手指や器具を介した接触感染で広がる。正しい。", "D": "学校保健安全法の第三種感染症として、医師が感染のおそれがないと認めるまで出席停止となる。正しい。", "E": "手洗いとタオルの共用を避けることが予防の基本である。正しい。"}'),
    ('117-A-25', '正答は B「眼窩部単純CT」。

鉄片が高速で飛入しており眼球穿孔外傷と眼内異物を疑う。単純CTは金属異物の存在と位置を確実に描出でき、診断に有用である。

出典：厚生労働省ホームページ 第117回医師国家試験 A025',
     '{"A": "蛍光眼底造影は網膜血管の評価に用いる検査で、透光体が混濁した状況では施行できない。", "C": "網膜電図は網膜機能の評価で、異物の同定にならない。", "D": "眼部超音波は有用だが、穿孔創のある眼球に探触子を当てると内容の脱出を招く危険がある。", "E": "MRIは金属異物が磁場で移動して眼内をさらに損傷するため禁忌である。"}'),
    ('117-A-28', '正答は D「水痘・帯状疱疹ウイルス」。

耳介の水疱を伴う耳痛と同側の末梢性顔面神経麻痺があり、Ramsay Hunt症候群である。膝神経節に潜伏していた水痘・帯状疱疹ウイルスの再活性化による。

出典：厚生労働省ホームページ 第117回医師国家試験 A028',
     '{"A": "アデノウイルスは咽頭結膜熱や流行性角結膜炎の原因である。", "B": "単純ヘルペスウイルスはBell麻痺の一因とされるが、耳介の水疱は伴わない。", "C": "EBウイルスは伝染性単核球症の原因である。", "E": "ヒトパピローマウイルスは疣贅や子宮頸癌の原因である。"}'),
    ('117-A-30', '正答は D「新鮮凍結血漿」。

破水直後の急激な呼吸困難に、フィブリノゲン50mg/dLという著明な低下を伴っている。羊水塞栓症による産科DICで、フィブリノゲンを含む凝固因子を補充する新鮮凍結血漿の大量投与が治療の中心になる。

出典：厚生労働省ホームページ 第117回医師国家試験 A030',
     '{"A": "感染を示す所見に乏しく、抗菌薬は主治療にならない。", "B": "アルブミンは膠質浸透圧を保つが、凝固因子を含まない。", "C": "けいれんはなく、ジアゼパムの適応がない。", "E": "昇圧薬は循環の補助にはなるが、DICそのものを是正しない。"}'),
    ('117-A-32', '正答は E「代償性呼吸性アシドーシス」。

pH7.26と酸血症があり、PaCO2 68TorrとHCO3− 28mEq/Lで、代償が不十分な呼吸性アシドーシスである。慢性呼吸性アシドーシスであれば腎性代償によりHCO3−はもっと上昇するはずで、急性増悪が加わっていることを示す。「代償性」とは言えない。

出典：厚生労働省ホームページ 第117回医師国家試験 A032',
     '{"A": "心エコーで右心系の拡張と心室中隔の左方偏位があり、肺高血圧を認める。", "B": "PaCO2 68Torrの高二酸化炭素血症は肺胞低換気を示す。", "C": "胸郭形成術後の変形と換気血流不均等によりシャント率は上昇する。", "D": "%VC45%の拘束性障害とFEV1%60%の閉塞性障害を併せもつ混合性換気障害である。"}'),
    ('117-A-33', '正答は E「抗精神病薬の減量により軽快する。」。

抗精神病薬の投与直後からじっとしていられずに歩き回るのはアカシジア(静坐不能症)である。薬剤性の錐体外路症状で、原因薬の減量・中止により軽快する。

出典：厚生労働省ホームページ 第117回医師国家試験 A033',
     '{"A": "ジストニアは持続的な筋収縮による異常肢位で、眼球上転や斜頸として現れる。", "B": "知覚低下は伴わない。", "C": "睡眠時無呼吸症候群とは無関係である。", "D": "脳波に異常は生じない。"}'),
    ('117-A-34', '正答は B「有効な薬物療法がある。」。

不注意・多動・衝動性が複数の場面でみられ、注意欠如多動症である。メチルフェニデート徐放剤やアトモキセチン、グアンファシンなど有効な薬物療法があり、行動療法と併せて用いる。

出典：厚生労働省ホームページ 第117回医師国家試験 A034',
     '{"A": "知的障害を伴わない例が多い。", "C": "多動は年齢とともに目立たなくなることがあるが、不注意は成人期にも残ることが多い。", "D": "養育が原因ではない。脳機能の発達の偏りによると考えられている。", "E": "望ましい行動を具体的に褒めて強化することが、行動療法の基本である。"}'),
    ('117-A-47', '正答は D「完全矯正の眼鏡装用」。

3歳で両眼+6.00Dの強い遠視があり、遠くを見るときにも調節を働かせるため輻湊が過剰になって内斜視をきたす調節性内斜視である。調節麻痺薬下で測定した屈折値をそのまま完全矯正する眼鏡を常用させると、調節の必要がなくなって眼位が正位に戻る。

出典：厚生労働省ホームページ 第117回医師国家試験 A047',
     '{"A": "この年齢で内斜視を放置すると斜視弱視と両眼視機能の未発達を残す。経過観察してよい時期ではない。", "B": "低矯正では残った遠視を補うために調節が働き続け、内斜視が消えない。遠視の眼鏡は完全矯正が原則である。", "C": "プリズム眼鏡は屈折矯正で改善しない斜視角に対して用いるもので、まず完全矯正眼鏡を試すのが順序である。", "E": "手術は完全矯正眼鏡で残った非調節性の斜視角に対して検討する。屈折矯正を試す前の手術は適応がない。"}'),
    ('117-A-56', '正答は E「5」。

6年来の腹痛と下痢で、就職という心理社会的因子で増悪しており過敏性腸症候群がまず疑われる。しかし便潜血陽性は器質的疾患を示唆する警告徴候であり、大腸癌や炎症性腸疾患を除外するために下部消化管内視鏡検査を行う根拠となる。

出典：厚生労働省ホームページ 第117回医師国家試験 A056',
     '{"A": "胸やけは胃食道逆流症を示唆する上部消化管の症状で、下部消化管の検索理由にならない。", "B": "警告徴候となるのは体重減少である。1年間で4kgの増加は器質的疾患を示唆しない。", "C": "脈拍96/分は正常上限にとどまり、消化管出血を示唆するほどの頻脈ではない。", "D": "腸蠕動音の亢進は下痢があれば過敏性腸症候群でもみられ、器質的疾患に特異的ではない。"}'),
    ('117-A-59', '正答は C「強迫性障害」。

自分でも過剰だと分かっているのにやめられない戸締りの確認が反復し、遅刻するほど生活に支障をきたしており強迫性障害である。不合理と自覚している(自我違和的)点と、確認行為という強迫行為が反復する点が診断の決め手になる。

出典：厚生労働省ホームページ 第117回医師国家試験 A059',
     '{"A": "適応障害はストレス因に対する抑うつや不安が主体で、この患者のような定型的な確認強迫は説明できない。", "B": "解離性障害は記憶や同一性の連続性が失われる病態で、健忘や遁走を認めない本例は当てはまらない。", "D": "身体化障害では多彩な身体症状を訴える。身体症状の訴えはない。", "E": "社交〈社会〉不安障害は人前で注視され評価されることへの恐怖で、一人暮らしの自宅の戸締りとは関係しない。"}'),
    ('117-A-63', '正答は D「デング熱」。

東南アジアから帰国後の高熱・筋肉痛に、口腔粘膜の点状出血、白血球2,000という白血球減少、Ht60%という血液濃縮を伴っておりデング熱である。潜伏期は3〜7日と短く、解熱するころに血漿漏出が進んでショックに陥ることがあるため、輸液管理が重要になる。

出典：厚生労働省ホームページ 第117回医師国家試験 A063',
     '{"A": "エボラ出血熱の流行地は中部・西部アフリカで、東南アジアの渡航歴では考えない。", "B": "A型肝炎は黄疸と著明なトランスアミナーゼ上昇が前面に出る。出血傾向や血液濃縮は典型的でない。", "C": "腸チフスは高熱に比して脈が遅い比較的徐脈とバラ疹が特徴で、112/分の頻脈は合わない。", "E": "マラリアは周期的な発熱と溶血性貧血、脾腫を伴う。脾を触知せず、点状出血と血液濃縮が目立つ本例には合わない。"}'),
    ('117-A-69', '正答は E「副腎静脈血サンプリング」。

低カリウム血症を伴う高血圧で、血漿アルドステロン濃度472pg/mLに対し血漿レニン活性0.1ng/mL/時とアルドステロン・レニン比が著明に高く、原発性アルドステロン症である。手術の可否を決めるには片側性か両側性かの判定が要るので、確定後の局在診断として副腎静脈血サンプリングを行う。

出典：厚生労働省ホームページ 第117回医師国家試験 A069',
     '{"A": "FDG-PETは悪性腫瘍の検索に用いる検査で、アルドステロン産生腺腫の同定には役立たない。", "B": "レノグラムは腎の血流と排泄機能をみる検査で、副腎の局在診断はできない。", "C": "腎静脈血サンプリングはレニン分泌の左右差をみる検査で、腎血管性高血圧の評価に用いる。本例はレニンが抑制されている。", "D": "ガリウムシンチグラフィは炎症巣や腫瘍の検索に用いる。副腎皮質の機能を反映する核医学検査はアドステロールシンチグラフィである。"}'),
    ('117-A-72', '正答は A「動脈管開存症」。

右心室83.9%に対して右肺動脈90.2%・左肺動脈92.6%と、肺動脈のレベルで酸素飽和度が段階的に上昇している。左右短絡の流入部位が肺動脈であることを示しており、大動脈から肺動脈へ血液が流れ込む動脈管開存症である。

出典：厚生労働省ホームページ 第117回医師国家試験 A072',
     '{"B": "Fallot四徴症は右左短絡のため大動脈血の酸素飽和度が低下する。大動脈98.8%とは相容れない。", "C": "心房中隔欠損症では右心房の段階で酸素飽和度が上昇する。右心房84.5%は上大静脈82.8%と大差ない。", "D": "心室中隔欠損症では右心室の段階で上昇する。右心室83.9%は右心房84.5%と大差ない。", "E": "房室中隔欠損症〈心内膜床欠損症〉は心房と心室の両方に短絡があり、右心房から酸素飽和度が上がる。"}'),
    ('117-B-1', '正答は C「薬剤に関する報告件数が最も多い。」。

インシデントレポートで報告される事象は薬剤に関するものが最も多く、指示・処方の誤りや与薬時の間違いが上位を占める。原因の分析と再発防止に用いるためのもので、報告者の責任追及には使わない。

出典：厚生労働省ホームページ 第117回医師国家試験 B001',
     '{"A": "保健所への報告義務はない。院内の医療安全管理部門で集計・分析する。", "B": "作成するのは事象に関与した、あるいは発見した医療従事者である。医療安全管理委員会は集まった報告を分析して対策を立てる。", "D": "報告件数が少ないのは報告しにくい組織風土を示すことがあり、安全の質が高い証拠にはならない。", "E": "患者に実害が及ばなかった事例(ヒヤリ・ハット)こそ再発防止の手がかりであり、報告の対象である。"}'),
    ('117-B-2', '正答は B「咳嗽を伴う。」。

喀血は気道からの出血なので、咳嗽とともに喀出される。鮮紅色で泡沫を混じ、アルカリ性であることも吐血との鑑別点になる。

出典：厚生労働省ホームページ 第117回医師国家試験 B002',
     '{"A": "悪心を伴って嘔吐されるのは吐血である。", "C": "食物残渣が混じるのは胃内容とともに嘔出された吐血である。", "D": "タール便は上部消化管からの出血が腸管を通過したもので、吐血に伴う所見である。", "E": "暗赤色やコーヒー残渣様の色調は胃酸で変性した血液で、吐血の特徴である。"}'),
    ('117-B-3', '正答は D「症例対照研究のために患者に許可なく本籍地を含む個人情報を収集した。」。

研究のために診療目的を超えた個人情報を本人の許可なく収集することは、個人情報保護法にも人を対象とする医学系研究の倫理指針にも反する。研究利用には本人の同意、または倫理審査委員会の承認を得たうえでの適切な手続きが必要である。

出典：厚生労働省ホームページ 第117回医師国家試験 B003',
     '{"A": "医療施設への寄付は個々の診療内容に影響を与えない限り受け入れうる。医師個人が診療の見返りとして金品を受け取ることとは区別される。", "B": "自らの能力を超えると判断したときに適切な医療機関へ紹介することは、むしろ医師の義務である。", "C": "サプリメントの使用を頭ごなしに否定せず、健康被害の可能性を伝えて注意を促すのは適切な指導である。", "E": "輸血拒否のような場合に、患者の自己決定を尊重しつつ救命の道を探る努力をすることは倫理的に望ましい対応である。"}'),
    ('117-B-4', '正答は D「臍帯動脈」。

臍帯動脈は胎児から胎盤へ向かう血管で、全身を灌流し終えた血液が流れるため胎児循環で最も酸素飽和度が低い。胎盤でガス交換を受けたあと臍帯静脈として胎児に戻る、という向きを押さえておく。

出典：厚生労働省ホームページ 第117回医師国家試験 B004',
     '{"A": "左心室には卵円孔を経て酸素飽和度の高い血液が流入し、脳と上肢へ送られる。", "B": "静脈管は臍帯静脈の血液を肝を迂回して下大静脈へ導く経路で、酸素飽和度は高い。", "C": "臍帯静脈は胎盤でガス交換を受けた直後の血液で、胎児循環で最も酸素飽和度が高い。", "E": "中大脳動脈は左心系から送り出された比較的酸素飽和度の高い血液を受ける。"}'),
    ('117-B-5', '正答は B「鑑別診断」。

SOAPのA(Assessment)は、SとOから導かれる評価であり、鑑別診断や病態の解釈がここに入る。SOAPは主観的情報・客観的情報・評価・計画の順に整理する記載法である。

出典：厚生労働省ホームページ 第117回医師国家試験 B005',
     '{"A": "現病歴は患者本人が語る情報でS(Subjective)に入る。", "C": "検査結果は測定された客観的情報でO(Objective)に入る。", "D": "身体所見も診察で得た客観的情報でO(Objective)に入る。", "E": "治療計画は次に何をするかを示すのでP(Plan)に入る。"}'),
    ('117-B-6', '正答は D「Osler結節」。

Osler結節は手指や足趾の腹側にできる有痛性の紅色結節で、感染性心内膜炎の免疫複合体による血管炎を反映する。無痛性のJaneway斑や爪下線状出血とともに末梢の血管病変として現れる。

出典：厚生労働省ホームページ 第117回医師国家試験 B006',
     '{"A": "Roth斑は網膜にみられる中心が白い出血斑で、感染性心内膜炎を示唆するが眼底所見であって皮膚所見ではない。", "B": "輪状紅斑はリウマチ熱の大症状の一つで、体幹に環状の紅斑が現れる。", "C": "Koplik斑は麻疹の発疹出現前に頬粘膜に生じる白色斑で、粘膜疹である。", "E": "遊走性紅斑はマダニ刺咬部から環状に拡大するLyme病の初期病変である。"}'),
    ('117-B-7', '正答は C「認知機能」。

3つの単語を言わせて復唱させるのは、改訂長谷川式簡易知能評価スケールやMMSEなど認知機能検査の記銘の項目である。高齢者総合機能評価では身体機能・認知機能・情緒・社会的背景を多面的に評価する。

出典：厚生労働省ホームページ 第117回医師国家試験 B007',
     '{"A": "意欲の評価にはVitality Indexなど、日常の行動観察に基づく尺度を用いる。", "B": "運動機能はTimed Up and Go テストや開眼片脚起立時間、握力などで評価する。", "D": "基本的日常生活動作は食事・移動・排泄などの自立度をBarthel IndexやFIMで評価する。", "E": "手段的日常生活動作は買い物・金銭管理・服薬管理などをLawton尺度や老研式活動能力指標で評価する。"}'),
    ('117-B-9', '正答は A「血小板の減少」。

血小板減少はHELLP症候群など妊娠高血圧症候群の重症化を示す臓器障害の指標で、加重型やけいれん発作への移行を警戒する必要がある。ほかに肝機能障害、腎機能障害、肺水腫、視覚障害や持続する頭痛も重症化の徴候となる。

出典：厚生労働省ホームページ 第117回医師国家試験 B009',
     '{"B": "肺水腫が生じれば呼吸数はむしろ増加する。呼吸数の減少は重症化の指標にならない。", "C": "下腿浮腫は正常妊娠でも高頻度にみられるため、現在の診断基準では重症度の判定に用いない。", "D": "子宮収縮の増強は切迫早産や常位胎盤早期剝離を疑う所見であって、妊娠高血圧症候群そのものの重症度指標ではない。", "E": "尿蛋白/クレアチニン比は増加が病態の進行を示す。低下は重症化を示さない。"}'),
    ('117-B-11', '正答は B「「何をするのも億劫で仕方ありません」」。

「何をするのも億劫」は意欲低下と精神運動制止を表す訴えで、抑うつ状態の中核症状である。抑うつ気分、興味・喜びの喪失とともに、うつ病を疑う手がかりになる。

出典：厚生労働省ホームページ 第117回医師国家試験 B011',
     '{"A": "かっとなりやすいのは易怒性で、躁状態や器質性精神障害、認知症などでみられる。", "C": "落ち着かない気持ちは不安や焦燥を表す訴えで、不安障害でもみられる。", "D": "昼間の傾眠は睡眠時無呼吸症候群や薬剤性など睡眠の問題を示唆する。", "E": "見られている感じは注察妄想で、統合失調症を疑う訴えである。"}'),
    ('117-B-12', '正答は C「一般名による薬剤名の記載は有効である。」。

後発医薬品の使用促進のため一般名(一般的名称)による処方が認められており、薬局で該当する銘柄を調剤できる。処方箋には氏名・年齢・薬名・分量・用法用量・発行年月日・使用期間などの記載が必要である。

出典：厚生労働省ホームページ 第117回医師国家試験 B012',
     '{"A": "使用期間の記載がなければ、交付の日を含めて4日以内である。", "B": "処方箋を交付できるのは医師・歯科医師・獣医師で、薬剤師に発行権限はない。", "D": "患者には保険薬局を選ぶ自由があり、医療機関が特定の薬局を指定することはできない。", "E": "記名押印でもよく、自筆の署名でなければならないわけではない。"}'),
    ('117-B-13', '正答は B「肥大型心筋症」。

肥大型心筋症はサルコメア蛋白の遺伝子変異による常染色体顕性(優性)遺伝形式をとることが多く、半数程度が家族性である。突然死の家族歴も含めて家族内発症を確認することが診断と血縁者のスクリーニングに直結する。

出典：厚生労働省ホームページ 第117回医師国家試験 B013',
     '{"A": "心房細動の大半は加齢・高血圧・心不全・弁膜症などを背景に生じる。家族歴が診断の決め手になることは少ない。", "C": "冠攣縮性狭心症は喫煙や飲酒などの生活習慣の関与が大きい。", "D": "大動脈弁狭窄症は加齢に伴う石灰化が主因で、二尖弁でも多くは孤発例である。", "E": "心サルコイドーシスは原因不明の肉芽腫性疾患で、家族集積性は乏しい。"}'),
    ('117-B-14', '正答は B「40歳」。

介護保険の被保険者は、65歳以上の第1号被保険者と、40歳以上65歳未満の医療保険加入者である第2号被保険者からなる。強制加入となるのは40歳からで、第2号被保険者は特定疾病による要介護状態のときに給付を受けられる。

出典：厚生労働省ホームページ 第117回医師国家試験 B014',
     '{"A": "20歳は国民年金の強制加入開始年齢である。", "C": "60歳から始まる公的な保険制度はない。", "D": "65歳は第1号被保険者になる年齢で、加入が始まる年齢ではない。", "E": "75歳は後期高齢者医療制度の対象となる年齢である。"}'),
    ('117-B-15', '正答は C「結節性紅斑」。

結節性紅斑は下腿伸側に生じる有痛性の皮下結節で、圧痛はあっても瘙痒はきたしにくい。溶連菌感染やサルコイドーシス、Behçet病、炎症性腸疾患などに伴って現れる。

出典：厚生労働省ホームページ 第117回医師国家試験 B015',
     '{"A": "薬疹の多くは瘙痒を伴う播種状の紅斑として現れる。", "B": "蕁麻疹は強い瘙痒を伴う膨疹が出没するのが特徴である。", "D": "多形滲出性紅斑は標的状の紅斑で、瘙痒や灼熱感を伴う。", "E": "アトピー性皮膚炎は瘙痒が診断に必須の症状である。"}'),
    ('117-B-16', '正答は C「血圧低下」。

緊張性気胸では胸腔内圧の上昇が縦隔を健側へ圧排し、静脈還流が妨げられて血圧が低下する。閉塞性ショックであり、画像検査を待たずに患側の胸腔穿刺による脱気を行う。

出典：厚生労働省ホームページ 第117回医師国家試験 B016',
     '{"A": "ばち指は慢性の低酸素血症や肺癌、間質性肺炎、Fallot四徴症などで生じ、急性の緊張性気胸では認めない。", "B": "奇異呼吸は吸気時に胸壁が陥凹する所見で、フレイルチェストや上気道閉塞でみられる。", "D": "縦隔動揺は呼吸性に縦隔が左右へ振れる所見で、フレイルチェストや開放性気胸でみられる。緊張性気胸では縦隔は健側へ偏位したままになる。", "E": "患側の肋間腔はむしろ開大し、胸郭の膨隆と打診上の鼓音を伴う。"}'),
    ('117-B-17', '正答は D「相手の話を熱心に聞く。」。

傾聴は相手の話に関心を向けて熱心に聞く態度そのものを指す。うなずきや相づち、沈黙を待つといった非言語的な促しによって、患者が語りやすい場をつくることが目的である。

出典：厚生労働省ホームページ 第117回医師国家試験 B017',
     '{"A": "事実の確認は必要な作業だが、聞き手の関心に沿って情報を確かめる行為であり傾聴とは異なる。", "B": "助言を挟むと患者の語りが途切れる。傾聴の段階では判断や助言を控える。", "C": "時間を区切って聞くことは効率のための工夫であって、傾聴の要件ではない。", "E": "あらかじめ決めた項目を順に尋ねるのは構造化面接であり、患者の語りに従う傾聴とは対照的である。"}'),
    ('117-B-18', '正答は D「アミノグリコシド系」。

アミノグリコシド系は有効域と中毒域が近く、腎障害と第8脳神経障害(聴力障害・平衡障害)を起こすため治療薬物モニタリングの対象となる。ほかにバンコマイシン、テイコプラニン、アルベカシン、ボリコナゾールが対象である。

出典：厚生労働省ホームページ 第117回医師国家試験 B018',
     '{"A": "カルバペネム系は治療域が広く、通常TDMの対象としない。", "B": "ニューキノロン系は経口吸収がよく、血中濃度測定は日常的には行わない。", "C": "リンコマイシン系(クリンダマイシンなど)もTDMの対象ではない。", "E": "セファロスポリン系は安全域が広く、血中濃度の測定は不要である。"}'),
    ('117-B-19', '正答は D「横隔膜ヘルニア」。

先天性横隔膜ヘルニアでは胎生期に腹部臓器が胸腔内へ脱出し、肺の発育を妨げるため肺低形成をきたす。出生直後から呼吸不全と肺高血圧をきたすので、バッグマスク換気を避けて気管挿管を行い、循環を安定させてから手術する。

出典：厚生労働省ホームページ 第117回医師国家試験 B019',
     '{"A": "水頭症は脳室の拡大による病態で、肺の発育には影響しない。", "B": "二分脊椎は下肢の運動・感覚障害や膀胱直腸障害をきたすが、肺低形成は伴わない。", "C": "臍帯ヘルニアは腹腔外に臓器が脱出するもので、胸腔は圧迫されない。", "E": "先天性食道閉鎖症は気管食道瘻を伴うことが多く誤嚥性肺炎をきたすが、肺低形成の原因にはならない。"}'),
    ('117-B-20', '正答は D「完全房室ブロック — 安静臥位」。

完全房室ブロックによる失神(Adams-Stokes発作)は心室補充調律の停止や心室細動によって起こり、体位とは関係なく生じる。安静臥位はむしろ静脈還流を保って失神を防ぐ体位であり、誘因にはならない。

出典：厚生労働省ホームページ 第117回医師国家試験 B020',
     '{"A": "α遮断薬は末梢血管を拡張させて起立時の血圧低下を招くため、起立性低血圧の誘因として正しい。", "B": "頸動脈洞症候群では頸部の伸展や回旋、きつい襟、髭剃りなどの刺激が徐脈と血圧低下を招く。正しい組合せである。", "C": "Brugada症候群では発熱がナトリウムチャネルの機能異常を助長し、心室細動の引き金となる。正しい組合せである。", "E": "閉塞性肥大型心筋症では激しい運動により左室流出路の狭窄が強まり、心拍出量が低下して失神する。正しい組合せである。"}'),
    ('117-B-21', '正答は A「国民皆保険制度である。」。

我が国は全国民が何らかの公的医療保険に加入する国民皆保険制度をとっており、1961年に達成された。フリーアクセス、現物給付、原則3割の一部負担が特徴である。

出典：厚生労働省ホームページ 第117回医師国家試験 B021',
     '{"B": "予防接種や健康診断、正常分娩など疾病の治療にあたらないものは保険給付の対象外である。定期接種は予防接種法に基づき公費で行う。", "C": "保険医を登録するのは厚生労働大臣である。保険者は保険料を集めて給付を行う主体である。", "D": "後期高齢者医療制度の対象は75歳以上、および65歳以上で一定の障害があると認定された者である。", "E": "被用者保険の保険料は事業主と被保険者が原則として折半して負担する。"}'),
    ('117-B-22', '正答は E「被験者への説明と同意文書の取得」。

介入を伴う臨床研究では、目的・方法・予測される利益と不利益・拒否しても不利益を受けないことなどを説明したうえで、被験者本人から文書で同意を得る必要がある。インフォームド・コンセントは説明と自発的な同意の取得によって初めて成立する。

出典：厚生労働省ホームページ 第117回医師国家試験 B022',
     '{"A": "薬物を服用したという事実をもって同意とみなすことはできない。同意は投与に先立って得るものである。", "B": "主治医の同意は被験者本人の同意の代わりにならない。同意する権利は被験者にある。", "C": "倫理委員会の承認は研究を実施するための要件だが、個々の被験者から同意を得る手続きとは別である。", "D": "ホームページでの公示による情報公開(オプトアウト)は既存資料を用いる観察研究などで認められる方式で、ランダム化比較試験には用いられない。"}'),
    ('117-B-23', '正答は B「イヌリンクリアランスは正確なGFR評価に用いられる。」。

イヌリンは糸球体で自由に濾過され、尿細管で再吸収も分泌も受けないため、そのクリアランスがそのまま糸球体濾過量に等しくなる。手技が煩雑なので日常診療では推算GFRを用いるが、正確な測定の基準となるのはイヌリンクリアランスである。

出典：厚生労働省ホームページ 第117回医師国家試験 B023',
     '{"A": "血清クレアチニン値はGFRが半分程度に低下するまで基準範囲にとどまる(クレアチニン盲域)。軽度低下では上昇しない。", "C": "健常者でも30〜40歳ごろから加齢とともに緩やかにGFRが低下する。", "D": "筋肉量が少ないと血清クレアチニン値が低く出るため、eGFRは実測GFRより高く見積もられる。", "E": "成人のeGFRは血清クレアチニン値、年齢、性別から計算する。身長を用いるのは小児の推算式である。"}'),
    ('117-B-25', '正答は E「患者が未成年の場合、患者の意思よりも代理人の希望が優先される。」。

リスボン宣言では、法的無能力の患者であっても、判断能力があればその意思決定に参加する権利を認めており、患者の意思は尊重されなければならないとしている。代理人の希望が一律に優先されるわけではない。

出典：厚生労働省ホームページ 第117回医師国家試験 B025',
     '{"A": "患者には知る権利とともに、知らされないことを明確に要求する権利も認められている。", "B": "医学教育や医学研究への参加を拒否する権利が明記されている。", "C": "意識のない患者や自殺企図の患者については、常に患者の最善の利益に沿って生命を救う努力をするとされている。", "D": "患者の秘密は死後も守られなければならないと明記されている。"}'),
    ('117-B-26', '正答は A「表情をみながら触診する。」。

重度の認知症で言葉による訴えができない患者では、表情の変化が疼痛や不快を伝える主要な手がかりになる。うなり声も苦痛の表現でありうるので、表情を確かめながらゆっくり触診し、痛みの部位を探る。

出典：厚生労働省ホームページ 第117回医師国家試験 B026',
     '{"B": "右側臥位では下側になる右半身に浮腫が偏る。体位の影響を考慮して両側を比べる必要がある。", "C": "拘縮した関節を無理に伸展させると強い疼痛や骨折を招く。可動域の範囲内で診察する。", "D": "重度の認知症では指示が通らず、うなり声は苦痛の表現でもある。抑えさせるべきものではない。", "E": "疼痛が疑われる部位に打診を繰り返せば苦痛を強いることになる。"}'),
    ('117-B-27', '正答は D「横紋筋融解症」。

慣れないフルマラソン後の筋肉痛と赤黒い尿で、尿潜血3+にもかかわらず沈渣に赤血球を認めないことから、ミオグロビン尿を反映した横紋筋融解症である。ミオグロビンは尿潜血反応を陽性にするが赤血球としては見えない。急性腎障害と高カリウム血症を警戒し、大量輸液を行う。

出典：厚生労働省ホームページ 第117回医師国家試験 B027',
     '{"A": "膀胱炎では排尿時痛や頻尿を伴い、沈渣に白血球と細菌を認める。", "B": "IgA腎症では沈渣に変形赤血球や赤血球円柱を認め、蛋白尿を伴うことが多い。", "C": "尿路結石では側腹部の疝痛発作を伴い、沈渣に赤血球を認める。", "E": "多発性囊胞腎では両側の腹部腫瘤と高血圧、家族歴を認め、血尿は赤血球によるものである。"}'),
    ('117-B-28', '正答は D「患者の推定意思を尊重し家族と医療チームが話し合って決定する。」。

本人の意思が確認できないときは、家族等から本人の価値観や過去の言動を聴き取って推定意思を尊重し、それに基づいて何が本人にとって最善かを医療・ケアチームと家族が繰り返し話し合って決める。人生の最終段階における医療・ケアの決定プロセスに関するガイドラインの基本的な考え方である。

出典：厚生労働省ホームページ 第117回医師国家試験 B028',
     '{"A": "決定の基礎になるのは家族の希望ではなく本人の推定意思である。本例では家族の意見も分かれている。", "B": "傾眠状態で呼びかけに反応せず、現時点で本人が意思決定できる状態にない。", "C": "医学的な妥当性だけで医療チームが決めてよいものではない。本人の推定意思と家族との合意形成が要る。", "E": "複数の専門職からなる委員会は、話し合っても合意に至らない場合に助言を求める仕組みであり、最初から判断を委ねる場ではない。"}'),
    ('117-B-29', '正答は D「体重」。

体重は日々同じ条件で測れば体液貯留を最も鋭敏かつ定量的に反映する。数日で2〜3kg増えれば心不全の増悪を疑う手がかりになり、自己管理の指標として在宅での測定が勧められる。

出典：厚生労働省ホームページ 第117回医師国家試験 B029',
     '{"A": "体温は体液量を反映せず、感染などの合併を知る指標である。", "B": "脈拍は活動や情動でも変動し、体液量の指標としての特異度が低い。", "C": "血圧も測定条件や服薬で変動し、体液貯留を早期に捉える指標にはならない。", "E": "浮腫が目に見えるようになるのは数kgの体液貯留が生じた後で、体重変化より遅れて現れる。"}'),
    ('117-B-30', '正答は E「「痛みの原因をどのように考えていますか」」。

解釈モデルとは、患者が自分の症状の原因や意味をどう理解しているかという考えである。これを尋ねることで患者の心配の中身が分かり、説明の焦点を定めやすくなる。解釈・感情・影響・期待の4つを聞き出すのが医療面接の基本である。

出典：厚生労働省ホームページ 第117回医師国家試験 B030',
     '{"A": "受診の理由を広く尋ねる開放型質問で、解釈モデルを直接引き出す問いではない。", "B": "痛みの性状という症状の情報を集める質問である。", "C": "心理社会的な背景を探る質問で、患者自身の解釈を尋ねてはいない。", "D": "症状の経過を確かめる質問である。"}'),
    ('117-B-32', '正答は A「鼻翼をつまむ。」。

鼻出血の大部分は鼻中隔前方のKiesselbach部位からで、座って軽く前かがみになり、鼻翼を指でつまんで10〜20分圧迫すれば止まることが多い。硬い鼻骨ではなく柔らかい鼻翼を左右から押さえるのがこつである。

出典：厚生労働省ホームページ 第117回医師国家試験 B032',
     '{"B": "仰臥位にすると血液が咽頭へ流れ込み、誤嚥や嘔吐を招く。座位で軽く前傾させる。", "C": "冷罨法は補助的なもので、これだけでは止血できない。", "D": "後頸部を叩いても止血効果はない。", "E": "飲み込んだ血液は嘔気・嘔吐を誘発するため、口から吐き出させる。"}'),
    ('117-B-35', '正答は C「3」。

徒手筋力テストで、重力に抗して全可動域の運動ができるが抵抗を加えると保てない状態は3(Fair)である。重力に抗せるかどうかが2と3の、抵抗に抗せるかどうかが3と4の境目になる。

出典：厚生労働省ホームページ 第117回医師国家試験 B035',
     '{"A": "1(Trace)は筋収縮を触知できるが関節運動が起こらない状態である。", "B": "2(Poor)は重力を除いた肢位でのみ全可動域の運動ができる状態である。", "D": "4(Good)は中等度の抵抗に抗して全可動域の運動ができる状態である。", "E": "5(Normal)は強い抵抗に抗して全可動域の運動ができる状態である。"}'),
    ('117-B-36', '正答は B「ジアゼパム」。

けいれんが反復して意識が戻らない、あるいは5分以上続く状態はてんかん重積状態であり、第一選択はベンゾジアゼピン系のジアゼパム静注である。抗けいれん薬の自己中断が誘因になっている。呼吸抑制に備えて気道管理の準備をしておく。

出典：厚生労働省ホームページ 第117回医師国家試験 B036',
     '{"A": "モルヒネは鎮痛薬で抗けいれん作用はなく、呼吸抑制を加えるだけである。", "C": "フロセミドは利尿薬でけいれんの治療薬ではない。", "D": "アドレナリンは心停止やアナフィラキシーに用いる。", "E": "グルコン酸カルシウムは低カルシウム血症によるテタニーや高カリウム血症の心筋保護に用いる。"}'),
    ('117-B-37', '正答は E「ゆっくり呼吸するように指導する。」。

満員バスという状況で誘発された頻呼吸に、SpO2は100%で低酸素はなく、呼吸性アルカローシスによる口周囲と四肢のしびれを伴っており過換気症候群である。安心させたうえで、意識してゆっくり呼吸するよう指導すれば軽快する。

出典：厚生労働省ホームページ 第117回医師国家試験 B037',
     '{"A": "抗精神病薬の適応はない。不安が強ければ抗不安薬を考慮する。", "B": "症状が続いたまま帰すのは不適切で、まず呼吸を落ち着かせる。", "C": "SpO2は100%で低酸素血症はなく、酸素投与を要さない。", "D": "紙袋再呼吸法は低酸素血症を招いて死亡した例が報告されており、現在は行わない。"}'),
    ('117-B-38', '正答は B「診療方針について患者本人に説明し意向を聞く。」。

聴覚障害と軽度の知的障害が疑われても意識は清明で、意思決定能力がないと決めつけてはならない。筆談や図の使用などその人に合った方法で分かるように説明し、本人の意向を確かめることが出発点になる。

出典：厚生労働省ホームページ 第117回医師国家試験 B038',
     '{"A": "本人への意思決定支援を尽くさずに医師が代行して決めてよいものではない。", "C": "民生委員は地域の相談・見守りを担う非常勤の特別職公務員で、法定代理権をもたない。成年後見人とみなすことはできない。", "D": "意思決定が難しいことを理由に検査や治療を控えるのは、障害を理由とする不利益な取扱いにあたる。", "E": "医学的所見のみで客観的に決めるのは、本人の価値観や意向を無視した対応である。"}'),
    ('117-B-40', '正答は B「異状死の届出」。

診療中の疾病と関係のない外因や、死因に異状が疑われる状況で死亡を確認した場合、医師は24時間以内に所轄警察署へ届け出なければならない(医師法第21条)。肺炎が治癒し退院予定だった患者が点滴チューブの外れとともに死亡しており、異状死として届け出る。

出典：厚生労働省ホームページ 第117回医師国家試験 B040',
     '{"A": "現場は保存する必要があり、清掃してしまうと検証ができなくなる。", "C": "異状死の届出先は所轄警察署であって保健所ではない。", "D": "病理解剖は病死の死因を究明するためのもので、遺族の承諾も要る。この状況ではまず警察への届出が先である。", "E": "死因を診療中の疾病で説明できないため死亡診断書は書けない。届出を経たうえで死体検案書となる。"}'),
    ('117-B-43', '正答は D「退職して治療に専念するよう伝える。」。

設問は「誤っている」対応を選ぶもの。38歳でADLは自立し歩行も可能で、外来での抗癌化学療法を続けながら働ける。治療と仕事の両立を支えるのがいまの標準であり、医師が退職を勧めるのは本人の生活基盤を奪うことになる。

出典：厚生労働省ホームページ 第117回医師国家試験 B043',
     '{"A": "何をどこまで理解しているかを確かめることは、以降の相談の前提になる。", "B": "職場にどう伝えるかは両立支援の中心で、助言は適切である。", "C": "幼い子を養う不安を訴えており、心理面の支援は必要である。", "E": "使える制度を知らせることは、経済的な不安をやわらげる具体的な支援になる。"}'),
    ('117-B-44', '正答は C「高額療養費制度」。

外来での抗癌化学療法は費用がかさむが、高額療養費制度により月ごとの自己負担に上限が設けられる。限度額適用認定証をあらかじめ受け取っておけば、窓口での支払いも上限までで済む。

出典：厚生労働省ホームページ 第117回医師国家試験 B044',
     '{"A": "介護保険は65歳以上、または40歳以上で末期がんなどの特定疾病に該当する場合に使う。38歳では対象にならない。", "B": "障害年金は初診から一定期間の経過などの要件があり、この時点では該当しない。", "D": "自立支援医療は精神通院医療・更生医療・育成医療が対象で、がんの化学療法は含まれない。", "E": "指定難病医療費助成の対象は国が定める難病で、がんは含まれない。"}'),
    ('117-B-45', '正答は C「③」。

造影CTを撮れるかどうかを左右するのは腎機能で、ヨード造影剤は腎障害のある患者で造影剤腎症を起こしうる。下線部③のeGFRは保たれており、造影は可能と判断できる。

出典：厚生労働省ホームページ 第117回医師国家試験 B045',
     '{"A": "尿沈渣に白血球がないことは尿路感染の否定に役立つが、造影剤を使えるかどうかとは関わらない。", "B": "総ビリルビンの上昇は胆道系の評価に関わるもので、造影の可否を決めない。", "D": "尿酸値は造影剤の使用可否と関係しない。", "E": "血清Naも造影の可否を決める指標ではない。"}'),
    ('117-B-49', '正答は A「胸部CT」。

左胸部の強打後に呼吸困難と血痰が続き、胸部エックス線写真で左肺の虚脱と胸水の貯留がある。外傷性の血気胸と肺挫傷を考え、損傷の範囲と出血源を同時に見るために胸部CTを撮る。短時間で撮れ、肋骨骨折や大血管の損傷まで一度に評価できる。

出典：厚生労働省ホームページ 第117回医師国家試験 B049',
     '{"B": "MRIは撮像に時間がかかり、循環が不安定な外傷の急性期には向かない。", "C": "FDG-PETは腫瘍の評価に使うもので、急性外傷の検査ではない。", "D": "肺動脈造影は侵襲が大きく、この段階で選ぶ検査ではない。", "E": "肺血流シンチグラフィは肺血栓塞栓症を疑うときの検査である。"}'),
    ('117-B-50', '正答は E「弾性ストッキング着用」。

安静臥床が続けば下肢の静脈血がうっ滞し、深部静脈血栓から肺塞栓に至る。本例は出血のあとで貧血が進み、血小板も減っており、抗凝固薬は使いにくい。弾性ストッキングによる物理的な予防が適している。

出典：厚生労働省ホームページ 第117回医師国家試験 B050',
     '{"A": "酸素投与は低酸素血症への対応で、血栓ができるのを防ぐものではない。", "B": "抗菌薬は感染への対応で、血栓の予防とは関係しない。", "C": "血栓溶解薬はできた血栓を溶かす治療であり、出血のある外傷患者には使えない。", "D": "気管支拡張薬は気道の狭窄に対するもので、血栓予防にはならない。"}'),
    ('117-C-2', '正答は A「二次医療圏単位で構築される。」。

地域包括ケアシステムが想定する範囲は、おおむね30分以内に必要なサービスが提供される日常生活圏域(中学校区程度)である。二次医療圏は一般的な入院医療を提供する単位で、地域包括ケアの単位ではない。

出典：厚生労働省ホームページ 第117回医師国家試験 C002',
     '{"B": "住まいを土台に、介護予防と生活支援を基盤として医療・介護・リハビリテーションの専門的サービスが乗るという構造で示される。", "C": "市町村が3年ごとに策定する介護保険事業計画を通じて、地域の実情に応じて構築していく。", "D": "高齢者が尊厳を保ちながら住み慣れた地域で自分らしい暮らしを続けられるようにすることを目的としている。", "E": "地域ケア会議では個別事例の検討を積み重ねることで地域に共通する課題を見いだし、政策形成につなげる。"}'),
    ('117-C-3', '正答は B「曝露因子と関連している。」。

交絡因子は、曝露因子と関連があり、かつそれ自体が結果の危険因子であって、曝露から結果に至る中間段階にはない因子である。この3条件を満たすため、見かけ上の関連を生んだり真の関連を隠したりする。

出典：厚生労働省ホームページ 第117回医師国家試験 C003',
     '{"A": "交絡は系統誤差(バイアス)の一種であり、標本の偶然のばらつきによる偶然誤差とは異なる。", "C": "交絡はコホート研究でも生じる。無作為割付を行わない限り曝露群と非曝露群の背景がそろわないためである。", "D": "統計学的に有意かどうかと交絡の有無は別の問題で、有意でなくても効果推定値は歪みうる。", "E": "解析段階で対象を絞り込んだり追跡から脱落したりすることでも新たな歪みが生じる。交絡はデザインと解析の両方で対処する。"}'),
    ('117-C-4', '正答は D「トリアージは医師以外の医療職も行うことができる。」。

トリアージは医師に限らず、看護師、救急救命士など訓練を受けた医療職が実施できる。多数傷病者が同時に発生する災害では、限られた資源を最大多数の救命に振り向けるため、START法などで迅速に優先度を判定する。

出典：厚生労働省ホームページ 第117回医師国家試験 C004',
     '{"A": "災害拠点病院を指定するのは都道府県知事である。", "B": "救急救命士は医師の指示のもとで特定行為を行う。医師が救急救命士の指揮下に入ることはない。", "C": "二次医療圏は一般的な入院医療を提供する区域として定められたもので、防災体制の整備単位として定義されたものではない。", "E": "DHEATは被災地の行政機能を支援する保健医療の専門職チームで、災害医療そのものを指す言葉ではない。"}'),
    ('117-C-5', '正答は D「療養期」。

病床機能報告では、医療機関が病棟ごとに高度急性期・急性期・回復期・慢性期の4区分から機能を選んで都道府県に報告する。「療養期」という区分はない。長期療養を担う病床は慢性期に含まれる。

出典：厚生労働省ホームページ 第117回医師国家試験 C005',
     '{"A": "高度急性期は診療密度が特に高い医療を提供する機能で、区分に含まれる。", "B": "急性期は急性期の患者に医療を提供する機能で、区分に含まれる。", "C": "回復期は在宅復帰に向けた医療やリハビリテーションを提供する機能で、区分に含まれる。", "E": "慢性期は長期にわたり療養が必要な患者を入院させる機能で、区分に含まれる。"}'),
    ('117-C-6', '正答は E「アルマ・アタ宣言」。

アルマ・アタ宣言(1978年、WHOとUNICEF)は「すべての人々に健康を」を掲げ、住民の主体的な参加と地域資源の活用によって基本的な保健医療を提供するプライマリヘルスケアの理念を打ち出した。

出典：厚生労働省ホームページ 第117回医師国家試験 C006',
     '{"A": "オタワ憲章(1986年)はヘルスプロモーションを「人々が自らの健康をコントロールし改善できるようにするプロセス」と定義した。", "B": "アデレードでの会議は健康的な公共政策づくりを主題としたヘルスプロモーションの国際会議である。", "C": "ジュネーブ宣言は医師の職業倫理の誓いを現代の言葉に改めたものである。", "D": "ヘルシンキ宣言は人を対象とする医学研究の倫理原則を定めたものである。"}'),
    ('117-C-7', '正答は E「シュレッダー処理された書類」。

事業活動に伴って生じる廃棄物のうち、法令で定める20種類が産業廃棄物である。紙くずは建設業や印刷業など特定の業種から出たものだけが産業廃棄物になるため、医療機関から出る書類は事業系一般廃棄物として扱う。

出典：厚生労働省ホームページ 第117回医師国家試験 C007',
     '{"A": "使用済みメスは血液が付着した鋭利な器材で、感染性産業廃棄物として処理する。", "B": "未使用でも注射針は鋭利な金属くずであり、産業廃棄物として専用容器で処理する。", "C": "アルコール試薬は廃アルコール類として産業廃棄物にあたる。", "D": "使用済みゴム手袋はゴムくず・廃プラスチック類にあたり、感染性であればなお産業廃棄物として処理する。"}'),
    ('117-C-9', '正答は C「C」。

Cは2013年に14,344人と突出し、2018〜2019年にも2,000人を超える流行を示している。成人男性を中心とした大規模流行が2013年と2018年に起きた風疹の推移に一致する。

出典：厚生労働省ホームページ 第117回医師国家試験 C009',
     '{"A": "827人から7,007人へ一貫して増え続けており、近年急増している梅毒である。", "B": "毎年1,000〜1,600人前後で緩やかに減少しており、新規報告数が横ばいの後天性免疫不全症候群である。", "D": "数十人から数百人の間で増減し2019年に744人と近年最多となっており、麻疹である。", "E": "2011〜2013年に報告がなく2014年から十数〜数十人で推移しており、2014年に五類全数把握疾患に追加された薬剤耐性アシネトバクター感染症である。"}'),
    ('117-C-10', '正答は B「セラミド」。

角層では、角化細胞が産生した層板顆粒の内容が細胞間に放出され、セラミド・コレステロール・遊離脂肪酸がラメラ構造をつくる。なかでもセラミドが約半分を占め、水分の保持と経皮的な水分喪失の防止を担う。

出典：厚生労働省ホームページ 第117回医師国家試験 C010',
     '{"A": "ケラチンは角化細胞の内部を満たす中間径フィラメントで、細胞間脂質ではない。", "C": "アミロイドはβシート構造をとる異常蛋白の沈着で、正常の角層構成成分ではない。", "D": "デスモソームは角化細胞どうしを結ぶ接着装置で、蛋白からなる。", "E": "ヘミデスモソームは基底細胞を基底膜に接着させる装置である。"}'),
    ('117-C-11', '正答は C「十二指腸」。

十二指腸は球部を除いて後腹膜に固定されており、腸間膜をもたない。ほかに膵(尾部を除く)、上行結腸、下行結腸、腎、副腎、尿管、腹部大動脈、下大静脈が後腹膜臓器である。

出典：厚生労働省ホームページ 第117回医師国家試験 C011',
     '{"A": "食道は大部分が後縦隔を走り、腹腔内に入る部分はごく短い。後腹膜臓器には数えない。", "B": "胃は小網と大網をもち、腹腔内を可動性をもって位置する。", "D": "空腸は腸間膜をもつ腹腔内臓器で、可動性がある。", "E": "横行結腸は横行結腸間膜をもつ腹腔内臓器である。上行結腸・下行結腸が後腹膜に固定されているのと対照的である。"}'),
    ('117-C-12', '正答は D「2.1」。

人口置換水準は、女性が生涯に産む子どもの数が親世代を過不足なく置き換える水準で、我が国ではおよそ2.07である。女児の出生割合と、女性が出産年齢に達するまでの死亡を考慮するため2をやや上回る。

出典：厚生労働省ホームページ 第117回医師国家試験 C012',
     '{"A": "1.0では次の世代の人口が半減する。", "B": "1.1も人口置換水準を大きく下回る。近年の我が国の合計特殊出生率はこれに近い水準まで低下している。", "C": "1.9はやや下回る水準で、人口は緩やかに減少する。", "E": "4.0は出生率の高い開発途上国でみられる水準である。"}'),
    ('117-C-16', '正答は D「この結果から喫煙による肺癌死亡の寄与危険度が計算できる。」。

曝露の有無で群を分けて10年間追跡したコホート研究である。寄与危険度(リスク差)は曝露群の罹患率から非曝露群の罹患率を引いたもので、1.20−0.10=1.10(人/1,000人年)と計算できる。

出典：厚生労働省ホームページ 第117回医師国家試験 C016',
     '{"A": "疾病の発生前に曝露を把握して追跡しており、コホート研究である。症例対照研究は結果が生じた後に過去の曝露をさかのぼって調べる。", "B": "統計的な関連を示すだけでは因果関係の証明にならない。時間的前後関係、量・反応関係、生物学的妥当性などを併せて判断する。", "C": "喫煙の有無しか示されておらず、喫煙本数別のデータがないため量・反応関係は判断できない。", "E": "相対危険度は1.20÷0.10=12である。1.2は両者の値を取り違えている。"}'),
    ('117-C-17', '正答は B「MRワクチン — 水痘ワクチン」。

2020年10月の改正で異なるワクチン間の接種間隔の制限は原則撤廃され、現在も27日以上あける必要があるのは注射生ワクチンどうしの場合だけである。MRワクチンも水痘ワクチンも注射生ワクチンなので、同時接種しないなら27日以上あける。

出典：厚生労働省ホームページ 第117回医師国家試験 C017',
     '{"A": "ロタウイルスワクチンは経口生ワクチンで、注射生ワクチンとの間隔の制限はない。", "C": "4種混合ワクチンは不活化ワクチンなので、接種間隔の制限を受けない。", "D": "小児用肺炎球菌ワクチンもB型肝炎ワクチンも不活化ワクチンで、間隔の制限はない。", "E": "インフルエンザ桿菌〈Hib〉ワクチンは不活化ワクチンなので、MRワクチンとの間隔の制限はない。"}'),
    ('117-C-18', '正答は E「我が国の相対的貧困率はOECD加盟国の平均より高い。」。

相対的貧困率は等価可処分所得が中央値の半分に満たない人の割合で、我が国は15%前後とOECD加盟国の平均を上回る。生存に必要な最低限の水準を欠く絶対的貧困と異なり、その社会の標準的な生活水準からの隔たりを表す指標である。

出典：厚生労働省ホームページ 第117回医師国家試験 C018',
     '{"A": "1日あたりの所得額で絶対的貧困を定義しているのが世界銀行で、相対的貧困はOECDの定義による。", "B": "生活保護の受給の有無とは無関係に、所得の分布から算出される。", "C": "ひとり親世帯の相対的貧困率は5割近くに達し、単身世帯より高い。", "D": "世帯所得を世帯人員の平方根で割った等価可処分所得を用いるため、世帯の大きさを考慮している。"}'),
    ('117-C-19', '正答は B「介護福祉士」。

介護保険法上の機能訓練指導員になれるのは、理学療法士、作業療法士、言語聴覚士、看護職員、柔道整復師、あん摩マッサージ指圧師、および一定の実務経験のあるはり師・きゅう師である。介護福祉士は含まれない。

出典：厚生労働省ホームページ 第117回医師国家試験 C019',
     '{"A": "看護師は看護職員として機能訓練指導員になれる。", "C": "言語聴覚士は機能訓練指導員になれる。", "D": "作業療法士は機能訓練指導員になれる。", "E": "理学療法士は機能訓練指導員になれる。"}'),
    ('117-C-20', '正答は B「参加制約は生活環境に起因する。」。

ICFの参加制約は、その人が生活・人生の場面に関わるときに経験する困難で、建物や交通、制度、周囲の態度といった環境因子に大きく左右される。同じ機能障害があっても環境が整えば参加制約は生じない、という考え方をとる。

出典：厚生労働省ホームページ 第117回医師国家試験 C020',
     '{"A": "ICFは障害の有無にかかわらずすべての人の生活機能を記述する分類である。", "C": "障害の程度で人を段階づける分類ではなく、心身機能・身体構造、活動、参加という構成要素を中立的な用語で記述する。", "D": "機能障害があっても、環境や個人因子によって活動制限が生じないことがある。一方向の因果ではなく相互作用としてとらえる。", "E": "社会的不利はICIDHの用語で、障害の帰結を一方向にとらえていた。ICFはこれを環境との相互作用でとらえ直して参加制約と呼んでおり、同義ではない。"}'),
    ('117-C-22', '正答は A「家族構成」。

要介護認定の一次判定は、認定調査員が調べる74項目の基本調査と主治医意見書をコンピュータにかけ、介護に要する時間を推計して行う。調査項目は身体機能・起居動作、生活機能、認知機能、精神・行動障害、社会生活への適応などで構成され、家族構成のような介護環境は含まれない。

出典：厚生労働省ホームページ 第117回医師国家試験 C022',
     '{"B": "食事摂取、排尿、外出頻度などの生活機能は調査項目に含まれる。", "C": "意思の伝達、短期記憶、日課の理解などの認知機能は調査項目に含まれる。", "D": "被害的、作話、昼夜逆転などの精神・行動障害(社会的行動)は調査項目に含まれる。", "E": "寝返り、起き上がり、歩行などの基本動作機能(身体機能・起居動作)は調査項目に含まれる。"}'),
    ('117-C-24', '正答は D「患者・家族からの苦情に対応する。」。

医療安全支援センターは、患者や家族からの医療に関する苦情・相談に対応し、助言や情報提供を行う窓口である。医療法に基づいて都道府県、保健所設置市および特別区に設置される。

出典：厚生労働省ホームページ 第117回医師国家試験 C024',
     '{"A": "設置主体は都道府県、保健所を設置する市および特別区で、すべての市町村ではない。", "B": "医療事故調査は医療機関自身が行い、その結果を医療事故調査・支援センターに報告する。名称は似ているが別の仕組みである。", "C": "根拠法は医療法であり、地域保健法ではない。", "E": "相談員を配置するが、看護師の常駐が義務付けられているわけではない。"}'),
    ('117-C-25', '正答は D「へき地医療拠点病院は一次医療圏単位で整備される。」。

へき地医療拠点病院は都道府県が二次医療圏を基本として指定し、無医地区への巡回診療、へき地診療所への医師派遣や代診医の派遣を担う。一次医療圏単位で整備されるものではない。

出典：厚生労働省ホームページ 第117回医師国家試験 C025',
     '{"A": "無医地区などへの巡回診療はへき地医療拠点病院の中心的な役割の一つである。", "B": "遠隔画像診断や遠隔コンサルテーションなど情報通信技術の活用が進められている。", "C": "医療計画では救急医療、災害時医療、へき地医療、周産期医療、小児医療の5事業(現在は新興感染症を加えて6事業)について体制を定める。", "E": "限られた医師で幅広い健康問題に対応する必要があるため、総合的な診療能力をもつ医師の確保が課題とされている。"}'),
    ('117-C-26', '正答は C「肺結核」。

肺結核は飛沫核(空気)感染するため、陰圧に保った個室で管理し、部屋の空気は高性能フィルターを通して排気する。医療者はN95マスクを着用する。麻疹と水痘も同じ空気感染予防策の対象である。

出典：厚生労働省ホームページ 第117回医師国家試験 C026',
     '{"A": "インフルエンザは飛沫感染で、サージカルマスクと個室ないし集団隔離で足りる。陰圧は要さない。", "B": "ウイルス性胃腸炎は接触感染が主で、手指衛生と適切な吐物処理が中心となる。", "D": "流行性角結膜炎は接触感染で、手指衛生と器具の消毒、患者の隔離で対応する。", "E": "流行性耳下腺炎は飛沫感染で、飛沫予防策の対象である。"}'),
    ('117-C-27', '正答は B「食に関する指導(食育)」。

食に関する指導(食育)は学校給食法および食育基本法に規定されており、学校保健安全法の規定ではない。学校保健安全法は健康診断、健康相談、感染症による出席停止、学校環境衛生、学校安全計画などを定める。

出典：厚生労働省ホームページ 第117回医師国家試験 C027',
     '{"A": "職員の健康診断など学校職員の健康の保持増進が規定されている。", "C": "通学路の安全を含め、学校外での安全確保に関する取組みが学校安全計画に位置づけられている。", "D": "事件・事故や災害の後に心身の健康問題を抱える児童生徒への支援(心のケア)が規定されている。", "E": "危険等発生時対処要領の作成など、災害時の児童生徒の安全確保が規定されている。"}'),
    ('117-C-28', '正答は A「Barthel Index〈BI〉」。

Barthel Indexは食事、移乗、整容、トイレ動作、入浴、歩行、階段昇降、更衣、排便・排尿の10項目を採点し、100点満点で日常生活動作の自立度を評価する尺度である。FIMとともにリハビリテーションの場で広く用いられる。

出典：厚生労働省ホームページ 第117回医師国家試験 C028',
     '{"B": "Japan Coma Scaleは意識障害の深度を3-3-9度方式で評価する。", "C": "Glasgow Coma Scaleは開眼、言語反応、運動反応の3項目で意識レベルを評価する。", "D": "Brief Psychiatric Rating Scaleは統合失調症などの精神症状の重症度を評価する。", "E": "Mini-Mental State Examinationは見当識や記銘・計算などから認知機能を評価する。"}'),
    ('117-C-31', '正答は D「医師の臨床研修」。

医師の臨床研修は医師法に規定されている。医療法が定めるのは医療提供施設の開設・管理、医療計画(医療圏、基準病床数、地域医療構想、医療従事者の確保など)、医療安全の確保といった医療提供体制に関する事項である。

出典：厚生労働省ホームページ 第117回医師国家試験 C031',
     '{"A": "医療圏(一次・二次・三次)は医療法に基づく医療計画で定められる。", "B": "基準病床数は病床の地域的な偏在を是正するため医療法に基づいて定められる。", "C": "地域医療構想は2014年の医療法改正で医療計画の一部として位置づけられた。", "E": "医療従事者の確保に関する事項は医療計画に定める項目として医療法に規定されている。"}'),
    ('117-C-32', '正答は B「全職員対象の敷地内禁煙」。

ポピュレーションアプローチは、危険度の高い個人を選び出さずに集団全体に働きかけてリスク分布そのものを下げる方法である。全職員を対象とする敷地内禁煙は、対象を絞らずに集団全体の曝露を減らす典型例である。

出典：厚生労働省ホームページ 第117回医師国家試験 C032',
     '{"A": "肥満者という高リスク者を選んで介入しており、しかも治療的な処置である。", "C": "高血圧と診断された者に絞って治療しており、ハイリスクアプローチである。", "D": "長期欠席という問題が生じた児童に限って介入するハイリスクアプローチである。", "E": "うつ病と診断された患者への治療であり、ハイリスクアプローチにあたる。"}'),
    ('117-C-34', '正答は D「生活保護制度」。

公助は公費(税)を財源として、自助・互助・共助では対応できない困窮に対応する仕組みで、生活保護や虐待対策、人権擁護がこれにあたる。社会保険方式で支え合う制度は共助、自らの健康管理は自助、住民同士の支え合いは互助と整理される。

出典：厚生労働省ホームページ 第117回医師国家試験 C034',
     '{"A": "医療保険制度は保険料を出し合って支え合う社会保険であり、共助にあたる。", "B": "介護保険制度も社会保険であり、共助にあたる。", "C": "雇用保険制度も社会保険であり、共助にあたる。", "E": "特定健康診査は自らの健康管理のために受けるもので、自助に位置づけられる。"}'),
    ('117-C-35', '正答は E「80歳で20歯以上の自分の歯を有する者の割合の目標達成」。

健康日本21(第二次)の中間評価では、80歳で20歯以上の自分の歯を有する者の割合が目標値に達したと評価された。フッ化物の応用や定期的な歯科受診の普及が背景にある。

出典：厚生労働省ホームページ 第117回医師国家試験 C035',
     '{"A": "成人の喫煙率は低下を続けており、増加してはいない。", "B": "野菜摂取量は目標の350gに届かず、果物の摂取量も目標を下回ったままで、改善していない。", "C": "20歳代女性のやせの者の割合は横ばいで、増加したとは評価されていない。", "D": "20歳代で歯肉に炎症所見を有する者の割合は改善しておらず、増加という評価ではない。"}'),
    ('117-C-40', '正答は E「光化学オキシダント」。

夏の日中、快晴・微風・高温という条件で、屋外にいた複数の児童が同時に目の刺激と咽頭痛、咳を訴えている。窒素酸化物と揮発性有機化合物が紫外線を受けて生成する光化学オキシダントによる健康被害である。交通量の多い地域で発生しやすく、注意報が出れば屋外活動を控えさせる。

出典：厚生労働省ホームページ 第117回医師国家試験 C040',
     '{"A": "輻射熱による熱中症であれば体温上昇や発汗停止、意識障害が主体で、目の刺激や咽頭痛は説明できない。", "B": "一酸化炭素中毒は閉鎖空間で起こり、頭痛や意識障害をきたすが眼刺激症状はない。屋外の校庭では考えにくい。", "C": "ダイオキシンは慢性の曝露で問題となる物質で、10km離れた焼却施設から急性の集団症状が出ることはない。", "D": "微小粒子状物質は呼吸器や循環器への影響が中心で、強い眼の刺激症状は特徴的でない。"}'),
    ('117-C-41', '正答は D「「家庭血圧の測定を続けてください」」。

家庭血圧は診察室血圧より予後をよく反映し、白衣高血圧や仮面高血圧の判別、降圧薬の効果判定にも役立つ。良好に管理できている患者にも、測定の継続を勧めるのが適切である。

出典：厚生労働省ホームページ 第117回医師国家試験 C041',
     '{"A": "機会飲酒であり、節酒の助言は要るとしても禁酒を求める根拠はない。", "B": "運動は降圧と心血管リスク低減に有効で、良好な管理が得られている今も続けるべきである。", "C": "自己判断で服薬を中断すると血圧が再上昇する。指示どおりの継続が必要である。", "E": "血圧以外の異常を早期に見つけるためにも、定期的な健康診査は続けるべきである。"}'),
    ('117-C-42', '正答は B「運動の推奨」。

BMI22.0で肥満はなく、食塩摂取5.5g/日、野菜350g/日と食事は良好、飲酒も少量である。是正すべき点は運動習慣がほとんどないことで、有酸素運動を毎日30分程度続けるよう勧めるのが適切である。

出典：厚生労働省ホームページ 第117回医師国家試験 C042',
     '{"A": "ビール350mLを週2回は節度ある適度な飲酒の範囲内で、禁止する必要はない。", "C": "BMI22.0は標準体重であり、減量の対象にならない。", "D": "食塩摂取量5.5g/日は高血圧の食事療法で目標とする6g/日未満をすでに満たしている。", "E": "野菜はカリウムや食物繊維の供給源として摂取が勧められる。制限する理由はない。"}'),
    ('117-C-44', '正答は D「アルギニン負荷試験」。

6歳女児の乳房発育と身長・体重の促進から思春期早発症を疑う。原因検索には頭蓋内病変を除くMRI、卵巣・副腎腫瘍を除く腹部超音波検査、骨年齢の評価が要る。アルギニン負荷試験は成長ホルモンの分泌不全を調べる検査で、成長が促進している本例では必要がない。

出典：厚生労働省ホームページ 第117回医師国家試験 C044',
     '{"A": "中枢性思春期早発症の原因となる視床下部・下垂体の器質性病変を除外するために行う。", "B": "成長速度の変化がいつから起きたかを知るために不可欠である。", "C": "卵巣腫瘍や副腎腫瘍などエストロゲン産生源の検索、子宮・卵巣の成熟度の評価に有用である。", "E": "手根骨エックス線撮影で骨年齢を評価すると、暦年齢を上回る骨成熟の進行を確認できる。"}'),
    ('117-C-45', '正答は C「気管挿管」。

灯油(炭化水素)を飲んでおり、意識レベルはJCS III-100で気道保護反射が失われ、酸素投与下でもSpO2 88%と誤嚥による化学性肺炎が進行している。まず気管挿管により気道を確保し、換気と酸素化を立て直す。

出典：厚生労働省ホームページ 第117回医師国家試験 C045',
     '{"A": "石油製品は誤嚥すると重篤な化学性肺炎を起こすため、胃洗浄は禁忌である。行うとしても気道確保の後になる。", "B": "炭化水素は分布容積が大きく脂溶性が高いため血液透析では除去できない。", "D": "血圧は保たれており、大量輸液を要する循環不全はない。", "E": "高気圧酸素治療は一酸化炭素中毒などの適応で、気道が確保されていない本例では行えない。"}'),
    ('117-C-46', '正答は D「弁護士を代理人として行うことができる。」。

退院請求は入院中の本人または家族等が、都道府県知事に対して退院や処遇改善を求める制度である。本人が直接行うほか、弁護士など代理人を通じて行うこともできる。請求を受けると精神医療審査会が入院の必要性を審査する。

出典：厚生労働省ホームページ 第117回医師国家試験 C046',
     '{"A": "病院長の許可は要らない。病院を介さずに請求できることが制度の要点である。", "B": "書面によるのが原則だが、電話や口頭による請求も受け付けられる。", "C": "閉鎖病棟か開放病棟かを問わず、入院形態にかかわらず行える。", "E": "医療保護入院は本人の同意によらない入院であり、まさに退院請求の対象となる。"}'),
    ('117-C-48', '正答は B「心拍動を認める胎芽」。

最終月経が1月1日なので、3月7日は妊娠9週2日にあたる。胎囊は妊娠5週ごろ、胎芽と心拍動は妊娠6週ごろに確認できるので、この時期には心拍動のある胎芽(胎児)が見える。

出典：厚生労働省ホームページ 第117回医師国家試験 C048',
     '{"A": "胎囊のみが見えるのは妊娠5週前後で、9週で心拍動が確認できないのは流産を疑う所見である。", "C": "木の葉状の子宮内膜像は排卵期にみられる非妊娠時の所見である。", "D": "頭殿長3.0cmとなるのは妊娠10週前後を過ぎてからで、この時期にはやや大きすぎる。", "E": "児頭大横径が測定できるようになるのは妊娠12週以降で、3.0cmは妊娠20週前後の大きさである。"}'),
    ('117-C-50', '正答は E「全身性エリテマトーデス」。

若年女性の多発関節痛に、脱毛、口腔粘膜のびらん、凍瘡様皮疹、蛋白尿と変形赤血球を伴う血尿、白血球減少と血小板減少がそろっており全身性エリテマトーデスである。CRPが上昇しないのに発熱するという解離、APTT延長(ループスアンチコアグラント)も本症を支持する。

出典：厚生労働省ホームページ 第117回医師国家試験 C050',
     '{"A": "皮膚筋炎ではGottron徴候やヘリオトロープ疹と近位筋の筋力低下を伴い、CKが上昇する。CK26U/Lは合わない。", "B": "Behçet病は口腔内アフタ、外陰部潰瘍、ぶどう膜炎、結節性紅斑を主症状とし、腎障害や血球減少は前面に出ない。", "C": "関節リウマチは持続する滑膜炎による関節破壊が主体で、蛋白尿や血球減少、粘膜疹は説明できない。", "D": "Sjögren症候群は乾燥症状が中心で、全身性エリテマトーデスに合併することはあるが本例の多彩な症状の主因とはいえない。"}'),
    ('117-C-51', '正答は A「1」。

3歳では手すりを使って交互に足を出しながら階段を昇れるのが標準で、ひとりで階段を昇れないのは粗大運動の遅れを疑う。ほかの下線部はいずれも3歳としてふつうにみられる発達段階である。

出典：厚生労働省ホームページ 第117回医師国家試験 C051',
     '{"B": "上着を自分で着られるようになるのは4歳ごろで、3歳で脱ぐだけできるのは正常である。", "C": "ルールのある遊びができるようになるのは4〜5歳ごろで、3歳では並行遊びから連合遊びの段階である。", "D": "住所を言えるようになるのは5歳前後で、3歳で名前が言えれば正常である。", "E": "左右の区別がつくのは5〜6歳ごろで、3歳でわからないのは正常である。"}'),
    ('117-C-52', '正答は E「5」。

ICFの生活機能は心身機能・身体構造、活動、参加の3つからなり、参加は仕事、家庭内での役割、地域社会との関わりなど生活・人生場面へのかかわりを指す。近所付き合いがないことは地域社会への参加の状況を表している。

出典：厚生労働省ホームページ 第117回医師国家試験 C052',
     '{"A": "脳出血という病気は健康状態であって、生活機能の3要素には含まれない。", "B": "運動麻痺は心身機能の障害(機能障害)にあたる。", "C": "過疎地域に住んでいることは環境因子にあたる。", "D": "妻と2人暮らしという家族の状況も環境因子にあたる。"}'),
    ('117-C-53', '正答は D「「作業場の室温を下げるようにしましょう」」。

空調のない閉め切った室内での作業中に大量発汗、めまい、頭痛が生じており熱中症(I度)である。作業環境そのものが原因なので、室温を下げて暑熱環境を改善することが最も本質的な対策になる。肥満と睡眠不足はいずれも熱中症の危険因子である。

出典：厚生労働省ホームページ 第117回医師国家試験 C053',
     '{"A": "作業自体をやめる必要はない。環境の改善と水分・塩分の補給、休憩で予防できる。", "B": "肥満は熱の産生が多く放散が悪いため熱中症の危険因子であり、関係がないとはいえない。", "C": "睡眠不足は体調不良として熱中症の危険因子に挙げられており、関係がないとはいえない。", "E": "高齢者や作業中は口渇を自覚しにくい。渇きを感じる前から計画的に水分と塩分を摂る必要がある。"}'),
    ('117-C-57', '正答は E「陰茎」。

喫煙と飲酒はいずれも上気道から上部消化管の扁平上皮を広く傷害するため、口腔・咽頭・喉頭・食道・肺に重複癌が生じやすい(field cancerization)。陰茎癌はヒトパピローマウイルス感染や包茎が主な危険因子で、喫煙・飲酒による重複癌としては可能性が低い。

出典：厚生労働省ホームページ 第117回医師国家試験 C057',
     '{"A": "口腔は喫煙と飲酒が直接作用する扁平上皮で、重複癌の好発部位である。", "B": "下咽頭癌は喉頭癌・食道癌との重複が特に多いことで知られる。", "C": "肺は喫煙による最大の標的臓器で、重複癌の頻度が高い。", "D": "食道扁平上皮癌は喫煙と飲酒が二大危険因子で、頭頸部癌との重複が多い。"}'),
    ('117-C-73', '正答は B「β2刺激薬」。

長い喫煙歴があり、両側でwheezesを聴取し、動脈血ガスで二酸化炭素が溜まっている。慢性閉塞性肺疾患を背景に誤嚥性肺炎を起こした状態で、抗菌薬に加えて短時間作用性β2刺激薬の吸入により気道の攣縮を緩める。

出典：厚生労働省ホームページ 第117回医師国家試験 C073',
     '{"A": "NSAIDは解熱鎮痛薬で気道閉塞を改善しない。腎機能も低下しており避けたい。", "C": "アルブミン製剤は低アルブミン血症を一時的に補うだけで、呼吸状態は改善しない。", "D": "抗ヒスタミン薬はアレルギー性の病態に用いるもので、痰を粘稠にし、高齢者ではせん妄も招く。", "E": "テオフィリンは有効域と中毒域が近く、高齢者では痙攣や不整脈の危険があるため第一選択にならない。"}'),
    ('117-C-74', '正答は E「夜間はベンゾジアゼピン系睡眠薬を用いる。」。

設問は「誤っている」対応を選ぶもの。急に落ち着きを失い、入院中であることを理解できず制止を要する状態はせん妄である。ベンゾジアゼピン系睡眠薬は高齢者のせん妄をかえって悪化させ、転倒も増やすため用いない。

出典：厚生労働省ホームページ 第117回医師国家試験 C074',
     '{"A": "脱水はせん妄の代表的な誘因で、避けるのは正しい。", "B": "臥床を続けること自体がせん妄を長引かせる。早期離床は正しい。", "C": "昼夜のリズムを整えることはせん妄対策の基本である。", "D": "酸素も不要になっており、体につながれた機器を減らすのはせん妄への対応として正しい。"}'),
    ('117-D-2', '正答は B「ベラパミル」。

ベラパミルは非ジヒドロピリジン系カルシウム拮抗薬で陰性変力作用が強く、左室駆出率の低下した心不全では心収縮力をさらに落として増悪させるため使用しない。ジルチアゼムやシベンゾリンなども同じ理由で避ける。

出典：厚生労働省ホームページ 第117回医師国家試験 D002',
     '{"A": "スタチンは心不全を悪化させない。動脈硬化性疾患の二次予防に用いる。", "C": "ACE阻害薬は左室駆出率の低下した心不全の予後を改善する基本薬である。", "D": "SGLT2阻害薬は左室駆出率にかかわらず心不全の予後を改善することが示され、標準治療に組み込まれている。", "E": "プロトンポンプ阻害薬は心収縮力に影響しない。"}'),
    ('117-D-4', '正答は E「新規に透析を導入する原因疾患として患者数が増加傾向である。」。

腎硬化症は高血圧が続くことで細動脈の硬化と糸球体の虚血をきたす病態で、高齢化に伴い透析導入原因の第3位を占め、その割合は増加傾向にある。糖尿病性腎症が第1位、慢性糸球体腎炎が第2位である。

出典：厚生労働省ホームページ 第117回医師国家試験 D004',
     '{"A": "赤血球円柱は糸球体腎炎に特徴的な所見で、腎硬化症では尿沈渣に乏しいのがふつうである。", "B": "蛋白尿は軽度にとどまることが多く、ネフローゼ症候群を呈することはまれである。", "C": "厳格な降圧が腎機能低下の進行を抑えるため、130/80mmHg未満を目標とする降圧が推奨される。", "D": "レニン・アンジオテンシン系抑制薬は蛋白尿を伴う場合に有用で、禁忌ではない。両側腎動脈狭窄など個別の禁忌があるにすぎない。"}'),
    ('117-D-6', '正答は D「妊娠高血圧症候群の高リスクである。」。

抗リン脂質抗体症候群は動静脈血栓症と習慣流産をきたす自己免疫疾患で、妊娠高血圧症候群や胎児発育不全、常位胎盤早期剝離の高リスクである。妊娠中は低用量アスピリンとヘパリンの併用で管理する。

出典：厚生労働省ホームページ 第117回医師国家試験 D006',
     '{"A": "血小板はしばしば減少する。増加はしない。", "B": "妊娠は禁止されない。適切な抗凝固療法のもとで妊娠・出産が可能である。", "C": "ループスアンチコアグラントの影響でAPTTが延長する。プロトロンビン時間の短縮は特徴ではない。", "E": "第一選択は抗血小板薬と抗凝固薬による血栓予防である。副腎皮質ステロイドは基礎疾患がある場合などに限られる。"}'),
    ('117-D-8', '正答は B「母乳栄養」。

母乳栄養は腸管の免疫を助け、壊死性腸炎の発症を減らすことが知られている。発症要因ではなくむしろ予防因子である。腸管の未熟性を背景に、虚血と細菌の異常増殖、経腸栄養の負荷が重なって発症する。

出典：厚生労働省ホームページ 第117回医師国家試験 D008',
     '{"A": "敗血症は循環不全と炎症を介して腸管の虚血を招き、発症要因となる。", "C": "低酸素血症は腸管の血流低下をきたし、発症要因となる。", "D": "低出生体重、とくに極低出生体重児は腸管が未熟で最大の危険因子である。", "E": "動脈管開存では拡張期に腸管への血流が奪われ(steal現象)、腸管虚血をきたす。"}'),
    ('117-D-9', '正答は E「アキレス腱の肥厚」。

家族性高コレステロール血症では、高LDLコレステロール血症、腱黄色腫、家族歴の3つが診断の柱になる。なかでもアキレス腱の肥厚は特徴的で、軟線撮影で厚さ9mm以上(男性)を目安に評価する。

出典：厚生労働省ホームページ 第117回医師国家試験 D009',
     '{"A": "角膜混濁はLCAT欠損症や魚眼病でみられる。家族性高コレステロール血症では角膜輪(老人環)がみられる。", "B": "扁桃の橙黄色腫大はコレステロールエステル転送に関わるTangier病の特徴である。", "C": "赤血球の変形(有棘赤血球)は無βリポ蛋白血症などでみられる。", "D": "手掌線条黄色腫はIII型高脂血症(家族性III型高リポ蛋白血症)に特徴的である。"}'),
    ('117-D-10', '正答は B「骨盤骨折」。

骨盤骨折では後腹膜腔に大量の出血をきたし、循環血液量の半分近くを失うこともある。後腹膜は圧迫止血が効きにくく死因になりやすいので、骨盤輪の不安定性を認めたら骨盤固定具を装着し、輸血と経カテーテル動脈塞栓術を早期に考える。

出典：厚生労働省ホームページ 第117回医師国家試験 D010',
     '{"A": "頸椎捻挫は軟部組織の損傷が主で、大量出血はきたさない。", "C": "肩関節脱臼は整復を要するが、出血性ショックの原因にはならない。", "D": "橈骨遠位端骨折は開放骨折でなければ出血量は限られる。", "E": "膝前十字靱帯損傷は関節血症をきたすが、循環に影響する量ではない。"}'),
    ('117-D-13', '正答は D「速やかなAEDの使用が予後改善に有効である。」。

心臓振盪は、心室の受攻期(T波の上行脚)にあたる瞬間に前胸部へ衝撃が加わり、心室細動が誘発される病態である。ただちに胸骨圧迫を始め、AEDによる除細動を行えれば救命でき、予後を大きく左右する。

出典：厚生労働省ホームページ 第117回医師国家試験 D013',
     '{"A": "胸郭が柔らかく衝撃が心臓に伝わりやすい小児・若年者に多い。", "B": "除細動が遅れれば致死的で、死亡例も多い。", "C": "受傷直後に心室細動が生じるものであり、時間をおいて起こるものではない。", "E": "機序は心室細動であって、迷走神経反射による洞性徐脈ではない。"}'),
    ('117-D-14', '正答は E「母指から環指橈側の感覚障害」。

手根管症候群は横手根靱帯の下で正中神経が絞扼される病態で、母指・示指・中指と環指の橈側半分にしびれと感覚障害をきたす。進行すると母指球筋が萎縮して母指の対立が困難になる。夜間から明け方に悪化するのが特徴である。

出典：厚生労働省ホームページ 第117回医師国家試験 D014',
     '{"A": "頸部痛は頸椎症性神経根症など頸部由来の病変を示唆する。手根管症候群では生じない。", "B": "小指球筋の萎縮は尺骨神経麻痺による。手根管症候群では母指球筋が萎縮する。", "C": "手関節の背屈困難(下垂手)は橈骨神経麻痺による。", "D": "末梢神経の絞扼であり深部腱反射は亢進しない。亢進は中枢性の障害を示す。"}'),
    ('117-D-15', '正答は B「炭酸リチウム」。

炭酸リチウムは有効域が狭く腎から排泄されるため、血中濃度の上昇による中毒と、長期投与による腎性尿崩症や慢性間質性腎炎をきたしやすい。定期的な血中濃度測定と腎機能の監視が要る。

出典：厚生労働省ホームページ 第117回医師国家試験 D015',
     '{"A": "スタチンの主な有害事象は横紋筋融解症と肝障害で、それに伴わない腎障害の頻度は高くない。", "C": "メトホルミンは腎排泄されるため腎機能低下時には減量・中止するが、薬剤自体が腎障害を起こすわけではない。問題となるのは乳酸アシドーシスである。", "D": "カルシウム拮抗薬は腎障害を起こしにくく、腎機能低下例でも使いやすい降圧薬である。", "E": "副腎皮質ステロイドの主な有害事象は易感染性、糖尿病、骨粗鬆症などで、腎障害は主要な問題ではない。"}'),
    ('117-D-16', '正答は D「副腎皮質ステロイド」。

中年女性の急性肝炎様の経過で、肝炎ウイルスマーカーがすべて陰性、IgG 3,131mg/dLと高値、抗核抗体640倍陽性、肝生検で門脈域に形質細胞を含む単核球浸潤を認めており自己免疫性肝炎である。副腎皮質ステロイドが第一選択で、反応も良好なことが多い。

出典：厚生労働省ホームページ 第117回医師国家試験 D016',
     '{"A": "グリチルリチンは肝庇護薬で、炎症を抑える主たる治療にはならない。", "B": "インターフェロンはウイルス性肝炎に用いる。自己免疫性肝炎では病態を悪化させうる。", "C": "核酸アナログ製剤はB型肝炎の治療薬で、HBs抗原陰性の本例には適応がない。", "E": "直接作用型抗ウイルス薬はC型肝炎の治療薬で、HCV-RNA陰性の本例には適応がない。"}'),
    ('117-D-19', '正答は E「アニオンギャップの増加」。

ビグアナイド薬を内服する腎機能低下例(クレアチニン2.0mg/dL)で、多量飲酒を契機に意識障害と血圧低下、呼吸数28/分のKussmaul呼吸をきたしている。血糖128mg/dLと高くないので、乳酸アシドーシスである。乳酸という測定されない陰イオンが増えるためアニオンギャップが開大する。

出典：厚生労働省ホームページ 第117回医師国家試験 D019',
     '{"A": "ビグアナイド薬は単独では低血糖を起こしにくく、血糖128mg/dLは低血糖ではない。", "B": "尿ケトン体陰性であり、ケトン体による呼気のアセトン臭はきたさない。", "C": "頻呼吸による代償が働いておりPaCO2はむしろ低下する。呼吸性アシドーシスではない。", "D": "代謝性アシドーシスであって、アルカローシスではない。"}'),
    ('117-D-20', '正答は E「血管透過性亢進」。

採卵後に両側卵巣が10cmに腫大し、腹水と血液濃縮(Ht51%)、凝固亢進を伴っており卵巣過剰刺激症候群である。血管内皮増殖因子などにより血管透過性が亢進して血漿成分が血管外へ漏出し、腹水貯留と循環血漿量減少が同時に起こる。血栓症を警戒する。

出典：厚生労働省ホームページ 第117回医師国家試験 D020',
     '{"A": "発熱や腹膜刺激徴候はなく、腹部は軟である。腹膜炎を示す所見に乏しい。", "B": "心エコー検査で異常を認めず、頸静脈怒張もない。右心不全は否定的である。", "C": "クレアチニン0.81mg/dLと腎機能は保たれている。", "D": "肝疾患を示す所見はなく、門脈圧亢進を疑わせる脾腫や側副血行路も認めない。"}'),
    ('117-D-22', '正答は D「Romberg徴候が陽性である。」。

胃全摘後10年でMCV114fLの大球性貧血をきたしており、内因子の欠乏によるビタミンB12欠乏症である。脊髄後索が侵されて深部感覚が障害されるため、暗所や閉眼で身体の動揺が強まるRomberg徴候が陽性となる(亜急性連合性脊髄変性症)。

出典：厚生労働省ホームページ 第117回医師国家試験 D022',
     '{"A": "核間性眼筋麻痺は多発性硬化症などでみられる。ビタミンB12欠乏症の典型所見ではない。", "B": "鼻指鼻試験の測定障害は小脳性の運動失調を示す。本症の失調は後索障害による感覚性である。", "C": "上肢Barré徴候は錐体路障害による軽度の片麻痺をみる検査で、頭部MRIに異常のない本例では陽性にならない。", "E": "側索の障害で腱反射が亢進することもあるが、末梢神経障害を合併してアキレス腱反射はむしろ低下・消失することが多い。"}'),
    ('117-D-23', '正答は B「アデノウイルス」。

発熱、咽頭炎、結膜炎の3つがそろう咽頭結膜熱(プール熱)で、原因はアデノウイルスである。夏に流行し、迅速抗原検査で診断できる。学校保健安全法では主要症状が消退して2日を経過するまで出席停止となる。

出典：厚生労働省ホームページ 第117回医師国家試験 D023',
     '{"A": "麻疹では頰粘膜にKoplik斑が出現し、その後に全身の発疹をみる。白斑も皮疹も認めない。", "C": "パルボウイルスB19による伝染性紅斑では頰の紅斑が特徴だが、皮疹を認めない。", "D": "コクサッキーウイルスによるヘルパンギーナや手足口病では口腔内に水疱を認めるが、水疱はない。", "E": "単純ヘルペスウイルスによる歯肉口内炎では歯肉腫脹と口腔内の水疱・潰瘍をみるが、いずれも認めない。"}'),
    ('117-D-24', '正答は E「von Willebrand病」。

乳児期からの鼻出血と皮下出血に、出血時間の延長とAPTTの延長が併存し、血小板数と血小板凝集能は正常で、父親にも出血傾向がある。von Willebrand因子の異常により血小板粘着障害と第VIII因子の減少が同時に起こるvon Willebrand病である。常染色体顕性遺伝が多い。

出典：厚生労働省ホームページ 第117回医師国家試験 D024',
     '{"A": "血友病AはX連鎖潜性遺伝で男児に発症し、APTTは延長するが出血時間は正常で、関節内出血が主となる。父から息子へは遺伝しない。", "B": "単純性紫斑は若い女性の下肢にみられる軽微な紫斑で、凝固検査に異常はない。", "C": "血小板無力症ではADPによる血小板凝集能が欠如する。凝集能は正常である。", "D": "ビタミンK欠乏症ではプロトロンビン時間が延長する。PT-INR1.0と正常である。"}'),
    ('117-D-26', '正答は E「抗アルドステロン薬」。

慢性腎臓病の患者に抗アルドステロン薬が投与され、K6.5mEq/Lの高カリウム血症をきたしている。抗アルドステロン薬は集合管でのカリウム排泄を抑えるため、腎機能低下例では高カリウム血症の最大の原因になる。ただちに中止し、心電図を確認して治療する。

出典：厚生労働省ホームページ 第117回医師国家試験 D026',
     '{"A": "スルホニル尿素薬の問題は低血糖で、血清カリウムは上げない。", "B": "DPP-4阻害薬はカリウムに影響しない。", "C": "SGLT2阻害薬は尿糖排泄を促し、脱水には注意を要するが高カリウム血症の原因にはならない。", "D": "カルシウム拮抗薬は血清カリウムに影響しない。"}'),
    ('117-D-28', '正答は D「ビタミンB12」。

新生児期に広範な小腸切除を受け、回腸末端が失われている。ビタミンB12は内因子と結合して回腸末端で吸収されるため、体内の貯蔵が尽きる数年後に欠乏し、MCV111fLの大球性貧血をきたす。経口では補えないので非経口的に投与する。

出典：厚生労働省ホームページ 第117回医師国家試験 D028',
     '{"A": "ビタミンA欠乏では夜盲や眼球乾燥をきたすが、貧血の原因にはならない。", "B": "ビタミンC欠乏(壊血病)では出血傾向と歯肉出血をきたす。出血時間は正常で紫斑もない。", "C": "ビタミンB1欠乏では脚気や Wernicke脳症をきたす。大球性貧血は説明できない。", "E": "ビタミンK欠乏ではプロトロンビン時間が延長する。PT-INR1.0と正常である。"}'),
    ('117-D-35', '正答は B「Tourette症候群」。

幼児期に始まった多彩な運動チックと音声チックが1年以上続いており、Tourette症候群である。単純チックから複雑チックへ広がり、汚言症を伴うこともある。多くは年齢とともに軽快するが、生活への支障が大きければ薬物療法を検討する。

出典：厚生労働省ホームページ 第117回医師国家試験 D035',
     '{"A": "分離不安症は愛着対象から離れることへの過度の不安が主症状で、チックは伴わない。", "C": "自閉スペクトラム症は社会的コミュニケーションの障害と限定的な興味・常同行動が幼児期から続く。音声チックや汚言症は中核症状ではない。", "D": "吃音症は語の反復や引き伸ばしなど発話の流暢性の障害で、運動チックを伴わない。", "E": "注意欠陥多動障害は不注意・多動・衝動性が中心で、チックを合併することはあるが本例の中核ではない。"}'),
    ('117-D-37', '正答は D「血清K値」。

糖尿病性ケトアシドーシスである。インスリンを投与するとカリウムが細胞内へ移動するため、初期には正常〜高値であった血清カリウムが治療開始後数時間で急速に低下する。心電図監視のもとでカリウムを補充しながら治療する。

出典：厚生労働省ホームページ 第117回医師国家試験 D037',
     '{"A": "生理食塩液で循環血漿量が回復するため、血圧はむしろ上昇する。", "B": "HbA1cは過去1〜2か月の平均血糖を反映するので、数時間では変化しない。", "C": "高血糖による偽性低ナトリウム血症が是正され、血清ナトリウムはむしろ上昇する。", "E": "生理食塩液には塩素が多く含まれるため、血清塩素はむしろ上昇する。"}'),
    ('117-D-39', '正答は C「薬剤リンパ球刺激試験」。

サプリメント摂取後に生じた肝障害で、ウイルス性・自己免疫性のマーカーがすべて陰性、末梢血の好酸球が12%と増加している。薬物性肝障害を疑う状況であり、原因物質に対するリンパ球の反応をみる薬剤リンパ球刺激試験が診断の一助となる。

出典：厚生労働省ホームページ 第117回医師国家試験 D039',
     '{"A": "ICG試験は肝の予備能をみる検査で、原因の特定には役立たない。", "B": "尿素呼気試験はHelicobacter pylori感染の診断に用いる。", "D": "α1-アンチトリプシン法は蛋白漏出性胃腸症で消化管への蛋白漏出をみる検査である。", "E": "75gOGTTは耐糖能の評価に用いる。血糖96mg/dLで糖代謝の問題はない。"}'),
    ('117-D-40', '正答は D「「アドレナリン自己注射製剤を携帯しましょう」」。

小麦の摂取と運動が重なったときだけ症状が出る食物依存性運動誘発アナフィラキシーである。原因食物を食べた後4時間程度は運動を避けるのが基本で、それでも発症しうるため、アドレナリン自己注射製剤を携帯し、学校とも対応を共有しておく。

出典：厚生労働省ホームページ 第117回医師国家試験 D040',
     '{"A": "小麦を食べていなければ運動できるので、運動そのものを禁じる必要はない。", "B": "完全除去まではせず、運動の前に摂らないという形で管理する。成長期の子どもに不要な除去は望ましくない。", "C": "抗ヒスタミン薬の予防内服でアナフィラキシーは防げない。", "E": "β2刺激薬は気管支収縮を緩めるだけで、循環虚脱を伴うアナフィラキシーには対応できない。"}'),
    ('117-D-41', '正答は C「フェリチン」。

夕方に上がるスパイク状の弛張熱、解熱とともに消えるサーモンピンクの紅斑、関節炎、リンパ節腫脹、著明な白血球増多と好中球優位、リウマトイド因子と抗核抗体陰性がそろっており成人Still病である。血清フェリチンの著増が診断を支持する。

出典：厚生労働省ホームページ 第117回医師国家試験 D041',
     '{"A": "第XIII因子は凝固の最終段階でフィブリンを架橋する因子で、欠乏すると創傷治癒の遅延や遅発性の出血をきたす。本症の評価には用いない。", "B": "HLA-B51はBehçet病との関連が知られる。口腔内アフタや陰部潰瘍は認めない。", "D": "ハプトグロビンは溶血性貧血で低下する指標で、貧血のない本例では意味をなさない。", "E": "血清アミロイドAは炎症の指標にすぎず、成人Still病に特徴的ではない。"}'),
    ('117-D-42', '正答は A「座位訓練」。

発症5日目で神経徴候が悪化せず、背もたれを90度にしても血圧が下がらないことを確認できている。全身状態が安定した時点で座位を保つ訓練から始め、廃用症候群を防ぎつつ段階的に離床を進める。

出典：厚生労働省ホームページ 第117回医師国家試験 D042',
     '{"B": "右上下肢が麻痺側であり、この時期に麻痺側手指での書字は行えない。", "C": "他動可動域訓練が要るのは麻痺側の右上肢である。左上下肢の筋力は5で正常である。", "D": "右下肢は股関節屈曲1、膝伸展0、足関節背屈0で、歩行器を用いても歩行訓練は行えない。", "E": "階段昇降は座位・立位の安定を確認したのちの段階で、現時点では時期尚早である。"}'),
    ('117-D-43', '正答は E「副腎皮質ステロイド薬の投与」。

貧血に間接ビリルビン優位の黄疸、網赤血球増加、LD上昇、ハプトグロビン著減がそろい、直接Coombs試験が陽性であることから自己免疫性溶血性貧血である。温式では副腎皮質ステロイドが第一選択で、多くが反応する。

出典：厚生労働省ホームページ 第117回医師国家試験 D043',
     '{"A": "脾摘はステロイドが無効または減量できない場合の二次的な選択肢である。", "B": "造血幹細胞移植は本症の初期治療にはならない。", "C": "抗C5抗体(エクリズマブ)は発作性夜間ヘモグロビン尿症に用いる。直接Coombs試験は陰性となる。", "D": "抗CD20抗体(リツキシマブ)はステロイド抵抗例に用いる二次治療である。"}'),
    ('117-D-49', '正答は A「血糖測定」。

母体の妊娠糖尿病により胎児が高インスリン血症となり、出生後に糖の供給が絶たれて低血糖に陥る。体重4,100gの巨大児であることもそれを裏づける。無症候のこともあるので、ただちに血糖を測定して補正する。

出典：厚生労働省ホームページ 第117回医師国家試験 D049',
     '{"B": "糖尿病母体児では肥大型心筋症の合併もありうるが、心音に異常がなく呼吸循環も安定しており緊急性がない。", "C": "頭部超音波検査は頭蓋内出血を疑うときに行うもので、神経学的異常を認めない本例では優先度が低い。", "D": "生後1時間で黄疸は問題にならない。ビリルビンの評価は日齢が進んでからである。", "E": "呼吸数50/分、SpO2 98%、呼吸音も正常で、呼吸障害を示す所見がない。"}'),
    ('117-D-54', '正答は D「「子宮頸部細胞診を半年後に行いましょう」」。

軽度異形成(CIN1)の多くは自然に消退するため、ただちに治療せず細胞診による経過観察を行う。6か月ごとの細胞診とコルポスコピィで、高度化しないかを確かめていく。

出典：厚生労働省ホームページ 第117回医師国家試験 D054',
     '{"A": "MRIは浸潤癌の進行度診断に用いるもので、上皮内にとどまる病変には不要である。", "B": "円錐切除術は高度異形成(CIN3)や上皮内癌、微小浸潤癌が適応で、CIN1には過剰な治療である。早産の危険も高まる。", "C": "HPV感染そのものに有効な抗ウイルス薬はない。", "E": "HPVワクチンは感染の予防のためのもので、すでに生じた病変を治療する効果はない。"}'),
    ('117-D-58', '正答は A「KL-6低下」。

夏季に繰り返し、入院して原因環境から離れると治療なしに軽快する経過と、両側のfine cracklesおよび小葉中心性陰影から夏型過敏性肺炎である。間質の障害を反映してKL-6はむしろ上昇するので、低下という記載が誤りである。

出典：厚生労働省ホームページ 第117回医師国家試験 D058',
     '{"B": "間質性肺疾患では肺が硬くなり、肺活量が低下する拘束性換気機能障害を示す。", "C": "ツベルクリン反応の陰転化はサルコイドーシスなど細胞性免疫の変化を反映する所見で、過敏性肺炎でもみられうる。", "D": "夏型過敏性肺炎の原因抗原はTrichosporon asahiiで、その抗体が陽性となる。", "E": "気管支肺胞洗浄液ではリンパ球が増加し、CD8陽性細胞が優位となってCD4/CD8比が低下する。"}'),
    ('117-D-60', '正答は D「4」。

子宮体部の癌肉腫は骨盤への放射線照射から10年以上を経て発生する二次発癌として知られる。45歳時の根治的放射線治療が最も関連が深い。

出典：厚生労働省ホームページ 第117回医師国家試験 D060',
     '{"A": "胞状奇胎は絨毛性疾患で、続発するのは侵入奇胎や絨毛癌である。子宮体部の癌肉腫とは結びつかない。", "B": "HPV感染は子宮頸部の扁平上皮癌の原因で、子宮体部の癌肉腫の原因にはならない。", "C": "抗癌薬も二次発癌の原因になりうるが、この部位・組織型では放射線の関与のほうが強い。", "E": "ビスホスホネート製剤の代表的な有害事象は顎骨壊死と非定型大腿骨骨折で、発癌との関連はない。"}'),
    ('117-D-64', '正答は D「関節液培養」。

人工股関節置換術から7年を経て、発熱、局所の腫脹・熱感・発赤、白血球増多とCRP上昇、インプラントのゆるみを認めており人工関節感染を疑う。起因菌と感受性を確かめるため、抗菌薬を始める前に関節液を穿刺して培養に出す。

出典：厚生労働省ホームページ 第117回医師国家試験 D064',
     '{"A": "感染が疑われる関節への副腎皮質ステロイド注入は感染を悪化させるため禁忌である。", "B": "牽引は感染の診断にも治療にもならない。", "C": "可動域訓練は感染の制御がついてから考えるもので、この時点で優先されない。", "E": "ギプス固定では感染巣は治らず、原因の究明にもならない。"}'),
    ('117-D-66', '正答は D「鉄キレート剤の投与」。

4年にわたる頻回の赤血球輸血でフェリチン2,500ng/mL、血清鉄250μg/dL、皮膚の色素沈着、肝のCT値上昇を認め、輸血後鉄過剰症である。鉄キレート剤を投与して臓器への鉄沈着を減らす。

出典：厚生労働省ホームページ 第117回医師国家試験 D066',
     '{"A": "Hb5.8g/dLの高度貧血があり、瀉血は行えない。瀉血が選べるのはヘモクロマトーシスで貧血のない場合である。", "B": "肝機能は保たれており、肝移植の適応ではない。", "C": "75歳で高度の血球減少があり、造血幹細胞移植の適応にならない。", "E": "再生不良性貧血は造血幹細胞そのものの減少によるため、エリスロポエチン製剤は無効である。"}'),
    ('117-D-67', '正答は D「高二酸化炭素血症」。

RSウイルスによる細気管支炎である。細気管支の狭窄で呼気が妨げられ、換気が保てなくなると二酸化炭素が貯留する。陥没呼吸とチアノーゼを認め呼吸数60/分と努力呼吸が続いており、呼吸不全への進行を高二酸化炭素血症で捉える。

出典：厚生労働省ホームページ 第117回医師国家試験 D067',
     '{"A": "血小板数の減少はきたさない。", "B": "初回の細気管支炎でIgEが高値になるとは限らない。喘息の発症と関連づけられることはあるが検査所見としては予測できない。", "C": "ウイルス感染であり、好中球の核左方移動は起こりにくい。", "E": "細気管支の閉塞による過膨脹が主で、肺浸潤影ではなく肺野の透過性亢進を示すことが多い。"}'),
    ('117-D-68', '正答は E「ニューキノロン系抗菌薬が第一選択薬である。」。

膿性の尿道分泌物にGram陰性双球菌を認め淋菌性尿道炎である。淋菌はニューキノロン系への耐性率が高く第一選択にならない。第一選択はセフトリアキソンの単回静注である。

出典：厚生労働省ホームページ 第117回医師国家試験 D068',
     '{"A": "オーラルセックスにより淋菌性咽頭炎を生じる。無症状のことが多く、感染源となる。", "B": "クラミジアとの混合感染が20〜30%にみられるため、同時に治療することが多い。", "C": "核酸増幅検査(PCR)は感度が高く、咽頭や尿検体でも診断に有用である。", "D": "女性では上行感染により骨盤内炎症性疾患を起こし、不妊や子宮外妊娠の原因となる。"}'),
    ('117-E-1', '正答は E「ランダム化比較試験〈RCT〉」。

介入研究は研究者が曝露(治療や予防手段)を割り付けて、その結果を比較する研究である。ランダム化比較試験は割り付けを無作為に行うことで交絡を制御でき、因果関係を示す証拠として最も強い。

出典：厚生労働省ホームページ 第117回医師国家試験 E001',
     '{"A": "横断研究はある一時点の曝露と疾病を同時に調べる観察研究である。", "B": "コホート研究は曝露の有無で群を分けて追跡する観察研究で、割り付けは行わない。", "C": "症例対照研究は疾病のある群とない群で過去の曝露をさかのぼって比べる観察研究である。", "D": "ケースシリーズ研究は症例の記述にとどまり、比較対照を置かない。"}'),
    ('117-E-3', '正答は E「Douglas窩の圧痛」。

骨盤内炎症性疾患では炎症が骨盤腹膜に及ぶため、内診でDouglas窩に圧痛を認める。子宮頸部を動かすと痛む頸管可動痛や付属器の圧痛とともに、診断の中心となる所見である。

出典：厚生労働省ホームページ 第117回医師国家試験 E003',
     '{"A": "帯下の悪臭は細菌性腟症などでもみられ、骨盤内への波及を示す所見ではない。", "B": "脾臓の触知は血液疾患や門脈圧亢進症を示唆し、骨盤内の炎症とは関係しない。", "C": "子宮口の開大は流産や切迫早産、分娩の進行を示す所見である。", "D": "下腹部腫瘤の触知は子宮筋腫や卵巣腫瘍でもみられ、炎症に特異的ではない。"}'),
    ('117-E-4', '正答は C「装着はどの部位に付けても構わない。」。

トリアージタッグは原則として右手首に装着する。負傷などで装着できない場合は左手首、右足首、左足首、頸部の順とする。装着部位を決めておくのは、混乱した現場で誰もが確実に見つけられるようにするためである。

出典：厚生労働省ホームページ 第117回医師国家試験 E004',
     '{"A": "氏名や傷病の内容、トリアージ区分を記載して傷病者を識別するために用いる。", "B": "様式は総務省消防庁により全国で統一されている。", "D": "多数傷病者が同時に発生し、治療の優先順位づけが必要な状況で用いる。", "E": "死亡または救命が困難な場合は0(黒)を残すように切り取る。"}'),
    ('117-E-5', '正答は C「Horner症候群 — 散瞳」。

Horner症候群は交感神経の遠心路が障害される病態で、縮瞳、眼瞼下垂、患側顔面の発汗低下を三徴とする。散瞳ではなく縮瞳をきたす点が誤りである。

出典：厚生労働省ホームページ 第117回医師国家試験 E005',
     '{"A": "急性緑内障発作では中等度に散瞳したまま対光反応が鈍くなる。正しい組合せである。", "B": "交感神経作動薬は瞳孔散大筋を収縮させて散瞳させる。正しい組合せである。", "D": "動眼神経麻痺では副交感神経成分が障害されて散瞳し、眼瞼下垂と外斜視を伴う。正しい組合せである。", "E": "有機リン中毒ではアセチルコリンの蓄積によりムスカリン様作用が強まり縮瞳する。正しい組合せである。"}'),
    ('117-E-8', '正答は A「後天性血友病A」。

後天性血友病Aは第VIII因子に対する自己抗体(インヒビター)が生じる病態で、高齢者に突然の出血傾向として現れる。広範な皮下出血や筋肉内出血をきたし、APTTが延長するがPTは正常である。

出典：厚生労働省ホームページ 第117回医師国家試験 E008',
     '{"B": "本態性血小板血症は血小板が増加する疾患で、血栓症が主体である。", "C": "抗リン脂質抗体症候群も動静脈血栓症をきたす病態で、出血ではない。", "D": "免疫性血小板減少性紫斑病は血小板の減少により点状出血や紫斑、粘膜出血をきたす。深部の筋肉内出血は典型的でない。", "E": "IgA血管炎は下肢に触知可能な紫斑をきたす小血管炎で、凝固能は正常である。"}'),
    ('117-E-9', '正答は D「橈骨神経損傷」。

三角筋への筋肉注射は肩峰から2〜3横指下の三角筋中央部に行う。遠位側にずれると、上腕骨の橈骨神経溝を走る橈骨神経を損傷して下垂手をきたす危険がある。

出典：厚生労働省ホームページ 第117回医師国家試験 E009',
     '{"A": "肩関節障害は逆に近位側、肩峰に近すぎる部位に打った場合に問題となる。", "B": "肩腱板も肩峰の直下にあり、近位側にずれたときに損傷しうる。", "C": "血栓性静脈炎は静脈内への薬剤投与に伴う合併症である。", "E": "上腕動脈は上腕の内側を走り、三角筋の刺入部位からは離れている。"}'),
    ('117-E-10', '正答は A「歯周病」。

歯周病は歯垢中の細菌による慢性炎症で、適切な歯磨きと禁煙、定期的な歯科受診によって発症を防げる。糖尿病との相互関係も知られ、生活習慣病の一つに位置づけられている。

出典：厚生労働省ホームページ 第117回医師国家試験 E010',
     '{"B": "1型糖尿病は膵β細胞が自己免疫機序で破壊されて起こり、生活習慣とは関係しない。", "C": "悪性リンパ腫の発症は生活習慣の改善では防げない。", "D": "急性骨髄性白血病は造血幹細胞の遺伝子異常によるもので、生活習慣による予防はできない。", "E": "原発性アルドステロン症は副腎の腺腫や過形成によるもので、生活習慣とは関係しない。"}'),
    ('117-E-11', '正答は C「準備期 — 行動計画の作成」。

準備期は1か月以内に行動を変えようと思っており、すでに準備を始めている段階である。いつ・何を・どれだけ行うかという具体的な行動計画を一緒に作ることが有効な働きかけになる。

出典：厚生労働省ホームページ 第117回医師国家試験 E011',
     '{"A": "無関心期はまだ変える気がない段階で、目標を設定させても実行につながらない。まずは情報提供で気づきを促す。", "B": "関心期は関心はあるが行動に移せない段階で、変えることの利点と負担を整理して動機づけを高める。", "D": "実行期は始めて6か月未満の段階で、続けられるように支援と称賛を行う。罰則は逆効果である。", "E": "維持期でも逆戻りは起こりうるため、支援を打ち切るのではなく継続を後押しする。"}'),
    ('117-E-12', '正答は C「皮膚に対して直角に穿刺する。」。

大腿動脈は体表から深い位置にあるため、拍動を触知した真上から皮膚に対して直角に穿刺する。鼠径靱帯の下で、外側から大腿神経・動脈・静脈の順に並ぶ位置関係を確かめて行う。

出典：厚生労働省ホームページ 第117回医師国家試験 E012',
     '{"A": "18Gは太すぎる。動脈血ガス分析には23G前後の細い針を用いる。", "B": "動脈は皮下深くを走り目視できない。指で拍動を触れて位置を確かめる。", "D": "動脈圧で自然に血液が流入するので、強い陰圧は不要である。陰圧をかけると気泡が混入して測定値が狂う。", "E": "揉むと出血や血腫を招く。5分以上しっかり圧迫止血する。"}'),
    ('117-E-13', '正答は C「強直性脊椎炎 — 安静により改善する腰背部痛」。

強直性脊椎炎の腰背部痛は炎症性腰痛で、安静や睡眠中にむしろ悪化し、明け方に強く、体を動かすと軽快する。安静により改善するのは椎間板ヘルニアなど機械的腰痛の特徴で、組合せとして誤っている。

出典：厚生労働省ホームページ 第117回医師国家試験 E013',
     '{"A": "関節リウマチは中足趾節関節や中手指節関節など小関節の滑膜炎をきたす。正しい組合せである。", "B": "乾癬性関節炎は遠位指節間関節を侵し、爪の変化を伴うことが多い。正しい組合せである。", "D": "Sjögren症候群では唾液分泌の低下により口腔乾燥をきたし、舌乳頭が萎縮して平滑舌となる。正しい組合せである。", "E": "皮膚筋炎では体幹に近い筋が侵され、頸部では屈筋が優位に低下して頭を持ち上げにくくなる。正しい組合せである。"}'),
    ('117-E-14', '正答は E「McBurney圧痛点は臍と右前上腸骨棘を結ぶ線上外側1/3にある。」。

McBurney点は臍と右上前腸骨棘を結ぶ線を3等分した外側3分の1の点で、急性虫垂炎で圧痛が強くなる部位である。Lanz点(左右の上前腸骨棘を結ぶ線の右3分の1)とともに押さえておく。

出典：厚生労働省ホームページ 第117回医師国家試験 E014',
     '{"A": "膵は後腹膜の深部にあり、健常者では触知できない。", "B": "健常者では腎はふつう触れない。やせた人で右腎の下極が触れることがある程度である。", "C": "反跳痛は手を離したときに強く痛むもので、腹膜刺激徴候である。加圧時より除圧時の痛みが強い。", "D": "Murphy徴候は右季肋部を圧迫しながら息を吸わせたときに痛みで吸気が止まるかをみる。吐かせるのではない。"}'),
    ('117-E-15', '正答は E「聴診 → 打診 → 触診」。

腹部診察は視診のあと聴診、打診、触診の順に行う。触診や打診を先に行うと腸管が刺激されて腸蠕動音が変化し、本来の音を評価できなくなるためである。

出典：厚生労働省ホームページ 第117回医師国家試験 E015',
     '{"A": "触診を最初に行うと腸蠕動音が変わってしまう。", "B": "同じく触診が先になっており、聴診の所見が変わってしまう。", "C": "打診も腹壁への刺激となるため、聴診より先に行わない。", "D": "打診と触診が聴診より先になっている。"}'),
    ('117-E-16', '正答は C「データの収集・解析方法の計画」。

倫理審査委員会は研究計画書の妥当性を審査するので、目的、対象、方法、データの収集と解析の計画は審査を受ける前に固めておく必要がある。統計解析の計画が不十分な研究は被験者に負担をかけるだけで成果が出ないため、倫理的に問題があるとされる。

出典：厚生労働省ホームページ 第117回医師国家試験 E016',
     '{"A": "同意の取得は承認された説明文書と手順に沿って行うもので、審査前に行ってはならない。", "B": "被験者の組入れも審査の承認後に始める。", "D": "謝金の額と支払い方法も審査の対象で、承認前に支払うことはできない。", "E": "治験薬の投与という介入そのものを承認前に行うことは許されない。"}'),
    ('117-E-17', '正答は E「クエン酸ナトリウム」。

クエン酸ナトリウムはカルシウムをキレートして凝固を止め、測定時にカルシウムを加えれば反応を再開できるため、プロトロンビン時間やAPTTなどの凝固検査に用いる。血液9に対し抗凝固剤1の比を守ることが重要である。

出典：厚生労働省ホームページ 第117回医師国家試験 E017',
     '{"A": "EDTAもカルシウムをキレートするが結合が強固で凝固反応を再開できない。血算に用いる。", "B": "ヘパリンはアンチトロンビンを介してトロンビンを阻害し、凝固検査の値を乱す。", "C": "ワルファリンは経口の抗凝固薬で、採血管の抗凝固剤としては用いない。", "D": "フッ化ナトリウムは解糖を止めるための添加物で、血糖測定用の採血管に用いる。"}'),
    ('117-E-18', '正答は C「自己注射が認められている。」。

アナフィラキシーの既往がある患者にはアドレナリン自己注射製剤の処方が認められており、患者本人や家族、学校の教職員などが大腿前外側に筋肉内注射できる。早期の投与が予後を左右する。

出典：厚生労働省ホームページ 第117回医師国家試験 E018',
     '{"A": "皮下では吸収が遅い。大腿前外側への筋肉内注射が推奨される。", "B": "妊婦でもアナフィラキシーでは母体の救命が優先され、投与する。", "D": "アナフィラキシーは生命に関わるため、不整脈があっても投与をためらわない。", "E": "ショックに至る前、呼吸器や循環器の症状が現れた時点で投与する。遅れるほど予後が悪い。"}'),
    ('117-E-20', '正答は E「精巣腫瘍」。

精巣腫瘍は無痛性の陰囊内腫瘤として気づかれるもので、尿路と交通しないため肉眼的血尿では発症しない。腫瘍マーカーのAFPとhCGが診断と経過観察に有用である。

出典：厚生労働省ホームページ 第117回医師国家試験 E020',
     '{"A": "腎癌では血尿、腹部腫瘤、疼痛が古典的三徴とされ、無症候性の肉眼的血尿で見つかることがある。", "B": "腎盂癌は尿路上皮癌で、無症候性肉眼的血尿が典型的な初発症状である。", "C": "膀胱癌も無症候性肉眼的血尿が最も多い初発症状である。", "D": "前立腺癌は排尿症状や検診のPSA高値で見つかることが多いが、進行例では肉眼的血尿をきたす。"}'),
    ('117-E-21', '正答は E「疾病や治療についての患者の理解を確認する。」。

アドヒアランスは患者が治療方針の決定に参加し、納得して実行することを指す。病気と治療の意義を患者がどう理解しているかを確かめ、必要に応じて説明し直すことが向上につながる。

出典：厚生労働省ホームページ 第117回医師国家試験 E021',
     '{"A": "処方日数を延ばすだけでは服薬の実行は改善せず、残薬の把握もしにくくなる。", "B": "叱責すると患者は飲み忘れを申告しなくなり、実態がつかめなくなる。", "C": "副作用を説明しないと、症状が出たときに自己判断で中断してしまう。", "D": "内服回数はできるだけ少なくまとめるほうが続けやすい。"}'),
    ('117-E-23', '正答は B「インフルエンザ」。

1918〜1919年に世界的に流行したスペインインフルエンザは、第一次世界大戦の末期と重なって数千万人の死者を出した。A(H1N1)型による最初のインフルエンザパンデミックとされる。

出典：厚生労働省ホームページ 第117回医師国家試験 E023',
     '{"A": "エボラ出血熱は1976年に初めて確認され、流行は主にアフリカに限られる。", "C": "鳥インフルエンザ(H5N1)のヒトへの感染が問題となったのは1997年以降である。", "D": "中東呼吸器症候群は2012年に初めて報告された。", "E": "後天性ヒト免疫不全症候群が報告されたのは1981年である。"}'),
    ('117-E-24', '正答は D「患者が嘔吐している場合は撥水性ガウンを着用して診察する。」。

標準予防策では、血液・体液・分泌物・排泄物・傷のある皮膚・粘膜はすべて感染性があるものとして扱う。飛散する恐れがあれば、手袋に加えて撥水性ガウンやマスク、ゴーグルなど個人防護具を選んで用いる。

出典：厚生労働省ホームページ 第117回医師国家試験 E024',
     '{"A": "日常の診療では清潔(非滅菌)手袋で足りる。滅菌手袋は無菌操作を要する場面で用いる。", "B": "診断の有無にかかわらず、すべての患者に対して常に行うのが標準予防策である。", "C": "手指衛生は石けんと流水による手洗いかアルコール製剤で行う。次亜塩素酸ナトリウムは皮膚に用いない。", "E": "唾液が付着した舌圧子は感染性廃棄物として処理する。"}'),
    ('117-E-25', '正答は C「両上肢の随意把持努力により減弱する。」。

両上肢を組んで引っ張らせるJendrassik手技は、反射弓の緊張を高めて腱反射を出やすくする方法である。減弱させるのではなく増強させるので、この記述が誤っている。

出典：厚生労働省ホームページ 第117回医師国家試験 E025',
     '{"A": "反射弓の求心路・遠心路が障害されるため、末梢神経障害では腱反射が低下する。", "B": "力が入っていると反射が出にくいので、力を抜くよう促す。", "D": "膝蓋腱を叩くと大腿四頭筋が収縮し、下腿が前方に振り上がる。", "E": "ハンマーは柄の適切な位置を軽く持ち、手首のスナップを使って叩く。"}'),
    ('117-E-27', '正答は D「ジアゼパムの静脈内投与」。

坐薬のジアゼパムでけいれんが止まらず30分以上持続しており、けいれん重積状態である。静脈路が確保できたので、まずジアゼパムを静脈内投与する。効果がなければ第二選択薬に進む。

出典：厚生労働省ホームページ 第117回医師国家試験 E027',
     '{"A": "30分以上続くけいれんを経過観察してよい状況ではない。", "B": "解熱薬に抗けいれん作用はなく、熱性けいれんの再発予防にもならない。", "C": "経鼻胃管はけいれんを止める手段ではない。", "E": "酸素投与でSpO2 98%まで改善しており、呼吸は保たれている。挿管はまず薬物で止めることを試みてからである。"}'),
    ('117-E-28', '正答は D「医師の承諾」。

臓器の移植に関する法律では、本人の書面による提供意思がある場合と、本人の意思が不明で家族が承諾する場合に提供できる。医師の承諾は根拠にならない。

出典：厚生労働省ホームページ 第117回医師国家試験 E028',
     '{"A": "個人番号カードの裏面には臓器提供の意思表示欄があり、書面による意思表示として有効である。", "B": "運転免許証の意思表示欄も有効である。", "C": "健康保険証の意思表示欄も有効である。", "E": "本人の意思が不明でも、家族が書面で承諾すれば提供できる。"}'),
    ('117-E-29', '正答は D「オピオイドの経口投与」。

NSAIDで抑えきれない癌性疼痛には、段階を踏まずにオピオイドを導入してよい。経口摂取が可能なので、まず経口のオピオイドから始めて効果と有害事象をみながら調節する。

出典：厚生労働省ホームページ 第117回医師国家試験 E029',
     '{"A": "NSAIDには天井効果があり、増量しても鎮痛は頭打ちで、腎障害や消化管出血の危険が増すだけである。", "B": "持続硬膜外麻酔は全身投与で制御できない場合に検討する侵襲的な手段である。", "C": "放射線照射は骨転移痛などに有用だが、効果が出るまで時間がかかり、まず行うものではない。", "E": "副腎皮質ステロイドは補助薬として併用するもので、単独で第一に用いる鎮痛手段ではない。"}'),
    ('117-E-30', '正答は A「頸管縫縮術」。

妊娠中期に自覚症状の乏しいまま胎胞が膨隆して流産することを繰り返しており、頸管無力症である。次の妊娠では妊娠12〜14週ごろに予防的な頸管縫縮術を行う。

出典：厚生労働省ホームページ 第117回医師国家試験 E030',
     '{"B": "NSAIDは子宮収縮を抑える目的で用いられることがあるが、頸管無力症の治療にはならず、胎児の動脈管早期閉鎖の危険がある。", "C": "β2刺激薬は子宮収縮抑制薬で、収縮を伴わない頸管無力症には無効である。", "D": "マグネシウム製剤も子宮収縮抑制薬であり、同様に適応でない。", "E": "副腎皮質ステロイドは早産が避けられない場合に胎児の肺成熟を促す目的で用いるもので、この時期の対応ではない。"}'),
    ('117-E-32', '正答は C「心肺蘇生法」。

気道異物による窒息から心停止に至っている。頸動脈を触知しないので、ただちに胸骨圧迫を含む心肺蘇生を始める。胸骨圧迫は胸腔内圧を高めて異物を押し出す効果も期待できる。

出典：厚生労働省ホームページ 第117回医師国家試験 E032',
     '{"A": "開胸手術は気道異物の処置ではない。", "B": "静脈路確保より胸骨圧迫が優先される。", "D": "背部叩打法は意識がある間に行う手技で、意識を失った時点で心肺蘇生に切り替える。", "E": "気管支鏡下摘出術は循環を立て直したうえで行うもので、心停止の場では第一の処置にならない。"}'),
    ('117-E-33', '正答は E「5」。

ロコモティブシンドロームでは運動器の衰えから移動能力が落ちる。外出を控えれば活動量がさらに減り、廃用が進んで悪循環に陥る。外出の禁止は誤りで、安全に外出を続けられるように支援するのが適切である。

出典：厚生労働省ホームページ 第117回医師国家試験 E033',
     '{"A": "下肢を中心とした筋力訓練とバランス訓練が中核の対応である。", "B": "身長155cm・体重38kgと低体重で低栄養が疑われ、蛋白質を中心とした栄養指導が必要である。", "C": "ふさぎ込みがちで抑うつが疑われ、こころの健康への配慮は適切である。", "D": "転倒は骨折から要介護に直結するため、住環境の整備を含む転倒予防の指導は重要である。"}'),
    ('117-E-35', '正答は A「訪問看護」。

自分で行えていたストマの管理が入院を機に難しくなっている。ストマ装具の交換や皮膚のトラブルへの対応は医療的な処置なので、介護保険の訪問看護を導入して支援する。

出典：厚生労働省ホームページ 第117回医師国家試験 E035',
     '{"B": "外来通院が予定されており通院できる状態なので、医師が自宅に出向く訪問診療の適応ではない。", "C": "入浴は自立しており、訪問入浴介護は要さない。", "D": "認知機能に問題がなく服薬管理もできているので、訪問薬剤管理指導は要さない。", "E": "妻と同居しており在宅生活が続けられる。認知症対応型のグループホーム入所の対象でもない。"}'),
    ('117-E-36', '正答は D「母乳量は十分であると伝える。」。

出生体重3,000gから日齢28で3,600gとなっており、退院時の2,800gから約33g/日の増加で標準的である。排尿10回、排便3回と十分で、母乳量は足りていると判断できる。母親の不安に対しては、根拠を示して安心させることが最も適切な対応になる。

出典：厚生労働省ホームページ 第117回医師国家試験 E036',
     '{"A": "体重増加は良好で、人工乳に変える理由がない。", "B": "現在の授乳回数で足りており、増やす必要はない。", "C": "母乳添加用粉末は極低出生体重児などに用いるもので、正期産で順調に育っている児には要さない。", "E": "混合栄養に変える必要はなく、母乳のみで足りている。"}'),
    ('117-E-37', '正答は C「抗菌薬を投与する。」。

ネコ咬傷はPasteurella multocidaなどによる感染を起こしやすく、深く狭い創で嫌気的な環境ができるため急速に進行する。すでに発赤と腫脹があり、アモキシシリン・クラブラン酸などの抗菌薬を投与する。

出典：厚生労働省ホームページ 第117回医師国家試験 E037',
     '{"A": "急性炎症の時期に温めると腫脹と疼痛が悪化する。", "B": "動物咬傷は感染の危険が高く、原則として一次縫合せず開放創のままとする。", "D": "駆血は血流を妨げて組織を傷害するだけで、感染の管理にならない。", "E": "起因菌は創部から採取して調べる。動物の口腔内を培養しても治療の役に立たない。"}'),
    ('117-E-38', '正答は B「カテーテルを抜去する前に固定水を抜く。」。

バルーンカテーテルは、抜去する前に注射器で固定水(バルーンの蒸留水)を完全に抜いてから引き抜く。膨らんだまま引くと尿道を損傷する。

出典：厚生労働省ホームページ 第117回医師国家試験 E038',
     '{"A": "仰臥位で行う。座位では操作しにくく清潔も保ちにくい。", "C": "エタノールは粘膜を刺激するため用いない。外尿道口の消毒には水溶性の消毒薬を使う。", "D": "潤滑剤はカテーテルの外側と尿道に用いる。内腔に注入すれば流出路を塞いでしまう。", "E": "頻回の交換はかえって尿路感染や尿道損傷の危険を高める。閉塞や汚染があるときに交換する。"}'),
    ('117-E-39', '正答は B「子どもに話しかける。」。

急性中耳炎が疑われる2歳児が不安で泣いている。まず子どもと目線を合わせて話しかけ、母親に抱かれたままの姿勢で安心させてから診察に入る。信頼関係を作ることが正確な所見を得る近道になる。

出典：厚生労働省ホームページ 第117回医師国家試験 E039',
     '{"A": "診察台に寝かせると不安が強まる。母親に抱かれた状態のまま診るほうがよい。", "C": "耳鏡による診察のために鎮静薬を用いる必要はない。", "D": "夜間眠れないほどの痛みと発熱があり、この日のうちに鼓膜を確認すべきである。", "E": "耳鏡は痛みを伴い児が嫌がるため、最後に行う。まず苦痛の少ない診察から進める。"}'),
    ('117-E-41', '正答は A「肺転移」。

設問は嘔吐の原因として「誤っている」ものを選ぶもの。肺転移は呼吸器症状をきたすが、嘔吐の原因にはならない。両肺の多発小結節は所見としてあっても、この嘔吐とは結びつかない。

出典：厚生労働省ホームページ 第117回医師国家試験 E041',
     '{"B": "終末期には予期性嘔吐など心理的な要因も嘔吐に関わる。考慮すべきである。", "C": "アルブミンが低いので補正すると高カルシウム血症にあたり、嘔吐の原因になる。", "D": "オピオイドを定期内服しており、悪心・嘔吐はその代表的な副作用である。", "E": "腹部膨隆と金属音があり、癌性腹膜炎による消化管閉塞は十分に考えられる。"}'),
    ('117-E-42', '正答は D「視線を合わせて、次の言葉を待つ。」。

「なぜ自分が」という問いは答えを求めているのではなく、生きる意味が揺らいだ苦しみの表れである。ここで求められるのは説明でも評価でもなく、視線を合わせて沈黙を共にし、次の言葉を待つことである。

出典：厚生労働省ホームページ 第117回医師国家試験 E042',
     '{"A": "話題を逸らすのは、訴えを受け止めないという返答になってしまう。", "B": "理由を問い詰めれば、患者は責められていると感じる。", "C": "罹患率という統計は、この問いへの答えになっていない。", "E": "その考えが良いか悪いかを評価する立場に医師はない。"}'),
    ('117-E-43', '正答は E「扁平足の有無」。

設問は優先度の「低い」項目を選ぶもの。糖尿病の足の診察では、神経障害・血流障害・皮膚病変の三つを見て、足潰瘍と切断につながる変化を早く見つける。扁平足の有無は足の形態の問題で、この場面での優先度は低い。

出典：厚生労働省ホームページ 第117回医師国家試験 E043',
     '{"A": "アキレス腱反射の低下は糖尿病性多発神経障害を示す所見で、優先して確認する。", "B": "足背動脈の拍動は末梢動脈疾患の評価にあたり、潰瘍の治りやすさを左右する。", "C": "潰瘍や胼胝、白癬などの皮膚病変は感染の入口になるため必ず見る。", "D": "内顆での振動覚は神経障害を捉えやすく、優先度が高い。"}'),
    ('117-E-44', '正答は E「心身機能の評価をもとにした血糖コントロール目標の設定」。

独居の高齢者で、増殖網膜症と硝子体出血、神経障害があり、生活の実情も踏まえた個別の目標設定が要る。高齢者では認知機能とADL、併存疾患から区分を決め、低血糖を避けるための下限も含めて目標を設定する。

出典：厚生労働省ホームページ 第117回医師国家試験 E044',
     '{"A": "尿蛋白はごく軽度でeGFRも保たれており、蛋白制限の適応となる顕性腎症ではない。", "B": "増殖網膜症と硝子体出血があり、強度の高い運動は眼底出血を助長する。", "C": "一律に強いエネルギー制限をかけると、低血糖やサルコペニアを招く。", "D": "スルホニル尿素薬による厳格な管理は、独居の高齢者では重症低血糖の危険が大きい。"}'),
    ('117-E-45', '正答は A「①」。

感染症の事前確率を最も大きく動かすのは曝露歴である。下線部①の「同居している息子が発症した」は、家庭内という濃厚な曝露を示し、事前確率を高くする。

出典：厚生労働省ホームページ 第117回医師国家試験 E045',
     '{"B": "陽性が判明した時点で本人が無症状だったことは、その後の発症を否定しない。事前確率を上げる情報ではない。", "C": "自身で行った抗原定性検査の陰性は、むしろ確率を下げる方向の情報である。", "D": "高血圧症は重症化のリスク因子ではあるが、感染しているかどうかの確率とは別である。", "E": "無職で外出が少ないことは、家庭外での曝露機会をむしろ減らす。"}'),
    ('117-E-46', '正答は A「新型コロナウイルス〈SARS-CoV-2〉PCR検査」。

抗原定性検査は感度が高くなく、陰性でも感染を否定できない。同居家族の発症という強い曝露があり、発熱と呼吸器症状も揃っているため、感度の高いPCR検査で確かめる。

出典：厚生労働省ホームページ 第117回医師国家試験 E046',
     '{"B": "インフルエンザも鑑別に挙がるが、家庭内での明らかな曝露がある以上、優先度は下がる。", "C": "アデノウイルスは成人の肺炎の原因として考えにくい。", "D": "マイコプラズマは若年者に多く、この曝露歴のもとでは優先度が低い。", "E": "RSウイルスは主に乳幼児で問題になる。"}'),
    ('117-E-47', '正答は B「胸腔穿刺」。

頸静脈の怒張、気管の右方偏位、左胸部の鼓音と呼吸音消失があり、緊張性気胸である。胸腔内の圧が上がって静脈還流が妨げられ、放置すれば数分で心停止に至る。画像を待たずに脱気する。

出典：厚生労働省ホームページ 第117回医師国家試験 E047',
     '{"A": "発声が可能で気道は開通している。陽圧換気はかえって胸腔内圧を上げ、緊張性気胸を悪化させる。", "C": "昇圧薬は原因である胸腔内圧の上昇を取り除かない限り効かない。", "D": "出血への対応も要るが、まず還流障害を解除しなければ輸血も届かない。", "E": "中心静脈カテーテルの留置は時間がかかり、この場面で優先しない。"}'),
    ('117-E-48', '正答は B「鼻から挿入する。」。

設問は手順として「誤っている」ものを選ぶもの。前頭蓋底骨折があるため、経鼻での胃管挿入は篩板を越えて頭蓋内へ迷入する危険がある。この場合は口から入れる。

出典：厚生労働省ホームページ 第117回医師国家試験 E048',
     '{"A": "頸椎を保護したまま仰臥位で挿入することは差し支えない。", "C": "抵抗を感じたら無理に進めないのは、どの経路でも守るべき手順である。", "D": "吸引して胃内容物が引けることは位置確認の手掛かりになる。", "E": "胸部エックス線写真での位置確認は、注入前に必ず行う。"}'),
    ('117-E-49', '正答は B「項部硬直」。

発熱・頭痛・嘔吐が揃っており、細菌性髄膜炎を第一に考える。項部硬直は髄膜刺激徴候の代表で、その場で確かめられ、陽性なら腰椎穿刺へ進む判断に直結する。

出典：厚生労働省ホームページ 第117回医師国家試験 E049',
     '{"A": "眼振は前庭や小脳の障害をみる所見で、髄膜炎の診断には結びつかない。", "C": "Barré徴候は軽度の錐体路性の筋力低下をみるものである。", "D": "Babinski徴候は錐体路障害を示す所見で、髄膜刺激徴候ではない。", "E": "Romberg徴候は深部感覚性の失調をみるものである。"}'),
    ('117-E-50', '正答は C「脳脊髄液検査」。

頭部単純CTで異常がなく、髄膜炎を疑う病像が残っている。脳脊髄液検査で細胞数・糖・蛋白を調べ、培養とグラム染色に出せば起因菌まで迫れる。占拠性病変がないことをCTで確かめたので安全に行える。

出典：厚生労働省ホームページ 第117回医師国家試験 E050',
     '{"A": "脳波はてんかんや脳症の評価に用いるもので、髄膜炎の診断にはならない。", "B": "感染性心内膜炎を疑えば心エコーも要るが、この病像ではまず髄液である。", "D": "針筋電図は神経筋疾患の評価で、この場面では適応がない。", "E": "嘔吐はあるが、上部消化管内視鏡で髄膜炎は分からない。"}'),
    ('117-F-1', '正答は C「肺炎球菌性肺炎」。

肺炎球菌は莢膜をもつ細菌で、これに対抗するのは抗体と補体による液性免疫と脾臓の働きである。Tリンパ球の機能低下による日和見感染症には含まれない。無脾症や低ガンマグロブリン血症で問題となる。

出典：厚生労働省ホームページ 第117回医師国家試験 F001',
     '{"A": "結核菌は細胞内寄生菌で、細胞性免疫が落ちると封じ込めが破れて粟粒結核として再燃する。", "B": "食道カンジダ症はCD4陽性リンパ球が減少したときに生じ、後天性免疫不全症候群の指標疾患である。", "D": "ニューモシスチス肺炎はCD4が200/μL未満に減った状況で起こる代表的な日和見感染症である。", "E": "サイトメガロウイルスは潜伏感染し、細胞性免疫の低下により網膜炎や腸炎として再活性化する。"}'),
    ('117-F-3', '正答は A「バリアフリーの推進」。

ノーマライゼーションは、障害の有無にかかわらず誰もが地域で当たり前の生活を送れる社会をつくるという考え方である。段差の解消や情報の保障などバリアフリーの推進はその具体化にあたる。

出典：厚生労働省ホームページ 第117回医師国家試験 F003',
     '{"B": "リビングウィルの尊重は終末期における自己決定の尊重にあたる。", "C": "セカンドオピニオンの利用は治療選択における患者の自己決定を支える仕組みである。", "D": "ヘルスプロモーションは人々が自らの健康を管理し改善できるようにする過程で、オタワ憲章に基づく。", "E": "インフォームド・コンセントは説明を受けたうえで同意するという自己決定の原則である。"}'),
    ('117-F-4', '正答は D「血清アルブミン値」。

生理的黄疸は、新生児が多血であること、赤血球寿命が短いこと、グルクロン酸抱合酵素の活性が低いこと、腸肝循環が亢進していることが重なって生じる。血清アルブミン値はビリルビンの運搬能に関わり核黄疸の危険を左右するが、黄疸そのものの成因ではない。

出典：厚生労働省ホームページ 第117回医師国家試験 F004',
     '{"A": "新生児は多血でヘマトクリットが高く、崩壊する赤血球が多いためビリルビンの産生が多い。", "B": "腸内細菌叢が未熟でβ-グルクロニダーゼにより脱抱合され、再吸収される腸肝循環が亢進している。", "C": "新生児の赤血球寿命は70〜90日と成人より短く、崩壊が多い。", "E": "肝のグルクロン酸抱合酵素の活性が低く、間接ビリルビンを処理しきれない。"}'),
    ('117-F-6', '正答は D「在宅療養中の肺がん終末期の肺炎による死亡」。

医療関連死は医療行為に関連して生じた死亡を指す。在宅療養中の肺癌終末期に肺炎で亡くなるのは原疾患の自然な経過であり、医療行為に起因するものではない。

出典：厚生労働省ホームページ 第117回医師国家試験 F006',
     '{"A": "手術という医療行為に伴う出血による死亡で、医療関連死にあたる。", "B": "機器の誤用という医療行為の過程で生じた死亡である。", "C": "検査という医療行為の最中に生じた死亡である。", "E": "入院中の療養看護の過程で生じた褥瘡に起因しており、医療関連死にあたる。"}'),
    ('117-F-9', '正答は C「味覚障害」。

味覚障害は亜鉛欠乏や薬剤、口腔乾燥などで生じるもので、誤嚥を示す所見ではない。誤嚥は原因不明の発熱、湿性咳嗽、喀痰の増加、飲水時のむせから疑う。

出典：厚生労働省ホームページ 第117回医師国家試験 F009',
     '{"A": "誤嚥性肺炎により発熱をきたす。高齢者では発熱だけが手がかりのこともある。", "B": "気道に入った唾液や食物により湿った咳が出る。", "D": "気道への異物の刺激で分泌が増え、喀痰が増加する。", "E": "水分は最も誤嚥しやすく、飲水時のむせは嚥下障害の代表的な徴候である。"}'),
    ('117-F-11', '正答は D「網膜色素変性 — 輪状暗点」。

網膜色素変性では網膜の中間周辺部から杆体が変性するため、初期には夜盲と輪状暗点が生じ、進行すると求心性視野狭窄となる。

出典：厚生労働省ホームページ 第117回医師国家試験 F011',
     '{"A": "緑内障では網膜神経線維の走行に沿った弓状暗点(Bjerrum暗点)や鼻側階段が生じる。中心視力は末期まで保たれる。", "B": "視神経炎では乳頭黄斑線維が侵され中心暗点をきたす。", "C": "加齢黄斑変性では黄斑が侵されるため中心暗点と変視症が生じる。", "E": "中心性漿液性網脈絡膜症も黄斑の漿液性剝離により中心暗点と小視症をきたす。らせん状視野は心因性視覚障害の所見である。"}'),
    ('117-F-12', '正答は B「Crohn病」。

Crohn病は口腔から肛門までの全消化管を侵しうる疾患で、アフタ性口内炎は腸管外病変としてしばしばみられる。縦走潰瘍、敷石像、非乾酪性肉芽腫、痔瘻とともに診断の手がかりになる。

出典：厚生労働省ホームページ 第117回医師国家試験 F012',
     '{"A": "腸結核は回盲部に輪状潰瘍をきたすが、口腔内アフタは特徴的でない。", "C": "大腸憩室症は腸管壁の脱出によるもので、口腔病変を伴わない。", "D": "虚血性大腸炎は下行結腸からS状結腸の血流障害によるもので、口腔病変とは無関係である。", "E": "過敏性腸症候群は器質的病変を伴わない機能性疾患である。"}'),
    ('117-F-13', '正答は D「色素沈着」。

副腎腺腫が自律的にコルチゾールを分泌するため、負のフィードバックで下垂体のACTHは抑制される。ACTHの前駆体に由来するメラニン細胞刺激作用も働かないので、色素沈着はきたさない。色素沈着がみられるのは異所性ACTH症候群やAddison病である。

出典：厚生労働省ホームページ 第117回医師国家試験 F013',
     '{"A": "脂肪の中心性再分布により満月様顔貌(円形顔貌)を呈する。", "B": "顔面の脂肪沈着と体液貯留により眼瞼の腫れぼったさをきたす。", "C": "骨形成の抑制と骨吸収の亢進により骨粗鬆症をきたし、椎体骨折の原因となる。", "E": "皮膚が菲薄化し、腹部などに赤紫色の皮膚線条を生じる。"}'),
    ('117-F-14', '正答は C「完全大血管転位症」。

完全大血管転位症では体循環と肺循環が並列となり、卵円孔と動脈管を通じた血液の混合がなければ生存できない。出生直後からチアノーゼが強く、プロスタグランジンE1で動脈管を開存させ、必要ならバルーン心房中隔裂開術を行う。

出典：厚生労働省ホームページ 第117回医師国家試験 F014',
     '{"A": "心房中隔欠損症は成人期まで無症状で経過することも多い。", "B": "心室中隔欠損症では肺血管抵抗が下がる生後数週から心不全症状が現れる。出生直後の緊急介入は要さない。", "D": "部分肺静脈還流異常症は短絡量が少なく、症状に乏しい。", "E": "房室中隔欠損症も心不全は生後数週以降に現れる。"}'),
    ('117-F-15', '正答は B「カルシウム」。

挫滅症候群では壊れた筋細胞からカリウム、ミオグロビン、CK、リンが放出される一方、遊離したリンと結合したカルシウムが壊死筋に沈着するため血清カルシウムは低下する。

出典：厚生労働省ホームページ 第117回医師国家試験 F015',
     '{"A": "細胞内に多いカリウムが放出され高カリウム血症となる。致死性不整脈の原因となる。", "C": "筋の破壊を反映してCKが著明に上昇する。", "D": "傷害された筋への大量の体液移動により循環血漿量が減り、血液が濃縮してヘマトクリットが上昇する。", "E": "ミオグロビンが血中に放出され、腎尿細管を傷害して急性腎障害をきたす。"}'),
    ('117-F-19', '正答は B「2時間」。

水やお茶など固形物を含まない清澄水は、麻酔導入の2時間前まで摂ってよいとされている。長い絶飲は脱水や不快感を招くだけで、誤嚥の予防にはつながらない。

出典：厚生労働省ホームページ 第117回医師国家試験 F019',
     '{"A": "15分では胃内容が排出しきらず短すぎる。", "C": "6時間は軽い固形食(パンなど)に必要な絶食時間である。", "D": "12時間の絶飲は不要に長く、脱水を招く。", "E": "24時間の絶飲は害があるだけである。"}'),
    ('117-F-20', '正答は D「蛋白質摂取を制限する。」。

フレイルの背景にはサルコペニアがあり、筋肉量を保つには十分な蛋白質が要る。制限はむしろ悪化させるので誤りである。高齢者では1.0g/kg/日以上の摂取が勧められる。

出典：厚生労働省ホームページ 第117回医師国家試験 F020',
     '{"A": "口腔機能の衰え(オーラルフレイル)は低栄養につながるため、口腔のケアは予防策となる。", "B": "レジスタンス運動を含む運動習慣は筋力低下を防ぐ。", "C": "よく嚙むことは咀嚼機能を保ち、食事摂取量の維持につながる。", "E": "社会参加は社会的フレイルを防ぎ、身体活動と意欲の維持にもつながる。"}'),
    ('117-F-21', '正答は C「プロテインC」。

ビタミンK依存性の蛋白は、凝固因子の第II・VII・IX・X因子と、抗凝固に働くプロテインCおよびプロテインSである。グルタミン酸残基のγ-カルボキシル化にビタミンKが要る。

出典：厚生労働省ホームページ 第117回医師国家試験 F021',
     '{"A": "第V因子はビタミンK依存性ではない。肝で合成されるが γ-カルボキシル化を受けない。", "B": "第XIII因子はフィブリンを架橋する因子で、ビタミンK依存性ではない。", "D": "フィブリノゲンは肝で合成されるがビタミンK依存性ではない。", "E": "アンチトロンビンも肝で合成される抗凝固因子だが、ビタミンK依存性ではない。"}'),
    ('117-F-22', '正答は A「成人特有の反応である。」。

悲嘆反応は年齢を問わず生じる。子どもも死別に反応するが、退行や身体症状、遊びを通した表現など大人と異なる形をとることがあり、発達段階に応じた支援が要る。

出典：厚生労働省ホームページ 第117回医師国家試験 F022',
     '{"B": "抑うつ気分や不眠はうつ病と重なるため、経過や自責感の質から鑑別する必要がある。", "C": "不眠、食欲低下、疲労感など身体的な影響も生じる。", "D": "死別による悲嘆を抱える人への支援をグリーフケアという。", "E": "多くは時間とともに軽快する。長引いて生活に支障をきたす場合は遷延性悲嘆症として対応する。"}'),
    ('117-F-24', '正答は E「簡易精神症状評価尺度[Brief Psychiatric Rating Scale〈BPRS〉]」。

簡易精神症状評価尺度(BPRS)は、思考解体、幻覚、感情の平板化など18項目を評価者が採点する尺度で、統合失調症の精神症状を包括的にとらえて治療効果の判定に用いる。

出典：厚生労働省ホームページ 第117回医師国家試験 F024',
     '{"A": "Rorschachテストはインクの染みへの反応から人格傾向をみる投影法の検査である。", "B": "状態特性不安検査は不安の程度を、その時の状態と性格傾向に分けて測る。", "C": "リバーミード行動記憶検査は日常生活に即した記憶障害の評価に用いる。", "D": "Mini-Mental State Examinationは認知機能のスクリーニング検査である。"}'),
    ('117-F-26', '正答は D「日光角化症」。

デルマドロームは内臓疾患に伴って現れる皮膚症状のことである。日光角化症は長年の紫外線曝露によって生じる前癌病変で、内臓疾患を反映するものではない。

出典：厚生労働省ホームページ 第117回医師国家試験 F026',
     '{"A": "Sweet病(急性熱性好中球性皮膚症)は骨髄異形成症候群や白血病に伴うことがある。", "B": "皮膚筋炎は悪性腫瘍の合併率が高く、悪性腫瘍の検索が必要である。", "C": "黒色表皮腫はインスリン抵抗性や胃癌などの内臓悪性腫瘍に伴う。", "E": "壊疽性膿皮症は潰瘍性大腸炎やCrohn病、関節リウマチなどに伴う。"}'),
    ('117-F-27', '正答は C「多発性骨髄腫 — 紅皮症」。

紅皮症は全身の皮膚が潮紅して落屑する状態で、皮膚T細胞リンパ腫(Sézary症候群)や薬疹、乾癬などでみられる。多発性骨髄腫の特徴的な症候ではなく、この組合せが誤っている。

出典：厚生労働省ホームページ 第117回医師国家試験 F027',
     '{"A": "Hodgkinリンパ腫では発熱と無熱期を繰り返すPel-Ebstein型の間欠熱がみられる。正しい組合せである。", "B": "菌状息肉症は皮膚T細胞リンパ腫で、紅斑期から局面期を経て腫瘤期に至る。正しい組合せである。", "D": "マクログロブリン血症では過粘稠度症候群により網膜静脈の怒張と蛇行をきたす。正しい組合せである。", "E": "慢性リンパ性白血病ではリンパ節腫脹とともに肝脾腫をきたす。正しい組合せである。"}'),
    ('117-F-28', '正答は B「警報音は高音域の音とする。」。

加齢に伴って高い周波数の音から聞き取りにくくなる。警報音は低音域を用いるほうが高齢労働者に届きやすいので、高音域とするのは適切でない。

出典：厚生労働省ホームページ 第117回医師国家試験 F028',
     '{"A": "つまずきによる転倒を防ぐため、段差の解消は有効である。", "C": "加齢により必要な明るさが増すため、十分な照度の確保は有効である。", "D": "標識による注意喚起は危険の認知を助ける。", "E": "腰を落としてから持ち上げる姿勢は腰部への負担を減らし、腰痛を防ぐ。"}'),
    ('117-F-29', '正答は E「変容が得られないときは意思を強く持つよう指導する。」。

行動が変わらないときに意思の強さを求めるのは、うまくいかない原因を本人の性格に帰することになり、自己効力感を下げてしまう。障壁を一緒に洗い出し、目標を実行しやすい大きさに調整するほうが効果的である。

出典：厚生労働省ホームページ 第117回医師国家試験 F029',
     '{"A": "自分で決めた目標のほうが実行につながる。", "B": "体重や歩数を自分で記録するセルフモニタリングは行動変容の基本的な技法である。", "C": "周囲の規範や価値観に働きかけることは行動変容を後押しする。", "D": "行動変容ステージに応じて働きかけを変えることが効果を高める。"}'),
    ('117-F-30', '正答は E「12か月 — 非対称性緊張性頸反射」。

非対称性緊張性頸反射は原始反射で、生後4〜6か月ごろまでに消える。12か月で残っていれば中枢神経の障害を疑う所見であり、この組合せが誤りである。

出典：厚生労働省ホームページ 第117回医師国家試験 F030',
     '{"A": "Moro反射は生後4〜6か月ごろまでみられる。1か月でみられるのは正常である。", "B": "足底把握反射は生後9〜10か月ごろまでみられる。3か月でみられるのは正常である。", "C": "Landau反射は生後4〜6か月ごろから2歳ごろまでみられる姿勢反射である。", "D": "パラシュート反射は生後8〜9か月ごろに出現し、生涯残る。"}'),
    ('117-F-32', '正答は D「見当識障害」。

見当識障害は意識障害や認知症、せん妄でみられる症状で、躁状態では意識は清明に保たれる。躁状態では気分の高揚、観念奔逸、行為心迫、誇大的な言動が前面に出る。

出典：厚生労働省ホームページ 第117回医師国家試験 F032',
     '{"A": "多弁は観念奔逸を反映した躁状態の代表的な症状である。", "B": "抑制がきかず高額な買い物をするなどの浪費は躁状態でよくみられる。", "C": "思いどおりにならないと激しく怒る易怒性・易刺激性も躁状態の症状である。", "E": "眠らなくても平気で活動を続ける睡眠欲求の減少は躁状態の特徴である。"}'),
    ('117-F-34', '正答は A「医師の免許」。

医師法は医師の免許、国家試験、臨床研修、業務(応召義務、診断書交付義務、無診察治療の禁止、異状死体の届出、診療録の記載と保存)を定める。免許に関する規定は医師法である。

出典：厚生労働省ホームページ 第117回医師国家試験 F034',
     '{"B": "医師の守秘義務は刑法第134条に規定されている。医師法には定めがない。", "C": "病院・診療所・助産所といった医療機関の種類は医療法が定める。", "D": "医療の安全の確保は医療法に定められている。", "E": "特定機能病院の要件も医療法が定める。"}'),
    ('117-F-35', '正答は E「頭部MRAの検査予定日」。

カプセル内視鏡は消化管に停滞することがあり、そのままMRI検査を受けると発熱や粘膜損傷の危険がある。頭部MRAが予定されているので、カプセルの排出を確認してから検査を受けるよう日程を調整する必要がある。

出典：厚生労働省ホームページ 第117回医師国家試験 F035',
     '{"A": "排便は2日に1回の普通便で、通過を妨げるほどの便秘ではない。", "B": "虫垂切除術は開腹歴ではあるが、癒着による狭窄を疑う症状はなく、最も注意すべき点ではない。", "C": "カプセル内視鏡は生検や処置を伴わないので、抗凝固薬の休薬を要さない。", "D": "抗不安薬の内服はカプセル内視鏡の実施に影響しない。"}'),
    ('117-F-36', '正答は C「8点」。

心拍は6秒間に12回で毎分120回のため2点、啼泣が強く呼吸は2点、四肢を活発に動かす筋緊張は2点、刺激への咳嗽という反射は2点、皮膚色が全身暗紫色で0点となり、合計8点である。

出典：厚生労働省ホームページ 第117回医師国家試験 F036',
     '{"A": "6点ではどこかの項目をさらに1点減じることになるが、該当する所見がない。", "B": "7点も同様に減点する根拠がない。", "D": "皮膚色が全身暗紫色なので0点であり、9点にはならない。", "E": "満点となるのは全身が淡紅色の場合で、本児は当てはまらない。"}'),
    ('117-F-37', '正答は E「Pseudomonas aeruginosa」。

寛解導入療法後の好中球数は500×1%で5/μLと極度の好中球減少にあたる。発熱性好中球減少症では緑膿菌による敗血症が最も予後を左右するため、抗緑膿菌活性をもつ抗菌薬を直ちに開始する。

出典：厚生労働省ホームページ 第117回医師国家試験 F037',
     '{"A": "Clostridium perfringensはガス壊疽の起因菌で、発熱性好中球減少症の初期治療の主たる標的ではない。", "B": "Enterococcus faecalisも問題になりうるが、初期治療で最優先されるのは緑膿菌である。", "C": "Haemophilus influenzaeは市中肺炎の起因菌で、この状況で最優先とはならない。", "D": "Moraxella catarrhalisも市中の気道感染の起因菌である。"}'),
    ('117-F-38', '正答は D「「専門の病院に緊急入院して精査が必要です」」。

白血球95万という著明な増加に、Hb5.6g/dLの貧血と血小板1.5万の減少、LDと尿酸の上昇を伴っており、乳児の急性白血病が強く疑われる。白血球うっ滞と腫瘍崩壊症候群の危険があり、専門施設への緊急入院が必要である。

出典：厚生労働省ホームページ 第117回医師国家試験 F038',
     '{"A": "点滴をして帰宅させてよい状態ではない。", "B": "受診の遅れを責めることは母親を追い詰めるだけで、医学的にも意味がない。", "C": "翌日まで待てる状態ではない。", "E": "生命に関わる病態であり、心配は要らないという説明は誤りである。"}'),
    ('117-F-39', '正答は C「ループ利尿薬」。

糖尿病性腎症による腎不全とネフローゼ状態に、体重7kgの増加、下腿浮腫、心拡大と肺うっ血を伴っており体液過剰である。まずループ利尿薬で除水し、うっ血を解除する。

出典：厚生労働省ホームページ 第117回医師国家試験 F039',
     '{"A": "新鮮凍結血漿は凝固因子の補充に用いるもので、膠質浸透圧を上げる目的で使うものではない。", "B": "Hb8.6g/dLの腎性貧血は緊急の輸血を要する水準ではなく、輸血は体液量をさらに増やす。", "D": "アルブミン製剤は低アルブミン血症の是正を目的とした投与が推奨されておらず、体液量を増やす。", "E": "K5.8mEq/Lと高カリウム血症があり、カリウムを含む維持輸液は禁忌にあたる。体液過剰でもある。"}'),
    ('117-F-41', '正答は D「定期的な悪性腫瘍スクリーニングが必須である。」。

移植後は免疫抑制薬を長期に続けるため、免疫監視機構が働きにくくなり悪性腫瘍の発生率が高まる。皮膚癌やリンパ増殖性疾患をはじめ、定期的なスクリーニングが欠かせない。

出典：厚生労働省ホームページ 第117回医師国家試験 F041',
     '{"A": "生体腎提供者は腎機能や血圧の経過をみるため生涯にわたる定期受診が必要である。", "B": "状態が安定していれば海外旅行もできる。渡航先の感染症対策と薬の携行に注意する。", "C": "不活化ワクチンであるインフルエンザワクチンは接種でき、むしろ推奨される。生ワクチンは避ける。", "E": "生体腎移植の10年生着率は8割前後で、半数が透析に戻るわけではない。"}'),
    ('117-F-43', '正答は E「総エネルギー摂取量の40〜60%を炭水化物由来とする。」。

2型糖尿病の食事療法では、指示エネルギー量の40〜60%を炭水化物から摂り、蛋白質20%まで、残りを脂質とするのが標準的な配分である。

出典：厚生労働省ホームページ 第117回医師国家試験 F043',
     '{"A": "血圧144/92mmHgもあり、食塩は6g/日未満を目標とする。10g/日未満では緩すぎる。", "B": "腎症がなく蛋白質を35g/日未満に絞る理由はない。過度の制限は栄養障害を招く。", "C": "飽和脂肪酸は動脈硬化を促すため控えるべきで、50g/日以上という指示は逆である。", "D": "身長152cmの標準体重は約50.9kgで、25〜30kcal/kgとすると1,300〜1,500kcal/日が目安となる。1,800kcalは多い。"}'),
    ('117-F-44', '正答は E「日常生活動作〈ADL〉」。

予約どおりバスを使って来院し、身だしなみも整っている。移動と身の回りの管理ができており、日常生活動作は保たれていると判断できる。

出典：厚生労働省ホームページ 第117回医師国家試験 F044',
     '{"A": "好きだった花の手入れや食事の準備が億劫になっており、意欲は低下している。", "B": "よくつまずいて転倒しており、運動機能は低下している。", "C": "食欲が低下し食事量も減っており、栄養状態は悪化しつつある。", "D": "食事中にむせるようになっており、嚥下機能は低下している。"}'),
    ('117-F-45', '正答は B「禁酒」。

ビール350mLを週2回は節度ある適度な飲酒の範囲内で、これをやめても腎機能の維持にはつながらない。BMI29.0の肥満、蛋白質2.0g/kg/日、食塩9.5g/日という是正すべき点が明らかにある。

出典：厚生労働省ホームページ 第117回医師国家試験 F045',
     '{"A": "喫煙は腎機能低下を進める確立した危険因子で、禁煙の効果は大きい。", "C": "BMI29.0の肥満は糸球体過剰濾過を招く。減量は蛋白尿と腎機能低下を抑える。", "D": "食塩9.5g/日は多い。6g/日未満への制限は降圧と蛋白尿の減少をもたらす。", "E": "蛋白質2.0g/kg/日は過剰で、0.6〜0.8g/kg/日程度への制限が腎機能低下の進行を抑える。"}'),
    ('117-F-49', '正答は B「カルシウム拮抗薬」。

Ca11.5mg/dLの高カルシウム血症、K6.0mEq/Lの高カリウム血症、クレアチニン2.1mg/dLの腎機能低下があり、ACE阻害薬・NSAID・ビスホスホネート製剤はいずれも中止・見直しが要る。カルシウム拮抗薬はこれらの異常に関与せず、血圧160/96mmHgに対しても継続してよい。

出典：厚生労働省ホームページ 第117回医師国家試験 F049',
     '{"A": "NSAIDは腎血流を減らして腎障害を悪化させ、高カリウム血症も助長する。中止する。", "C": "ビスホスホネート製剤は腎機能低下時には慎重投与で、高カルシウム血症の原因検索が済むまで見直しが要る。", "D": "ベンゾジアゼピン系睡眠薬は1週間前から追加されており、意識レベルの低下と食欲低下に関与している可能性が高い。", "E": "ACE阻害薬は腎機能低下と高カリウム血症を悪化させるため中止する。"}'),
    ('117-F-51', '正答は A「気道確保」。

強い嚥下痛から始まり、含み声と吸気性喘鳴が急速に進んでおり急性喉頭蓋炎による上気道閉塞である。診察中にも増悪しており、まず気道確保を行う。窒息に備えて輪状甲状靱帯穿刺・切開の準備をしておく。

出典：厚生労働省ホームページ 第117回医師国家試験 F051',
     '{"B": "経鼻胃管の挿入は喉頭の刺激となり、かえって閉塞を招く危険がある。", "C": "消炎鎮痛薬では気道の腫脹はすぐに引かず、閉塞に間に合わない。", "D": "閉塞部位は喉頭であり、気管支拡張薬は効かない。", "E": "テオフィリンも気管支に作用する薬で、上気道閉塞には無効である。"}'),
    ('117-F-54', '正答は C「母乳を与えてから再度聴診を試みる。」。

乳児の心音を聴くには児が静かであることが要る。最後の授乳から2時間30分が経ち空腹で泣いているので、母乳を与えて落ち着かせ、あるいは入眠したところで聴診するのが最も現実的で侵襲もない。

出典：厚生労働省ホームページ 第117回医師国家試験 F054',
     '{"A": "心雑音の聴取のために鎮静薬を用いるのは侵襲が大きく、適切でない。", "B": "1か月児はおもちゃを手に持って遊べる発達段階にない。", "D": "聴診を試みる余地があるうちから心エコー検査に切り替える必要はない。まず身体診察を尽くす。", "E": "1か月児は映像に注意を向けられず、あやす手段にならない。"}'),
    ('117-F-55', '正答は B「早期破水」。

破水は子宮口全開大より前に起こると早期破水と呼ぶ。午前8時、子宮口6cm開大の時点で破水しており早期破水にあたる。分娩開始前の破水は前期破水である。

出典：厚生労働省ホームページ 第117回医師国家試験 F055',
     '{"A": "経産婦の分娩所要時間は15時間以内が目安で、午前1時の陣痛開始から午後1時の全開大まで12時間であり遷延分娩ではない。", "C": "陣痛周期3分、持続1分は有効な陣痛で、微弱陣痛ではない。", "D": "子宮口は4cmから6cm、全開大へと進み、児頭も下降しており停止していない。", "E": "小泉門を1時方向に触れ矢状縫合が骨盤縦径に一致しており、第1前方後頭位である。後方後頭位ではない。"}'),
    ('117-F-58', '正答は D「スタチンの開始」。

スタチンは尿酸値を上げず、痛風発作の誘因にならない。むしろ軽度に尿酸を下げるとの報告もある。

出典：厚生労働省ホームページ 第117回医師国家試験 F058',
     '{"A": "アルコールは尿酸の産生を増やし排泄を妨げるため、発作の誘因となる。", "B": "激しい運動はATPの分解を進めて尿酸を増やし、発汗による脱水も加わって誘因となる。", "C": "脱水は血中尿酸濃度を上げ、尿酸塩の析出を促す。", "E": "サイアザイド系などの降圧利尿薬は尿酸の排泄を妨げ、高尿酸血症をきたす。"}'),
    ('117-F-61', '正答は D「死亡診断書を作成する。」。

突然の頭痛から意識障害に至り、入院して治療を受けた経過であり、くも膜下出血という診療中の疾病で亡くなったと判断できる。診療していた医師が死亡診断書を作成する。

出典：厚生労働省ホームページ 第117回医師国家試験 F061',
     '{"A": "異状死ではないため、警察への届出は要らない。", "B": "保健所への届出は感染症など法で定められた場合に行うもので、この死亡は該当しない。", "C": "司法解剖は犯罪の疑いがある場合に行われる。", "E": "医療安全支援センターは患者からの相談を受ける窓口で、死亡の届出先ではない。"}'),
    ('117-F-62', '正答は A「II型呼吸不全」。

動脈血ガス分析では酸素分圧の低下に二酸化炭素の貯留を伴っており、II型呼吸不全である。長い喫煙歴、喘鳴、胸鎖乳突筋の肥大とあわせて慢性閉塞性肺疾患の像である。

出典：厚生労働省ホームページ 第117回医師国家試験 F062',
     '{"B": "閉塞性換気障害では呼気が延長する。短縮はしない。", "C": "吸気性の呼吸困難は上気道の狭窄で起こる。閉塞性肺疾患は呼気性である。", "D": "room airでの酸素分圧から求めると約267となり、200を上回る。", "E": "HCO3−が上がってpHが保たれており、慢性の呼吸性アシドーシスが代償された状態である。"}'),
    ('117-F-63', '正答は E「ヒスタミンH1受容体拮抗薬投与」。

設問は「誤っている」対応を選ぶもの。ヒスタミンH1受容体拮抗薬はアレルギー性の病態に用いる薬で、慢性閉塞性肺疾患の増悪には効かない。抗コリン作用で気道分泌物が粘稠になり、痰の喀出をかえって妨げる。

出典：厚生労働省ホームページ 第117回医師国家試験 F063',
     '{"A": "低酸素血症があり酸素投与は必要である。二酸化炭素の貯留があるため濃度は控えめにする。", "B": "膿性痰が出ており、細菌感染を伴う増悪として抗菌薬の適応がある。", "C": "全身性副腎皮質ステロイドの短期投与は増悪の標準治療である。", "D": "短時間作用性β2刺激薬の吸入は増悪時の第一選択である。"}'),
    ('117-F-64', '正答は E「非侵襲的陽圧換気〈NPPV〉」。

二酸化炭素が急激に溜まってアシドーシスに傾き、意識レベルも落ちている。換気そのものを助ける必要があり、非侵襲的陽圧換気で呼吸仕事量を減らして二酸化炭素を吐き出させる。

出典：厚生労働省ホームページ 第117回医師国家試験 F064',
     '{"A": "気管切開は長期の人工呼吸管理が要るときに検討するもので、急性期の最初の一手ではない。", "B": "気管挿管は非侵襲的陽圧換気で改善しないときや、意識障害が進んで気道が保てないときに進む。", "C": "酸素化はすでに足りている。酸素をさらに増やすと呼吸中枢への刺激が減り、二酸化炭素の貯留を悪化させる。", "D": "高気圧酸素治療は一酸化炭素中毒などの適応で、この病態には用いない。"}'),
    ('117-F-65', '正答は C「主訴」。

胆囊結石は無症状なら経過観察でよく、手術を勧める根拠になるのは症状があることである。本例は右季肋部痛が主訴で、頻度も増しており、腹腔鏡下胆囊摘出術の適応になる。

出典：厚生労働省ホームページ 第117回医師国家試験 F065',
     '{"A": "年齢そのものは手術適応を決める根拠にならない。", "B": "性別も適応を決める要素ではない。", "D": "高血圧症と糖尿病は周術期の管理で気をつける点であって、手術を勧める根拠ではない。", "E": "飲酒歴は胆石症の手術適応と結びつかない。"}'),
    ('117-F-66', '正答は C「当日術前、経口糖尿病薬を内服する。」。

設問は周術期管理として「誤っている」ものを選ぶもの。手術当日は絶食となるため、経口血糖降下薬をそのまま飲めば低血糖を起こす。当日朝は中止し、必要なら血糖を測りながらインスリンで調整する。

出典：厚生労働省ホームページ 第117回医師国家試験 F066',
     '{"A": "前日の夕食までは通常どおり摂取してよい。", "B": "降圧薬は中断すると血圧が変動するため、当日朝も少量の水で内服することが多い。", "D": "腹腔鏡下胆囊摘出術では翌日から食事を再開できる。", "E": "翌日に経口鎮痛薬へ切り替えるのは、術後疼痛管理として妥当である。"}'),
    ('117-F-69', '正答は E「姿勢反射障害」。

レボドパが当初よく効き、年余をかけて進行し、効果の持続が短くなってすくみ足と転倒が現れている。進行期のParkinson病であり、立ち直り反射が失われる姿勢反射障害が現れる。転倒の主な原因になる。

出典：厚生労働省ホームページ 第117回医師国家試験 F069',
     '{"A": "下肢の痙縮は錐体路障害の所見である。Parkinson病では歯車様の筋強剛をみる。", "B": "測定障害は小脳性失調の所見で、Parkinson病の症候ではない。", "C": "Parkinson病の振戦は安静時に目立ち、動作や姿勢の保持では弱まる。", "D": "垂直方向の眼球運動障害は進行性核上性麻痺で目立つ。本例はレボドパが著効しており、その像とは異なる。"}'),
    ('117-F-72', '正答は B「Dダイマー」。

経口避妊薬を内服しており、右下腿の浮腫、頻呼吸、低酸素血症、頸静脈怒張とII音の亢進が揃う。心電図の右心負荷所見もあわせて急性肺血栓塞栓症を疑い、Dダイマーを測る。

出典：厚生労働省ホームページ 第117回医師国家試験 F072',
     '{"A": "KL-6は間質性肺疾患の活動性をみる指標である。", "C": "フェリチンは鉄代謝や炎症の指標で、血栓の評価には使わない。", "D": "β-Dグルカンは深在性真菌症を疑うときの指標である。", "E": "プロカルシトニンは細菌感染の指標で、肺塞栓の診断には結びつかない。"}'),
    ('118-A-1', '正答は B「腹部大動脈瘤」。

腹部大動脈瘤は破裂するまで自覚症状に乏しく、腹部の拍動性腫瘤や、他の目的で行った画像検査で偶然見つかることが多い。径5cmを超えると破裂の危険が高まり、待機的な人工血管置換術やステントグラフト内挿術を検討する。

出典：厚生労働省ホームページ 第118回医師国家試験 A001',
     '{"A": "大動脈解離は突然の激烈な胸背部痛で発症する。", "C": "感染性心内膜炎は持続する発熱、心雑音、塞栓症状で気づかれる。", "D": "冠攣縮性狭心症は夜間から早朝の安静時胸痛で受診する。", "E": "たこつぼ心筋症は強い精神的・身体的ストレスの後に胸痛や呼吸困難で発症する。"}'),
    ('118-A-2', '正答は E「居室と脱衣所の温度差をなくす。」。

冬季の入浴中の事故の多くは、暖かい居室から寒い脱衣所・浴室へ移動した際の急激な血圧変動(ヒートショック)による。脱衣所と浴室を暖めて温度差をなくすことが最も有効な予防策である。

出典：厚生労働省ホームページ 第118回医師国家試験 A002',
     '{"A": "食後は消化管に血流が集まり血圧が下がりやすいので、食直後の入浴は避ける。", "B": "深夜は室温が下がり発見も遅れるため、危険が高い。", "C": "湯から出た後に体を冷やすと血管が収縮して血圧が急に上がる。", "D": "事故が多いのは気温の低い冬季であり、暑い時期を避けるのは的外れである。"}'),
    ('118-A-3', '正答は C「ビタミンD欠乏症」。

ビタミンD欠乏では腸管からのカルシウムとリンの吸収がともに低下する。低カルシウム血症に反応して副甲状腺ホルモンが上昇し、尿細管でのリン再吸収を抑えるため、低リン血症がさらに進む。

出典：厚生労働省ホームページ 第118回医師国家試験 A003',
     '{"A": "腫瘍性骨軟化症はFGF23の過剰産生による低リン血症が主体で、血清カルシウムは基準内に保たれる。", "B": "甲状腺機能亢進症では骨吸収が亢進して血清カルシウムはむしろ上昇する。", "D": "副甲状腺機能低下症では尿中へのリン排泄が減るため、低カルシウム血症と高リン血症になる。", "E": "慢性腎臓病ではリンの排泄が低下して高リン血症となり、活性型ビタミンD低下により低カルシウム血症をきたす。"}'),
    ('118-A-4', '正答は A「糖尿病」。

糖尿病では自律神経障害により心臓の求心性神経が障害され、心筋虚血があっても胸痛を自覚しない無痛性心筋虚血をきたす。発見が遅れて重症化しやすいので、定期的な心電図や負荷検査による評価が要る。

出典：厚生労働省ホームページ 第118回医師国家試験 A004',
     '{"B": "骨粗鬆症は骨量の減少による病態で、心筋虚血の自覚とは関係しない。", "C": "気管支喘息は気道の慢性炎症による疾患で、痛覚には影響しない。", "D": "Parkinson病では自律神経障害を伴うが、無痛性虚血をきたす代表的疾患としては挙げられない。", "E": "胃食道逆流症はむしろ狭心症と紛らわしい胸痛を起こす側である。"}'),
    ('118-A-5', '正答は B「湿性咳嗽」。

特発性肺線維症の咳嗽は痰を伴わない乾性咳嗽である。湿性咳嗽は気管支拡張症や慢性気管支炎など気道分泌の増える病態でみられる。

出典：厚生労働省ホームページ 第118回医師国家試験 A005',
     '{"A": "慢性の低酸素血症を反映してばち指がみられる。", "C": "進行すると呼吸仕事量の増大と食欲低下により体重が減る。", "D": "両側背下部に吸気終末のfine crackles(捻髪音)を聴取するのが特徴的である。", "E": "拡散障害と拘束性換気障害により労作時呼吸困難が徐々に進行する。"}'),
    ('118-A-6', '正答は D「膵管癌 — 膵・胆管合流異常症」。

膵・胆管合流異常症では膵液が胆道へ逆流し、胆道癌(とくに胆囊癌)の危険因子となる。膵管癌の原因ではないので、この組合せが誤りである。

出典：厚生労働省ホームページ 第118回医師国家試験 A006',
     '{"A": "肝細胞癌の大部分は肝炎ウイルスやアルコール、脂肪性肝疾患による肝硬変を背景に発生する。正しい組合せである。", "B": "胃食道逆流により生じたBarrett食道は食道腺癌の前癌病変である。正しい組合せである。", "C": "先天性胆道拡張症は膵・胆管合流異常を伴い、胆道癌の危険が高い。正しい組合せである。", "E": "ヘリコバクター・ピロリの持続感染は萎縮性胃炎を経て胃癌の原因となる。正しい組合せである。"}'),
    ('118-A-7', '正答は B「たばこパッケージの警告表示」。

たばこのパッケージには、健康被害に関する警告文の表示が法令で義務づけられている。表示面積の拡大など段階的に強化されてきた。

出典：厚生労働省ホームページ 第118回医師国家試験 A007',
     '{"A": "広告は業界の自主規制などで制限されているが、全面禁止には至っていない。", "C": "禁煙治療は一定の要件を満たせば保険が適用されるが、無料ではない。", "D": "健康増進法の改正で多くの施設は屋内原則禁煙となっており、分煙の義務化ではない。", "E": "喫煙の有無で医療保険の保険料を変える仕組みはない。"}'),
    ('118-A-8', '正答は A「自然治癒する。」。

痔瘻は肛門腺の感染から生じた瘻管が残ったもので、自然に治ることはない。瘻管を処理する手術が唯一の根治手段である。

出典：厚生労働省ホームページ 第118回医師国家試験 A008',
     '{"B": "Crohn病では難治性の痔瘻を合併することが多く、痔瘻から診断に至ることもある。", "C": "長年放置した痔瘻からは痔瘻癌が発生しうる。", "D": "肛門周囲膿瘍が自壊または切開排膿された後に瘻管が残って痔瘻となる。", "E": "瘻管の外口から便意と無関係に膿が出る。"}'),
    ('118-A-9', '正答は D「自己誘発嘔吐と下剤乱用を反復することが多い。」。

神経性過食症では、過食の後に体重増加を防ごうとして自己誘発嘔吐や下剤・利尿薬の乱用といった代償行動を反復する。嘔吐による低カリウム血症、う蝕、手背のタコ(Russell徴候)に注意する。

出典：厚生労働省ホームページ 第118回医師国家試験 A009',
     '{"A": "自己評価が体型や体重に強く左右され、自己肯定感はむしろ低い。", "B": "過活動が目立つのは神経性やせ症のほうである。", "C": "体重が増えることへの強い恐怖があり、それが代償行動の動機になる。", "E": "過食の最中は食べることを制御できないという感覚を伴うのが特徴である。"}'),
    ('118-A-10', '正答は A「TPHAは疾患活動性の指標となる。」。

TPHA(TP抗体)は梅毒トレポネーマそのものに対する抗体で、治癒後も生涯陽性のままとなるため疾患活動性の指標にならない。活動性と治療効果の判定にはRPRなどの脂質抗原検査の抗体価を用いる。

出典：厚生労働省ホームページ 第118回医師国家試験 A010',
     '{"B": "性感染症は重複しやすく、HIVやクラミジアなどの検索が必要である。", "C": "神経梅毒は早期にも生じうるため、感染からの期間で除外できない。", "D": "未治療の妊婦から経胎盤感染して先天梅毒をきたす。妊婦健診での検査が重要である。", "E": "国内の梅毒報告数は近年著しく増加している。"}'),
    ('118-A-11', '正答は E「前立腺全摘除術」。

前立腺全摘除術では外尿道括約筋やその支持組織が損傷され、咳やくしゃみなど腹圧がかかったときに尿がもれる腹圧性尿失禁をきたす。骨盤底筋訓練が治療の中心となる。

出典：厚生労働省ホームページ 第118回医師国家試験 A011',
     '{"A": "尿閉では膀胱に貯まった尿があふれる溢流性尿失禁となる。", "B": "脳梗塞では排尿反射の抑制が外れて切迫性尿失禁をきたす。", "C": "過活動膀胱は急な強い尿意を伴う切迫性尿失禁の原因である。", "D": "間質性膀胱炎は膀胱痛と頻尿が主症状である。"}'),
    ('118-A-12', '正答は E「ムンプスウイルス」。

ムンプスウイルスは内耳を直接侵し、多くは片側性の高度感音難聴を後遺症として残す。ワクチンで予防できる難聴として重要である。

出典：厚生労働省ホームページ 第118回医師国家試験 A012',
     '{"A": "アデノウイルスは咽頭結膜熱や流行性角結膜炎の原因で、難聴はきたさない。", "B": "EBウイルスは伝染性単核症の原因で、感音難聴の原因としては挙げられない。", "C": "単純ヘルペスウイルスは口唇ヘルペスや脳炎、Bell麻痺に関与するが、後天性の感音難聴の代表ではない。", "D": "風疹ウイルスによる難聴は胎内感染による先天性風疹症候群としてみられるもので、後天性ではない。"}'),
    ('118-A-16', '正答は D「高位精巣摘除術」。

無痛性の精巣腫大に充実性腫瘤と後腹膜リンパ節転移を認め、精巣腫瘍である。経陰囊的な生検は腫瘍を播種させるため行わず、鼠径部を切開して精索を高位で処理する高位精巣摘除術で診断と初期治療を兼ねる。

出典：厚生労働省ホームページ 第118回医師国家試験 A016',
     '{"A": "後腹膜リンパ節転移があり、経過観察は適応外である。", "B": "組織型が確定しないまま放射線治療は行えない。", "C": "経陰囊的な針生検は腫瘍細胞を陰囊内やリンパ路に播種させる危険があり禁忌である。", "E": "化学療法は高位精巣摘除術で組織型を確かめてから行う。"}'),
    ('118-A-19', '正答は D「胸部〜下肢造影CT」。

若年発症で家族歴に脳静脈洞血栓症があり、下肢浮腫とDダイマー10μg/mLの上昇を伴っている。遺伝性の血栓性素因を背景とした深部静脈血栓症と肺血栓塞栓症を疑い、胸部から下肢までの造影CTで血栓の有無と範囲を一度に評価する。

出典：厚生労働省ホームページ 第118回医師国家試験 A019',
     '{"A": "気管支鏡検査は気道や肺実質の病変を調べるもので、血栓の評価にはならない。", "B": "呼吸機能検査は急性の血栓塞栓症の診断には役立たず、実施にも時間がかかる。", "C": "頸部超音波検査は頸動脈の動脈硬化の評価に用いる。", "E": "足関節上腕血圧比は下肢の動脈閉塞をみる検査で、静脈血栓の評価には使えない。"}'),
    ('118-A-25', '正答は E「サイトメガロウイルス感染症」。

妊娠初期検査で風疹HI抗体価が高く梅毒もHIVも陰性であった妊婦が、妊娠15週の感冒様症状の後に胎児発育不全と胎児腹水をきたしている。母体の初感染から経胎盤感染するサイトメガロウイルス感染症が最も考えられる。

出典：厚生労働省ホームページ 第118回医師国家試験 A025',
     '{"A": "水痘の母子感染では四肢低形成や瘢痕性皮膚病変が特徴で、水疱疹のエピソードもない。", "B": "RPR 1倍未満、TPHA陰性で梅毒は否定される。", "C": "風疹HI抗体価128倍と免疫があり、初感染は考えにくい。", "D": "HBs抗原陰性であり、また B型肝炎の母子感染は分娩時感染が主で胎児発育不全をきたさない。"}'),
    ('118-A-29', '正答は A「抗菌薬」。

発熱、下腹部の反跳痛、子宮の圧痛、外子宮口からの膿性分泌物、著明な白血球増多とCRP上昇から骨盤内炎症性疾患である。淋菌とクラミジアを想定した抗菌薬治療を速やかに始める。

出典：厚生労働省ホームページ 第118回医師国家試験 A029',
     '{"B": "整腸薬では感染は治らない。", "C": "起因菌は細菌であり、抗ウイルス薬の適応はない。", "D": "GnRHアゴニストは子宮内膜症や子宮筋腫に用いる。", "E": "感染症に対してグルココルチコイドを単独で用いれば病態を悪化させる。"}'),
    ('118-A-30', '正答は C「ベンゾジアゼピン系薬剤」。

長年の多量飲酒者が断酒すると、数時間から数日で手指振戦、発汗、不眠、けいれん、振戦せん妄といった離脱症状をきたす。交叉耐性のあるベンゾジアゼピン系薬剤を投与して離脱症状を抑え、漸減する。

出典：厚生労働省ホームページ 第118回医師国家試験 A030',
     '{"A": "抗酒薬は離脱期を脱して断酒を維持する段階で用いる。離脱症状の治療薬ではない。", "B": "レボドパはParkinson病の治療薬で、アルコール離脱の振戦には無効である。", "D": "アセチルコリンエステラーゼ阻害薬はAlzheimer型認知症の治療薬である。", "E": "SSRIはうつ病や不安障害に用いるもので、離脱症状には即効性がない。"}'),
    ('118-A-31', '正答は E「臨床工学技士」。

臨床工学技士は生命維持管理装置の操作と保守を担う。人工呼吸器を要さない誤嚥性肺炎の治療サポートでは出番がない。

出典：厚生労働省ホームページ 第118回医師国家試験 A031',
     '{"A": "体重46kgと低栄養があり、管理栄養士が栄養管理と食形態の調整に関わる。", "B": "むせがあり嚥下障害の評価と嚥下訓練を言語聴覚士が担う。", "C": "う歯があり口腔内が乾燥しており、口腔ケアで誤嚥性肺炎を防ぐために歯科衛生士が関わる。", "D": "左不全片麻痺があり、廃用を防ぐ運動療法と排痰の援助を理学療法士が担う。"}'),
    ('118-A-32', '正答は A「血漿交換」。

汎血球減少と骨髄の著明な低形成から再生不良性貧血である。血漿交換は血漿中の病因物質を除く治療で、造血幹細胞の減少という病態には効かず適応にならない。

出典：厚生労働省ホームページ 第118回医師国家試験 A032',
     '{"B": "Hb5.4g/dLの高度貧血に対し、症状に応じて赤血球輸血を行う。", "C": "抗胸腺細胞グロブリンとシクロスポリンによる免疫抑制療法が重症例の標準治療である。", "D": "トロンボポエチン受容体作動薬は造血の回復を促す薬剤として免疫抑制療法に併用される。", "E": "好中球360/μLと減少しており、感染症を合併すればG-CSFを用いる。"}'),
    ('118-A-35', '正答は E「直接作用型抗ウイルス薬〈direct acting antivirals〉」。

HCV抗体陽性かつHCV-RNA陽性でC型慢性肝炎である。現在の第一選択は直接作用型抗ウイルス薬で、8〜12週の内服により95%以上でウイルスが排除される。

出典：厚生労働省ホームページ 第118回医師国家試験 A035',
     '{"A": "インターフェロンは有害事象が多く、直接作用型抗ウイルス薬に置き換わった。", "B": "核酸アナログ製剤はB型肝炎の治療薬である。HBs抗原は陰性である。", "C": "グルココルチコイドは自己免疫性肝炎に用いる。ウイルスを増やす危険がある。", "D": "ウルソデオキシコール酸は原発性胆汁性胆管炎などに用いる肝庇護薬で、ウイルスは排除できない。"}'),
    ('118-A-36', '正答は C「グルコン酸カルシウム」。

腎機能低下に果物の多食が重なり、K6.7mEq/Lの高カリウム血症で心電図にテント状T波が出ている。致死性不整脈を防ぐため、まずグルコン酸カルシウムを静注して心筋の膜を安定化させ、続いてグルコース・インスリン療法や透析でカリウムを下げる。

出典：厚生労働省ホームページ 第118回医師国家試験 A036',
     '{"A": "SGLT2阻害薬は血糖を下げるが、この状況で緊急に投与する薬ではない。", "B": "アルブミン製剤は体液過剰と肺うっ血を悪化させる。", "D": "エリスロポエチン製剤は腎性貧血に用いるもので、効果が出るまで数週かかる。", "E": "アンジオテンシン受容体拮抗薬は高カリウム血症をさらに悪化させるため、この時点では禁忌である。"}'),
    ('118-A-37', '正答は A「筋膜切開」。

上腕骨顆上骨折後に前腕の著明な腫脹、他動伸展での激痛、橈骨動脈拍動の消失がそろっており急性コンパートメント症候群である。ただちに筋膜切開で内圧を下げないとVolkmann拘縮を残す。

出典：厚生労働省ホームページ 第118回医師国家試験 A037',
     '{"B": "牽引では区画内圧は下がらず、対応が遅れる。", "C": "ギプス固定はむしろ内圧を高めて悪化させる。", "D": "他動伸展で激痛があり、可動域訓練は不適切である。", "E": "骨折の固定より先に区画内圧の解除が要る。"}'),
    ('118-A-40', '正答は A「乳癌」。

皮膚の陥凹(えくぼ徴候)を伴う硬い腫瘤に、マンモグラフィでスピキュラを伴う腫瘤陰影と多形性の微細石灰化を認めており乳癌である。針生検で組織型とサブタイプを確かめて治療方針を決める。

出典：厚生労働省ホームページ 第118回医師国家試験 A040',
     '{"B": "乳腺症は月経周期に伴う疼痛と硬結が主で、スピキュラや多形性微細石灰化は伴わない。", "C": "葉状腫瘍は急速に増大する境界明瞭な腫瘤で、皮膚陥凹やスピキュラは示さない。", "D": "慢性乳腺炎では発赤と圧痛を伴う炎症所見が前面に出る。", "E": "乳腺線維腺腫は若年者に多い可動性良好な境界明瞭腫瘤である。"}'),
    ('118-A-43', '正答は E「副腎皮質ステロイド点鼻」。

季節性の症状で鼻汁好酸球陽性、スギ花粉の飛散期に増悪しており季節性アレルギー性鼻炎である。鼻噴霧用の副腎皮質ステロイドは鼻閉を含むすべての症状に有効で、効果の発現も早い。

出典：厚生労働省ホームページ 第118回医師国家試験 A043',
     '{"A": "細菌感染ではなく、抗菌薬の適応はない。", "B": "減感作療法(アレルゲン免疫療法)は数年かけて行うもので、今すぐの改善にはつながらない。", "C": "免疫抑制薬を用いる病態ではない。", "D": "鼻内レーザー手術は薬物療法で改善しない鼻閉に対して、花粉飛散前に行うものである。"}'),
    ('118-A-44', '正答は A「C3低下」。

先行する咽頭炎から2週間後に血尿・蛋白尿、浮腫、高血圧が現れており急性糸球体腎炎(A群β溶血性連鎖球菌感染後)である。免疫複合体による補体の消費を反映して血清C3が低下し、6〜8週で回復する。

出典：厚生労働省ホームページ 第118回医師国家試験 A044',
     '{"B": "IgE高値はアレルギー疾患や寄生虫感染でみられ、本症の所見ではない。", "C": "M蛋白は多発性骨髄腫などで検出される。", "D": "抗核抗体陽性はループス腎炎を示唆するが、顔面皮疹もなく先行感染との時間関係が典型的である。", "E": "抗リン脂質抗体は血栓症と関連し、本症の所見ではない。"}'),
    ('118-A-47', '正答は E「レム〈REM〉睡眠行動障害」。

睡眠後半に夢の内容に一致した行動が現れ、覚醒すると夢を記憶している。筋強剛と認知機能低下も伴っており、レム睡眠行動障害である。Parkinson病やLewy小体型認知症に先行する徴候として重要である。

出典：厚生労働省ホームページ 第118回医師国家試験 A047',
     '{"A": "夜間せん妄では意識が混濁し、日中の記憶も断片的で、夢として想起されない。", "B": "睡眠時遊行症はノンレム睡眠中に生じ、本人は出来事を覚えていない。小児に多い。", "C": "ナルコレプシーは日中の耐えがたい眠気と情動脱力発作が主症状である。日中の異常はない。", "D": "むずむず脚症候群は入眠時の下肢の不快感と動かしたい衝動が主症状である。"}'),
    ('118-A-53', '正答は D「乳房超音波検査」。

マンモグラフィで腫瘤を指摘され触知もできる。次に行うのは乳房超音波検査で、腫瘤の性状を評価し、その場で針生検の穿刺誘導にも使える。乳癌の診断は視触診・画像・病理の三者で進める。

出典：厚生労働省ホームページ 第118回医師国家試験 A053',
     '{"A": "頭部MRIは転移の検索であり、診断が確定する前に行うものではない。", "B": "乳房MRIは広がり診断に用いるもので、まず行う検査ではない。", "C": "胸部造影CTも病期診断の段階の検査である。", "E": "骨シンチグラフィは骨転移の検索で、確定診断の後に必要に応じて行う。"}'),
    ('118-A-55', '正答は A「結核性髄膜炎」。

亜急性に進む頭痛と発熱、意識障害に脳神経麻痺(外転神経・顔面神経)を伴い、脳脊髄液は単核球優位の細胞増多、糖の低下、蛋白の上昇、ADA上昇を示しており結核性髄膜炎である。頭蓋底の癒着性炎症が脳神経麻痺を招く。

出典：厚生労働省ホームページ 第118回医師国家試験 A055',
     '{"B": "重症筋無力症は日内変動する眼瞼下垂や複視が主で、発熱や髄液異常は伴わない。", "C": "正常圧水頭症は歩行障害・認知機能低下・尿失禁が三徴で、CTで脳室拡大を認めるが本例では認めない。", "D": "多発性硬化症では髄液の糖は低下しない。", "E": "Bell麻痺は末梢性顔面神経麻痺のみで、髄膜刺激徴候や意識障害を伴わない。"}'),
    ('118-A-58', '正答は C「「専門の病院に紹介しましょう」」。

生後1か月で哺乳力が低下し、舌の線維束攣縮、弱い泣き声、腹式呼吸(奇異呼吸)、四肢の筋力低下を認めており脊髄性筋萎縮症I型が疑われる。治療可能な時期が限られるため、速やかに専門施設へ紹介する。

出典：厚生労働省ホームページ 第118回医師国家試験 A058',
     '{"A": "哺乳に時間がかかるのは栄養の種類ではなく筋力の問題であり、人工乳にしても解決しない。", "B": "感冒を示す所見はない。", "D": "進行性の疾患であり、1か月の経過観察は許されない。", "E": "うつ伏せ寝は乳幼児突然死症候群の危険因子であり、勧めてはならない。"}'),
    ('118-A-59', '正答は A「尿素呼気試験」。

血小板のみが減少し、他の血球と凝固に異常なく、骨髄で巨核球はむしろ増えており免疫性血小板減少性紫斑病である。Helicobacter pylori感染があれば除菌で血小板が回復する例があるため、尿素呼気試験で感染の有無を確かめて治療方針を決める。

出典：厚生労働省ホームページ 第118回医師国家試験 A059',
     '{"B": "血小板凝集能検査は血小板無力症など機能異常を疑うときの検査で、数の減少の評価には用いない。", "C": "抗リン脂質抗体は血栓症の評価に用いる。出血傾向の本例では治療方針を左右しない。", "D": "HLA検査は輸血不応や移植の適合性をみるためのもので、初期の治療方針決定には要らない。", "E": "抗ADAMTS-13抗体は血栓性血小板減少性紫斑病で調べる。溶血性貧血や腎障害、神経症状を欠く本例では考えにくい。"}'),
    ('118-A-60', '正答は B「眼底検査」。

血圧228/132mmHgに腎機能障害と低カリウム血症を伴い、高血圧緊急症が疑われる。眼底で乳頭浮腫や軟性白斑・出血があれば臓器障害が進行していることになり、降圧の速度と目標を決める判断材料になる。

出典：厚生労働省ホームページ 第118回医師国家試験 A060',
     '{"A": "神経診察に異常がなく、頭蓋内病変を疑う所見はない。", "C": "29歳で頸動脈の動脈硬化を評価する意義は乏しい。", "D": "腹部エックス線撮影で得られる情報はほとんどない。", "E": "足関節上腕血圧比は末梢動脈疾患の評価で、緊急の降圧方針を左右しない。"}'),
    ('118-A-62', '正答は A「West症候群」。

生後7か月で、両上肢を挙上し頭部を前屈する動作が数秒〜十数秒間隔で反復し(シリーズ形成)、同時に発達の退行がみられており West症候群(点頭てんかん)である。脳波でヒプスアリスミアを確認し、ビガバトリンやACTH療法を行う。

出典：厚生労働省ホームページ 第118回医師国家試験 A062',
     '{"B": "欠神てんかんは学童期に始まる数秒の意識消失発作で、発達の退行は伴わない。", "C": "Lennox-Gastaut症候群は幼児期以降に多彩な発作型で発症し、West症候群から移行することがある。", "D": "先天性筋強直性ジストロフィーは出生時からの筋緊張低下と哺乳障害が主で、発作性の動作ではない。", "E": "福山型先天性筋ジストロフィーも筋力低下と精神運動発達遅滞が主体で、シリーズ形成する発作は特徴でない。"}'),
    ('118-A-63', '正答は E「カタル期には核酸増幅検査が診断に有用である。」。

百日咳のカタル期は感冒と区別しにくいが、菌量が多く感染力も強い時期で、核酸増幅検査(LAMP法など)の感度が高い。培養と抗体価は時期や日数の制約が大きく、早期診断には核酸増幅検査が有用である。

出典：厚生労働省ホームページ 第118回医師国家試験 A063',
     '{"A": "百日咳は飛沫感染で、空気(飛沫核)感染はしない。", "B": "潜伏期は7〜10日程度で、2、3日ではない。", "C": "痙咳期に聴かれるのは、発作性の咳の後に息を吸い込むときの笛声(吸気性のwhoop)である。呼気喘鳴ではない。", "D": "百日咳菌にセフェム系は無効で、マクロライド系が第一選択である。"}'),
    ('118-A-64', '正答は B「2」。

尿中ナトリウムが10mEq/Lと低いことは、尿細管でナトリウムを最大限に再吸収していることを示し、腎前性の急性腎障害を裏づける。腎性であれば尿細管が障害されて再吸収できず、尿中ナトリウムは高くなる。

出典：厚生労働省ホームページ 第118回医師国家試験 A064',
     '{"A": "尿量の減少は急性腎障害そのものを示す所見で、原因の鑑別には役立たない。", "C": "Hb10.0g/dLの貧血は原因の鑑別に結びつかない。", "D": "クレアチニンの上昇は腎障害があることを示すだけで、原因の区別はできない。", "E": "高カリウム血症は腎機能低下の結果であり、これも原因の鑑別にはならない。"}'),
    ('118-A-65', '正答は E「立ち上がり・立位保持訓練」。

端座位はほぼ自立しているが、立ち上がりと立位保持には中等度の介助を要する。到達している段階の一つ先に目標を置くのが原則で、立ち上がりと立位保持の訓練を行う。

出典：厚生労働省ホームページ 第118回医師国家試験 A065',
     '{"A": "立位が保てない段階で歩行訓練には進めない。", "B": "端座位はすでにほぼ自立しており、座位訓練は目標として低すぎる。", "C": "階段昇降は歩行が安定してから取り組む段階である。", "D": "右上肢は肘屈曲1、手指伸展0で、書字ができる筋力ではない。利き手交換はもっと先の課題である。"}'),
    ('118-A-66', '正答は D「呼吸筋麻痺」。

上位運動ニューロン徴候(腱反射亢進、Babinski徴候陽性)と下位運動ニューロン徴候(筋萎縮、線維束性収縮)が併存し、感覚は正常で眼球運動も保たれており筋萎縮性側索硬化症である。進行すると呼吸筋が麻痺し、呼吸不全が予後を規定する。

出典：厚生労働省ホームページ 第118回医師国家試験 A066',
     '{"A": "褥瘡は陰性四徴の一つで、末期まで生じにくいとされる。", "B": "眼球運動障害も陰性四徴の一つで、複視はきたしにくい。", "C": "膀胱直腸障害も陰性四徴に含まれ、排尿障害は生じにくい。", "E": "自律神経は比較的保たれ、起立性低血圧は特徴的でない。"}'),
    ('118-B-1', '正答は D「薬剤師」。

採血(静脈路からの採血を含む)は診療の補助として、看護師・准看護師・保健師・助産師と臨床検査技師が医師の指示のもとで行える。薬剤師の業務は調剤と服薬指導であり、採血は含まれない。

出典：厚生労働省ホームページ 第118回医師国家試験 B001',
     '{"A": "看護師は診療の補助として採血できる。", "B": "助産師も看護師の業務を行えるので採血できる。", "C": "保健師も同様に採血できる。", "E": "臨床検査技師は法令上、採血が明記された業務である。"}'),
    ('118-B-2', '正答は E「前立腺は、直腸指診で腹側に触知する。」。

前立腺は直腸の腹側(前方)にあるため、直腸指診で指の腹側に触れる。大きさ、硬さ、表面の性状、圧痛を確かめる。

出典：厚生労働省ホームページ 第118回医師国家試験 B002',
     '{"A": "肝は深吸気時に下降した下縁を触知する。裏面を触れることはできない。", "B": "膵は後腹膜の深部にあり、健常者では触知できない。", "C": "腎は深吸気時に下降した下極を触れることがある。上極は触れない。", "D": "膀胱は恥骨結合の背側、直腸の腹側にあり、直腸指診では指の腹側に触れる。"}'),
    ('118-B-3', '正答は D「熱性けいれん」。

熱性けいれんは生後6か月から5歳ごろに好発し、有熱時けいれんの大半を占める。2歳児のけいれんの原因として最も頻度が高い。

出典：厚生労働省ホームページ 第118回医師国家試験 B003',
     '{"A": "急性脳症は熱性けいれんに比べてはるかにまれである。", "B": "てんかんの有病率は約1%で、この年齢のけいれんの主因ではない。", "C": "細菌性髄膜炎はワクチンの普及で著減しており、頻度は低い。", "E": "憤怒けいれんは啼泣に伴う無熱性のもので、熱性けいれんより頻度が低い。"}'),
    ('118-B-4', '正答は E「Courvoisier徴候陽性」。

Courvoisier徴候は無痛性に腫大した胆囊を触れる所見で、膵頭部癌など遠位胆管の悪性閉塞を示唆する。腹膜炎の所見ではない。

出典：厚生労働省ホームページ 第118回医師国家試験 B004',
     '{"A": "反跳痛(Blumberg徴候)は腹膜刺激徴候の代表である。", "B": "筋性防御は腹壁筋の反射性収縮で、腹膜炎を示す。", "C": "打診による圧痛は腹膜刺激徴候を捉える感度の高い方法である。", "D": "つま先立ちから踵を落として腹痛が誘発される踵下ろし試験は腹膜刺激徴候をみる手技である。"}'),
    ('118-B-5', '正答は E「抜去した内針はリキャップをする。」。

使用した針のリキャップは針刺し事故の主要な原因で、行ってはならない。抜いた内針はそのまま専用の耐貫通性容器に廃棄する。

出典：厚生労働省ホームページ 第118回医師国家試験 B005',
     '{"A": "刺入部の皮膚はアルコールなどで消毒し、乾いてから穿刺する。", "B": "浅い角度で刺入するのが基本で、15〜30度が目安である。", "C": "逆血を確認した時点では内針だけが血管内にあるので、少し進めてから外筒を送る。", "D": "駆血帯を外してから内針を抜くと、血液の噴出を防げる。"}'),
    ('118-B-6', '正答は B「改善策の記述を含める。」。

インシデントレポートは事実の記載にとどまらず、なぜ起きたかの分析と再発を防ぐための改善策までを含めて初めて意味をもつ。個人の責任追及ではなく仕組みの改善に用いる。

出典：厚生労働省ホームページ 第118回医師国家試験 B006',
     '{"A": "提出先は院内の医療安全管理部門であって保健所ではない。", "C": "作成するのは事象に関与した、あるいは発見した医療従事者である。", "D": "個人情報を含むため一般に公開するものではない。", "E": "報告数が少ないのは報告しにくい風土を示すことがあり、安全度の高さを意味しない。"}'),
    ('118-B-7', '正答は C「関節液」。

T2強調像では自由水を多く含む組織ほど高信号になる。関節液は水そのものなので著明な高信号を示し、関節水腫の評価に用いる。

出典：厚生労働省ホームページ 第118回医師国家試験 B007',
     '{"A": "腱は緻密な線維組織で水分に乏しく、T1・T2ともに低信号である。", "B": "靱帯も同様に低信号である。", "D": "骨皮質は可動性のプロトンがほとんどなく、無信号に近い。", "E": "半月板は線維軟骨で低信号を示し、内部に高信号が入れば断裂を疑う。"}'),
    ('118-B-8', '正答は C「副甲状腺」。

副甲状腺は米粒大で甲状腺の背側にあり、正常では触知できない。触れるほど大きくなっていれば腺腫や癌を疑う。

出典：厚生労働省ホームページ 第118回医師国家試験 B008',
     '{"A": "顎下腺は下顎角の内側で双手診により触知できる。", "B": "頸動脈は胸鎖乳突筋の内側で拍動として触知できる。", "D": "輪状軟骨は甲状軟骨の下方に輪状の隆起として触れる。", "E": "胸鎖乳突筋は頭部を対側に回旋させると明瞭に触知できる。"}'),
    ('118-B-9', '正答は E「症例対照研究よりエビデンスレベルが高い。」。

ランダム化比較試験は無作為割付により既知・未知の交絡因子が両群に均等に分かれるため、症例対照研究やコホート研究より高いエビデンスレベルに位置づけられる。

出典：厚生労働省ホームページ 第118回医師国家試験 B009',
     '{"A": "研究者が介入を割り付ける介入研究である。", "B": "適格基準を厳しく設けるため対象が限られ、結果を一般の患者に当てはめる外的妥当性はむしろ低くなりやすい。", "C": "無作為化によって未測定の交絡因子も均等に分かれるので、対応できるのが最大の利点である。", "D": "まれな疾患では必要な症例数を集めにくく、症例対照研究のほうが適している。"}'),
    ('118-B-10', '正答は E「患者の機能障害の固定を目標とする。」。

リハビリテーションは機能障害を固定させることではなく、残された機能を最大限に生かして活動と参加を高め、その人らしい生活を取り戻すことを目指す。

出典：厚生労働省ホームページ 第118回医師国家試験 B010',
     '{"A": "廃用症候群を防ぐため、全身状態が許せば早期から開始する。", "B": "就労や地域での役割を含む社会参加の支援は目標の中心にある。", "C": "国際生活機能分類でいう生活機能全体の改善を目指す。", "D": "医師、看護師、療法士、社会福祉士などが目標を共有してチームで取り組む。"}'),
    ('118-B-11', '正答は B「研究で知り得た情報を公開する権利がある。」。

患者・市民参画は研究の企画や実施に患者や市民の視点を取り入れる取組みで、参画者は研究協力者として守秘義務を負う。研究で知り得た情報を自ら公開する権利をもつわけではない。

出典：厚生労働省ホームページ 第118回医師国家試験 B011',
     '{"A": "研究テーマの設定など初期段階から対等なパートナーとして加わることが求められる。", "C": "検査の回数や来院負担など、対象者の立場からの助言が期待される。", "D": "倫理審査委員会には一般の立場を代表する委員が加わることになっている。", "E": "説明文書や同意文書が分かりやすい表現になるよう助言することは重要な役割である。"}'),
    ('118-B-14', '正答は E「慢性閉塞性肺疾患〈COPD〉」。

慢性閉塞性肺疾患の最大の危険因子は喫煙で、飲酒は危険因子とされていない。

出典：厚生労働省ホームページ 第118回医師国家試験 B014',
     '{"A": "アルコールはアセトアルデヒドを介して食道扁平上皮癌の危険を高める。", "B": "多量飲酒は認知症の危険因子として知られる。", "C": "飲酒は骨形成を妨げ、転倒も増えるため骨粗鬆症と骨折の危険因子である。", "D": "慢性のアルコール多飲によるビタミンB1欠乏がWernicke脳症を引き起こす。"}'),
    ('118-B-15', '正答は B「処方日数の短期化」。

処方日数が短くなることはポリファーマシーの原因にならない。むしろ長期処方や残薬の把握不足が薬剤の重複を招く。

出典：厚生労働省ホームページ 第118回医師国家試験 B015',
     '{"A": "複数の疾患それぞれに標準治療を積み上げると薬剤数が増える。", "C": "複数の医療機関がそれぞれ処方すれば、重複や相互作用が生じる。", "D": "自己管理能力が落ちると残薬が増え、実際の服用状況が把握できなくなる。", "E": "お薬手帳などによる情報共有が働かないと、重複処方を見つけられない。"}'),
    ('118-B-16', '正答は A「新生児」。

新生児では体重の約75〜80%が水分で、そのうち細胞外液が約40%と最も高い割合を占める。成長とともに細胞外液の割合は減り、成人では約20%になる。このため新生児・乳児は脱水に陥りやすい。

出典：厚生労働省ホームページ 第118回医師国家試験 B016',
     '{"B": "乳児では細胞外液の割合が新生児より下がる。", "C": "幼児ではさらに下がる。", "D": "学童では成人に近づく。", "E": "成人の細胞外液は体重の約20%で最も低い。"}'),
    ('118-B-17', '正答は B「感度の高い検査が陰性のとき」。

感度の高い検査が陰性であれば偽陰性が少ないので、その疾患をほぼ否定できる。逆に特異度の高い検査が陽性であれば偽陽性が少なく、確定診断に近づく。

出典：厚生労働省ホームページ 第118回医師国家試験 B017',
     '{"A": "感度の高い検査の陽性は偽陽性を多く含みうるので、確定には向かない。", "C": "特異度の高い検査の陽性は確定(rule in)に有用で、除外には使わない。", "D": "特異度の高い検査が陰性でも偽陰性が多く、除外はできない。", "E": "感度/(1−特異度)は陽性尤度比で、1より大きいことは検査後確率が上がることを示す。除外の指標ではない。"}'),
    ('118-B-19', '正答は A「「症状をあげていただけますか」」。

解釈モデルは患者が自分の病気の原因、経過、意味、望む治療をどう考えているかである。症状を列挙してもらうのは事実の情報収集であり、患者の考えを引き出す問いではない。

出典：厚生労働省ホームページ 第118回医師国家試験 B019',
     '{"B": "どんな治療が要ると考えるかは、治療への期待を尋ねる問いである。", "C": "治ったら生活がどう変わるかは、病気が生活に与える影響と期待を尋ねる問いである。", "D": "原因について思い当たることを尋ねるのは、解釈モデルの中核である。", "E": "困りごとを尋ねるのは、病気が生活に及ぼす影響を知る問いである。"}'),
    ('118-B-20', '正答は C「「盗聴器を体に埋め込まれて監視されています」」。

盗聴器を埋め込まれて監視されているという確信は、事実に反する内容を訂正できずに保持する妄想(被害妄想・注察妄想)である。

出典：厚生労働省ホームページ 第118回医師国家試験 B020',
     '{"A": "存在しない虫が見えるのは幻視である。", "B": "実際にはない声が聞こえるのは幻聴である。", "D": "腹の中で球が動くという体感の異常は体感幻覚(セネストパチー)である。", "E": "何を食べても砂のように感じるのは味覚の異常である。"}'),
    ('118-B-21', '正答は C「大量飲酒 — 肺塞栓症」。

大量飲酒で問題になるのは離脱症状、肝機能障害、麻酔薬の必要量の増加などで、肺塞栓症とは結びつかない。肺塞栓症の危険因子は長期臥床、肥満、悪性腫瘍、下肢静脈瘤などである。

出典：厚生労働省ホームページ 第118回医師国家試験 B021',
     '{"A": "喫煙は気道分泌の増加と線毛運動の低下を招き、術後無気肺や肺炎の危険を高める。正しい組合せである。", "B": "開口障害があると喉頭展開ができず、気道確保が困難になる。正しい組合せである。", "D": "抗凝固薬の継続は術中術後の止血困難につながる。正しい組合せである。", "E": "バナナ・アボカド・キウイなどで蕁麻疹が出る人はラテックスと交差反応を示す。正しい組合せである。"}'),
    ('118-B-22', '正答は B「Kernig徴候 — 髄膜炎」。

Kernig徴候は股関節と膝関節を屈曲させた状態から膝を伸展させようとすると抵抗と疼痛が生じる所見で、髄膜刺激徴候の一つである。項部硬直やBrudzinski徴候とともに髄膜炎を疑う。

出典：厚生労働省ホームページ 第118回医師国家試験 B022',
     '{"A": "えくぼ徴候は乳癌でCooper靱帯が引かれて皮膚が陥凹する所見である。", "C": "Chvostek徴候は顔面神経を叩くと顔面筋が収縮する所見で、低カルシウム血症を示す。", "D": "Blumberg徴候は反跳痛で、腹膜刺激徴候である。", "E": "Grey-Turner徴候は側腹部の皮下出血斑で、重症急性膵炎などの後腹膜出血を示す。"}'),
    ('118-B-23', '正答は D「医療の安全の確保に資することを目的とする。」。

医療事故調査制度は医療法に基づき、原因を明らかにして再発を防ぎ、医療の安全を確保することを目的とする。責任追及のための仕組みではない。

出典：厚生労働省ホームページ 第118回医師国家試験 B023',
     '{"A": "根拠法は医療法である。", "B": "警察への通報を前提とする制度ではない。異状死の届出は医師法に基づく別の手続きである。", "C": "対象は医療に起因する、または起因すると疑われる死亡のうち、管理者が予期しなかったものに限られる。", "E": "調査の状況や結果は遺族に説明することとされている。"}'),
    ('118-B-24', '正答は D「「知らない人と会うと非常に緊張する」」。

社交〈社会〉不安障害は、他人から注視され評価される場面で強い不安と身体症状が生じ、そうした場面を避けるようになる病態である。初対面の人と会うときの著しい緊張はその典型である。

出典：厚生労働省ホームページ 第118回医師国家試験 B024',
     '{"A": "閉所での恐怖は限局性恐怖症(閉所恐怖)にあたる。", "B": "世間の人々から嫌われているという確信は関係妄想や被害妄想である。", "C": "漠然と大変なことが起こる予感は全般性不安障害でみられる。", "E": "施錠の確認を何十回も繰り返すのは強迫性障害の確認強迫である。"}'),
    ('118-B-25', '正答は E「インフォームド・アセント」。

インフォームド・アセントは、同意能力が十分でない未成年者に理解力に応じた説明を行い、本人の納得(賛意)を得ることをいう。法的な同意は代諾者から得たうえで、本人の意思も尊重する。

出典：厚生労働省ホームページ 第118回医師国家試験 B025',
     '{"A": "オプトアウトは既存の資料を用いる研究などで、拒否の機会を保障して情報公開する方式である。", "B": "パターナリズムは医療者が患者に代わって決めてしまう考え方である。", "C": "リビングウィルは終末期医療についての事前の意思表示である。", "D": "セカンドオピニオンは別の医師に意見を求めることである。"}'),
    ('118-B-26', '正答は E「「薬を始めないのであれば、他の医療機関を受診していただけますか」」。

他の医療機関の受診を促すのは、治療方針に同意しないことを理由に診療関係を切ることになり、診療を拒む正当な事由にあたらない。通院を続ける意思がある以上、対話を重ねて合意点を探るべきである。

出典：厚生労働省ホームページ 第118回医師国家試験 B026',
     '{"A": "実行できる治療を患者自身に考えてもらう問いは、行動変容を促すうえで適切である。", "B": "患者が何を目標としているかを共有することは方針の擦り合わせに役立つ。", "C": "服薬を避けたい理由を聞くことは、誤解や不安の把握につながる。", "D": "このままの状態が続いた場合をどう考えているかを尋ねるのは、認識のずれを確かめる適切な問いである。"}'),
    ('118-B-27', '正答は D「睡眠を妨げる痛み」。

癌性疼痛の緩和は、まず夜間の睡眠が妨げられない状態を目指し、次に安静時の痛みの消失、最後に体動時の痛みの消失という順に段階的に目標を上げていく。本例は睡眠を妨げる痛みが主訴でもある。

出典：厚生労働省ホームページ 第118回医師国家試験 B027',
     '{"A": "歩行時の痛みは体動時痛で、最終段階の目標にあたる。", "B": "立位時の痛みも体動時痛にあたる。", "C": "階段昇降時の痛みも同様に体動時痛である。", "E": "重い荷物を持ち上げるときの痛みは負荷が最も大きく、緩和の目標として最後になる。"}'),
    ('118-B-28', '正答は D「この患者への診療をさし控える。」。

サプリメントを使いたいという申し出を理由に診療を控えることは、診療の拒否にあたり許されない。希望の背景を聴き、薬物相互作用などの情報を集めて一緒に判断するのが適切な対応である。

出典：厚生労働省ホームページ 第118回医師国家試験 B028',
     '{"A": "なぜ使いたいのかという思いを丁寧に聴くことが出発点になる。", "B": "訪問看護師や薬剤師と情報を共有して安全性を確かめる。", "C": "自費となるため、生活への負担を確認することは適切である。", "E": "成分と内服薬との相互作用について情報を集めることは医師の役割である。"}'),
    ('118-B-29', '正答は A「喀痰抗酸菌染色」。

空気感染予防策を始めるかどうかは、周囲に菌を排出しているか(排菌の有無)で決まる。喀痰抗酸菌染色(塗抹検査)は数時間で結果が出て菌量も分かるので、隔離の判断に直結する。

出典：厚生労働省ホームページ 第118回医師国家試験 B029',
     '{"B": "培養は結果が出るまで数週間かかり、隔離の判断には間に合わない。", "C": "ツベルクリン反応は感染の既往をみるもので、排菌の有無は分からない。生物学的製剤の使用下では偽陰性にもなる。", "D": "気管支肺胞洗浄は侵襲が大きく、まず喀痰で調べる。", "E": "IGRAも感染の有無をみる検査で、活動性や排菌の判断はできない。"}'),
    ('118-B-30', '正答は C「「どうすれば体重を減らせると思いますか」」。

減量したい気持ちはあるが、仕事の忙しさを理由に行動に移せていない関心期である。具体的な指示を与えるより、どうすればできそうかを本人に考えてもらい、障壁を一緒に整理することが有効である。

出典：厚生労働省ホームページ 第118回医師国家試験 B030',
     '{"A": "脅すような伝え方は防衛的な反応を招き、関係を損ないやすい。", "B": "受診の継続を遠ざける声かけで、支援の機会を失う。", "D": "具体的な数値目標の設定は、行動を始める準備が整った準備期以降に適する。", "E": "運動する時間がないと述べている段階で一律の運動処方を与えても実行につながらない。"}'),
    ('118-B-31', '正答は E「5」。

毛細血管再充満時間4秒は末梢循環不全を示し、代償性ショックを疑う所見である。乳児では血圧が下がるのは代償が破綻した後なので、皮膚所見での早期認識が重要になる。

出典：厚生労働省ホームページ 第118回医師国家試験 B031',
     '{"A": "体温37.1°Cは発熱とはいえない。", "B": "心拍数120/分は1か月児として正常範囲である。", "C": "血圧80/50mmHgもこの月齢で保たれている値である。", "D": "呼吸数36/分も1か月児では正常範囲である。"}'),
    ('118-B-32', '正答は E「「転倒に気をつけて片足立ちやスクワットをしましょう」」。

歩行距離が短くなりつまずきが増えており、ロコモティブシンドロームの段階にある。片脚立ちとスクワットは下肢筋力とバランスを鍛えるロコモーショントレーニングの中心で、転倒に注意しながら続けるよう勧める。

出典：厚生労働省ホームページ 第118回医師国家試験 B032',
     '{"A": "ビール350mLを週3回は節度ある適度な飲酒の範囲内で、禁酒を求める根拠はない。", "B": "外出を控えれば活動量が落ちてさらに運動機能が低下する。", "C": "BMI24.4は肥満ではなく、高齢者では過度の減量が筋肉量の減少を招く。", "D": "腰痛に対する長期の安静はかえって回復を遅らせる。動ける範囲で活動を保つのがよい。"}'),
    ('118-B-33', '正答は E「胃管を55cmまで挿入し胸部エックス線写真で胃管先端が胃内にあることを確認し再開する。」。

胃管が30cm抜けており、入れ直した後は先端が胃内にあることを確かめてから注入する。最も確実なのは胸部エックス線写真での確認で、気管内への誤挿入を見逃さない。

出典：厚生労働省ホームページ 第118回医師国家試験 B033',
     '{"A": "先端の位置が分からないまま注入すれば、気道に流入して致死的になる。", "B": "挿入長だけでは食道内や気管内にあることを否定できない。", "C": "空気注入音の聴取は気管内にあっても聞こえることがあり、確認法として不確実である。", "D": "水の注入は、気管内にあれば誤嚥そのものになる。"}'),
    ('118-B-35', '正答は A「胸腔穿刺」。

胸部強打後に、患側の胸郭膨隆・鼓音・呼吸音減弱に加えて頸静脈怒張と血圧低下がそろっており緊張性気胸である。画像を待たずにただちに胸腔穿刺で脱気し、続いて胸腔ドレーンを留置する。

出典：厚生労働省ホームページ 第118回医師国家試験 B035',
     '{"B": "低体温療法は心停止後の脳保護に用いるもので、この状況の治療ではない。", "C": "浸透圧利尿薬は脳浮腫に用いる。頭蓋内圧亢進を示す所見はない。", "D": "閉塞性ショックであり、大量輸液では静脈還流の障害は解除できない。", "E": "陽圧換気は胸腔内圧をさらに高め、緊張性気胸を悪化させる。"}'),
    ('118-B-37', '正答は D「ペニシリン系薬」。

パートナーに無痛性の陰茎潰瘍(初期硬結)の治療歴があり、本人には手掌・足底の紅斑丘疹と無痛性のリンパ節腫脹がみられる。第2期梅毒であり、治療の第一選択はペニシリン系薬である。

出典：厚生労働省ホームページ 第118回医師国家試験 B037',
     '{"A": "真菌感染ではない。", "B": "細菌(スピロヘータ)による感染であり、抗ウイルス薬は無効である。", "C": "セフェム系は梅毒の標準治療薬ではない。", "E": "カルバペネム系も適応ではない。ペニシリンアレルギーがある場合はドキシサイクリンなどを用いる。"}'),
    ('118-B-38', '正答は E「5」。

参加制約は、生活・人生の場面に関わるときに生じる困難である。趣味の俳句教室に通えなくなり家に閉じこもりがちになっていることが、社会参加が妨げられている状態にあたる。

出典：厚生労働省ホームページ 第118回医師国家試験 B038',
     '{"A": "マンションに一人暮らしという住環境は環境因子にあたる。", "B": "長距離を歩けないことは活動制限にあたる。", "C": "おしゃべり好きという性格は個人因子にあたる。", "D": "入口の階段という物理的な障壁は環境因子にあたる。"}'),
    ('118-B-39', '正答は D「腹部超音波検査」。

高度の蛋白尿と低アルブミン血症、高コレステロール血症、浮腫がそろいネフローゼ症候群である。血液が濃縮し(Ht55%)腎機能も悪化しており、腎静脈血栓症の合併を疑って、まず侵襲のない腹部超音波検査で腎の大きさと血流を評価する。

出典：厚生労働省ホームページ 第118回医師国家試験 B039',
     '{"A": "膀胱鏡検査は肉眼的血尿の原因検索に用いる。潜血は陰性である。", "B": "レノグラムは分腎機能の評価で、初期評価としての優先度は低い。", "C": "クレアチニン1.9mg/dLと腎機能が低下しており、造影剤の使用は慎重を要する。", "E": "腹部エックス線撮影で得られる情報はほとんどない。"}'),
    ('118-B-40', '正答は C「血小板数」。

妊娠32週の高血圧に、頭痛・眼華閃発・心窩部痛という中枢神経症状と肝被膜伸展の症状が加わっており、HELLP症候群を含む重症の妊娠高血圧腎症である。溶血、肝酵素上昇、血小板減少が三徴で、低下するのは血小板数である。

出典：厚生労働省ホームページ 第118回医師国家試験 B040',
     '{"A": "溶血を反映してLDは上昇する。", "B": "肝細胞障害によりASTは上昇する。", "D": "溶血が進めばヘマトクリットは下がりうるが、血管透過性亢進による血液濃縮で上昇することも多く、必発の低下所見ではない。", "E": "腎障害の進行により尿蛋白/クレアチニン比は上昇する。"}'),
    ('118-B-41', '正答は E「固定姿勢保持困難〈asterixis〉」。

黄疸、くも状血管拡張、手掌紅斑、脾腫、血小板減少と、慢性肝疾患の像が揃い、アンモニアが著明に高い。便秘を契機とした肝性脳症で、手関節を背屈させて保つと不規則に落ちる固定姿勢保持困難があらわれる。

出典：厚生労働省ホームページ 第118回医師国家試験 B041',
     '{"A": "筋強剛はParkinson症候群でみる所見で、代謝性脳症の徴候ではない。", "B": "企図振戦は小脳障害の所見である。", "C": "項部硬直は髄膜刺激徴候で、髄膜炎やくも膜下出血を示す。", "D": "Barré徴候は軽度の錐体路性筋力低下をみるものである。"}'),
    ('118-B-42', '正答は E「分岐鎖アミノ酸製剤の点滴静注」。

肝性脳症では血中の芳香族アミノ酸が相対的に増えて偽性神経伝達物質となる。分岐鎖アミノ酸製剤を補ってこの比を戻し、あわせて誘因である便秘を合成二糖類で解消する。

出典：厚生労働省ホームページ 第118回医師国家試験 B042',
     '{"A": "PT-INRは基準内で凝固異常がなく、新鮮凍結血漿の適応がない。", "B": "血糖は保たれており、低血糖の治療は要らない。", "C": "脱水を示す所見がなく、生理食塩水だけでは脳症は改善しない。", "D": "腹水や循環動態の破綻はなく、アルブミンを入れても脳症は良くならない。"}'),
    ('118-B-43', '正答は A「気管挿管」。

接触時から意識が急速に悪化し、舌根が沈下していびき様の呼吸をしている。瞳孔不同と左不全片麻痺があり、右側の頭蓋内血腫による切迫脳ヘルニアを疑う。低酸素と高二酸化炭素血症は脳を二重に痛めるので、まず気管挿管で気道を確保する。

出典：厚生労働省ホームページ 第118回医師国家試験 B043',
     '{"B": "呼吸音に左右差がなく、気胸を示す所見がない。", "C": "心拍数は保たれており、ペーシングの適応となる徐脈ではない。", "D": "脳室ドレナージは画像で病変を確かめてからの手技で、気道確保より先には来ない。", "E": "迅速簡易超音波検査でも異常がなく、この場面で優先する処置ではない。"}'),
    ('118-B-47', '正答は C「③」。

根治的化学放射線療法は費用がかさむが、高額療養費制度で月ごとの自己負担に上限が設けられる。限度額適用認定証を先に受け取れば窓口での支払いも抑えられる。

出典：厚生労働省ホームページ 第118回医師国家試験 B047',
     '{"A": "介護保険は65歳以上、または40歳以上で特定疾病に該当する場合に使う。この年齢では対象外である。", "B": "生活保護は収入と資産の要件があり、休職中というだけで直ちに該当するものではない。", "D": "指定難病医療費助成の対象は国が定める難病で、肺癌は含まれない。", "E": "ひとり親家庭等医療費助成は、妻と同居している本例には当たらない。"}'),
    ('118-B-48', '正答は E「医療ソーシャルワーカー」。

医療ソーシャルワーカーは、療養中の経済的・社会的な問題の相談に応じ、使える制度につなぐ職種である。休職と治療費への不安を抱えるこの患者に、制度の説明を依頼するのに最も適している。

出典：厚生労働省ホームページ 第118回医師国家試験 B048',
     '{"A": "看護師の役割は療養上の世話と診療の補助で、制度の説明を主に担う職種ではない。", "B": "公認心理師は心理的な支援を担う。", "C": "介護支援専門員は介護保険のケアプランを作る職種で、この年齢では介護保険の対象にならない。", "D": "精神保健福祉士は精神障害のある人の社会復帰支援が中心である。"}'),
    ('118-B-49', '正答は A「多尿」。

血清カルシウムが著明に高く、高カルシウム血症である。腎の尿濃縮力が落ちて多尿となり、そこから脱水が進んで意識障害に至る。食欲不振と傾眠も高カルシウム血症で説明できる。

出典：厚生労働省ホームページ 第118回医師国家試験 B049',
     '{"B": "テタニーは低カルシウム血症の症候で、逆である。", "C": "Barré徴候は錐体路障害をみるもので、電解質異常の所見ではない。", "D": "Trousseau徴候も低カルシウム血症でみられる。", "E": "固定姿勢保持困難は肝性脳症など代謝性脳症でみる所見で、アンモニアの上昇を伴う。"}'),
    ('118-B-50', '正答は A「生理食塩液」。

高カルシウム血症では多尿による脱水が進み、脱水そのものがカルシウムの排泄をさらに妨げる。まず生理食塩液を十分に入れて循環血漿量を戻し、尿からのカルシウム排泄を促す。

出典：厚生労働省ホームページ 第118回医師国家試験 B050',
     '{"B": "点滴用蒸留水をそのまま入れると溶血を起こす。単独では投与しない。", "C": "低血糖ではなく、ブドウ糖液の適応がない。", "D": "炭酸水素ナトリウムはアシドーシスの補正に用いるもので、この病態の初期治療にはならない。", "E": "グルコン酸カルシウムはカルシウムをさらに上げてしまい、逆効果である。"}'),
    ('118-C-1', '正答は D「コレステロール塞栓症」。

コレステロール塞栓症は、カテーテル操作や抗凝固療法を契機に粥腫のコレステロール結晶が末梢へ飛び、網状皮斑や足趾のチアノーゼ、腎機能低下をきたす。異物反応として好酸球増加と低補体血症を伴う。

出典：厚生労働省ホームページ 第118回医師国家試験 C001',
     '{"A": "IgA腎症はIgAを含む免疫複合体の沈着による糸球体腎炎で、好酸球は増えない。", "B": "遺伝性血管性浮腫はC1インヒビターの欠損によるもので、好酸球増加を伴わない。", "C": "抗リン脂質抗体症候群は血栓症と習慣流産をきたす病態で、好酸球増加は特徴でない。", "E": "多発血管炎性肉芽腫症は好中球とPR3-ANCAが関与する。好酸球が増えるのは好酸球性多発血管炎性肉芽腫症である。"}'),
    ('118-C-2', '正答は E「気持ちの辛さについて優先順位をつけて対応する。」。

終末期の苦痛は身体・精神・社会・スピリチュアルにわたり、すべてに同時に対応することはできない。患者が今いちばん辛いと感じていることを聴き取り、優先順位をつけて対応する。

出典：厚生労働省ホームページ 第118回医師国家試験 C002',
     '{"A": "不安や気持ちの辛さは医師から尋ねなければ語られないことが多い。", "B": "耐えるよう促すことは苦痛の否認であり、孤立を深める。", "C": "希死念慮の話題を制止すると、大切な訴えを聴く機会を失う。安全を確かめながら傾聴する。", "D": "過去の思い出を語ることは人生の意味を確かめる作業(ライフレビュー)であり、真剣に聴く。"}'),
    ('118-C-3', '正答は E「ヘマトクリット値」。

妊娠末期には循環血漿量が約50%増えるのに対し赤血球量の増加は約20〜30%にとどまるため、相対的に希釈されてヘマトクリット値とヘモグロビン濃度が低下する(妊娠性貧血)。

出典：厚生労働省ホームページ 第118回医師国家試験 C003',
     '{"A": "心拍出量の増加に伴い心拍数は10〜20/分増える。", "B": "白血球数は妊娠中に増加する。", "C": "腎血漿流量の増加により糸球体濾過量は約50%増え、血清クレアチニンは下がる。", "D": "hPLなどの作用でインスリン抵抗性はむしろ高まる。"}'),
    ('118-C-4', '正答は A「医療法 — 無診察治療の禁止」。

無診察治療の禁止は医師法第20条に定められている。医療法が定めるのは医療提供施設の開設と管理、医療計画、医療安全の確保といった提供体制に関する事項である。

出典：厚生労働省ホームページ 第118回医師国家試験 C004',
     '{"B": "小児慢性特定疾病の医療費助成は児童福祉法に基づく。正しい組合せである。", "C": "産前産後休業は労働基準法第65条に定められている。正しい組合せである。", "D": "がん医療の均てん化の促進はがん対策基本法の基本理念である。正しい組合せである。", "E": "業務災害・通勤災害に関する保険給付は労働者災害補償保険法に基づく。正しい組合せである。"}'),
    ('118-C-6', '正答は C「脾動脈は腹腔動脈から分岐する。」。

腹腔動脈は左胃動脈、総肝動脈、脾動脈の3本に分かれる。脾動脈は膵の上縁に沿って蛇行しながら脾門に至り、途中で膵枝と短胃動脈、左胃大網動脈を出す。

出典：厚生労働省ホームページ 第118回医師国家試験 C006',
     '{"A": "総肝動脈は腹腔動脈から分かれて肝十二指腸間膜に入る。総胆管と並走するのは固有肝動脈である。", "B": "尿管に伴走するのは精巣(卵巣)動脈で、下腸間膜動脈は尿管とは走行が異なる。", "D": "Glisson鞘を通るのは門脈、肝動脈、胆管の三つ組で、肝静脈は含まれない。", "E": "門脈は上腸間膜静脈と脾静脈が合流して形成される。下腸間膜静脈は多くの場合、脾静脈に合流する。"}'),
    ('118-C-7', '正答は B「Rotor症候群」。

Rotor症候群は肝細胞における抱合型ビリルビンの排泄障害による体質性黄疸で、肝の構造は保たれ門脈圧も上がらないので脾腫はきたさない。

出典：厚生労働省ホームページ 第118回医師国家試験 C007',
     '{"A": "肝硬変では門脈圧亢進によりうっ血性の脾腫をきたす。", "C": "日本住血吸虫症では虫卵が門脈枝に詰まって肝の線維化と門脈圧亢進を招く。", "D": "Budd-Chiari症候群は肝静脈の閉塞により肝うっ血と門脈圧亢進をきたす。", "E": "特発性門脈圧亢進症は肝硬変がないのに門脈圧が上がり、著明な脾腫をきたす。"}'),
    ('118-C-8', '正答は D「Raynaud現象」。

チェーンソーや削岩機などの振動工具を長く使うと、手指の細動脈が攣縮して白く変色するRaynaud現象(白ろう病)を生じる。末梢神経障害や骨関節障害も伴い、業務上疾病として扱われる。

出典：厚生労働省ホームページ 第118回医師国家試験 C008',
     '{"A": "Gottron徴候は皮膚筋炎で手指関節背面に生じる紅斑である。", "B": "Heberden結節は遠位指節間関節の変形性関節症による骨性の膨隆である。", "C": "Osler結節は感染性心内膜炎でみられる指趾腹の有痛性結節である。", "E": "Romberg徴候は深部感覚障害を示す神経学的所見である。"}'),
    ('118-C-9', '正答は D「在宅勤務中の負傷は労働災害補償の対象である。」。

在宅勤務も労働であり、業務に起因して生じた負傷であれば労働災害補償の対象となる。業務との関連が認められることが要件である。

出典：厚生労働省ホームページ 第118回医師国家試験 C009',
     '{"A": "在宅勤務は労使の取決めによるもので、労働者に権利として保障されているものではない。", "B": "在宅勤務でも事業者には健康診断を実施する義務があり、労働者にも受診義務がある。", "C": "労働時間の管理は事業者の責務で、労働者の裁量に委ねられるわけではない。", "E": "在宅勤務は以前から存在し、感染症の流行によって普及が加速したにすぎない。"}'),
    ('118-C-10', '正答は E「知的障害」。

特別支援学校の対象は、視覚障害・聴覚障害・知的障害・肢体不自由・病弱(身体虚弱を含む)の5つと定められている。知的障害はこれに含まれる。

出典：厚生労働省ホームページ 第118回医師国家試験 C010',
     '{"A": "自閉症は特別支援学級や通級による指導の対象である。", "B": "学習障害も通級による指導の対象である。", "C": "言語障害も特別支援学級や通級による指導の対象である。", "D": "情緒障害も特別支援学級や通級による指導の対象である。"}'),
    ('118-C-11', '正答は D「定期予防接種」。

定期予防接種は予防接種法に規定されている。健康増進法が定めるのは、国民の健康増進の基本方針(健康日本21)、国民健康・栄養調査、受動喫煙の防止、食事摂取基準の策定などである。

出典：厚生労働省ホームページ 第118回医師国家試験 C011',
     '{"A": "健康日本21は健康増進法に基づく基本方針として策定される。", "B": "受動喫煙の防止は健康増進法に定められ、2018年の改正で規制が強化された。", "C": "日本人の食事摂取基準は健康増進法に基づき厚生労働大臣が定める。", "E": "国民健康・栄養調査も健康増進法に基づいて毎年実施される。"}'),
    ('118-C-12', '正答は B「左橋病変」。

Babinski徴候は錐体路障害を示す。錐体路は延髄下部で交叉するので、それより上位である橋の病変では対側に徴候が出る。左橋の病変で右のBabinski徴候が陽性となる。

出典：厚生労働省ホームページ 第118回医師国家試験 C012',
     '{"A": "右大脳半球の病変では対側の左に錐体路徴候が出る。", "C": "小脳の病変では運動失調をきたすが、錐体路徴候は出ない。", "D": "頸髄では交叉を終えているので、左頸髄の病変は左に徴候を出す。", "E": "馬尾は末梢神経であり、障害されても腱反射は低下し、Babinski徴候は陰性である。"}'),
    ('118-C-13', '正答は E「「自分の考えなど取るに足らない価値のないものです」」。

自我障害は、思考や行動が自分のものであるという感覚(自我意識)が損なわれる症状である。自分の考えに価値がないという訴えは微小妄想や自責感で、うつ状態にみられるもので自我障害ではない。

出典：厚生労働省ホームページ 第118回医師国家試験 C013',
     '{"A": "他人に操られるという訴えはさせられ体験(作為体験)である。", "B": "考えを抜き取られるという訴えは思考奪取である。", "C": "自分のものでない考えが浮かぶという訴えは思考吹入である。", "D": "考えが世界に伝わるという訴えは思考伝播である。"}'),
    ('118-C-14', '正答は B「3か月で寝返りをする。」。

寝返りができるようになるのは生後5〜6か月ごろで、3か月ではまだできない。3か月で獲得するのは定頸(首のすわり)である。

出典：厚生労働省ホームページ 第118回医師国家試験 C014',
     '{"A": "Moro反射は生後4〜6か月ごろまでみられるので、1か月で認めるのは正常である。", "C": "顔にかけた布をすぐに取り除けるようになるのは生後6〜7か月ごろである。", "D": "パラシュート反射は生後8〜9か月ごろに出現し、以後生涯残る。", "E": "立位で傾けたときに足を踏み出して支えるホッピング反応は1歳前後に完成する。"}'),
    ('118-C-15', '正答は E「地域の医療従事者に対する研修」。

地域医療支援病院は、かかりつけ医からの紹介患者への医療提供、医療機器の共同利用、救急医療の提供に加えて、地域の医療従事者に対する研修の実施が承認要件とされている。都道府県知事が承認する。

出典：厚生労働省ホームページ 第118回医師国家試験 C015',
     '{"A": "高度医療技術の開発と評価は特定機能病院の要件である。", "B": "地域住民の栄養改善は保健所や市町村保健センターが担う。", "C": "高度な医療技術の開発・研究の主導も特定機能病院の役割である。", "D": "難病患者の療養生活支援は難病相談支援センターが担う。"}'),
    ('118-C-16', '正答は E「子宮頸癌」。

子宮頸癌の大部分はヒトパピローマウイルスの持続感染により生じるため、HPVワクチンの接種で発症を予防できる。定期接種の対象で、キャッチアップ接種も行われている。

出典：厚生労働省ホームページ 第118回医師国家試験 C016',
     '{"A": "胃癌のワクチンはない。予防はヘリコバクター・ピロリの除菌による。", "B": "肺癌のワクチンはない。予防は禁煙である。", "C": "白血病を予防するワクチンはない。", "D": "膀胱癌にもワクチンはない。BCGの膀胱内注入は上皮内癌の治療であって予防ではない。"}'),
    ('118-C-18', '正答は B「経済状況」。

CGA7は7項目からなる簡易版で、意欲、認知機能(復唱・遅延再生)、手段的ADL、基本的ADL(入浴・排泄)、情緒・気分を短時間で評価する。経済状況は含まれない。

出典：厚生労働省ホームページ 第118回医師国家試験 C018',
     '{"A": "外来や診察の場面での自発性から意欲を評価する項目がある。", "C": "3単語の復唱と遅延再生で認知機能を評価する。", "D": "入浴と排泄の自立度で基本的ADLを評価する。", "E": "買い物や食事の準備、金銭管理などで手段的ADLを評価する。"}'),
    ('118-C-19', '正答は B「通院が困難な患者」。

訪問診療は、疾病や傷病のために通院による療養が困難な患者に対し、計画的に医師が居宅を訪問して行う医療である。通院困難であることが要件で、疾患名や居住形態では決まらない。

出典：厚生労働省ホームページ 第118回医師国家試験 C019',
     '{"A": "認知症があっても通院できる患者は対象にならない。", "C": "独居であることは要件ではない。", "D": "胃瘻が造設されていても、通院できれば対象にならない。", "E": "急な発熱で臨時に往診するのは往診であって、計画的に訪問する訪問診療とは区別される。"}'),
    ('118-C-20', '正答は A「病院」。

職業性白内障は放射線や赤外線などへの曝露で生じる。医療機関ではエックス線透視やインターベンションに従事する職員が電離放射線に曝露するため、水晶体の等価線量限度が定められ、防護眼鏡の着用が求められる。

出典：厚生労働省ホームページ 第118回医師国家試験 C020',
     '{"B": "印刷工場で問題となるのは有機溶剤による中毒で、かつて1,2-ジクロロプロパンによる胆管癌が発生した。", "C": "縫製工場では上肢の反復作業による頸肩腕障害が問題となる。", "D": "クリーニング工場ではテトラクロロエチレンなど有機溶剤の曝露が問題となる。", "E": "コンビニエンスストアには白内障を起こす特有の曝露はない。"}'),
    ('118-C-21', '正答は A「外側半規管」。

温度眼振検査は外耳道に冷水や温水、冷風を入れて外側半規管の内リンパに対流を起こし、誘発される眼振を観察する。左右の半規管機能を個別に評価できる唯一の検査で、半規管麻痺の判定に用いる。

出典：厚生労働省ホームページ 第118回医師国家試験 C021',
     '{"B": "外有毛細胞の機能は耳音響放射で評価する。", "C": "球形囊は垂直方向の直線加速度を感じる耳石器で、前庭誘発筋電位で評価する。", "D": "後半規管の機能はhead impulse testやDix-Hallpike法で評価する。", "E": "卵形囊は水平方向の直線加速度を感じる耳石器で、眼球反対回旋などで評価する。"}'),
    ('118-C-22', '正答は A「65」。

基準集団の年齢階級別死亡率を対象集団の人口に当てはめると、期待死亡数は2,000×100/10万＋4,000×150/10万＋4,000×300/10万＝2＋6＋12＝20人となる。観察された死亡数は1＋4＋8＝13人なので、標準化死亡比は13÷20×100＝65である。

出典：厚生労働省ホームページ 第118回医師国家試験 C022',
     '{"B": "76は期待死亡数の計算を誤ったときに出る値である。", "C": "110は観察死亡数と期待死亡数を取り違えると近い値になる。", "D": "130は観察死亡数13をそのまま10倍したもので、期待死亡数で割っていない。", "E": "170は基準集団と対象集団を入れ替えて計算したときに出る値である。"}'),
    ('118-C-24', '正答は D「「治療に納得いかない場合は精神医療審査会に申し立てができます」」。

医療保護入院や措置入院の患者、その家族等は、都道府県知事に対して退院や処遇改善を請求でき、精神医療審査会が入院の必要性と処遇の妥当性を審査する。入院時にこの権利を書面で告知しなければならない。

出典：厚生労働省ホームページ 第118回医師国家試験 C024',
     '{"A": "弁護士など代理人との面会や電話は、いかなる場合も制限してはならない。", "B": "病状が改善して本人の同意が得られれば任意入院に切り替える。", "C": "入院の必要性と目的は医師が説明すべきことで、本人に考えさせるものではない。", "E": "72時間以内の退院という規定はない。72時間は応急入院の入院期間の上限である。"}'),
    ('118-C-25', '正答は D「ブロモクリプチン」。

ブロモクリプチンはドパミンD2受容体作動薬で、下垂体前葉からのプロラクチン分泌を抑えて乳汁分泌を止める。高プロラクチン血症や乳汁漏出症の治療に用いる。

出典：厚生労働省ホームページ 第118回医師国家試験 C025',
     '{"A": "スルピリドはドパミン受容体を遮断してプロラクチンを上昇させ、乳汁分泌を促す。", "B": "パロキセチンなどのSSRIも高プロラクチン血症をきたすことがある。", "C": "プレドニゾロンは乳汁分泌に直接影響しない。", "E": "メトクロプラミドもドパミン受容体遮断薬で、プロラクチンを上昇させる。"}'),
    ('118-C-26', '正答は E「Turner症候群」。

Turner症候群はX染色体が1本欠けた45,Xを典型とし、染色体数が減少する疾患である。低身長、翼状頸、外反肘、性腺発育不全を特徴とする。

出典：厚生労働省ホームページ 第118回医師国家試験 C026',
     '{"A": "Down症候群は21番染色体が3本になる(トリソミー)ため、染色体数は増える。", "B": "Klinefelter症候群は47,XXYで、性染色体が1本多い。", "C": "Marfan症候群はフィブリリン遺伝子の変異による常染色体顕性遺伝疾患で、染色体数は正常である。", "D": "Prader-Willi症候群は15番染色体長腕の父由来領域の欠失などによるもので、染色体数そのものは正常である。"}'),
    ('118-C-28', '正答は A「鶏卵1個(約50g)」。

1単位80kcalは糖尿病の食品交換表で用いられる目安で、鶏卵1個(約50g)がおよそこれに当たる。食品の量とエネルギーの対応をつかんでおくと栄養指導に役立つ。

出典：厚生労働省ホームページ 第118回医師国家試験 C028',
     '{"B": "木綿豆腐1丁(約300g)は約210kcalである。", "C": "食パン6枚切り1枚(約60g)は約150kcalである。", "D": "米飯茶碗1杯(約160g)は約250kcalである。", "E": "ビール中ジョッキ1杯(約570mL)は約230kcalである。"}'),
    ('118-C-29', '正答は E「血中ヘモグロビン値」。

ヘモグロビン濃度はアンドロゲンによる造血刺激と月経による鉄喪失の差から男性のほうが高く、基準値に性差がある。ヘマトクリット、赤血球数、血清クレアチニン、尿酸なども同様に性差をもつ。

出典：厚生労働省ホームページ 第118回医師国家試験 C029',
     '{"A": "血清カルシウム値に性差はない。", "B": "CRPの基準値にも性差は設けられていない。", "C": "動脈血酸素分圧は加齢で下がるが、性差はない。", "D": "血清アルブミン値にも性差はない。"}'),
    ('118-C-35', '正答は A「尿酸」。

尿酸結石はエックス線を透過するため、腹部単純写真で写らない。高尿酸血症(8.6mg/dL)を背景に、超音波でのみ確認できる結石という組合せが尿酸結石を示す。尿のアルカリ化で溶解が期待できる点も特徴である。

出典：厚生労働省ホームページ 第118回医師国家試験 C035',
     '{"B": "炭酸カルシウムはカルシウムを含むためエックス線写真に写る。", "C": "リン酸カルシウムも高吸収でエックス線写真に写る。", "D": "シュウ酸カルシウムは尿路結石で最も多いが、エックス線写真によく写る。", "E": "リン酸マグネシウムアンモニウム(感染結石)も写る。尿素分解菌の感染を背景に生じ、サンゴ状結石をつくる。"}'),
    ('118-C-38', '正答は A「経過観察」。

完全母乳栄養で体重増加は良好、直接ビリルビンは0.1mg/dLと上がらず間接ビリルビン優位の黄疸が続いている。母乳性黄疸であり、生後2〜3か月で自然に消退するので経過観察でよい。

出典：厚生労働省ホームページ 第118回医師国家試験 C038',
     '{"B": "交換輸血は核黄疸の危険が差し迫る著明な高ビリルビン血症に行うもので、総ビリルビン6.6mg/dLでは適応がない。", "C": "この値では光線療法も要さない。", "D": "直接ビリルビンが上がっておらず胆汁うっ滞はない。便色も問題になっていない。", "E": "母乳を中止する必要はない。母乳の利点を損なうだけである。"}'),
    ('118-C-39', '正答は B「網赤血球数」。

過多月経による鉄欠乏性貧血で、鉄剤を投与すると数日で赤芽球の産生が動き出し、1週間前後で網赤血球が増加する(網赤血球クリーゼ)。ヘモグロビンの上昇はその後に続く。

出典：厚生労働省ホームページ 第118回医師国家試験 C039',
     '{"A": "血清鉄は投与直後に上がるが、これは吸収された鉄そのものを見ているだけで治療反応の指標にならない。", "C": "ヘモグロビン値が上がり始めるのは網赤血球の増加より後で、正常化には数か月かかる。", "D": "血清フェリチンは貯蔵鉄を反映し、正常化するのは最後である。", "E": "トランスフェリン飽和度も鉄の補充を反映するが、造血の反応そのものではない。"}'),
    ('118-C-40', '正答は C「赤」。

呼びかけに反応せず、呼吸数32/分、毛細血管再充満時間3秒で、両下腿の挫滅による大量出血がある。生命の危機が差し迫っており、直ちに処置すれば救命が期待できる最優先治療群であるから赤タッグを付ける。挫滅症候群への対応も要る。

出典：厚生労働省ホームページ 第118回医師国家試験 C040',
     '{"A": "緑は歩行可能な軽症群につけるもので、この患者には当てはまらない。", "B": "黄は多少処置が遅れても生命に危険がない待機的治療群で、意識障害と大量出血がある本例は該当しない。", "D": "白いタッグを付ける区分はない。", "E": "黒は死亡または救命が極めて困難な群につける。自発呼吸があり循環も残っており、該当しない。"}'),
    ('118-C-41', '正答は C「世界保健機関〈WHO〉」。

世界保健機関は各国から集めた感染症の発生動向を公表し、診断と治療に関する技術的な指針も示している。国外で流行する感染症の情報を得るのに最も適した組織である。

出典：厚生労働省ホームページ 第118回医師国家試験 C041',
     '{"A": "入国管理局は出入国の管理を行う機関で、感染症の医学情報は扱わない。", "B": "国際協力機構は開発協力を担う機関で、感染症の発生動向の公表主体ではない。", "D": "救急医療情報センターは地域の受入れ可能な医療機関を案内する仕組みである。", "E": "地域医療支援センターは都道府県が医師の確保と配置調整を行う組織である。"}'),
    ('118-C-42', '正答は B「低体温」。

体重28kg、BMI12.8の著しいるいそうで、神経性やせ症である。飢餓に対する適応として代謝が落ち、低体温、徐脈、低血圧、産毛の増加、無月経をきたす。

出典：厚生労働省ホームページ 第118回医師国家試験 C042',
     '{"A": "摂取不足のため低血糖に傾く。高血糖は起こらない。", "C": "エストロゲン低下と低栄養により骨密度は低下する。", "D": "低栄養では低カリウム血症になりやすい。とくに嘔吐や下剤乱用があれば顕著である。", "E": "ナトリウムも低下しやすく、高ナトリウム血症は典型的でない。"}'),
    ('118-C-43', '正答は C「腹部超音波検査」。

妊娠31週で突然の下腹部痛と性器出血、板状硬に近い腹部膨満、ショックバイタルを認めており常位胎盤早期剝離が最も疑われる。ベッドサイドで直ちに行える腹部超音波検査で胎盤後血腫と胎児の状態を確認する。

出典：厚生労働省ホームページ 第118回医師国家試験 C043',
     '{"A": "意識はほぼ清明で、頭蓋内病変を疑う所見はない。", "B": "造影CTは搬送と時間を要し、ショック状態の妊婦には不適である。", "D": "子宮動脈造影は分娩後出血の止血手段で、この時点の診断手技ではない。", "E": "胎児心拍数陣痛図は並行して装着するが、母体の出血源と胎盤の状態を把握する超音波検査が優先される。"}'),
    ('118-C-44', '正答は B「2日以内は異常行動に留意する。」。

インフルエンザでは、抗ウイルス薬の使用の有無にかかわらず、発症から少なくとも2日間は突然走り出すなどの異常行動が起こりうる。保護者に対し、児を一人にしないなど転落防止の注意を促す必要がある。

出典：厚生労働省ホームページ 第118回医師国家試験 C044',
     '{"A": "学校保健安全法では、発症後5日を経過し、かつ解熱後2日(幼児は3日)を経過するまで出席停止である。", "C": "飛沫感染するため、家族と接する際もマスクを着用する。", "D": "発熱と発汗で脱水になりやすく、口渇を待たずに水分を摂る。", "E": "抗ウイルス薬が短縮する有症状期間は約1日である。"}'),
    ('118-C-45', '正答は D「妊娠高血圧腎症」。

妊娠20週以降に初めて高血圧が出現し、蛋白尿(尿蛋白/Cr比2.4g/gCr)を伴っており妊娠高血圧腎症である。胎児発育不全も伴っており、母児の状態をみながら分娩時期を決める。

出典：厚生労働省ホームページ 第118回医師国家試験 C045',
     '{"A": "妊娠高血圧は蛋白尿や臓器障害を伴わない場合の診断名である。", "B": "HELLP症候群は溶血、肝酵素上昇、血小板減少を伴う。AST15U/L、血小板18万で該当しない。", "C": "高血圧合併妊娠は妊娠前または妊娠20週までに高血圧があった場合をいう。妊娠32週までは異常がなかった。", "E": "加重型妊娠高血圧腎症は、もともとの高血圧や腎疾患に蛋白尿や臓器障害が加わった場合である。"}'),
    ('118-C-46', '正答は E「ポリソムノグラフィー」。

肥満、大きないびき、睡眠中の無呼吸、日中の眠気に加え、咽頭の視診で軟口蓋しか見えない(Mallampati分類の高度)ことから閉塞性睡眠時無呼吸を疑う。診断と重症度判定にはポリソムノグラフィーで無呼吸低呼吸指数を求める。

出典：厚生労働省ホームページ 第118回医師国家試験 C046',
     '{"A": "嚥下障害の訴えはなく、嚥下機能検査は診断に寄与しない。", "B": "気管支鏡は下気道の病変を調べる検査で、睡眠時の無呼吸は評価できない。", "C": "頭部エックス線写真(セファログラム)は顎顔面形態の評価に補助的に使うが、診断は確定できない。", "D": "発声機能検査は音声障害の評価に用いる。"}'),
    ('118-C-47', '正答は B「症状の緩和」。

肝転移と副腎転移を伴う進行肺癌で、腫瘍による上大静脈症候群をきたしている。この放射線治療は治癒を目指すものではなく、腫瘍を縮小させて上大静脈の圧排を解き、顔面と上肢の腫脹を軽くする緩和目的である。

出典：厚生労働省ホームページ 第118回医師国家試験 C047',
     '{"A": "遠隔転移がある段階で局所照射による根治は望めない。", "C": "照射野は右上肺野の腫瘤であり、肝や副腎の転移は縮小しない。", "D": "同時化学放射線療法では増感効果を狙うが、本例は症状緩和のための照射である。", "E": "放射線照射でPD-L1発現が減弱することは期待される効果ではない。"}'),
    ('118-C-48', '正答は D「高所作業の制限」。

片麻痺が残る状態では、墜落による重大災害を避けるため高所作業の制限が必要になる。産業医は、業務内容と残存する機能障害を突き合わせて就業上の配慮を意見する。

出典：厚生労働省ホームページ 第118回医師国家試験 C048',
     '{"A": "出張そのものが片麻痺で直ちに危険になるわけではない。", "B": "夜勤の制限が必要になるのは睡眠障害やてんかんなど別の事情による。", "C": "業務時間は段階的に戻すことはあっても、真っ先に考慮すべき安全上の制限ではない。", "E": "接客業務は片麻痺があっても安全に行える。"}'),
    ('118-C-49', '正答は A「インスリン」。

肥満に高血糖、高トリグリセリド血症、低HDLコレステロール血症、肝障害が重なっており、インスリン抵抗性を基盤とした病態である。空腹時の血中インスリン値からHOMA-IRを算出してインスリン抵抗性を評価する。

出典：厚生労働省ホームページ 第118回医師国家試験 C049',
     '{"B": "グルカゴンの測定はグルカゴノーマなど特殊な病態を疑うときに行う。", "C": "コルチゾールはCushing症候群を疑うときに測るが、満月様顔貌や皮膚線条などの所見がない。", "D": "成長ホルモンは先端巨大症を疑うときに測る。特徴的な身体所見がない。", "E": "遊離サイロキシンは甲状腺機能の評価で、この病態の中心ではない。"}'),
    ('118-C-51', '正答は B「限局性学習障害」。

全般的な知的発達は保たれているのに、漢字の書字だけが著しく習得できず学習に支障をきたしており限局性学習障害(書字表出の障害)である。読み書きや計算のうち特定の領域だけが際立って苦手になるのが特徴である。

出典：厚生労働省ホームページ 第118回医師国家試験 C051',
     '{"A": "知的発達障害では全般的な知的機能が低く、成績も広く振るわない。中等度の成績を保っていた本例は当てはまらない。", "C": "自閉スペクトラム症では社会的コミュニケーションの障害が中核症状だが、友人関係のトラブルはない。", "D": "注意欠如多動性障害では不注意や多動が複数の場面でみられるが、その記載がない。", "E": "発達性協調運動障害は運動のぎこちなさが主体で、漢字だけが習得できないという偏りは説明できない。"}'),
    ('118-C-52', '正答は E「予防接種」。

三次予防は、発症した疾病の悪化や合併症を防ぎ、機能を維持して社会復帰を図る段階の対策である。予防接種は疾病そのものの発生を防ぐ一次予防にあたる。

出典：厚生労働省ホームページ 第118回医師国家試験 C052',
     '{"A": "既にある腎障害と動脈硬化の進行を抑えるための禁煙は三次予防にあたる。", "B": "血圧と肝への負担を減らす禁酒も、合併症の進展を防ぐ三次予防である。", "C": "運動療法は血糖と血圧の管理を通じて合併症の進行を抑える三次予防である。", "D": "栄養療法も腎症の進行を抑える目的で行われ、三次予防にあたる。"}'),
    ('118-C-53', '正答は B「後向きコホート研究」。

過去の人事記録から曝露の有無で2群に分け、すでに起きている疾病の発生を追跡して比較している。曝露から結果へという向きはコホート研究と同じで、時間的に過去にさかのぼって行うため後向きコホート研究という。

出典：厚生労働省ホームページ 第118回医師国家試験 C053',
     '{"A": "症例対照研究は罹患者と非罹患者を先に分けて、過去の曝露を比べる。本例は曝露の有無で群を分けている。", "C": "ケースシリーズ研究は症例の記述にとどまり、比較対照を置かない。", "D": "ランダム化比較試験は研究者が曝露を無作為に割り付ける。曝露は業務によるものである。", "E": "メタ分析は既存の複数の研究結果を統合する手法である。"}'),
    ('118-C-54', '正答は B「腟分泌物鏡検」。

黄色泡沫状の帯下と腟壁の発赤から腟トリコモナス症を疑う。腟分泌物を生理食塩水で希釈して鏡検し、鞭毛で活発に運動する原虫を確認すれば診断できる。パートナーも同時に治療する。

出典：厚生労働省ホームページ 第118回医師国家試験 C054',
     '{"A": "血清TPHAは梅毒の検査で、帯下の性状から想定される病態と合わない。", "C": "コルポスコピーは子宮頸部の上皮内病変を観察する検査である。", "D": "腟壁擦過細胞診でも原虫が見つかることはあるが、鏡検のほうが迅速で確実である。", "E": "Gram染色は細菌の観察に用いる。トリコモナスは原虫で、生鮮標本の鏡検が適している。"}'),
    ('118-C-55', '正答は C「3」。

正常な分娩では、児頭は後頭部を母体腹壁側に向けて回旋し、顔は母体背中側を向く(第1回旋・第3回旋)。顔面を母体腹壁側に向ける回旋は後方後頭位で、分娩の遷延や停止を招く異常な経過である。

出典：厚生労働省ホームページ 第118回医師国家試験 C055',
     '{"A": "破水から7時間後に規則的な子宮収縮が始まるのは前期破水後の経過として異常ではない。", "B": "陣痛開始から5時間で子宮口全開大に至るのは経産婦として順調である。", "D": "肩甲は母体腹壁側(前在肩甲)が先に、次いで背中側(後在肩甲)が娩出されるのが正常である。", "E": "胎盤は児娩出後30分以内に娩出されるのが正常で、9分は問題ない。"}'),
    ('118-C-56', '正答は D「1水質基準 2環境基準」。

水道水そのものに求められるのは水道法に基づく水質基準である。公共用水域である河川に定められるのは環境基本法に基づく環境基準で、生物化学的酸素要求量はその項目に含まれる。排水基準は工場などが排出する水に課される基準である。

出典：厚生労働省ホームページ 第118回医師国家試験 C056',
     '{"A": "水道水に適用されるのは環境基準ではなく水質基準である。", "B": "許容基準は作業環境における有害物質濃度の目安を指す用語で、水道水の基準ではない。", "C": "水道水は水質基準、河川は環境基準であり、どちらも当てはまらない。", "E": "河川という公共用水域に適用されるのは環境基準で、排水基準は工場の排出口に適用される。"}'),
    ('118-C-57', '正答は D「病理解剖を行う。」。

前日まで診療を受けていた大腸癌の進行による死亡で、死因に異状はない。病死の死因や病態をさらに詳しく調べるために遺族の承諾を得て行うのは病理解剖である。

出典：厚生労働省ホームページ 第118回医師国家試験 C057',
     '{"A": "行政解剖は監察医制度のある地域で、犯罪性のない異状死体について行う。", "B": "系統解剖は医学教育のための解剖で、生前の献体の意思に基づく。", "C": "司法解剖は犯罪に関係する疑いのある死体について裁判所の令状に基づき行う。", "E": "遺族が希望しており、病理解剖という適切な手段がある。"}'),
    ('118-C-60', '正答は A「頭部造影MRI」。

肺腺癌のリンパ節再発と分かり、治療方針を決めるには全身の広がりを確かめる必要がある。腹部と骨は既に評価済みで、残るのは脳である。腺癌は脳転移をきたしやすく、造影MRIが最も感度が高い。

出典：厚生労働省ホームページ 第118回医師国家試験 C060',
     '{"B": "腹部は造影CTで評価済みで、改めてMRIを撮る理由がない。", "C": "嗄声は縦隔病変による反回神経麻痺で説明でき、頸部超音波の優先度は低い。", "D": "肺動脈造影は肺循環の評価に用いるもので、病期診断には使わない。", "E": "肺血流シンチグラフィは肺塞栓や手術前の肺機能予測に用いる。"}'),
    ('118-C-61', '正答は A「気管切開術」。

人工呼吸が2週間を超えて続き、なお長期化が見込まれる。気管切開に切り替えると鎮静を減らせて口腔ケアや喀痰の吸引がしやすくなり、喉頭の損傷や人工呼吸器関連肺炎も減らせる。

出典：厚生労働省ホームページ 第118回医師国家試験 C061',
     '{"B": "ECMOは回復が見込める病態への橋渡しで、改善しない薬剤性肺障害では適応にならない。", "C": "声門上器具は短時間の気道確保に用いるもので、長期の人工呼吸には使えない。", "D": "経鼻エアウェイは上気道の開通を保つだけで、人工呼吸の回路にはならない。", "E": "非侵襲的陽圧換気は挿管を避けたい段階の選択肢で、既に挿管を要する状態から移すものではない。"}'),
    ('118-C-64', '正答は C「腸管洗浄液を内服する。」。

下部消化管内視鏡では、腸管内に便が残っていると粘膜が見えず病変を見落とす。検査当日に腸管洗浄液を内服して、排液が透明になるまで洗い流す。

出典：厚生労働省ホームページ 第118回医師国家試験 C064',
     '{"A": "除毛は内視鏡検査には不要である。", "B": "肛門周囲の消毒も内視鏡の前処置としては行わない。", "D": "バリウムは注腸造影で使うもので、内視鏡の前に飲めば視野を妨げる。", "E": "ホルマリンの注腸は放射線性直腸炎の止血に用いる治療で、前処置ではない。"}'),
    ('118-C-67', '正答は A「低体温にする。」。

設問は「誤っている」対応を選ぶもの。外傷では低体温・アシドーシス・凝固障害が互いを悪化させる悪循環に陥る。低体温は凝固因子の働きと血小板の機能をともに落とすので、輸液を温め室温を上げて積極的に保温する。

出典：厚生労働省ホームページ 第118回医師国家試験 C067',
     '{"B": "造影剤の血管外漏出があり出血が続いている。輸血の準備は正しい。", "C": "腹腔内に遊離ガスがあり消化管損傷を伴う。抗菌薬の投与は正しい。", "D": "抗血小板薬を内服しており、凝固能の把握は正しい。", "E": "ショックの程度と酸塩基平衡をみるため、動脈血ガス分析は正しい。"}'),
    ('118-C-69', '正答は C「改訂長谷川式簡易知能評価スケール」。

物忘れの評価であり、まずは認知機能を数量化して重症度と経過を追えるようにする。改訂長谷川式簡易知能評価スケールは短時間で施行でき、外来での初回評価に適している。

出典：厚生労働省ホームページ 第118回医師国家試験 C069',
     '{"A": "Rorschachテストは人格の傾向をみる投影法の検査である。", "B": "標準型失語症検査は失語の型と重症度を調べるもので、本例に失語はない。", "D": "日本版Denver式発達スクリーニング検査は乳幼児の発達をみる検査である。", "E": "気分の落ち込みはなく趣味も楽しめており、うつ病の評価尺度を用いる場面ではない。"}'),
    ('118-C-70', '正答は A「ドネペジル」。

実際にはいない子どもが見えるという具体的な幻視と、歯車様筋強剛・小刻み歩行のパーキンソニズムが揃い、Lewy小体型認知症である。この疾患ではコリン作動性の低下が強く、ドネペジルが認知機能にも幻視にも効きやすい。

出典：厚生労働省ホームページ 第118回医師国家試験 C070',
     '{"B": "メラトニンは睡眠の問題に用いるが、睡眠障害は認めていない。", "C": "クロナゼパムはレム睡眠行動障害に使うが、睡眠中の行動異常は認めていない。", "D": "パロキセチンは抗うつ薬で、抑うつがなく、抗コリン作用が認知機能を悪化させうる。", "E": "Lewy小体型認知症は抗精神病薬に過敏で、ハロペリドールは重篤なパーキンソニズムを招く。"}'),
    ('118-C-71', '正答は B「患者より夫の意向を優先する。」。

設問は「誤っている」ものを選ぶもの。アドバンス・ケア・プランニングの中心は本人の価値観と意向である。本例は意思疎通が可能で礼節も保たれており、夫の意向を本人より優先する理由はない。

出典：厚生労働省ホームページ 第118回医師国家試験 C071',
     '{"A": "医師・看護師・介護職などが関わって支えるのは正しい。", "C": "話し合いの内容を記録に残し関係者で共有するのは正しい。", "D": "落ち着いて話せる環境を整えるのは正しい。", "E": "意思は状況によって変わるため、繰り返し確かめるのは正しい。"}'),
    ('118-C-72', '正答は A「眼球陥凹」。

血糖が著明に高く、ケトン体の上昇はわずかである。高血糖高浸透圧状態で、糖の浸透圧利尿によって激しい脱水に陥っている。眼球の落ちくぼみはその脱水を示す所見である。

出典：厚生労働省ホームページ 第118回医師国家試験 C072',
     '{"B": "手指振戦は低血糖や甲状腺機能亢進症でみる所見である。", "C": "圧痕性浮腫は体液が過剰なときの所見で、脱水とは逆である。", "D": "呼気のアセトン臭は糖尿病ケトアシドーシスの所見で、本例はケトン体の上昇がわずかである。", "E": "足の母趾基部の発赤腫脹は痛風発作の所見である。"}'),
    ('118-D-1', '正答は E「吐き気をともなう。」。

前庭神経炎は片側の前庭機能が急に脱落する病態で、強い回転性めまいと悪心・嘔吐が数日続く。蝸牛症状(難聴・耳鳴)を伴わないことがMénière病との鑑別点になる。

出典：厚生労働省ホームページ 第118回医師国家試験 D001',
     '{"A": "通常は一度きりで、反復するのは Ménière病や良性発作性頭位めまい症である。", "B": "眼振は健側向きの水平回旋性で、垂直性眼振は中枢性病変を示唆する。", "C": "頭痛は伴わない。頭痛を伴うめまいでは前庭性片頭痛や中枢性病変を考える。", "D": "難聴は伴わない。伴えばMénière病や突発性難聴を考える。"}'),
    ('118-D-2', '正答は A「エボラウイルス」。

アフリカで流行を繰り返し、体液との接触で感染し、回復後も精液中にウイルスが残存し、致死率が約50%という記述はエボラウイルス病に一致する。一類感染症に指定されている。

出典：厚生労働省ホームページ 第118回医師国家試験 D002',
     '{"B": "ジカウイルスは蚊が媒介し、致死率は低い。妊婦の感染による小頭症が問題となる。", "C": "新型コロナウイルスは飛沫・エアロゾルで伝播し、致死率は大幅に低い。", "D": "デングウイルスも蚊が媒介し、アジアや中南米で流行する。", "E": "ポリオウイルスは経口感染し、急性弛緩性麻痺をきたす。致死率は低い。"}'),
    ('118-D-3', '正答は C「無脈性心室頻拍」。

無脈性心室頻拍は心室細動とともに電気ショックの適応(ショック適応リズム)である。ただちに除細動を行い、胸骨圧迫を再開する。

出典：厚生労働省ホームページ 第118回医師国家試験 D003',
     '{"A": "心静止は電気ショックの適応ではなく、胸骨圧迫とアドレナリン投与を続ける。", "B": "心房細動そのものは心停止ではない。血行動態が破綻した場合の同期下カルディオバージョンは、心停止に対する除細動とは別である。", "D": "完全房室ブロックには経皮ペーシングやアトロピンで対応する。", "E": "無脈性電気活動もショック適応ではなく、原因の是正と胸骨圧迫を行う。"}'),
    ('118-D-4', '正答は A「男性に多い。」。

チック症は男児に多く、男女比はおよそ3〜4対1である。幼児期から学童期に始まり、多くは思春期を過ぎるころに軽快する。

出典：厚生労働省ホームページ 第118回医師国家試験 D004',
     '{"B": "好発は4〜11歳ごろで、思春期には軽快に向かうことが多い。", "C": "チックは突発的で素早い運動が特徴である。", "D": "睡眠中は軽減または消失する。", "E": "多くは成人までに軽快し、生涯続くのは一部である。"}'),
    ('118-D-5', '正答は B「外ヘルニアである。」。

鼠径ヘルニアは腹壁の外へ脱出する外ヘルニアである。腹腔内の陥凹に入り込む内ヘルニアと区別される。

出典：厚生労働省ホームページ 第118回医師国家試験 D005',
     '{"A": "成人の鼠径ヘルニアは高齢男性に多い。女性では大腿ヘルニアの割合が相対的に高くなる。", "C": "成人では下腹壁動脈の外側から脱出する外鼠径ヘルニアが最も多い。", "D": "腹膜鞘状突起の閉鎖不全は小児の外鼠径ヘルニアの原因である。成人では腹壁の脆弱化による。", "E": "開腹手術の既往は腹壁瘢痕ヘルニアの危険因子であって、鼠径ヘルニアのそれではない。"}'),
    ('118-D-6', '正答は E「尿管嵌頓結石」。

成人男性の腎盂腎炎は、女性と違って上行性感染だけで起こることは少なく、尿路の閉塞など基礎疾患を伴うことが多い。尿管に嵌頓した結石による閉塞が最も頻度の高い原因で、閉塞を解除しなければ敗血症に至る。

出典：厚生労働省ホームページ 第118回医師国家試験 D006',
     '{"A": "性感染症は尿道炎や精巣上体炎の原因になるが、腎盂腎炎の主因ではない。", "B": "過活動膀胱は排尿の切迫感が主症状で、腎盂腎炎の原因にはならない。", "C": "糖尿病は感染しやすさの背景にはなるが、糖尿病腎症そのものが腎盂腎炎の原因になるわけではない。", "D": "間質性膀胱炎は無菌性の慢性膀胱痛症候群で、感染とは異なる。"}'),
    ('118-D-7', '正答は A「患者数は少ない。」。

我が国の透析患者の約97%は血液透析で、腹膜透析は3%前後にとどまる。腹膜透析は自宅で行え、通院回数が少なく残存腎機能が保たれやすいという利点をもつ。

出典：厚生労働省ホームページ 第118回医師国家試験 D007',
     '{"B": "持続的に除水と溶質除去が行われるため、水分やカリウムの制限はむしろ緩やかである。", "C": "自宅で患者自身または家族が行うのが基本の治療法である。", "D": "シャントを要するのは血液透析である。腹膜透析では腹腔カテーテルを留置する。", "E": "不均衡症候群は血液透析で血中の溶質が急に減ったときに起こる。緩やかな腹膜透析では起こりにくい。"}'),
    ('118-D-8', '正答は E「肺サーファクタント減少」。

急性呼吸窮迫症候群ではII型肺胞上皮細胞が障害されてサーファクタントの産生が減り、また滲出した血漿蛋白により不活化される。その結果、肺胞が虚脱してコンプライアンスが低下する。

出典：厚生労働省ホームページ 第118回医師国家試験 D008',
     '{"A": "気道抵抗が低下することはない。病態の主座は肺胞と間質である。", "B": "低酸素性肺血管攣縮と微小血栓により肺血管抵抗は上昇する。", "C": "虚脱した肺胞に血流が流れ続けるため肺内シャントは増加し、酸素投与に反応しにくい低酸素血症となる。", "D": "肺は硬くなり、コンプライアンスは低下する。"}'),
    ('118-D-9', '正答は D「潰瘍性大腸炎」。

原発性硬化性胆管炎は肝内外の胆管が線維性に狭窄する疾患で、その半数以上に潰瘍性大腸炎を合併する。大腸内視鏡検査による評価が勧められ、大腸癌と胆管癌の危険も高い。

出典：厚生労働省ホームページ 第118回医師国家試験 D009',
     '{"A": "虚血性腸炎は腸管の血流低下によるもので、本症との関連はない。", "B": "偽膜性腸炎は抗菌薬使用後のClostridioides difficile感染による。", "C": "大腸憩室炎は憩室に生じた炎症で、本症とは無関係である。", "E": "過敏性腸症候群は器質的病変を伴わない機能性疾患である。"}'),
    ('118-D-10', '正答は C「嗅覚障害」。

眼窩吹き抜け骨折では眼窩下壁や内壁が骨折し、下直筋の絞扼による眼球運動障害と複視、眼窩下神経の障害による頰部の知覚障害、副鼻腔との交通による鼻出血や眼窩気腫を生じる。嗅神経は篩板を通り眼窩底とは離れているため、嗅覚障害は起こりにくい。

出典：厚生労働省ホームページ 第118回医師国家試験 D010',
     '{"A": "下直筋が絞扼されると上方視で複視が生じる。", "B": "上顎洞や篩骨洞と交通するため鼻出血をきたす。", "D": "下直筋の絞扼により眼球の上転が制限される。", "E": "眼窩下神経の障害により同側の頰部と上口唇の知覚が低下する。"}'),
    ('118-D-11', '正答は E「生後間もなくから体重増加は不良となる。」。

重症複合免疫不全症ではT細胞とB細胞の両方の機能が失われ、生後数か月から反復する重症感染症と難治性下痢により体重増加不良(発育不全)をきたす。造血幹細胞移植が唯一の根治療法で、早期発見のため新生児マススクリーニングも行われている。

出典：厚生労働省ホームページ 第118回医師国家試験 D011',
     '{"A": "リンパ組織が発育せず、胸腺は小さく扁桃やリンパ節も触れにくい。", "B": "細胞性免疫が失われるため、ウイルスや真菌に対する抵抗力も著しく低い。生ワクチンは禁忌である。", "C": "X連鎖潜性遺伝または常染色体潜性遺伝の形式をとる。", "D": "免疫グロブリンは著明に低下する。"}'),
    ('118-D-18', '正答は C「下垂体MRI」。

無月経に加えてプロラクチン125ng/mLの高値と、増悪する頭痛を認めており、プロラクチン産生下垂体腺腫が疑われる。腫瘍の大きさと視交叉への進展を確かめるため下垂体MRIを行う。

出典：厚生労働省ホームページ 第118回医師国家試験 D018',
     '{"A": "腹部CTで下垂体は評価できない。", "B": "FDG-PETは悪性腫瘍の検索に用いるもので、下垂体腺腫の描出には適さない。", "D": "乳汁漏出があってもマンモグラフィで下垂体病変は分からない。", "E": "TSHは基準内で、甲状腺機能低下による高プロラクチン血症は考えにくい。"}'),
    ('118-D-19', '正答は B「悪性腫瘍」。

ヘリオトロープ疹とGottron丘疹に近位筋の筋力低下、CK1,620U/Lを伴い皮膚筋炎である。抗TIF1-γ抗体は悪性腫瘍の合併と強く関連し、陽性例では全身の悪性腫瘍検索を欠かせない。

出典：厚生労働省ホームページ 第118回医師国家試験 D019',
     '{"A": "AST・ALTの上昇は筋由来で、肝不全を示すものではない。", "C": "間質性肺炎は抗ARS抗体や抗MDA5抗体で問題となる。胸部エックス線写真に異常はなく、抗TIF1-γ抗体では合併が少ない。", "D": "クレアチニン0.4mg/dLで腎機能は保たれている。", "E": "膀胱直腸障害は脊髄病変でみられるもので、本症の合併症ではない。"}'),
    ('118-D-20', '正答は D「便中CDトキシン」。

抗菌薬を1週間使ったあとに1日10回を超える水様性下痢が出ており、Clostridioides difficile感染症を第一に考える。便中の毒素を調べるのが最も直接的で、陽性なら治療方針が決まる。

出典：厚生労働省ホームページ 第118回医師国家試験 D020',
     '{"A": "便潜血は出血の有無をみるだけで、原因の特定にはならない。", "B": "一般の便培養では通常この菌を狙って培養しないため、見逃す。", "C": "尿素呼気試験はHelicobacter pyloriの検査である。", "E": "α1アンチトリプシン試験は蛋白漏出性胃腸症を疑うときに用いる。"}'),
    ('118-D-22', '正答は E「5」。

FDG-PETで両側肺への遠隔転移が確認されており、切除の適応外と判断する根拠になる。肝細胞癌の切除は肝内に限局した病変が対象で、肺転移があれば全身療法に切り替える。

出典：厚生労働省ホームページ 第118回医師国家試験 D022',
     '{"A": "HCV抗体陽性は背景肝疾患を示すもので、切除の可否を左右しない。", "B": "ICG15分値8%は肝予備能が良好であることを示し、切除を支持する所見である。", "C": "肝内転移1個は同一肝内の病変で、切除の対象となりうる。", "D": "径5cmという大きさ自体は切除不能の理由にならない。"}'),
    ('118-D-23', '正答は C「急性副鼻腔炎」。

感冒に続いて片側の頰部痛と同側の膿性鼻汁が出ており急性副鼻腔炎(上顎洞炎)である。多くはウイルス性で自然軽快するが、症状が強く遷延すれば細菌感染を考えて抗菌薬を用いる。

出典：厚生労働省ホームページ 第118回医師国家試験 D023',
     '{"A": "鼻せつは鼻前庭の毛囊の感染で、鼻入口部に限局した発赤と圧痛を認める。", "B": "三叉神経痛は誘因を伴う電撃様の発作性疼痛で、膿性鼻汁は伴わない。", "D": "頰部蜂窩織炎なら皮膚に発赤と腫脹を認めるが、認めない。", "E": "アレルギー性鼻炎の鼻汁は水様性で、片側の頰部痛は起こさない。"}'),
    ('118-D-24', '正答は B「NSAID」。

検査で器質的異常がなく、心理社会的なストレスと関連して食後の胃もたれが続いており機能性ディスペプシアである。酸分泌抑制薬、消化管運動調節薬、漢方薬(六君子湯)、必要に応じて抗うつ薬が用いられる。NSAIDは胃粘膜を傷害するため用いない。

出典：厚生労働省ホームページ 第118回医師国家試験 D024',
     '{"A": "六君子湯などの漢方薬は上腹部症状に有用で、治療選択肢の一つである。", "C": "薬物療法で改善しない例には少量の抗うつ薬が用いられる。", "D": "酸分泌抑制薬は心窩部痛症候群に有効で、第一選択の一つである。", "E": "消化管運動調節薬は食後愁訴症候群に有効である。"}'),
    ('118-D-33', '正答は D「適応障害〈適応反応症〉」。

はっきりしたストレス因(叱責)から3か月以内に症状が現れ、休日には趣味を楽しめており、ストレス因が取り除かれると軽快している。適応障害の典型的な経過である。

出典：厚生労働省ホームページ 第118回医師国家試験 D033',
     '{"A": "うつ病では興味・喜びの喪失が場面を問わず持続する。休日に趣味を楽しめている点が合わない。", "B": "社交不安障害は他者からの評価を伴う場面全般への恐怖で、幼少期から続くことが多い。", "C": "概日リズム障害は睡眠相のずれが中心で、動悸や気分の落ち込みは主症状でない。", "E": "心的外傷後ストレス障害は生命を脅かすような出来事の後に、再体験・回避・過覚醒が続くもので、叱責はその出来事にあたらない。"}'),
    ('118-D-36', '正答は E「遊離サイロキシン〈FT4〉」。

体重減少、頻脈、皮膚の湿潤、前頸部の腫脹、手指振戦がそろっており甲状腺機能亢進症(Basedow病)を疑う。遊離サイロキシンとTSHを測定して確かめる。

出典：厚生労働省ホームページ 第118回医師国家試験 D036',
     '{"A": "頭部MRIは下垂体病変を疑うときに行うが、まず末梢のホルモンを測る。", "B": "抗GAD抗体は1型糖尿病を疑うときに測る。多飲・多尿の記載がない。", "C": "アルギニン負荷試験は成長ホルモン分泌不全の診断に用いる。", "D": "手根骨エックス線撮影は骨年齢の評価で、この病態の診断には直結しない。"}'),
    ('118-D-38', '正答は B「線維筋痛症」。

3か月以上続く全身の広範な疼痛に、圧痛点の存在、睡眠障害(むずむず脚症候群を含む)、炎症所見の欠如がそろっており線維筋痛症である。心理社会的な負荷が誘因になることも多い。

出典：厚生労働省ホームページ 第118回医師国家試験 D038',
     '{"A": "脊椎関節炎では炎症性腰背部痛と脊椎可動域の制限をきたすが、可動域に異常はない。", "C": "関節リウマチでは関節の腫脹と滑膜炎を認める。腫脹はない。", "D": "変形性関節症の骨棘は認めるが、体幹を含む広範な圧痛は説明できない。", "E": "リウマチ性多発筋痛症では肩や腰帯の痛みと著明な赤沈亢進を伴う。"}'),
    ('118-D-39', '正答は C「経過観察」。

加熱式たばこのスティックはニコチン含有量が少なく、すでに吐き出させ嘔吐もしている。バイタルサインは安定しており症状もないので、催吐や胃洗浄は行わず経過観察でよい。

出典：厚生労働省ホームページ 第118回医師国家試験 D039',
     '{"A": "胃洗浄は誤嚥の危険があり、この状況では適応がない。", "B": "意識は清明で呼吸も保たれており、気道確保は要らない。", "D": "多量の水を飲ませるとニコチンの吸収を促すため、たばこ誤飲では禁忌とされる。", "E": "血液浄化法を要する重症中毒ではない。"}'),
    ('118-D-40', '正答は B「膜性腎症」。

高齢者に無症候性の高度蛋白尿(尿蛋白/クレアチニン比2.5g/gCr)が生じ、血尿に乏しく腎機能もほぼ保たれている。成人のネフローゼ症候群で最も多い膜性腎症を考える。悪性腫瘍の合併検索も要る。

出典：厚生労働省ホームページ 第118回医師国家試験 D040',
     '{"A": "IgA腎症では顕微鏡的血尿が持続するのが特徴で、潜血陰性の本例は合わない。", "C": "多発性囊胞腎なら超音波検査で多数の囊胞を認める。腎に異常を認めない。", "D": "微小変化型は小児と若年成人に多く、急激に発症する。無症候で2年にわたる経過は合わない。", "E": "半月体形成性糸球体腎炎では数週で腎機能が急速に悪化し、血尿と赤血球円柱を伴う。"}'),
    ('118-D-42', '正答は B「気管挿管」。

縦隔の巨大腫瘤と末梢血の芽球14%からT細胞性リンパ芽球性リンパ腫・白血病が疑われる。仰臥位で気道と大血管が圧排されて呼吸困難とチアノーゼが急速に進んでおり、まず気管挿管で気道を確保する。

出典：厚生労働省ホームページ 第118回医師国家試験 D042',
     '{"A": "開胸手術は気道緊急の対応にならない。", "C": "胸腔穿刺は胸水の排除であって、縦隔腫瘤による気道閉塞は解除できない。", "D": "閉塞は縦隔腫瘤による圧排で、気管支拡張薬は無効である。", "E": "急速に悪化しており帰宅させてはならない。"}'),
    ('118-D-45', '正答は D「ジスキネジア」。

抗Parkinson病薬の増量に伴って出現した、体幹や四肢を不規則にくねらせる不随意運動はジスキネジアである。レボドパの血中濃度が高い時期に現れることが多く、投与量や投与法の調整で対応する。

出典：厚生労働省ホームページ 第118回医師国家試験 D045',
     '{"A": "チックは突発的で反復性の常同的な運動で、一時的に抑制できる。", "B": "ジストニアは持続的な筋収縮による異常肢位で、レボドパの効果が切れる時間帯に足に生じることが多い。", "C": "静止時振戦はParkinson病そのものの症状で、薬剤の増量で新たに出るものではない。", "E": "ミオクローヌスは電撃様の短い筋収縮で、性状が異なる。"}'),
    ('118-D-46', '正答は B「SGLT2阻害薬」。

尿蛋白とクレアチニンの比から1日あたり2g前後の蛋白尿があり、腎機能も低下している。糖尿病性腎症で、SGLT2阻害薬は血糖とは別の経路で糸球体内圧を下げ、蛋白尿と腎機能低下の進行を抑えることが示されている。

出典：厚生労働省ホームページ 第118回医師国家試験 D046',
     '{"A": "尿酸値は基準内で、尿酸降下薬を加える理由がない。", "C": "血圧は診察室でも家庭でも良好で、降圧薬を追加する状況にない。", "D": "スルホニル尿素薬は腎機能が落ちた患者で低血糖を起こしやすく、腎保護の働きもない。", "E": "カリウムの上昇は軽度で、陽イオン交換樹脂は腎機能低下の進行を抑える薬ではない。"}'),
    ('118-D-48', '正答は E「「適切なタイミングで欠損孔の閉鎖治療が必要か考えます」」。

II音の固定性分裂と肺動脈弁領域の収縮期雑音、三尖弁の相対的狭窄による拡張期雑音、右心系の拡大を認める心房中隔欠損症である。右心負荷があるので、就学前ごろを目安にカテーテル閉鎖術か外科的閉鎖の適応を検討する。

出典：厚生労働省ホームページ 第118回医師国家試験 D048',
     '{"A": "大部分は孤発例で、遺伝性が多い疾患ではない。", "B": "肺高血圧がなく症状もない時期に運動を制限する必要はない。", "C": "心房性不整脈は成人期になって問題となるもので、小児期には少ない。", "D": "心不全症状がなく、塩分制限を要する状態ではない。"}'),
    ('118-D-50', '正答は B「気管支喘息」。

夜間から早朝の呼吸困難と慢性の咳・痰があり、FEV1%68%の閉塞性障害がβ2受容体刺激薬吸入で FEV1が2.12Lから2.66Lへ25%以上改善している。可逆性のある気道閉塞であり気管支喘息である。ネコが抗原の可能性がある。

出典：厚生労働省ホームページ 第118回医師国家試験 D050',
     '{"A": "過敏性肺炎は拘束性換気障害を示し、%VCが低下する。104%と保たれている。", "C": "慢性気管支炎の気流閉塞は可逆性に乏しい。", "D": "うっ血性心不全なら心音・呼吸音の異常や胸部エックス線写真での心拡大を認める。", "E": "睡眠時無呼吸症候群では呼吸機能検査は正常で、気管支拡張薬にも反応しない。"}'),
    ('118-D-52', '正答は A「経過観察」。

発熱、扁桃の白苔、頸部リンパ節腫脹、異型リンパ球15%、肝逸脱酵素の上昇からEBウイルスによる伝染性単核症である。多くは自然に軽快するので対症療法と経過観察でよい。脾破裂を避けるため激しい運動は控えさせる。

出典：厚生労働省ホームページ 第118回医師国家試験 D052',
     '{"B": "血漿交換を要する病態ではない。", "C": "アシクロビルはEBウイルスに対する有効性が確立しておらず、通常は用いない。", "D": "アンピシリンを投与すると高率に薬疹が出るため避ける。", "E": "悪性リンパ腫ではなく、抗癌薬の適応はない。"}'),
    ('118-D-55', '正答は C「病室に出入りする人全員が同様に予防策を理解する。」。

多剤耐性緑膿菌は接触感染で広がるため接触予防策をとる。医師・看護師だけでなく、清掃員や面会者を含め病室に出入りするすべての人が同じ予防策を理解して実行しなければ、伝播は止められない。

出典：厚生労働省ホームページ 第118回医師国家試験 D055',
     '{"A": "接触予防策では個室管理か同一菌の患者どうしの集団隔離を行う。", "B": "N95マスクは空気感染予防策で用いる。緑膿菌は空気感染しない。", "D": "手袋には目に見えない破損があり、外した後も手指衛生が必要である。", "E": "環境や患者に接触する場面では吸引の有無にかかわらず個人防護具を用いる。"}'),
    ('118-D-58', '正答は B「脂肪便」。

長年の多量飲酒と反復する腹痛の既往、膵のびまん性石灰化から慢性膵炎の非代償期である。膵外分泌機能が低下してリパーゼが不足し、脂肪が消化されずに脂肪便となる。膵消化酵素薬を補充する。

出典：厚生労働省ホームページ 第118回医師国家試験 D058',
     '{"A": "黒色便は上部消化管出血を示す所見で、本症の特徴ではない。", "C": "粘血便は潰瘍性大腸炎や細菌性腸炎でみられる。", "D": "灰白色便は胆汁がうっ滞して腸管に届かない閉塞性黄疸でみられる。総ビリルビンは0.8mg/dLで正常である。", "E": "兎糞状便は便秘型過敏性腸症候群でみられる。"}'),
    ('118-D-59', '正答は E「パーソナリティ障害〈パーソナリティ症〉」。

思春期以降に始まり、対人関係の不安定さ、見捨てられ不安、衝動性、反復する自傷や過量服薬が持続しており境界性パーソナリティ障害である。心理療法が治療の中心で、薬物療法は補助的に用いる。

出典：厚生労働省ホームページ 第118回医師国家試験 D059',
     '{"A": "双極性障害では躁病相と抑うつ相が数週から数か月の単位で現れる。気分の変動は対人関係の出来事に即時に反応しており、性質が異なる。", "B": "統合失調症では幻覚妄想や思考障害が中核となるが、そうした症状の記載がない。", "C": "自閉スペクトラム症は幼少期から社会的コミュニケーションの障害が続く。小学生までは問題がなかった。", "D": "注意欠如多動性障害も幼少期から不注意や多動が複数の場面で認められる。"}'),
    ('118-D-60', '正答は E「アンジオテンシン変換酵素〈ACE〉阻害薬」。

Raynaud現象と前腕までの皮膚硬化があり全身性強皮症で、抗RNAポリメラーゼIII抗体陽性、急激な高血圧、腎機能の急速な悪化、血漿レニン活性の上昇から強皮症腎クリーゼである。ACE阻害薬が特異的に有効で、ためらわず投与する。

出典：厚生労働省ホームページ 第118回医師国家試験 D060',
     '{"A": "β遮断薬は末梢血管を収縮させてRaynaud現象を悪化させ、腎クリーゼには無効である。", "B": "ループ利尿薬は循環血漿量を減らしてレニン・アンジオテンシン系をさらに亢進させる。", "C": "高用量のグルココルチコイドはむしろ腎クリーゼの誘因となる。", "D": "抗コリンエステラーゼ薬は重症筋無力症に用いる。"}'),
    ('118-D-64', '正答は D「気管支肺胞洗浄〈BAL〉:リンパ球分画増加」。

職場でだけ咳が出て自宅では出ないという環境との関連があり、キノコ栽培に従事していることからキノコ胞子による過敏性肺炎が疑われる。気管支肺胞洗浄液ではリンパ球が増加し、CD8陽性細胞が優位となる。

出典：厚生労働省ホームページ 第118回医師国家試験 D064',
     '{"A": "抗酸菌感染を疑う所見はなく、職場との関連も説明できない。", "B": "血清IgAの高値は本症の所見ではない。", "C": "過敏性肺炎は拘束性換気障害を示し、FEV1%は低下しない。", "E": "びまん性肺胞障害は急性呼吸窮迫症候群の病理像で、過敏性肺炎では肉芽腫を伴うリンパ球性の胞隔炎をみる。"}'),
    ('118-E-2', '正答は B「複数の研究を統合できる。」。

メタ分析は同じ問いを扱った複数の研究結果を統計学的に統合し、より精度の高い推定値を得る手法である。系統的レビューと組み合わせて用いられ、エビデンスレベルの階層では最上位に位置づけられる。

出典：厚生労働省ホームページ 第118回医師国家試験 E002',
     '{"A": "エビデンスレベルは最も高い部類に位置づけられる。", "C": "有意な結果が公表されやすいという出版バイアスは、メタ分析で必ず検討すべき問題である。", "D": "ランダム化比較試験を統合の対象とすることは多いが、同義ではない。", "E": "既存の研究結果を統合する手法で、研究者が対象集団に直接働きかけることはない。"}'),
    ('118-E-3', '正答は E「Staphylococcus epidermidis」。

Staphylococcus epidermidisをはじめとするコアグラーゼ陰性ブドウ球菌は皮膚の常在菌で、2セット中1セットのみの陽性なら採血時の汚染菌と判断することが多い。ただし人工物が留置されていれば起因菌となりうる。

出典：厚生労働省ホームページ 第118回医師国家試験 E003',
     '{"A": "Candida albicansは血液から検出されれば汚染とはみなさず、必ず治療する。", "B": "Escherichia coliも常在菌ではあるが、血液培養から検出されれば起因菌として扱う。", "C": "Pseudomonas aeruginosaも検出されれば起因菌として治療する。", "D": "Staphylococcus aureusは1セットのみの陽性でも起因菌とみなし、感染性心内膜炎の検索を含めて治療する。"}'),
    ('118-E-5', '正答は D「橈骨動脈の触知不良」。

死期が近づくと心拍出量が低下し末梢循環が保てなくなるため、橈骨動脈が触れにくくなる。四肢の冷感とチアノーゼ、下顎呼吸、意識レベルの低下とともに、死が数日以内に迫っている徴候となる。

出典：厚生労働省ホームページ 第118回医師国家試験 E005',
     '{"A": "末梢循環不全により手足は冷たくなる。", "B": "腎血流の低下により尿量は減少する。", "C": "呼吸機能の低下により酸素飽和度は下がる。", "E": "循環不全により毛細血管再充満時間は延長する。"}'),
    ('118-E-6', '正答は C「高血圧症」。

患者調査では、65歳以上の外来患者数は高血圧性疾患が最も多い。有病率が高く、生涯にわたり通院を要することが背景にある。

出典：厚生労働省ホームページ 第118回医師国家試験 E006',
     '{"A": "糖尿病も多いが、高血圧性疾患には及ばない。", "B": "緑内障は眼科の外来で多いが、全体では高血圧性疾患に及ばない。", "D": "悪性新生物は入院での比重が大きく、外来患者数では上位ではない。", "E": "脂質異常症も多いが、高血圧性疾患のほうが多い。"}'),
    ('118-E-7', '正答は D「綿棒を患者の鼻孔から上方に向けて挿入する。」。

鼻腔は鼻背に沿って上向きではなく、鼻孔から顔面に対して水平に、後方(耳のほう)へ向けて挿入する。上方に向けると鼻甲介にあたって痛みを与え、検体も採れない。

出典：厚生労働省ホームページ 第118回医師国家試験 E007',
     '{"A": "飛沫を浴びる手技なので、マスク・ゴーグル・ガウン・手袋を着用する。", "B": "咳やくしゃみを正面から浴びないよう、患者の側方に立つ。", "C": "急に動くと粘膜を傷つけるため、頭部を支えて固定する。", "E": "鼻咽頭ぬぐい液は咽頭後壁に綿棒を当て、数秒とどめてから回転させて採取する。"}'),
    ('118-E-8', '正答は A「患者の眼鏡」。

標準予防策で手袋を要するのは、血液・体液・分泌物・排泄物、傷のある皮膚、粘膜に触れるときである。患者の眼鏡はこれらに該当せず、素手で扱ってよい。

出典：厚生労働省ホームページ 第118回医師国家試験 E008',
     '{"B": "創部にあてたガーゼは血液や滲出液が付着しており手袋を要する。", "C": "便が付着したオムツは排泄物であり手袋を要する。", "D": "口腔ケアに用いたブラシは唾液が付着しており手袋を要する。", "E": "喀痰が付着したティッシュペーパーも分泌物であり手袋を要する。"}'),
    ('118-E-9', '正答は B「かゆみ」。

閉塞性黄疸では胆汁が腸管へ流れず、胆汁酸が血中に貯留して皮膚の神経終末を刺激するため強いかゆみが生じる。灰白色便と濃い尿(ビリルビン尿)も伴う。

出典：厚生労働省ホームページ 第118回医師国家試験 E009',
     '{"A": "紫斑は血小板減少や凝固障害でみられ、閉塞性黄疸で直ちに生じるものではない。", "C": "黒色便は上部消化管出血によるもので、閉塞性黄疸では灰白色便となる。", "D": "立ちくらみは起立性低血圧や貧血の症状である。", "E": "肉眼的血尿は尿路の出血によるもので、閉塞性黄疸では濃い黄褐色のビリルビン尿となる。"}'),
    ('118-E-10', '正答は E「山中伸弥 — 多能性幹細胞〈iPS細胞〉の作製」。

山中伸弥は体細胞に4つの因子を導入して多能性を獲得させるiPS細胞の作製により、2012年にノーベル生理学・医学賞を受賞した。

出典：厚生労働省ホームページ 第118回医師国家試験 E010',
     '{"A": "大隅良典の受賞理由はオートファジーの機構の解明である。", "B": "大村智の受賞理由は寄生虫感染症に対するイベルメクチンにつながる発見である。", "C": "利根川進の受賞理由は抗体の多様性が生じる遺伝的原理の解明である。", "D": "本庶佑の受賞理由はPD-1の発見による免疫チェックポイント阻害を用いた癌治療である。"}'),
    ('118-E-11', '正答は D「がん、循環器疾患、糖尿病の総称である。」。

非感染性疾患は感染以外の原因で生じる慢性疾患の総称で、がん、循環器疾患、糖尿病に加えて慢性呼吸器疾患が主要な4つの疾患とされ、精神疾患などを含めることもある。3つに限る記述は誤りである。

出典：厚生労働省ホームページ 第118回医師国家試験 E011',
     '{"A": "家族歴や遺伝的素因は発症に関与する。", "B": "喫煙、飲酒、食生活、身体活動の4つが共通の危険因子とされる。", "C": "健康日本21は非感染性疾患の予防を主要な目標に掲げている。", "E": "健康の社会的決定要因を踏まえた環境整備が必要とされている。"}'),
    ('118-E-12', '正答は B「滅菌手袋を着用して穿刺する。」。

腰椎穿刺は無菌操作で行うため、術者は滅菌手袋を着用し、穿刺部位を広く消毒して滅菌ドレープをかける。医原性の髄膜炎を防ぐために欠かせない。

出典：厚生労働省ホームページ 第118回医師国家試験 E012',
     '{"A": "側臥位で背中を丸めさせて棘突起間を開く。腹臥位では行えない。", "C": "太い針は穿刺後頭痛を増やすため、できるだけ細い針を用いる。", "D": "脊髄円錐は成人でL1〜L2の高さで終わるので、その下のL3/4またはL4/5を穿刺する。", "E": "穿刺後は仰臥位で安静にする。座位を保つ必要はない。"}'),
    ('118-E-13', '正答は C「医療者と患者がともに最善の方法を探る。」。

共同意思決定は、医学的な根拠と患者の価値観・生活の双方を持ち寄り、医療者と患者が対話しながら一緒に最善の方針を作り上げる過程である。

出典：厚生労働省ホームページ 第118回医師国家試験 E013',
     '{"A": "医療者が決めた方針に同意を得るのはパターナリズムに近い形である。", "B": "選択肢を示して患者に選ばせるだけでは、情報提供にとどまり共同の意思決定にならない。", "D": "インフォームド・コンセントは説明と同意の手続きで、方針を一緒に作る過程とは異なる。", "E": "経過が確実に予測できる場合はむしろ標準治療が定まりやすい。共同意思決定が生きるのは、複数の選択肢があり優劣がつけがたい場面である。"}'),
    ('118-E-14', '正答は E「副鼻腔気管支症候群」。

副鼻腔気管支症候群は慢性副鼻腔炎と気管支の慢性炎症が併存する病態で、膿性痰を伴う湿性咳嗽が続く。マクロライド少量長期療法が有効である。

出典：厚生労働省ホームページ 第118回医師国家試験 E014',
     '{"A": "咳喘息は痰を伴わない乾性咳嗽が主体である。", "B": "間質性肺炎も乾性咳嗽をきたす。", "C": "感染後咳嗽は気道の過敏性が残ることによる乾性咳嗽である。", "D": "胃食道逆流症による咳嗽も乾性である。"}'),
    ('118-E-15', '正答は C「自身の業務に関係のない患者の電子カルテを閲覧する。」。

自身の診療に関係しない患者の診療録を閲覧することは、正当な目的のない個人情報へのアクセスであり、守秘義務と職業倫理に反する。

出典：厚生労働省ホームページ 第118回医師国家試験 E015',
     '{"A": "セカンドオピニオンを求める権利は患者にあり、応じるのは適切である。", "B": "同僚の不適切な医療行為に対して忠告することは、患者の安全を守るための責務である。", "D": "適応に合う患者に治験の情報を提供することは、選択肢を示す行為として適切である。", "E": "判断能力を欠く患者について、その利益を守る立場の者に説明することは適切である。"}'),
    ('118-E-16', '正答は A「乳汁分泌」。

乳汁分泌は妊娠・授乳期のほか、高プロラクチン血症や薬剤性でみられる生理的・内分泌的な現象で、乳癌を疑う所見ではない。乳癌で問題になるのは血性の乳頭分泌である。

出典：厚生労働省ホームページ 第118回医師国家試験 E016',
     '{"B": "腫瘍が乳管を引き込むと乳頭が陥凹する。", "C": "Cooper靱帯が引かれて皮膚が陥凹するえくぼ徴候は乳癌を示唆する。", "D": "皮膚のリンパ管が閉塞して毛孔が目立つ橙皮様変化は進行乳癌の所見である。", "E": "大胸筋に固着した腫瘤は胸壁への浸潤を示す。"}'),
    ('118-E-17', '正答は E「血清クレアチニンを用いた推算GFRは筋肉量に影響される。」。

血清クレアチニンは筋肉由来なので、筋肉量が多ければ高く、少なければ低く出る。これを用いた推算GFRは、るいそうの高齢者や四肢麻痺の患者で実際より高く見積もられる。そうした場合はシスタチンCによる推算が有用である。

出典：厚生労働省ホームページ 第118回医師国家試験 E017',
     '{"A": "腎血流量は加齢とともに減少する。", "B": "尿濃縮能も加齢とともに低下し、高齢者は脱水になりやすい。", "C": "妊娠中は腎血漿流量が増えてGFRは約50%増加する。", "D": "シスタチンCはGFRが低下すれば上昇する。"}'),
    ('118-E-18', '正答は E「悪い知らせを聞く意思があるかどうかを患者本人に確認する。」。

悪い知らせを伝える際は、まず患者がどこまで知りたいと望んでいるかを確かめる。SPIKESでいうInvitationの段階で、知りたくないという意思も尊重される。

出典：厚生労働省ホームページ 第118回医師国家試験 E018',
     '{"A": "患者が望むなら家族の同席が支えになる。誰に同席してほしいかを事前に確認する。", "B": "一度で受け止められるものではなく、繰り返し説明し理解を確かめる。", "C": "患者が病状をどう理解しているかを先に聴くこと(Perception)は、説明の出発点になる。", "D": "理解度に合わせて言葉を選び、区切りながら伝える必要がある。"}'),
    ('118-E-19', '正答は D「予期不安」。

予期不安は、パニック発作がまた起こるのではないかという持続的な不安で、発作そのものと並ぶパニック障害の中核症状である。これに広場恐怖や回避行動が加わって生活が制限される。

出典：厚生労働省ホームページ 第118回医師国家試験 E019',
     '{"A": "健忘は解離性障害や器質性精神障害でみられる。", "B": "無為は統合失調症の陰性症状である。", "C": "観念奔逸は躁状態でみられる思考の障害である。", "E": "フラッシュバックは心的外傷後ストレス障害の再体験症状である。"}'),
    ('118-E-20', '正答は E「固定姿勢保持困難〈asterixis〉は上肢を前方に水平挙上させて観察する。」。

固定姿勢保持困難(羽ばたき振戦)は、上肢を前方に挙げて手関節を背屈させ、その姿勢を保たせたときに現れる不規則な落下運動である。肝性脳症や高二酸化炭素血症、尿毒症でみられる。

出典：厚生労働省ホームページ 第118回医師国家試験 E020',
     '{"A": "呼吸数は意識されると変わるので、患者に気づかれないよう30秒〜1分測る。", "B": "会話は血圧を上げるため、静かに座って数分安静にしてから測る。", "C": "握力計で測れるのは前腕・手の筋力である。上肢近位筋は徒手筋力テストで評価する。", "D": "中心静脈圧の推定は上半身を30〜45度起こした半坐位で行う。臥位では拍動の頂点が観察できない。"}'),
    ('118-E-22', '正答は D「医師が署名しなければならない。」。

死亡診断書(死体検案書)には医師が記名押印または署名しなければならない。作成は医師の義務で、正当な事由なく交付を拒めない。

出典：厚生労働省ホームページ 第118回医師国家試験 E022',
     '{"A": "死亡の原因の欄には、解剖によって明らかになった所見も記載する。解剖の有無を記す欄もある。", "B": "歯科医師も自らの診療に関する範囲で死亡診断書を交付できる。", "C": "主治医でなくても、死亡を確認した医師が診察に基づいて記載できる。", "E": "届出先は市町村長である。死亡届に添えて提出する。"}'),
    ('118-E-23', '正答は A「胸骨圧迫」。

窒息した人が意識を失って倒れたら、心停止に準じてただちに胸骨圧迫を始める。胸骨圧迫による胸腔内圧の上昇は異物を押し出す効果も期待できる。

出典：厚生労働省ホームページ 第118回医師国家試験 E023',
     '{"B": "背部叩打は意識があるうちに行う手技である。", "C": "腹部突き上げも意識がある間に行う。", "D": "まず胸骨圧迫を始め、人工呼吸は訓練を受けていれば30対2で組み合わせる。", "E": "口腔内をのぞいて見える異物は取り除くが、盲目的な指による掻き出しは異物を押し込む危険があり、圧迫を中断してまで行わない。"}'),
    ('118-E-25', '正答は D「敗血症性ショック — 蕁麻疹」。

蕁麻疹はアナフィラキシーショックの所見である。敗血症性ショックでは発熱や低体温、末梢血管拡張による四肢の温感(ウォームショック)、乏尿、意識障害がみられる。

出典：厚生労働省ホームページ 第118回医師国家試験 E025',
     '{"A": "出血性ショックでは循環血液量の減少を代償して頻脈になる。正しい組合せである。", "B": "心原性ショックでは心拍出量の低下により腎血流が減り乏尿となる。正しい組合せである。", "C": "神経原性ショックでは交感神経の遮断により血管拡張と徐脈をきたす。正しい組合せである。", "E": "アナフィラキシーショックでは喉頭浮腫による気道閉塞が致命的となる。正しい組合せである。"}'),
    ('118-E-26', '正答は A「減塩」。

BMI21.3で肥満はなく、腹囲・脂質・血糖・尿酸も問題ない。是正すべきは食塩摂取15g/日という点であり、6g/日未満を目標に減塩を指導する。

出典：厚生労働省ホームページ 第118回医師国家試験 E026',
     '{"B": "機会飲酒であり禁酒を求める根拠はない。", "C": "身長168cm、体重60kgで肥満はなく、減量の対象にならない。", "D": "総コレステロール170mg/dL、トリグリセリド70mg/dLと脂質は良好である。", "E": "尿酸6.8mg/dLは基準内で、プリン体制限を要さない。"}'),
    ('118-E-27', '正答は D「精巣捻転症」。

急な陰囊痛と腫大、透光性なし、著明な圧痛に加えてカラードプラで精巣内の血流が乏しく精巣捻転症である。発症から6〜8時間以内に整復しないと精巣が壊死するため、緊急手術を行う。

出典：厚生労働省ホームページ 第118回医師国家試験 E027',
     '{"A": "精巣腫瘍は無痛性の腫大として現れ、血流はむしろ増加する。", "B": "精巣水瘤は透光性を認め、圧痛を伴わない。", "C": "精索静脈瘤は立位で目立つ蔓状の静脈拡張で、急激な疼痛はきたさない。", "E": "鼠径ヘルニアなら鼠径部に腫瘤を触れるが、触れない。"}'),
    ('118-E-30', '正答は A「医療安全管理部門にインシデントレポートを提出する。」。

薬剤師の指摘が生かされず、アレルギー歴のある薬剤が投与されて蕁麻疹という健康被害が生じている。院内の医療安全管理部門へインシデントレポートを提出し、指摘が治療方針に反映される仕組みづくりにつなげる。

出典：厚生労働省ホームページ 第118回医師国家試験 E030',
     '{"B": "医療事故調査制度の対象は予期しなかった死亡例で、この事例は該当しない。", "C": "既知のアレルギー歴を確認しなかった院内の過程の問題であり、製薬会社への副作用報告が第一ではない。", "D": "実害が生じており、報告して再発防止につなげる必要がある。", "E": "保健所への届出を要する事案ではない。"}'),
    ('118-E-31', '正答は A「緊急手術」。

無月経7週で妊娠反応陽性、子宮内に胎囊を認めず付属器領域に腫瘤、Morrison窩とDouglas窩に液体貯留、血圧78/52mmHgのショック状態であり、卵管妊娠破裂による腹腔内出血である。ただちに開腹または腹腔鏡下の緊急手術を行う。

出典：厚生労働省ホームページ 第118回医師国家試験 E031',
     '{"B": "子宮鏡は子宮腔内を観察する検査で、出血性ショックの対応にならない。", "C": "子宮動脈塞栓術は分娩後出血などに用いる。破裂した卵管の止血には手術が確実である。", "D": "ショック状態であり経過観察は許されない。", "E": "メトトレキサート療法は未破裂で循環動態が安定した異所性妊娠に限られる。"}'),
    ('118-E-32', '正答は E「Neisseria meningitidis」。

急速に進行する発熱と頭痛、項部硬直に加えて四肢の出血斑(電撃性紫斑)を伴っており、髄膜炎菌による侵襲性髄膜炎菌感染症である。血液培養でグラム陰性双球菌が検出される。予後を左右するので直ちに抗菌薬を投与し、濃厚接触者には予防内服を行う。

出典：厚生労働省ホームページ 第118回医師国家試験 E032',
     '{"A": "Escherichia coliはグラム陰性桿菌で、成人の市中髄膜炎の主因ではない。", "B": "A群溶血性連鎖球菌はグラム陽性球菌で連鎖状に並ぶ。", "C": "Moraxella catarrhalisもグラム陰性双球菌だが、気道感染の起因菌で電撃性紫斑を伴う敗血症はきたさない。", "D": "Neisseria gonorrhoeaeもグラム陰性双球菌だが、性器や咽頭の感染が主で、この経過は合わない。"}'),
    ('118-E-33', '正答は C「腹部超音波検査」。

総合感冒薬に含まれる抗ヒスタミン薬や抗コリン成分が引き金となった、前立腺肥大症を背景とする急性尿閉である。下腹部の弾性軟の腫瘤は充満した膀胱で、腹部超音波検査で残尿量を確かめれば診断がつく。導尿で速やかに解除する。

出典：厚生労働省ホームページ 第118回医師国家試験 E033',
     '{"A": "骨盤部MRIは前立腺癌の局所診断に用いるもので、急性期にまず行う検査ではない。", "B": "造影CTは被曝と造影剤の負担があり、まず行う検査ではない。", "D": "腹部エックス線撮影では膀胱内の尿は評価できない。", "E": "下部消化管内視鏡は大腸の検査で、この病態には無関係である。"}'),
    ('118-E-34', '正答は E「産褥6週間後に再度75g経口ブドウ糖負荷試験を行う。」。

75gOGTTで2点以上が基準を超えており妊娠糖尿病である。妊娠糖尿病の既往は将来の2型糖尿病発症の危険因子なので、産褥6〜12週に75gOGTTを再検して耐糖能を評価し、以後も定期的に追跡する。

出典：厚生労働省ホームページ 第118回医師国家試験 E034',
     '{"A": "禁忌がなければ運動療法は勧められる。", "B": "妊娠中の経口血糖降下薬は原則として用いず、食事療法で不十分ならインスリンを用いる。", "C": "1,200kcalでは母児に必要なエネルギーが不足する。標準体重×30kcalに妊娠中期以降の付加量を加える。", "D": "妊娠中の目標は食後2時間値120mg/dL未満とより厳格である。"}'),
    ('118-E-35', '正答は D「「話し合いで決まったことでも後で変更できます」」。

人生の最終段階における医療・ケアの話し合いは、本人の状態や気持ちの変化に応じて何度でも見直すことが前提である。一度決めたら変えられないものではないと伝えることが、話し合いを始めやすくする。

出典：厚生労働省ホームページ 第118回医師国家試験 E035',
     '{"A": "話し合いの内容は文書にまとめて共有し、関係者が同じ理解をもてるようにする。", "B": "配偶者は本人の意思を最もよく知る立場にあり、代理意思決定者になりうる。", "C": "認知症があっても本人の意思を確かめる努力が必要で、可能な範囲で参加してもらう。", "E": "在宅サービスの調整を担うケアマネジャーとの共有は欠かせない。"}'),
    ('118-E-36', '正答は A「直腸指診を行う。」。

心窩部から右下腹部への痛みの移動と咳嗽時の疼痛から急性虫垂炎を疑う。骨盤内に位置する虫垂の炎症では腹壁からの所見が乏しいので、直腸指診でDouglas窩の圧痛を確かめることが診断に役立つ。

出典：厚生労働省ホームページ 第118回医師国家試験 E036',
     '{"B": "腹部診察は視診・聴診・打診・触診の順で行う。打診が聴診より先になってはならない。", "C": "腸蠕動音の減弱を判断するには最低1分は聴く。5秒では足りない。", "D": "痛みの部位は最後に触れる。先に触れると防御反応で以後の診察ができなくなる。", "E": "腸蠕動音は腹腔内に伝わるので、1か所を十分な時間聴けばよい。"}'),
    ('118-E-37', '正答は D「「おつらいですね、もう少しお気持ちをお話しいただけますか」」。

「もう終わりにしたい」という訴えの背後には、身体の苦痛だけでなく孤独感や無力感があることが多い。まず気持ちを受けとめ、さらに語ってもらうことで何が最もつらいのかを一緒に探る。

出典：厚生労働省ホームページ 第118回医師国家試験 E037',
     '{"A": "本人は自宅で過ごすことを望んでおり、いきなり入院を提案するのは訴えを受けとめていない。", "B": "生命を積極的に終わらせる行為は許されない。", "C": "身体症状に絞って尋ねると、精神的・社会的な苦痛を語る機会を閉ざしてしまう。最初の返答としては早い。", "E": "励ましは訴えの否認となり、患者を孤立させる。"}'),
    ('118-E-38', '正答は E「回復期リハビリテーション病院」。

大腿骨頸部骨折の術後で、意欲があり在宅復帰を目指せる状態である。回復期リハビリテーション病棟は集中的な訓練で日常生活動作を高め、在宅復帰を図る施設で、この患者に最も適する。

出典：厚生労働省ホームページ 第118回医師国家試験 E038',
     '{"A": "介護医療院は長期の療養と生活の場を提供する施設で、在宅復帰を目指す段階には合わない。", "B": "特定機能病院は高度医療を担う施設で、リハビリテーションの場ではない。", "C": "グループホームは認知症の人が共同生活を送る場で、認知症のない本例は対象にならない。", "D": "特別養護老人ホームは原則として要介護3以上の人が生活する施設である。"}'),
    ('118-E-39', '正答は B「小刻み歩行」。

便秘と嗅覚低下という前駆症状に続き、左右差のある静止時振戦・筋強剛・姿勢反射障害が現れ、ドパミントランスポーターSPECTで線条体の取込み低下を認めておりParkinson病である。歩幅が狭く足を擦るような小刻み歩行が特徴的で、前方突進やすくみ足を伴う。

出典：厚生労働省ホームページ 第118回医師国家試験 E039',
     '{"A": "鶏歩は下垂足のため膝を高く上げる歩行で、腓骨神経麻痺や末梢神経障害でみられる。", "C": "動揺性歩行は近位筋の筋力低下により腰を左右に振る歩行で、筋ジストロフィーでみられる。", "D": "はさみ足歩行は両下肢の痙縮による歩行で、痙性対麻痺でみられる。痙縮はない。", "E": "マグネット歩行は足が床に吸いつくような歩行で、正常圧水頭症でみられる。"}'),
    ('118-E-40', '正答は E「5」。

予防給付は要支援1・2と認定された人が受けられる給付である。要支援1という認定こそが根拠になる。

出典：厚生労働省ホームページ 第118回医師国家試験 E040',
     '{"A": "高血圧症で通院していることは給付の要件にならない。", "B": "一人暮らしであることも要件ではない。", "C": "年金生活という経済状況も要件ではない。", "D": "認知機能に問題がないことも給付の根拠にはならない。"}'),
    ('118-E-41', '正答は D「E3 V2 M5」。

呼びかけで開眼するのでE3、うなり声だけで言葉にならないのでV2、痛み刺激の部位を払いのけるのでM5である。合計10点となる。

出典：厚生労働省ホームページ 第118回医師国家試験 E041',
     '{"A": "自発開眼と、見当識のある会話が必要な組み合わせで、本例には当たらない。", "B": "自発開眼していないためE4にはならない。", "C": "会話は成立しておらずV4にはならない。払いのける動作はM5である。", "E": "刺激部位を払いのけるのはM5で、M4は逃避のための屈曲である。"}'),
    ('118-E-42', '正答は B「頭部単純CT」。

食事中に突然の激しい頭痛と嘔吐で発症し、意識障害と著明な高血圧を伴う。くも膜下出血を第一に考え、まず頭部単純CTを撮る。発症直後の出血はCTで高吸収域として最もよく写る。

出典：厚生労働省ホームページ 第118回医師国家試験 E042',
     '{"A": "脳波はてんかんや脳症の評価に用いるもので、出血の診断には使わない。", "C": "出血や占拠性病変を否定する前の腰椎穿刺は、脳ヘルニアを起こす危険がある。", "D": "MRIは撮像に時間がかかり、意識障害のある急性期には向かない。", "E": "脳血流をみる検査で、急性期の出血診断には使わない。"}'),
    ('118-E-43', '正答は E「睡眠欲求の減少」。

抑うつで抗うつ薬を始めたあとに、多弁で気分が高揚し、遅くまで働いて外出し明け方まで電話をするようになった。躁病エピソードへ転じており、眠らなくても平気という睡眠欲求の減少がその中核症状である。

出典：厚生労働省ホームページ 第118回医師国家試験 E043',
     '{"A": "幻視は認めておらず、躁病の症状でもない。", "B": "離人症は認めていない。", "C": "聴覚過敏は躁病の症状ではない。", "D": "現在は気分が高揚しており、抑うつ気分は認めない。"}'),
    ('118-E-44', '正答は B「「薬を変える必要があると思います」」。

抗うつ薬の投与中に躁転しており、双極性障害と考える。抗うつ薬を続ければ躁状態をさらに押し上げるので中止し、気分安定薬へ切り替える必要がある。薬を変えるという説明が正しい。

出典：厚生労働省ホームページ 第118回医師国家試験 E044',
     '{"A": "躁状態のさなかに転職のような重大な決断をすると、後で本人が困ることになる。", "C": "躁病エピソードであり、精神疾患ではないという説明は誤りである。", "D": "抗うつ薬を続けたまま様子をみれば、躁状態は悪化する。", "E": "仕事を詰め込むよう促すのは、躁状態を助長し消耗させる。"}'),
    ('118-E-45', '正答は C「運動失調」。

足を広げた不安定な歩行、まっすぐ線を引けない、箸を目的の場所へ運べない、不明瞭な話し方が徐々に進んでいる。筋力も感覚も保たれており、小脳性の運動失調である。

出典：厚生労働省ホームページ 第118回医師国家試験 E045',
     '{"A": "痙縮は錐体路障害の所見で、腱反射の亢進を伴う。", "B": "失行は運動の企図や順序が組み立てられない高次脳機能障害である。", "D": "筋力低下は自覚も所見もなく、運動麻痺ではない。", "E": "不随意運動は認めていない。"}'),
    ('118-E-46', '正答は D「鼻指鼻試験拙劣」。

小脳性の運動失調では、目標に手を運ぶ動作が拙劣になる。鼻指鼻試験で測定障害や企図振戦がみられる。

出典：厚生労働省ホームページ 第118回医師国家試験 E046',
     '{"A": "Gowers徴候は近位筋の筋力低下でみられ、筋原性疾患を示す。", "B": "Romberg徴候は深部感覚性の失調で陽性になる。本例は暗いところでもふらつきが変わらず、小脳性である。", "C": "Chaddock反射は錐体路障害を示す病的反射である。", "E": "固定姿勢保持困難は代謝性脳症でみる所見である。"}'),
    ('118-E-47', '正答は E「夜中から明け方に悪化する。」。

上気道炎を契機に喘鳴を伴う呼吸困難が出ており、好酸球も増えている。気管支喘息では気道の炎症と迷走神経の緊張により、夜中から明け方にかけて気道が狭くなり、症状が強まる。

出典：厚生労働省ホームページ 第118回医師国家試験 E047',
     '{"A": "座位で悪化するのは心不全の起座呼吸である。喘息では座ると楽になる。", "B": "食後の悪化は喘息の特徴ではない。", "C": "悪化する時間帯は夕方ではなく、夜間から早朝である。", "D": "特定の側臥位で悪化するのは喘息の特徴ではない。"}'),
    ('118-E-48', '正答は E「吸入副腎皮質ステロイド/長時間作用性β2刺激薬配合剤」。

発作が治まったあとに要るのは、気道の慢性炎症そのものを抑える長期管理薬である。吸入副腎皮質ステロイドが土台で、長時間作用性β2刺激薬との配合剤にすると吸入の手間が減り、続けやすい。

出典：厚生労働省ホームページ 第118回医師国家試験 E048',
     '{"A": "利尿薬は心不全の治療で、喘息には用いない。", "B": "抗ヒスタミン薬は喘息の長期管理の主軸にはならない。", "C": "マクロライドは難治例で補助的に使うことがあるが、まず吸入ステロイドである。", "D": "長時間作用性抗コリン薬は追加の選択肢で、最初に置く薬ではない。"}'),
    ('118-E-49', '正答は A「痛風」。

母趾基部の腫脹と疼痛を繰り返してきた経過があり、今回は足関節に急性の激しい関節炎が起きた。関節液に白血球が針状結晶を貪食する像を認め、尿酸ナトリウム結晶による痛風である。

出典：厚生労働省ホームページ 第118回医師国家試験 E049',
     '{"B": "偽痛風の結晶はピロリン酸カルシウムで、菱形や棒状を呈する。", "C": "脊椎関節炎は体軸の炎症が主体で、結晶は出ない。", "D": "関節リウマチは多関節が対称性に侵され、関節液に結晶は認めない。", "E": "変形性関節症は炎症所見に乏しく、急激な発赤腫脹は起こさない。"}'),
    ('118-E-50', '正答は A「NSAID」。

痛風発作の急性期は、炎症をすばやく抑えることが目的になる。腎機能は保たれており、NSAIDを十分量で短期間使う。

出典：厚生労働省ホームページ 第118回医師国家試験 E050',
     '{"B": "麻薬性鎮痛薬は痛風発作の適応にならない。", "C": "尿酸を下げる薬を発作中に始めると、尿酸値が動いて発作を長引かせる。落ち着いてから開始する。", "D": "グルココルチコイドはNSAIDが使えないときの選択肢である。本例は血糖が高く、糖尿病を悪化させる懸念がある。", "E": "疾患修飾性抗リウマチ薬は関節リウマチの薬で、痛風には用いない。"}'),
    ('118-F-1', '正答は E「駅のホームドア(転落防止柵)」。

ユニバーサルデザインは、障害の有無や年齢にかかわらず誰もが使えるように最初から設計するという考え方である。ホームドアは視覚障害者だけでなく、酔客や子ども、すべての利用者の転落を防ぐ。

出典：厚生労働省ホームページ 第118回医師国家試験 F001',
     '{"A": "手話通訳は聴覚障害者を対象とした支援である。", "B": "電動車椅子は歩行が困難な人のための福祉用具である。", "C": "点字ブロックは視覚障害者を対象とした設備である。", "D": "障害者用駐車場も対象を限定した設備で、バリアフリーの考え方にあたる。"}'),
    ('118-F-2', '正答は B「白内障」。

放射線白内障は被曝から数か月から数年を経て現れる晩発影響(晩期障害)である。しきい値のある確定的影響で、水晶体の等価線量限度が定められている。

出典：厚生労働省ホームページ 第118回医師国家試験 F002',
     '{"A": "脱毛は被曝後数週で現れる早期(急性)反応である。", "C": "運動失調は胎内被曝や大量被曝による中枢神経症状で、急性期に現れる。", "D": "けいれんは中枢神経症候群として被曝直後に現れる。", "E": "皮膚紅斑も被曝後数時間から数週で現れる早期反応である。"}'),
    ('118-F-3', '正答は E「背部の外傷は側臥位にして確認する。」。

骨盤骨折が疑われる患者を側臥位にすると、骨折部がずれて後腹膜出血を悪化させる。背部の観察は頭部・体幹を一直線に保ったまま複数人で行うログロールで、必要最小限にとどめる。

出典：厚生労働省ホームページ 第118回医師国家試験 F003',
     '{"A": "後腹膜への大量出血をきたすため、血圧の推移の確認は必須である。", "B": "骨盤輪の転位を反映して下肢の脚長差が生じる。", "C": "打撲痕や皮下出血は受傷部位と外力の方向を示す手がかりになる。", "D": "外尿道口からの出血は尿道損傷を示唆し、盲目的な導尿を避ける判断につながる。"}'),
    ('118-F-4', '正答は C「労働災害」。

医療計画には5疾病(がん・脳卒中・心筋梗塞等の心血管疾患・糖尿病・精神疾患)と6事業(救急医療、災害時医療、新興感染症対応、へき地医療、周産期医療、小児医療)、在宅医療、地域医療構想、医療従事者の確保などを定める。労働災害は労働者災害補償保険法の領域で、医療計画の記載事項ではない。

出典：厚生労働省ホームページ 第118回医師国家試験 F004',
     '{"A": "救急医療は医療計画の事業に含まれる。", "B": "精神疾患は5疾病の一つとして含まれる。", "D": "地域医療構想は医療計画の一部として定められる。", "E": "医療従事者の確保も医療計画の記載事項である。"}'),
    ('118-F-5', '正答は D「中高生の1日のゲームの使用時間」。

健やか親子21(第2次)は、切れ目ない妊産婦・乳幼児への保健対策、学童期・思春期の健やかな体の育成、子どもの健やかな成長を見守る地域づくりを基盤課題とし、育てにくさを感じる親への支援と妊娠期からの児童虐待防止を重点課題としている。ゲームの使用時間は指標に含まれない。

出典：厚生労働省ホームページ 第118回医師国家試験 F005',
     '{"A": "十代の飲酒率は学童期・思春期の課題の指標である。", "B": "妊婦の喫煙率は妊娠期の指標である。", "C": "低出生体重児の割合も指標に含まれる。", "E": "積極的に育児をしている父親の割合も指標に含まれる。"}'),
    ('118-F-6', '正答は B「赤芽球癆 — シクロスポリン」。

赤芽球癆は赤芽球系のみが選択的に障害される病態で、Tリンパ球による自己免疫機序が関与する。シクロスポリンなどの免疫抑制療法が有効である。

出典：厚生労働省ホームページ 第118回医師国家試験 F006',
     '{"A": "腎性貧血にはエリスロポエチン製剤やHIF-PH阻害薬を用いる。", "C": "巨赤芽球性貧血の治療はビタミンB12または葉酸の補充である。", "D": "慢性炎症に伴う貧血では鉄は貯蔵鉄として封じ込められており、鉄剤は無効である。原疾患の治療が優先される。", "E": "自己免疫性溶血性貧血の第一選択は副腎皮質ステロイドである。"}'),
    ('118-F-8', '正答は A「バンコク憲章」。

バンコク憲章(2005年)はグローバル化した世界におけるヘルスプロモーションを主題とし、オタワ憲章の理念を発展させた文書である。

出典：厚生労働省ホームページ 第118回医師国家試験 F008',
     '{"B": "リスボン宣言は患者の権利に関する世界医師会の宣言である。", "C": "ジュネーブ宣言は医師の職業倫理の誓いである。", "D": "ヘルシンキ宣言は人を対象とする医学研究の倫理原則である。", "E": "アルマ・アタ宣言はプライマリヘルスケアの理念を打ち出した宣言である。"}'),
    ('118-F-10', '正答は C「2000年代」。

我が国の総人口は2008年をピークに、以後は減少に転じている。少子化により出生数が死亡数を下回る自然減が定着したためである。

出典：厚生労働省ホームページ 第118回医師国家試験 F010',
     '{"A": "1980年代はまだ人口が増加していた。", "B": "1990年代も増加が続いていた。合計特殊出生率の低下が問題になり始めた時期である。", "D": "2010年代は既に減少が続いていた時期で、転じた時期ではない。", "E": "2020年代も減少が続いている。"}'),
    ('118-F-11', '正答は D「インドメタシン — 動脈管収縮」。

インドメタシンなどのNSAIDはプロスタグランジンの合成を抑えるため、胎児の動脈管を収縮させる。妊娠後期の使用は避ける。

出典：厚生労働省ホームページ 第118回医師国家試験 F011',
     '{"A": "ACE阻害薬は胎児の腎機能を障害して尿量を減らすため、羊水過少症をきたす。", "B": "吸入副腎皮質ステロイドは喘息の管理に必要で、妊娠中も継続する。早産の原因にはならない。", "C": "ミソプロストールは子宮収縮を起こして流産を招く。脳出血ではない。", "E": "ミノサイクリンなどのテトラサイクリン系は胎児の歯の着色と骨形成の抑制をきたす。水腎症ではない。"}'),
    ('118-F-12', '正答は A「60分以下」。

分娩第2期(子宮口全開大から児娩出まで)の所要時間は、初産婦で2〜3時間、経産婦では1時間以下が目安である。これを超えて進行しない場合は遷延を疑う。

出典：厚生労働省ホームページ 第118回医師国家試験 F012',
     '{"B": "61〜120分は初産婦の目安に近い。", "C": "121〜180分も初産婦の範囲で、経産婦では遷延を考える。", "D": "181〜240分は初産婦でも遷延にあたる。", "E": "241分以上はいずれの場合も明らかな遷延である。"}'),
    ('118-F-13', '正答は A「後負荷の減少」。

後負荷が減れば左室は同じ収縮力でより多くの血液を駆出できるため、1回拍出量が増えて心拍出量が増加する。血管拡張薬が心不全に有効な理由でもある。

出典：厚生労働省ホームページ 第118回医師国家試験 F013',
     '{"B": "心拍出量は1回拍出量と心拍数の積なので、心拍数が減れば減少する。", "C": "前負荷が減ればFrank-Starlingの法則により1回拍出量が減る。", "D": "冠血流量が減れば心筋の収縮力が落ち、心拍出量は減る。", "E": "甲状腺機能低下では心拍数と心収縮力が落ち、心拍出量は減る。"}'),
    ('118-F-14', '正答は A「医療扶助」。

生活保護の8つの扶助のうち、医療扶助と介護扶助は現物給付である。医療扶助では自己負担なく指定医療機関で医療を受けられ、費用は直接医療機関に支払われる。

出典：厚生労働省ホームページ 第118回医師国家試験 F014',
     '{"B": "教育扶助は義務教育に必要な費用を金銭で支給する。", "C": "住宅扶助は家賃相当額を金銭で支給する。", "D": "生活扶助は日常生活に必要な費用を金銭で支給する。", "E": "葬祭扶助も費用を金銭で支給する。"}'),
    ('118-F-15', '正答は E「有害物質使用工程の密閉化」。

労働衛生の3管理のうち作業環境管理は、有害要因そのものを作業環境から取り除く対策である。有害物質を扱う工程を密閉化して発散を断つのは、その典型で最も効果が高い。

出典：厚生労働省ホームページ 第118回医師国家試験 F015',
     '{"A": "安全な手順の教育は労働衛生教育にあたる。", "B": "作業時間の制限は作業管理にあたる。", "C": "防塵マスクの使用は個人が曝露を減らす対策で、作業管理にあたる。", "D": "血中鉛高値者への保健指導は健康管理にあたる。"}'),
    ('118-F-17', '正答は C「慢性骨髄性白血病」。

慢性骨髄性白血病では成熟した顆粒球系細胞が骨髄外造血の場である脾臓に浸潤し、臍を越えるほどの著明な脾腫をきたす。左季肋部の膨満感や早期満腹感が受診の契機になる。

出典：厚生労働省ホームページ 第118回医師国家試験 F017',
     '{"A": "多発性骨髄腫では形質細胞が骨髄内で増え、脾腫は通常みられない。", "B": "急性骨髄性白血病でも脾腫はあっても軽度である。", "D": "急性リンパ性白血病では肝脾腫やリンパ節腫脹をみるが、著明な脾腫は特徴的でない。", "E": "成人T細胞白血病・リンパ腫では高カルシウム血症、皮疹、リンパ節腫脹が主体である。"}'),
    ('118-F-19', '正答は E「臨床経過と病理解剖の所見を比較検討する。」。

臨床病理検討会は、亡くなった患者の臨床経過と病理解剖で得られた所見を突き合わせ、診断や治療が適切だったかを検討する場である。臨床研修の必修項目でもある。

出典：厚生労働省ホームページ 第118回医師国家試験 F019',
     '{"A": "治療法の相談はキャンサーボードなど別の場で行う。", "B": "入院中の症例の検討はカンファレンスで行う。CPCは剖検例が対象である。", "C": "医療行為と事故の因果関係の評価は医療事故調査の枠組みで行う。", "D": "術式の検討は術前カンファレンスで行う。"}'),
    ('118-F-20', '正答は B「腹部超音波」。

ラジオ波焼灼術は腹部超音波でリアルタイムに病変を描出しながら、経皮的に電極針を腫瘍へ刺入して行う。焼灼範囲の確認にも用いる。

出典：厚生労働省ホームページ 第118回医師国家試験 F020',
     '{"A": "MRIは治療前の病変の同定に用いるが、通常この手技の穿刺誘導には使わない。", "C": "超音波内視鏡は消化管壁や膵の観察に用いる。", "D": "血管造影は肝動脈化学塞栓療法で用いる。", "E": "上部消化管内視鏡は食道・胃・十二指腸の観察に用いる。"}'),
    ('118-F-21', '正答は B「脈圧」。

加齢により大血管の弾性が失われて収縮期血圧が上がり、拡張期血圧は下がるため脈圧が増大する。これが収縮期高血圧の主な機序である。

出典：厚生労働省ホームページ 第118回医師国家試験 F021',
     '{"A": "骨量は加齢とともに減少する。", "C": "肺の弾性が失われ胸郭も硬くなるため、肺活量は減少する。", "D": "心筋の線維化により拡張能は低下する。", "E": "糸球体濾過量も加齢とともに低下する。"}'),
    ('118-F-22', '正答は D「植込み型ペースメーカ」。

植込み型ペースメーカは血液と接する人工物が電極先端に限られ、血流も妨げないため抗凝固療法を要さない。心房細動などの合併があれば別の理由で抗凝固薬を用いる。

出典：厚生労働省ホームページ 第118回医師国家試験 F022',
     '{"A": "ECMOは血液を体外の回路に通すため抗凝固が必須である。", "B": "人工心肺装置も体外循環であり抗凝固が必須である。", "C": "機械弁は血栓を生じやすく、ワルファリンによる生涯の抗凝固が必要である。", "E": "植込み型補助人工心臓もポンプ内の血栓形成を防ぐため抗凝固が必須である。"}'),
    ('118-F-23', '正答は A「t検定」。

血圧のような連続変数の平均を2群で比べるにはt検定を用いる。分布が正規でなければMann-WhitneyのU検定などノンパラメトリック法を使う。

出典：厚生労働省ホームページ 第118回医師国家試験 F023',
     '{"B": "χ2検定は割合など質的データの分布を比べるのに用いる。", "C": "生存分析は事象が起こるまでの時間を扱う。", "D": "比例ハザードモデルは生存時間に対する複数因子の影響をみる。", "E": "ロジスティック回帰は2値の結果に対する複数因子の影響をみる。"}'),
    ('118-F-24', '正答は C「複数の臼歯が生える。」。

離乳は生後5〜6か月ごろに始めるが、乳歯が生え始めるのはそのころで、臼歯が生えそろうのは1歳半以降である。臼歯の萌出を待つ必要はない。

出典：厚生労働省ホームページ 第118回医師国家試験 F024',
     '{"A": "支えがあれば座位を保てることは、安全に食べさせるための目安になる。", "B": "大人が食べる様子に関心を示すことは、離乳開始のよい合図である。", "D": "定頸は誤嚥を防ぐうえで欠かせない前提である。", "E": "哺乳反射が減弱してスプーンを受け入れられることが目安になる。"}'),
    ('118-F-25', '正答は E「連合弛緩」。

連合弛緩は考えのつながりが緩んで話がまとまらなくなる思考の障害(思考過程の障害)であり、知覚の障害ではない。

出典：厚生労働省ホームページ 第118回医師国家試験 F025',
     '{"A": "幻嗅は対象のない匂いを感じる知覚の障害である。", "B": "幻視も対象のない視覚体験で知覚の障害である。", "C": "思考化声は自分の考えが声として聞こえる幻聴の一種である。", "D": "体感幻覚は身体の内部に生じる異常な感覚で、知覚の障害である。"}'),
    ('118-F-26', '正答は E「腕頭動脈」。

腕頭動脈は大動脈弓から分かれて胸骨柄の背側を走り、右鎖骨下動脈と右総頸動脈に分かれる。頸部の体表からは圧迫できない位置にある。

出典：厚生労働省ホームページ 第118回医師国家試験 F026',
     '{"A": "気管は前頸部の皮下にあり、強く圧迫すれば閉塞して窒息する。", "B": "外頸静脈は胸鎖乳突筋の表層を走り、圧迫で容易に閉塞する。", "C": "総頸動脈は胸鎖乳突筋の内側で触知でき、圧迫できる。", "D": "内頸静脈も頸動脈鞘内にあり、圧迫の影響を受ける。"}'),
    ('118-F-27', '正答は C「①4 ②5 ③1」。

後期高齢者医療制度の財源は、患者負担を除くと公費が約5割、現役世代からの支援金が約4割、高齢者本人の保険料が約1割で構成される。したがって①4割、②5割、③1割となる。

出典：厚生労働省ホームページ 第118回医師国家試験 F027',
     '{"A": "支援金2割・公費5割・保険料3割では、支援金と保険料の割合が実際と食い違う。", "B": "公費が3割では、財源の半分を公費が占めるという構成を説明できない。", "D": "支援金5割・公費2割は、公費と支援金の関係が逆転している。", "E": "支援金5割・公費4割も、公費が最大の財源であるという構成に合わない。"}'),
    ('118-F-28', '正答は C「遠隔医療の推進」。

持続可能な開発目標は貧困、飢餓、保健、教育、ジェンダー、水、エネルギー、経済成長、不平等、気候変動など17の目標からなる。遠隔医療の推進という個別の手段は目標に掲げられていない。

出典：厚生労働省ホームページ 第118回医師国家試験 F028',
     '{"A": "目標1はあらゆる場所のあらゆる形態の貧困を終わらせることである。", "B": "目標10は国内および国家間の不平等を是正することである。", "D": "目標5はジェンダー平等の達成である。", "E": "目標13は気候変動とその影響に立ち向かうための緊急対策である。"}'),
    ('118-F-29', '正答は C「脂肪細胞での中性脂肪分解促進」。

インスリンは同化ホルモンで、脂肪細胞ではリポ蛋白リパーゼを活性化して中性脂肪の合成・蓄積を促し、ホルモン感受性リパーゼを抑えて分解を抑制する。分解を促進するという記述は逆である。

出典：厚生労働省ホームページ 第118回医師国家試験 F029',
     '{"A": "肝での糖新生を抑えて血糖の上昇を防ぐ。", "B": "肝でグリコーゲン合成を促し、グルコースを貯蔵する。", "D": "骨格筋へのアミノ酸取り込みと蛋白合成を促す。", "E": "GLUT4の細胞膜への移動を促して骨格筋のグルコース取り込みを増やす。"}'),
    ('118-F-30', '正答は D「リスクファクターの数に応じて対象者を抽出する。」。

特定保健指導は特定健康診査の結果から、腹囲や体格に加えて血糖・脂質・血圧・喫煙という危険因子の数によって動機付け支援と積極的支援に階層化して対象者を選ぶ。

出典：厚生労働省ホームページ 第118回医師国家試験 F030',
     '{"A": "実施主体は医療保険者である。", "B": "対象は40歳から74歳までである。", "C": "根拠法は高齢者の医療の確保に関する法律である。", "E": "危険因子をもつ個人を選んで介入するハイリスクストラテジーである。"}'),
    ('118-F-37', '正答は B「呼気延長」。

気管支喘息の中発作である。末梢気道が狭窄するため呼気に時間がかかり、聴診で呼気の延長とwheezesを聴取する。胸部エックス線写真の肺過膨張も呼出障害を反映している。

出典：厚生労働省ホームページ 第118回医師国家試験 F037',
     '{"A": "嗄声は喉頭の病変でみられる。喘息では生じない。", "C": "犬吠様咳嗽はクループ(急性喉頭蓋炎・急性声門下喉頭炎)の症状である。", "D": "無呼吸発作は乳児の細気管支炎や百日咳でみられる。", "E": "レプリーゼは百日咳の痙咳発作の後にみられる笛声様の吸気である。"}'),
    ('118-F-38', '正答は B「非侵襲的陽圧換気〈NPPV〉」。

pH7.32、PaCO2 60Torrと急性増悪した慢性II型呼吸不全で、意識は清明で喀痰も少ない。非侵襲的陽圧換気は換気を助けて二酸化炭素を洗い出し、挿管を回避できる。

出典：厚生労働省ホームページ 第118回医師国家試験 F038',
     '{"A": "意識が保たれ気道分泌も多くないので、まずNPPVを試みる。", "C": "気道の可逆性狭窄が主体ではなく、β2刺激薬では換気不全は改善しない。", "D": "グルココルチコイドは慢性閉塞性肺疾患の急性増悪で補助的に用いるが、換気不全そのものを是正しない。", "E": "高流量の酸素はCO2ナルコーシスを招く。目標SpO2を88〜92%程度に抑える。"}'),
    ('118-F-39', '正答は D「大泉門」。

在胎期間の推定にはNew Ballard法などを用い、皮膚の成熟度、うぶ毛、足底のしわ、乳房・乳輪の発達、耳介の軟骨、外性器といった身体的成熟の指標と神経学的所見を組み合わせる。大泉門の大きさは在胎期間を反映しない。

出典：厚生労働省ホームページ 第118回医師国家試験 F039',
     '{"A": "乳輪の隆起と乳腺組織の触知量は成熟の指標である。", "B": "皮膚の厚さ、透見される血管、落屑の程度は成熟の指標である。", "C": "うぶ毛は在胎28週ごろ全身を覆い、満期に近づくと減る。", "E": "足底のしわは満期に近づくほど足底全体に広がる。"}'),
    ('118-F-41', '正答は C「「入院して治療をしましょう」」。

日齢14で38.8°Cの発熱があり、活気不良で大泉門が膨隆している。新生児の発熱は細菌性髄膜炎や敗血症を想定して、入院のうえ血液・尿・髄液を培養し、直ちに抗菌薬を開始する。

出典：厚生労働省ホームページ 第118回医師国家試験 F041',
     '{"A": "急速に悪化しうるため、翌日まで待つことは許されない。", "B": "経口の抗菌薬では髄液移行が不十分で、外来治療の対象にならない。", "D": "冷却は解熱の手段にすぎず、原因の検索と治療が優先される。", "E": "母乳を人工乳に変える理由はない。"}'),
    ('118-F-42', '正答は B「利尿薬の投与」。

径8mmの心室中隔欠損を介する多量の左右短絡により肺うっ血と体重増加不良をきたしている。手術までの橋渡しとして、まず利尿薬で肺うっ血と容量負荷を軽減する。

出典：厚生労働省ホームページ 第118回医師国家試験 F042',
     '{"A": "酸素は肺血管を拡張させて左右短絡をさらに増やすため、この病態では有害になりうる。", "C": "β遮断薬は乳児の急性期心不全の第一選択にならない。", "D": "アドレナリンは心拍出量が保たれている本例には不要で、体血管抵抗を上げて短絡を増やす。", "E": "肺血管拡張薬は肺血流をさらに増やし、短絡を悪化させる。"}'),
    ('118-F-44', '正答は E「ホルムアルデヒド」。

内装の改修後から屋内で症状が出て、換気のよい日は軽い。合板や接着剤から放散するホルムアルデヒドによるシックハウス症候群である。建築基準法で使用が規制され、換気設備の設置が義務づけられている。

出典：厚生労働省ホームページ 第118回医師国家試験 F044',
     '{"A": "オゾンは光化学スモッグや複写機から生じるもので、内装材からは放散しない。", "B": "エタノールは室内空気汚染の主要な原因物質ではない。", "C": "二酸化窒素は燃焼機器や自動車排ガスから生じる。", "D": "フロンガスはオゾン層破壊の原因物質で、室内での健康被害は問題にならない。"}'),
    ('118-F-45', '正答は B「II」。

意思疎通ができ、着替え・食事・排泄・入浴が自立している一方で、服薬と金銭の管理には家族の助けが要る。誰かが注意していれば自立できる段階なのでランクIIにあたる。

出典：厚生労働省ホームページ 第118回医師国家試験 F045',
     '{"A": "ランクIは日常生活がほぼ自立している段階で、服薬管理に助けが必要な本例は当てはまらない。", "C": "ランクIIIは介護を必要とする段階で、基本的な日常生活動作が自立している本例より重い。", "D": "ランクIVは常に介護を必要とする段階である。", "E": "ランクMは著しい精神症状や問題行動があり専門医療を要する段階だが、周辺症状も問題行動もない。"}'),
    ('118-F-46', '正答は D「カリウム」。

eGFR15.3mL/分/1.73m2の高度腎機能低下にK5.8mEq/Lの高カリウム血症を伴い、カリウム摂取量3,500mg/日は過剰である。1,500mg/日程度への制限が要る。塩分5.8g/日と蛋白質30g/日はすでに目標を満たしている。

出典：厚生労働省ホームページ 第118回医師国家試験 F046',
     '{"A": "塩分5.8g/日は6g/日未満の目標を満たしており、これ以上の制限は要らない。", "B": "浮腫は軽度で、飲水1.5L/日は過剰ではない。", "C": "蛋白質30g/日は体重52kgに対し0.6g/kgで、既に十分制限されている。", "E": "体重は1年間変化なく、エネルギー摂取は適正である。"}'),
    ('118-F-50', '正答は E「精神保健福祉センター」。

精神保健福祉センターは都道府県・指定都市に置かれ、精神保健と精神障害者の福祉に関する相談指導、社会復帰の支援、関係機関の情報提供を担う。復職支援や緊急時の受診先の相談窓口として適している。

出典：厚生労働省ホームページ 第118回医師国家試験 F050',
     '{"A": "グループホームは共同生活を送る住まいで、相談窓口ではない。", "B": "労働基準監督署は労働条件と安全衛生の監督を行う機関である。", "C": "就労移行支援事業所は就労のための訓練を行う場で、緊急受診先の情報提供は担わない。", "D": "知的障害者を対象とする施設であり、本例には該当しない。"}'),
    ('118-F-51', '正答は D「4」。

1歳6か月では積み木を2〜3個積めるのが標準で、つまめても積めないのは微細運動の遅れを疑う。ほかの下線部はこの月齢としてふつうにみられる。

出典：厚生労働省ホームページ 第118回医師国家試験 F051',
     '{"A": "両足で跳べるようになるのは2歳ごろで、できなくてよい。", "B": "階段を降りられるようになるのは2歳ごろである。", "C": "直線をまねしてひけるようになるのは2歳ごろである。", "E": "絵を見て物の名前を言えるようになるのは2歳前後で、1歳6か月では指させれば十分である。"}'),
    ('118-F-52', '正答は E「びまん性汎細気管支炎」。

小児期からの副鼻腔炎を思わせる経過に、慢性の膿性痰と労作時呼吸困難が加わり、胸部CTでびまん性小葉中心性粒状影を認めておりびまん性汎細気管支炎である。マクロライド少量長期療法が奏効する。

出典：厚生労働省ホームページ 第118回医師国家試験 F052',
     '{"A": "肺気腫は喫煙者に生じ、CTでは低吸収域をみる。喫煙歴はない。", "B": "粟粒結核では大きさのそろった粒状影が全肺野に均等に分布し、発熱や全身症状を伴う。", "C": "気管支拡張症では拡張した気管支と気管支壁の肥厚をみる。小葉中心性粒状影が主体ではない。", "D": "慢性気管支炎では画像所見に乏しい。"}'),
    ('118-F-53', '正答は C「強迫性障害〈強迫症〉」。

菌が付いているという考えが不合理と分かりながら消えず、洗浄行為が長時間に及んで仕事も家族関係も損なわれている。疎通は良好で病識も保たれており強迫性障害である。SSRIと曝露反応妨害法が治療の中心となる。

出典：厚生労働省ホームページ 第118回医師国家試験 F053',
     '{"A": "統合失調症では不合理性の自覚が失われ、疎通性も損なわれることが多い。", "B": "症状性精神障害は身体疾患に伴う精神症状で、意識障害や認知機能低下を伴う。", "D": "身体症状症は身体の苦痛と、それへのとらわれが中心で、洗浄強迫は説明できない。", "E": "素行障害は他者の権利を侵害する反復的な行動が特徴で、本例とは異なる。"}'),
    ('118-F-54', '正答は C「地域医療支援病院へ紹介する。」。

誤嚥性肺炎による呼吸不全と血圧低下があり、在宅では対応できない。地域医療支援病院はかかりつけ医からの紹介患者を受け入れて入院治療を担う病院で、紹介先として適している。

出典：厚生労働省ホームページ 第118回医師国家試験 F054',
     '{"A": "介護医療院は長期療養の生活の場で、急性期の治療を担わない。", "B": "特定機能病院は高度先進医療を担う施設で、標準的な肺炎治療の紹介先ではない。", "D": "地域包括支援センターは介護予防と相談支援の窓口で、急性期の治療は行わない。", "E": "特別養護老人ホームも生活の場であり、急性期治療の場ではない。"}'),
    ('118-F-55', '正答は E「抗dsDNA抗体」。

若年女性の顔面紅斑、多関節炎、蛋白尿、汎血球減少に高ガンマグロブリン血症を伴っており全身性エリテマトーデスである。抗dsDNA抗体は疾患特異性が高く、抗体価はループス腎炎の活動性とよく相関する。

出典：厚生労働省ホームページ 第118回医師国家試験 F055',
     '{"A": "抗CCP抗体は関節リウマチに特異的である。腎障害や血球減少は説明できない。", "B": "抗Jo-1抗体は多発性筋炎・皮膚筋炎に伴い、間質性肺炎と関連する。CKは正常である。", "C": "抗Mi-2抗体も皮膚筋炎に特異的な抗体である。", "D": "抗Scl-70抗体はびまん皮膚硬化型全身性強皮症に特異的である。皮膚硬化はない。"}'),
    ('118-F-56', '正答は D「輪状甲状靱帯切開」。

換気も気管挿管もできない状況(cannot ventilate, cannot intubate)であり、輪状甲状靱帯を切開して外科的に気道を確保する。低酸素が続けば数分で心停止に至るため、ためらわず移行する。

出典：厚生労働省ホームページ 第118回医師国家試験 F056',
     '{"A": "ECMOの導入には時間がかかり、気道確保の代わりにならない。", "B": "頸動脈を触知でき心停止ではないので、胸骨圧迫の適応ではない。", "C": "徐脈による循環不全ではなく、ペーシングは無効である。", "E": "大動脈内バルーンパンピングは心原性ショックの補助循環で、換気の問題は解決しない。"}'),
    ('118-F-57', '正答は D「4」。

腸重積症の既往はロタウイルスワクチンの接種禁忌である。ワクチン接種後に腸重積の危険がわずかに高まるためで、初回接種の月齢上限も定められている。

出典：厚生労働省ホームページ 第118回医師国家試験 F057',
     '{"A": "在胎36週2日の早産は禁忌にあたらない。暦月齢に従って接種する。", "B": "出生体重2,460gの低出生体重も禁忌にならない。", "C": "卵円孔開存は器質的心疾患ではなく、禁忌にならない。", "E": "体温37.0°Cは明らかな発熱(37.5°C以上)にあたらず、接種できる。"}'),
    ('118-F-64', '正答は B「1」。

徒手筋力テストは、筋の収縮が触れるが関節は動かない段階を1と評価する。本例は大腿四頭筋の収縮を認めるが関節運動は認めないため1である。

出典：厚生労働省ホームページ 第118回医師国家試験 F064',
     '{"A": "収縮そのものがまったく触れない場合が0である。", "C": "重力を除けば全可動域を動かせる場合が2である。", "D": "重力に抗して全可動域を動かせる場合が3である。", "E": "ある程度の抵抗に抗して動かせる場合が4である。"}'),
    ('118-F-65', '正答は D「第10胸髄」。

感覚障害の上縁が臍の高さにあり、臍は第10胸髄の皮膚分節にあたる。上肢の筋力は正常で、両下肢は筋収縮のみで関節運動がない。第10胸髄の高さの脊髄損傷である。

出典：厚生労働省ホームページ 第118回医師国家試験 F065',
     '{"A": "頸髄の損傷なら上肢にも筋力低下が出る。本例の上肢は正常である。", "B": "第1胸髄では手の内在筋が障害される。", "C": "第5胸髄なら感覚障害の上縁はもっと頭側になる。", "E": "第1腰髄では感覚障害の上縁が鼠径部の高さになり、臍より下になる。"}'),
    ('118-F-66', '正答は D「標準型車椅子」。

上肢の筋力は正常で、下肢は3か月経っても回復していない。自分で駆動できる標準型車椅子を使えば、移動の自立を保てる。

出典：厚生労働省ホームページ 第118回医師国家試験 F066',
     '{"A": "歩行器は下肢で体重を支えられることが前提で、この患者には使えない。", "B": "短下肢装具は足関節を補助する装具で、立位が取れない患者の役には立たない。", "C": "上肢が使えるので自走式で足り、電動車椅子は必要以上の機能になる。", "E": "リフトは移乗が全介助になる場合の用具で、上肢が使える本例では自立を狭めてしまう。"}'),
    ('118-F-68', '正答は D「D」。

Cockcroft-Gaultの式に当てはめると、クレアチニンクリアランスは(140−80)×72/(72×1.0)＝60mL/分となる。アンピシリンは感受性試験で耐性、メロペネムは広すぎるので、感性のセファゾリンを選ぶ。クリアランスが50を超える欄のセファゾリンがDである。

出典：厚生労働省ホームページ 第118回医師国家試験 F068',
     '{"A": "アンピシリンの欄だが、感受性試験で耐性と判定されており使えない。", "B": "同じくアンピシリンで、腎機能の区分も本例に当たらない。", "C": "同じくアンピシリンで、高度腎機能低下の区分である。", "E": "セファゾリンだがクリアランスが50以下の区分で、本例の60mL/分には当たらない。"}'),
    ('118-F-70', '正答は B「気管挿管」。

縮瞳、著明な発汗、口周囲の分泌物、全身のけいれんがあり、有機リン中毒を疑う。リザーバー付マスクで酸素を投与してもSpO2が上がらず、気道分泌物と呼吸筋の障害で換気が保てない。まず気管挿管を行う。

出典：厚生労働省ホームページ 第118回医師国家試験 F070',
     '{"A": "胃管による除染は気道を確保してからの手順で、先に行えば誤嚥を招く。", "C": "発熱はあるが、まず換気を確保しなければ全身冷却の意味がない。", "D": "血圧は保たれており、大量輸液を急ぐ状況ではない。", "E": "中心静脈カテーテルの留置は時間がかかり、この場面で優先しない。"}'),
    ('118-F-71', '正答は B「「落ちていた空の瓶は持ってきましたか」」。

中毒では原因物質が分かるかどうかで解毒薬の選択が変わる。倒れていた部屋にあった空の瓶が手元にあれば、成分をその場で確かめられ、有機リンであればアトロピンとプラリドキシムをすぐ始められる。

出典：厚生労働省ホームページ 第118回医師国家試験 F071',
     '{"A": "遺書は自殺企図の評価に要るが、搬入直後の治療内容を変えるものではない。", "C": "家族の通院歴は、いま投与する薬を決める材料にならない。", "D": "飲酒量は直後の治療を左右しない。", "E": "けいれんの既往は参考にはなるが、原因物質の特定ほど治療を変えない。"}'),
    ('118-F-72', '正答は A「コリン作動性」。

縮瞳、著明な発汗、分泌物の増加、けいれんが揃い、コリンエステラーゼが著明に低下している。有機リンによるコリン作動性のトキシドロームである。

出典：厚生労働省ホームページ 第118回医師国家試験 F072',
     '{"B": "交感神経興奮性では散瞳と高血圧が前面に出る。縮瞳とは合わない。", "C": "鎮静睡眠作用性では呼吸抑制と鎮静が主で、けいれんや分泌物の増加は伴わない。", "D": "オピオイド作動性でも縮瞳はみられるが、発汗と分泌物の増加やコリンエステラーゼの低下は説明できない。", "E": "ヒスタミン作用性では紅潮や掻痒が主体になる。"}'),
    ('119-A-1', '正答は A「膵の萎縮を認める。」。

自己免疫性膵炎では膵がびまん性に腫大し、いわゆるソーセージ様の形態を示す。萎縮ではなく腫大が特徴で、主膵管はびまん性に不整狭細化する。

出典：厚生労働省ホームページ 第119回医師国家試験 A001',
     '{"B": "60歳代以降の男性に多い。", "C": "リンパ球と形質細胞の浸潤に伴う線維化(花筵状線維化)と閉塞性静脈炎が病理学的特徴である。", "D": "IgG4関連疾患の膵病変にあたり、涙腺・唾液腺や胆管、後腹膜にも病変を伴うことがある。", "E": "グルココルチコイドが第一選択で、速やかに膵腫大と狭細化が改善する。"}'),
    ('119-A-2', '正答は A「頸肩腕障害」。

頸肩腕障害は、上肢を一定の姿勢で長時間使う作業により頸部から肩、上肢に痛みやしびれ、こりを生じる作業関連疾患である。VDT作業に従事する若年労働者に多く、作業姿勢と休憩の見直しが対策となる。

出典：厚生労働省ホームページ 第119回医師国家試験 A002',
     '{"B": "肩関節周囲炎は中年以降に多く、肩の可動域制限が主症状である。", "C": "肘部管症候群は尺骨神経の絞扼で、環指尺側と小指のしびれと小指球筋の萎縮をきたす。", "D": "変形性頸椎症は加齢による椎間板と椎間関節の変性で、中高年に多い。", "E": "頸椎後縦靱帯骨化症も中年以降に発症し、進行すると脊髄症状をきたす。"}'),
    ('119-A-4', '正答は E「ケラトアカントーマ — 臍部」。

ケラトアカントーマは日光に当たる顔面や手背などの露出部に生じ、中央にケラチン栓をもつ半球状の腫瘤として急速に増大する。臍部は好発部位ではない。

出典：厚生労働省ホームページ 第119回医師国家試験 A004',
     '{"A": "疥癬はヒゼンダニが手指間、腋窩、外陰部などの柔らかい皮膚に寄生する。外陰部の結節は男性で特徴的である。", "B": "ケロイドは前胸部、肩、恥骨部とともに耳介(ピアス孔)に好発する。", "C": "脂腺母斑は頭部の脱毛斑として生まれつき存在する。", "D": "血管性浮腫は口唇や眼瞼など疎な結合組織の部位に生じやすい。"}'),
    ('119-A-5', '正答は B「排尿前」。

家庭血圧は起床後1時間以内、排尿後、朝食前、服薬前に、座位で1〜2分の安静をとってから測る。膀胱が充満していると交感神経が刺激されて血圧が上がるため、排尿前ではなく排尿後に測る。

出典：厚生労働省ホームページ 第119回医師国家試験 A005',
     '{"A": "食事の影響を避けるため朝食前に測る。", "C": "降圧薬の効果が切れた時点の値をみるため服薬前に測る。", "D": "1〜2分の座位安静後に測ることが定められている。", "E": "起床後1時間以内に測ることで、早朝高血圧を捉えられる。"}'),
    ('119-A-7', '正答は E「連続性病変」。

潰瘍性大腸炎の炎症は直腸から連続性・びまん性に口側へ広がり、粘膜と粘膜下層にとどまる。この連続性が、区域性(skip lesion)に病変が分布するCrohn病との最大の鑑別点である。

出典：厚生労働省ホームページ 第119回医師国家試験 A007',
     '{"A": "敷石像は縦走潰瘍と横走潰瘍に囲まれた粘膜の隆起で、Crohn病の所見である。", "B": "縦走潰瘍もCrohn病に特徴的である。", "C": "全層性の炎症はCrohn病の特徴で、瘻孔や狭窄の原因となる。", "D": "難治性痔瘻もCrohn病でみられ、そこから診断されることがある。"}'),
    ('119-A-8', '正答は E「1日尿量が2,000mL以上となるように水分摂取が推奨される。」。

尿が濃縮されると結晶が析出しやすくなるため、1日尿量2,000mL以上を目標に水分を摂ることが結石成分によらず共通の予防策である。

出典：厚生労働省ホームページ 第119回医師国家試験 A008',
     '{"A": "カルシウム摂取を減らすと腸管でシュウ酸と結合する相手が減り、吸収されたシュウ酸が尿中に増えてかえって結石ができやすくなる。", "B": "尿酸結石では尿のアルカリ化、シスチン結石でも尿のアルカリ化と、成分ごとに予防法は異なる。", "C": "野菜と果実はクエン酸やカリウムを含み、結石の形成を抑える。摂取が勧められる。", "D": "ナトリウムの過剰摂取は尿中カルシウム排泄を増やすため、減塩が勧められる。"}'),
    ('119-A-9', '正答は D「再脱臼は若年者で生じやすい。」。

肩関節前方脱臼では関節唇や関節包が損傷し、若年者ほど修復が不十分で再脱臼しやすい。10歳代の発症では再脱臼率が高く、鏡視下の修復術が検討される。

出典：厚生労働省ホームページ 第119回医師国家試験 A009',
     '{"A": "合併しやすいのは腋窩神経麻痺で、三角筋の筋力低下と肩外側の知覚低下をきたす。", "B": "肩関節周囲炎は加齢に伴う退行性変化によるもので、脱臼が原因ではない。", "C": "肩関節脱臼の大部分(9割以上)は前方脱臼である。", "E": "外転・外旋を強制されたときに前方へ脱臼する。内転位ではない。"}'),
    ('119-A-10', '正答は A「SGLT2阻害薬 — 近位尿細管」。

SGLT2は近位尿細管に発現し、濾過されたグルコースの大部分を再吸収する。SGLT2阻害薬はこれを抑えて尿糖排泄を増やし、血糖低下に加え心・腎保護作用を示す。

出典：厚生労働省ホームページ 第119回医師国家試験 A010',
     '{"B": "抗アルドステロン薬が作用するのは集合管である。", "C": "サイアザイド系利尿薬は遠位尿細管のNa-Cl共輸送体を阻害する。", "D": "バソプレシンV2受容体は集合管にあり、拮抗薬は水利尿を起こす。", "E": "ループ利尿薬はHenleの太い上行脚のNa-K-2Cl共輸送体を阻害する。下行脚は水のみを通す。"}'),
    ('119-A-16', '正答は D「Kayser-Fleischer輪」。

小児の肝障害に、尿中銅排泄の増加、血清銅とセルロプラスミンの低下がそろっておりWilson病である。角膜Descemet膜への銅沈着によるKayser-Fleischer輪が細隙灯顕微鏡で確認できる。

出典：厚生労働省ホームページ 第119回医師国家試験 A016',
     '{"A": "円錐角膜は角膜が円錐状に突出する疾患で、銅代謝とは無関係である。", "B": "視神経萎縮はLeber遺伝性視神経症などでみられる。", "C": "白内障はGalactose血症やステロイド長期使用でみられる。Wilson病では特徴的な「ひまわり白内障」もあるが、診断に用いる代表的所見はKayser-Fleischer輪である。", "E": "桜実紅斑はTay-Sachs病やNiemann-Pick病などのライソゾーム病でみられる眼底所見である。"}'),
    ('119-A-17', '正答は C「腹部造影CT」。

造影CTは被曝を伴い、思春期の患者に毎回行うと生涯の発癌リスクが積み重なる。腫瘍マーカーと超音波で追跡し、異常が疑われたときにCTを行うのが適切である。

出典：厚生労働省ホームページ 第119回医師国家試験 A017',
     '{"A": "腹部触診は無侵襲で、腫瘤の再発を捉える基本の診察である。", "B": "化学療法後の卵巣機能を評価するため、月経の再開を確認する必要がある。", "D": "超音波検査は被曝がなく、残存卵巣と骨盤内の観察に適している。", "E": "AFPは卵黄囊腫瘍のマーカーで、再発を最も早く捉える指標である。"}'),
    ('119-A-19', '正答は D「自宅待機を指示する。」。

喀痰抗酸菌染色が陽性で排菌が確認された時点で、周囲への感染を防ぐ必要がある。すでに帰宅している患者には自宅待機を指示し、翌日以降の入院と届出につなげる。

出典：厚生労働省ホームページ 第119回医師国家試験 A019',
     '{"A": "本人の同意なく勤務先へ連絡することはできない。接触者健診は保健所が主体となって進める。", "B": "結核の届出は診断した時点で行うが、確定は培養や核酸増幅検査を待つ。まず本人の行動を制限して感染拡大を防ぐことが先である。", "C": "薬剤感受性を確かめる検体を採取したうえで、入院のうえ治療を始める。帰宅している患者にその場で投与はできない。", "E": "患者にはサージカルマスクを着用させる。N95マスクを着けるのは周囲の医療者である。"}'),
    ('119-A-25', '正答は E「Streptococcus agalactiae(GBS)」。

日齢20の細菌性髄膜炎で、生後1か月未満の起因菌としてはB群溶血性連鎖球菌(Streptococcus agalactiae)が最も多い。産道での垂直感染により生じ、大腸菌とともに新生児髄膜炎の二大起因菌である。

出典：厚生労働省ホームページ 第119回医師国家試験 A025',
     '{"A": "Haemophilus influenzaeは乳児期以降の起因菌で、Hibワクチンの普及により激減した。", "B": "Neisseria meningitidisは年長児や若年成人に多い。", "C": "Pseudomonas aeruginosaは院内感染や免疫不全でみられる。", "D": "Streptococcus pneumoniaeは生後3か月以降の主要な起因菌である。"}'),
    ('119-A-26', '正答は A「腹部造影CT」。

大量飲酒後の激しい心窩部痛にアミラーゼ2,048U/Lを認め、急性膵炎である。造影CTは膵の壊死範囲や周囲への炎症の波及を評価でき、重症度判定に必須である。

出典：厚生労働省ホームページ 第119回医師国家試験 A026',
     '{"B": "超音波検査は消化管ガスに妨げられ膵の全体像を捉えにくい。胆石の検索には有用である。", "C": "超音波内視鏡は急性期には侵襲が大きく、重症度の判定には向かない。", "D": "MRCPは胆管結石の検索に有用だが、膵の壊死範囲の評価は造影CTが優れる。", "E": "ERCPは膵炎を悪化させうるため、胆石性膵炎で胆管炎を伴う場合などに限られる。"}'),
    ('119-A-27', '正答は E「ビタミンB1」。

慢性の大量飲酒者に、意識障害・眼球運動障害・失調性歩行の三徴がそろっておりWernicke脳症である。ビタミンB1の測定結果を待たずに直ちに投与する。ブドウ糖を先に投与すると症状が悪化するので順序に注意する。

出典：厚生労働省ホームページ 第119回医師国家試験 A027',
     '{"A": "亜鉛欠乏は味覚障害や皮膚炎をきたすが、この三徴は説明できない。", "B": "貧血はあるが緊急に鉄剤を要する状態ではなく、原因の評価が先である。", "C": "葉酸欠乏も飲酒者にみられるが、Wernicke脳症を防ぐのはビタミンB1である。", "D": "ビタミンD欠乏は骨軟化症をきたすもので、急を要さない。"}'),
    ('119-A-30', '正答は C「血糖値の異常」。

食後数時間で空腹感とともに動悸・発汗・手指振戦が現れ、糖分の摂取で軽快する。耐糖能異常を背景とした反応性低血糖で、症状の原因は血糖値の異常である。

出典：厚生労働省ホームページ 第119回医師国家試験 A030',
     '{"A": "血圧142/88mmHgは軽度の上昇にすぎず、この症状の説明にならない。", "B": "更年期のホットフラッシュは時間帯や食事と無関係に起こり、糖分で改善しない。", "D": "スタチンの有害事象は筋症状と肝障害で、低血糖症状は起こさない。", "E": "TSHとFT4はいずれも基準内で、甲状腺機能は正常である。"}'),
    ('119-A-31', '正答は D「心臓カテーテル検査」。

労作時胸痛が増悪して安静時にも持続し、ST低下とトロポニンT陽性を認めており非ST上昇型急性冠症候群である。侵襲的検査(心臓カテーテル検査)による冠動脈の評価と血行再建を早期に行う。

出典：厚生労働省ホームページ 第119回医師国家試験 A031',
     '{"A": "症状が持続している状況で運動負荷をかけることは禁忌である。", "B": "冠動脈CTは低リスク例の除外に用いる検査で、この状況では治療の遅れにつながる。", "C": "心臓MRIは心筋症や心筋炎の評価に用いる。", "E": "薬物負荷心筋血流シンチグラフィも安定狭心症の評価に用いる検査である。"}'),
    ('119-A-32', '正答は D「HBV-DNA定量」。

HBs抗原陰性でHBc抗体陽性は既往感染を示す。リツキシマブを含む化学療法ではHBVが再活性化して劇症肝炎に至ることがあるため、治療前にHBV-DNA定量を行い、以後も定期的に監視する。

出典：厚生労働省ホームページ 第119回医師国家試験 A032',
     '{"A": "HBc抗原は血中で測定できない。", "B": "HBe抗原はHBs抗原陽性例でウイルス量の目安として測るもので、既往感染例の再活性化監視には用いない。", "C": "HBe抗体も同様に、再活性化の監視の指標にならない。", "E": "HCV抗体が陰性であり、HCV-RNAを測る意義はない。"}'),
    ('119-A-36', '正答は E「大腿骨遠位端」。

新生児マススクリーニング陽性で、哺乳力低下、遷延性黄疸、便秘、大泉門の開大、臍ヘルニアがそろっており先天性甲状腺機能低下症である。骨成熟の遅れをみるには、満期産児で通常存在する大腿骨遠位端骨核の有無を確認する。

出典：厚生労働省ホームページ 第119回医師国家試験 A036',
     '{"A": "頭蓋骨のエックス線写真では骨成熟を評価できない。", "B": "肋骨も骨年齢の指標にならない。", "C": "手根骨の骨核が現れるのは生後数か月以降で、新生児期の評価には使えない。", "D": "腰椎も骨成熟の指標にならない。"}'),
    ('119-A-39', '正答は E「de Quervain病」。

手関節橈側の腫脹と圧痛に加え、母指を握り込んで手関節を尺屈させると疼痛が誘発される(Finkelstein試験陽性)。短母指伸筋腱と長母指外転筋腱の腱鞘炎であるde Quervain病である。

出典：厚生労働省ホームページ 第119回医師国家試験 A039',
     '{"A": "ばね指は屈筋腱の腱鞘炎で、指の屈伸時に引っかかりや弾発現象を生じる。", "B": "関節リウマチは多関節の対称性腫脹をきたす。指関節に異常はない。", "C": "手根管症候群は正中神経の絞扼で、母指から環指橈側のしびれが主症状である。感覚障害はない。", "D": "肘部管症候群は尺骨神経の絞扼で、環指尺側と小指の症状をきたす。"}'),
    ('119-A-41', '正答は B「酸分泌抑制薬」。

内視鏡や画像で器質的異常がなく、心窩部痛と早期飽満感がストレスと関連して続いており機能性ディスペプシアである。心窩部痛症候群には酸分泌抑制薬が第一選択となる。

出典：厚生労働省ホームページ 第119回医師国家試験 A041',
     '{"A": "NSAIDは胃粘膜を傷害し、症状を悪化させる。", "C": "ニトログリセリンは狭心症に用いる。", "D": "グルココルチコイドは適応がなく、胃粘膜傷害の危険もある。", "E": "GLP-1受容体作動薬は胃排出を遅らせるため、早期飽満感を悪化させる。"}'),
    ('119-A-42', '正答は E「確定診断には核酸増幅検査が用いられる。」。

膿性の尿道分泌物にGram陰性双球菌を認め淋菌性尿道炎である。核酸増幅検査は感度が高く、咽頭を含む検体でも診断でき、クラミジアの同時検出も可能で確定診断に用いる。

出典：厚生労働省ホームページ 第119回医師国家試験 A042',
     '{"A": "潜伏期は2〜7日と短い。2〜3週間の潜伏期はクラミジアの特徴である。", "B": "無症状のパートナーも治療しなければ再感染(ピンポン感染)を繰り返す。", "C": "淋菌感染に終生免疫は成立せず、何度でも感染する。", "D": "ニューキノロン耐性が広がっており第一選択にならない。セフトリアキソンの単回静注を用いる。"}'),
    ('119-A-44', '正答は E「心臓リハビリテーション」。

左室駆出率が保たれた心不全で、入院5日目には酸素も不要となり食事も摂れている。高齢の心不全では安静を続けること自体が筋力と運動耐容能を奪うので、この時期から心臓リハビリテーションを始める。再入院を減らす効果も示されている。

出典：厚生労働省ホームページ 第119回医師国家試験 A044',
     '{"A": "貧血は軽度で、輸血を要する水準ではない。", "B": "室内気でSpO2が保たれており、酸素療法の適応がない。", "C": "駆出率は保たれ、房室ブロックと徐脈傾向もある。この時点でβ遮断薬を入れる状況ではない。", "D": "食事が摂れているので、静脈からの高カロリー投与ではなく経口摂取を支えるほうがよい。"}'),
    ('119-A-45', '正答は C「炭酸リチウム」。

昇進を機に多弁、浪費、活動性亢進をきたした躁状態である。カルバマゼピンでStevens-Johnson症候群を起こした既往があり、気分安定薬としては炭酸リチウムを選ぶ。腎機能と血中濃度の監視が要る。

出典：厚生労働省ホームページ 第119回医師国家試験 A045',
     '{"A": "ジアゼパムは不安や不眠に一時的に用いるだけで、躁状態の治療薬ではない。", "B": "イミプラミンなどの抗うつ薬は躁状態を増悪させる。", "D": "フェニトインは抗てんかん薬で、気分安定作用はない。またカルバマゼピンとの交差反応の危険もある。", "E": "カルバマゼピンは重篤な薬疹の既往があり禁忌である。"}'),
    ('119-A-46', '正答は D「Guillain-Barré症候群」。

先行感染の1週間後に、外眼筋麻痺・運動失調・腱反射消失の三徴が現れており、Guillain-Barré症候群の亜型であるFisher症候群である。抗GQ1b抗体が陽性となり、多くは自然に軽快する。

出典：厚生労働省ホームページ 第119回医師国家試験 A046',
     '{"A": "重症筋無力症では症状に日内変動があり、腱反射は保たれる。", "B": "多発性硬化症は時間的・空間的多発を示し、腱反射はむしろ亢進する。", "C": "進行性核上性麻痺は垂直方向の眼球運動障害と易転倒性をきたすが、年単位で緩徐に進行する。", "E": "筋萎縮性側索硬化症では眼球運動が保たれ、腱反射は亢進する。"}'),
    ('119-A-47', '正答は B「赤血球輸血」。

汎血球減少で骨髄は過形成、3系統に異形成を認め芽球は増えておらず骨髄異形成症候群(低リスク群)である。エリスロポエチンは10mIU/mLと低く反応が期待できないため、症状のある貧血には赤血球輸血で対応する。

出典：厚生労働省ホームページ 第119回医師国家試験 A047',
     '{"A": "血漿交換を要する病態ではない。", "C": "グルココルチコイドは再生不良性貧血にも骨髄異形成症候群にも標準治療とならない。", "D": "トロンボポエチン受容体作動薬は血小板減少に用いるが、Hb5.2g/dLの貧血が当面の問題である。", "E": "G-CSFは好中球減少に用いるもので、貧血は改善しない。"}'),
    ('119-A-53', '正答は C「急性間質性腎炎」。

抗菌薬の投与後に腎機能が急速に悪化し、尿中β2-マイクログロブリンが著明に上昇して尿糖も陽性である。尿細管障害を示す所見であり、薬剤性の急性間質性腎炎が最も考えられる。被疑薬の中止が治療の基本となる。

出典：厚生労働省ホームページ 第119回医師国家試験 A053',
     '{"A": "膜性腎症は高度の蛋白尿を呈するが、蛋白は(±)にとどまる。", "B": "血糖98mg/dL、HbA1c5.2%で糖尿病はない。尿糖陽性は尿細管での再吸収障害による。", "D": "急性糸球体腎炎では血尿と赤血球円柱、補体低下を認める。潜血陰性でC3も高値である。", "E": "急速進行性糸球体腎炎ではANCAや抗GBM抗体が陽性となり、血尿と赤血球円柱を認める。"}'),
    ('119-A-55', '正答は A「放射線治療」。

両側の骨盤壁に及ぶ子宮傍組織浸潤があり進行子宮頸癌(IIIB期以上)である。手術の適応はなく、根治を目指すには同時化学放射線療法を行う。出血の制御にも放射線治療が有効である。

出典：厚生労働省ホームページ 第119回医師国家試験 A055',
     '{"B": "血管新生阻害薬は化学療法との併用で再発・転移例に用いる。", "C": "骨盤壁に達する浸潤があり、広汎子宮全摘出術の適応外である。", "D": "動注化学療法は標準治療として位置づけられていない。", "E": "免疫チェックポイント阻害薬は既治療の再発・転移例が対象である。"}'),
    ('119-A-56', '正答は A「血漿交換」。

発熱、意識障害、血小板減少、破砕赤血球を伴う溶血性貧血、腎機能障害の五徴がそろい、PT・APTT・FDPが正常で血栓性血小板減少性紫斑病である。ADAMTS13活性の低下が本態で、直ちに血漿交換を行う。

出典：厚生労働省ホームページ 第119回医師国家試験 A056',
     '{"B": "血小板輸血は血栓形成を助長するため原則として避ける。", "C": "CRP0.8mg/dLと炎症所見に乏しく、感染症を示す所見はない。", "D": "FDP9μg/mLとPT・APTTは正常で播種性血管内凝固ではなく、ヘパリンの適応はない。", "E": "トロンボポエチン受容体作動薬は免疫性血小板減少性紫斑病に用いるもので、この病態には無効である。"}'),
    ('119-A-57', '正答は C「カルシウム拮抗薬」。

深夜から早朝の安静時に起こる胸痛が、器質的狭窄のないまま硝酸薬で速やかに消失しており冠攣縮性狭心症である。カルシウム拮抗薬が発作の予防に最も有効で、禁煙も欠かせない。

出典：厚生労働省ホームページ 第119回医師国家試験 A057',
     '{"A": "スタチンは動脈硬化の進展抑制に有用だが、攣縮そのものは抑えない。", "B": "DPP-4阻害薬は血糖降下薬で、攣縮には無効である。", "D": "ビスホスホネート製剤は骨粗鬆症の治療薬である。", "E": "ARBは降圧薬で、冠攣縮の予防薬としては位置づけられていない。β遮断薬はむしろ攣縮を誘発しうる。"}'),
    ('119-A-64', '正答は B「β遮断薬の投与」。

安静時痛と潰瘍・壊死を伴う包括的高度慢性下肢虚血で、浅大腿動脈の閉塞に対して血行再建を急ぐ。β遮断薬は末梢血管抵抗を高めて症状を悪化させうるため、この病態での投与は適切でない。

出典：厚生労働省ホームページ 第119回医師国家試験 A064',
     '{"A": "壊死と感染が制御できなければ切断もやむを得ず、選択肢として考慮される。", "C": "浅大腿動脈の長区間閉塞にはバイパス術が有力な選択肢である。", "D": "血管内治療による血行再建も第一に検討される。", "E": "プロスタグランジン製剤は血行再建が難しい場合の補助的治療として用いられる。"}'),
    ('119-A-65', '正答は C「「アドレナリン吸入を行います」」。

オットセイの鳴き声のような犬吠様咳嗽、吸気性喘鳴、陥没呼吸からクループ症候群(急性声門下喉頭炎)である。中等症以上ではアドレナリンの吸入で声門下の浮腫を速やかに減らす。デキサメタゾンの全身投与も併せて行う。

出典：厚生労働省ホームページ 第119回医師国家試験 A065',
     '{"A": "会話が可能で酸素化も保たれており、人工呼吸管理を要する段階ではない。", "B": "閉塞部位は声門下で、β2刺激薬は下気道に作用するため無効である。", "D": "アレルギー反応ではなく、抗ヒスタミン薬は効かない。", "E": "副腎皮質ステロイドは全身投与(経口・静注)を行う。吸入では十分な効果が得られない。"}'),
    ('119-A-68', '正答は B「自由に行動させて観察する。」。

言語発達の遅れ、独特の抑揚とオウム返し、視線の合いにくさ、同一性へのこだわりから自閉スペクトラム症が疑われる。診察室では自由に行動させ、その様子から対人関係やこだわりを観察するのが最も有用である。

出典：厚生労働省ホームページ 第119回医師国家試験 A068',
     '{"A": "押さえつけると強い抵抗を招き、以後の診察も難しくなる。", "C": "厳しい指示は理解されず、混乱を招くだけである。", "D": "養育が原因ではなく、両親を責めることは支援の妨げになる。", "E": "受診の機会を逃さず、この場で観察と評価を進める。"}'),
    ('119-B-1', '正答は A「鶏眼 — うおのめ」。

鶏眼は足底の圧迫部に角質が楔状に増殖したもので、俗に「うおのめ」と呼ばれる。中心の芯が真皮を圧迫して痛む。

出典：厚生労働省ホームページ 第119回医師国家試験 B001',
     '{"B": "「とびひ」は伝染性膿痂疹の俗称である。色素性母斑は「ほくろ」と呼ばれる。", "C": "「みずいぼ」は伝染性軟属腫の俗称である。水痘は「みずぼうそう」である。", "D": "「そばかす」は雀卵斑の俗称である。麦粒腫は「ものもらい」と呼ばれる。", "E": "「はしか」は麻疹の俗称である。風疹は「三日はしか」と呼ばれる。"}'),
    ('119-B-2', '正答は E「個人の経験に依存した判断」。

EBMは、疑問の定式化、情報の収集、批判的吟味、患者への適用、そして振り返りという5段階で進める。得られた根拠と患者の価値観、臨床医の技能を統合するもので、個人の経験だけに頼る判断はこれと対極にある。

出典：厚生労働省ホームページ 第119回医師国家試験 B002',
     '{"A": "得られた根拠を目の前の患者に当てはめられるかを検討する段階が含まれる。", "B": "定式化した疑問に答える文献を効率よく集める段階が含まれる。", "C": "研究デザインや結果の妥当性を吟味する段階が含まれる。", "D": "患者・介入・比較・結果の枠組みで疑問を定式化する段階が出発点になる。"}'),
    ('119-B-3', '正答は A「緩和ケアは在宅医療の中で実施できる。」。

緩和ケアは病院でも在宅でも提供でき、在宅では訪問診療と訪問看護、必要に応じて医療用麻薬の持続皮下注などを組み合わせて行う。住み慣れた場所で過ごしたいという希望に応えられる。

出典：厚生労働省ホームページ 第119回医師国家試験 B003',
     '{"B": "計画的に定期訪問するのが訪問診療で、緊急時に出向くのは往診である。", "C": "使用済みの注射針は感染性産業廃棄物として処理する。", "D": "我が国の死亡場所は病院が最も多く、在宅はその半分にも満たない。", "E": "要介護認定を受けていれば原則として介護保険が優先される。厚生労働大臣が定める疾病等や急性増悪時には医療保険となる。"}'),
    ('119-B-4', '正答は B「聴力低下は高音から始まる。」。

老人性難聴は蝸牛基底回転の有毛細胞から障害されるため、高音域から左右対称性に聴力が低下する。語音明瞭度も落ちるので、大きな声より、ゆっくりはっきり話すことが有効である。

出典：厚生労働省ホームページ 第119回医師国家試験 B004',
     '{"A": "耳鳴を伴うことが多い。", "C": "内耳の障害による感音難聴である。", "D": "補聴器の装用は社会的孤立や認知機能低下を防ぐうえで積極的に勧められる。", "E": "両側対称性に進行するのが特徴で、左右差が目立つ場合は聴神経腫瘍などを疑う。"}'),
    ('119-B-5', '正答は E「地域包括支援センター」。

地域包括支援センターは市町村が設置する。介護予防ケアマネジメント、総合相談支援、権利擁護、包括的・継続的ケアマネジメント支援を担い、保健師・社会福祉士・主任介護支援専門員が配置される。

出典：厚生労働省ホームページ 第119回医師国家試験 B005',
     '{"A": "児童相談所は都道府県と指定都市に設置が義務づけられている。", "B": "医療安全支援センターは都道府県、保健所設置市および特別区が設置する。", "C": "精神保健福祉センターは都道府県と指定都市が設置する。", "D": "地域医療支援センターは都道府県が設置し、医師の確保と地域偏在の是正を担う。"}'),
    ('119-B-6', '正答は E「立方体の模写」。

改訂長谷川式簡易知能評価スケールは9項目からなり、年齢、見当識、3単語の記銘と遅延再生、計算(100から7の連続減算)、数字の逆唱、物品記銘、語想起で構成される。立方体の模写は含まれず、これはMMSEの項目である。

出典：厚生労働省ホームページ 第119回医師国家試験 B006',
     '{"A": "100から順に7を引く計算の項目がある。", "B": "日時と場所の見当識を問う項目がある。", "C": "5つの物品を見せた後に隠して答えさせる項目がある。", "D": "3桁と4桁の数字の逆唱を求める項目がある。"}'),
    ('119-B-7', '正答は E「「心身ともにおつらいですね」」。

共感とは相手の感情を理解し、それを言葉にして返すことである。つらさを言い当てて受け止める言葉が最も共感的で、患者は理解されたと感じられる。

出典：厚生労働省ホームページ 第119回医師国家試験 B007',
     '{"A": "情報を集める質問で、感情に触れていない。", "B": "励ましは感情の否定になりやすく、共感とは異なる。", "C": "対処の提案であって、気持ちを受け止めてはいない。", "D": "医師の意気込みを伝えるもので、患者の感情に向き合っていない。"}'),
    ('119-B-8', '正答は E「尿道留置カテーテルの集尿袋内の尿」。

集尿袋内の尿は時間が経って細菌が増殖しており、また外部から汚染されるため培養検体に適さない。カテーテル留置中はカテーテルの採尿ポートを消毒して注射器で新鮮な尿を採る。

出典：厚生労働省ホームページ 第119回医師国家試験 B008',
     '{"A": "中間尿は外尿道口の常在菌の混入を減らせるので、標準的な検体である。", "B": "尿道分泌物は尿道炎の起因菌を調べる適切な検体である。", "C": "導尿で採取した尿は外陰部の常在菌の混入が少ない。", "D": "腎瘻造設時に採取した尿は無菌操作で得られ、上部尿路の情報が得られる。"}'),
    ('119-B-10', '正答は A「外国籍でも加入できる。」。

在留資格をもち住所を有する外国籍の人も、国民健康保険や被用者保険に加入できる。国民皆保険は国籍ではなく居住と就労の状況に基づく。

出典：厚生労働省ホームページ 第119回医師国家試験 B010',
     '{"B": "財源の内訳は保険料が約5割、公費が約4割で、保険料のほうが多い。", "C": "療養の給付は医療サービスそのものを受ける現物給付である。", "D": "予防接種や健康診断など疾病の治療にあたらないものは給付の対象外である。", "E": "患者には薬局を選ぶ自由があり、医療機関が指定することはできない。"}'),
    ('119-B-11', '正答は E「チアノーゼ」。

チアノーゼは還元ヘモグロビンが5g/dLを超えると現れる。したがって多血症では出やすく、高度の貧血では低酸素があっても出にくいことに注意する。

出典：厚生労働省ホームページ 第119回医師国家試験 B011',
     '{"A": "黄疸はビリルビンの増加により皮膚と眼球結膜が黄染するものである。", "B": "紅斑は真皮の血管拡張・充血によるもので、圧迫すると退色する。", "C": "紫斑は皮下の出血で、圧迫しても退色しない。", "D": "網状皮斑は皮膚の網目状の色調変化で、血管攣縮や塞栓でみられる。"}'),
    ('119-B-12', '正答は B「胸椎の叩打痛」。

思春期特発性脊柱側弯症は無痛性に進行するのが特徴で、叩打痛は認めない。疼痛を伴う場合は骨腫瘍や感染など別の原因を疑う必要がある。

出典：厚生労働省ホームページ 第119回医師国家試験 B012',
     '{"A": "前屈させると椎体の回旋により肋骨隆起(rib hump)が現れ、早期発見に有用である。", "C": "椎体の回旋により片側の肩甲骨が突出する。", "D": "側弯により左右の肩の高さに差が生じる。", "E": "体幹の傾きによりウエストラインが非対称になる。"}'),
    ('119-B-13', '正答は D「大量のエストロゲンは骨端線を閉鎖させる。」。

エストロゲンは骨端軟骨の成熟を促し、最終的に骨端線を閉鎖させる。思春期の急激な身長の伸びが止まるのはこのためで、思春期早発症では最終身長が低くなる。

出典：厚生労働省ホームページ 第119回医師国家試験 B013',
     '{"A": "初経後1〜2年は無排卵性の月経周期が多い。", "B": "卵胞数は胎生期の約700万個をピークに減り続け、出生時に約200万個、思春期には30万個ほどになる。", "C": "初経に先立ってゴナドトロピンの分泌は増加する。", "E": "二次性徴は乳房発育(思春期の始まり)、陰毛発育、初経の順に進む。"}'),
    ('119-B-14', '正答は A「訪問介護」。

訪問介護(ホームヘルプ)は身体介護と生活援助を行う介護保険の生活支援サービスで、ケアプランに基づいて提供される。医師の指示は要らない。

出典：厚生労働省ホームページ 第119回医師国家試験 B014',
     '{"B": "訪問看護は医師が交付する訪問看護指示書に基づいて行う。", "C": "訪問栄養食事指導は医師の指示に基づいて管理栄養士が行う。", "D": "訪問薬剤管理指導も医師の指示に基づいて薬剤師が行う。", "E": "訪問リハビリテーションも医師の指示が必要である。"}'),
    ('119-B-15', '正答は E「左側臥位」。

上部消化管内視鏡検査は左側臥位で行う。胃の大彎側が下になって観察しやすく、唾液や吐物が口の外に流れて誤嚥を防げるためである。

出典：厚生労働省ホームページ 第119回医師国家試験 B015',
     '{"A": "右側臥位では胃の観察に不利で、唾液も咽頭に貯留しやすい。", "B": "起座位では内視鏡の挿入と観察が行えない。", "C": "仰臥位では唾液や吐物を誤嚥する危険が高い。", "D": "砕石位は経腟・経肛門の処置で用いる体位である。"}'),
    ('119-B-16', '正答は C「頭痛」。

急性中耳炎に頭痛が加われば、炎症が乳突蜂巣を越えて頭蓋内に及ぶ合併症(硬膜外膿瘍、S状静脈洞血栓症、髄膜炎、脳膿瘍)を疑う。緊急に側頭骨と頭部の画像検査を行う。

出典：厚生労働省ホームページ 第119回医師国家試験 B016',
     '{"A": "耳痛は急性中耳炎の主症状で、それ自体は画像検査の適応にならない。", "B": "耳漏は鼓膜穿孔による排膿で、通常は症状の軽快につながる。", "D": "難聴は中耳の貯留液による伝音難聴で、急性中耳炎に通常みられる。", "E": "発熱も急性中耳炎によくみられる症状である。"}'),
    ('119-B-17', '正答は E「エネルギー」。

保存期末期腎不全では蛋白質を制限するため、そのぶんエネルギーが不足すると体蛋白の異化が進んで尿素窒素が増える。エネルギーはむしろ十分に(30〜35kcal/kg/日)確保する必要がある。

出典：厚生労働省ホームページ 第119回医師国家試験 B017',
     '{"A": "リンは高リン血症と血管石灰化を防ぐため制限する。", "B": "食塩は3g以上6g/日未満に制限する。", "C": "蛋白質は0.6〜0.8g/kg/日に制限し、腎機能低下の進行を抑える。", "D": "カリウムは高カリウム血症による致死性不整脈を防ぐため制限する。"}'),
    ('119-B-18', '正答は D「大腿動脈」。

動脈血ガス分析の採血には、体表から触知しやすく太い橈骨動脈が第一選択だが、選択肢の中では大腿動脈が最も適する。鼠径靱帯直下で拍動を触知でき、圧迫止血も確実に行える。

出典：厚生労働省ホームページ 第119回医師国家試験 B018',
     '{"A": "総頸動脈は脳への血流を担い、血腫や塞栓が脳虚血に直結するため穿刺しない。", "B": "鎖骨下動脈は深く、胸膜が近いため気胸の危険があり、圧迫止血もできない。", "C": "尺骨動脈は手への側副血行の主体で、損傷すると手の虚血を招くため避ける。", "E": "膝窩動脈は深部にあり触知しにくく、圧迫止血も難しい。"}'),
    ('119-B-20', '正答は C「20」。

初産婦では妊娠20週前後、経産婦では18週前後に胎動を自覚し始める。胎動は妊娠週数の推定と胎児の健康状態を知る手がかりになる。

出典：厚生労働省ホームページ 第119回医師国家試験 B020',
     '{"A": "妊娠4週では胎芽もごく小さく、胎動を感じることはない。", "B": "妊娠12週では胎児は動いているが、母体が感じ取れるほどではない。", "D": "妊娠28週にはすでに明瞭な胎動を自覚している。", "E": "妊娠36週では胎動を感じ始める時期をはるかに過ぎている。"}'),
    ('119-B-21', '正答は E「卵巣」。

エストラジオールが低いのにFSHが高いのは、卵巣からのフィードバックが働かず下垂体が刺激され続けている状態で、原因は卵巣にある(高ゴナドトロピン性性腺機能低下症)。早発卵巣不全やTurner症候群でみられる。

出典：厚生労働省ホームページ 第119回医師国家試験 B021',
     '{"A": "視床は感覚の中継核で、性腺の調節には関与しない。", "B": "視床下部性ならGnRHが出ずFSHも低値となる。", "C": "下垂体性でもFSHは低値となる。", "D": "副腎性の無月経では男性化徴候を伴い、FSHがここまで上昇しない。"}'),
    ('119-B-22', '正答は A「患者の職場からの照会への回答」。

職場からの照会に答えることは、診療や公益上の例外にあたらない第三者提供であり、本人の同意が要る。同意なく答えれば守秘義務違反となる。

出典：厚生労働省ホームページ 第119回医師国家試験 B022',
     '{"B": "疑義照会への回答は適切な調剤のために必要で、黙示の同意で足りる。", "C": "審査支払機関への情報提供は法令に基づくもので、同意は要らない。", "D": "生活保護法に基づく病状調査への回答も法令に基づくものである。", "E": "医療事故調査・支援センターへの報告は医療法に基づく義務である。"}'),
    ('119-B-23', '正答は B「脈拍 — 52/分」。

乳児の心拍数は120〜140/分が正常で、52/分は明らかな徐脈である。乳児の徐脈は低酸素の結果として現れることが多く、心停止に至る前段階として直ちに換気と酸素化を立て直す必要がある。

出典：厚生労働省ホームページ 第119回医師国家試験 B023',
     '{"A": "38.0°Cの発熱は原因の検索を要するが、直ちに処置を要する所見ではない。", "C": "血圧76/52mmHgは乳児として保たれている。", "D": "呼吸数36/分は乳児の正常範囲内である。", "E": "SpO2 96%は正常である。"}'),
    ('119-B-24', '正答は B「角膜」。

角膜は血流を必要としない組織で、心臓が停止した後でも一定時間内であれば提供できる。腎臓と膵臓も心停止後の提供が可能である。

出典：厚生労働省ホームページ 第119回医師国家試験 B024',
     '{"A": "肺は脳死下でなければ提供できない。", "C": "肝臓も脳死下での提供が原則である。", "D": "小腸も脳死下での提供に限られる。", "E": "心臓は脳死下でしか提供できない。"}'),
    ('119-B-25', '正答は B「法の遵守」。

実際に行っていない診療の報酬を請求することは詐欺にあたり、健康保険法にも反する不正請求である。医師の職業倫理の基本である法の遵守に反したことが処分の理由となる。

出典：厚生労働省ホームページ 第119回医師国家試験 B025',
     '{"A": "情報を開示しなかったことが問題なのではない。", "C": "従業員の労働条件が問われた事案ではない。", "D": "経営の健全性そのものが処分の対象になるわけではない。", "E": "個人情報の管理が問われた事案ではない。"}'),
    ('119-B-26', '正答は A「応援を呼ぶ。」。

反応がない人を見つけたら、まず大声で応援を呼び、救急コールと除細動器の手配を依頼する。一人で対応しようとすると蘇生の開始も遅れるため、人と資機材を集めることが最初の行動になる。

出典：厚生労働省ホームページ 第119回医師国家試験 B026',
     '{"B": "頸椎の保護は高所からの転落など受傷機転が疑われる場合に考える。まず応援である。", "C": "胸骨圧迫は呼吸と反応を確かめた後に始める。", "D": "呼吸の確認は応援を呼んだ直後に行う。", "E": "頸動脈の触知は医療者が呼吸の確認と同時に10秒以内に行う。順序としては応援要請が先である。"}'),
    ('119-B-27', '正答は D「4」。

視線が合わないのは対人的な関わりの発達の遅れを示す所見で、9か月では明らかな異常である。自分の手を見つめる行動(ハンドリガード)も本来は生後4か月ごろに消える。ほかの下線部はこの月齢としてふつうにみられる。

出典：厚生労働省ホームページ 第119回医師国家試験 B027',
     '{"A": "つかまり立ちから独りで立てるようになるのは10〜12か月ごろである。", "B": "独歩は1歳前後で獲得するので、9か月でできなくてよい。", "C": "積み木を積めるようになるのは1歳前後である。", "E": "意味のある言葉が出るのは1歳前後で、喃語の段階として正常である。"}'),
    ('119-B-28', '正答は D「鼻カニューラ2L/分」。

慢性II型呼吸不全の急性増悪では、高濃度酸素はCO2ナルコーシスを招く。SpO2 88〜92%を目標に、現在の1L/分からわずかに増やす2L/分程度から始め、動脈血ガスを再検して調節する。

出典：厚生労働省ホームページ 第119回医師国家試験 B028',
     '{"A": "リザーバー付マスク15L/分は過剰でCO2ナルコーシスを招く。", "B": "10L/分も同じ理由で不適切である。", "C": "鼻カニューラ5L/分でも高濃度になりすぎる。", "E": "0.5L/分ではSpO2 87%からさらに下がり、低酸素が是正されない。"}'),
    ('119-B-29', '正答は E「「胎児形態異常のリスクは糖尿病ではない方とほとんど変わりません」」。

妊娠前からHbA1c 6.0%と血糖が良好に管理されていれば、胎児形態異常の頻度は糖尿病のない妊婦とほとんど変わらない。器官形成期の高血糖こそが危険因子なので、その事実を伝えて安心させる。

出典：厚生労働省ホームページ 第119回医師国家試験 B029',
     '{"A": "中絶を勧める根拠はまったくない。", "B": "超音波検査で分かる形態異常には限りがあり、すべてを検出できるわけではない。", "C": "妊娠中の経口血糖降下薬は原則として用いず、インスリンを続ける。", "D": "すでに糖尿病と診断され治療中の妊婦に糖負荷試験を行う必要はなく、高血糖を招く危険もある。"}'),
    ('119-B-31', '正答は A「血糖測定」。

インスリン治療中の糖尿病患者が突然の意識障害をきたした場合、まず低血糖を疑う。血糖測定は即座に行え、低ければブドウ糖投与で速やかに回復するため、他の検査に先立って行う。

出典：厚生労働省ホームページ 第119回医師国家試験 B031',
     '{"B": "脳波検査は非けいれん性てんかん重積を疑うときに行うが、まず低血糖を除外する。", "C": "頭部CTは麻痺や外傷を疑うときに行う。麻痺は認めない。", "D": "髄液検査は髄膜炎を疑うときに行うが、発熱も髄膜刺激徴候もない。", "E": "動脈血ガス分析も鑑別に有用だが、最も簡便で治療に直結するのは血糖測定である。"}'),
    ('119-B-32', '正答は B「輸液の減量」。

終末期に近づくと体液を保持できず、輸液を続けると胸水・腹水・浮腫・気道分泌の増加を招いて苦痛が増す。呼吸音の減弱と喀痰の増加、著明な浮腫が出ており、まず輸液量を減らす。

出典：厚生労働省ホームページ 第119回医師国家試験 B032',
     '{"A": "SpO2 96%と酸素化は保たれており、酸素投与では気道分泌は減らない。", "C": "腎機能の悪化を示す所見はなく、本人の希望する在宅療養とも相容れない。", "D": "本人が選択しなかった治療であり、この全身状態でも適応がない。", "E": "肺血栓塞栓症を疑う所見はない。"}'),
    ('119-B-33', '正答は E「労働者災害補償保険の給付対象となる。」。

業務中に生じた負傷は、本人の不注意によるものであっても業務災害として労働者災害補償保険の給付対象となる。事業主の過失の有無を問わない無過失責任の仕組みである。

出典：厚生労働省ホームページ 第119回医師国家試験 B033',
     '{"A": "労災保険から療養補償給付が支給され、自己負担は生じない。", "B": "医療扶助は生活保護の給付で、この事案には該当しない。", "C": "業務災害には健康保険を使えない。", "D": "後期高齢者医療制度も業務災害には適用されない。"}'),
    ('119-B-34', '正答は E「患者中心性」。

専門用語が多く理解できなかったこと、心理状態への配慮を欠いたこと、仕事の心配という生活上の問題に応じてもらえなかったこと、いずれも患者の価値観や状況に沿った医療という患者中心性の欠如を示す。

出典：厚生労働省ホームページ 第119回医師国家試験 B034',
     '{"A": "誤投薬や合併症など安全に関わる問題は起きていない。", "B": "受けられる医療に不公平があったという記載はない。", "C": "受診後すぐに入院と治療が行われており、適時性は保たれている。", "D": "適切な診断と治療により回復しており、有効性は保たれている。"}'),
    ('119-B-36', '正答は B「口腔ケアの実施を提案する。」。

口腔内の衛生状態が不良で乾燥しており、これが食欲低下と誤嚥性肺炎の一因になっている。口腔ケアは食べる機能を支える基本で、栄養サポートチームの介入として適切である。

出典：厚生労働省ホームページ 第119回医師国家試験 B036',
     '{"A": "終末期に近い患者に胃瘻を造設しても予後や生活の質の改善は期待しにくく、まず提案する内容ではない。", "C": "緩和ケアチームと目標を共有して連携する必要がある。", "D": "体重減少を待つのではなく、低栄養の兆しを捉えて早期に介入する。", "E": "栄養療法の実施には主治医の同意と指示が必要である。"}'),
    ('119-B-37', '正答は C「腹部単純CT」。

突然の側腹部痛、肋骨脊柱角の叩打痛、血尿、水腎症から尿管結石である。腹部単純エックス線写真に写らない尿酸結石でも単純CTなら描出でき、大きさと位置、水腎症の程度まで一度に評価できる。

出典：厚生労働省ホームページ 第119回医師国家試験 B037',
     '{"A": "FDG-PETは悪性腫瘍の検索に用いる。", "B": "膀胱鏡は膀胱内の病変を観察する検査で、尿管結石の診断には向かない。", "D": "膀胱造影は膀胱損傷や膀胱尿管逆流の評価に用いる。", "E": "腎シンチグラフィは分腎機能の評価に用いる検査で、急性期の診断には使わない。"}'),
    ('119-B-38', '正答は E「5」。

スリッパは脱げやすく踵が固定されないため、高齢者の転倒の危険因子になる。踵を覆い滑りにくい靴に替えることが転倒予防の基本である。

出典：厚生労働省ホームページ 第119回医師国家試験 B038',
     '{"A": "食事の再開は栄養状態を保ち、筋力の維持につながる。", "B": "点滴ラインの終了は行動を妨げるものが減るので、転倒の危険はむしろ下がる。", "C": "離床センサーは早期に気づくための対策である。", "D": "看護師の見守りも転倒を防ぐための対策である。"}'),
    ('119-B-39', '正答は E「多職種の関係者で対応を検討する。」。

外出には症状の管理、酸素の携行、移動手段の確保、学校との調整など多くの準備が要る。医師、看護師、薬剤師、社会福祉士など多職種で検討し、本人の希望を実現する道を探る。

出典：厚生労働省ホームページ 第119回医師国家試験 B039',
     '{"A": "付き添いや急変時の対応が必要になるため、家族の意向の確認は欠かせない。", "B": "携帯用酸素ボンベを用いれば酸素投与下でも外出できる。", "C": "救急車は緊急時の搬送手段であり、予定された外出には介護タクシーなどを利用する。", "D": "座席や休憩場所の確保などのため、学校とは早い段階から相談する。"}'),
    ('119-B-40', '正答は A「喘鳴」。

縦隔腫瘤が気管を圧排して内腔が狭窄しており、中枢気道の狭窄音が胸骨付近で聴かれる。吸気・呼気を通じた高調な連続性ラ音(喘鳴)で、頸部から胸骨上で最も強く聴取される。

出典：厚生労働省ホームページ 第119回医師国家試験 B040',
     '{"B": "水泡音(coarse crackles)は気道内の分泌物によるもので、肺炎や気管支拡張症でみられる。", "C": "捻髪音(fine crackles)は虚脱した末梢気道が吸気終末に開く音で、間質性肺炎でみられる。肺野に異常はない。", "D": "胸膜摩擦音は胸膜炎で炎症を起こした胸膜がこすれる音である。", "E": "呼吸音の減弱は気胸や胸水、無気肺でみられる。肺野に異常はない。"}'),
    ('119-B-41', '正答は B「②」。

設問は報告する際に「重要でない」情報を選ぶもの。下線部②は妻の既往で、この患者の脂質異常症の評価にも治療方針にも関わらない。

出典：厚生労働省ホームページ 第119回医師国家試験 B041',
     '{"A": "体重の増加は脂質異常症の悪化要因で、生活習慣の是正を考えるうえで重要である。", "C": "飲酒はトリグリセリドを上げる要因で、重要である。", "D": "父が若くして心筋梗塞で亡くなっており、家族性高コレステロール血症を疑う手掛かりになる。", "E": "アキレス腱の肥厚は家族性高コレステロール血症の診断項目そのものである。"}'),
    ('119-B-42', '正答は C「準備期」。

行動変容ステージのうち、準備期は「1か月以内に行動を変えるつもりがある」段階を指す。「来週から通勤時に歩こうと思います」はまさにこれにあたる。

出典：厚生労働省ホームページ 第119回医師国家試験 B042',
     '{"A": "無関心期は、半年以内に行動を変える気がない段階である。", "B": "関心期は、半年以内には変えたいが直近の予定はない段階である。", "D": "実行期は、既に始めていて半年未満の段階である。", "E": "維持期は、半年以上続いている段階である。"}'),
    ('119-B-45', '正答は E「⑤」。

解釈モデルとは、患者が自分の病気をどう捉えているかである。下線部⑤の問いに対して「父が胃癌で亡くなったので、自分も胃癌ではないかと心配」という答えが返っており、まさに解釈モデルを引き出している。

出典：厚生労働省ホームページ 第119回医師国家試験 B045',
     '{"A": "飲酒の有無は生活歴の聴取である。", "B": "便の色は症状と所見を確かめる問いである。", "C": "健康診断の受診歴は既往の確認である。", "D": "併用薬の確認は服薬歴の聴取である。"}'),
    ('119-B-46', '正答は E「タール便」。

腰痛のため市販の鎮痛薬を1か月飲んでおり、空腹時の心窩部痛と貧血がある。NSAIDによる胃十二指腸潰瘍からの出血を考える。上部消化管からの出血は腸を通る間に酸化されて黒くなり、粘り気のあるタール便になる。

出典：厚生労働省ホームページ 第119回医師国家試験 B046',
     '{"A": "脂肪便は膵外分泌機能の低下でみられる。", "B": "水様便は感染性腸炎などでみられる。", "C": "粘血便は大腸の炎症や腫瘍でみられる。", "D": "灰白色便は胆汁が腸に流れない胆道閉塞でみられるが、黄染を認めていない。"}'),
    ('119-B-47', '正答は B「振戦」。

常習飲酒があり、2日前から禁酒している。発汗、頻脈、手の震えはアルコール離脱の初期症状で、断酒後6〜24時間から出はじめる。問診票にうまく書けないほどの振戦がすでに現れている。

出典：厚生労働省ホームページ 第119回医師国家試験 B047',
     '{"A": "総ビリルビンは正常で、黄疸を認める段階ではない。", "C": "腹部に波動を認めず、腹水はない。", "D": "肝を触知しておらず、肝腫大の記載もない。", "E": "手掌紅斑は慢性の肝障害でみる所見だが、アルブミンも凝固能も保たれており肝硬変には至っていない。"}'),
    ('119-B-48', '正答は E「ベンゾジアゼピン系薬」。

アルコール離脱はこのあと振戦せん妄やけいれんへ進みうる。ベンゾジアゼピン系薬を用いて離脱症状を抑え、重症化を防ぐ。あわせてビタミンB1を補ってWernicke脳症を予防する。

出典：厚生労働省ホームページ 第119回医師国家試験 B048',
     '{"A": "血圧は保たれており、降圧薬の適応がない。", "B": "血糖は正常で、血糖降下薬は要らない。", "C": "甲状腺の検査値は基準内で、抗甲状腺薬の適応がない。", "D": "尿酸値は基準内である。"}'),
    ('119-B-49', '正答は B「妄想」。

「世界がなくなってしまう」という世界没落体験や、「知らない人が自分を見ている」という注察妄想がみられる。訂正できない誤った確信であり、妄想にあたる。

出典：厚生労働省ホームページ 第119回医師国家試験 B049',
     '{"A": "心気は、自分が重い身体の病気だと過度に心配する状態である。", "C": "強迫観念は、不合理と分かっていながら頭から離れない考えである。本例には病識がない。", "D": "対人恐怖は、人前で恥をかくことへの強い不安である。", "E": "予期不安は、また発作が起きるのではないかという不安で、パニック症でみられる。"}'),
    ('119-B-50', '正答は B「統合失調症」。

思春期に発症し、意欲や集中力の低下から成績が落ちて引きこもった（陰性症状）。自室からの独語と空笑、妄想、会話のまとまりのなさ（陽性症状）も揃っており、統合失調症である。

出典：厚生労働省ホームページ 第119回医師国家試験 B050',
     '{"A": "うつ病では気分の落ち込みが中心で、幻覚や妄想がここまで前面には出ない。", "C": "パーソナリティ症は持続する対人関係や行動の様式の問題で、幻覚妄想が主体ではない。", "D": "自閉スペクトラム症は幼少期からの発達の偏りが前提だが、本例では指摘されていない。", "E": "双極症は気分の高揚と抑うつを繰り返すもので、経過が異なる。"}'),
    ('119-C-1', '正答は B「救命救急センター数の増加」。

健康日本21(第3次)は、健康寿命の延伸と健康格差の縮小を最終目標に、生活習慣の改善、社会環境の質の向上、ライフコースアプローチを柱とする。救命救急センターの整備は医療提供体制の課題で、医療計画が扱う。

出典：厚生労働省ホームページ 第119回医師国家試験 C001',
     '{"A": "健康経営に取り組む企業の増加は、社会環境の質の向上の目標に含まれる。", "C": "メンタルヘルス対策に取り組む事業場の増加も目標に含まれる。", "D": "利用者に応じた食事提供をする特定給食施設の増加も目標に含まれる。", "E": "「居心地がよく歩きたくなる」まちなかづくりに取り組む市町村の増加も目標に含まれる。"}'),
    ('119-C-3', '正答は E「精神医療審査会の事務」。

精神保健福祉センターは、精神医療審査会の事務を担うほか、精神保健に関する知識の普及、相談指導、自立支援医療と精神障害者保健福祉手帳の判定を行う。

出典：厚生労働省ホームページ 第119回医師国家試験 C003',
     '{"A": "要介護認定は市町村が介護認定審査会の判定に基づいて行う。", "B": "障害年金の認定は日本年金機構が行う。", "C": "麻薬の取り締まりは麻薬取締官・麻薬取締員が担う。", "D": "心神喪失者の精神鑑定は裁判所が選任した鑑定医が行う。"}'),
    ('119-C-4', '正答は D「調査対象者数」。

偶然誤差は標本の偶然のばらつきによる誤差で、対象者数を増やせば小さくなる。系統誤差(バイアス)と違い、標本サイズによって左右されるのが特徴である。

出典：厚生労働省ホームページ 第119回医師国家試験 C004',
     '{"A": "喫煙の定義が曖昧なら測定バイアスとなり、系統誤差である。", "B": "記名式では正直に答えにくく、これも測定バイアス(系統誤差)にあたる。", "C": "質問の妥当性が低ければ測りたいものが測れず、系統誤差となる。", "E": "無作為抽出を怠れば選択バイアスが生じ、これも系統誤差である。"}'),
    ('119-C-5', '正答は B「経済的虐待」。

児童虐待防止法が定める児童虐待は、身体的虐待・性的虐待・ネグレクト・心理的虐待の4類型である。経済的虐待は高齢者虐待防止法や障害者虐待防止法に定めがあるが、児童虐待の類型には含まれない。

出典：厚生労働省ホームページ 第119回医師国家試験 C005',
     '{"A": "児童にわいせつな行為をすること、させることは性的虐待にあたる。", "C": "外傷が生じる、または生じるおそれのある暴行は身体的虐待にあたる。", "D": "著しい暴言や拒絶的な対応、面前でのドメスティック・バイオレンスは心理的虐待にあたる。", "E": "適切な監護を著しく怠ることはネグレクトにあたる。"}'),
    ('119-C-6', '正答は D「家事動作訓練が含まれる。」。

介護保険の機能訓練は生活機能の維持・向上を目的とし、調理や掃除、洗濯といった家事動作の訓練も含まれる。生活の場に即した訓練であることが医療機関のリハビリテーションとの違いである。

出典：厚生労働省ホームページ 第119回医師国家試験 C006',
     '{"A": "機能訓練指導員になれるのは理学療法士、作業療法士、言語聴覚士、看護職員などで、介護福祉士は含まれない。", "B": "高齢化に伴い利用者は増加している。", "C": "介護保険の機能訓練はケアプランに基づいて行うもので、医師の指示は要件ではない。", "E": "特定機能病院は高度医療を担う施設で、介護保険の機能訓練の実施場所ではない。"}'),
    ('119-C-7', '正答は E「所得によって支払う保険料が異なる。」。

介護保険料は所得段階に応じて設定され、所得が高いほど多く負担する。第1号被保険者の保険料は市町村ごとに定められ、所得段階も市町村が決める。

出典：厚生労働省ホームページ 第119回医師国家試験 C007',
     '{"A": "40歳以上であれば生涯にわたって納付する。上限年齢はない。", "B": "第1号被保険者の保険料は市町村ごとに異なる。", "C": "40歳から第2号被保険者として納付義務が生じる。", "D": "サービス利用時には所得に応じて1〜3割の自己負担がある。"}'),
    ('119-C-8', '正答は D「骨盤」。

初期診療では胸部と骨盤のエックス線写真を撮る。骨盤骨折は後腹膜へ大量に出血してショックの原因となり、骨盤輪の不安定性が分かれば固定と血管内治療の判断につながるためである。

出典：厚生労働省ホームページ 第119回医師国家試験 C008',
     '{"A": "頭部は出血源としての寄与が小さく、評価はCTで行う。", "B": "頸椎は損傷の有無を評価するが、ショックの原因検索としての優先度は低い。", "C": "腹腔内出血の評価はエックス線写真では困難で、迅速簡易超音波検査(FAST)を用いる。", "E": "大腿骨骨折も出血源になるが、初期の定型的な撮影部位には含まれない。"}'),
    ('119-C-9', '正答は C「診療録」。

医師法第24条は、診療録を診療完結の日から5年間保存することを定めている。保存義務を負うのは病院・診療所の管理者、または診療した医師である。

出典：厚生労働省ホームページ 第119回医師国家試験 C009',
     '{"A": "紹介状の保存期間は医師法に定めがない。", "B": "処方箋は療養担当規則により3年間の保存とされ、保存するのは調剤した薬局である。", "D": "看護記録は医療法施行規則により2年間の保存とされる。", "E": "エックス線写真も医療法施行規則により2年間の保存とされる。"}'),
    ('119-C-10', '正答は D「自己免疫性溶血性貧血」。

尿潜血反応はヘモグロビンとミオグロビンのペルオキシダーゼ活性を捉えるため、溶血で遊離したヘモグロビンが尿中に出れば、赤血球がなくても陽性となる。潜血陽性で沈渣に赤血球を認めないのがヘモグロビン尿の特徴である。

出典：厚生労働省ホームページ 第119回医師国家試験 C010',
     '{"A": "腎梗塞では梗塞部からの出血で沈渣に赤血球を認める。", "B": "膀胱癌では腫瘍からの出血により沈渣に赤血球を多数認める。", "C": "尿路結石でも粘膜損傷により沈渣に赤血球を認める。", "E": "膜性増殖性糸球体腎炎では変形赤血球や赤血球円柱を認める。"}'),
    ('119-C-11', '正答は E「滅裂思考」。

思路(思考過程)の障害は考えのつながり方の異常で、滅裂思考は文と文のつながりが失われて理解できなくなるものである。観念奔逸や思考制止も思路の障害にあたる。

出典：厚生労働省ホームページ 第119回医師国家試験 C011',
     '{"A": "強迫観念は思考の内容にとらわれる障害で、思考内容の異常に分類される。", "B": "思考吹入は自我障害にあたる。", "C": "心気妄想は思考内容の障害(妄想)である。", "D": "広場恐怖は不安症状で、思考の障害ではない。"}'),
    ('119-C-12', '正答は E「ガラガラをつかむ。」。

微細運動は手指を使う細かい動きを指す。ガラガラをつかむのは把握の発達をみる項目で、生後3〜4か月ごろに獲得する微細運動の指標である。

出典：厚生労働省ホームページ 第119回医師国家試験 C012',
     '{"A": "首がすわるのは体幹を支える粗大運動である。", "B": "手をみつめる行動(ハンドリガード)は視覚と身体の認識に関わるもので、運動そのものではない。", "C": "寝返りは全身を使う粗大運動である。", "D": "バイバイは模倣による社会性の発達を示す項目である。"}'),
    ('119-C-13', '正答は B「訪問診療」。

訪問診療は医療保険で提供される。介護保険の対象になるのは訪問介護や福祉用具貸与、住宅改修など生活を支えるサービスである。

出典：厚生労働省ホームページ 第119回医師国家試験 C013',
     '{"A": "手すりの設置や段差の解消といった住宅改修は介護保険の給付である。", "C": "介護医療院は介護保険の施設サービスである。", "D": "福祉用具貸与も介護保険の給付である。", "E": "ショートステイ(短期入所生活介護)も介護保険の給付である。"}'),
    ('119-C-14', '正答は E「都道府県知事」。

感染症法に基づく就業制限は都道府県知事が通知する。一類・二類・三類感染症および新型インフルエンザ等感染症の患者について、飲食物に直接接触する業務などへの従事を制限する。

出典：厚生労働省ホームページ 第119回医師国家試験 C014',
     '{"A": "産業医は事業者に意見を述べる立場で、法に基づく就業制限の通知権限をもたない。", "B": "事業者は通知を受けて対応する側である。", "C": "主治医は診断して届け出るが、就業制限そのものは通知できない。", "D": "専門医であっても通知の権限はない。"}'),
    ('119-C-16', '正答は A「沸点が高い。」。

生物濃縮を受けやすいのは、脂溶性が高く化学的に安定で分解されにくい物質である。沸点が高いことは揮発しにくく環境中に残りやすいことを意味し、食物連鎖を通じて濃縮される。PCBや有機水銀、DDTが代表である。

出典：厚生労働省ホームページ 第119回医師国家試験 C016',
     '{"B": "水溶性の物質は尿中に排泄されやすく、体内に蓄積しない。", "C": "急性毒性の強さと蓄積のしやすさは別の性質である。", "D": "化学的に不安定なら環境中で分解されて濃縮されない。", "E": "生体内で代謝されやすい物質は排泄され、蓄積しない。"}'),
    ('119-C-17', '正答は D「エタノール」。

エタノールは分子が小さく脂溶性もあるため、胃粘膜から直接吸収される。約20%が胃で、残りが小腸で吸収されるため、空腹時には吸収が速く血中濃度が急に上がる。

出典：厚生労働省ホームページ 第119回医師国家試験 C017',
     '{"A": "鉄は十二指腸から空腸上部で吸収される。", "B": "葉酸も空腸で吸収される。", "C": "脂肪酸は胆汁酸ミセルとなって空腸・回腸で吸収される。", "E": "グルコースはSGLT1により小腸で吸収される。"}'),
    ('119-C-19', '正答は D「低出生体重児の届出」。

母子保健法は、体重2,500g未満の低出生体重児が出生したときの届出のほか、母子健康手帳の交付、妊産婦・乳幼児の健康診査、養育医療、新生児訪問指導などを定めている。

出典：厚生労働省ホームページ 第119回医師国家試験 C019',
     '{"A": "定期予防接種は予防接種法に規定されている。", "B": "児童虐待に係る通告は児童虐待防止法と児童福祉法に規定されている。", "C": "人工妊娠中絶の要件は母体保護法に規定されている。", "E": "就学時健康診断は学校保健安全法に規定されている。"}'),
    ('119-C-20', '正答は C「すくみ足」。

すくみ足は歩き出しや方向転換で足が床に張りついて出なくなる症状で、床の線やレーザーポインタ、号令といった外的な合図(キュー)があると乗り越えられる。等間隔の線をまたぐ訓練はこれを利用したものである。

出典：厚生労働省ホームページ 第119回医師国家試験 C020',
     '{"A": "加速歩行は歩き出すと歩幅が狭く速くなる症状で、線をまたいでも制御できない。", "B": "姿勢異常には体幹のストレッチや姿勢を意識させる訓練を行う。", "D": "突進現象は重心が前に移って止まれなくなるもので、方向転換や停止の訓練で対応する。", "E": "静止時振戦は薬物療法や脳深部刺激療法の対象で、歩行訓練では改善しない。"}'),
    ('119-C-21', '正答は E「樹状細胞」。

樹状細胞は取り込んだ抗原をMHCクラスIIに載せてナイーブT細胞に提示できる、最も強力な抗原提示細胞である。マクロファージとB細胞も抗原提示能をもつ。

出典：厚生労働省ホームページ 第119回医師国家試験 C021',
     '{"A": "T細胞は提示された抗原を認識する側で、提示はしない。", "B": "血小板は止血に働き、抗原提示能はない。", "C": "好酸球は寄生虫感染やアレルギーに関与するが、抗原提示細胞ではない。", "D": "好中球は貪食と殺菌を担うが、ナイーブT細胞への抗原提示は行わない。"}'),
    ('119-C-23', '正答は D「複視」。

Bell麻痺は顔面神経の障害で、外眼筋を支配する動眼・滑車・外転神経は侵されないため複視は生じない。複視があれば脳幹病変など別の原因を考える。

出典：厚生労働省ホームページ 第119回医師国家試験 C023',
     '{"A": "口輪筋の麻痺により口角が下がる。", "B": "末梢性の麻痺なので前頭筋も麻痺し、額のしわ寄せができなくなる。", "C": "アブミ骨筋の麻痺により音が響いて聞こえる聴覚過敏を生じる。", "E": "鼓索神経が障害されると舌前2/3の味覚が低下する。"}'),
    ('119-C-24', '正答は E「ユニバーサル・ヘルス・カバレッジ〈UHC〉の達成」。

ゴール3のターゲットには、ユニバーサル・ヘルス・カバレッジの達成、すなわちすべての人が経済的な困難なく必要な保健医療サービスを受けられる状態の実現が明記されている。

出典：厚生労働省ホームページ 第119回医師国家試験 C024',
     '{"A": "水と衛生へのアクセスはゴール6の内容である。", "B": "国内および国家間の不平等の是正はゴール10である。", "C": "健康の社会的決定要因への取り組みは重要な考え方だが、ゴール3の個別ターゲットとしては掲げられていない。", "D": "グローバル・パートナーシップの活性化はゴール17である。"}'),
    ('119-C-26', '正答は E「抗アミノアシルtRNA合成酵素抗体〈抗ARS抗体〉 — 間質性肺炎」。

抗ARS抗体は多発性筋炎・皮膚筋炎に伴い、間質性肺炎、機械工の手、多関節炎、Raynaud現象を特徴とする抗合成酵素症候群を形成する。間質性肺炎の合併率が高く、予後を左右する。

出典：厚生労働省ホームページ 第119回医師国家試験 C026',
     '{"A": "抗MDA5抗体は急速進行性の間質性肺炎と関連する。間質性腎炎ではない。", "B": "抗Mi-2抗体は皮膚症状の目立つ古典的な皮膚筋炎に伴う。蝶形紅斑は全身性エリテマトーデスの所見である。", "C": "抗SS-A抗体はSjögren症候群に伴い、乾燥症状や新生児ループスと関連する。皮膚硬化ではない。", "D": "抗TIF1-γ抗体は悪性腫瘍を合併する皮膚筋炎と関連する。硬化性胆管炎ではない。"}'),
    ('119-C-27', '正答は A「血友病」。

薬害エイズ事件では、血友病患者の凝固因子補充に用いられた非加熱の濃縮血液製剤にHIVが混入しており、多数の患者が感染した。加熱製剤への切り替えの遅れが被害を広げた。

出典：厚生労働省ホームページ 第119回医師国家試験 C027',
     '{"B": "多発性骨髄腫の治療に濃縮血液製剤は用いない。", "C": "無菌性髄膜炎は対症療法で治療する。", "D": "成人T細胞白血病はHTLV-1による疾患で、血液製剤による医原性免疫不全とは別である。", "E": "Creutzfeldt-Jakob病はヒト乾燥硬膜の移植による医原性感染が問題となった、別の薬害である。"}'),
    ('119-C-28', '正答は E「血清クレアチニン値」。

妊娠中は腎血漿流量と糸球体濾過量が増えるため、血清クレアチニン値は低下する。非妊娠時の基準値を当てはめると腎機能障害を見落とすので注意する。

出典：厚生労働省ホームページ 第119回医師国家試験 C028',
     '{"A": "白血球数は妊娠中に増加する。", "B": "プロゲステロンの作用で一回換気量は増加する。", "C": "増大した子宮が下大静脈を圧迫するため大腿静脈圧は上昇する。", "D": "hPLなどの作用でインスリン抵抗性は増大する。"}'),
    ('119-C-29', '正答は E「偽性副甲状腺機能低下症」。

偽性副甲状腺機能低下症は、副甲状腺ホルモンの受容体以降のシグナル伝達(Gs蛋白)の障害により標的臓器が反応できない病態である。PTHはむしろ高値なのに低カルシウム血症と高リン血症を示す。

出典：厚生労働省ホームページ 第119回医師国家試験 C029',
     '{"A": "骨軟化症はビタミンD欠乏やリン喪失によるもので、受容体異常ではない。", "B": "Basedow病はTSH受容体に対する刺激性の自己抗体によるもので、受容体そのものの異常ではない。", "C": "慢性甲状腺炎は甲状腺への自己免疫性の破壊による。", "D": "副甲状腺機能亢進症はホルモンの過剰分泌によるもので、受容体は正常である。"}'),
    ('119-C-30', '正答は D「過敏性腸症候群」。

過敏性腸症候群は器質的な病変を伴わない機能性疾患で、下血をきたさない。血便があれば診断を見直し、器質的疾患を検索する必要がある。

出典：厚生労働省ホームページ 第119回医師国家試験 C030',
     '{"A": "大腸癌は腫瘍からの出血により下血をきたす。", "B": "潰瘍性大腸炎では粘血便が特徴的である。", "C": "虚血性大腸炎では突然の腹痛に続いて鮮血便をみる。", "E": "非閉塞性腸管虚血症でも腸管壊死により下血をきたす。"}'),
    ('119-C-31', '正答は E「ベンゾジアゼピン系薬」。

ベンゾジアゼピン系薬は反復使用で耐性と身体依存を形成し、急に中止すると不安、不眠、けいれんなどの離脱症状が現れる。漸減して中止する必要がある。

出典：厚生労働省ホームページ 第119回医師国家試験 C031',
     '{"A": "LSDは幻覚剤で、精神依存はあるが身体依存は形成しにくい。", "B": "大麻も精神依存が主で、身体依存は弱い。", "C": "コカインは強い精神依存を生じるが、身体依存は形成しにくい。", "D": "アンフェタミン類も精神依存が中心で、身体依存は弱い。"}'),
    ('119-C-37', '正答は D「4」。

ノロウイルスはエンベロープをもたないためアルコールが効きにくい。吐物で汚染された面は次亜塩素酸ナトリウムで消毒する。

出典：厚生労働省ホームページ 第119回医師国家試験 C037',
     '{"A": "吐物を広げないようペーパータオルで静かに拭き取るのは適切である。", "B": "使用したペーパータオルをビニール袋に密封するのは適切である。", "C": "感染性の吐物を医療廃棄物として処理するのは適切である。", "E": "アルコールが効きにくいため、石鹸と流水による手洗いで物理的に洗い流すのが適切である。"}'),
    ('119-C-38', '正答は E「子宮収縮薬投与」。

分娩第2期が3時間続き、陣痛周期5〜6分・持続20秒と微弱陣痛になっている。児頭下降度SP±0cmで下降が進まず、胎児心拍数は良好なので、まず子宮収縮薬で陣痛を補強する。

出典：厚生労働省ホームページ 第119回医師国家試験 C038',
     '{"A": "吸引分娩は児頭下降度がSP+2cm以上に達してから行う。", "B": "分娩第2期が3時間に及んでおり、経過観察は適切でない。", "C": "胎児は良好で、児頭も下降しつつある。まず陣痛の補強を試みる。", "D": "胎児圧出法は子宮底を圧迫する手技で、単独では行わず、また子宮破裂の危険がある。"}'),
    ('119-C-39', '正答は A「老衰」。

老衰は、高齢者で他に記載すべき死因がない自然死に用いる。長期の経過で徐々に衰弱し、明らかな病態を特定できない本例は老衰と記載してよい。

出典：厚生労働省ホームページ 第119回医師国家試験 C039',
     '{"B": "心不全は死亡に至る過程を示す状態で、直接死因として単独で記載しない。", "C": "脳梗塞は5年前の発症で、今回の死亡の直接の原因とは考えにくい。", "D": "呼吸不全も心不全と同様、死亡の一過程を示す表現である。", "E": "経過と死体所見から老衰と判断できており、不詳とする理由がない。"}'),
    ('119-C-43', '正答は B「体重の減量」。

身長160cm、体重90kgでBMI35.2の高度肥満である。肥満は排卵障害の原因となり、妊娠高血圧症候群や妊娠糖尿病、巨大児の危険も高める。妊娠前の減量が最も有効な助言になる。

出典：厚生労働省ホームページ 第119回医師国家試験 C043',
     '{"A": "小学校教師という職業に妊娠を妨げる要因はなく、休職を勧める根拠はない。", "C": "血圧は良好に管理されており、妊娠を断念する理由はない。", "D": "降圧薬は妊娠中に使える薬剤へ変更するのであって、中止するものではない。", "E": "まだ避妊をやめて自然妊娠を試みる段階で、いきなり体外受精を始めるものではない。"}'),
    ('119-C-44', '正答は B「妊娠反応検査」。

生殖年齢の女性の不正性器出血では、まず妊娠の有無を確かめる。異所性妊娠や流産を見落とせば命に関わるため、月経不順であっても妊娠反応検査が最初の一歩になる。

出典：厚生労働省ホームページ 第119回医師国家試験 C044',
     '{"A": "被曝を伴い、妊娠の可能性を否定する前に行うべきではない。", "C": "経腟超音波検査は次に行う重要な検査だが、妊娠反応の結果があってこそ所見を解釈できる。", "D": "子宮内膜組織診は子宮体癌を疑うときに行う。妊娠の可能性を否定してからである。", "E": "プロゲステロン投与は原因を確かめずに行うもので、妊娠中であれば診断を遅らせる。"}'),
    ('119-C-45', '正答は A「入院させる。」。

予防接種歴も乳児健診の記録もなく、栄養は明らかに不足し(1日400mLのミルクのみ、体重6,500g)、おむつは長時間交換されず衣類も汚れている。ネグレクトが強く疑われるので、まず入院させて身体の評価と保護を同時に行う。

出典：厚生労働省ホームページ 第119回医師国家試験 C045',
     '{"B": "通告先は児童相談所または市町村で、警察ではない。まず児の安全を確保する。", "C": "自宅に帰せば養育環境が変わらず、状態が悪化する。", "D": "家族への働きかけだけでは児の安全を確保できない。", "E": "5日続く発熱とけいれんの既往があり、翌日まで待てる状態ではない。"}'),
    ('119-C-46', '正答は A「Rorschachテスト」。

自傷と衝動的な過量服薬を繰り返し、対人関係が不安定という像からパーソナリティ障害が疑われる。Rorschachテストは投影法の人格検査で、意識されにくい内的な体験様式やパーソナリティ構造の理解に役立つ。

出典：厚生労働省ホームページ 第119回医師国家試験 C046',
     '{"B": "前頭葉機能検査は前頭葉障害の評価に用いる。", "C": "Wechsler成人知能検査は知的機能の評価に用いる。大学院を修了しており知的な問題は示唆されない。", "D": "リバーミード行動記憶検査は記憶障害の評価に用いる。", "E": "MMSEは認知機能のスクリーニング検査である。"}'),
    ('119-C-47', '正答は D「二酸化炭素中毒」。

遺体の保存に用いられるドライアイスが昇華して発生した二酸化炭素は空気より重く、棺の底部に高濃度で滞留する。そこに顔を入れた状態が続けば酸素欠乏と二酸化炭素中毒により意識を失い、そのまま死亡する。

出典：厚生労働省ホームページ 第119回医師国家試験 C047',
     '{"A": "トルエンは有機溶剤で、棺の中で発生するものではない。", "B": "硫化水素は硫黄を含む物質の腐敗や薬品の混合で生じるもので、この状況では発生しない。", "C": "一酸化炭素は不完全燃焼で生じる。棺の中に燃焼源はない。", "E": "ホルマリンは刺激臭が強く、通夜の棺で致死的な濃度になることはない。"}'),
    ('119-C-48', '正答は C「胎児心拍数モニタリング」。

羊水指数3cmは羊水過少(5cm以下)で、臍帯圧迫による胎児機能不全の危険が高い。まず胎児心拍数モニタリングで変動一過性徐脈などの所見がないかを確かめ、分娩のタイミングを判断する。

出典：厚生労働省ホームページ 第119回医師国家試験 C048',
     '{"A": "羊水検査は染色体異常の診断に行うもので、この時期に羊水過少の対応としては行わない。", "B": "胎児MRIは形態異常の精査に用いるが、緊急性の判断には役立たない。", "D": "推定体重1,500gは-1.5SD程度で、糖尿病の検索より胎児の状態把握が優先される。", "E": "HTLV-1抗体検査は妊娠初期に済ませる検査で、羊水過少の対応ではない。"}'),
    ('119-C-51', '正答は E「甲状腺ホルモン投与」。

神経性やせ症では飢餓への適応としてT3が低下する低T3症候群を示すが、これは代謝を落として身体を守る反応であり、甲状腺ホルモンを補うと代謝が上がってかえって消耗を招く。栄養の回復とともに自然に戻る。

出典：厚生労働省ホームページ 第119回医師国家試験 C051',
     '{"A": "再栄養症候群に注意しながら段階的に栄養を回復させることが治療の柱である。", "B": "体重や体型へのとらわれに対する心理療法が欠かせない。", "C": "家族の理解と協力が回復を左右するため、家族への支援も重要である。", "D": "無月経が長引けば骨密度が下がるため、体重が回復しない場合には女性ホルモンの投与を検討する。"}'),
    ('119-C-52', '正答は D「7日(木)」。

学校保健安全法では、インフルエンザは発症した後5日を経過し、かつ解熱した後2日を経過するまで出席停止とする。発症は12月1日なので6日を経過するのは12月7日、解熱は12月3日なので解熱後2日を経過するのも12月6日以降であり、登校できるのは7日(木)である。

出典：厚生労働省ホームページ 第119回医師国家試験 C052',
     '{"A": "4日(月)では発症後5日を経過していない。", "B": "5日(火)も発症後5日を経過していない。", "C": "6日(水)は発症の翌日から数えて5日目が終わる日で、まだ条件を満たさない。", "E": "8日(金)は条件を満たすが、7日から登校できるので最も早い日ではない。"}'),
    ('119-C-53', '正答は A「MRワクチン」。

MRワクチンの第2期は小学校就学前の1年間(年長児の4月1日から3月31日)に接種する。定期接種をすべて受けている5歳児にこの時期に勧めるのはMRワクチンである。

出典：厚生労働省ホームページ 第119回医師国家試験 C053',
     '{"B": "水痘ワクチンは1〜3歳未満に2回接種する。すでに済んでいる。", "C": "髄膜炎菌ワクチンは定期接種ではなく、渡航者などが任意で接種する。", "D": "小児用肺炎球菌ワクチンは生後2か月から始め、1歳過ぎの追加接種で完了する。", "E": "インフルエンザ桿菌〈Hib〉ワクチンも1歳過ぎの追加接種で完了する。"}'),
    ('119-C-54', '正答は C「脊椎圧迫骨折」。

関節リウマチでグルココルチコイドを長期に内服しており、続発性骨粗鬆症を背景に尻もちで椎体が圧潰したものである。背部正中の叩打痛が所見で、神経症状がなければ保存的に治療する。

出典：厚生労働省ホームページ 第119回医師国家試験 C054',
     '{"A": "尿管結石なら側腹部の疝痛と肋骨脊柱角の叩打痛、血尿を認める。", "B": "強直性脊椎炎は若年男性に多く、炎症性腰背部痛が緩やかに進行する。", "D": "腰部脊柱管狭窄症は間欠跛行が主症状で、外傷を契機に急に発症するものではない。", "E": "腰椎椎間板ヘルニアでは下肢の放散痛と神経症状を伴う。感覚・運動障害はない。"}'),
    ('119-C-55', '正答は E「「野菜を多く摂りましょう」」。

BMI22.0で肥満はなく、食塩5.5g/日、運動も毎日1時間、飲酒も月1回とすでに良好である。唯一届いていないのが野菜摂取量200g/日で、目標の350g/日に増やすよう勧める。カリウムと食物繊維の摂取は降圧に役立つ。

出典：厚生労働省ホームページ 第119回医師国家試験 C055',
     '{"A": "月1回で日本酒0.5合は節度ある適度な飲酒をはるかに下回る。", "B": "食塩5.5g/日はすでに6g/日未満の目標を満たしている。", "C": "BMI22.0は標準体重で、減量の対象にならない。", "D": "毎日1時間のジョギングは十分な運動量で、増やす必要はない。"}'),
    ('119-C-59', '正答は A「E4 V5 M6」。

開眼しているのでE4、日付・場所・名前を正確に答えられるのでV5、指示に従って四肢を動かせるのでM6である。合計15点で、意識は清明である。

出典：厚生労働省ホームページ 第119回医師国家試験 C059',
     '{"B": "指示に従えているのでM6であり、M5ではない。", "C": "同じくM6にあたる。", "D": "自ら開眼しておりE4で、見当識も保たれているのでV5である。", "E": "同じくE4、V5、M6である。"}'),
    ('119-C-60', '正答は D「本人からの問診は省略する。」。

設問は「適切でない」ものを選ぶもの。難聴はあるが、見当識は保たれ、医師が診察していることも理解できている。本人から話を聴かずに済ませるのは、本人しか知りえない情報を取り逃がし、意思決定の主体を奪うことになる。

出典：厚生労働省ホームページ 第119回医師国家試験 C060',
     '{"A": "耳元で大きめの声で話すのは、難聴のある人への基本的な配慮である。", "B": "短く簡潔な言い回しにするのは伝わりやすさを高める。", "C": "大きな声で話す分、周囲に聞かれない場所を選ぶ配慮が要る。", "E": "筆談を併せて使うのは、聞き取りの負担を減らす有効な手段である。"}'),
    ('119-C-62', '正答は C「ノルアドレナリン」。

脾臓を摘出しており、莢膜をもつ細菌による重症感染症を起こしやすい。発熱と低血圧、乳酸の上昇、足趾の暗紫色変化があり敗血症性ショックである。輸液を行っても血圧が戻らないので、ノルアドレナリンで血管を締めて平均血圧を保つ。

出典：厚生労働省ホームページ 第119回医師国家試験 C062',
     '{"A": "血小板は減っているが出血はなく、予防的に輸血する水準ではない。", "B": "ニトログリセリンは血管を広げるため、血圧をさらに下げてしまう。", "D": "グルココルチコイドは、十分な輸液と昇圧薬でも血圧が保てないときに考えるものである。", "E": "乳酸アシドーシスに対する重炭酸の投与は予後を改善せず、まず循環を立て直す。"}'),
    ('119-C-64', '正答は A「解剖終了後は遺体を家族に返還する。」。

病理解剖は遺族の承諾を得て行うもので、終わったあとは遺体を整えて家族に返す。死因の解明と医療の質の向上が目的である。

出典：厚生労働省ホームページ 第119回医師国家試験 C064',
     '{"B": "使用した器具は洗浄と滅菌を行って再び使う。すべて廃棄するものではない。", "C": "病理解剖は犯罪捜査とは関係がなく、警察への届出は要らない。", "D": "標準予防策を守れば足り、関わった全員が予防的に抗菌薬を飲むものではない。", "E": "死亡診断書は死亡を確認した時点で速やかに発行する。解剖報告書の完成を待つものではない。"}'),
    ('119-C-68', '正答は A「①」。

設問は高齢者機能評価簡易版に「含まれない」ものを選ぶもの。この評価は意欲、認知機能、手段的および基本的な日常生活動作、情緒・気分の項目からなる。下線部①は幻視の記述で、評価項目そのものではない。

出典：厚生労働省ホームページ 第119回医師国家試験 C068',
     '{"B": "入浴が自分でできるかは基本的な日常生活動作の項目である。", "C": "排泄が自立しているかも基本的な日常生活動作の項目である。", "D": "あいさつをするかどうかは意欲の項目にあたる。", "E": "自分が無力だと感じることは情緒・気分の項目にあたる。"}'),
    ('119-C-69', '正答は E「起立性低血圧」。

睡眠中の異常行動、具体的な幻視、認知機能の変動、パーキンソニズムが揃い、Lewy小体型認知症である。この疾患では自律神経障害を伴いやすく、高度な便秘に加えて起立性低血圧が現れる。転倒の一因にもなる。

出典：厚生労働省ホームページ 第119回医師国家試験 C069',
     '{"A": "失語は大脳皮質の言語野の障害でみられ、本例の主な症候ではない。", "B": "運動失調は小脳障害の所見である。", "C": "感覚障害は認めていない。", "D": "項部硬直は髄膜刺激徴候で、この病態では出ない。"}'),
    ('119-C-70', '正答は E「ドパミントランスポーターシンチグラフィ」。

ドパミントランスポーターシンチグラフィで線条体の集積低下を確かめられれば、黒質線条体のドパミン神経が脱落していることを示せる。Lewy小体型認知症を支持する所見となり、Alzheimer型認知症との鑑別に役立つ。

出典：厚生労働省ホームページ 第119回医師国家試験 C070',
     '{"A": "FDG-PETは腫瘍の評価が主で、この鑑別のための第一の検査ではない。", "B": "頸椎単純CTは頸椎症の評価に用いる。", "C": "頸部超音波検査は頸動脈の狭窄をみる検査である。", "D": "脳血管造影は侵襲が大きく、変性疾患の診断には用いない。"}'),
    ('119-D-1', '正答は D「衝動的行動を認める。」。

注意欠如多動性障害は不注意、多動性、衝動性を中核症状とする。順番を待てない、質問が終わる前に答えてしまうといった衝動的行動が、複数の場面で持続してみられる。

出典：厚生労働省ホームページ 第119回医師国家試験 D001',
     '{"A": "こだわりの強さは自閉スペクトラム症の特徴である。", "B": "知能は正常範囲のことが多い。", "C": "独り遊びが多いのは自閉スペクトラム症の特徴である。", "E": "多動は成長とともに目立たなくなることが多く、不注意が成人期まで残りやすい。"}'),
    ('119-D-3', '正答は C「術後72時間以上のベッド上安静」。

術後は早期離床が原則で、深部静脈血栓症、肺炎、腸管麻痺、筋力低下を防ぐ。72時間もベッド上で安静にさせるのは術後回復力強化(ERAS)の考え方に反する。

出典：厚生労働省ホームページ 第119回医師国家試験 D003',
     '{"A": "術前4週間以上の禁煙は術後の呼吸器合併症を減らす。", "B": "大腸手術では術前日に非吸収性抗菌薬を経口投与して腸内細菌を減らす。", "D": "腸管内容を除いておくことは手術操作と縫合の安全につながる。", "E": "清澄水は麻酔導入の2〜3時間前まで摂ってよく、脱水と不快感を避けられる。"}'),
    ('119-D-4', '正答は B「Campylobacter jejuni」。

Campylobacter jejuniは熱に弱く、十分な加熱(中心温度75°C以上で1分以上)で確実に死滅する。鶏肉の生食や加熱不足が主な原因で、Guillain-Barré症候群の先行感染としても重要である。

出典：厚生労働省ホームページ 第119回医師国家試験 D004',
     '{"A": "Bacillus cereusのセレウリドは耐熱性の毒素で、加熱しても分解されない。", "C": "Clostridium botulinumは芽胞をつくり、通常の加熱では死滅しない。", "D": "Clostridium perfringensも芽胞をつくり、加熱後の緩慢な冷却で増殖する。", "E": "Staphylococcus aureusのエンテロトキシンは耐熱性で、加熱しても無毒化されない。"}'),
    ('119-D-5', '正答は E「砕石位」。

膀胱鏡検査は砕石位(截石位)で行う。外尿道口を正面に出せて操作しやすく、消毒と清潔野の確保も容易である。

出典：厚生労働省ホームページ 第119回医師国家試験 D005',
     '{"A": "立位では器具の操作も清潔の保持もできない。", "B": "座位も同様に検査には適さない。", "C": "腹臥位では外尿道口に到達できない。", "D": "側臥位も尿道への挿入と操作に適さない。"}'),
    ('119-D-6', '正答は C「全身性エリテマトーデス〈SLE〉」。

特発性大腿骨頭壊死症の危険因子はグルココルチコイドの大量使用と多量飲酒である。全身性エリテマトーデスは大量のグルココルチコイドを用いるため合併が多く、股関節痛が出れば本症を疑う。

出典：厚生労働省ホームページ 第119回医師国家試験 D006',
     '{"A": "胃潰瘍は大腿骨頭壊死と関連しない。", "B": "狭心症も関連しない。", "D": "糖尿病そのものは危険因子として確立していない。", "E": "肺結核も直接の危険因子ではない。ただし治療でステロイドを用いれば別である。"}'),
    ('119-D-7', '正答は D「聴性脳幹反応〈ABR〉」。

3歳児では自覚的な応答による聴力検査が難しい。聴性脳幹反応は音刺激に対する脳幹の電位を記録するもので、睡眠下でも施行でき、他覚的に閾値を推定できる。

出典：厚生労働省ホームページ 第119回医師国家試験 D007',
     '{"A": "語音聴力検査は言葉の聞き取りを調べるもので、幼児では実施が難しい。", "B": "自記オージオメトリは被検者自身がボタンで応答する検査で、幼児には行えない。", "C": "純音聴力検査も自覚的応答を要する。遊戯聴力検査で代替することもあるが、確定には他覚的検査が要る。", "E": "ティンパノメトリは中耳の状態を調べる検査で、聴力そのものは測れない。"}'),
    ('119-D-8', '正答は B「過多月経 — ヘパリン起因性血小板減少症」。

ヘパリン起因性血小板減少症は、血小板が減るにもかかわらず血栓が生じるのが特徴で、出血ではなく動静脈血栓症を起こす。過多月経との組合せが誤りである。

出典：厚生労働省ホームページ 第119回医師国家試験 D008',
     '{"A": "von Willebrand病では血小板粘着障害により鼻出血や過多月経など粘膜出血をきたす。正しい組合せである。", "C": "急性前骨髄球性白血病では播種性血管内凝固を合併し、歯肉出血などの出血症状をきたす。正しい組合せである。", "D": "免疫性血小板減少症では血小板減少により点状出血や紫斑をきたす。正しい組合せである。", "E": "血友病では凝固第VIII・IX因子の欠乏により関節内出血や筋肉内出血をきたす。正しい組合せである。"}'),
    ('119-D-9', '正答は A「乳癌」。

角膜移植で問題になるのは、レシピエントへ伝播しうる感染症と、眼組織に病変が及ぶ疾患である。乳癌のような固形癌は眼球に転移していなければ提供の妨げにならない。

出典：厚生労働省ホームページ 第119回医師国家試験 D009',
     '{"B": "敗血症では血流に病原体が存在し、伝播の危険があるため提供できない。", "C": "白血病は全身性の血液悪性疾患で、提供の禁忌である。", "D": "B型肝炎はウイルスが伝播する危険があり提供できない。", "E": "Creutzfeldt-Jakob病は角膜移植による伝播が報告されており、絶対的禁忌である。"}'),
    ('119-D-20', '正答は A「色覚検査」。

焼け具合や水色とピンクの区別がつかず、弟にも同じ傾向がある。X連鎖潜性遺伝の先天赤緑色覚異常が疑われ、石原表などの色覚検査で確かめる。

出典：厚生労働省ホームページ 第119回医師国家試験 D020',
     '{"B": "視野検査は緑内障や視路の病変で行うもので、色の識別は評価できない。", "C": "両眼視機能検査は斜視や立体視の評価に用いる。", "D": "視覚誘発電位は視路の伝導を評価する検査である。", "E": "網膜電図は網膜色素変性など網膜全体の機能をみる検査である。"}'),
    ('119-D-22', '正答は C「抗SS-A抗体」。

抗SS-A抗体はIgGとして胎盤を通過し、胎児の刺激伝導系を障害して先天性完全房室ブロックを、また新生児ループスを起こしうる。妊娠16週以降は胎児心拍数と房室伝導の監視が必要になる。

出典：厚生労働省ホームページ 第119回医師国家試験 D022',
     '{"A": "抗Sm抗体は全身性エリテマトーデスに特異的だが、胎児への影響は知られていない。", "B": "抗RNP抗体は混合性結合組織病と関連するが、胎児への影響はない。", "D": "抗dsDNA抗体は疾患活動性の指標で、胎児に直接影響するものではない。", "E": "リウマトイド因子はIgMが主体で胎盤を通過せず、胎児への影響はない。"}'),
    ('119-D-23', '正答は E「2〜4週間後に甲状腺機能を再検する。」。

抗TPO抗体陽性の女性が産後5か月にTSH抑制とFT4高値を示しており無痛性甲状腺炎(産後甲状腺炎)である。破壊性の一過性甲状腺中毒症なので、抗甲状腺薬は用いず2〜4週後に再検して自然経過を追う。

出典：厚生労働省ホームページ 第119回医師国家試験 D023',
     '{"A": "ホルモンの合成が亢進しているのではなく、貯蔵ホルモンが漏れ出ている病態なので抗甲状腺薬は無効である。", "B": "一過性の病態であり手術の適応はない。", "C": "無機ヨウ素も合成を抑える薬で、破壊性の中毒症には効かない。", "D": "亜急性甲状腺炎のような疼痛や強い炎症はなく、グルココルチコイドは要さない。"}'),
    ('119-D-25', '正答は C「処置時の手袋の変更」。

処置の介助中に繰り返す喘鳴とラテックス特異的IgEの高値から、ラテックス手袋による職業性喘息(即時型アレルギー)である。原因への曝露を断つのが原則なので、ニトリル手袋など非ラテックス製に替える。

出典：厚生労働省ホームページ 第119回医師国家試験 D025',
     '{"A": "原因を取り除けば就業を続けられる。離職は最後の手段である。", "B": "手袋は院内のどの部署でも使うため、配置換えでは解決しない。", "D": "抗IgE抗体は重症の難治例に用いる。まず原因への曝露を断つ。", "E": "吸入ステロイドの増量は対症的で、原因が残る限り発作は繰り返す。"}'),
    ('119-D-26', '正答は C「抗TNF-α抗体製剤」。

抗TNF-α抗体製剤は肉芽腫の形成と維持を妨げ、潜在性結核を活動性へ転じさせる。活動性結核と診断されたら直ちに中止し、抗結核薬による治療を優先する。

出典：厚生労働省ホームページ 第119回医師国家試験 D026',
     '{"A": "NSAIDは結核の経過に影響せず、中止する必要はない。", "B": "カルシウム製剤も結核と無関係である。", "D": "プロトンポンプ阻害薬も中止の対象にならない。ただしリファンピシンとの相互作用には注意する。", "E": "活性型ビタミンD製剤も中止を要さない。"}'),
    ('119-D-27', '正答は B「食道ステント留置術」。

内視鏡も通過できない高度狭窄で、経口摂取を回復させるには狭窄部を広げる必要がある。食道ステント留置術は速やかに通過を確保でき、経口摂取の再開に直結する。

出典：厚生労働省ホームページ 第119回医師国家試験 D027',
     '{"A": "口腔ケアは誤嚥性肺炎の予防に有用だが、通過障害は解決しない。", "C": "内視鏡的筋層切開術はアカラシアに行う手技で、悪性狭窄には適応がない。", "D": "嚥下リハビリテーションは機能性の嚥下障害に行うもので、器質的狭窄には無効である。", "E": "胃瘻は栄養は入るが、経口摂取を可能にするという目的を満たさない。"}'),
    ('119-D-28', '正答は E「非侵襲的陽圧換気〈NPPV〉開始」。

筋萎縮性側索硬化症で%VC58%と呼吸筋力が落ち、呼吸困難と意識レベルの低下が生じており、二酸化炭素の貯留による呼吸不全である。方針として人工呼吸器の装着が合意されており、まず非侵襲的陽圧換気で換気を助ける。

出典：厚生労働省ホームページ 第119回医師国家試験 D028',
     '{"A": "筋力増強訓練は過用性の筋力低下を招くため本症では推奨されず、急性期の対応にもならない。", "B": "エダラボンは進行を遅らせる薬で、急性の呼吸不全には効かない。", "C": "意識レベルが低下しており帰宅させてはならない。", "D": "リルゾールも進行を遅らせる薬で、目の前の呼吸不全には対応できない。"}'),
    ('119-D-30', '正答は E「ダンピング症候群」。

胃全摘後に食後5〜10分で腹痛、下痢、動悸、顔面紅潮、めまいが現れており早期ダンピング症候群である。高浸透圧の食物が急速に小腸へ流入して腸管に体液が移動し、消化管ホルモンも放出されて起こる。少量頻回の食事と炭水化物の制限で対応する。

出典：厚生労働省ホームページ 第119回医師国家試験 D030',
     '{"A": "胆石症なら右季肋部痛が主で、脂肪食の後に数時間続く。", "B": "脈拍64/分で整であり、心房細動を示す所見はない。", "C": "腸閉塞なら腹部膨満と嘔吐、腸雑音の変化を伴い、症状は食後10分で自然に軽快しない。", "D": "巨赤芽球性貧血は胃全摘の数年後に生じるもので、貧血を認めない本例には当てはまらない。"}'),
    ('119-D-33', '正答は D「ヒトヘルペスウイルス6」。

3日間の高熱の後、解熱と入れ替わりに体幹中心の紅色丘疹が出現しており突発性発疹である。原因はヒトヘルペスウイルス6で、生後6か月から2歳ごろに初感染する。解熱後の不機嫌も特徴的である。

出典：厚生労働省ホームページ 第119回医師国家試験 D033',
     '{"A": "風疹では発熱と同時に発疹が出て、後頸部リンパ節が腫脹する。", "B": "麻疹では発疹出現時に発熱が続き、Koplik斑を伴う。", "C": "パルボウイルスB19による伝染性紅斑では両頰の紅斑が特徴的である。", "E": "EBウイルスによる伝染性単核症では扁桃の白苔とリンパ節腫脹、肝脾腫を伴う。"}'),
    ('119-D-34', '正答は E「心的外傷後ストレス障害〈PTSD〉」。

生命を脅かす事故を体験した後、1か月以上にわたり侵入的な想起、関連する状況の回避、不眠などの過覚醒が続き、生活が制限されている。心的外傷後ストレス障害である。

出典：厚生労働省ホームページ 第119回医師国家試験 D034',
     '{"A": "うつ病では抑うつ気分と興味の喪失が中核で、特定の場面を回避するという構造をとらない。", "B": "適応障害はより日常的なストレス因に対する反応で、外傷体験の再体験症状は説明できない。", "C": "脱抑制性対人交流症は幼少期の不適切な養育に起因する小児の疾患である。", "D": "反応性アタッチメント症も幼少期の養育に起因する小児の疾患である。"}'),
    ('119-D-35', '正答は B「遺伝子検査」。

男児で運動発達の遅れとCK16,500U/Lの著明な上昇を認め、母方に若年の心筋症死があることから、X連鎖潜性遺伝のDuchenne型筋ジストロフィーが疑われる。ジストロフィン遺伝子の解析で確定でき、保因者診断や治療法の選択にも直結する。

出典：厚生労働省ホームページ 第119回医師国家試験 D035',
     '{"A": "脳波検査はてんかんを疑うときに行うもので、本症の診断には寄与しない。", "C": "呼吸機能検査は経過中の呼吸筋障害の評価に用いるが、診断の手段ではない。", "D": "脳脊髄液検査は中枢神経の炎症や感染を疑うときに行う。", "E": "末梢神経伝導検査は神経原性疾患との鑑別に用いるが、確定診断には遺伝子検査が要る。"}'),
    ('119-D-36', '正答は E「抗ミトコンドリア抗体測定」。

中年女性の慢性の皮膚瘙痒感に、胆道系酵素の著明な上昇とIgM高値、非代償性肝硬変の所見がそろっており原発性胆汁性胆管炎である。抗ミトコンドリア抗体が90%以上で陽性となり、診断の柱になる。

出典：厚生労働省ホームページ 第119回医師国家試験 D036',
     '{"A": "造影CTは腫瘤の検索に有用だが、腫瘤は認めず診断には結びつかない。", "B": "血小板3.5万、PT-INR1.8で出血の危険が高く、経皮的肝生検は避けたい。", "C": "常用薬もサプリメントもなく、薬物性肝障害は考えにくい。", "D": "血清銅は基準内で、Wilson病を疑う所見がない。"}'),
    ('119-D-39', '正答は E「活性型ビタミンD製剤」。

Ca12.1mg/dLの高カルシウム血症があり、活性型ビタミンD製剤が腸管からのカルシウム吸収を増やして高カルシウム血症と腎機能悪化を招いている。まずこれを中止する。

出典：厚生労働省ホームページ 第119回医師国家試験 D039',
     '{"A": "浮腫があり、ループ利尿薬はむしろ高カルシウム血症の治療にも用いられる。", "B": "カルシウム拮抗薬は血清カルシウムに影響しない。", "C": "動脈血ガス分析は代謝性アシドーシスを示しておらず、重炭酸ナトリウムは問題にならない。", "D": "エリスロポエチン製剤は腎性貧血の治療薬で、高カルシウム血症とは無関係である。"}'),
    ('119-D-42', '正答は D「尿中アルブミン」。

糖尿病腎症は尿中アルブミンの増加から始まる。通常の試験紙法で蛋白が出る前の早期に検出できるので、随時尿でアルブミン/クレアチニン比を測って病期を判定する。

出典：厚生労働省ホームページ 第119回医師国家試験 D042',
     '{"A": "尿潜血は糸球体腎炎や尿路の病変を疑うときに調べる。", "B": "尿比重は尿濃縮能の目安で、腎症の病期判定には用いない。", "C": "尿ケトン体はインスリン欠乏の指標で、腎合併症の評価ではない。", "E": "尿中β2-マイクログロブリンは尿細管障害の指標で、糖尿病腎症の病期判定には用いない。"}'),
    ('119-D-44', '正答は B「抗菌薬の投与」。

抗甲状腺薬の開始から1か月で好中球12/μLの無顆粒球症をきたし、高熱とCRP27mg/dLで感染を合併している。直ちに抗甲状腺薬を中止し、緑膿菌を含む広域の抗菌薬を投与する。

出典：厚生労働省ホームページ 第119回医師国家試験 D044',
     '{"A": "顆粒球輸血は効果が限られ、標準的な対応ではない。", "C": "まず細菌感染を想定して治療する。抗真菌薬は好中球減少が遷延する場合に追加を考える。", "D": "抗甲状腺薬こそが無顆粒球症の原因であり、直ちに中止する。", "E": "ウイルス感染を疑う所見はない。"}'),
    ('119-D-45', '正答は D「アセトアミノフェン」。

鼻茸、気管支喘息、好酸球増多に加えて鎮痛薬で重篤な発作を起こした既往があり、アスピリン喘息(NSAID過敏喘息)である。シクロオキシゲナーゼ阻害作用の弱いアセトアミノフェンを少量から用いる。

出典：厚生労働省ホームページ 第119回医師国家試験 D045',
     '{"A": "モルヒネは緊張型頭痛に用いる薬ではなく、依存の問題もある。", "B": "インドメタシンはCOX阻害作用が強く、重篤な発作を誘発する。", "C": "メトトレキサートは頭痛の治療薬ではない。", "E": "コハク酸エステル型のステロイド静注も発作を誘発することがあり、頭痛の第一選択でもない。"}'),
    ('119-D-46', '正答は E「「たばこは息切れを起こす病気の原因になります」」。

喫煙による慢性閉塞性肺疾患が疑われる段階で、まず喫煙と症状の関係を伝えて禁煙の動機づけを行う。事実を穏やかに示して本人が考えられるようにすることが、行動変容の出発点になる。

出典：厚生労働省ホームページ 第119回医師国家試験 D046',
     '{"A": "加熱式たばこも有害物質を含み、切り替えは禁煙にならない。", "B": "受診を遠ざける言い方で、支援の機会を失う。", "C": "入院を要する状態ではなく、禁煙治療は外来で行える。", "D": "本数を減らすだけでは害を十分に減らせない。目標は完全な禁煙である。"}'),
    ('119-D-48', '正答は E「レム〈REM〉睡眠行動障害」。

就寝後に大声をあげ家具を倒すという夢に一致した行動が5年続き、その後に嗅覚低下、抑うつ、認知機能の低下、静止時振戦と筋強剛が現れている。レム睡眠行動障害で、Lewy小体病(Parkinson病・Lewy小体型認知症)に先行する徴候である。

出典：厚生労働省ホームページ 第119回医師国家試験 D048',
     '{"A": "チックは覚醒時にみられる突発的で反復性の運動である。", "B": "常同行動は同じ動作を繰り返すもので、睡眠中の行動ではない。", "C": "舞踏運動は不規則で流れるような不随意運動で、Huntington病などでみられる。", "D": "複雑部分発作では意識が減損し、自動症を伴う。出来事を夢として想起しない。"}'),
    ('119-D-49', '正答は E「選択的セロトニン再取込み阻害薬〈SSRI〉」。

誘因なく突然の動悸・発汗・呼吸困難・窒息感が繰り返し起こり、身体的な異常がなく、発作を恐れて外出を避けるようになっておりパニック障害である。薬物療法の第一選択はSSRIで、必要に応じて認知行動療法を併用する。

出典：厚生労働省ホームページ 第119回医師国家試験 D049',
     '{"A": "α遮断薬は褐色細胞腫や高血圧に用いる。", "B": "抗コリン薬は本症の治療薬ではない。", "C": "抗ヒスタミン薬もパニック発作には無効である。", "D": "ドパミン受容体遮断薬は統合失調症などに用いる。"}'),
    ('119-D-50', '正答は B「染色体検査」。

外見は女性で乳房も発育しているのに腋毛・陰毛を欠き、腟は盲端で子宮がなく、テストステロンが男性域まで高い。アンドロゲン不応症(精巣性女性化症)であり、核型が46,XYであることを染色体検査で確かめる。鼠径部の腫瘤は停留精巣である。

出典：厚生労働省ホームページ 第119回医師国家試験 D050',
     '{"A": "頭部MRIは下垂体性の原発性無月経を疑うときに行う。LHは高く下垂体は働いている。", "C": "LHRH負荷試験は下垂体の反応をみる検査で、本例の本質を捉えられない。", "D": "子宮がないので子宮卵管造影は行えない。", "E": "エストロゲン・プロゲステロン負荷試験は子宮内膜の反応をみる検査で、子宮のない本例には意味がない。"}'),
    ('119-D-51', '正答は B「溶血性尿毒症症候群」。

焼き肉の後の血性下痢に、破砕赤血球を伴う溶血性貧血、血小板5.2万、クレアチニン4.2mg/dLの腎障害という三徴がそろっており、腸管出血性大腸菌感染に続発した溶血性尿毒症症候群である。

出典：厚生労働省ホームページ 第119回医師国家試験 D051',
     '{"A": "感染後糸球体腎炎は溶連菌感染の1〜2週後に血尿と浮腫、補体低下をきたす。溶血や血小板減少は伴わない。", "C": "急速進行性糸球体腎炎では血尿と赤血球円柱を認め、ANCAなどが陽性となる。", "D": "播種性血管内凝固ではPT延長やFDP上昇を伴う。凝固検査に異常を示す所見がない。", "E": "全身性エリテマトーデスでは慢性の経過をたどり、抗核抗体が陽性となる。急性の血便から始まる本例とは異なる。"}'),
    ('119-D-52', '正答は A「「骨盤底筋訓練は術後早期から行います」」。

前立腺全摘除術の後は尿失禁が問題になる。骨盤底筋訓練は術前から指導し、カテーテル抜去後の早期から始めることで回復が早まる。

出典：厚生労働省ホームページ 第119回医師国家試験 D052',
     '{"B": "膀胱カテーテルは吻合部の治癒を待って術後1週間前後で抜去する。1か月は長すぎる。", "C": "予防的抗菌薬は術直前から術後24時間程度までで、長期投与は耐性菌を生むだけである。", "D": "深部静脈血栓症の予防は手術中から弾性ストッキングや間欠的空気圧迫法で始める。", "E": "リンパ節郭清後のリンパ浮腫対策は術直後から指導する。"}'),
    ('119-D-53', '正答は D「高張(3%)食塩液の輸液」。

サイアザイド系利尿薬によるNa116mEq/Lの低ナトリウム血症で、意識障害を伴う症候性の急性増悪である。高張(3%)食塩液を投与してナトリウムを緩やかに上げる。上げすぎは浸透圧性脱髄症候群を招くので、24時間で8〜10mEq/L以内にとどめる。

出典：厚生労働省ホームページ 第119回医師国家試験 D053',
     '{"A": "飲水制限は抗利尿ホルモン不適合分泌症候群などで用いるが、意識障害のある急性期には効果が遅すぎる。", "B": "ループ利尿薬はナトリウムの喪失を助長する。", "C": "5%ブドウ糖液は自由水を与えることになり、低ナトリウム血症を悪化させる。", "E": "バソプレシンV2受容体拮抗薬は効果発現までに時間がかかり、急速な補正の危険もある。"}'),
    ('119-D-55', '正答は C「膀胱瘻造設」。

会陰部打撲後の尿閉と皮下出血、逆行性尿道造影で膀胱が描出されないことから尿道損傷である。経尿道的なカテーテル留置は損傷を悪化させるため、膀胱瘻を造設して尿路を確保する。

出典：厚生労働省ホームページ 第119回医師国家試験 D055',
     '{"A": "MRIは損傷部位の詳細な評価に有用だが、まず尿路の確保が先である。", "B": "膀胱鏡の挿入も損傷部を広げる危険がある。", "D": "NSAIDでは尿閉は解除できない。", "E": "尿道カテーテルの留置は尿道損傷では禁忌である。"}'),
    ('119-D-58', '正答は E「総肺静脈還流異常症」。

右心房から大動脈まで酸素飽和度がほぼ均一に85%前後で、全身の血液が完全に混ざっている。肺静脈血が左心房ではなく右心系へ還り、心房間交通を通じて体循環へ送られる総肺静脈還流異常症である。

出典：厚生労働省ホームページ 第119回医師国家試験 D058',
     '{"A": "Ebstein奇形では三尖弁の異常により右心房が拡大するが、全身で酸素飽和度が均一になるわけではない。", "B": "Fallot四徴症では右心室から大動脈への右左短絡があり、右心室以降で酸素飽和度が下がる。", "C": "大動脈離断症では上下肢で酸素飽和度に差が生じる。", "D": "完全大血管転位症では肺動脈の酸素飽和度が大動脈より高くなり、著しい差を生じる。"}'),
    ('119-D-61', '正答は C「胸腹部エックス線撮影」。

コイン型リチウム電池は食道に停滞すると数時間で粘膜の壊死と穿孔をきたす。無症状でも直ちに胸腹部エックス線写真で位置を確かめ、食道内にあれば緊急に内視鏡で摘出する。

出典：厚生労働省ホームページ 第119回医師国家試験 D061',
     '{"A": "動脈血ガス分析は病態の把握に寄与しない。", "B": "造影検査は誤嚥の危険があり、その後の内視鏡操作も妨げる。", "D": "内視鏡は摘出のために行うが、まず位置と個数をエックス線写真で確かめる。", "E": "食道に停滞していれば数時間で穿孔しうる。自宅で経過をみてはならない。"}'),
    ('119-D-62', '正答は E「ペニシリンアレルギーの精査」。

ペニシリンアレルギーの申告の多くは真のアレルギーではなく、精査すれば標準的な除菌療法を安全に行えることが多い。まず皮膚テストや特異的IgEの測定で本当にアレルギーかを確かめる。

出典：厚生労働省ホームページ 第119回医師国家試験 D062',
     '{"A": "重篤な即時型反応が疑われる病歴があり、確かめずにペニシリンを投与するのは危険である。", "B": "マクロライド単剤では除菌できず、耐性菌を生む。", "C": "酸分泌抑制薬単剤では除菌できない。", "D": "迅速ウレアーゼ試験は陽性で、再検の必要はない。"}'),
    ('119-D-65', '正答は C「口部自動症」。

3か月前に反応が止まって数分続くエピソードがあり、脳波で左側頭部に鋭波を認め、最近は健忘のエピソードが繰り返している。側頭葉てんかんの焦点意識減損発作で、口をもぐもぐさせる口部自動症を伴う。

出典：厚生労働省ホームページ 第119回医師国家試験 D065',
     '{"A": "音過敏は片頭痛の随伴症状である。", "B": "閃輝暗点は片頭痛の前兆である。", "D": "静止時振戦はParkinson病の症状である。", "E": "線維束性収縮は下位運動ニューロン障害の所見である。"}'),
    ('119-D-66', '正答は B「2」。

母親が乳癌で死亡しているという第一度近親者の家族歴は、乳癌の明確な危険因子である。若年発症や両側性、卵巣癌の家族歴があれば遺伝性乳癌卵巣癌症候群も考える。

出典：厚生労働省ホームページ 第119回医師国家試験 D066',
     '{"A": "高血圧症は乳癌の危険因子ではない。", "C": "初経12歳は平均的で、早発初経(11歳未満)にはあたらない。", "D": "出産経験はむしろ乳癌の危険を下げる。未産・初産年齢が高いことが危険因子である。", "E": "BMI20.3は標準で、閉経後の肥満という危険因子には当たらない。"}'),
    ('119-E-1', '正答は D「下肢の冷感 — 深部静脈血栓症」。

深部静脈血栓症では静脈の還流が妨げられるため、患肢は腫脹し熱感と発赤を伴う。冷感は動脈閉塞の所見であり、この組合せが誤りである。

出典：厚生労働省ホームページ 第119回医師国家試験 E001',
     '{"A": "腰部脊柱管狭窄症では馬尾が圧迫されて膀胱直腸障害をきたすことがある。正しい組合せである。", "B": "頸椎性脊髄症では下肢の痙性により歩行障害をきたす。正しい組合せである。", "C": "大動脈解離では引き裂かれるような胸背部痛が突然生じる。正しい組合せである。", "E": "偽痛風はピロリン酸カルシウムの結晶により膝関節の急性腫脹と疼痛をきたす。正しい組合せである。"}'),
    ('119-E-2', '正答は C「病歴」。

個人情報保護法は、人種、信条、社会的身分、病歴、犯罪の経歴、犯罪により害を被った事実などを要配慮個人情報と定め、取得や第三者提供に原則として本人の同意を要するとしている。

出典：厚生労働省ホームページ 第119回医師国家試験 E002',
     '{"A": "学歴は要配慮個人情報に含まれない。", "B": "国籍そのものは要配慮個人情報とされていない(人種は該当する)。", "D": "肌の色は人種に関わる情報だが、法が列挙するのは「人種」である。病歴のほうが医療現場では明確に該当する。", "E": "職業的地位も要配慮個人情報には含まれない。"}'),
    ('119-E-3', '正答は E「共同意思決定」。

医療倫理の4原則は、自律尊重、無危害、善行、正義である。共同意思決定は自律尊重を実践するための方法であって、原則そのものではない。

出典：厚生労働省ホームページ 第119回医師国家試験 E003',
     '{"A": "正義(公正)は資源の配分や負担の分かち方に関わる原則である。", "B": "善行は患者の利益を最大にするよう努める原則である。", "C": "無危害は害を与えないという原則である。", "D": "自律尊重は患者の自己決定を尊重する原則である。"}'),
    ('119-E-4', '正答は B「性交渉相手の人数を確認する。」。

性交渉相手の人数は感染の危険度の評価と、接触者への対応を考えるうえで欠かせない情報である。非難する調子にならないよう配慮しつつ、必要な情報として尋ねる。

出典：厚生労働省ホームページ 第119回医師国家試験 E004',
     '{"A": "診断と治療の方針に直結するので、初診時から聴取する。", "C": "保護者の同席は本人が話しにくくなる。本人だけの場を確保して聴くのが原則である。", "D": "配偶者からの感染も、配偶者への感染もありうるので聴取する。", "E": "経口避妊薬は性感染症を防がない。むしろコンドームを使っていない可能性を考える。"}'),
    ('119-E-5', '正答は A「「会議中に突然眠ってしまいます」」。

ナルコレプシーは日中に耐えがたい眠気の発作が繰り返し起こる過眠症で、会議中や会話中など不適切な場面で突然眠り込む。情動脱力発作、入眠時幻覚、睡眠麻痺を伴うことがある。

出典：厚生労働省ホームページ 第119回医師国家試験 E005',
     '{"B": "入眠困難が続くのは睡眠相後退症候群や不眠症である。", "C": "眠れないことへの不安は精神生理性不眠の訴えである。", "D": "睡眠中の下肢の反復的な動きは周期性四肢運動障害である。", "E": "睡眠中の摂食は睡眠関連摂食障害である。"}'),
    ('119-E-6', '正答は A「「うつぶせの姿勢で行います」」。

腰椎穿刺は側臥位で背中を丸め、棘突起間を開いた姿勢で行う。腹臥位では椎間が開かず穿刺できない。

出典：厚生労働省ホームページ 第119回医師国家試験 E006',
     '{"B": "出血傾向があると硬膜外血腫の危険があるため、血小板数と凝固能を事前に確かめる。", "C": "針が神経根に触れると下肢に放散する痛みが走ることがある。", "D": "頭蓋内圧が高いと脳ヘルニアを起こす危険があるので、うっ血乳頭や占拠性病変の有無を事前に確かめる。", "E": "髄液が漏れて低髄液圧となり、立位で悪化する頭痛(穿刺後頭痛)が起こりうる。"}'),
    ('119-E-7', '正答は B「自己の利益を追求する。」。

プロフェッショナリズムの基本は患者の利益を自己の利益に優先させることである。自己の利益の追求はこれに反する。

出典：厚生労働省ホームページ 第119回医師国家試験 E007',
     '{"A": "科学的根拠に基づく医療の実践と生涯学習は専門職の責務である。", "C": "社会のニーズに応え、公衆衛生に貢献することも責務に含まれる。", "D": "患者の感情を理解し共感を示すことは専門職の態度として求められる。", "E": "限られた医療資源を適正に配分することへの配慮も責務である。"}'),
    ('119-E-9', '正答は E「強迫観念によって生じる不安を予防あるいは緩和する目的で行われる。」。

強迫行為は、強迫観念によって生じた不安を打ち消すために行われる反復的な行動である。行えば一時的に不安は和らぐが、繰り返すうちにやめられなくなり生活を侵食する。

出典：厚生労働省ホームページ 第119回医師国家試験 E009',
     '{"A": "症状に日内変動はない。日内変動はうつ病でみられる。", "B": "意識は保たれ、行為の記憶もある。", "C": "多くの患者は不合理と自覚しながらやめられない(自我違和的)。", "D": "幻聴に従う行動は統合失調症の症状で、強迫行為とは異なる。"}'),
    ('119-E-10', '正答は A「事務職員も参加できる。」。

チーム医療は多職種がそれぞれの専門性を持ち寄って患者を支える取組みで、医療事務や医療ソーシャルワーカーなど診療に直接携わらない職種も重要な一員である。

出典：厚生労働省ホームページ 第119回医師国家試験 E010',
     '{"B": "医師の指示は医学的判断について必要だが、他職種の専門的意見も対等に検討される。", "C": "目的は患者にとってよい医療を提供することであって、経営業績の向上ではない。", "D": "多様な意見を出し合って検討することにこそ意味があり、全員一致は要件でない。", "E": "地域の医療機関や介護事業所も含めた連携が推奨されている。"}'),
    ('119-E-11', '正答は E「肋骨脊柱角の叩打診」。

腎盂腎炎では腎被膜の伸展と炎症により、患側の肋骨脊柱角に叩打痛を認める。発熱と膿尿とあわせて診断の柱になる。

出典：厚生労働省ホームページ 第119回医師国家試験 E011',
     '{"A": "振水音は胃内容の停滞をみる所見で、幽門狭窄などで聴かれる。", "B": "Traube三角の打診は脾腫の評価に用いる。", "C": "鼠径リンパ節の触診は下肢や外陰部の感染・悪性腫瘍の評価に用いる。", "D": "腹部血管雑音は腎動脈狭窄や腹部大動脈瘤を疑うときに聴取する。"}'),
    ('119-E-13', '正答は E「便通異常 — 過敏性腸症候群」。

過敏性腸症候群は腹痛と便通異常(下痢・便秘・その交代)が慢性に続き、排便により症状が変わるのが特徴である。器質的異常を伴わない。

出典：厚生労働省ホームページ 第119回医師国家試験 E013',
     '{"A": "膵炎の主症状は上腹部痛と背部痛で、嚥下障害はきたさない。", "B": "腸閉塞では嘔吐と腹部膨満をきたす。黄疸は胆道閉塞や肝疾患の所見である。", "C": "潰瘍性大腸炎は下部消化管の病変で、粘血便をきたす。吐血は上部消化管出血の症状である。", "D": "胃食道逆流症の症状は胸やけと呑酸で、腹部膨隆は伴わない。"}'),
    ('119-E-14', '正答は A「視力障害」。

砕石位で長時間手術を行うと、下腿の神経圧迫や区画症候群、深部静脈血栓症、接地部の褥瘡、体位解除時の静脈還流の急減による低血圧が問題になる。視力障害が問題になるのは腹臥位での長時間手術である。

出典：厚生労働省ホームページ 第119回医師国家試験 E014',
     '{"B": "腓骨頭部の圧迫による総腓骨神経麻痺や、股関節の過屈曲による大腿神経麻痺が起こりうる。", "C": "下肢の静脈還流が滞るため深部静脈血栓症の危険が高まる。", "D": "支脚器や仙骨部の接地面に圧迫性の潰瘍を生じうる。", "E": "下肢を下ろすと血液が下肢に移動し、静脈還流が減って血圧が下がる。"}'),
    ('119-E-15', '正答は C「1型糖尿病」。

1型糖尿病は膵β細胞が自己免疫機序で破壊されて起こるもので、喫煙との関連は乏しい。喫煙が危険因子となるのは2型糖尿病である。

出典：厚生労働省ホームページ 第119回医師国家試験 E015',
     '{"A": "喫煙は歯周組織の血流と免疫を損ない、歯周病の最大の環境危険因子である。", "B": "喫煙は動脈壁の脆弱化を招き、腹部大動脈瘤の強い危険因子である。", "D": "喫煙は動脈硬化を促進し、冠動脈疾患の主要な危険因子である。", "E": "慢性閉塞性肺疾患の原因の大半は喫煙である。"}'),
    ('119-E-16', '正答は E「上肢Barré試験」。

上肢Barré試験は両上肢を前方に挙げて閉眼させ、回内しながら下垂するかをみる検査で、錐体路障害による軽度の片麻痺を捉える。小脳機能の評価には用いない。

出典：厚生労働省ホームページ 第119回医師国家試験 E016',
     '{"A": "膝踵試験は踵を対側の膝に当てて脛に沿って滑らせる検査で、下肢の協調運動をみる。", "B": "指鼻試験は上肢の測定障害と企図振戦をみる。", "C": "鼻指鼻試験も上肢の協調運動をみる検査である。", "D": "回内回外試験は反復拮抗運動不能をみる検査である。"}'),
    ('119-E-17', '正答は A「1番染色体」。

1番染色体はヒトで最も大きく、約2,000個と最も多くの遺伝子を含む。染色体の大きさと遺伝子数はおおむね対応する。

出典：厚生労働省ホームページ 第119回医師国家試験 E017',
     '{"B": "16番染色体は1番よりはるかに小さく、遺伝子数も少ない。", "C": "18番染色体は遺伝子密度が低い染色体である。", "D": "21番染色体はヒトで最も小さく、遺伝子数も最も少ない部類である。トリソミーでも生存できるのはこのためである。", "E": "X染色体は中程度の大きさで、遺伝子数も1番染色体には及ばない。"}'),
    ('119-E-18', '正答は D「ポビドンヨード」。

ポビドンヨードは殺菌スペクトルが広く組織への刺激が比較的少ないため、開放創や粘膜の消毒に用いることができる。

出典：厚生労働省ホームページ 第119回医師国家試験 E018',
     '{"A": "エタノールは正常皮膚の消毒には用いるが、開放創では強い疼痛と組織傷害を生じる。", "B": "グルタールアルデヒドは器具の消毒に用いる薬剤で、生体には使えない。", "C": "次亜塩素酸ナトリウムは環境や器具の消毒に用いる。組織傷害性が強い。", "E": "ホルマリンは固定に用いる薬剤で、生体の消毒には使えない。"}'),
    ('119-E-19', '正答は E「「(鳴っていない携帯電話を見せながら)今もこの電話の着信音がやまないのです」」。

鳴っていない携帯電話の着信音が聞こえるという訴えは、対象のない知覚である幻聴にあたる。実在しない刺激を知覚するのが幻覚の定義である。

出典：厚生労働省ホームページ 第119回医師国家試験 E019',
     '{"A": "人前での緊張は社交不安の訴えで、知覚の異常ではない。", "B": "知らない人が自分を見て笑うという訴えは、実在する刺激の誤った解釈で関係妄想にあたる。", "C": "食事の味が砂のように感じるのは、実在する刺激に対する感覚の変化である。", "D": "天井のしみを意味づけるのは、実在する対象への妄想的解釈である。"}'),
    ('119-E-20', '正答は D「第1腰髄」。

鼠径部の皮膚分節は第1腰髄が支配する。それより下のすべての感覚が失われているので、損傷レベルは第1腰髄である。乳頭がT4、剣状突起がT6、臍がT10という目印とあわせて覚える。

出典：厚生労働省ホームページ 第119回医師国家試験 E020',
     '{"A": "第4頸髄なら鎖骨から下の感覚が失われる。", "B": "第5胸髄なら乳頭のやや下から失われる。", "C": "第10胸髄なら臍のレベルから失われる。", "E": "脊髄円錐部の損傷では会陰部の鞍状の感覚障害と膀胱直腸障害が主体で、鼠径部以下すべてが失われるわけではない。"}'),
    ('119-E-21', '正答は E「Gram染色の鏡検で上皮細胞が多い検体」。

扁平上皮細胞が多い検体は口腔内の唾液が主体で、下気道の情報を反映しない。Geckler分類やMiller-Jones分類で質を評価し、上皮細胞が多ければ採り直す。

出典：厚生労働省ホームページ 第119回医師国家試験 E021',
     '{"A": "うがいで口腔内の常在菌を減らしてから採取するのは適切である。", "B": "膿性部分を選んで検査するのは適切である。", "C": "痰が出ない場合に高張食塩水の吸入で誘発するのは適切な方法である。", "D": "白血球が多いのは下気道の炎症を反映しており、質のよい検体である。"}'),
    ('119-E-22', '正答は A「解釈モデルを確認する。」。

生活習慣の改善は本人が納得して初めて続く。まず患者が自分の状態や生活習慣をどう理解しているか(解釈モデル)を聴き取り、そこを出発点として一緒に方針を立てる。

出典：厚生労働省ホームページ 第119回医師国家試験 E022',
     '{"B": "医師主導で決めた目標は実行に結びつきにくい。本人が決めることが要である。", "C": "必要な情報は伝えるべきで、不安への配慮は伝え方の工夫で行う。", "D": "専門用語は理解を妨げる。平易な言葉で説明する。", "E": "生活背景は一人ひとり違うので、画一的な指導では実行できない。"}'),
    ('119-E-25', '正答は D「副作用」。

投与後に生じた症状がその薬によるものかを判断するには、まず添付文書の副作用の項で、報告されている皮膚症状とその頻度、重篤な副作用(Stevens-Johnson症候群など)を確かめる。

出典：厚生労働省ホームページ 第119回医師国家試験 E025',
     '{"A": "効能又は効果は適応を確かめる項である。", "B": "用法及び用量は投与方法を確かめる項である。", "C": "相互作用は併用薬との関係を確かめる項で、次に確かめる項目にあたる。", "E": "薬物動態は吸収・分布・代謝・排泄を示す項である。"}'),
    ('119-E-26', '正答は B「2」。

推定エネルギー必要量は、標準体重(身長から算出)に身体活動レベルに応じた係数を掛けて求める。身長と職業(事務職=軽い労作)が必要で、下線部のうち該当するのは事務職という職業の情報である。

出典：厚生労働省ホームページ 第119回医師国家試験 E026',
     '{"A": "高血圧という診断名は必要量の算出に用いない。", "C": "過食気味であることは現在の摂取量の問題で、必要量の算出には用いない。", "D": "脈拍は算出に用いない。", "E": "LDLコレステロール値は脂質の配分を考える材料だが、総エネルギー量の算出には用いない。"}'),
    ('119-E-27', '正答は D「下肢静脈超音波検査」。

手術を控えた患者に、悪性腫瘍の治療中、下肢の圧痕性浮腫、Dダイマー9.0μg/mLがそろっており深部静脈血栓症が強く疑われる。下肢静脈超音波検査で血栓の有無を確かめ、あれば手術前に対応する。

出典：厚生労働省ホームページ 第119回医師国家試験 E027',
     '{"A": "腹部単純CTは腹腔内の評価で、下肢静脈の血栓は捉えられない。", "B": "腎シンチグラフィは分腎機能の評価に用いる。", "C": "下肢動脈造影は動脈閉塞の評価で、静脈血栓は評価できない。", "E": "足関節上腕血圧比も動脈の評価で、静脈血栓の診断には使えない。"}'),
    ('119-E-29', '正答は B「0.2mL/時間」。

1日24mgを5mg/mLの溶液で投与するので、必要量は24÷5=4.8mL/日である。これを24時間で割ると0.2mL/時間となる。

出典：厚生労働省ホームページ 第119回医師国家試験 E029',
     '{"A": "0.1mL/時間では1日2.4mL、12mgにしかならない。", "C": "0.4mL/時間では1日9.6mL、48mgと倍量になる。", "D": "0.5mL/時間では60mg/日になる。", "E": "0.8mL/時間では96mg/日と大幅な過量になる。"}'),
    ('119-E-31', '正答は E「硫酸マグネシウム」。

妊娠高血圧腎症に意識消失とけいれんが加わり子癇である。硫酸マグネシウムがけいれんの止痙と再発予防の第一選択で、投与中は腱反射、呼吸数、尿量を監視する。

出典：厚生労働省ホームページ 第119回医師国家試験 E031',
     '{"A": "グルコン酸カルシウムは硫酸マグネシウム中毒が起きたときの拮抗薬である。", "B": "ドパミンは昇圧薬で、高血圧の本例には用いない。", "C": "ニトログリセリンは降圧に用いることはあるが、けいれんは止まらない。", "D": "フロセミドは肺水腫を合併した場合に用いるもので、けいれんの治療薬ではない。"}'),
    ('119-E-32', '正答は D「「どのようにしたら減塩できると思いますか」」。

塩分の摂りすぎを気にしているが実行には至っていない関心期にあたる。具体的な指示を与えるより、どうすれば減塩できそうかを本人に考えてもらい、実行への準備を促すのが適切である。

出典：厚生労働省ホームページ 第119回医師国家試験 E032',
     '{"A": "恐怖に訴える伝え方は反発を招きやすい。", "B": "知識としてはすでに気にしており、情報提供だけでは行動につながらない。", "C": "具体的な指示は準備期以降に適する。関心期では実行の障壁を一緒に考える。", "E": "受診と支援の機会を手放す言い方で、適切でない。"}'),
    ('119-E-33', '正答は C「項部硬直」。

これまでに経験したことのない突然の激しい頭痛はくも膜下出血を第一に疑う。髄膜刺激徴候である項部硬直を確かめ、疑えば頭部CTと必要に応じて腰椎穿刺に進む。

出典：厚生労働省ホームページ 第119回医師国家試験 E033',
     '{"A": "耳鳴は突発性難聴やMénière病でみられる。", "B": "結膜充血は急性緑内障発作や群発頭痛でみられるが、緊急性の判断の主軸ではない。", "D": "閃輝暗点は片頭痛の前兆で、緊急性は高くない。", "E": "四肢のしびれは脳梗塞などで問診するが、この頭痛でまず確かめるのは髄膜刺激徴候である。"}'),
    ('119-E-34', '正答は E「疼痛コントロール」。

「早く死なせて欲しい」という訴えの多くは、耐えがたい苦痛から逃れたいという願いである。まず疼痛を十分に緩和することが最優先で、痛みが取れれば訴えが変わることも多い。

出典：厚生労働省ホームページ 第119回医師国家試験 E034',
     '{"A": "本人が望んでおらず、また苦痛の解決にならない。", "B": "眠れないほどの痛みを放置してはならない。", "C": "生命を積極的に終わらせる行為は許されない。", "D": "終末期の高カロリー輸液は苦痛を増すことがあり、訴えへの答えにもならない。"}'),
    ('119-E-35', '正答は D「④」。

市中肺炎の重症度分類A-DROPは、年齢(男性70歳以上)、脱水、呼吸(SpO2 90%以下)、意識障害、収縮期血圧90mmHg以下の5項目で評価する。SpO2 90%は呼吸の項目に該当し、意識障害と脱水に加えて入院を要すると判断する根拠になる。

出典：厚生労働省ホームページ 第119回医師国家試験 E035',
     '{"A": "57歳は男性70歳以上という年齢の基準を満たさない。", "B": "同居家族の症状は感染源の推定には役立つが、重症度の評価項目ではない。", "C": "体温は A-DROPの評価項目に含まれない。", "E": "coarse cracklesは肺炎の存在を示す所見で、重症度の評価項目ではない。"}'),
    ('119-E-36', '正答は E「「入院して経過をみましょう」」。

灯油などの炭化水素は誤嚥すると化学性肺炎を起こす。現時点で呼吸器症状はなくても数時間後に発症しうるので、入院して経過を観察する。

出典：厚生労働省ホームページ 第119回医師国家試験 E036',
     '{"A": "催吐は誤嚥の危険を高めるため禁忌である。", "B": "胃洗浄も誤嚥を招くため行わない。", "C": "牛乳は吸収を促すおそれがあり、また嘔吐を誘発する。", "D": "呼吸状態は保たれており、現時点で人工呼吸管理を要さない。"}'),
    ('119-E-37', '正答は C「3」。

薬剤1〜3はいずれも発症率を10%減らし効果は同等なので、最も安価な3(年間4,000円)が費用対効果に優れる。4と5は効果がないので、費用にかかわらず選べない。

出典：厚生労働省ホームページ 第119回医師国家試験 E037',
     '{"A": "1は同じ効果で年間20,000円と最も高い。", "B": "2も同じ効果で12,000円と3より高い。", "D": "4は効果がないうえ20,000円かかる。", "E": "5は安価だが効果がなく、目的を果たさない。"}'),
    ('119-E-39', '正答は E「82%」。

スコアは持続時間2分以内で1点、寝返りで誘発されて2点、安静時のめまいがないので減点なしの計3点、陽性尤度比6.8である。事前確率40%はオッズ0.67で、6.8を掛けると事後オッズ4.5、確率に戻すと約82%になる。

出典：厚生労働省ホームページ 第119回医師国家試験 E039',
     '{"A": "8%は尤度比0.2(0点)に相当する低い値である。", "B": "19%は尤度比0.1(−1点)に近い値である。", "C": "47%は尤度比1.3(1点)に相当する。", "D": "65%は尤度比2.8(2点)に相当する。"}'),
    ('119-E-40', '正答は B「2」。

尿が出にくいという排尿障害に、会陰部の知覚障害と肛門括約筋の収縮低下が加わっており馬尾症候群である。放置すれば膀胱直腸障害が不可逆となるため、緊急の画像診断と除圧手術を要する。

出典：厚生労働省ホームページ 第119回医師国家試験 E040',
     '{"A": "体動で増強する腰痛は椎間板ヘルニアの一般的な症状で、緊急性を示すものではない。", "C": "顔のほてりは更年期症状で、この病態とは無関係である。", "D": "8年前の子宮頸癌手術は骨転移の可能性を考える材料だが、今すぐの対応を迫る所見ではない。", "E": "1年で4kgの体重増加は緊急性を示さない。"}'),
    ('119-E-41', '正答は A「アドレナリン」。

造影剤の投与から5分で、低血圧、頻脈、皮膚の発赤と腫脹、顔面浮腫、吸気性喘鳴が現れた。アナフィラキシーショックであり、アドレナリンを大腿前外側に筋注する。遅らせるほど死亡率が上がる。

出典：厚生労働省ホームページ 第119回医師国家試験 E041',
     '{"B": "アトロピンは徐脈への薬で、本例は頻脈である。", "C": "グルココルチコイドは遅発性の反応を抑える目的で併用するが、初期対応の主役ではない。", "D": "グルコン酸カルシウムは高カリウム血症などの適応である。", "E": "ジアゼパムはけいれんの治療に用いる。"}'),
    ('119-E-42', '正答は E「患者の診療録上の所定の位置に有害事象を記録する。」。

以前にもヨード造影剤で気分不快が出ていたことが後から判明した。この情報が診療録の決まった場所に記録され、次に造影検査を計画する人が必ず目にする形になっていれば、繰り返さずに済む。

出典：厚生労働省ホームページ 第119回医師国家試験 E042',
     '{"A": "クリニカルパスは標準的な診療の流れを定めるもので、個人の有害事象を伝える仕組みではない。", "B": "医療事故調査制度は、予期しない死亡が起きたときの調査の仕組みである。", "C": "医療安全支援センターは患者からの相談を受ける窓口である。", "D": "製薬会社への報告は安全性情報として意味があるが、この患者に繰り返さないための手立てにはならない。"}'),
    ('119-E-43', '正答は C「③」。

設問は左心不全に特徴的な徴候を選ぶもの。左心の拍出が落ちると肺静脈圧が上がり、肺胞に水が染み出す。両肺野で聴かれるcoarse cracklesがその所見である。

出典：厚生労働省ホームページ 第119回医師国家試験 E043',
     '{"A": "食欲低下は非特異的で、左右どちらの心不全にも特徴的とはいえない。", "B": "頸静脈の怒張は右心系のうっ滞を示す。", "D": "肝腫大も体循環のうっ滞、すなわち右心不全の徴候である。", "E": "下肢の圧痕性浮腫も右心不全の徴候である。"}'),
    ('119-E-44', '正答は E「悪性リンパ腫」。

駆出率が大きく低下しており、薬剤性の心筋障害を疑う。既往のうち治療で心毒性のある薬を使うのは悪性リンパ腫で、アントラサイクリン系薬は総投与量に依存して心筋障害をきたす。

出典：厚生労働省ホームページ 第119回医師国家試験 E044',
     '{"A": "気管支喘息の治療薬に、心筋を傷める代表的なものはない。", "B": "虫垂炎の手術は心筋障害と関わらない。", "C": "胆石症も同様である。", "D": "脊椎圧迫骨折の治療も心筋障害とは結びつかない。"}'),
    ('119-E-45', '正答は E「「周りに同じ症状の人はいますか」」。

「うつる病気かどうか」という心配に応えるには、周囲に同じ症状の人がいるかを尋ねるのが最も直接的である。同じものを食べた人や身近な人に同様の症状があれば、感染性腸炎を裏づけ、家庭内での対策にもつながる。

出典：厚生労働省ホームページ 第119回医師国家試験 E045',
     '{"A": "睡眠の状況からは、感染性かどうかを判断できない。", "B": "便秘の有無はこの心配に答える材料にならない。", "C": "腹部膨満の有無も感染性の判断には結びつかない。", "D": "手足のしびれは、この場面での鑑別に寄与しない。"}'),
    ('119-E-46', '正答は E「反跳痛」。

心窩部から始まった痛みが右下腹部へ移動している。急性虫垂炎の典型的な経過で、炎症が腹膜へ及ぶと、圧迫した手を急に離したときに強い痛みが走る反跳痛が現れる。

出典：厚生労働省ホームページ 第119回医師国家試験 E046',
     '{"A": "黄疸は胆道系の疾患でみられ、虫垂炎の所見ではない。", "B": "下血は虫垂炎では通常みられない。", "C": "波動は腹水があるときの所見である。", "D": "金属音は腸閉塞でみられる腸雑音である。"}'),
    ('119-F-1', '正答は A「疾病の国際的伝播を最大限防止する。」。

世界保健機関憲章は「すべての人々が可能な最高の健康水準に到達すること」を目的に掲げ、国際保健事業の指導と調整、感染症の国際的伝播の防止、保健分野の基準の設定などを担う。

出典：厚生労働省ホームページ 第119回医師国家試験 F001',
     '{"B": "移住の推進は国際移住機関の役割である。", "C": "開発途上国の経済・社会の発展は国連開発計画などが担う。", "D": "子どもの権利の保障は国連児童基金の役割である。", "E": "食糧の供給は国連食糧農業機関や世界食糧計画が担う。"}'),
    ('119-F-2', '正答は A「鼠径靱帯は坐骨結節に付着する。」。

鼠径靱帯は上前腸骨棘と恥骨結節の間に張る。坐骨結節ではない。大腿静脈の穿刺では、鼠径靱帯を基準に大腿神経・動脈・静脈が外側から内側へ並ぶ位置関係を確かめる。

出典：厚生労働省ホームページ 第119回医師国家試験 F002',
     '{"B": "鼠径靱帯より頭側は後腹膜腔で、この高さより上を穿刺すると後腹膜血腫を招く。正しい。", "C": "大腿三角は鼠径靱帯、縫工筋、長内転筋で囲まれる。正しい。", "D": "大腿静脈は大腿動脈の内側を走る。正しい。", "E": "大腿神経は大腿動脈の外側を走る。正しい。"}'),
    ('119-F-3', '正答は D「生理的体重減少は10%以下である。」。

生後数日は水分と胎便の喪失により体重が減るが、正常なら出生体重の10%以内にとどまり、生後7〜10日で出生体重に戻る。10%を超えれば哺乳不足や脱水を疑う。

出典：厚生労働省ホームページ 第119回医師国家試験 F003',
     '{"A": "新生児は4頭身である。7頭身になるのは成人である。", "B": "肋間筋が未熟なため腹式呼吸が主体である。", "C": "大泉門が閉鎖するのは1歳半ごろである。生後1か月ではまだ開いている。", "E": "生理的黄疸のピークは生後4〜5日である。"}'),
    ('119-F-4', '正答は A「ドパミン受容体」。

抗精神病薬は中脳辺縁系のドパミンD2受容体を遮断して幻覚・妄想を抑える。同時に黒質線条体系を遮断するため錐体外路症状を、下垂体系を遮断するため高プロラクチン血症をきたす。

出典：厚生労働省ホームページ 第119回医師国家試験 F004',
     '{"B": "非定型抗精神病薬はセロトニン受容体にも作用するが、抗精神病作用の中核はドパミン受容体の遮断である。", "C": "モノアミンオキシダーゼの阻害は一部の抗うつ薬やParkinson病治療薬の作用機序である。", "D": "アセチルコリンエステラーゼの阻害はAlzheimer型認知症治療薬の作用機序である。", "E": "ノルアドレナリントランスポーターの阻害は抗うつ薬やアトモキセチンの作用機序である。"}'),
    ('119-F-5', '正答は E「遺伝子の違いにより環境の健康への影響が異なる。」。

遺伝子-環境交互作用とは、同じ環境曝露を受けても遺伝子型によって健康影響の大きさが変わることをいう。アルデヒド脱水素酵素の遺伝子型により飲酒の害が異なるのが代表例である。

出典：厚生労働省ホームページ 第119回医師国家試験 F005',
     '{"A": "交互に現れるという意味ではない。同時に作用して効果が変わることをいう。", "B": "環境要因による遺伝子変異は変異原性の問題で、交互作用とは別である。", "C": "遺伝子組み換え生物の環境影響はまったく別の話題である。", "D": "それぞれ単独で原因となる疾患があることは、交互作用の説明にならない。"}'),
    ('119-F-6', '正答は E「性腺」。

副腎皮質と性腺はいずれもコレステロールからステロイドホルモンを合成し、コレステロール側鎖切断酵素や3β-水酸化ステロイド脱水素酵素、17α-水酸化酵素などを共有する。先天性副腎過形成症で性ホルモンの異常を伴うのはこのためである。

出典：厚生労働省ホームページ 第119回医師国家試験 F006',
     '{"A": "視床下部が分泌するのはペプチドホルモンで、合成経路が異なる。", "B": "下垂体もペプチド・糖蛋白ホルモンを分泌する。", "C": "副甲状腺ホルモンもペプチドホルモンである。", "D": "副腎髄質はチロシンからカテコールアミンを合成し、ステロイド合成酵素は共有しない。"}'),
    ('119-F-7', '正答は A「アデレード宣言 — あらゆる政策において健康を考慮する。」。

アデレードでの会議は健康的な公共政策づくりを主題とし、あらゆる政策分野で健康への影響を考慮するという Health in All Policies の考え方を打ち出した。

出典：厚生労働省ホームページ 第119回医師国家試験 F007',
     '{"B": "アルマ・アタ宣言はプライマリヘルスケアと「すべての人に健康を」を掲げた宣言である。", "C": "ジュネーブ宣言は医師の職業倫理の誓いで、患者の秘密の尊重を含む。", "D": "ヘルシンキ宣言は人を対象とする医学研究の倫理原則で、倫理審査委員会の設置を求めている。", "E": "リスボン宣言は患者の権利に関する宣言で、セカンドオピニオンを求める権利を認めている。"}'),
    ('119-F-8', '正答は A「雇入時」。

労働安全衛生法は、雇入れ時の健康診断と1年以内ごとの定期健康診断を事業者に義務づけている。有害業務に従事する労働者には特殊健康診断も課される。

出典：厚生労働省ホームページ 第119回医師国家試験 F008',
     '{"B": "退職時の健康診断は義務づけられていない。", "C": "労働災害の発生時に健康診断を行う定めはない。", "D": "長時間労働者には医師による面接指導が義務づけられており、健康診断ではない。", "E": "復職時の健康診断も法定ではなく、事業場ごとの取決めによる。"}'),
    ('119-F-9', '正答は B「χ2検定」。

2群で「症状が消失したかどうか」という2値の割合を比べているので、χ2検定(またはFisherの正確検定)を用いる。

出典：厚生労働省ホームページ 第119回医師国家試験 F009',
     '{"A": "t検定は連続変数の平均を比べるときに用いる。", "C": "生存分析は事象が起こるまでの時間を扱う。3日目という一時点の割合の比較には用いない。", "D": "線形回帰は連続変数を目的変数とする。", "E": "比例ハザードモデルは生存時間に対する複数因子の影響をみる手法である。"}'),
    ('119-F-10', '正答は B「教育」。

国民生活基礎調査は世帯、健康(保健)、介護、所得、貯蓄について調べる。福祉や医療の利用状況も含まれるが、教育に関する事項は調査項目にない。

出典：厚生労働省ホームページ 第119回医師国家試験 F010',
     '{"A": "通院や入院の状況など医療に関わる事項は含まれる。", "C": "所得票により所得と貯蓄を調べる。", "D": "介護票により要介護者の状況を調べる。", "E": "健康票により有訴者率や通院者率を調べる。"}'),
    ('119-F-11', '正答は E「小さい病変(最大径3cm以下)」。

定位放射線照射は病変に線量を集中させる治療で、原発巣が制御されていて、最大径3cm以下の限られた個数の転移巣が対象となる。周囲の正常脳への照射を抑えられる。

出典：厚生労働省ホームページ 第119回医師国家試験 F011',
     '{"A": "髄膜播種は広範に散らばるため、局所への集中照射では制御できない。", "B": "脳ヘルニアを伴う病変は緊急に減圧が必要で、開頭手術を優先する。", "C": "病変が多数の場合は全脳照射や薬物療法を考える。", "D": "薬物療法に高感受性の腫瘍(胚細胞腫瘍や小細胞肺癌など)ではまず薬物療法を行う。"}'),
    ('119-F-12', '正答は D「弾性着衣による圧迫」。

リンパ浮腫の治療の柱は複合的理学療法で、用手的リンパドレナージ、弾性着衣や包帯による圧迫、圧迫下の運動、スキンケアからなる。なかでも圧迫療法が中心となる。

出典：厚生労働省ホームページ 第119回医師国家試験 F012',
     '{"A": "温めると血管が拡張して組織液の産生が増え、浮腫が悪化する。", "B": "固定は筋のポンプ作用を失わせ、浮腫を悪化させる。", "C": "促通訓練は片麻痺に対する神経筋の再教育法で、リンパ浮腫の治療ではない。", "E": "電気療法はリンパ浮腫の標準治療に含まれない。"}'),
    ('119-F-13', '正答は C「メチル水銀」。

メチル水銀は食物連鎖を通じて魚介類に濃縮され、これを食べることが主な曝露経路になる。水俣病の原因であり、妊婦に対して大型魚の摂取に関する注意も出されている。

出典：厚生労働省ホームページ 第119回医師国家試験 F013',
     '{"A": "鉛の曝露源は塗料や水道管、粉じんなどである。", "B": "カドミウムの主な曝露源は米などの農作物で、イタイイタイ病の原因となった。", "D": "塩化ビニルモノマーは職業曝露で問題となり、肝血管肉腫を起こす。", "E": "テトラクロロエチレンはドライクリーニングなどの職業曝露と地下水汚染が問題となる。"}'),
    ('119-F-14', '正答は C「チロシナーゼはメラニン生成に必須である。」。

チロシナーゼはチロシンからドーパを経てメラニンを合成する律速酵素で、この酵素が欠損すると眼皮膚白皮症をきたす。

出典：厚生労働省ホームページ 第119回医師国家試験 F014',
     '{"A": "Merkel細胞は触覚を受容する細胞である。免疫を担うのはLangerhans細胞である。", "B": "皮脂の主成分はトリグリセリド、ワックスエステル、スクアレンである。", "D": "アポクリン汗腺は毛包に開口する。表皮に直接開口するのはエクリン汗腺である。", "E": "ヘミデスモソームは基底細胞と基底膜の接着に関わる。細胞間の接着はデスモソームが担う。"}'),
    ('119-F-15', '正答は D「後期高齢者医療制度」。

後期高齢者医療制度は、75歳以上および65歳以上で一定の障害がある人を対象とする公的医療保険である。運営主体は都道府県ごとの後期高齢者医療広域連合である。

出典：厚生労働省ホームページ 第119回医師国家試験 F015',
     '{"A": "医療扶助は生活保護の給付で、保険ではない。", "B": "介護保険は介護サービスを給付する社会保険で、医療保険ではない。", "C": "国民年金は年金保険である。", "E": "労働者災害補償保険は業務災害・通勤災害を対象とする労働保険である。"}'),
    ('119-F-16', '正答は B「ヘルパーT細胞」。

ヘルパーT細胞はB細胞が提示した抗原を認識し、CD40リガンドとサイトカインを介してB細胞を活性化する。これによりクラススイッチと親和性成熟、記憶B細胞の形成が進む。

出典：厚生労働省ホームページ 第119回医師国家試験 F016',
     '{"A": "NK細胞は自然免疫で感染細胞や腫瘍細胞を傷害する。", "C": "マクロファージは貪食と抗原提示を行うが、B細胞の活性化を直接担うのはヘルパーT細胞である。", "D": "制御性T細胞は免疫応答を抑える方向に働く。", "E": "細胞傷害性T細胞は感染細胞を直接傷害する。"}'),
    ('119-F-17', '正答は B「循環器系の疾患」。

国民医療費のうち医科診療医療費を傷病分類別にみると、循環器系の疾患が最も大きい。高血圧性疾患、脳血管疾患、虚血性心疾患を含み、患者数が多く長期にわたって治療を要するためである。

出典：厚生労働省ホームページ 第119回医師国家試験 F017',
     '{"A": "呼吸器系の疾患は循環器系には及ばない。", "C": "精神及び行動の障害は入院医療費の比重が大きいが、全体では循環器系に次ぐ規模である。", "D": "内分泌、栄養及び代謝疾患も糖尿病を含むが循環器系ほどではない。", "E": "筋骨格系及び結合組織の疾患も上位だが最大ではない。"}'),
    ('119-F-18', '正答は C「身体障害者手帳の交付」。

身体障害者手帳の交付は都道府県知事、指定都市市長、中核市市長が行い、申請の窓口は市町村である。保健所の業務ではない。

出典：厚生労働省ホームページ 第119回医師国家試験 F018',
     '{"A": "精神保健に関する相談と訪問指導は保健所の業務である。", "B": "医療機関への立入検査(医療監視)は保健所が行う。", "D": "人口動態統計に関する事務は保健所を経由して行われる。", "E": "結核患者が発生したときの接触者健康診断は保健所が実施する。"}'),
    ('119-F-20', '正答は B「無為 — 意欲」。

無為は自発的な行動が起こらない状態で、意欲(発動性)の障害にあたる。統合失調症の陰性症状としてみられる。

出典：厚生労働省ホームページ 第119回医師国家試験 F020',
     '{"A": "恐怖は感情の障害である。", "C": "離人症は自分や周囲を現実味なく感じる体験で、自我意識の障害である。", "D": "両価性は相反する感情が同時に存在する状態で、感情の障害に分類される。", "E": "学習障害は特定の学習能力の障害で、全般的な知能の障害ではない。"}'),
    ('119-F-21', '正答は E「生産年齢人口」。

従属人口指数は(年少人口＋老年人口)÷生産年齢人口×100で表し、働き手が支える扶養負担の大きさを示す。分母は生産年齢人口(15〜64歳)である。

出典：厚生労働省ホームページ 第119回医師国家試験 F021',
     '{"A": "総人口を分母にするのは年少人口割合や老年人口割合である。", "B": "年少人口は分子の一部である。", "C": "成人人口という区分は人口統計で用いない。", "D": "老年人口も分子の一部である。"}'),
    ('119-F-22', '正答は B「6%」。

晩婚化と晩産化により40歳以上の出産が増え、近年は年間出生数の6%前後を占める。母体年齢の上昇は妊娠高血圧症候群や染色体異常の頻度上昇と結びつく。

出典：厚生労働省ホームページ 第119回医師国家試験 F022',
     '{"A": "1%は1990年代以前の水準である。", "C": "16%は実際よりかなり高い。", "D": "26%はさらに過大である。", "E": "36%は現実離れした値である。"}'),
    ('119-F-23', '正答は E「開放隅角緑内障」。

開放隅角緑内障では網膜神経線維が障害され、鼻側階段や弓状暗点から始まり、進行すると求心性視野狭窄に至る。中心視力は末期まで保たれるため自覚が遅れる。

出典：厚生労働省ホームページ 第119回医師国家試験 F023',
     '{"A": "うっ血乳頭ではMariotte盲点の拡大をきたす。", "B": "頭蓋咽頭腫は視交叉を圧迫して両耳側半盲をきたす。", "C": "加齢黄斑変性は中心暗点と変視症をきたす。", "D": "球後視神経炎は中心暗点をきたす。"}'),
    ('119-F-24', '正答は E「処遇改善請求の制限」。

退院請求や処遇改善請求は患者に保障された権利で、これを制限することはできない。弁護士や人権擁護機関との電話・面会も制限してはならない。

出典：厚生労働省ホームページ 第119回医師国家試験 F024',
     '{"A": "隔離は12時間を超える場合に精神保健指定医の判断で行える。", "B": "身体拘束も精神保健指定医の判断で行える。", "C": "医療保護入院や措置入院では退院を制限できる。", "D": "治療上必要な場合に限り、面会の制限が認められることがある。"}'),
    ('119-F-26', '正答は A「肝臓でのブドウ糖放出」。

早朝空腹時は食事からの糖の供給がないため、肝がグリコーゲン分解と糖新生によりブドウ糖を血中へ放出して血糖を保つ。インスリンとグルカゴンのバランスがこれを調節する。

出典：厚生労働省ホームページ 第119回医師国家試験 F026',
     '{"B": "腎の再吸収は濾過された糖を回収するだけで、血糖を新たに供給する機構ではない。", "C": "脳のブドウ糖取り込みは血糖を消費する側である。", "D": "骨格筋の取り込みも血糖を下げる方向に働く。", "E": "糖質コルチコイドは糖新生を促す方向に働くが、早朝空腹時の血糖維持の主役は肝からの放出である。"}'),
    ('119-F-27', '正答は A「高齢者虐待の防止」。

地域包括支援センターの4つの業務は、総合相談支援、権利擁護、包括的・継続的ケアマネジメント支援、介護予防ケアマネジメントである。高齢者虐待の防止と対応は権利擁護業務にあたる。

出典：厚生労働省ホームページ 第119回医師国家試験 F027',
     '{"B": "発達障害児の相談は発達障害者支援センターや児童相談所が担う。", "C": "がん検診は市町村の健康増進事業として行われる。", "D": "へき地医療対策の企画は都道府県が担う。", "E": "通所リハビリテーションの提供は介護サービス事業所が行う。センターは調整役である。"}'),
    ('119-F-37', '正答は B「子宮頸管長測定」。

妊娠12週未満の流産を3回以上繰り返す反復流産・習慣流産では、抗リン脂質抗体、甲状腺機能、子宮形態、夫婦の染色体を調べる。子宮頸管長の測定は妊娠中に早産の危険を評価するもので、次回妊娠に向けた原因検索には含まれない。

出典：厚生労働省ホームページ 第119回医師国家試験 F037',
     '{"A": "甲状腺機能異常は流産の危険因子で、検索の対象となる。", "C": "子宮卵管造影で子宮形態異常(中隔子宮など)を調べる。", "D": "抗リン脂質抗体症候群は治療可能な原因として重要である。", "E": "夫婦いずれかの均衡型転座が原因となることがあり、染色体検査を行う。"}'),
    ('119-F-39', '正答は C「3」。

健康の社会的決定要因は、労働環境、social support、経済状況、教育など健康を左右する社会的な条件を指す。職場の人間関係の悪化は労働環境とストレスに関わる社会的決定要因にあたる。

出典：厚生労働省ホームページ 第119回医師国家試験 F039',
     '{"A": "意識障害は結果として生じた症状である。", "B": "糖尿病という疾患そのものは健康状態であって決定要因ではない。", "D": "不規則な食事と飲酒は生活習慣(行動要因)で、社会的決定要因が背景にある行動である。", "E": "呼吸数は身体所見である。"}'),
    ('119-F-40', '正答は A「経過観察」。

HBワクチンを接種してHBs抗体が十分に獲得できていた者は免疫があると考えられ、HBs抗原陽性患者からの針刺しでも追加の処置を要さない。経過観察でよい。

出典：厚生労働省ホームページ 第119回医師国家試験 F040',
     '{"B": "すでに抗体を獲得しており、追加接種の必要はない。", "C": "核酸アナログ製剤は感染が成立した場合の治療薬で、曝露後予防には用いない。", "D": "抗HBsヒト免疫グロブリンは抗体を獲得していない者への曝露後予防に用いる。", "E": "両者の併用も抗体陰性者に対する対応である。"}'),
    ('119-F-42', '正答は C「脂質の摂取は総摂取エネルギー量の20〜30%とする。」。

食事摂取基準では、脂質は総エネルギーの20〜30%、蛋白質は13〜20%、炭水化物は50〜65%を目安とする。減量時もこの配分を保ちながら総エネルギー量を減らす。

出典：厚生労働省ホームページ 第119回医師国家試験 F042',
     '{"A": "高血圧もあり、食塩は6g/日未満を目標とする。15gは過剰である。", "B": "標準体重約64kgに25〜30kcalを掛けると1,600〜1,900kcal程度で、4,500kcalは論外である。", "D": "蛋白質を5〜10%に抑えると必要量に足りず、筋肉量の減少を招く。", "E": "炭水化物30〜40%は基準を下回る。"}'),
    ('119-F-43', '正答は A「筋肉内出血」。

APTT72.4秒と単独で延長し、フィブリノゲンは高値、血小板も正常である。前立腺癌に伴って生じた後天性血友病A(第VIII因子インヒビター)が疑われ、広範な筋肉内出血をきたしている。

出典：厚生労働省ホームページ 第119回医師国家試験 F043',
     '{"B": "坐骨神経痛では紫斑や腫脹、凝固検査の異常は生じない。", "C": "腸腰筋膿瘍なら発熱とCRPの著明な上昇を伴う。体温36.2°C、CRP0.8mg/dLで合わない。", "D": "大腿骨頭壊死症は股関節痛を主症状とし、紫斑や凝固異常は伴わない。", "E": "変形性股関節症も慢性の経過をたどり、急な腫脹や紫斑はきたさない。"}'),
    ('119-F-44', '正答は E「本人に自身の病気をどれくらい理解しているか確認する。」。

小児期発症の慢性疾患を成人診療科へ移行するには、本人が自分の病気と治療を理解し、自分で管理できるようになる過程(移行支援)が要る。まず本人の理解度を確かめることが出発点になる。

出典：厚生労働省ホームページ 第119回医師国家試験 F044',
     '{"A": "過去の怠薬を責めても信頼関係を損なうだけである。", "B": "理解度を確かめないまま自己管理に切り替えれば、再び怠薬を招く。", "C": "母親に任せ続けては自立が進まず、移行が果たせない。", "D": "本人が受診せずに処方するのは無診察治療にあたり、医師法に反する。"}'),
    ('119-F-45', '正答は D「「1時間後に再度診察します」」。

発熱に伴う左右差のない2分間の全身けいれんで、意識も回復し髄膜刺激徴候もない単純型熱性けいれんである。再発や意識の回復を確かめるため1時間ほど院内で経過をみて、問題なければ帰宅させる。

出典：厚生労働省ホームページ 第119回医師国家試験 F045',
     '{"A": "脱水を示す所見はなく、輸液を要さない。", "B": "上気道炎が背景で、抗菌薬の適応はない。", "C": "ビタミンKは新生児のビタミンK欠乏性出血症に用いる。", "E": "すでに止まっており、単純型では抗けいれん薬の予防投与も要さない。"}'),
    ('119-F-46', '正答は A「創感染の予防」。

高血糖は好中球の遊走能と貪食能を落とし、創部の血流も損なうため、手術部位感染や縫合不全の危険が高まる。周術期の血糖管理はこれを防ぐことを主な目的とする。

出典：厚生労働省ホームページ 第119回医師国家試験 F046',
     '{"B": "周術期の短期間の血糖管理で脳血管障害を防げるわけではない。", "C": "心血管イベントの予防は長期的な管理の目標である。", "D": "深部静脈血栓症の予防は抗凝固と物理的予防で行う。", "E": "神経障害の予防も長期の血糖管理の目標である。"}'),
    ('119-F-47', '正答は C「第2回旋の異常」。

小泉門が3時方向から6時方向へ回旋しており、後頭部が母体の背側を向く後方後頭位になっている。児頭が骨盤の形に合わせて回る第2回旋の異常で、分娩の遷延を招く。

出典：厚生労働省ホームページ 第119回医師国家試験 F047',
     '{"A": "小泉門が6時方向、すなわち母体の背側にあり、正常の回旋ではない。", "B": "第1回旋は児頭が屈位をとる動きで、小泉門が先進していることから正常である。", "D": "第3回旋は児頭が娩出時に伸展する動きで、まだその段階に至っていない。", "E": "第4回旋は児頭娩出後に肩の向きに合わせて外回旋する動きで、これも先の段階である。"}'),
    ('119-F-48', '正答は E「「今から会社の人が付き添って、精神科を受診させてください」」。

具体的な手段(練炭の購入)まで準備した明確な自殺念慮があり、切迫した状態である。一人にせず、その場から誰かが付き添って精神科を受診させる。

出典：厚生労働省ホームページ 第119回医師国家試験 F048',
     '{"A": "配置転換は中長期の対策で、今日の生命の危険には対応できない。", "B": "労災申請も緊急の対応にならない。", "C": "一人で早退させることが最も危険である。", "D": "食事の配慮は問題の本質からかけ離れている。"}'),
    ('119-F-49', '正答は D「「腹膜透析を行ってからでも腎移植はできます」」。

腹膜透析は残存腎機能を保ちやすく、その後に生体腎移植を行うこともできる。透析の方法によって移植の適応が左右されることはない。

出典：厚生労働省ホームページ 第119回医師国家試験 F049',
     '{"A": "週3回の通院を要するのは血液透析である。腹膜透析の通院は月1〜2回程度である。", "B": "糖尿病があっても腹膜透析は行える。", "C": "腹膜透析でも塩分と水分の管理は必要である。", "E": "大腸ポリープの内視鏡的切除術は腹膜の癒着を伴わず、適応の妨げにならない。"}'),
    ('119-F-51', '正答は C「「今は食事を楽しむことが大事ですからゆっくり進めていきましょう」」。

1歳6か月ごろの偏食はよくみられ、成長も順調であれば無理強いせず、食事の場を楽しいものにしながらゆっくり進めるのが基本である。身長81cm、体重10.5kgは標準的である。

出典：厚生労働省ホームページ 第119回医師国家試験 F051',
     '{"A": "生卵はサルモネラ感染の危険があり、乳幼児には勧めない。", "B": "濃い味付けは食塩の過剰摂取につながる。薄味を基本とする。", "D": "ミニトマトやブドウは丸のまま与えると窒息の危険があり、切って与える。", "E": "無理に口へ押し込むと食事が苦痛になり、偏食を強める。"}'),
    ('119-F-52', '正答は A「現時点」。

骨密度がYAM70%を超えていても、椎体骨折という脆弱性骨折の既往があれば骨粗鬆症と診断され、直ちに薬物治療を始める。骨折の連鎖を断つことが目的である。

出典：厚生労働省ホームページ 第119回医師国家試験 F052',
     '{"B": "腰痛の有無は治療開始の基準にならない。", "C": "次の骨折を待つのでは治療の意味がない。", "D": "神経障害の出現を待つのはさらに遅い。", "E": "脆弱性骨折がある場合は骨密度の値にかかわらず治療を開始する。"}'),
    ('119-F-53', '正答は A「降圧薬の処方」。

トータルヘルスプロモーションプランは労働者の心と体の健康づくりを進める取組みで、運動指導、保健指導、栄養指導、心理相談、健康教育からなる。診断や治療は含まれず、降圧薬の処方は医療機関で行う。

出典：厚生労働省ホームページ 第119回医師国家試験 F053',
     '{"B": "運動指導担当者による運動計画の立案は中核の活動である。", "C": "産業栄養指導担当者による食生活の指導も含まれる。", "D": "健康教育としての講演会も含まれる。", "E": "心理相談担当者によるメンタルヘルスケアも含まれる。"}'),
    ('119-F-55', '正答は D「4」。

受傷の前後の記憶がない(健忘)ことは、頭蓋内損傷の危険を示す所見で、頭部CTの適応となる。意識消失、繰り返す嘔吐、頭蓋底骨折を疑う所見、けいれん、抗凝固薬の内服なども同様である。

出典：厚生労働省ホームページ 第119回医師国家試験 F055',
     '{"A": "軽度の頭痛のみでは画像検査の適応にならない。", "B": "後頸部痛は頸椎の評価を要するが、頭部CTの適応を決める所見ではない。", "C": "体温37.3°Cは頭部外傷の重症度と関係しない。", "E": "打撲部位の圧痛だけでは頭蓋内損傷を示唆しない。"}'),
    ('119-F-62', '正答は C「甲状腺ホルモン薬内服」。

TSHが著明に高くFT4が測定下限近くまで下がっており、高度の甲状腺機能低下症である。低体温、徐脈、動作緩慢、便秘、コレステロールの上昇はいずれもこれで説明できる。甲状腺ホルモン薬の補充が根本的な治療になる。

出典：厚生労働省ホームページ 第119回医師国家試験 F062',
     '{"A": "血圧が低く脱水に傾いており、利尿薬はさらに循環を悪くする。", "B": "ヨウ素を多く摂ると甲状腺ホルモンの合成がかえって抑えられることがあり、治療にならない。", "D": "コレステロールの上昇は甲状腺機能低下の結果で、ホルモンを補えば戻る。まず原因を治す。", "E": "カリウムの補正は要るが、急速静注は致死性不整脈を招く。希釈してゆっくり入れる。"}'),
    ('119-F-63', '正答は A「輸液」。

黒色物の嘔吐は上部消化管出血で、NSAIDの内服が誘因と考えられる。頻脈があり循環血液量が減りはじめている。まず太い静脈路を確保して細胞外液を入れ、血圧と臓器血流を保ちながら内視鏡へ進む。

出典：厚生労働省ホームページ 第119回医師国家試験 F063',
     '{"B": "貧血は軽度で、この時点で直ちに輸血する水準ではない。出血が続けば考える。", "C": "感染を示す所見がなく、抗菌薬の適応がない。", "D": "アトロピンは徐脈への薬で、本例は頻脈である。", "E": "血圧は保たれており、まず輸液で血管内容量を戻すのが順序である。"}'),
    ('119-F-64', '正答は E「局所麻酔薬に対するアレルギー歴」。

上部消化管内視鏡では咽頭に局所麻酔薬を用いる。アレルギーがあればショックを起こしうるので、検査前に必ず確かめる。安全に直結する情報である。

出典：厚生労働省ホームページ 第119回医師国家試験 F064',
     '{"A": "閉経後であり、妊娠出産歴はこの検査の安全に関わらない。", "B": "排便回数は上部消化管内視鏡の前処置とは関係しない。", "C": "香辛料の嗜好は検査の可否を左右しない。", "D": "除菌歴は所見の解釈に役立つが、検査前に優先して確かめる安全上の情報ではない。"}'),
    ('119-F-68', '正答は C「「家族の方は抗菌薬の予防内服が必要です」」。

設問は説明として「誤っている」ものを選ぶもの。梅毒は主に性的接触で伝播し、日常生活を共にする家族へうつるものではない。同居家族に予防的な抗菌薬の内服を勧める根拠はない。

出典：厚生労働省ホームページ 第119回医師国家試験 F068',
     '{"A": "認知機能の低下があり神経梅毒を疑う。脳脊髄液検査を行うのは正しい。", "B": "梅毒の治療はペニシリン系抗菌薬が第一選択で、正しい。", "D": "治療後もRPRの推移を追って治癒を判定するため、定期的な血液検査は正しい。", "E": "トイレの共用で感染することはなく、正しい説明である。"}'),
    ('119-F-69', '正答は D「ニトログリセリンの舌下」。

設問は「誤っている」処置を選ぶもの。下壁誘導に加えて右側胸部誘導でもSTが上昇し、右室の壁運動も低下している。右室梗塞では心拍出が前負荷に依存するため、血管を広げる硝酸薬は血圧をさらに下げて危険である。しかもPDE5阻害薬を服用しており、併用は禁忌である。

出典：厚生労働省ホームページ 第119回医師国家試験 F069',
     '{"A": "急性冠症候群に対する抗凝固としてヘパリンの静注は正しい。", "B": "アスピリンの経口投与は初期治療の基本である。", "C": "輸液に反応しない低心拍出には、ドブタミンによる強心が理にかなう。", "E": "右室梗塞では前負荷を保つことが要で、生理食塩液の負荷は正しい。"}'),
    ('119-F-71', '正答は E「ECMO〈Extracorporeal membrane oxygenation〉」。

平均血圧を保てず頻脈と不穏が続いており、心原性ショックが進行している。自己の心拍出だけでは全身の灌流を維持できないため、体外循環で血流と酸素化をまるごと肩代わりするECMOを導入し、その間に冠動脈の再灌流を図る。

出典：厚生労働省ホームページ 第119回医師国家試験 F071',
     '{"A": "植込み型除細動器は致死性不整脈の再発を防ぐ慢性期のデバイスで、この場の循環は支えられない。", "B": "洞調律に復帰しており、ペースメーカの適応となる徐脈ではない。", "C": "補助人工心臓は開胸して植え込むもので、この急場には間に合わない。", "D": "大動脈内バルーンパンピングは補助の程度が小さく、自己心拍出がある程度残っていることが前提になる。ここまでの循環破綻には足りない。"}')
) AS v(blueprint_code, explanation, choice_explanations)
WHERE q.exam_type = 'KOKUSHI' AND q.blueprint_code = v.blueprint_code;

-- quiz.0010_backfill_choice_explanations を記録する。中身は上の UPDATE で
-- 済ませてあるので、あとから manage.py migrate を通しても二重には当たらない。
INSERT INTO django_migrations (app, name, applied)
SELECT 'quiz', '0010_backfill_choice_explanations', NOW()
WHERE NOT EXISTS (
    SELECT 1 FROM django_migrations
    WHERE app = 'quiz' AND name = '0010_backfill_choice_explanations'
);

-- 確認: 公開中の国試で、まだ本文に畳み込まれたまま（列が空）の数。0であること。
SELECT count(*) AS folded_not_split
FROM quiz_question
WHERE exam_type = 'KOKUSHI' AND status = 'published'
  AND explanation LIKE '%【誤答選択肢の解説】%'
  AND choice_explanations = '{}'::jsonb;

COMMIT;
